/**
 * Application Settings Service
 * 
 * Centralized settings management that provides:
 * - Singleton access to application settings
 * - localStorage persistence
 * - Type-safe setting access and updates
 * - Event-driven change notifications
 * 
 * This service is separate from UI concerns - UI components use this service
 * but core application logic can access settings directly without going through UI layers.
 */

import { EventManager, EventSource, type BaseInteractionEvent } from './EventManager'
import { AppSettingsEventTypes } from '../types/InteractionEvents'

// Lighting Quality Constants
export const LIGHTING_QUALITY = {
    SIMPLE: 'simple',
    ENHANCED: 'enhanced', 
    ADVANCED: 'advanced',
    OUCH_MY_EYES: 'ouch-my-eyes'
} as const

export type LightingQuality = typeof LIGHTING_QUALITY[keyof typeof LIGHTING_QUALITY]

/** Setting keys as const for type-safe, refactorable access */
export const Setting = {
    // Performance
    QualityLevel: 'qualityLevel',
    // Graphics
    LightingQuality: 'lightingQuality',
    ShadowQuality: 'shadowQuality',
    CeilingHeight: 'ceilingHeight',
    EnableLighting: 'enableLighting',
    ShowLightingDebug: 'showLightingDebug',
    ShowCeiling: 'showCeiling',
    // Feature Flags
    EnableLabels: 'enableLabels',
    EnableStickers: 'enableStickers',
    EnableArtwork: 'enableArtwork',
    UseMultiAtlas: 'useMultiAtlas',
    UseLodAtlas: 'useLodAtlas',
    // LOD Settings
    LodHighDistance: 'lodHighDistance',
    LodMedDistance: 'lodMedDistance',
    LodMaxHighSlots: 'lodMaxHighSlots',
    LodHighReductionRatio: 'lodHighReductionRatio',
    LodMedReductionRatio: 'lodMedReductionRatio',
    // Interface
    ShowFPS: 'showFPS',
    ShowPerformanceStats: 'showPerformanceStats',
    HideUIInVR: 'hideUIInVR',
    // Debug
    VerboseLogging: 'verboseLogging',
    ShowDebugInfo: 'showDebugInfo',
    ShowCompassRose: 'showCompassRose',
    EnableBlockingTracker: 'enableBlockingTracker',
    // General
    AutoSave: 'autoSave',
    // Steam
    AutoLoadProfile: 'autoLoadProfile',
    DevelopmentMode: 'developmentMode',
} as const

/** Settings grouped by UI panel/category for bulk operations */
export const SettingCategory = {
    Graphics: [
        Setting.LightingQuality,
        Setting.ShadowQuality,
        Setting.CeilingHeight,
        Setting.EnableLighting,
        Setting.ShowLightingDebug,
        Setting.ShowCeiling,
        Setting.LodHighDistance,
        Setting.LodMedDistance,
        Setting.LodMaxHighSlots,
        Setting.LodHighReductionRatio,
        Setting.LodMedReductionRatio,
    ] as const,
    // Add other categories as needed (Interface, Debug, Steam, etc.)
} as const

export interface ApplicationSettings {
    // Performance Settings
    qualityLevel: 'low' | 'medium' | 'high' | 'ultra'

    // Graphics Settings
    lightingQuality: LightingQuality
    shadowQuality: number // 0=off, 1=low, 2=medium, 3=high, 4=ultra
    ceilingHeight: number
    enableLighting: boolean
    showLightingDebug: boolean
    showCeiling: boolean

    // Feature Flags (GPU/Performance tuning)
    enableLabels: boolean      // Game box text labels (GPU intensive)
    enableStickers: boolean    // Shelf stickers/decals (GPU intensive)
    enableArtwork: boolean     // Game box artwork textures
    useMultiAtlas: boolean     // Use 3-tier texture atlas system (reduces VRAM)
    useLodAtlas: boolean       // Use LOD texture atlas with per-instance detail levels

    // LOD Settings
    lodHighDistance: number      // Distance threshold for HIGH texture quality (meters)
    lodMedDistance: number       // Distance threshold for MED texture quality (meters)
    lodMaxHighSlots: number      // Max HIGH texture slots (affects VRAM)
    lodHighReductionRatio: number // HIGH texture reduction (0.5 = 50% of source)
    lodMedReductionRatio: number  // MED texture reduction (0.25 = 25% of source)

    // Interface Settings
    showFPS: boolean
    showPerformanceStats: boolean
    hideUIInVR: boolean

    // Debug Settings
    verboseLogging: boolean
    showDebugInfo: boolean
    showCompassRose: boolean
    enableBlockingTracker: boolean // Track main thread blocking operations

    // General Settings
    autoSave: boolean

    // Steam Settings (moved from GameSettings for centralization)
    autoLoadProfile: boolean
    developmentMode: boolean // Limit to 20 games for testing
}

export interface SettingChangedEvent extends BaseInteractionEvent {
    key: keyof ApplicationSettings
    value: ApplicationSettings[keyof ApplicationSettings]
    previousValue: ApplicationSettings[keyof ApplicationSettings]
}

/**
 * Centralized application settings service
 * Provides type-safe access to settings with localStorage persistence
 */
export class AppSettings {
    private static instance: AppSettings | null = null
    private settings: ApplicationSettings
    private eventManager: EventManager
    private readonly STORAGE_KEY = 'steam-brick-mortar-app-settings'

    private constructor() {
        this.eventManager = EventManager.getInstance()
        this.settings = this.loadSettings()
    }

    /**
     * Get the singleton instance of AppSettings
     */
    public static getInstance(): AppSettings {
        if (!AppSettings.instance) {
            AppSettings.instance = new AppSettings()
        }
        return AppSettings.instance
    }

    /**
     * Static shorthand for getting a setting value
     * Usage: AppSettings.get('enableLabels') instead of AppSettings.getInstance().getSetting('enableLabels')
     */
    public static get<K extends keyof ApplicationSettings>(key: K): ApplicationSettings[K] {
        return AppSettings.getInstance().settings[key]
    }

    /**
     * Get a specific setting value
     */
    public getSetting<K extends keyof ApplicationSettings>(key: K): ApplicationSettings[K] {
        return this.settings[key]
    }

    /**
     * Get the default value for a specific setting
     */
    public getDefaultSetting<K extends keyof ApplicationSettings>(key: K): ApplicationSettings[K] {
        const defaults = this.getDefaultSettings()
        return defaults[key]
    }

    /**
     * Check if a setting is currently at its default value
     */
    public isSettingAtDefault<K extends keyof ApplicationSettings>(key: K): boolean {
        return this.settings[key] === this.getDefaultSetting(key)
    }

    /**
     * Update a specific setting
     */
    public setSetting<K extends keyof ApplicationSettings>(
        key: K,
        value: ApplicationSettings[K],
        source: EventSource = EventSource.System
    ): void {
        const previousValue = this.settings[key]

        if (previousValue === value) {
            return // No change
        }

        this.settings[key] = value

        // Auto-save if enabled
        if (this.settings.autoSave) {
            this.saveSettings()
        }

        // Emit change event
        this.eventManager.emit<SettingChangedEvent>(AppSettingsEventTypes.Changed, {
            key,
            value,
            previousValue,
            source
        })
    }

    /**
     * Update multiple settings at once
     */
    public updateSettings(
        updates: Partial<ApplicationSettings>,
        source: EventSource = EventSource.System
    ): void {
        const changes: Array<SettingChangedEvent> = []
        const settingsRecord = this.settings as Record<keyof ApplicationSettings, ApplicationSettings[keyof ApplicationSettings]>

        for (const typedKey of Object.keys(updates) as Array<keyof ApplicationSettings>) {
            const value = updates[typedKey]
            if (value === undefined) {
                continue
            }

            const previousValue = settingsRecord[typedKey]

            if (previousValue !== value) {
                settingsRecord[typedKey] = value as ApplicationSettings[keyof ApplicationSettings]
                changes.push({
                    key: typedKey,
                    value: value as ApplicationSettings[keyof ApplicationSettings],
                    previousValue,
                    timestamp: Date.now(),
                    source
                })
            }
        }

        // Auto-save if enabled and there were changes
        if (changes.length > 0 && this.settings.autoSave) {
            this.saveSettings()
        }

        // Emit change events for all changes
        changes.forEach(change => {
            this.eventManager.emit<SettingChangedEvent>(AppSettingsEventTypes.Changed, change)
        })
    }

    /**
     * Get a copy of all current settings
     */
    public getAllSettings(): ApplicationSettings {
        return { ...this.settings }
    }

    /**
     * Reset settings to defaults
     */
    public resetToDefaults(source: EventSource = EventSource.UI): void {
        const oldSettings = { ...this.settings }
        this.settings = this.getDefaultSettings()
        this.saveSettings()

        // Emit events for all changed settings
        for (const [key, value] of Object.entries(this.settings)) {
            const typedKey = key as keyof ApplicationSettings
            const previousValue = oldSettings[typedKey]

            if (previousValue !== value) {
                this.eventManager.emit<SettingChangedEvent>(AppSettingsEventTypes.Changed, {
                    key: typedKey,
                    value: value as ApplicationSettings[keyof ApplicationSettings],
                    previousValue,
                    timestamp: Date.now(),
                    source
                })
            }
        }
    }

    /**
     * Reset specific settings to their defaults.
     * Use SettingCategory.Graphics (etc.) for category-based reset.
     */
    public resetSettingsToDefaults(
        keys: ReadonlyArray<keyof ApplicationSettings>,
        source: EventSource = EventSource.UI
    ): Partial<ApplicationSettings> {
        const defaults = this.getDefaultSettings()
        const changes: Partial<ApplicationSettings> = {}

        for (const key of keys) {
            const defaultValue = defaults[key]
            const currentValue = this.settings[key]

            if (currentValue !== defaultValue) {
                (this.settings as Record<keyof ApplicationSettings, unknown>)[key] = defaultValue
                ;(changes as Record<keyof ApplicationSettings, unknown>)[key] = defaultValue

                this.eventManager.emit<SettingChangedEvent>(AppSettingsEventTypes.Changed, {
                    key,
                    value: defaultValue,
                    previousValue: currentValue,
                    timestamp: Date.now(),
                    source
                })
            }
        }

        if (Object.keys(changes).length > 0) {
            this.saveSettings()
        }

        return changes
    }

    /**
     * Force save settings to localStorage
     */
    public saveSettings(): void {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.settings))
        } catch (error) {
            console.error('Failed to save settings:', error)
        }
    }

    /**
     * Validate and import settings from an external source
     */
    public importSettings(
        importedSettings: unknown,
        source: EventSource = EventSource.UI
    ): boolean {
        if (!this.validateSettings(importedSettings)) {
            return false
        }

        const validSettings = importedSettings as Partial<ApplicationSettings>
        const mergedSettings = { ...this.getDefaultSettings(), ...validSettings }

        this.updateSettings(mergedSettings, source)
        return true
    }

    /**
     * Export settings as JSON string
     */
    public exportSettings(): string {
        return JSON.stringify(this.settings, null, 2)
    }

    private loadSettings(): ApplicationSettings {
        try {
            const saved = localStorage.getItem(this.STORAGE_KEY)
            if (saved) {
                const parsed = JSON.parse(saved)
                return { ...this.getDefaultSettings(), ...parsed }
            }
        } catch (error) {
            console.warn('Failed to load settings:', error)
        }

        return this.getDefaultSettings()
    }

    private getDefaultSettings(): ApplicationSettings {
        // In development mode, disable GPU-intensive features by default for faster startup.
        const hostname = typeof window !== 'undefined' && window.location ? window.location.hostname : ''
        const isDev = hostname === 'localhost' || hostname === '127.0.0.1'

        return {
            // Performance Settings
            qualityLevel: 'high',

            // Graphics Settings
            lightingQuality: LIGHTING_QUALITY.ENHANCED,
            shadowQuality: 2, // Medium shadows by default
            ceilingHeight: 3.2,
            enableLighting: true,
            showLightingDebug: false,
            showCeiling: true,

            // TODO: Review these for removed / unused settings
            // Feature Flags
            enableLabels: true, // Text fallback for failed artwork - keep enabled
            enableStickers: !isDev, // GPU intensive - disable in dev for faster startup
            enableArtwork: true, // Always on - this is the core feature
            useMultiAtlas: false, // Use 3-tier atlas for better VRAM efficiency
            useLodAtlas: true, // Use LOD atlas with switchable detail levels (experimental)

            // LOD Settings - distances in meters for texture quality switching
            lodHighDistance: 3.0,  // Within 3m = HIGH quality textures
            lodMedDistance: 8.0,   // Within 8m = MED quality, beyond = LOW
            lodMaxHighSlots: 128,  // Max HIGH texture slots (128 ├ù 300├ù450 = ~66MB VRAM)
            lodHighReductionRatio: 0.5,  // HIGH = 50% of source (600├ù900 ΓåÆ 300├ù450)
            lodMedReductionRatio: 0.25,  // MED = 25% of source (600├ù900 ΓåÆ 150├ù225)

            // Interface Settings
            showFPS: false,
            showPerformanceStats: false,
            hideUIInVR: true,

            // Debug Settings
            verboseLogging: false,
            showDebugInfo: false,
            showCompassRose: false,
            enableBlockingTracker: isDev, // Enable in dev mode by default

            // General Settings
            autoSave: true,

            // Steam Settings  
            autoLoadProfile: true,
            developmentMode: isDev // Default based on environment
        }
    }

    private validateSettings(settings: unknown): settings is Partial<ApplicationSettings> {
        if (typeof settings !== 'object' || settings === null) return false

        const settingsObj = settings as Record<string, unknown>

        // Validate specific fields if present
        if (settingsObj.qualityLevel && !['low', 'medium', 'high', 'ultra'].includes(settingsObj.qualityLevel as string)) {
            return false
        }

        // Validate boolean fields
        const booleanFields = [
            'showFPS', 'showPerformanceStats', 'hideUIInVR', 
            'verboseLogging', 'showDebugInfo', 'showCompassRose',
            'autoSave', 'autoLoadProfile', 'developmentMode',
            'enableLabels', 'enableStickers', 'enableArtwork', 'useMultiAtlas', 'useLodAtlas',
            'enableLighting', 'showLightingDebug', 'showCeiling'
        ]
        for (const field of booleanFields) {
            if (settingsObj[field] !== undefined && typeof settingsObj[field] !== 'boolean') {
                return false
            }
        }

        return true
    }

    /**
     * Dispose of the settings service (for testing)
     */
    public static dispose(): void {
        if (AppSettings.instance) {
            // Save final state before disposal
            AppSettings.instance.saveSettings()
            AppSettings.instance = null
        }
    }
}

if(window) {
    // @ts-ignore
    window.AppSettings = AppSettings;
}

import { Logger } from '../utils/Logger'

export enum EventSource {
    UI = 'ui',
    // TODO: Why won't "input device" suffice?
    Keyboard = 'keyboard',
    Mouse = 'mouse',
    Gamepad = 'gamepad',
    VRController = 'vr-controller',
    System = 'system',
    ManagedLight = 'managed-light'
}

export interface BaseInteractionEvent {
    // TODO: Remove these optional markers after migrating all emit() calls to not provide timestamp/source
    timestamp?: number
    source?: EventSource
}

export interface EventHandlerOptions extends AddEventListenerOptions {
    /** Register as default handler - only used if no other handlers exist */
    isDefault?: boolean
    /** Register as override handler - removes existing handlers first */
    isOverride?: boolean
}

// Type alias for cleaner code
// Handler type for internal use
type HandlerFunction = (event: CustomEvent<BaseInteractionEvent>) => void

export class EventManager extends EventTarget {
    private static instance: EventManager
    private static readonly logger = Logger.createLogFunctions(EventManager.name)

    // Simplified tracking
    private registeredHandlers = new Map<string, Set<HandlerFunction>>()
    private normalHandlers = new Map<string, Set<HandlerFunction>>()
    private defaultHandlers = new Map<string, Set<HandlerFunction>>()

    private constructor() {
        super()
        EventManager.logger.info('EventManager initialized')
    }

    public static getInstance(): EventManager {
        if (!EventManager.instance) {
            EventManager.instance = new EventManager()
        }
        return EventManager.instance
    }

    /**
     * Emit an event with automatic timestamp generation.
     * Note: The timestamp field will be automatically set to Date.now() - 
     * consuming classes should not provide their own timestamp value.
     */
    public emit<T extends BaseInteractionEvent>(
        eventType: string, 
        detail?: T,
        source: T['source'] = EventSource.System as T['source']
    ): boolean {
        const eventDetail = {
            ...(detail || {}),
            timestamp: Date.now(),
            source: detail?.source || source
        }

        const event = new CustomEvent(eventType, { detail: eventDetail })

        // Only log non-noisy events (skip high-frequency events like game-loaded)
        if (!eventType.includes('game-loaded') && !eventType.includes(':progress')) {
            EventManager.logger.debug(`Emitting event: ${eventType}`, { detail: eventDetail })
        }
        return this.dispatchEvent(event)
    }

    public registerEventHandler<T extends BaseInteractionEvent>(
        eventType: string,
        handler: (event: CustomEvent<T>) => void,
        options?: EventHandlerOptions
    ): void {
        const typedHandler = handler as HandlerFunction
        const normalCount = this.normalHandlers.get(eventType)?.size ?? 0
        const defaultCount = this.defaultHandlers.get(eventType)?.size ?? 0

        if (options?.isDefault) {
            if (normalCount > 0) {
                EventManager.logger.warn(`Skipping default handler for ${eventType}, normal handlers already exist`)
                return
            }
            this.addToHandlerMap(this.defaultHandlers, eventType, typedHandler)

        } else if (options?.isOverride) {
            if (defaultCount > 0) {
                this.removeDefaultHandlers(eventType)
                EventManager.logger.debug(`Removed default handlers for override: ${eventType}`)
            }
            this.addToHandlerMap(this.normalHandlers, eventType, typedHandler)

        } else {
            if (defaultCount > 0) {
                this.removeDefaultHandlers(eventType)
                EventManager.logger.debug(`Replaced default handlers with normal handler: ${eventType}`)
            }
            this.addToHandlerMap(this.normalHandlers, eventType, typedHandler)
        }

        this.addEventListener(eventType, handler as EventListener, options)
        this.addToHandlerMap(this.registeredHandlers, eventType, typedHandler)

        // Only log registration for important/infrequent events
        if (!eventType.includes(':progress') && !eventType.includes('game-loaded')) {
            const handlerType = options?.isDefault ? 'default' : options?.isOverride ? 'override' : 'normal'
            EventManager.logger.debug(`Registered ${handlerType} handler for: ${eventType}`)
        }
    }

    private addToHandlerMap(map: Map<string, Set<HandlerFunction>>, eventType: string, handler: HandlerFunction): void {
        if (!map.has(eventType)) {
            map.set(eventType, new Set())
        }
        map.get(eventType)?.add(handler)
    }

    private removeFromHandlerMap(map: Map<string, Set<HandlerFunction>>, eventType: string, handler: HandlerFunction): boolean {
        const handlers = map.get(eventType)
        if (handlers?.has(handler)) {
            handlers.delete(handler)
            if (handlers.size === 0) {
                map.delete(eventType)
            }
            return true
        }
        return false
    }

    private removeDefaultHandlers(eventType: string): void {
        const defaultHandlers = this.defaultHandlers.get(eventType)
        if (defaultHandlers) {
            for (const handler of defaultHandlers) {
                this.removeEventListener(eventType, handler as EventListener)
                this.removeFromHandlerMap(this.registeredHandlers, eventType, handler)
            }
            this.defaultHandlers.delete(eventType)
        }
    }

    public deregisterEventHandler<T extends BaseInteractionEvent>(
        eventType: string,
        handler: (event: CustomEvent<T>) => void,
        options?: EventListenerOptions
    ): void {
        const typedHandler = handler as HandlerFunction
        this.removeEventListener(eventType, handler as EventListener, options)

        // Remove from all tracking maps
        this.removeFromHandlerMap(this.registeredHandlers, eventType, typedHandler)
        this.removeFromHandlerMap(this.normalHandlers, eventType, typedHandler)
        this.removeFromHandlerMap(this.defaultHandlers, eventType, typedHandler)
    }

    private removeAllListenersForEvent(eventType: string): void {
        const handlers = this.registeredHandlers.get(eventType)
        if (handlers) {
            for (const handler of handlers) {
                this.removeEventListener(eventType, handler as EventListener)
            }
        }

        // Clean up all tracking consistently
        this.registeredHandlers.delete(eventType)
        this.normalHandlers.delete(eventType)
        this.defaultHandlers.delete(eventType)
    }

    public removeAllListeners(eventType?: string): void {
        if (eventType) {
            this.removeAllListenersForEvent(eventType)
            EventManager.logger.debug(`Removed all listeners for: ${eventType}`)
        } else {
            // Remove all listeners for all events
            for (const eventType of this.registeredHandlers.keys()) {
                this.removeAllListenersForEvent(eventType)
            }
            // Final cleanup
            this.registeredHandlers.clear()
            this.normalHandlers.clear()
            this.defaultHandlers.clear()
            EventManager.logger.debug('Removed all listeners')
        }
    }

    // Backward compatibility methods
    public registerDefaultHandler<T extends BaseInteractionEvent>(
        eventType: string,
        handler: (event: CustomEvent<T>) => void
    ): void {
        this.registerEventHandler(eventType, handler, { isDefault: true })
    }

    public registerOverrideHandler<T extends BaseInteractionEvent>(
        eventType: string,
        handler: (event: CustomEvent<T>) => void
    ): void {
        this.registerEventHandler(eventType, handler, { isOverride: true })
    }

    public dispose(): void {
        this.removeAllListeners()
        EventManager.logger.info('EventManager disposed')
    }
}

∩╗┐/**
 * Steam Brick and Mortar Application Core
 * 
 * Main application orchestrator that coordinates high-level subsystems:
 * - Scene coordination via SceneCoordinator
 * - WebXR and input coordination via WebXRCoordinator  
 * - UI coordination via UICoordinator
 * - Steam integration and game management
 * 
 * This class follows the orchestrator pattern - it initializes coordinators
 * and delegates complex workflows to them, keeping this class focused on
 * high-level application lifecycle management.
 */

import * as THREE from 'three'
import { ToastManager, UIManager, StartupProgressUI, GameLibraryBinderUI } from '../ui'
import { WebXRUICoordinator, SystemUICoordinator } from '../ui/coordinators'
import { SceneManager, SceneCoordinator } from '../scene'
import { SceneManagerDebug } from '../debug/SceneManagerDebug'
import { CompassRose } from '../ui/debug/CompassRose'
import { SteamIntegration } from '../steam-integration'
import { WebXRCoordinator } from '../webxr/WebXRCoordinator'
import { WebXREventHandler } from '../webxr/WebXREventHandler'
import { EventManager } from './EventManager'
import { GameEventTypes, type GameStartEvent, type SceneReadyEvent } from '../types/InteractionEvents'
import { AppSettings } from './AppSettings'

import { StartupEventTracker, StartupPhase } from '../utils/StartupEventTracker'
import { RenderLoopDiagnostics } from '../debug/RenderLoopDiagnostics'
// Side-effect import: registers GpuMemoryEstimator to window for console debugging
import '../debug/GpuMemoryEstimator'

export interface AppConfig {
    scene?: {
        antialias?: boolean
        outputColorSpace?: THREE.ColorSpace
    }
    input?: {
        speed?: number
        mouseSensitivity?: number
    }
    steam?: {
        apiBaseUrl?: string
        maxGames?: number
    }
    data?: {
        enablePersistence?: boolean
        defaultTTL?: number
        maxEntries?: number
    }
    tests?: Record<string, string>
}

const BACKEND_URL = 'https://steam-api-dev.wehrly.com';

export class SteamBrickAndMortarApp {
    private readonly config: AppConfig // Store config for potential recreation

    // Services - will be resolved from container where available
    private sceneManager: SceneManager
    private sceneCoordinator!: SceneCoordinator // Will be resolved from DI container in init()
    private webxrCoordinator: WebXRCoordinator
    private webxrEventHandler: WebXREventHandler
    // UI coordinators resolved from DI container
    private webxrUICoordinator: WebXRUICoordinator  
    private systemUICoordinator: SystemUICoordinator
    private uiManager: UIManager
    private steamIntegration: SteamIntegration
    private eventManager: EventManager
    private appSettings: AppSettings
    private compassRose?: CompassRose
    private gameLibraryBinder?: GameLibraryBinderUI

    // Startup tracking
    private startupTracker: StartupEventTracker

    // State
    private isInitialized: boolean = false
    private initPromise: Promise<void> | null = null

    // GameStart prerequisite tracking
    private prerequisites = {
        sceneReady: false,
        renderLoopReady: false,
        uiReady: false
    }
    private gameStartEmitted = false

    constructor(config: AppConfig = {}) {
        // Initialize startup tracker first to capture all events
        this.startupTracker = StartupEventTracker.getInstance()

        // Phase 1: CoreInit ΓÇö everything up through DI resolution
        this.startupTracker.phaseStart(StartupPhase.CoreInit, 'Core initialization')

        // Create startup progress UI (self-contained; listens to AppEventTypes events)
        new StartupProgressUI()
        // Wire game-loading progress listeners now that we have an EventManager instance
        this.startupTracker.setupProgressListeners()

        // Store config for potential container recreation
        this.config = config

        // Initialize AppSettings first (needed for default values)
        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Initializing AppSettings')
        this.appSettings = AppSettings.getInstance()

        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Creating SceneManager')
        this.sceneManager = new SceneManagerDebug({
            antialias: config.scene?.antialias ?? true,
            outputColorSpace: config.scene?.outputColorSpace ?? THREE.SRGBColorSpace
        })

        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Preparing core coordinators')

        const isDevelopmentMode = this.appSettings.getSetting('developmentMode')
        const defaultMaxGames = isDevelopmentMode ? 20 : 100
        const maxGames = config.steam?.maxGames ?? defaultMaxGames

        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Creating SteamIntegration')
        this.steamIntegration = new SteamIntegration({
            apiBaseUrl: config.steam?.apiBaseUrl ?? BACKEND_URL,
            maxGames: maxGames
        })

        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Creating WebXRCoordinator')
        this.webxrCoordinator = new WebXRCoordinator({
            camera: this.sceneManager.getCamera(),
            input: {
                speed: config.input?.speed ?? 0.1,
                mouseSensitivity: config.input?.mouseSensitivity ?? 0.005
            }
        })

        this.startupTracker.logEvent(StartupPhase.CoreInit, 'Creating UIManager')
        this.uiManager = new UIManager()

        this.startupTracker.phaseEnd(StartupPhase.CoreInit, 'Constructor complete')
    }

    async init(): Promise<void> {
        if (this.isInitialized) {
            return
        }

        if (this.initPromise) {
            return this.initPromise
        }

        this.initPromise = this.initImpl()
        try {
            await this.initPromise
        } finally {
            this.initPromise = null
        }
    }

    private async initImpl(): Promise<void> {
        try {
            this.startupTracker.phaseStart(StartupPhase.EngineStart, 'DI Container + coordinators initialization')

            this.eventManager = EventManager.getInstance()

            // Set up prerequisite event listeners now that EventManager is available
            this.startupTracker.logEvent(StartupPhase.EngineStart, 'Setting up prerequisite event listeners')
            this.setupPrerequisiteEventListeners()

            // Construct SceneCoordinator directly (DI container removed)
            this.startupTracker.logEvent(StartupPhase.EngineStart, 'Constructing SceneCoordinator')
            this.sceneCoordinator = new SceneCoordinator(this.sceneManager)

            // Construct UI coordinators directly ΓÇö no DI indirection needed
            this.startupTracker.logEvent(StartupPhase.EngineStart, 'Constructing UI coordinators')
            this.webxrUICoordinator = new WebXRUICoordinator()
            this.systemUICoordinator = new SystemUICoordinator(
                this.eventManager,
                this.appSettings
            )

            // Initialize webxr event handler now that UI coordinators are available
            this.webxrEventHandler = new WebXREventHandler(
                this.webxrCoordinator,
                this.webxrUICoordinator,
                this.eventManager
            )

            this.startupTracker.phaseEnd(StartupPhase.EngineStart)


            // ≡ƒÄ» PRIORITY 1: Get controls working ASAP - this enables user input immediately
            this.startupTracker.phaseStart(StartupPhase.ControlsReady, 'Controls initialization')
            this.startupTracker.milestone(StartupPhase.ControlsReady, 'Setting up controls')
            await this.initializeControls()
            this.startupTracker.phaseEnd(StartupPhase.ControlsReady)

            this.startupTracker.milestone(StartupPhase.ControlsReady, 'Player can move')

            // ≡ƒÄ» PRIORITY 2: Basic UI and render loop (blocking for interaction)
            this.startupTracker.phaseStart(StartupPhase.Interactive, 'Starting render loop and critical UI')
            this.startupTracker.milestone(StartupPhase.Interactive, 'Initializing UI')
            await this.initializeCriticalUI()

            this.startupTracker.milestone(StartupPhase.Interactive, 'Starting render engine')
            this.startRenderLoop()

            this.prerequisites.renderLoopReady = true
            this.checkGameStartPrerequisites()

            this.isInitialized = true
            this.startupTracker.phaseEnd(StartupPhase.Interactive)
            this.startupTracker.milestone(StartupPhase.Interactive, 'User can move - starting world build')

            // ≡ƒÄ¼ PRIORITY 2.5: Start scene building AFTER render loop is running.
            // Material prewarm runs concurrently ΓÇö the scene setup pipeline has enough
            // async steps that materials will be ready before shelves are actually built.
            // Do NOT await materialPrewarmPromise here ΓÇö that caused a visible black-screen hitch.
            this.sceneCoordinator.startSceneSetup()

            // PRIORITY 3: Everything else happens async (non-blocking)
            this.initializeNonEssentialSystemsAsync()

        } catch (error) {
            console.error('Failed to initialize application:', error)
            this.startupTracker.logEvent(StartupPhase.Interactive, `INITIALIZATION ERROR: ${error}`)
            throw error
        }
    }

    private async initializeControls(): Promise<void> {
        await this.webxrCoordinator.setupWebXR(this.sceneManager.getRenderer())
    }

    private async initializeCriticalUI(): Promise<void> {
        this.uiManager.init()
        this.uiManager.hideLoading()

        console.debug('≡ƒÄ¿ Critical UI ready')
        this.prerequisites.uiReady = true
        this.checkGameStartPrerequisites()
    }

    private initializeNonEssentialSystemsAsync(): void {
        this.startupTracker.logAsyncStart(StartupPhase.PostSetupEncore, 'Non-essential systems initialization')

        this.loadNonEssentialSystems().catch(error => {
            console.error('ΓÜá∩╕Å Non-essential systems failed to load:', error)
            this.startupTracker.logEvent(StartupPhase.PostSetupEncore, `Non-essential systems error: ${error}`)
        })
    }

    private async loadNonEssentialSystems(): Promise<void> {
        const asyncStartTime = this.startupTracker.logAsyncStart(StartupPhase.PostSetupEncore, 'Loading non-essential systems')

        try {
            this.startupTracker.phaseStart(StartupPhase.PrewarmEncore, 'Debug systems initialization')
            // Binder button first so it occupies the top slot in ui-right-center-group;
            // lighting panel appends after and sits below it.
            this.gameLibraryBinder = GameLibraryBinderUI.getInstance()
            this.gameLibraryBinder.init()
            this.startupTracker.logEvent(StartupPhase.PrewarmEncore, 'Game Library Binder UI initialized')

            // Initialize system UI coordinator (lighting panel, debug panels, etc.)
            await this.systemUICoordinator.init(this.sceneManager.getRenderer())
            this.startupTracker.phaseEnd(StartupPhase.PrewarmEncore)

            // PostSetupEncore: auto-load Steam games; progress events handled via AppEventTypes
            this.startupTracker.phaseStart(StartupPhase.PostSetupEncore, 'Steam data fetch')
            ToastManager.success('Steam Brick and Mortar is fully loaded!', { duration: 3000 })
            this.startupTracker.phaseEnd(StartupPhase.PostSetupEncore)

            this.startupTracker.logAsyncEnd(StartupPhase.PostSetupEncore, 'Non-essential systems loaded', asyncStartTime)

        } catch (error) {
            console.error('Failed to load non-essential systems:', error)
            this.startupTracker.logEvent(StartupPhase.PostSetupEncore, `Load error: ${error}`)
        }
    }

    async dispose(): Promise<void> {
        if (!this.isInitialized) {
            return
        }

        this.webxrEventHandler.dispose()
        this.eventManager.dispose()

        this.systemUICoordinator.dispose()
        this.webxrCoordinator.dispose()
        this.sceneCoordinator.dispose()
        this.sceneManager.dispose()

        this.isInitialized = false
        this.initPromise = null
        console.debug('Γ£à Application disposed')
    }

    private setupPrerequisiteEventListeners(): void {
        this.eventManager.registerEventHandler<SceneReadyEvent>(
            GameEventTypes.SceneReady,
            () => {
                this.startupTracker.milestone(StartupPhase.WorldBuild, 'World has spawned')
                this.prerequisites.sceneReady = true
                this.checkGameStartPrerequisites()
            }
        )

        // GameStart event triggers auto-load via SteamIntegration
    }

    private checkGameStartPrerequisites(): void {
        if (this.gameStartEmitted) {
            console.debug('Γ£à GameStart already emitted')
            return
        }

        const { sceneReady, renderLoopReady, uiReady } = this.prerequisites

        this.startupTracker.logEvent(StartupPhase.WorldBuild, 'Checking prerequisites', {
            sceneReady,
            renderLoopReady,
            uiReady
        })

        if (sceneReady && renderLoopReady && uiReady) {
            this.emitGameStartEvent()
            this.gameStartEmitted = true
        } else {
            console.debug('ΓÅ│ Waiting for remaining prerequisites...', { sceneReady, renderLoopReady, uiReady })
        }
    }

    private emitGameStartEvent(): void {
        this.startupTracker.phaseStart(StartupPhase.WorldBuild, 'Emitting GameStart event')
        this.startupTracker.milestone(StartupPhase.WorldBuild, 'World ready')
        console.debug('≡ƒÄ« GameStart event emitted')
        this.eventManager.emit<GameStartEvent>(GameEventTypes.Start, {
            prerequisites: {
                sceneReady: this.prerequisites.sceneReady,
                renderLoopReady: this.prerequisites.renderLoopReady,
                uiReady: this.prerequisites.uiReady
            }
        })
        this.startupTracker.phaseEnd(StartupPhase.WorldBuild)
    }

    private startRenderLoop(): void {
        // Initialize compass rose (self-registers with render loop)
        // TODO: This probably shouldn't go here, but where does it go?
        this.compassRose = new CompassRose(this.sceneManager.getCamera())

        // TODO: Normalize configuration inputs
        // and don't require so many lines in the main files

        // Initialize render loop diagnostics if enabled via URL param (?diagnostics=1)
        // This MUST happen before startRenderLoop() - decision is made once, zero per-frame overhead when disabled
        // TODO: set appsettings from url, have diagnostics class set up at this phase?
        const urlParams = new URLSearchParams(window.location.search)
        const diagnosticsEnabled = urlParams.get('diagnostics') === '1'
        RenderLoopDiagnostics.initialize({ 
            enabled: diagnosticsEnabled,
            logInterval: 60,  // Log every ~1 second at 60fps
            frameTimeWarnThreshold: 16.67,  // Warn if frame exceeds 60fps budget
            callbackTimeWarnThreshold: 5  // Warn if any callback > 5ms
        })

        // Start the render loop (all updates happen via registry)
        this.sceneManager.startRenderLoop()
    }

    // TODO: This method exists solely for testing purposes - remove or refactor
    getIsInitialized(): boolean {
        return this.isInitialized
    }

    // Test-only getters - minimal interface for testing
    getSteamIntegration(): SteamIntegration {
        return this.steamIntegration
    }

    getSceneManager(): SceneManager {
        return this.sceneManager
    }
}

/**
 * Centralized Data Management System
 * 
 * Single source of truth for application data with type safety,
 * meta-keying, dynamic lookups, and future persistence support.
 * 
 * Phase 1 Implementation:
 * - Basic string->object mapping with type safety
 * - Domain-based meta-keying for data organization
 * - Singleton pattern for global access
 * - Event integration for automatic updates
 */

import { EventManager, EventSource, type BaseInteractionEvent } from '../EventManager'
import type { 
    DataDomain, 
    DataEntry, 
    DataMetadata, 
    DataProvider, 
    DataManagerConfig
} from './DataTypes'

// Data-specific events that extend BaseInteractionEvent
interface DataEvent extends BaseInteractionEvent {
    key: string
    domain: DataDomain
}

interface DataChangeEventDetail<T = any> extends DataEvent {
    oldValue?: T
    newValue: T
}

interface DataDeletedEventDetail extends DataEvent {}

interface DataClearedEventDetail extends BaseInteractionEvent {
    entriesCleared: number
}

export class DataManager {
    private static instance: DataManager | null = null
    private store = new Map<string, DataEntry>()
    private metaStore = new Map<DataDomain, Set<string>>()
    private dynamicProviders = new Map<string, DataProvider>()
    private eventManager: EventManager
    private config: DataManagerConfig

    private constructor(config: DataManagerConfig = {}) {
        this.config = {
            enablePersistence: false,
            defaultTTL: undefined,
            maxEntries: 10000,
            ...config
        }
        this.eventManager = EventManager.getInstance()
    }

    /**
     * Get singleton instance
     */
    public static getInstance(config?: DataManagerConfig): DataManager {
        if (!DataManager.instance) {
            DataManager.instance = new DataManager(config)
        }
        return DataManager.instance
    }

    /**
     * Store data with type safety and metadata
     */
    public set<T>(key: string, value: T, metadata: DataMetadata): void {
        const oldEntry = this.store.get(key)
        const now = Date.now()

        const entry: DataEntry<T> = {
            value,
            metadata,
            timestamp: now,
            expiresAt: metadata.ttl ? now + metadata.ttl : undefined
        }

        this.store.set(key, entry)

        // Update meta-store for domain tracking
        if (!this.metaStore.has(metadata.domain)) {
            this.metaStore.set(metadata.domain, new Set())
        }
        this.metaStore.get(metadata.domain)!.add(key)

        // Emit change event using DOM events
        const changeDetail: DataChangeEventDetail<T> = {
            key,
            oldValue: oldEntry?.value,
            newValue: value,
            domain: metadata.domain,
            timestamp: now,
            source: EventSource.System
        }

        window.dispatchEvent(new CustomEvent('data:changed', { detail: changeDetail }))

        console.debug(`≡ƒôè Stored data: ${key} (domain: ${metadata.domain})`)
    }

    /**
     * Retrieve data with type safety
     */
    public get<T>(key: string): T | undefined {
        const entry = this.store.get(key)

        if (!entry) {
            return undefined
        }

        // Check expiration
        if (entry.expiresAt && Date.now() > entry.expiresAt) {
            this.delete(key)
            return undefined
        }

        return entry.value as T
    }

    /**
     * Retrieve data with fallback value
     */
    public getOrDefault<T>(key: string, defaultValue: T): T {
        const value = this.get<T>(key)
        return value !== undefined ? value : defaultValue
    }

    /**
     * Check if key exists and is not expired
     */
    public has(key: string): boolean {
        const entry = this.store.get(key)

        if (!entry) {
            return false
        }

        // Check expiration
        if (entry.expiresAt && Date.now() > entry.expiresAt) {
            this.delete(key)
            return false
        }

        return true
    }

    /**
     * Delete data entry
     */
    public delete(key: string): boolean {
        const entry = this.store.get(key)

        if (!entry) {
            return false
        }

        // Remove from meta-store
        const domainKeys = this.metaStore.get(entry.metadata.domain)
        if (domainKeys) {
            domainKeys.delete(key)
            if (domainKeys.size === 0) {
                this.metaStore.delete(entry.metadata.domain)
            }
        }

        const deleted = this.store.delete(key)

        if (deleted) {
            const deleteDetail: DataDeletedEventDetail = {
                key,
                domain: entry.metadata.domain,
                timestamp: Date.now(),
                source: EventSource.System
            }

            window.dispatchEvent(new CustomEvent('data:deleted', { detail: deleteDetail }))
            console.debug(`≡ƒôè Deleted data: ${key}`)
        }

        return deleted
    }

    /**
     * Get all keys for a specific domain
     */
    public getKeysByDomain(domain: DataDomain): string[] {
        const keys = this.metaStore.get(domain)
        return keys ? Array.from(keys) : []
    }

    /**
     * Get all data for a specific domain
     */
    public getDataByDomain<T = any>(domain: DataDomain): Record<string, T> {
        const keys = this.getKeysByDomain(domain)
        const result: Record<string, T> = {}

        for (const key of keys) {
            const value = this.get<T>(key)
            if (value !== undefined) {
                result[key] = value
            }
        }

        return result
    }

    /**
     * Clear all data for a specific domain
     */
    public clearDomain(domain: DataDomain): number {
        const keys = this.getKeysByDomain(domain)
        let deletedCount = 0

        for (const key of keys) {
            if (this.delete(key)) {
                deletedCount++
            }
        }

        console.debug(`≡ƒôè Cleared ${deletedCount} entries from domain: ${domain}`)
        return deletedCount
    }

    /**
     * Get all available domains
     */
    public getDomains(): DataDomain[] {
        return Array.from(this.metaStore.keys())
    }

    /**
     * Get metadata for a key
     */
    public getMetadata(key: string): DataMetadata | undefined {
        const entry = this.store.get(key)
        return entry?.metadata
    }

    /**
     * Get all keys (optionally filtered by domain)
     */
    public getAllKeys(domain?: DataDomain): string[] {
        if (domain) {
            return this.getKeysByDomain(domain)
        }
        return Array.from(this.store.keys())
    }

    /**
     * Clear all data
     */
    public clear(): void {
        const totalEntries = this.store.size
        this.store.clear()
        this.metaStore.clear()
        this.dynamicProviders.clear()

        const clearDetail: DataClearedEventDetail = {
            entriesCleared: totalEntries,
            timestamp: Date.now(),
            source: EventSource.System
        }

        window.dispatchEvent(new CustomEvent('data:cleared', { detail: clearDetail }))

        console.debug(`≡ƒôè Cleared all data (${totalEntries} entries)`)
    }

    /**
     * Get statistics about data storage
     */
    // =================================================================
    // Memory Consumption Tracking
    // Systems register their estimated GPU/memory usage here
    // =================================================================

    private memoryConsumers = new Map<string, { megabytes: number; getCurrentValue?: () => number }>()

    /**
     * Register a memory consumer with its current usage in MB
     * @param name Unique identifier for this consumer (e.g., 'LOD/high', 'InstancedShelf')
     * @param megabytes Current memory usage in whole megabytes
     * @param getCurrentValue Optional callback to get current value when aggregating stats
     */
    public addMemoryConsumption(
        name: string, 
        megabytes: number, 
        getCurrentValue?: () => number
    ): void {
        this.memoryConsumers.set(name, { megabytes, getCurrentValue })
    }

    /**
     * Remove a memory consumer (e.g., on dispose)
     */
    public removeMemoryConsumption(name: string): void {
        this.memoryConsumers.delete(name)
    }

    /**
     * Get all registered memory consumers with current values
     * If a consumer has getCurrentValue callback, it's called to get fresh data
     */
    public getMemoryConsumption(): Map<string, number> {
        const result = new Map<string, number>()

        for (const [name, entry] of this.memoryConsumers) {
            const value = entry.getCurrentValue ? entry.getCurrentValue() : entry.megabytes
            result.set(name, value)
        }

        return result
    }

    // =================================================================

    public getStats(): {
        totalEntries: number
        domains: number
        providers: number
        memoryUsage: string
    } {
        return {
            totalEntries: this.store.size,
            domains: this.metaStore.size,
            providers: this.dynamicProviders.size,
            memoryUsage: `~${Math.round(JSON.stringify(Array.from(this.store.entries())).length / 1024)}KB`
        }
    }

    /**
     * Cleanup expired entries
     */
    public cleanup(): number {
        const now = Date.now()
        const expiredKeys: string[] = []

        for (const [key, entry] of this.store.entries()) {
            if (entry.expiresAt && now > entry.expiresAt) {
                expiredKeys.push(key)
            }
        }

        for (const key of expiredKeys) {
            this.delete(key)
        }

        if (expiredKeys.length > 0) {
            console.debug(`≡ƒôè Cleaned up ${expiredKeys.length} expired entries`)
        }

        return expiredKeys.length
    }

    /**
     * Reset singleton instance (for testing)
     */
    public static resetInstance(): void {
        DataManager.instance = null
    }
}

