        const artworkRenderer = this.renderer.getInstancedArtworkRenderer()
        if (artworkRenderer) {
            artworkRenderer.debugExportTextureArray()
            artworkRenderer.debugLogTextureArrayState()
        } else {
            console.warn('≡ƒöì InstancedArtworkRenderer not available')
        }
