        console.log('≡ƒöì [DEBUG] Artwork Renderer:', artworkRenderer ? 'Available' : 'Not available')
        if (artworkRenderer) {
            console.log('≡ƒöì [DEBUG] Artwork Instance Index:', this.renderer.getArtworkInstanceIndex())
        }
    }

    /**
     * Get information about artwork selection settings
     */
    public getArtworkSelectionInfo(): void {
        console.log('≡ƒöì [DEBUG] Artwork selection info:')
        console.log('≡ƒöì [DEBUG] Current setting: Every 20th game gets artwork')
        console.log('≡ƒöì [DEBUG] To see changes, reload the page after modifying StorePropsRenderer')
    }

    /**
     * Expose debug functions to global window object for console access
     */
    private exposeGlobalFunctions(): void {
        if (typeof window !== 'undefined') {
            (window as any).steamDebug = {
                exportTextureArray: () => this.exportTextureArray(),
                logRendererState: () => this.logRendererState(),
                forceGPUUpdate: () => this.forceGPUUpdate(),
                getArtworkSelectionInfo: () => this.getArtworkSelectionInfo()
