/**
 * Game Finder - Locate game objects in the Three.js scene
 *
 * TD: GameFinder belongs in src/utils/ (or src/scene/), not src/debug/.
 * It's used in production raycast resolution paths, not just debug tooling.
 * Deferred to avoid a disruptive move while the raycast path is actively changing.
 *
 * Singleton pattern (ES2022 private static field) ΓÇö static methods are the
 * public API; no getInstance() call needed at call sites.
 *
 * Usage:
 *   GameFinder.findByIntersection(intersection)  // raycast hit ΓåÆ game
 *   GameFinder.find("UNLOVED")                   // by name or appid
 *   GameFinder.findAll()                          // all known games
 */

import * as THREE from 'three'
import { DataManager } from '../core/data/DataManager'
import { DataKey } from '../core/data/DataTypes'
import { INSTANCED_LABEL_MESH_NAME } from '../scene/game-box/instancing/InstancedLabelRenderer'
import { LOD_ARTWORK_MESH_NAME } from '../scene/game-box/instancing/LodGameArtworkRenderer'
import { EventManager } from '../core/EventManager'
import { GameEventTypes } from '../types/InteractionEvents'
import { Logger } from '../utils/Logger'

export interface InstanceMetadata {
    name: string
    appid?: number | string
    position: THREE.Vector3
}

export interface InstancedObject {
    object: THREE.Object3D
    instanceId: number
}

export interface GameSceneObject {
    name?: string
    appid?: number | string
    position: THREE.Vector3
    mesh: THREE.Object3D
    instanceIndex?: number
    rendererType: 'gpu' | 'legacy' | 'label'
}

export class GameFinder {
    static #instance: GameFinder | null = null
    private static readonly logger = Logger.createLogFunctions(GameFinder.name)

    static get #current(): GameFinder {
        return GameFinder.#instance ??= new GameFinder()
    }

    // TODO: remove after GameSpotlight cleanup
    public static getScene(): THREE.Scene {
        return GameFinder.#current.scene
    }

    // Exposed for debug tools that need direct scene access (GameSpotlight etc.)
    readonly scene: THREE.Scene

    private constructor() {
        const scene = DataManager.getInstance().get<THREE.Scene>(DataKey.MainScene)
        if (!scene) {
            throw new Error('GameFinder requires scene to be registered in DataManager')
        }
        this.scene = scene
    }

    /**
     * Resolve a raycaster intersection to a GameSceneObject.
     *
     * Mesh name is the discriminator between artwork and label InstancedMeshes ΓÇö
     * instanceId is per-mesh (0..N), so the same number on two different meshes
     * means two different games. The metadata maps are keyed the same way.
     */
    public static findByInstancedObject({ object, instanceId }: InstancedObject): GameSceneObject | null {
        if (instanceId === undefined) return null

        const meshName = object.name
        const isArtwork = meshName === LOD_ARTWORK_MESH_NAME
        const isLabel = meshName === INSTANCED_LABEL_MESH_NAME
        if (!isArtwork && !isLabel) {
            GameFinder.logger.warn(`findByInstancedObject: unrecognized mesh "${meshName}" (instanceId=${instanceId}) ΓÇö not in artwork or label maps`)
            return null
        }

        const dataManager = DataManager.getInstance()
        const metaKey = isArtwork ? DataKey.InstancedArtworkMetadata : DataKey.InstancedLabelMetadata
        const meta = dataManager.get<Map<number, InstanceMetadata>>(metaKey)?.get(instanceId)
        if (!meta?.appid) {
            GameFinder.logger.warn(`findByInstancedObject: instanceId=${instanceId} on "${meshName}" has no appid in metadata (meta=${JSON.stringify(meta ?? null)})`)
            return null
        }

        return {
            name: meta.name,
            appid: meta.appid,
            position: meta.position.clone(),
            mesh: object,
            instanceIndex: instanceId,
            rendererType: isArtwork ? 'gpu' : 'label',
        }
    }

    public static find(identifier: string | number): GameSceneObject | null {
        return typeof identifier === 'number'
            ? GameFinder.#current.findByAppId(identifier)
            : GameFinder.#current.findByName(identifier)
    }

    public static findAll(): GameSceneObject[] {
        return GameFinder.#current.findAllImpl()
    }

    public static listAllGameNames(): string[] {
        const games = GameFinder.findAll()
        const names = games.map(g => g.name || 'unnamed').sort()
        GameFinder.logger.info(`≡ƒôï All games in scene (${names.length}):`, names)
        return names
    }

    // ΓöÇΓöÇ Instance methods (accessed via #current) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    private findByName(gameName: string): GameSceneObject | null {
        const searchTerm = gameName.toLowerCase()
        GameFinder.logger.debug(`≡ƒöì Searching for game by name: "${gameName}"`)
        const result = this.findGame((child) =>
            child.userData?.name?.toLowerCase().includes(searchTerm) ||
            child.name?.toLowerCase().includes(searchTerm)
        )
        if (result) {
            GameFinder.logger.debug(`Γ£à Found: ${result.name} at (${result.position.x.toFixed(2)}, ${result.position.y.toFixed(2)}, ${result.position.z.toFixed(2)})`)
        } else {
            GameFinder.logger.warn(`Γ¥î Not found: "${gameName}"`)
        }
        return result
    }

    private findByAppId(appid: number | string): GameSceneObject | null {
        GameFinder.logger.debug(`≡ƒöì Searching for game by appid: ${appid}`)
        const result = this.findGame((child) => child.userData?.appid === appid)
        if (result) {
            GameFinder.logger.debug(`Γ£à Found: ${result.name} (${result.appid})`)
        } else {
            GameFinder.logger.warn(`Γ¥î Not found: appid ${appid}`)
        }
        return result
    }

    private findAllImpl(): GameSceneObject[] {
        const games: GameSceneObject[] = []
        const instancedGames = this.findInstancedGames()
        games.push(...instancedGames)
        this.scene.traverse((child) => {
            const game = this.extractGameObject(child)
            if (game) games.push(game)
        })
        GameFinder.logger.debug(`≡ƒöì Found ${games.length} game(s) in scene (${instancedGames.length} instanced, ${games.length - instancedGames.length} legacy)`)
        return games
    }

    private findInstancedGames(): GameSceneObject[] {
        const games: GameSceneObject[] = []
        const dataManager = DataManager.getInstance()
        try {
            const artworkMetadata = dataManager.get<Map<number, InstanceMetadata>>(DataKey.InstancedArtworkMetadata)
            if (artworkMetadata) {
                GameFinder.logger.debug(`≡ƒöì Instanced artwork metadata contains ${artworkMetadata.size} game(s)`)
                for (const [instanceIndex, data] of artworkMetadata.entries()) {
                    games.push({
                        name: data.name,
                        appid: data.appid,
                        position: data.position.clone(),
                        mesh: this.scene,
                        instanceIndex,
                        rendererType: 'gpu'
                    })
                }
            }
            const labelMetadata = dataManager.get<Map<number, InstanceMetadata>>(DataKey.InstancedLabelMetadata)
            if (labelMetadata) {
                GameFinder.logger.debug(`≡ƒöì Instanced label metadata contains ${labelMetadata.size} game(s)`)
                for (const [instanceIndex, data] of labelMetadata.entries()) {
                    games.push({
                        name: data.name,
                        position: data.position.clone(),
                        mesh: this.scene,
                        instanceIndex,
                        rendererType: 'label'
                    })
                }
            }
        } catch (error) {
            GameFinder.logger.debug('≡ƒöì Instanced metadata not available:', error)
        }
        return games
    }

    private findGame(predicate: (child: THREE.Object3D) => boolean): GameSceneObject | null {
        const instancedGames = this.findInstancedGames()
        for (const game of instancedGames) {
            const mockChild = {
                userData: { name: game.name, appid: game.appid, isGameBox: true },
                name: game.name
            } as unknown as THREE.Object3D
            if (predicate(mockChild)) return game
        }
        let found: GameSceneObject | null = null
        this.scene.traverse((child) => {
            if (found) return
            if (predicate(child)) found = this.extractGameObject(child)
        })
        return found
    }

    private extractGameObject(child: THREE.Object3D): GameSceneObject | null {
        if (this.isInstancedMeshParent(child)) return null
        if (child.userData?.isGameBox) {
            return {
                name: child.userData.name,
                appid: child.userData.appid,
                position: child.position.clone(),
                mesh: child,
                rendererType: 'gpu'
            }
        }
        if (child.name?.includes('game-')) {
            return {
                name: child.userData?.name ?? child.name,
                appid: child.userData?.appid,
                position: child.position.clone(),
                mesh: child,
                rendererType: 'legacy'
            }
        }
        if (child.userData?.isLabel && child.userData?.name) {
            return {
                name: child.userData.name,
                appid: child.userData.appid,
                position: child.position.clone(),
                mesh: child,
                rendererType: 'label'
            }
        }
        return null
    }

    private isInstancedMeshParent(child: THREE.Object3D): boolean {
        return child.name === INSTANCED_LABEL_MESH_NAME ||
               child.name === LOD_ARTWORK_MESH_NAME
    }
}

export function initializeGameFinderOnStart(): void {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ;(window as any).findGame = (identifier: string | number) => GameFinder.find(identifier)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ;(window as any).findAllGames = () => GameFinder.findAll()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ;(window as any).nameAllGames = () => GameFinder.listAllGameNames()
}

EventManager.getInstance().registerEventHandler(GameEventTypes.Start, initializeGameFinderOnStart)

/**
 * TD: raf-loop-migration
 * Game Spotlight ΓÇö click-to-highlight system for games in the scene.
 * Also exposed to the browser console for manual debugging:
 *   window.spotlightGame("UNLOVED")
 *   window.spotlightGame(["Psychonauts", "Half Life: Alyx"])
 *   window.spotlightGame(611500) // by appid
 *   window.clearSpotlights()
 */

import * as THREE from 'three'
import { GameFinder } from './GameFinder'
import { LightRegistry } from '../lighting/LightRegistry'
import { EventManager } from '../core/EventManager'
import { GameEventTypes } from '../types/InteractionEvents'
import vertexShader from './shaders/spotlight-beam.vert?raw'
import fragmentShader from './shaders/spotlight-beam.frag?raw'

export interface SpotlightTarget {
    name?: string
    appid?: number | string
    position?: THREE.Vector3
    mesh?: THREE.Object3D
}

export class GameSpotlight {
    private static instance: GameSpotlight | null = null

    static getInstance(): GameSpotlight | null {
        return GameSpotlight.instance
    }

    private spotlights: THREE.SpotLight[] = []
    // Pre-created pool: all spots are in the scene at startup with intensity=0 so
    // materials compile with the full light count during the startup stall, not on
    // first click. visible=true is intentional ΓÇö invisible lights are excluded from
    // Three.js's light hash and won't trigger pre-compilation.
    private spotlightPool: THREE.SpotLight[] = []
    private spotlightGroup: THREE.Group
    private maxSpotlights: number = 1
    private originalLightIntensities: Map<THREE.Light, number> = new Map()
    private scene: THREE.Scene | null = null
    private readonly DIM_FACTOR = 0.2 // Dim to 20% of original intensity
    private camera: THREE.Camera | null = null
    private animationFrameId: number | null = null
    private baseIntensities: Map<THREE.SpotLight, number> = new Map()
    private beamsBySpotlight: Map<THREE.SpotLight, THREE.Mesh> = new Map()
    private static sharedBeamGeometry: THREE.CylinderGeometry | null = null
    private static sharedBeamMaterial: THREE.ShaderMaterial | null = null

    constructor() {
        this.spotlightGroup = new THREE.Group()
        this.spotlightGroup.name = 'diagnostic-spotlights'

        GameSpotlight.instance = this

        try {
            this.scene = GameFinder.getScene()
            this.scene.add(this.spotlightGroup)

            // Pre-create the full pool so shader compilation happens at startup.
            // All pool spotlights are in-scene with intensity=0 ΓÇö they count toward the
            // light hash (forcing MeshStandardMaterial recompile now) but emit nothing.
            for (let i = 0; i < this.maxSpotlights; i++) {
                const spotlight = this.createSpotlight()
                spotlight.intensity = 0
                this.spotlightGroup.add(spotlight)
                this.spotlightGroup.add(spotlight.target)
                const beam = this.beamsBySpotlight.get(spotlight)
                if (beam) beam.visible = false
                this.spotlightPool.push(spotlight)
            }

            // Get camera reference for distance calculations
            this.camera = this.scene.children.find(child => child instanceof THREE.Camera) as THREE.Camera || null
        } catch (error) {
            console.error('Failed to initialize GameSpotlight:', error)
        }
    }

    public spotlight(targets: string | number | Array<string | number>): void {
        if (!this.scene) {
            console.error('Γ¥î [Spotlight] Scene not available')
            return
        }

        const gameObjects = this.findTargetsInScene(targets)

        if (gameObjects.length === 0) {
            this.clear()
        } else {
            this.updateSpotlights(gameObjects)
        }
    }

    private findTargetsInScene(targets: string | number | (string | number)[]) : SpotlightTarget[]{
        const targetArray = Array.isArray(targets) ? targets : [targets]

        const gameObjects: SpotlightTarget[] = []

        for (const target of targetArray) {
            const found = GameFinder.find(target)
            if (found) {
                gameObjects.push(found)
            }
        }
        return gameObjects
    }

    private updateSpotlights(targets: SpotlightTarget[]): void {
        const neededCount = Math.min(targets.length, this.maxSpotlights)

        this.removeExcessSpotlights(neededCount)
        this.createSpotlights(neededCount)

        // Dim store/prop lights when spotlights are active
        this.dimStoreLights()

        // Position spotlights on targets
        for (let i = 0; i < neededCount; i++) {
            const spotlight = this.spotlights[i]
            const target = targets[i]

            this.aimSpotlightAtTarget(target, spotlight)

            // Store base intensity for animation
            this.baseIntensities.set(spotlight, spotlight.intensity)
        }

        // Start animation loop
        this.startAnimation()
    }

    private aimSpotlightAtTarget(target: SpotlightTarget, spotlight: THREE.SpotLight) {
        if (target.position) {
            // Position spotlight above target
            const spotlightHeight = target.position.y + 2 // 2m above game
            spotlight.position.set(
                target.position.x,
                spotlightHeight,
                target.position.z
            )

            const gameBottomY = target.position.y - 0.2 // Bottom of standard game box
            spotlight.target.position.set(
                target.position.x,
                gameBottomY,
                target.position.z
            )

            this.updateBeamHeight(spotlight)

            // visible stays true ΓÇö pool spotlights are always visible=true,
            // we control activation via intensity instead
        }
    }

    private createSpotlights(neededCount: number) {
        while (this.spotlights.length < neededCount) {
            // Activate from pool (already in scene) rather than constructing a new light,
            // so no shader recompilation occurs here.
            const spotlight = this.spotlightPool.pop() ?? this.createSpotlight()
            spotlight.intensity = 3.0
            const beam = this.beamsBySpotlight.get(spotlight)
            if (beam) beam.visible = true
            if (!this.spotlightGroup.children.includes(spotlight)) {
                this.spotlightGroup.add(spotlight)
                this.spotlightGroup.add(spotlight.target)
            }
            this.spotlights.push(spotlight)
        }
    }

    private removeExcessSpotlights(neededCount: number) {
        while (this.spotlights.length > neededCount) {
            this.removeSpotlight()
        }
    }

    private removeSpotlight(): void {
        const spotlight = this.spotlights.pop()
        if (spotlight) {
            spotlight.intensity = 0
            const beam = this.beamsBySpotlight.get(spotlight)
            if (beam) beam.visible = false
            this.spotlightPool.push(spotlight)
            // Stays in scene so the light-count hash remains stable
        }
    }

    private createSpotlight(): THREE.SpotLight {
        const spotlight = new THREE.SpotLight(
            0xfff8e7,      // color: soft warm white
            3.0,           // intensity: higher for visibility
            6,             // distance: 6m range
            Math.PI / 10,  // angle: ~18 degrees for focused beam
            0.5,           // penumbra: 0-1, higher = softer edges
            2              // decay: 2 = physically accurate falloff
        )
        spotlight.castShadow = false // Don't interfere with scene lighting
        spotlight.name = 'diagnostic-spotlight'
        this.createLightBeam(spotlight)
        return spotlight
    }

    private createLightBeam(spotlight: THREE.SpotLight): void {
        // TODO: Coordinate with RoomManager ceiling height instead of hardcoding
        const height = 3.5 // Standard room height (currently hardcoded, could be taller for outdoor scenes)
        const radiusTop = 0.08
        const radiusBottom = 0.12

        if (!GameSpotlight.sharedBeamGeometry) {
            GameSpotlight.sharedBeamGeometry = new THREE.CylinderGeometry(
                radiusTop,
                radiusBottom,
                height,
                24,   // radialSegments - higher = smoother cylinder
                1,    // heightSegments - 1 is sufficient for straight cylinder
                true  // openEnded - no caps for better performance
            )
        }

        if (!GameSpotlight.sharedBeamMaterial) {
            GameSpotlight.sharedBeamMaterial = new THREE.ShaderMaterial({
                uniforms: {
                    color: { value: new THREE.Color(0xfff8e7) },
                    opacity: { value: 0.2 }, // Low opacity for subtle effect
                    gameBottomY: { value: 0.0 }, // Updated per spotlight - where to start fade
                    beamBottomY: { value: 0.0 }  // Floor level (0) - where fade ends
                },
                vertexShader,
                fragmentShader,
                transparent: true,
                side: THREE.DoubleSide,
                blending: THREE.AdditiveBlending,
                depthWrite: false
            })
        }

        const beamMesh = new THREE.Mesh(
            GameSpotlight.sharedBeamGeometry,
            GameSpotlight.sharedBeamMaterial
        )
        beamMesh.name = 'spotlight-beam'
        beamMesh.position.set(0, 0, 0)

        this.spotlightGroup.add(beamMesh)
        this.beamsBySpotlight.set(spotlight, beamMesh)
    }

    private updateBeamHeight(spotlight: THREE.SpotLight): void {
        const beam = this.beamsBySpotlight.get(spotlight)
        if (!beam) return

        beam.position.copy(spotlight.position)
        beam.position.y = 1.75 // Mid-height (3.5m / 2)

        const material = beam.material as THREE.ShaderMaterial
        if (material?.uniforms) {
            material.uniforms.gameBottomY.value = spotlight.target.position.y
            material.uniforms.beamBottomY.value = 0.0
        }
    }

    public clear(): void {
        console.debug(`≡ƒöª [Spotlight] Clearing ${this.spotlights.length} spotlight(s)...`)

        this.stopAnimation()

        while (this.spotlights.length > 0) {
            this.removeSpotlight()
        }

        this.baseIntensities.clear()
        // beamsBySpotlight intentionally NOT cleared ΓÇö pooled spotlights still own their beams
        this.restoreStoreLights()
    }

    private getRectAreaLights(): THREE.RectAreaLight[] {
        return LightRegistry.getInstance().getLightsByType(THREE.RectAreaLight)
    }

    private dimStoreLights(): void {
        const lights = this.getRectAreaLights()

        for (const light of lights) {
            // Store original intensity if not already stored
            if (!this.originalLightIntensities.has(light)) {
                this.originalLightIntensities.set(light, light.intensity)
            }
            // Dim to 20% of original
            const originalIntensity = this.originalLightIntensities.get(light)
            if (originalIntensity !== undefined) {
                light.intensity = originalIntensity * this.DIM_FACTOR
            }
        }

        console.debug(`≡ƒöª [Spotlight] Dimmed ${lights.length} store lights to ${this.DIM_FACTOR * 100}%`)
    }

    private restoreStoreLights(): void {
        if (!this.scene) return

        this.originalLightIntensities.forEach((originalIntensity, light) => {
            light.intensity = originalIntensity
        })

        console.debug(`≡ƒöª [Spotlight] Restored ${this.originalLightIntensities.size} store lights to original intensity`)
        this.originalLightIntensities.clear()
    }

    private startAnimation(): void {
        if (this.animationFrameId !== null) return // Already running

        const animate = () => {
            this.updateSpotlightEffects()
            this.animationFrameId = requestAnimationFrame(animate)
        }

        animate()
    }

    private stopAnimation(): void {
        if (this.animationFrameId !== null) {
            cancelAnimationFrame(this.animationFrameId)
            this.animationFrameId = null
        }
    }

    private updateSpotlightEffects(): void {
        if (!this.camera || this.spotlights.length === 0) return

        const time = Date.now() * 0.001 // Convert to seconds

        for (const spotlight of this.spotlights) {
            const baseIntensity = this.baseIntensities.get(spotlight)
            if (baseIntensity === undefined) continue

            // Calculate distance from camera to spotlight
            const distance = this.camera.position.distanceTo(spotlight.position)

            // Distance-based intensity scaling
            // Close (0-5m): 2.0x base, Far (15m+): 5.0x base
            const minDistance = 3
            const maxDistance = 15
            const minIntensityMultiplier = 2.0
            const maxIntensityMultiplier = 5.0

            const normalizedDistance = Math.max(0, Math.min(1, (distance - minDistance) / (maxDistance - minDistance)))
            const intensityMultiplier = minIntensityMultiplier + (maxIntensityMultiplier - minIntensityMultiplier) * normalizedDistance

            // Pulsing effect - subtle and slow
            // Close: slower pulse (2s period, 8% variation)
            // Far: slightly faster pulse (1.5s period, 12% variation)
            const pulsePeriod = 2.0 - (0.5 * normalizedDistance) // 2.0s close, 1.5s far
            const pulseAmplitude = 0.08 + (0.04 * normalizedDistance) // 8% close, 12% far
            const pulseValue = 1 + pulseAmplitude * Math.sin(time * Math.PI * 2 / pulsePeriod)

            // Apply combined effect
            spotlight.intensity = baseIntensity * intensityMultiplier * pulseValue
        }
    }

    public static disposeSharedResources(): void {
        if (GameSpotlight.sharedBeamGeometry) {
            GameSpotlight.sharedBeamGeometry.dispose()
            GameSpotlight.sharedBeamGeometry = null
        }

        if (GameSpotlight.sharedBeamMaterial) {
            GameSpotlight.sharedBeamMaterial.dispose()
            GameSpotlight.sharedBeamMaterial = null
        }
    }

}

export function initializeGameSpotlightOnStart(): void {
    // TODO: move construction to before buildScene() in SteamBrickAndMortarApp so that
    // pool SpotLights exist before room MeshStandardMaterials first render. That way
    // materials compile once with the full light count instead of recompiling at startup.
    const instance = GameSpotlight.getInstance() ?? new GameSpotlight()

    // @ts-ignore - Intentionally adding to window for debugging
    window.spotlightGame = (target: string | number | Array<string | number>) => {
        instance.spotlight(target)
    }

    // @ts-ignore - Intentionally adding to window for debugging
    window.clearSpotlights = () => {
        instance.clear()
    }

    console.debug('≡ƒöª [GameSpotlight] Console functions: spotlightGame(), clearSpotlights()')
}

// Register the named handler with the EventManager
EventManager.getInstance().registerEventHandler(GameEventTypes.Start, initializeGameSpotlightOnStart)

/**
 * GPU Memory Estimator
 * 
 * Estimates GPU/VRAM usage based on Three.js renderer info and known texture allocations.
 * Browser doesn't expose actual VRAM usage, so we calculate based on what we've allocated.
 * 
 * Memory formulas:
 * - Texture: width ├ù height ├ù 4 bytes (RGBA) ├ù mipmap multiplier (~1.33 with mipmaps)
 * - DataArrayTexture: width ├ù height ├ù depth ├ù 4 bytes
 * - InstancedMesh: instances ├ù (16 floats matrix + attributes) ├ù 4 bytes
 * - Geometry: vertices ├ù stride ├ù 4 bytes
 * 
 * ## Known Limitations / TODOs
 * 
 * ### INFORMATION MISSING: LOD Texture Arrays (BIG - main memory hog)
 * - LodArtworkRenderer has textureArrayHigh, textureArrayMid in shader uniforms
 * - These are DataArrayTextures not attached to standard material properties
 * - POSSIBLY OBTAIN BY: Query window.lodArtworkRenderer.getMemoryStats() directly
 * - POSSIBLY OBTAIN BY: Add a registry pattern where renderers register their textures
 * 
 * ### INFORMATION MISSING: Geometry buffer sizes
 * - Currently using placeholder: geometryCount * 1000 bytes
 * - POSSIBLY OBTAIN BY: geometry.attributes.position.count * stride * 4
 * - POSSIBLY OBTAIN BY: Sum all BufferAttribute.array.byteLength on each geometry
 * 
 * ### INFORMATION MISSING: InstancedMesh custom attributes
 * - Only counting instanceMatrix (64 bytes/instance)
 * - Missing: lodLevel (4), textureIndex (4), highTextureSlot (4) = 12+ bytes/instance
 * - POSSIBLY OBTAIN BY: Iterate geometry.attributes and sum instanced ones
 * 
 * ### INFORMATION MISSING: Environment maps, render targets
 * - scene.environment, scene.background if texture
 * - Any WebGLRenderTarget used for effects
 * - POSSIBLY OBTAIN BY: Check scene.environment, renderer internal state
 * 
 * ### INFORMATION MISSING: GPU driver overhead
 * - Actual VRAM includes alignment, metadata, command buffers
 * - Typically 10-20% overhead on top of raw texture data
 * - POSSIBLY OBTAIN BY: Apply multiplier (configurable) to final estimate
 * 
 * ## Expected Output (with ~800 games loaded, LOD atlas enabled)
 * 
 * | Component | Expected Size |
 * |-----------|---------------|
 * | HIGH texture array (300├ù450├ù128) | ~66 MB |
 * | MID texture array (128├ù128├ù800) | ~52 MB |
 * | InstancedMesh buffers | ~5 MB |
 * | Shelf/room geometry | ~10 MB |
 * | Misc textures (procedural, UI) | ~20 MB |
 * | **Total expected** | **~150 MB** |
 * 
 * If this estimator reports significantly less, it's missing data sources.
 */

import * as THREE from 'three'
import { DataManager } from '../core/data/DataManager'
import { DataKey } from '../core/data/DataTypes'

export interface GpuMemoryBreakdown {
    textures: {
        count: number
        estimatedBytes: number
        details: TextureMemoryDetail[]
    }
    geometries: {
        count: number
        estimatedBytes: number
    }
    instancedMeshes: {
        count: number
        estimatedBytes: number
        details: InstancedMeshDetail[]
    }
    totalEstimatedBytes: number
    totalEstimatedMB: number
    warning?: string
}

export interface TextureMemoryDetail {
    name: string
    type: string
    dimensions: string
    bytes: number
}

export interface InstancedMeshDetail {
    name: string
    maxInstances: number
    activeInstances: number
    bytes: number
}

export class GpuMemoryEstimator {
    private static readonly MIPMAP_MULTIPLIER = 1.33
    private static readonly BYTES_PER_FLOAT = 4
    private static readonly MATRIX4_FLOATS = 16

    static estimate(renderer?: THREE.WebGLRenderer): GpuMemoryBreakdown {
        const dataManager = DataManager.getInstance()
        const scene = dataManager.get<THREE.Scene>(DataKey.MainScene)

        const textureDetails: TextureMemoryDetail[] = []
        const instancedDetails: InstancedMeshDetail[] = []

        let textureBytes = 0
        let geometryBytes: number
        let instancedBytes = 0

        // Get renderer info for counts
        // Note: If renderer not passed, geometry/texture COUNTS will be 0
        // but texture SIZES are still calculated from scene traversal and LOD stats
        const info = renderer?.info
        const textureCount = info?.memory?.textures ?? 0
        const geometryCount = info?.memory?.geometries ?? 0

        // =================================================================
        // PRIORITY: Get registered memory consumers
        // Components self-register their GPU memory usage with DataManager.addMemoryConsumer()
        // This is the primary source of truth for large allocations like LOD texture arrays
        // =================================================================
        const registeredNames = this.collectRegisteredMemoryConsumers(textureDetails)

        // Traverse scene to find textures and instanced meshes
        if (scene) {
            scene.traverse((object) => {
                // Check for InstancedMesh
                if (object instanceof THREE.InstancedMesh) {
                    const mesh = object as THREE.InstancedMesh
                    const maxCount = mesh.instanceMatrix.count / 16
                    const activeCount = mesh.count

                    // Matrix4 per instance + color attribute if present
                    // TODO: Also count custom instanced attributes (lodLevel, textureIndex, etc.)
                    const bytesPerInstance = this.MATRIX4_FLOATS * this.BYTES_PER_FLOAT
                    const bytes = maxCount * bytesPerInstance

                    instancedDetails.push({
                        name: mesh.name || 'unnamed',
                        maxInstances: maxCount,
                        activeInstances: activeCount,
                        bytes
                    })
                    instancedBytes += bytes
                }

                // Check for materials with textures
                if (object instanceof THREE.Mesh) {
                    const materials = Array.isArray(object.material) ? object.material : [object.material]
                    for (const mat of materials) {
                        if (mat instanceof THREE.MeshStandardMaterial || mat instanceof THREE.ShaderMaterial) {
                            this.collectTexturesFromMaterial(mat, textureDetails, registeredNames)
                        }
                    }
                }
            })
        }

        // Calculate texture bytes from collected details
        for (const detail of textureDetails) {
            textureBytes += detail.bytes
        }

        // Estimate geometry bytes (rough: 100 bytes per vertex average)
        // TODO: Calculate actual buffer sizes from geometry.attributes
        geometryBytes = geometryCount * 1000 // Very rough estimate

        const totalBytes = textureBytes + geometryBytes + instancedBytes

        // Warning threshold: 1GB
        const warning = totalBytes > 1024 * 1024 * 1024 
            ? `ΓÜá∩╕Å High VRAM usage estimated: ${(totalBytes / (1024 * 1024)).toFixed(0)} MB`
            : undefined

        return {
            textures: {
                count: textureCount,
                estimatedBytes: textureBytes,
                details: textureDetails
            },
            geometries: {
                count: geometryCount,
                estimatedBytes: geometryBytes
            },
            instancedMeshes: {
                count: instancedDetails.length,
                estimatedBytes: instancedBytes,
                details: instancedDetails
            },
            totalEstimatedBytes: totalBytes,
            totalEstimatedMB: totalBytes / (1024 * 1024),
            warning
        }
    }

    /**
     * Collect registered memory consumers from DataManager
     * Components self-register their GPU memory usage with DataManager.addMemoryConsumer()
     * This is the primary source of truth for large allocations like LOD texture arrays
     */
    private static collectRegisteredMemoryConsumers(details: TextureMemoryDetail[]): Set<string> {
        const registeredNames = new Set<string>()

        const dataManager = DataManager.getInstance()
        const consumers = dataManager.getMemoryConsumption()

        for (const [name, megabytes] of consumers) {
            const bytes = megabytes * 1024 * 1024

            registeredNames.add(name)

            details.push({
                name: `Registered/${name}`,
                type: 'registered',
                dimensions: `${megabytes} MB`,
                bytes
            })
        }

        if (consumers.size === 0) {
            details.push({
                name: 'No registered consumers',
                type: 'info',
                dimensions: 'N/A',
                bytes: 0
            })
        }

        return registeredNames
    }

    private static collectTexturesFromMaterial(
        material: THREE.Material, 
        details: TextureMemoryDetail[],
        skipDimensions: Set<string> = new Set()
    ): void {
        const addTexture = (tex: THREE.Texture | null, name: string) => {
            if (!tex) return

            // Skip duplicates (same texture referenced multiple times)
            if (details.some(d => d.name === name)) return

            let bytes = 0
            let dimensions = ''
            let type = 'Texture'

            if (tex instanceof THREE.DataArrayTexture) {
                type = 'DataArrayTexture'
                const width = tex.image?.width ?? 512
                const height = tex.image?.height ?? 512
                const depth = tex.image?.depth ?? 1
                bytes = width * height * depth * 4 // RGBA
                dimensions = `${width}├ù${height}├ù${depth}`

                // Skip if this matches a LOD texture we already counted
                if (skipDimensions.has(dimensions)) {
                    return
                }
            } else if (tex.image) {
                const img = tex.image as { width?: number; height?: number }
                const width = img.width ?? 512
                const height = img.height ?? 512
                // Include mipmap overhead
                bytes = Math.round(width * height * 4 * this.MIPMAP_MULTIPLIER)
                dimensions = `${width}├ù${height}`
            }

            details.push({ name, type, dimensions, bytes })
        }

        // Check standard material textures
        if (material instanceof THREE.MeshStandardMaterial) {
            addTexture(material.map, `${material.name || 'mat'}.map`)
            addTexture(material.normalMap, `${material.name || 'mat'}.normalMap`)
            addTexture(material.roughnessMap, `${material.name || 'mat'}.roughnessMap`)
            addTexture(material.metalnessMap, `${material.name || 'mat'}.metalnessMap`)
            addTexture(material.aoMap, `${material.name || 'mat'}.aoMap`)
        }

        // Check shader material uniforms for regular textures only
        // Skip DataArrayTextures - those should be registered via DataManager.addMemoryConsumption()
        if (material instanceof THREE.ShaderMaterial && material.uniforms) {
            for (const [key, uniform] of Object.entries(material.uniforms)) {
                if (uniform.value instanceof THREE.Texture && 
                    !(uniform.value instanceof THREE.DataArrayTexture)) {
                    addTexture(uniform.value, `${material.name || 'shader'}.${key}`)
                }
            }
        }
    }

    /**
     * Log a formatted memory report to console
     */
    static logReport(renderer?: THREE.WebGLRenderer): void {
        const breakdown = this.estimate(renderer)

        console.group('≡ƒÄ« GPU Memory Estimate')

        if (breakdown.warning) {
            console.warn(breakdown.warning)
        }

        console.log(`≡ƒôè Total: ${breakdown.totalEstimatedMB.toFixed(1)} MB estimated VRAM`)

        console.group('≡ƒû╝∩╕Å Textures')
        console.log(`Count: ${breakdown.textures.count}`)
        console.log(`Estimated: ${(breakdown.textures.estimatedBytes / (1024 * 1024)).toFixed(1)} MB`)
        if (breakdown.textures.details.length > 0) {
            console.table(breakdown.textures.details.map(d => ({
                name: d.name,
                type: d.type,
                size: d.dimensions,
                MB: (d.bytes / (1024 * 1024)).toFixed(2)
            })))
        }
        console.groupEnd()

        console.group('≡ƒôª Instanced Meshes')
        console.log(`Count: ${breakdown.instancedMeshes.count}`)
        console.log(`Estimated: ${(breakdown.instancedMeshes.estimatedBytes / (1024 * 1024)).toFixed(1)} MB`)
        if (breakdown.instancedMeshes.details.length > 0) {
            console.table(breakdown.instancedMeshes.details.map(d => ({
                name: d.name,
                max: d.maxInstances,
                active: d.activeInstances,
                MB: (d.bytes / (1024 * 1024)).toFixed(2)
            })))
        }
        console.groupEnd()

        console.group('≡ƒôÉ Geometries')
        console.log(`Count: ${breakdown.geometries.count}`)
        console.log(`Estimated: ${(breakdown.geometries.estimatedBytes / (1024 * 1024)).toFixed(1)} MB`)
        console.groupEnd()

        console.groupEnd()
    }
}

// Expose globally for debugging
if (typeof window !== 'undefined') {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any).GpuMemoryEstimator = GpuMemoryEstimator
}

/**
 * Zero-Overhead Render Loop Diagnostics
 * 
 * This module uses RenderLoopRegistry's instrumentation hook to provide
 * per-frame timing diagnostics. The registry owns the iteration over callbacks,
 * keeping its internal structure encapsulated.
 * 
 * - If diagnostics disabled: No instrumentation set, zero overhead
 * - If diagnostics enabled: Wrapper with timing, ~0.1ms overhead per frame
 * 
 * Usage:
 *   // At app startup, BEFORE render loop starts:
 *   RenderLoopDiagnostics.initialize({ enabled: true, logInterval: 60 })
 */

import { RenderLoopRegistry } from '../scene/RenderLoopRegistry'
import type { RenderLoopCallback } from '../scene/RenderLoopRegistry'

export interface DiagnosticsConfig {
    /** Enable diagnostics (default: false for production) */
    enabled: boolean
    /** Log frame stats every N frames (default: 60 = ~1 second) */
    logInterval?: number
    /** Warn if frame time exceeds this (ms, default: 16.67 for 60fps) */
    frameTimeWarnThreshold?: number
    /** Warn if any callback exceeds this (ms, default: 5) */
    callbackTimeWarnThreshold?: number
}

interface FrameStats {
    frameCount: number
    totalFrameTime: number
    maxFrameTime: number
    callbackTimes: Map<string, number[]>
    frameStartTime: number
}

export class RenderLoopDiagnostics {
    private static isInitialized = false
    private static config: Required<DiagnosticsConfig> = {
        enabled: false,
        logInterval: 60,
        frameTimeWarnThreshold: 16.67,
        callbackTimeWarnThreshold: 5
    }

    private static stats: FrameStats = {
        frameCount: 0,
        totalFrameTime: 0,
        maxFrameTime: 0,
        callbackTimes: new Map(),
        frameStartTime: 0
    }

    private static isFirstCallbackInFrame = true

    /**
     * Initialize diagnostics - call ONCE at app startup, before render loop starts
     */
    public static initialize(config?: Partial<DiagnosticsConfig>): void {
        if (this.isInitialized) {
            console.warn('≡ƒöº [RenderLoopDiagnostics] Already initialized, ignoring')
            return
        }

        this.config = { ...this.config, ...config }

        if (!this.config.enabled) {

            this.isInitialized = true
            return
        }

        const registry = RenderLoopRegistry.getInstance()

        // Set instrumentation wrapper - registry owns the iteration
        registry.setInstrumentation(this.instrumentCallback.bind(this))


        this.isInitialized = true
    }

    /**
     * Instrumentation wrapper called by RenderLoopRegistry for each callback
     */
    private static instrumentCallback(
        id: string,
        callback: RenderLoopCallback,
        now: number,
        deltaTime: number
    ): void {
        // Track frame start on first callback
        if (this.isFirstCallbackInFrame) {
            this.stats.frameStartTime = performance.now()
            this.isFirstCallbackInFrame = false
        }

        const callbackStart = performance.now()
        try {
            callback(now, deltaTime)
        } catch (error) {
            console.error(`≡ƒöº [RenderLoopDiagnostics] Error in callback '${id}':`, error)
        }
        const callbackTime = performance.now() - callbackStart

        // Track per-callback times
        if (!this.stats.callbackTimes.has(id)) {
            this.stats.callbackTimes.set(id, [])
        }
        const times = this.stats.callbackTimes.get(id)
        if (times) {
            times.push(callbackTime)
            if (times.length > this.config.logInterval) {
                times.shift()
            }
        }

        // Warn if callback is slow
        if (callbackTime > this.config.callbackTimeWarnThreshold) {
            console.warn(`ΓÜá∩╕Å [RenderLoopDiagnostics] Slow callback '${id}': ${callbackTime.toFixed(2)}ms`)
        }
    }

    /**
     * Called at end of each frame to finalize stats
     * Must be called by the render loop after executeAll()
     */
    public static endFrame(): void {
        if (!this.config.enabled || this.isFirstCallbackInFrame) {
            return // No callbacks executed this frame
        }

        const frameTime = performance.now() - this.stats.frameStartTime
        this.stats.frameCount++
        this.stats.totalFrameTime += frameTime
        this.stats.maxFrameTime = Math.max(this.stats.maxFrameTime, frameTime)
        this.isFirstCallbackInFrame = true // Reset for next frame

        // Warn if frame is slow
        if (frameTime > this.config.frameTimeWarnThreshold) {
            console.warn(`ΓÜá∩╕Å [RenderLoopDiagnostics] Slow frame: ${frameTime.toFixed(2)}ms`)
        }

        // Periodic logging
        if (this.stats.frameCount % this.config.logInterval === 0) {
            this.logStats()
        }
    }

    private static logStats(): void {
        const avgFrameTime = this.stats.totalFrameTime / this.config.logInterval

        // Only log if there's something noteworthy (>1ms avg or any callback >1ms)
        const hasSlowCallbacks = Array.from(this.stats.callbackTimes.values()).some(times => {
            const avg = times.reduce((a, b) => a + b, 0) / times.length
            return avg >= 1.0
        })

        if (avgFrameTime < 1.0 && !hasSlowCallbacks) {
            // Reset and skip logging - everything is fast
            this.stats.totalFrameTime = 0
            this.stats.maxFrameTime = 0
            return
        }

        console.log(`≡ƒôè [RenderLoopDiagnostics] Frame Stats (last ${this.config.logInterval} frames):`)
        console.log(`   Avg: ${avgFrameTime.toFixed(2)}ms, Max: ${this.stats.maxFrameTime.toFixed(2)}ms`)

        // Log per-callback averages (only those >= 1ms)
        for (const [id, times] of this.stats.callbackTimes.entries()) {
            const avg = times.reduce((a, b) => a + b, 0) / times.length
            const max = Math.max(...times)
            if (avg >= 1.0 || max >= 1.0) {
                console.log(`   ${id}: avg ${avg.toFixed(2)}ms, max ${max.toFixed(2)}ms`)
            }
        }

        // Reset for next interval
        this.stats.totalFrameTime = 0
        this.stats.maxFrameTime = 0
    }

    /**
     * Get current stats (for UI display or testing)
     */
    public static getStats(): Readonly<Omit<FrameStats, 'frameStartTime'>> {
        return { 
            frameCount: this.stats.frameCount,
            totalFrameTime: this.stats.totalFrameTime,
            maxFrameTime: this.stats.maxFrameTime,
            callbackTimes: new Map(this.stats.callbackTimes) 
        }
    }

    /**
     * Disable diagnostics and remove instrumentation
     */
    public static disable(): void {
        if (!this.config.enabled) {
            return
        }

        const registry = RenderLoopRegistry.getInstance()
        registry.setInstrumentation(null)
        this.config.enabled = false

    }

    /**
     * Reset for testing
     */
    public static reset(): void {
        const registry = RenderLoopRegistry.getInstance()
        registry.setInstrumentation(null)
        this.isInitialized = false
        this.config = {
            enabled: false,
            logInterval: 60,
            frameTimeWarnThreshold: 16.67,
            callbackTimeWarnThreshold: 5
        }
        this.stats = {
            frameCount: 0,
            totalFrameTime: 0,
            maxFrameTime: 0,
            callbackTimes: new Map(),
            frameStartTime: 0
        }
    }
}

/**
 * SceneManagerDebug ΓÇö drop-in replacement for SceneManager with debug capabilities.
 *
 * Follows the same pattern as ThreeWebGLRendererDebug: extend the production class,
 * swap the constructor call site (SteamBrickAndMortarApp), no other changes needed.
 *
 * Exposes on window:
 *   window.sceneManager.drawCallReport() ΓåÆ DrawCallReport
 */

import * as THREE from 'three'
import { SceneManager, type SceneManagerOptions } from '../scene/SceneManager'

export interface DrawCallObject {
    name: string
    type: 'InstancedMesh' | 'Mesh' | 'Line' | 'Points'
    visible: boolean
    instanceCount: number | null
    triangles: number
    material: string | null
}

export interface DrawCallReport {
    timestamp: string
    renderer: {
        calls: number
        triangles: number
        points: number
        lines: number
        programs: number
        geometries: number
        textures: number
    } | null
    objects: DrawCallObject[]
}

export class SceneManagerDebug extends SceneManager {
    constructor(options: SceneManagerOptions = {}) {
        super(options)
        this.attachToWindow()
    }

    /**
     * Walk the scene graph and extract draw call info from renderer.info.
     * Returns a snapshot ΓÇö call once after scene is ready for a stable report.
     */
    drawCallReport(): DrawCallReport {
        const renderer = this.getRenderer()
        const scene = this.getScene()
        const rendererInfo = renderer.info

        const objects: DrawCallObject[] = []
        scene.traverse((obj: THREE.Object3D) => {
            const mesh = obj as THREE.Mesh | THREE.InstancedMesh | THREE.Line | THREE.Points
            const isMesh = (mesh as THREE.Mesh).isMesh
            const isInstanced = (mesh as THREE.InstancedMesh).isInstancedMesh
            const isLine = (mesh as THREE.Line).isLine
            const isPoints = (mesh as THREE.Points).isPoints

            if (!isMesh && !isLine && !isPoints) return

            const geo = mesh.geometry as THREE.BufferGeometry | undefined
            const mat = (mesh as THREE.Mesh).material as THREE.Material | undefined
            const rawTriangles = geo?.index
                ? geo.index.count / 3
                : (geo?.attributes?.position?.count ?? 0) / 3
            const instanceCount = isInstanced ? (mesh as THREE.InstancedMesh).count : null
            const triangles = Math.round(rawTriangles * (instanceCount ?? 1))

            objects.push({
                name: mesh.name || '(unnamed)',
                type: isInstanced ? 'InstancedMesh' : isLine ? 'Line' : isPoints ? 'Points' : 'Mesh',
                visible: mesh.visible,
                instanceCount,
                triangles,
                material: mat?.type ?? null,
            })
        })

        return {
            timestamp: new Date().toISOString(),
            renderer: {
                calls: rendererInfo.render?.calls ?? 0,
                triangles: rendererInfo.render?.triangles ?? 0,
                points: rendererInfo.render?.points ?? 0,
                lines: rendererInfo.render?.lines ?? 0,
                programs: rendererInfo.programs?.length ?? 0,
                geometries: rendererInfo.memory?.geometries ?? 0,
                textures: rendererInfo.memory?.textures ?? 0,
            },
            objects,
        }
    }

    private attachToWindow(): void {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        ;(window as any).sceneManager = {
            drawCallReport: () => this.drawCallReport(),
        }
    }
}

/**
 * ThreeWebGLRendererDebug ΓÇö instrumented WebGLRenderer
 *
 * Drop-in replacement for THREE.WebGLRenderer during development / debug builds.
 * Swap the construction site; everything else stays the same since this is a subclass.
 *
 * Instruments:
 *   - gl.linkProgram hook (ctor): logs every GLSL program compile with material type,
 *     light counts, feature flags, and a readable stack trace (useful in Vite dev builds
 *     where Three.js is unminified)
 *   - render() override: warns when a frame exceeds the slow-frame threshold
 *
 * NOTE ΓÇö renderer.compileAsync() and KHR_parallel_shader_compile:
 *   When using compileAsync() for pre-warming shaders, the non-blocking behaviour
 *   depends on the KHR_parallel_shader_compile WebGL extension. Without it
 *   (older GPUs / certain mobile drivers), compileAsync() still blocks synchronously
 *   while programs link - the call resolves, but only after all the work is done on the
 *   main thread. If a user reports that startup stalls persist on their hardware, check:
 *     gl.getExtension('KHR_parallel_shader_compile')
 *   and consider falling back to the staggered-scene.add() approach (spread adds across
 *   frames via FrameBudgetScheduler) when the extension is absent.
 */

import * as THREE from 'three'
import { Logger } from '../utils/Logger'

const SLOW_FRAME_THRESHOLD_MS = 100

export class ThreeWebGLRendererDebug extends THREE.WebGLRenderer {
    private static readonly logger = Logger.createLogFunctions(ThreeWebGLRendererDebug.name)
    constructor(parameters?: THREE.WebGLRendererParameters) {
        super(parameters)
        this.installShaderCompileLogger()
    }

    /**
     * Timed render ΓÇö warns when a frame render exceeds the slow-frame threshold.
     * Synchronous shader compilation (new material ├ù light-config pairs) shows up here.
     */
    override render(scene: THREE.Object3D, camera: THREE.Camera): void {
        const start = performance.now()
        super.render(scene, camera)
        const elapsed = performance.now() - start
        if (elapsed > SLOW_FRAME_THRESHOLD_MS) {
            ThreeWebGLRendererDebug.logger.warn(`≡ƒÉî Slow frame: render() took ${elapsed.toFixed(1)}ms (frame budget ~16ms)`)
        }
    }

    /**
     * Patches gl.linkProgram to log every GLSL program compilation.
     * Each call = one unique (material type ├ù light config ├ù feature flags) triple.
     * Called once from the constructor ΓÇö no overhead after startup when all
     * programs have been compiled and the driver cache is warm.
     */
    private installShaderCompileLogger(): void {
        const gl = this.getContext()
        const originalLinkProgram = gl.linkProgram.bind(gl)
        let programCount = 0

        gl.linkProgram = (program: WebGLProgram) => {
            programCount++

            // Both vert and frag carry the same #define block; read whichever has it
            const shaders = gl.getAttachedShaders(program) ?? []
            const allDefines: string[] = []
            for (const shader of shaders) {
                const src = gl.getShaderSource(shader) ?? ''

                // Material type ΓÇö Three.js injects exactly one per program
                const matType = src.match(/#define (STANDARD|PHYSICAL|PHONG|TOON|NORMAL|DEPTH|ALPHATEST|POINTS|DASHED)\b/)?.[1]
                if (matType) allDefines.push(matType)

                // Light counts ΓÇö only non-zero ones affect the hash
                for (const key of ['NUM_DIR_LIGHTS', 'NUM_POINT_LIGHTS', 'NUM_SPOT_LIGHTS', 'NUM_RECT_AREA_LIGHTS', 'NUM_HEMI_LIGHTS']) {
                    const m = src.match(new RegExp(`#define ${key} (\\d+)`))
                    if (m && m[1] !== '0') allDefines.push(`${key}=${m[1]}`)
                }

                // Feature flags ΓÇö each unique combo produces a distinct compiled program
                for (const flag of ['USE_MAP', 'USE_NORMALMAP', 'USE_ROUGHNESSMAP', 'USE_ENVMAP', 'USE_INSTANCING', 'USE_SKINNING']) {
                    if (src.includes(`#define ${flag}`)) allDefines.push(flag.replace('USE_', ''))
                }
            }

            const summary = [...new Set(allDefines)].join(' | ') || '(custom/unknown)'

            // Stack trace: 'acquireProgram' confirms the Three.js path that triggered this.
            // In Vite dev mode Three.js is unminified so function names are readable.
            const stack = new Error().stack ?? ''
            const relevantFrames = stack.split('\n')
                .slice(1, 8)
                .map(f => f.trim().replace(/^at /, ''))
                .join(' ΓåÆ ')

            ThreeWebGLRendererDebug.logger.debug(`≡ƒöº [ShaderCompile] Program #${programCount}: ${summary}\n  ${relevantFrames}`)

            return originalLinkProgram(program)
        }
    }
}

import * as THREE from 'three'
import {
    ManagedAmbientLight,
    ManagedDirectionalLight,
    ManagedPointLight,
    ManagedSpotLight,
    ManagedRectAreaLight,
    ManagedHemisphereLight
} from './ManagedLights'
import { EventManager } from '../core/EventManager'
import { LightingEventTypes, type PointLightRequestEvent } from '../types/LightingEvents'

export interface LightFactoryOptions {
    name?: string
    addToScene?: boolean
    parent?: THREE.Object3D
    position?: THREE.Vector3 | [number, number, number]
}

type ManagedLight = { 
    addToParent(parent: THREE.Object3D, scene: THREE.Scene, name?: string): any
    addToScene(scene: THREE.Scene, name?: string): any
    position: THREE.Vector3
}

export class LightFactory {
    constructor(private scene: THREE.Scene) {
        // Subscribe to PointLightRequested so any system can safely request a point
        // light without reaching into the scene directly (which would bypass the
        // lighting system and cause uncontrolled shadow map recalculations).
        EventManager.getInstance().registerEventHandler(
            LightingEventTypes.PointLightRequested,
            (event: CustomEvent<PointLightRequestEvent>) => {
                const { color, intensity, distance, position, name, parent } = event.detail
                this.createPointLight(color, intensity, distance, undefined, {
                    name: name ?? 'requested-point-light',
                    addToScene: !parent,
                    parent,
                    position,
                })
            }
        )
    }

    private add<T extends ManagedLight>(light: T, options: LightFactoryOptions): T {
        if (options.position) {
            if (Array.isArray(options.position)) {
                light.position.set(...options.position)
            } else {
                light.position.copy(options.position)
            }
        }

        if (options.parent) {
            light.addToParent(options.parent, this.scene, options.name)
        } else if (options.addToScene !== false) {
            light.addToScene(this.scene, options.name)
        }
        return light
    }

    createAmbientLight(color?: THREE.ColorRepresentation, intensity?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedAmbientLight(color, intensity), options)
    }

    createDirectionalLight(color?: THREE.ColorRepresentation, intensity?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedDirectionalLight(color, intensity), options)
    }

    createPointLight(color?: THREE.ColorRepresentation, intensity?: number, distance?: number, decay?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedPointLight(color, intensity, distance, decay), options)
    }

    createSpotLight(color?: THREE.ColorRepresentation, intensity?: number, distance?: number, angle?: number, penumbra?: number, decay?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedSpotLight(color, intensity, distance, angle, penumbra, decay), options)
    }

    createRectAreaLight(color?: THREE.ColorRepresentation, intensity?: number, width?: number, height?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedRectAreaLight(color, intensity, width, height), options)
    }

    createHemisphereLight(skyColor?: THREE.ColorRepresentation, groundColor?: THREE.ColorRepresentation, intensity?: number, options: LightFactoryOptions = {}) {
        return this.add(new ManagedHemisphereLight(skyColor, groundColor, intensity), options)
    }

    updateScene(scene: THREE.Scene) {
        this.scene = scene
    }
}

/**
 * Light Registry - Central inventory for scene lights
 * 
 * Provides O(1) lookups for lights and attached geometry without scene traversal.
 * Attached geometry is any visual object associated with a light (debug helpers,
 * indicators, etc.) - the registry doesn't care what it's for.
 * 
 * TODO: Consider migrating to light.userData.attachedGeometry pattern
 * to eliminate this registry entirely.
 */

import * as THREE from 'three'
import { Logger } from '../utils/Logger'

interface LightEntry {
    type: string
    attachedGeometry?: THREE.Object3D
}

export class LightRegistry {
    private static instance: LightRegistry | null = null
    public static logger = Logger.createLogFunctions(LightRegistry.name)

    private lights: Map<THREE.Light, LightEntry> = new Map()
    private attachedGeometry: Map<THREE.Light, THREE.Object3D> = new Map()

    private constructor() {}

    public static getInstance(): LightRegistry {
        if (!LightRegistry.instance) {
            LightRegistry.instance = new LightRegistry()
        }
        return LightRegistry.instance
    }

    public registerLight(light: THREE.Light, options: { source?: string } = {}): void {
        const lightType = light.constructor.name
        this.lights.set(light, { type: lightType })
        LightRegistry.logger.debug(`≡ƒÆí Registered ${lightType}: "${light.name}" (source: ${options.source ?? 'unknown'})`)
    }

    public attachGeometry(light: THREE.Light, geometry: THREE.Object3D): void {
        const entry = this.lights.get(light)
        if (entry) {
            entry.attachedGeometry = geometry
            this.attachedGeometry.set(light, geometry)
            LightRegistry.logger.debug(`≡ƒÆí Attached geometry to "${light.name}"`)
        }
    }

    public getLightsByType<T extends THREE.Light>(lightClass: new (...args: unknown[]) => T): T[] {
        const results: T[] = []
        for (const [light] of this.lights) {
            if (light instanceof lightClass) results.push(light)
        }
        return results
    }

    public getLightsGroupedByType(): Map<string, THREE.Light[]> {
        const groups = new Map<string, THREE.Light[]>()
        for (const [light, entry] of this.lights) {
            if (!groups.has(entry.type)) {
                groups.set(entry.type, [])
            }
            groups.get(entry.type)!.push(light)
        }
        return groups
    }

    public getAttachedGeometry(light: THREE.Light): THREE.Object3D | undefined {
        return this.attachedGeometry.get(light)
    }

    public getAllAttachedGeometry(): THREE.Object3D[] {
        return Array.from(this.attachedGeometry.values())
    }

    public clear(): void {
        this.lights.clear()
        this.attachedGeometry.clear()
        LightRegistry.logger.debug('≡ƒÆí Cleared all registrations')
    }
}

import * as THREE from 'three'
import { EventManager, EventSource } from '../core/EventManager'
import { LightingEventTypes } from '../types/LightingEvents'
import { LightRegistry } from './LightRegistry'

interface IManagedLight {
    addToScene(scene: THREE.Scene, name?: string): this
    addToParent(parent: THREE.Object3D, scene: THREE.Scene, name?: string): this
}

function managedLightMixin<T extends new (...args: any[]) => THREE.Light>(Base: T, lightType: string) {
    return class extends Base implements IManagedLight {
        private eventManager = EventManager.getInstance()

        addToScene(scene: THREE.Scene, name?: string): this {
            if (name) this.name = name
            scene.add(this)
            this.registerAndEmit(scene, this.name)
            return this
        }

        addToParent(parent: THREE.Object3D, scene: THREE.Scene, name?: string): this {
            if (name) this.name = name
            parent.add(this)
            this.registerAndEmit(scene, this.name)
            return this
        }

        private registerAndEmit(scene: THREE.Scene, name?: string): void {
            // Register with central registry (enables O(1) lookups)
            LightRegistry.getInstance().registerLight(this, { source: 'ManagedLight' })

            // Emit event for UI updates
            this.eventManager.emit(LightingEventTypes.Created, {
                light: this,
                scene,
                lightType,
                lightName: name,
                timestamp: Date.now(),
                source: EventSource.ManagedLight
            })
        }
    }
}

export class ManagedAmbientLight extends managedLightMixin(THREE.AmbientLight, 'AmbientLight') {}
export class ManagedDirectionalLight extends managedLightMixin(THREE.DirectionalLight, 'DirectionalLight') {}
export class ManagedPointLight extends managedLightMixin(THREE.PointLight, 'PointLight') {}
export class ManagedSpotLight extends managedLightMixin(THREE.SpotLight, 'SpotLight') {}
export class ManagedRectAreaLight extends managedLightMixin(THREE.RectAreaLight, 'RectAreaLight') {}
export class ManagedHemisphereLight extends managedLightMixin(THREE.HemisphereLight, 'HemisphereLight') {}

/**
 * Steam Brick and Mortar - WebXR Main Entry Point
 * 
 * This is the application entry point that initializes the Steam Brick and Mortar
 * WebXR environment. The actual application logic is handled by the 
 * SteamBrickAndMortarApp orchestrator class.
 */

import './styles/main.css'
import { SteamBrickAndMortarApp } from './core'
import './debug/GameFinder'  // Self-executing on GameStart
import './debug/GameArtworkInspector'  // Self-executing on GameStart

// Track if initialization is already in progress or completed
let isInitializing = false
let isInitialized = false

/**
 * Initialize the Steam Brick and Mortar application
 */
export async function initializeApp(): Promise<void> {
    // Prevent duplicate initialization
    if (isInitializing || isInitialized) {
        console.debug('ΓÜá∩╕Å App initialization already in progress or completed, skipping duplicate attempt')
        return
    }

    isInitializing = true

    try {
        // CoreInit begins in the SteamBrickAndMortarApp constructor; nothing to mark here.



        const app = new SteamBrickAndMortarApp({
            scene: {
                antialias: true
            },
            steam: {
                apiBaseUrl: 'https://steam-api-dev.wehrly.com'
                // maxGames will be determined by AppSettings developmentMode default (20 when dev mode is enabled)
            },
            input: {
                speed: 0.1,
                mouseSensitivity: 0.005
            }
        })

        await app.init()

        // Store app reference globally for debugging
        if (typeof window !== 'undefined') {
            ;(window as typeof window & { steamBrickAndMortarApp: SteamBrickAndMortarApp }).steamBrickAndMortarApp = app
        }

        isInitialized = true

    } catch (error) {
        console.error('≡ƒÆÑ Failed to initialize Steam Brick and Mortar:', error)

        // Show user-friendly error message
        const errorElement = document.getElementById('loading-status')
        if (errorElement) {
            errorElement.textContent = 'Failed to initialize application. Please refresh to try again.'
            errorElement.style.color = '#ff6b6b'
        }

        // Reset flags so user can try again
        isInitializing = false
        isInitialized = false
    } finally {
        isInitializing = false
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', initializeApp)

// Also initialize immediately if DOM is already loaded
if (document.readyState !== 'loading') {
    // DOM is already loaded, initialize immediately
    initializeApp()
}

/**
 * Asset Loader - 3D Asset Loading and Management
 * 
 * Handles:
 * - GLTF model loading
 * - Asset caching
 * - Loading progress tracking
 */

import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'

export interface AssetLoadOptions {
    enableShadows?: boolean
    scale?: number
    position?: THREE.Vector3
    rotation?: THREE.Euler
}

export interface LoadProgress {
    loaded: number
    total: number
    percentage: number
}

export class AssetLoader {
    private gltfLoader: GLTFLoader
    private loadedAssets: Map<string, THREE.Group> = new Map()

    constructor() {
        this.gltfLoader = new GLTFLoader()
    }

    /**
     * Load a GLTF model
     */
    public async loadModel(
        path: string, 
        options: AssetLoadOptions = {},
        onProgress?: (progress: LoadProgress) => void
    ): Promise<THREE.Group> {
        // Check if already loaded
        if (this.loadedAssets.has(path)) {
            console.log(`≡ƒôª Using cached model: ${path}`)
            const cachedModel = this.loadedAssets.get(path)
            if (cachedModel) {
                return cachedModel.clone()
            }
        }

        try {
            console.log(`≡ƒôª Loading model: ${path}`)

            const gltf = await this.gltfLoader.loadAsync(path, (progressEvent) => {
                if (onProgress && progressEvent.total > 0) {
                    const progress: LoadProgress = {
                        loaded: progressEvent.loaded,
                        total: progressEvent.total,
                        percentage: Math.round((progressEvent.loaded / progressEvent.total) * 100)
                    }
                    onProgress(progress)
                }
            })

            const model = gltf.scene

            // Apply options
            if (options.scale !== undefined) {
                model.scale.setScalar(options.scale)
            }

            if (options.position) {
                model.position.copy(options.position)
            }

            if (options.rotation) {
                model.rotation.copy(options.rotation)
            }

            // Enable shadows if requested
            if (options.enableShadows ?? true) {
                this.enableShadowsForModel(model)
            }

            // Cache the original model
            this.loadedAssets.set(path, model.clone())

            console.log(`Γ£à Model loaded successfully: ${path}`)
            return model

        } catch (error) {
            console.error(`Γ¥î Failed to load model: ${path}`, error)
            throw error
        }
    }

    /**
     * Enable shadows for all meshes in a model
     */
    private enableShadowsForModel(model: THREE.Group) {
        model.traverse((child) => {
            if (child instanceof THREE.Mesh) {
                child.castShadow = true
                child.receiveShadow = true
            }
        })
    }

    /**
     * Get cached asset
     */
    public getCachedAsset(path: string): THREE.Group | undefined {
        return this.loadedAssets.get(path)?.clone()
    }

    /**
     * Check if asset is cached
     */
    public isAssetCached(path: string): boolean {
        return this.loadedAssets.has(path)
    }

    /**
     * Clear asset cache
     */
    public clearCache() {
        this.loadedAssets.clear()
        console.log('≡ƒùæ∩╕Å Asset cache cleared')
    }

    /**
     * Get cache statistics
     */
    public getCacheStats() {
        return {
            cachedAssets: this.loadedAssets.size,
            assetPaths: Array.from(this.loadedAssets.keys())
        }
    }

    /**
     * Preload multiple assets
     */
    public async preloadAssets(
        assets: { path: string; options?: AssetLoadOptions }[],
        onProgress?: (current: number, total: number, currentAsset: string) => void
    ): Promise<THREE.Group[]> {
        const loadedModels: THREE.Group[] = []

        for (let i = 0; i < assets.length; i++) {
            const asset = assets[i]

            if (onProgress) {
                onProgress(i, assets.length, asset.path)
            }

            try {
                const model = await this.loadModel(asset.path, asset.options)
                loadedModels.push(model)
            } catch (error) {
                console.warn(`ΓÜá∩╕Å Failed to preload asset: ${asset.path}`, error)
            }
        }

        if (onProgress) {
            onProgress(assets.length, assets.length, 'Complete')
        }

        return loadedModels
    }

    /**
     * Dispose of resources
     */
    public dispose() {
        this.clearCache()
    }
}

/**
 * GpuStorePropsRenderer
 *
 * Lifecycle coordinator for the GPU-instanced store.
 *
 * OWNS:
 * - GpuGameBoxRenderer allocation (deferred until game count is known)
 * - Props group in scene
 *
 * DOES NOT OWN:
 * - Layout math (ΓåÆ ShelfLayoutCoordinator)
 * - Sign placement (ΓåÆ SceneSignManager)
 * - Game sorting (ΓåÆ GameSorter)
 */

import * as THREE from 'three'
import { GpuGameBoxRenderer } from './game-box/GpuGameBoxRenderer'
import type { IStorePropsRenderer, PropsConfig } from './IStorePropsRenderer'

import { EventManager } from '../core/EventManager'
import { GameEventTypes } from '../types/InteractionEvents'
import {
    StorePropsEventTypes,
    type BatchReadyForPlacementEvent,
} from '../types/InteractionEvents'
import { Logger } from '../utils/Logger'
import { PerformanceMonitor, ASYNC_CONTEXT } from '../utils/PerformanceMonitor'
import { BatchCoordinator } from './batch/BatchCoordinator'
import { GameBoxSpawner } from './spawning/GameBoxSpawner'
import { ShelfLayoutCoordinator } from './shelves/ShelfLayoutCoordinator'
import { InstancedShelfRenderer } from './instancing/InstancedShelfRenderer'

export class GpuStorePropsRenderer implements IStorePropsRenderer {
    private static readonly logger = Logger.createLogFunctions(GpuStorePropsRenderer.name)

    private scene: THREE.Scene

    private gameBoxRenderer: GpuGameBoxRenderer | null = null
    private propsGroup: THREE.Group
    private config: PropsConfig = {}

    private static readonly DEFAULT_CONFIG: PropsConfig = Object.freeze({
        enableShelves: true,
        enableGameBoxes: true,
        enableSignage: true,
        performance: Object.freeze({
            maxTextureSize: 1024,
            nearDistance: 2.0,
            farDistance: 10.0,
            frustumCullingEnabled: true,
        })
    })

    private progressiveInitializationPromise: Promise<void> | null = null
    private setupPhaseInitialized = false

    private readonly instancedShelfRenderer: InstancedShelfRenderer
    private readonly shelfLayoutCoordinator: ShelfLayoutCoordinator

    constructor(scene: THREE.Scene) {
        this.scene = scene
        // Owns GamesBatchReady -> BatchReadyForPlacement queueing + completion signaling.
        new BatchCoordinator()

        this.propsGroup = new THREE.Group()
        this.propsGroup.name = 'props-instanced'
        this.scene.add(this.propsGroup)

        this.instancedShelfRenderer = new InstancedShelfRenderer()
        this.shelfLayoutCoordinator = new ShelfLayoutCoordinator()
        // Construct immediately so it's subscribed to BatchReadyForPlacement
        // before any batches can arrive. Previously constructed in setupProps()
        // which could run after batches had already fired, causing all
        // "No pending games" warnings.
        new GameBoxSpawner()

        this.setupEventListeners()
    }

    private setupEventListeners(): void {
        // First batch: allocate game box renderer sized to the library
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.BatchReadyForPlacement,
            this.handleInitialBatch.bind(this)
        )

        // AllBatchesComplete: finalize
        EventManager.getInstance().registerEventHandler(
            GameEventTypes.AllBatchesComplete,
            this.handleAllBatchesComplete.bind(this)
        )

        GpuStorePropsRenderer.logger.debug('Event listeners registered')
    }

    private async handleInitialBatch(event: CustomEvent<BatchReadyForPlacementEvent>): Promise<void> {
        const { totalBatches } = event.detail

        if (!this.progressiveInitializationPromise) {
            this.progressiveInitializationPromise = (async () => {
                const monitor = PerformanceMonitor.start('renderer-initialization', GpuStorePropsRenderer.logger, ASYNC_CONTEXT)
                await this.initializeGameBoxRenderer(totalBatches)
                monitor.end({ totalBatches })
            })()
        }

        await this.progressiveInitializationPromise
    }

    // we know the number of games by the time this happens, and should wire that in instead
    // either through an earlier-raised event, or by re-aligning this one
    private async initializeGameBoxRenderer(totalBatches: number): Promise<void> {
        const estimatedGames = totalBatches * 18
        this.gameBoxRenderer?.dispose()
        this.gameBoxRenderer = new GpuGameBoxRenderer(estimatedGames + 100)
    }

    private handleAllBatchesComplete(): void {
        GpuStorePropsRenderer.logger.debug('Progressive loading complete')
        this.progressiveInitializationPromise = null
    }

    public async setupProps(config: PropsConfig = {}): Promise<void> {
        if (this.setupPhaseInitialized) return

        this.instancedShelfRenderer.initialize().catch(error => {
            console.error('Γ¥î Failed to initialize InstancedShelfRenderer:', error)
        })

        this.setupPhaseInitialized = true
        this.config = { ...GpuStorePropsRenderer.DEFAULT_CONFIG, ...config }
    }

    public async addAtmosphericProps(): Promise<void> {
        console.warn('ΓÜá∩╕Å addAtmosphericProps not implemented')
    }

    public clearProps(): void {
        this.instancedShelfRenderer.reset()

        while (this.propsGroup.children.length > 0) {
            const child = this.propsGroup.children[0]
            this.propsGroup.remove(child)
            if (child instanceof THREE.Mesh) {
                child.geometry?.dispose()
                if (child.material instanceof THREE.Material) {
                    child.material.dispose()
                } else if (Array.isArray(child.material)) {
                    child.material.forEach(m => m.dispose())
                }
            }
        }
    }

    public dispose(): void {
        this.clearProps()
        this.gameBoxRenderer?.dispose()
        this.gameBoxRenderer = null
        this.instancedShelfRenderer.dispose()
        this.shelfLayoutCoordinator.dispose()
        this.scene.remove(this.propsGroup)
        GpuStorePropsRenderer.logger.info('GpuStorePropsRenderer disposed')
    }

    public logMemoryStats(): void {
        this.gameBoxRenderer?.logMemoryStats()
    }
}

/**
 * Store Props Renderer Interface
 * 
 * Common interface for both legacy and GPU StorePropsRenderer implementations.
 * Provides consistent API for rendering interactive store objects and props.
 */

export interface PropsConfig {
    enableShelves?: boolean
    enableGameBoxes?: boolean
    enableSignage?: boolean
    /* TODO: If we're not supporting something (like frustumCullingEnabled),
        we should warn if we find it in a non-default state */
    performance?: {
        maxTextureSize?: number
        nearDistance?: number
        farDistance?: number
        maxActiveTextures?: number
        frustumCullingEnabled?: boolean
    }
}

export interface IStorePropsRenderer {
    /**
     * Set up props with configuration
     */
    setupProps(config?: PropsConfig): Promise<void>

    /**
     * Add atmospheric props (wire racks, dividers, etc.)
     */
    addAtmosphericProps(): Promise<void>

    /**
     * Clear all props from the scene
     */
    clearProps(): void

    /**
     * Dispose of all resources and clean up
     */
    dispose(): void
}

/**
 * Lighting Debug Helper - Visual debugging for light coverage areas
 * 
 * Creates visual indicators showing where lights should be affecting the scene:
 * - Red spheres for point lights
 * - Red cones for spot lights  
 * - Red rectangles for rect area lights
 * - Semi-transparent to see through them
 * 
 * Debug helpers are registered with LightRegistry for O(1) lookups.
 */

import * as THREE from 'three'
import { LightRegistry } from '../lighting/LightRegistry'

export class LightingDebugHelper {
    private debugGroup: THREE.Group
    private scene: THREE.Scene
    private registry: LightRegistry

    constructor(scene: THREE.Scene) {
        this.scene = scene
        this.registry = LightRegistry.getInstance()
        this.debugGroup = new THREE.Group()
        this.debugGroup.name = 'lighting-debug'
        this.scene.add(this.debugGroup)
    }

    /**
     * Add visual debug helper for a point light
     */
    addPointLightHelper(light: THREE.PointLight): void {
        const geometry = new THREE.SphereGeometry(light.distance || 10, 16, 12)
        const material = new THREE.MeshBasicMaterial({
            color: 0xff0000,
            transparent: true,
            opacity: 0.15,
            wireframe: true
        })

        const helper = new THREE.Mesh(geometry, material)
        helper.position.copy(light.position)
        helper.name = `debug-point-${light.name || 'unnamed'}`
        this.debugGroup.add(helper)

        // Register with central registry
        this.registry.attachGeometry(light, helper)

        console.log(`≡ƒö┤ Added point light debug sphere at (${light.position.x.toFixed(1)}, ${light.position.y.toFixed(1)}, ${light.position.z.toFixed(1)}) radius: ${light.distance || 10}`)
    }

    /**
     * Add visual debug helper for a spot light
     */
    addSpotLightHelper(light: THREE.SpotLight): void {
        const distance = light.distance || 15
        const angle = light.angle

        // Create cone geometry for spot light coverage
        const radius = Math.tan(angle) * distance
        const geometry = new THREE.ConeGeometry(radius, distance, 16, 1, true)
        const material = new THREE.MeshBasicMaterial({
            color: 0xff0000,
            transparent: true,
            opacity: 0.15,
            wireframe: true,
            side: THREE.DoubleSide
        })

        const helper = new THREE.Mesh(geometry, material)
        helper.position.copy(light.position)
        helper.lookAt(light.target.position)
        helper.rotateX(-Math.PI / 2) // Align cone with light direction
        helper.name = `debug-spot-${light.name || 'unnamed'}`
        this.debugGroup.add(helper)

        // Register with central registry
        this.registry.attachGeometry(light, helper)

        console.log(`≡ƒö┤ Added spot light debug cone at (${light.position.x.toFixed(1)}, ${light.position.y.toFixed(1)}, ${light.position.z.toFixed(1)}) angle: ${(angle * 180 / Math.PI).toFixed(1)}┬░`)
    }

    /**
     * Add visual debug helper for a RectArea light
     */
    addRectAreaLightHelper(light: THREE.RectAreaLight): void {
        const geometry = new THREE.PlaneGeometry(light.width, light.height)
        const material = new THREE.MeshBasicMaterial({
            color: 0xff0000,
            transparent: true,
            opacity: 0.2,
            side: THREE.DoubleSide
        })

        const helper = new THREE.Mesh(geometry, material)
        helper.position.copy(light.position)
        helper.rotation.copy(light.rotation)
        helper.name = `debug-rectarea-${light.name || 'unnamed'}`
        this.debugGroup.add(helper)

        // Register with central registry
        this.registry.attachGeometry(light, helper)

        console.log(`≡ƒö┤ Added RectArea light debug plane at (${light.position.x.toFixed(1)}, ${light.position.y.toFixed(1)}, ${light.position.z.toFixed(1)}) size: ${light.width}x${light.height}`)
    }

    /**
     * Add visual debug helper for a directional light
     */
    addDirectionalLightHelper(light: THREE.DirectionalLight): void {
        // Create arrow showing light direction
        const origin = light.position.clone()
        const direction = new THREE.Vector3(0, -1, 0) // Directional lights point down
        if (light.target) {
            direction.subVectors(light.target.position, light.position).normalize()
        }

        const arrowHelper = new THREE.ArrowHelper(direction, origin, 5, 0xff0000, 1, 1)
        arrowHelper.name = `debug-directional-${light.name || 'unnamed'}`
        this.debugGroup.add(arrowHelper)

        // Register with central registry
        this.registry.attachGeometry(light, arrowHelper)

        console.log(`≡ƒö┤ Added directional light debug arrow at (${light.position.x.toFixed(1)}, ${light.position.y.toFixed(1)}, ${light.position.z.toFixed(1)})`)
    }

    /**
     * Add debug helpers for all registered lights.
     * Uses LightRegistry instead of scene traversal.
     */
    addHelpersForRegisteredLights(): void {
        console.log('≡ƒöì Adding debug helpers for all registered lights...')

        const groupedLights = this.registry.getLightsGroupedByType()

        for (const [type, lights] of groupedLights) {
            for (const light of lights) {
                // Skip if already has attached geometry (debug helper)
                if (this.registry.getAttachedGeometry(light)) continue

                if (light instanceof THREE.PointLight) {
                    this.addPointLightHelper(light)
                } else if (light instanceof THREE.SpotLight) {
                    this.addSpotLightHelper(light)
                } else if (light instanceof THREE.RectAreaLight) {
                    this.addRectAreaLightHelper(light)
                } else if (light instanceof THREE.DirectionalLight) {
                    this.addDirectionalLightHelper(light)
                }
            }
        }
    }

    /**
     * @deprecated Use addHelpersForRegisteredLights() instead - avoids scene traversal
     */
    addHelpersForLightGroup(lightGroup: THREE.Group): void {
        console.log(`≡ƒöì Analyzing light group "${lightGroup.name}" for debug helpers...`)

        lightGroup.traverse((child) => {
            if (child instanceof THREE.PointLight) {
                this.addPointLightHelper(child)
            } else if (child instanceof THREE.SpotLight) {
                this.addSpotLightHelper(child)
            } else if (child instanceof THREE.RectAreaLight) {
                this.addRectAreaLightHelper(child)
            } else if (child instanceof THREE.DirectionalLight) {
                this.addDirectionalLightHelper(child)
            }
        })
    }

    /**
     * Clear all debug helpers
     */
    clearHelpers(): void {
        while (this.debugGroup.children.length > 0) {
            const child = this.debugGroup.children[0]
            this.debugGroup.remove(child)

            // Dispose geometry and materials
            if (child instanceof THREE.Mesh) {
                child.geometry.dispose()
                if (child.material instanceof THREE.Material) {
                    child.material.dispose()
                }
            }
        }

    }

    /**
     * Toggle debug helper visibility
     */
    setVisible(visible: boolean): void {
        this.debugGroup.visible = visible
        console.log(`≡ƒö┤ Debug helpers ${visible ? 'shown' : 'hidden'}`)
    }

    /**
     * Dispose of all resources
     */
    dispose(): void {
        this.clearHelpers()
        this.scene.remove(this.debugGroup)
    }
}

/**
 * Lighting Renderer - Comprehensive Lighting Setup
 * 
 * Handles all lighting systems that illuminate the environment:
 * - Ambient and directional lighting foundation
 * - Fluorescent store fixtures and commercial lighting
 * - Shadow configuration and quality settings
 * - Dynamic lighting levels and atmosphere control
 * 
 * This renderer should be loaded SECOND after environment to establish
 * proper illumination for props and interactive elements.
 */

import * as THREE from 'three'
import { RectAreaLightUniformsLib } from 'three/examples/jsm/lights/RectAreaLightUniformsLib.js'
import { BlockbusterColors } from '../utils/Colors'
import { PropRenderer } from './PropRenderer'
import { LightingDebugHelper } from './LightingDebugHelper'
import { AppSettings, LIGHTING_QUALITY, type LightingQuality } from '../core/AppSettings'
import { EventManager, EventSource } from '../core/EventManager'
import { LightingEventTypes, type LightingToggleEvent, type LightingDebugToggleEvent, type LightingQualityChangedEvent } from '../types/LightingEvents'
import { RoomEventTypes, type RoomCreatedEvent, type RoomResizedEvent } from '../types/InteractionEvents'
import { StorePropsEventTypes } from './props/PropsEvents'
import { LightFactory } from '../lighting/LightFactory'
import { LightRegistry } from '../lighting/LightRegistry'
import { Logger } from '../utils/Logger'
import { PerformanceMonitor } from '../utils/PerformanceMonitor'
import { GameSpotlight } from '../debug/GameSpotlight'

// Lighting configuration constants
const LIGHT_NAMES = {
    AMBIENT: 'ambient-light',
    MAIN_DIRECTIONAL: 'main-directional-light', 
    FILL: 'window-fill-light',
    RIM_LIGHT: 'rim-light',
    FLUORESCENT_FIXTURES: 'fluorescent-fixtures',
    DRAMATIC_SPOTLIGHT: 'dramatic-spotlight',
    POINT_LIGHT: 'point-light',
    ACCENT_LIGHT: 'accent-light'
} as const

// Room dimensions - will be updated dynamically via room events
let CURRENT_ROOM_DIMENSIONS = {
    WIDTH: 22,
    DEPTH: 16
}

const SHADOW_MAP_SIZES = {
    LOW: 512,
    MEDIUM: 1024, 
    HIGH: 2048,
    ULTRA: 4096
} as const

export interface LightingConfig {
    /** Ambient light intensity (0.0 - 1.0) */
    ambientIntensity?: number
    /** Main directional light intensity (0.0 - 1.0) */
    directionalIntensity?: number
    /** Fill light intensity (0.0 - 1.0) */
    fillLightIntensity?: number
    /** Ceiling height for fluorescent fixtures */
    ceilingHeight?: number
    /** Shadow quality (0=off, 1=low, 2=medium, 3=high, 4=ultra) */
    shadowQuality?: number
    /** Shadow map resolution (derived from shadowQuality) */
    shadowMapSize?: number
    /** Lighting quality level */
    quality?: LightingQuality
}

export class LightingRenderer {
    private scene: THREE.Scene
    private renderer: THREE.WebGLRenderer
    private propRenderer: PropRenderer | null = null
    private lightingGroup: THREE.Group
    private debugHelper: LightingDebugHelper
    private registry: LightRegistry
    private config: LightingConfig = {}
    private eventManager: EventManager
    private lightFactory: LightFactory
    private currentShelfLayout?: { rows: number; shelvesPerRow?: number }
    public static logger = Logger.createLogFunctions(LightingRenderer.name)

    constructor(scene: THREE.Scene, renderer: THREE.WebGLRenderer) {
        this.scene = scene
        this.renderer = renderer
        // PropRenderer creation deferred to first use
        this.registry = LightRegistry.getInstance()
        this.debugHelper = new LightingDebugHelper(scene)
        this.eventManager = EventManager.getInstance()

        // Initialize RectAreaLight uniforms (required for RectAreaLight to work)
        RectAreaLightUniformsLib.init()

        // Create group to hold all lighting objects
        this.lightingGroup = new THREE.Group()
        this.lightingGroup.name = 'lighting'
        this.scene.add(this.lightingGroup)
        this.lightFactory = new LightFactory(this.scene)

        // Register for lighting events
        this.setupEventListeners()
    }

    private setupEventListeners(): void {
        // Listen for lighting toggle events
        this.eventManager.registerEventHandler(LightingEventTypes.Toggle, (event: CustomEvent<LightingToggleEvent>) => {
            this.toggleLighting(event.detail.enabled)
        })

        // Listen for debug visualization toggle events
        this.eventManager.registerEventHandler(LightingEventTypes.DebugToggle, (event: CustomEvent<LightingDebugToggleEvent>) => {
            this.toggleDebugVisualization(event.detail.enabled)
        })

        // Listen for lighting quality change events
        this.eventManager.registerEventHandler(LightingEventTypes.QualityChanged, (event: CustomEvent<LightingQualityChangedEvent>) => {
            this.updateLightingQuality(event.detail.quality)
        })

        // Listen for room creation and resizing events to update lighting
        this.eventManager.registerEventHandler(RoomEventTypes.Created, (event: CustomEvent<RoomCreatedEvent>) => {
            this.updateRoomDimensions(event.detail.dimensions)
        })

        this.eventManager.registerEventHandler(RoomEventTypes.Resized, (event: CustomEvent<RoomResizedEvent>) => {
            this.updateRoomDimensions(event.detail.dimensions, event.detail.shelfLayout, event.detail.centerOffset) 
        })

        // Observe store-props lifecycle to drive lighting phases.
        // Use plain registerEventHandler (not default) so these fire even when
        // GpuStorePropsEventHandler / LegacyStorePropsHandler hold the normal handler slot.
        // Lighting is a side-effect observer of the scene lifecycle, not the owner.
        this.eventManager.registerEventHandler(
            StorePropsEventTypes.SetupRequest,
            this.setupBasicLighting.bind(this)
        )

        this.eventManager.registerEventHandler(
            StorePropsEventTypes.SetupCompleted,
            this.upgradeLighting.bind(this)
        )
        // PointLightRequested is handled by LightFactory directly ΓÇö it self-registers
        // in its constructor so the factory owns all light creation, including event-driven requests.
    }

    /**
     * Setup basic lighting fast - just ambient + directional
     * This lets the scene become visible quickly without expensive fixtures
     */
    private async setupBasicLighting(): Promise<void> {
        const startTime = window.performance.now()
        this.config = this.getCurrentConfig()

        LightingRenderer.logger.lifecycle(`≡ƒÆí Setting up BASIC lighting (fast pass)...`)

        try {
            // No shadows for fast startup
            this.renderer.shadowMap.enabled = false

            await this.setupSimpleLighting()

            // Create GameSpotlight pool BEFORE room geometry renders, so its SpotLight
            // is counted in the initial light-hash. Materials compile once with the
            // full light count during startup instead of recompiling on first click.
            new GameSpotlight()

            const duration = window.performance.now() - startTime
            LightingRenderer.logger.debug(`Γ£à Basic lighting ready in ${duration.toFixed(1)}ms (advanced lighting will load in background)`)
        } catch (error) {
            LightingRenderer.logger.error('Γ¥î Failed to set up basic lighting:', error)
            // Absolute fallback - just ambient
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.5)
            this.lightingGroup.add(ambientLight)
        }
    }

    /**
     * Upgrade to full lighting system - called asynchronously after scene is visible
     * 
     * TODO: Currently disabled in SceneCoordinator (suspected startup hitch).
     * Re-evaluate: this clears all lights then rebuilds from scratch, which forces
     * a full shader recompile of every MeshStandardMaterial in the scene. If lights
     * are already set up correctly in setupBasicLighting(), this method may be
     * unnecessary ΓÇö or should be restructured to add lights incrementally rather
     * than clear-and-rebuild.
     */
    private async upgradeLighting(): Promise<void> {
        const monitor = PerformanceMonitor.start('lighting-upgrade', LightingRenderer.logger)
        const startTime = window.performance.now()
        this.config = this.getCurrentConfig()

        LightingRenderer.logger.lifecycle(`≡ƒÆí Upgrading to ${this.config.quality} lighting...`)

        try {
            // Clear basic lighting
            this.clearLights()

            // Now do full setup with shadows and fixtures
            this.configureShadows()
            await this.setupLightsByQuality()
            monitor.end({ quality: this.config.quality })

            // Check current settings for debug helpers and lighting state
            const appSettings = AppSettings.getInstance()

            // Only show debug helpers if setting is enabled
            if (appSettings.getSetting('showLightingDebug')) {
                this.debugHelper.addHelpersForRegisteredLights()
            }

            // Don't call toggleLighting() here - it would overwrite individual visibility states
            // Each light type has its own visibility set in setupEnhancedLighting()
            // toggleLighting() is only for user-triggered master on/off via UI

            const duration = window.performance.now() - startTime
            LightingRenderer.logger.debug(`Γ£à Advanced lighting setup complete in ${duration.toFixed(1)}ms!`)

            // Emit system ready event for UI components
            this.eventManager.emit(LightingEventTypes.SystemReady, {
                scene: this.scene,
                quality: this.config.quality,
                timestamp: Date.now(),
                source: EventSource.System
            })
        } catch (error) {
            LightingRenderer.logger.error('Γ¥î Failed to upgrade lighting:', error)
            // Keep basic lighting - better than nothing
        }
    }

    private getCurrentConfig(): LightingConfig {
        const appSettings = AppSettings.getInstance()
        const shadowQuality = appSettings.getSetting('shadowQuality')
        return {
            ambientIntensity: 0.02, // Much lower, disabled by default
            directionalIntensity: 0.15, // Reduced by 50% 
            fillLightIntensity: 0.12, // Reduced by 40%
            ceilingHeight: appSettings.getSetting('ceilingHeight'),
            shadowQuality: shadowQuality,
            shadowMapSize: this.getShadowMapSizeForQuality(shadowQuality),
            quality: appSettings.getSetting('lightingQuality')
        }
    }

    private configureShadows(): void {
        const shadowQuality = this.config.shadowQuality || 0

        if (shadowQuality === 0) {
            this.renderer.shadowMap.enabled = false
            return
        }

        this.renderer.shadowMap.enabled = true

        // Set shadow map type based on quality
        if (shadowQuality >= 4) {
            this.renderer.shadowMap.type = THREE.VSMShadowMap // Ultra quality
        } else {
            this.renderer.shadowMap.type = THREE.PCFSoftShadowMap // Standard quality
        }
    }

    private getShadowMapSizeForQuality(shadowQuality: number): number {
        switch (shadowQuality) {
            case 0: return 0 // Shadows disabled
            case 1: return SHADOW_MAP_SIZES.LOW    // 512
            case 2: return SHADOW_MAP_SIZES.MEDIUM // 1024
            case 3: return SHADOW_MAP_SIZES.HIGH   // 2048
            case 4: return SHADOW_MAP_SIZES.ULTRA  // 4096
            default: return SHADOW_MAP_SIZES.MEDIUM
        }
    }

    private async setupLightsByQuality(): Promise<void> {
        switch (this.config.quality) {
            case LIGHTING_QUALITY.SIMPLE:
                await this.setupSimpleLighting()
                break
            case LIGHTING_QUALITY.ENHANCED:
                await this.setupEnhancedLighting()
                break
            case LIGHTING_QUALITY.ADVANCED:
                await this.setupAdvancedLighting()
                break
            case LIGHTING_QUALITY.OUCH_MY_EYES:
                await this.setupOuchMyEyesLighting()
                break
            default:
                await this.setupEnhancedLighting()
        }
    }

    private async setupSimpleLighting(): Promise<void> {
        LightingRenderer.logger.lifecycle('≡ƒÆí Setting up SIMPLE lighting - basic illumination only')

        // Higher ambient light to compensate for fewer light sources
        this.lightFactory.createAmbientLight(0xffffff, 0.4, { 
            name: LIGHT_NAMES.AMBIENT,
            parent: this.lightingGroup
        })

        // Single directional light
        this.lightFactory.createDirectionalLight(0xffffff, 0.6, { 
            name: LIGHT_NAMES.MAIN_DIRECTIONAL,
            parent: this.lightingGroup,
            position: [0, 10, 0]
        })

        LightingRenderer.logger.debug(`Γ£à Simple lighting: ${this.lightingGroup.children.length} lights added`)
    }

    private async setupEnhancedLighting(): Promise<void> {
        LightingRenderer.logger.lifecycle('≡ƒÆí Setting up ENHANCED lighting - optimized retail atmosphere')

        // Ambient light ΓÇö warm retail white, noticeable brightness.
        // ambientIntensity in config is near-zero by design (keeps specular bias down),
        // but ambient *base* must be high enough to see the room before fixtures kick in.
        const ambientLight = this.lightFactory.createAmbientLight(0xFFF8E7, 0.45, {
            name: LIGHT_NAMES.AMBIENT,
            parent: this.lightingGroup
        })
        // Now enabled by default - provides base illumination
        ambientLight.visible = true

        // Main exterior light: Combined moonlight + street light as single directional
        // Positioned high and forward with warmer tone (mix of cool moonlight + warm street light)
        const exteriorHeight = (this.config.ceilingHeight ?? 3.2) + 2
        const exteriorLight = this.lightFactory.createDirectionalLight(0xD4DFF2, 0.22, { // Soft blue-white blend
            name: 'exterior-ambient-light',
            parent: this.lightingGroup,
            position: [1, exteriorHeight, 10]
        })
        exteriorLight.castShadow = false // No shadows for performance
        exteriorLight.visible = false // Disabled by default - toggleable in lighting panel

        // Entrance spotlight: Creates inviting bright area at storefront that fades inward
        // Positioned outside looking in, warm welcoming glow
        const entranceSpot = this.lightFactory.createSpotLight(
            0xFFE4B5, // Warm moccasin - inviting store lighting
            0.6, // Strong enough to be noticeable
            12, // 12m range - reaches into store entrance
            Math.PI / 5, // ~36┬░ cone - focused on entrance area
            0.3, // Soft penumbra for gradual fade
            1.5, // Moderate decay for natural falloff
            {
                name: 'entrance-spotlight',
                parent: this.lightingGroup,
                position: [0, exteriorHeight - 0.5, CURRENT_ROOM_DIMENSIONS.DEPTH / 2 + 2] // Just outside front wall
            }
        )
        entranceSpot.target.position.set(0, 0, CURRENT_ROOM_DIMENSIONS.DEPTH / 2 - 3) // Aims into entrance
        entranceSpot.castShadow = false // Performance - emissive glass provides visual
        entranceSpot.visible = false // Disabled by default - toggleable in lighting panel
        this.lightingGroup.add(entranceSpot.target)

        // Subtle rim light: defines edges from back, prevents flat lighting
        // Cool temperature, very low intensity, non-shadow casting
        const rimLightHeight = (this.config.ceilingHeight ?? 3.2) + 1
        const rimLight = this.lightFactory.createDirectionalLight(BlockbusterColors.fluorescentCool, 0.08, {
            name: 'rim-light',
            parent: this.lightingGroup,
            position: [3, rimLightHeight, -5]
        })
        rimLight.castShadow = false
        rimLight.visible = false // Disabled by default - toggleable in lighting panel

        // Primary illumination: RectAreaLights from ceiling fixtures
        // NOTE: Fixtures are added later when shelf layout is known (via updateRoomDimensions)
        // This keeps initial room lit with base lighting before shelves spawn

        LightingRenderer.logger.debug(`Γ£à Enhanced lighting: ${this.lightingGroup.children.length} lights/groups added (ambient enabled, directional/spot/point disabled by default)`)
                // Ensure proper state when enhanced lighting takes over
        this.toggleLighting(true)
        this.toggleDebugVisualization(false)

        LightingRenderer.logger.debug(`≡ƒÆí Ceiling fixtures will be added when shelf layout is determined`)
    }

    private async setupAdvancedLighting(): Promise<void> {
        LightingRenderer.logger.lifecycle('≡ƒÆí Setting up ADVANCED lighting - enhanced + point lights + better shadows')

        await this.setupEnhancedLighting()
        this.addPointLights()

        LightingRenderer.logger.debug(`Γ£à Advanced lighting: ${this.lightingGroup.children.length} lights/groups added`)
    }

    private async setupOuchMyEyesLighting(): Promise<void> {
        LightingRenderer.logger.lifecycle('≡ƒÆí Setting up OUCH-MY-EYES lighting - maximum visual fidelity + dramatic effects')

        await this.setupAdvancedLighting()
        this.addDramaticLighting()

        LightingRenderer.logger.debug(`Γ£à Ouch-my-eyes lighting: ${this.lightingGroup.children.length} lights/groups added`)
    }

    private async setupFluorescentFixtures(shelfLayout?: { rows: number; shelvesPerRow?: number }): Promise<void> {
        const monitor = PerformanceMonitor.start('ceiling-fixtures-setup', LightingRenderer.logger)

        if (!this.propRenderer) {
            this.propRenderer = new PropRenderer(this.scene)
        }

        // Use provided layout, stored layout, or fall back to defaults
        // Place fixtures for every OTHER shelf row for better lighting coverage and performance
        const layout = shelfLayout ?? this.currentShelfLayout
        const shelfRows = layout?.rows ?? 2
        const fixtureRows = Math.max(1, Math.ceil(shelfRows / 2)) // One light per 2 shelf rows
        const fixturesPerRow = layout?.shelvesPerRow ?? 4
        const ceilingHeight = this.config.ceilingHeight ?? 3.2

        const fixtures = this.propRenderer.createCeilingLightFixtures(
            ceilingHeight,
            CURRENT_ROOM_DIMENSIONS.WIDTH,
            CURRENT_ROOM_DIMENSIONS.DEPTH,
            {
                width: 4,
                height: 0.15,
                depth: 0.6,
                emissiveIntensity: 0.6, // Reduced from 0.8 for comfort
                rows: fixtureRows,
                fixturesPerRow: fixturesPerRow
            }
        )

        fixtures.name = LIGHT_NAMES.FLUORESCENT_FIXTURES
        this.lightingGroup.add(fixtures)

        monitor.end({ fixtureCount: fixtureRows * fixturesPerRow, shelfRows })
        LightingRenderer.logger.debug(`≡ƒÆí Created ${fixtureRows * fixturesPerRow} ceiling fixtures (${fixtureRows} rows x ${fixturesPerRow} per row) for ${shelfRows} shelf rows`)
    }

    private addPointLights(): void {
        // Strategic accent lights for special displays and atmosphere
        // Positioned to highlight key areas without overwhelming
        const pointLightPositions = [
            { x: -6, y: 1.8, z: 6, color: 0xFFE4B5, intensity: 0.2 }, // Warm accent - front left
            { x: 6, y: 1.8, z: 6, color: 0xFFE4B5, intensity: 0.2 },  // Warm accent - front right
            { x: 0, y: 2.2, z: -7, color: BlockbusterColors.fluorescentCool, intensity: 0.15 } // Cool back wall accent
        ]

        pointLightPositions.forEach((light, index) => {
            const pointLight = this.lightFactory.createPointLight(light.color, light.intensity, 8, 2, {
                name: `${LIGHT_NAMES.ACCENT_LIGHT}-${index}`,
                parent: this.lightingGroup,
                position: [light.x, light.y, light.z]
            })
            // Accent lights don't cast shadows for performance
            pointLight.castShadow = false
            pointLight.visible = false // Disabled by default - toggleable in lighting panel
        })

        LightingRenderer.logger.debug('≡ƒÆí Added strategic accent lighting for atmosphere (disabled by default)')
    }

    private addDramaticLighting(): void {
        const spotLight1 = this.lightFactory.createSpotLight(0xffffff, 1.0, 15, Math.PI / 6, 0.2, 1, {
            name: LIGHT_NAMES.DRAMATIC_SPOTLIGHT,
            parent: this.lightingGroup,
            position: [0, 8, 0]
        })
        spotLight1.target.position.set(0, 0, 0)
        if ((this.config.shadowQuality || 0) > 0) {
            spotLight1.castShadow = true
            const shadowMapSize = this.getShadowMapSizeForQuality(this.config.shadowQuality || 0)
            spotLight1.shadow.mapSize.width = shadowMapSize
            spotLight1.shadow.mapSize.height = shadowMapSize
        }
        this.lightingGroup.add(spotLight1.target)

        const accentColors = [0xff4444, 0x44ff44, 0x4444ff]
        accentColors.forEach((color, index) => {
            this.lightFactory.createPointLight(color, 0.3, 8, undefined, {
                name: `${LIGHT_NAMES.ACCENT_LIGHT}-${index}`,
                parent: this.lightingGroup,
                position: [(index - 1) * 6, 1.5, -6]
            })
        })
    }

    private async updateLightingQuality(quality: LightingQuality): Promise<void> {
        this.debugHelper.clearHelpers()
        this.clearLights()

        // Refresh full config from AppSettings to get updated shadows/ceiling height too
        this.config = { ...this.getCurrentConfig(), quality }
        await this.setupLightsByQuality()

        // Only show debug helpers if setting is enabled
        const appSettings = AppSettings.getInstance()
        if (appSettings.getSetting('showLightingDebug')) {
            this.debugHelper.addHelpersForRegisteredLights()
        }

        // Emit system ready event for UI components
        this.eventManager.emit(LightingEventTypes.SystemReady, {
            scene: this.scene,
            quality: this.config.quality,
            timestamp: Date.now(),
            source: EventSource.System
        })
    }

    private updateRoomDimensions(
        dimensions: { width: number; depth: number; height: number },
        shelfLayout?: { rows: number; shelvesPerRow?: number },
        centerOffset?: { x: number; y: number; z: number }
    ): void {
        LightingRenderer.logger.debug(`≡ƒÆí Updating lighting for room dimensions: ${dimensions.width}x${dimensions.depth}x${dimensions.height}`)

        // Update current room dimensions for fluorescent fixture positioning
        CURRENT_ROOM_DIMENSIONS.WIDTH = dimensions.width
        CURRENT_ROOM_DIMENSIONS.DEPTH = dimensions.depth

        // Update ceiling height in config if different
        if (this.config.ceilingHeight !== dimensions.height) {
            this.config.ceilingHeight = dimensions.height
        }

        // Store shelf layout for use during lighting upgrades
        if (shelfLayout) {
            this.currentShelfLayout = shelfLayout
            LightingRenderer.logger.debug(`≡ƒÆí Stored shelf layout: ${shelfLayout.rows} rows x ${shelfLayout.shelvesPerRow} shelves per row`)
        }

        // Position lighting group to match room offset so lights align with shelves
        if (centerOffset) {
            this.lightingGroup.position.set(centerOffset.x, centerOffset.y, centerOffset.z)
            LightingRenderer.logger.debug(`≡ƒÆí Lighting group positioned at: (${centerOffset.x}, ${centerOffset.y}, ${centerOffset.z.toFixed(1)})`)
        }

        // Add or update ceiling fixtures based on shelf layout
        // Only add fixtures if we have shelf layout data and don't already have them
        if (shelfLayout) {
            const existingFixtures = this.lightingGroup.getObjectByName(LIGHT_NAMES.FLUORESCENT_FIXTURES)
            if (existingFixtures) {
                LightingRenderer.logger.debug('≡ƒÆí Updating existing ceiling fixtures for new shelf layout...')
                this.lightingGroup.remove(existingFixtures)
            } else {
                LightingRenderer.logger.debug('≡ƒÆí Adding ceiling fixtures for shelf layout...')
            }
            this.setupFluorescentFixtures(shelfLayout)
        }
    }

    public toggleLighting(enabled: boolean): void {
        LightingRenderer.logger.debug(`≡ƒÆí ${enabled ? 'Enabling' : 'Disabling'} all lights`)

        for (const [, lights] of this.registry.getLightsGroupedByType()) {
            for (const light of lights) {
                light.visible = enabled
            }
        }
    }

    public toggleDebugVisualization(enabled: boolean): void {
        LightingRenderer.logger.debug(`≡ƒöì ${enabled ? 'Showing' : 'Hiding'} light debug visualization`)

        if (enabled) {
            this.debugHelper.addHelpersForRegisteredLights()
        } else {
            this.debugHelper.clearHelpers()
        }
    }

    /**
     * Toggle specific light by name on/off
     */
    public toggleLightByName(lightName: string, enabled: boolean): void {
        const light = this.lightingGroup.getObjectByName(lightName) as THREE.Light
        if (light) {
            light.visible = enabled
            LightingRenderer.logger.debug(`≡ƒÆí ${lightName} light ${enabled ? 'enabled' : 'disabled'}`)
        } else {
            LightingRenderer.logger.warn(`ΓÜá∩╕Å Light '${lightName}' not found for toggle`)
        }
    }

    /**
     * Toggle ambient light on/off (convenience method)
     */
    public toggleAmbientLight(enabled: boolean): void {
        this.toggleLightByName(LIGHT_NAMES.AMBIENT, enabled)
    }

    private clearLights(): void {
        // Clear registry first so the controls panel doesn't see stale entries
        this.registry.clear()

        // Preserve ceiling fixtures if they exist (added when shelves spawn)
        const existingFixtures = this.lightingGroup.getObjectByName(LIGHT_NAMES.FLUORESCENT_FIXTURES)
        if (existingFixtures) {
            this.lightingGroup.remove(existingFixtures)
        }

        // Remove all other children from lighting group
        while (this.lightingGroup.children.length > 0) {
            const child = this.lightingGroup.children[0]
            this.lightingGroup.remove(child)

            // Dispose any resources if needed
            if (child instanceof THREE.Light) {
                const shadowLight = child as THREE.DirectionalLight | THREE.SpotLight | THREE.PointLight
                if ('shadow' in shadowLight && shadowLight.shadow) {
                    shadowLight.shadow.dispose()
                }
            }
        }

        // Re-add preserved fixtures
        if (existingFixtures) {
            this.lightingGroup.add(existingFixtures)
            LightingRenderer.logger.debug('≡ƒÆí Preserved ceiling fixtures during lighting upgrade')
        }
    }

    public dispose(): void {
        this.clearLights()
        this.debugHelper.dispose()
        if (this.propRenderer) {
            this.propRenderer.dispose()
        }
        this.scene.remove(this.lightingGroup)
    }
}

/**
 * PropRenderer - Atmospheric Props Management
 * 
 * Handles:
 * - Ceiling light fixtures and panels
 * - Wire rack displays
 * - Category dividers and shelf separators
 * - Navigation markers and floor patterns
 * 
 * Note: Planned to be merged into legacy/GPU system bifurcation (see tech-debt.md)
 */

import * as THREE from 'three'
import { BlockbusterColors } from '../utils/Colors'
import { LightFactory } from '../lighting/LightFactory'
import { PerformanceMonitor } from '../utils/PerformanceMonitor'
import { Logger } from '../utils/Logger'

export interface LightFixtureOptions {
  width?: number
  height?: number
  depth?: number
  emissiveIntensity?: number
  rows?: number
  fixturesPerRow?: number
}

export interface WireRackOptions {
  width?: number
  height?: number
  depth?: number
  wireThickness?: number
  spacing?: number
}

export class PropRenderer {
  public static logger = Logger.createLogFunctions(PropRenderer.name)
  private scene: THREE.Scene
  private propsGroup: THREE.Group
  private lightFactory: LightFactory

  constructor(scene: THREE.Scene) {
  this.scene = scene
  this.propsGroup = new THREE.Group()
  this.propsGroup.name = 'AtmosphericProps'
  this.scene.add(this.propsGroup)
    this.lightFactory = new LightFactory(scene)
  }

  /**
   * Create ceiling-mounted fluorescent light fixtures
   * Positioned just below the ceiling surface for realistic appearance
   * TODO: Make this responsive to room resizing events
   */
  public createCeilingLightFixtures(ceilingHeight: number, roomWidth: number, roomDepth: number, options: LightFixtureOptions = {}): THREE.Group {
    const monitor = PerformanceMonitor.start('create-ceiling-fixtures', PropRenderer.logger)

    const {
      width = 4,
      height = 0.15,
      depth = 0.6,
      emissiveIntensity = 0.8,
      rows = 2,
      fixturesPerRow = 4
    } = options

    const fixturesGroup = new THREE.Group()
    fixturesGroup.name = 'CeilingLightFixtures'

    // Create the base fixture geometry
    const fixtureGeometry = new THREE.BoxGeometry(width, height, depth)

    // Create emissive material for the light panels (enhanced brightness)
    const fixtureMaterial = new THREE.MeshStandardMaterial({
      color: 0xFFFFF0, // Ivory (warmer and brighter than ghost white)
      emissive: 0xF0F8FF, // Alice blue glow (brighter emissive)
      emissiveIntensity: emissiveIntensity * 2.0, // Further increased for more prominence
      roughness: 0.05, // Even smoother for more reflection
      metalness: 0.02,
      transparent: true,
      opacity: 0.98 // Slightly more opaque
    })

    // Create housing material (lighter frame around light - more realistic)
    const housingMaterial = new THREE.MeshStandardMaterial({
      color: 0xD3D3D3, // Light gray (much brighter than before)
      roughness: 0.5,
      metalness: 0.4,
      emissive: 0x0A0A0A, // Subtle warm glow from housing
      emissiveIntensity: 0.1
    })

    // Position fixtures in a grid pattern across the ceiling
    const fixtureSpacingX = roomWidth / (fixturesPerRow + 1)
    const fixtureSpacingZ = roomDepth / (rows + 1)
    const fixtureY = ceilingHeight - height / 2 - 0.02 // Just below ceiling surface

    const totalFixtures = rows * fixturesPerRow

    // Create instanced meshes for housing and light panels (reduces draw calls!)
    const housingGeometry = new THREE.BoxGeometry(width + 0.1, height + 0.05, depth + 0.1)
    const housingInstanced = new THREE.InstancedMesh(housingGeometry, housingMaterial, totalFixtures)
    housingInstanced.name = 'CeilingFixtureHousings'

    const lightPanelInstanced = new THREE.InstancedMesh(fixtureGeometry, fixtureMaterial, totalFixtures)
    lightPanelInstanced.name = 'CeilingLightPanels'
    lightPanelInstanced.userData = { 
      isLightFixture: true,
      type: 'ceiling-fluorescent',
      instanceCount: totalFixtures
    }

    const matrix = new THREE.Matrix4()
    let instanceIndex = 0

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < fixturesPerRow; col++) {
        const fixtureX = -roomWidth / 2 + (col + 1) * fixtureSpacingX
        const fixtureZ = -roomDepth / 2 + (row + 1) * fixtureSpacingZ

        // Set housing instance matrix
        matrix.makeTranslation(fixtureX, fixtureY + 0.05, fixtureZ)
        housingInstanced.setMatrixAt(instanceIndex, matrix)

        // Set light panel instance matrix
        matrix.makeTranslation(fixtureX, fixtureY, fixtureZ)
        lightPanelInstanced.setMatrixAt(instanceIndex, matrix)

        instanceIndex++
      }
    }

    // Update instance matrices
    housingInstanced.instanceMatrix.needsUpdate = true
    lightPanelInstanced.instanceMatrix.needsUpdate = true

    fixturesGroup.add(housingInstanced)
    fixturesGroup.add(lightPanelInstanced)

    // Create one RectAreaLight per shelf row for proper coverage
    // Each light is positioned to match its corresponding row of fixtures
    for (let row = 0; row < rows; row++) {
      // Calculate Z position for this row (matches fixture positioning)
      const rowZ = -roomDepth / 2 + (row + 1) * fixtureSpacingZ

      const rowLight = this.lightFactory.createRectAreaLight(
        BlockbusterColors.fluorescentCool,
        4, // Balanced intensity per row
        roomWidth * 0.8,
        depth * 0.9,
        {
          name: `ceiling-row-${row}-light`,
          parent: fixturesGroup
        }
      )
      // Position the light just below the mesh panels for this row
      rowLight.position.set(0, fixtureY - 0.12, rowZ)
      rowLight.rotation.x = -Math.PI / 2

      rowLight.userData = {
        isShelfLight: true,
        rowIndex: row,
        fixtureCount: fixturesPerRow
      }
    }

    this.propsGroup.add(fixturesGroup)
    console.log(`≡ƒÆí Created ${rows * fixturesPerRow} ceiling fixtures with ${rows} RectAreaLights at height ${fixtureY.toFixed(2)}m`)

    monitor.end({ totalFixtures: rows * fixturesPerRow, rectAreaLights: rows })
    return fixturesGroup
  }

  /**
   * Create wire rack displays for snack/merchandise areas
   */
  public createWireRackDisplay(position: THREE.Vector3, options: WireRackOptions = {}): THREE.Group {
    const {
      width = 1.2,
      height = 1.8,
      depth = 0.6,
      wireThickness = 0.02,
      spacing = 0.3
    } = options

    const rackGroup = new THREE.Group()
    rackGroup.name = 'WireRackDisplay'

    // Wire material (brightened for better visibility)
    const wireMaterial = new THREE.MeshStandardMaterial({
      color: 0x808080, // Medium gray (brighter than before)
      roughness: 0.3,
      metalness: 0.7
    })

    // Create vertical posts
    const postGeometry = new THREE.CylinderGeometry(wireThickness, wireThickness, height)
    const posts = [
      new THREE.Vector3(-width/2, height/2, -depth/2),
      new THREE.Vector3(width/2, height/2, -depth/2),
      new THREE.Vector3(-width/2, height/2, depth/2),
      new THREE.Vector3(width/2, height/2, depth/2)
    ]

    posts.forEach(postPos => {
      const post = new THREE.Mesh(postGeometry, wireMaterial)
      post.position.copy(postPos)
      rackGroup.add(post)
    })

    // Create horizontal shelf wires
    const shelfCount = Math.floor(height / spacing)
    for (let i = 0; i < shelfCount; i++) {
      const shelfY = i * spacing + 0.2

      // Front-to-back wires
      const wireGeometry = new THREE.CylinderGeometry(wireThickness/2, wireThickness/2, depth)
      const leftWire = new THREE.Mesh(wireGeometry, wireMaterial)
      leftWire.rotation.x = Math.PI / 2
      leftWire.position.set(-width/2, shelfY, 0)
      rackGroup.add(leftWire)

      const rightWire = new THREE.Mesh(wireGeometry, wireMaterial)
      rightWire.rotation.x = Math.PI / 2
      rightWire.position.set(width/2, shelfY, 0)
      rackGroup.add(rightWire)

      // Side-to-side support wires
      const sideWireGeometry = new THREE.CylinderGeometry(wireThickness/2, wireThickness/2, width)
      const backWire = new THREE.Mesh(sideWireGeometry, wireMaterial)
      backWire.rotation.z = Math.PI / 2
      backWire.position.set(0, shelfY, depth/2)
      rackGroup.add(backWire)
    }

    rackGroup.position.copy(position)
    rackGroup.userData = { type: 'wire-rack', isAtmosphericProp: true }

    this.propsGroup.add(rackGroup)
    return rackGroup
  }

  /**
   * Create category dividers between shelf sections
   */
  public createCategoryDivider(position: THREE.Vector3, height: number = 2.2): THREE.Group {
    const dividerGroup = new THREE.Group()
    dividerGroup.name = 'CategoryDivider'

    // Main post
    const postGeometry = new THREE.BoxGeometry(0.05, height, 0.05)
    const postMaterial = new THREE.MeshStandardMaterial({
      color: 0x8B4513, // Saddle brown (wood)
      roughness: 0.6,
      metalness: 0.0
    })

    const post = new THREE.Mesh(postGeometry, postMaterial)
    post.position.set(0, height / 2, 0)
    dividerGroup.add(post)

    // Small top cap
    const capGeometry = new THREE.BoxGeometry(0.1, 0.02, 0.1)
    const cap = new THREE.Mesh(capGeometry, postMaterial)
    cap.position.set(0, height + 0.01, 0)
    dividerGroup.add(cap)

    dividerGroup.position.copy(position)
    dividerGroup.userData = { type: 'category-divider', isAtmosphericProp: true }

    this.propsGroup.add(dividerGroup)
    return dividerGroup
  }

  /**
   * Create entrance floor mat for visual entrance indication
   */
  public createEntranceFloorMat(roomWidth: number, _roomDepth: number): THREE.Group {
    const entranceGroup = new THREE.Group()
    entranceGroup.name = 'entrance-floor-mat'

    // Create entrance mat geometry (will be positioned by caller)
    const matWidth = Math.min(6, roomWidth * 0.4) // 40% of room width, max 6m
    const matDepth = 1.5 // 1.5m deep entrance mat
    const matGeometry = new THREE.PlaneGeometry(matWidth, matDepth)

    // Create mat material with different color/texture
    const matMaterial = new THREE.MeshStandardMaterial({
      color: 0x8B4513, // Brown entrance mat
      roughness: 0.8,
      metalness: 0.1
    })

    const mat = new THREE.Mesh(matGeometry, matMaterial)
    mat.rotation.x = -Math.PI / 2
    mat.position.set(0, 0.01, 0) // Just above floor, no Z offset (positioned by caller)
    mat.name = 'entrance-mat'

    entranceGroup.add(mat)
    return entranceGroup
  }

  /**
   * Create subtle floor navigation markers
   */
  public createFloorMarkers(roomWidth: number, roomDepth: number): THREE.Group {
    const markersGroup = new THREE.Group()
    markersGroup.name = 'FloorMarkers'

    // Create subtle aisle center lines
    const lineGeometry = new THREE.PlaneGeometry(0.05, roomDepth * 0.8)
    const lineMaterial = new THREE.MeshStandardMaterial({
      color: 0x555555, // Darker than carpet for subtle visibility
      transparent: true,
      opacity: 0.3,
      roughness: 0.9
    })

    // Main center aisle marker
    const centerLine = new THREE.Mesh(lineGeometry, lineMaterial)
    centerLine.rotation.x = -Math.PI / 2
    centerLine.position.set(0, 0.01, 0) // Slightly above floor
    markersGroup.add(centerLine)

    // Side aisle markers
    const leftLine = new THREE.Mesh(lineGeometry, lineMaterial)
    leftLine.rotation.x = -Math.PI / 2
    leftLine.position.set(-roomWidth * 0.3, 0.01, 0)
    markersGroup.add(leftLine)

    const rightLine = new THREE.Mesh(lineGeometry, lineMaterial)
    rightLine.rotation.x = -Math.PI / 2
    rightLine.position.set(roomWidth * 0.3, 0.01, 0)
    markersGroup.add(rightLine)

    markersGroup.userData = { type: 'floor-markers', isAtmosphericProp: true }

    this.propsGroup.add(markersGroup)
    return markersGroup
  }

  /**
   * Get the props group for positioning or manipulation
   */
  public getPropsGroup(): THREE.Group {
    return this.propsGroup
  }

  /**
   * Clear all atmospheric props
   */
  public clearProps(): void {
    while (this.propsGroup.children.length > 0) {
      const child = this.propsGroup.children[0]
      if (child instanceof THREE.Mesh) {
        child.geometry.dispose()
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose())
        } else {
          child.material.dispose()
        }
      }
      this.propsGroup.remove(child)
    }
  }

  /**
   * Dispose of resources
   */
  public dispose(): void {
    this.clearProps()
    this.scene.remove(this.propsGroup)
  }
}

