    public getPosition(): THREE.Vector3 {
        return this.position
    }

    /** Place (or replace) the Recently Played ceiling sign. */
    public place(centerX = 0): void {
        const y = RoomConstants.STORE_CEILING_HEIGHT - SIGN_DROP_FROM_CEILING
