interface RoomResizeEventData {
    dimensions?: RoomDimensions
    centerOffset?: { x: number; y: number; z: number }
    shelfLayout?: { rows: number; shelvesPerRow?: number }
}

export class RoomManager {
    private scene: THREE.Scene
    private camera: THREE.PerspectiveCamera
    private materialManager: SharedMaterialManager
    private eventManager: EventManager
    private logger = Logger.createLogFunctions('RoomManager')

    // Resize state: if room is building, this is the target; otherwise resize immediately
    private targetDimensions: RoomDimensions | null = null
    private targetCenterOffset: { x: number; y: number; z: number } | null = null
    private isBuilding = false

    // Room structure (reused on resize)
    private roomGroup: THREE.Group | null = null
    private floor: THREE.Mesh | null = null
    private ceiling: THREE.Mesh | null = null
    private walls: {
        front: THREE.Mesh | null
        back: THREE.Mesh | null  
        left: THREE.Mesh | null
        right: THREE.Mesh | null
    } = { front: null, back: null, left: null, right: null }

    private currentDimensions: RoomDimensions = {
        width: RoomConstants.DEFAULT_ROOM_WIDTH,
        depth: RoomConstants.DEFAULT_ROOM_DEPTH,
        height: RoomConstants.DEFAULT_ROOM_HEIGHT
    }

    constructor() {
        const scene = DataManager.getInstance().get<THREE.Scene>(DataKey.MainScene)
        if (!scene) {
            throw new Error('RoomManager requires scene to be registered in DataManager')
        }
        this.scene = scene

        const camera = DataManager.getInstance().get<THREE.PerspectiveCamera>(DataKey.MainCamera)
        if (!camera) {
            throw new Error('RoomManager requires camera to be registered in DataManager')
        }
        this.camera = camera

        this.materialManager = SharedMaterialManager.getInstance()
        this.eventManager = EventManager.getInstance()

        this.eventManager.registerEventHandler(RoomEventTypes.Resize, this.onResizeRoom.bind(this))
        this.eventManager.registerEventHandler(GameEventTypes.ShelfLayoutDetermined, this.onShelfLayoutDetermined.bind(this))
        this.eventManager.registerEventHandler(CeilingEventTypes.Toggle, this.onCeilingToggle.bind(this))

        // Fire-and-forget initial room creation
        this.createInitialRoom()
    }

    private async createInitialRoom(): Promise<void> {
        this.isBuilding = true
        try {
            await this.buildRoom(this.currentDimensions)

            // If resize was requested during build, apply it now
            if (this.targetDimensions) {
                await this.buildRoom(this.targetDimensions, this.targetCenterOffset ?? undefined)
                this.targetDimensions = null
                this.targetCenterOffset = null
            }
        } finally {
            this.isBuilding = false
        }
    }

    private onCeilingToggle(event: CustomEvent<CeilingToggleEvent>): void {
        if (this.ceiling) {
            this.ceiling.visible = event.detail.visible
        }
    }

    private async onShelfLayoutDetermined(event: CustomEvent<ShelfLayoutDeterminedEvent>): Promise<void> {
        const perf = PerformanceMonitor.start('room-resize-calculation', this.logger)

        const { shelfBounds, shelfLayout } = event.detail

        // Validate shelf bounds exist
        if (shelfBounds.minX === Infinity) {
            perf.end()
            console.debug('≡ƒÅá ShelfLayoutDetermined received with no shelf bounds - skipping resize')
            return
        }

        // Calculate room dimensions using our own constants
        const roomWidth = (shelfBounds.maxX - shelfBounds.minX) + (RoomConstants.STORE_WALL_CLEARANCE * 2)
        const roomDepth = Math.abs(shelfBounds.minZ) + RoomConstants.STORE_BACK_CLEARANCE
        const roomHeight = RoomConstants.STORE_CEILING_HEIGHT
        const roomCenterZ = (shelfBounds.minZ - RoomConstants.STORE_BACK_CLEARANCE) / 2

        const dimensions: RoomDimensions = { width: roomWidth, depth: roomDepth, height: roomHeight }
        const centerOffset = { x: 0, y: 0, z: roomCenterZ }

        console.debug(`≡ƒôÉ Shelf bounds: X[${shelfBounds.minX.toFixed(1)}, ${shelfBounds.maxX.toFixed(1)}], Z[${shelfBounds.minZ.toFixed(1)}, ${shelfBounds.maxZ.toFixed(1)}]`)
        console.debug(`≡ƒÅá Calculated room: ${roomWidth.toFixed(1)}x${roomDepth.toFixed(1)}x${roomHeight.toFixed(1)}, center Z: ${roomCenterZ.toFixed(1)}`)

        perf.end({ rows: shelfLayout.rows, shelvesPerRow: shelfLayout.shelvesPerRow })

        if (this.isBuilding) {
            this.targetDimensions = dimensions
            this.targetCenterOffset = centerOffset
            console.debug('≡ƒÅá Room building, queued resize target')
        } else {
            await this.buildRoom(dimensions, centerOffset)
        }

        // Notify listeners that room has resized
        this.eventManager.emit<RoomResizedEvent>(RoomEventTypes.Resized, { 
            dimensions,
            shelfLayout,
            centerOffset
        })
    }

    private async onResizeRoom(event: CustomEvent<RoomResizeEventData>): Promise<void> {
        const { dimensions, centerOffset, shelfLayout } = event.detail

        if (!dimensions) {
            // No dimensions provided - ignore (legacy events without dimensions)
            return
        }

        if (this.isBuilding) {
            // Room still building - just update the target, don't queue multiple operations
            this.targetDimensions = dimensions
            this.targetCenterOffset = centerOffset ?? null
            console.debug('≡ƒÅá Room building, queued resize target')
        } else {
            // Room ready - resize immediately
            await this.buildRoom(dimensions, centerOffset)
        }

        // Notify listeners that room has resized (or will resize to these dimensions)
        this.eventManager.emit<RoomResizedEvent>(RoomEventTypes.Resized, { 
            dimensions,
            shelfLayout,
            centerOffset
        })
    }

    private async buildRoom(dimensions: RoomDimensions, centerOffset?: { x: number; y: number; z: number }): Promise<void> {
        if (!this.roomGroup) {
            this.roomGroup = new THREE.Group()
            this.roomGroup.name = 'room-structure'
            this.scene.add(this.roomGroup)
        }

        if (centerOffset) {
            const appliedZ = centerOffset.z + RoomConstants.STORE_FRONT_OFFSET
            this.roomGroup.position.set(centerOffset.x, centerOffset.y, appliedZ)

            // Reposition and reorient camera to face the store center
            // Player spawns at origin (0, 1.6, 0), should look at back wall center
            const targetZ = appliedZ - (dimensions.depth / 2)
            this.camera.position.set(0, 1.6, 0)
            this.camera.lookAt(0, 1.6, targetZ)
            console.debug(`≡ƒô╖ Camera repositioned to face store center at Z=${targetZ.toFixed(1)}`)
        }

        this.emitProgress('Building floor')
        this.ensureFloor(dimensions)

        this.emitProgress('Building ceiling')
        this.ensureCeiling(dimensions)

        this.emitProgress('Building walls')
        this.ensureWalls(dimensions)

        this.currentDimensions = { ...dimensions }
        console.debug(`≡ƒÅá Room ready: ${dimensions.width.toFixed(0)}x${dimensions.depth.toFixed(0)}x${dimensions.height.toFixed(0)}`)
    }

    private emitProgress(detail: string): void {
        this.eventManager.emit<StorePropsProgressEvent>(StorePropsEventTypes.Progress, {
            step: 'room',
            detail
        })
    }

    private ensureFloor(dimensions: RoomDimensions): void {
        if (!this.roomGroup) return

        if (this.floor) {
            this.floor.geometry.dispose()
            this.floor.geometry = new THREE.PlaneGeometry(dimensions.width, dimensions.depth)
        } else {
            this.floor = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.width, dimensions.depth),
                this.materialManager.getMaterial(MaterialType.Carpet)
            )
            this.floor.rotation.x = -Math.PI / 2
            this.floor.position.y = 0
            this.floor.name = 'room-floor'
            this.roomGroup.add(this.floor)
        }
    }

    private ensureCeiling(dimensions: RoomDimensions): void {
        if (!this.roomGroup) return

        if (this.ceiling) {
            this.ceiling.geometry.dispose()
            this.ceiling.geometry = new THREE.PlaneGeometry(dimensions.width, dimensions.depth)
            this.ceiling.position.y = dimensions.height
        } else {
            this.ceiling = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.width, dimensions.depth),
                this.materialManager.getMaterial(MaterialType.Ceiling)
            )
            this.ceiling.rotation.x = Math.PI / 2
            this.ceiling.position.y = dimensions.height
            this.ceiling.name = 'room-ceiling'
            this.roomGroup.add(this.ceiling)
        }
    }

    private ensureWalls(dimensions: RoomDimensions): void {
        if (!this.roomGroup) return

        const wallMaterial = this.materialManager.getMaterial(MaterialType.WallWood)
        const glassMaterial = this.materialManager.getMaterial(MaterialType.Glass)
        const halfHeight = dimensions.height / 2

        // Back wall
        if (this.walls.back) {
            this.walls.back.geometry.dispose()
            this.walls.back.geometry = new THREE.PlaneGeometry(dimensions.width, dimensions.height)
            this.walls.back.position.set(0, halfHeight, -dimensions.depth / 2)
        } else {
            this.walls.back = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.width, dimensions.height),
                wallMaterial
            )
            this.walls.back.position.set(0, halfHeight, -dimensions.depth / 2)
            this.walls.back.name = 'room-back-wall'
            this.roomGroup.add(this.walls.back)
        }

        // Front wall (glass storefront)
        if (this.walls.front) {
            this.walls.front.geometry.dispose()
            this.walls.front.geometry = new THREE.PlaneGeometry(dimensions.width, dimensions.height)
            this.walls.front.position.set(0, halfHeight, dimensions.depth / 2)
        } else {
            this.walls.front = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.width, dimensions.height),
                glassMaterial
            )
            this.walls.front.position.set(0, halfHeight, dimensions.depth / 2)
            this.walls.front.rotation.y = Math.PI
            this.walls.front.name = 'room-front-wall-glass'
            this.roomGroup.add(this.walls.front)
        }

        // Left wall
        if (this.walls.left) {
            this.walls.left.geometry.dispose()
            this.walls.left.geometry = new THREE.PlaneGeometry(dimensions.depth, dimensions.height)
            this.walls.left.position.set(-dimensions.width / 2, halfHeight, 0)
        } else {
            this.walls.left = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.depth, dimensions.height),
                wallMaterial
            )
            this.walls.left.position.set(-dimensions.width / 2, halfHeight, 0)
            this.walls.left.rotation.y = Math.PI / 2
            this.walls.left.name = 'room-left-wall'
            this.roomGroup.add(this.walls.left)
        }

        // Right wall
        if (this.walls.right) {
            this.walls.right.geometry.dispose()
            this.walls.right.geometry = new THREE.PlaneGeometry(dimensions.depth, dimensions.height)
            this.walls.right.position.set(dimensions.width / 2, halfHeight, 0)
        } else {
            this.walls.right = new THREE.Mesh(
                new THREE.PlaneGeometry(dimensions.depth, dimensions.height),
                wallMaterial
            )
            this.walls.right.position.set(dimensions.width / 2, halfHeight, 0)
            this.walls.right.rotation.y = -Math.PI / 2
            this.walls.right.name = 'room-right-wall'
            this.roomGroup.add(this.walls.right)
        }
    }

    public getCurrentDimensions(): RoomDimensions {
        return { ...this.currentDimensions }
    }

    public dispose(): void {
        if (this.roomGroup) {
            this.scene.remove(this.roomGroup)

            // Dispose tracked room elements directly (no traverse needed)
            this.disposeRoomElement(this.floor)
            this.disposeRoomElement(this.ceiling)
            this.disposeRoomElement(this.walls.front)
            this.disposeRoomElement(this.walls.back)
            this.disposeRoomElement(this.walls.left)
            this.disposeRoomElement(this.walls.right)

            this.roomGroup = null
        }

        // Reset references
        this.floor = null
        this.ceiling = null
        this.walls = { front: null, back: null, left: null, right: null }

        console.debug('≡ƒÅá RoomManager disposed')
    }

    private disposeRoomElement(mesh: THREE.Mesh | null): void {
        if (!mesh) return
        mesh.geometry?.dispose()
        if (mesh.material instanceof THREE.Material) {
            mesh.material.dispose()
        }
    }
}

/**
 * Scene Coordinator - High-Level Scene Setup and Management
 * 
 * This coordinator orchestrates the complete visual system setup with
 * organized visual buckets loaded in
 * 1. Environment (skybox, room structure, spatial found            // Emit room:resize event to trigger proper event-driven room expansion
            // RoomManager will calculate dimensions and handle room structure
            // StorePropsRenderer will listen for room:resized and spawn shelves accordingly
            console.debug(`≡ƒùé∩╕Å Requesting room resize for ${eventData.gameCount} games`)
            EventManager.getInstance().emit('room:resize', {
                gameCount: eventData.gameCount,
                timestamp: Date.now(),
                source: 'SceneCoordinator',
                games: this.getGamesForShelfSpawning()
            } as any)2. Lighting (illumination systems, shadows, atmosphere)  
 * 3. Props (shelves, games, signage, interactive objects)
 * 
 * This sequential loading creates a smooth transition for players as
 * they see the space build up in logical layers.
 */

import * as THREE from 'three'
import { SceneManager } from './SceneManager'
import { SkyboxManager, SkyboxPresets } from './SkyboxManager'
import { LightingRenderer } from './LightingRenderer'
import { RoomManager } from './RoomManager'
import { EventManager } from '../core/EventManager'
import { GameEventTypes } from '../types/InteractionEvents'
import { DataManager } from '../core/data'
// Initialize store props system (self-registering module with dedicated events)
import { StorePropsEventTypes, type StorePropsSetupRequestEvent } from './props'
import type { SteamGameData } from './game-box/types/GameData'
import { StartupEventTracker, StartupPhase } from '../utils/StartupEventTracker'
import { SharedMaterialManager } from '../utils/SharedMaterialManager'
import { GameSorter } from './categorization/GameSorter'
import { SceneSignManager } from './SceneSignManager'

export interface SceneCoordinatorConfig {
    environment?: {
        skyboxPreset?: string
        roomSize?: { width: number, depth: number, height: number }
        proceduralTextures?: boolean
    }
    props?: {
        enableTestObjects?: boolean
    }
    tests?: Record<string, string>
}

export class SceneCoordinator {
    private sceneManager: SceneManager
    private skyboxManager: SkyboxManager
    private lightingRenderer: LightingRenderer
    private roomManager: RoomManager
    private dataManager: DataManager
    private eventManager: EventManager
    private gameSorter: GameSorter
    private sceneSignManager: SceneSignManager

    constructor(sceneManager?: SceneManager) {
        // TODO: DI tho?
        this.sceneManager = sceneManager ?? new SceneManager()
        this.dataManager = DataManager.getInstance() // Fallback for backward compatibility
        this.eventManager = EventManager.getInstance() // DI injection with fallback

        // Store props handlers are now self-registering via module import

        // Initialize visual system renderers
        this.skyboxManager = new SkyboxManager()
        this.lightingRenderer = new LightingRenderer(
            this.sceneManager.getScene(),
            this.sceneManager.getRenderer()
        )
        // Initialize room manager for event-driven room structure (retrieves scene from DataManager)
        this.roomManager = new RoomManager()
        this.gameSorter = new GameSorter()
        this.sceneSignManager = SceneSignManager.instance

        // Track WorldBuild phase ΓÇö opens here, closes when props complete
        const tracker = StartupEventTracker.getInstance()
        tracker.phaseStart(StartupPhase.WorldBuild, 'Building 3D environment')

        // Listen for props setup completion to end WorldBuild and emit SceneReady
        this.eventManager.registerEventHandler(StorePropsEventTypes.SetupCompleted, async () => {
            tracker.phaseEnd(StartupPhase.WorldBuild)
            tracker.milestone(StartupPhase.WorldBuild, 'Scene fully constructed')

            // Lighting upgrades automatically via SetupCompleted handler natively

            this.eventManager.emit(GameEventTypes.SceneReady, {})
        })

        // NOTE: Scene setup is now DEFERRED - call startSceneSetup() explicitly after controls are ready
        // This allows the user to move around while the world builds in the background

        if(window) {
            (window as any).debugListSceneObjects = this.debugListSceneObjects.bind(this);
        }
    }

    /**
     * Start scene setup asynchronously - call this AFTER controls are ready
     * This allows the user to move around while the world builds in the background
     */
    public startSceneSetup(): void {
        // yo do an event registration instead?
        // Use setTimeout(0) to yield to main thread before starting heavy work
        // This ensures the render loop has started and user can see/interact
        setTimeout(() => {
            this.loadEnhancedScene()
        }, 0)
    }

    private async loadEnhancedScene(config: SceneCoordinatorConfig['environment'] = {}): Promise<void> {
        const tracker = StartupEventTracker.getInstance()

        // Kick off procedural material generation now, fire-and-forget.
        // RoomManager and shelf renderers will receive flat-colour fallback materials
        // immediately via getMaterial(), and upsertMaterial() will swap in the textured
        // version once the worker resolves ΓÇö no blocking, no warning.
        SharedMaterialManager.getInstance().generateTexturesAsync()

        try {
            // TODO: Skyboxmanager responds to ready event itself
            tracker.milestone(StartupPhase.WorldBuild, 'Creating sky')
            const presetName = config.skyboxPreset ?? 'aurora'
            const preset = (SkyboxPresets as any)[presetName] || SkyboxPresets.aurora
            await this.skyboxManager.applySkybox(preset)

        } catch (error) {
            console.warn('ΓÜá∩╕Å Skybox loading failed:', error)
        }

        // ≡ƒÅ¬ Props (room, shelves, games ΓÇö the heavy stuff)
        tracker.milestone(StartupPhase.WorldBuild, 'Building store')
        this.requestPropsSetup()

    }

    private requestPropsSetup(): void {
        // Simply emit the setup request - handlers will get dependencies themselves
        this.eventManager.emit<StorePropsSetupRequestEvent>(StorePropsEventTypes.SetupRequest, {
            config: {
                enableShelves: true,
                enableGameBoxes: true,
                enableSignage: true
            }
        })
    }

    /**
     * Debug function to list all objects in the scene by name
     * Useful for hunting down duplicate environment objects
     */
    public debugListSceneObjects(): void {
        console.log('\n≡ƒöì === SCENE OBJECT DEBUG LIST ===')
        console.log(`≡ƒôè Total scene children: ${this.sceneManager.getScene().children.length}`)

        const listObjects = (obj: THREE.Object3D, indent: string = '') => {
            const name = obj.name || `<unnamed-${obj.type}>`
            const type = obj.type
            const childCount = obj.children.length
            const position = `(${obj.position.x.toFixed(2)}, ${obj.position.y.toFixed(2)}, ${obj.position.z.toFixed(2)})`

            console.log(`${indent}≡ƒôª ${name} [${type}] ${position} ${childCount > 0 ? `(${childCount} children)` : ''}`)

            if (obj.children.length > 0) {
                obj.children.forEach(child => {
                    listObjects(child, indent + '  ')
                })
            }
        }

        this.sceneManager.getScene().children.forEach(obj => {
            listObjects(obj)
        })

        console.log('=== END SCENE OBJECT LIST ===\n')
    }

    dispose(): void {
        this.skyboxManager.dispose()
        this.lightingRenderer.dispose()
        this.roomManager.dispose()
    }

    private analyzeTaxonomies(): void {
        // Get game data from DataManager instead of event
        const games = this.dataManager.get<SteamGameData[]>('steam.games') || []

        // Playtime-based taxonomies
        const playtimeBuckets = {
            unplayed: games.filter(g => g.playtime_forever === 0),
            lightly: games.filter(g => g.playtime_forever > 0 && g.playtime_forever < 600), // < 10 hours (in minutes)
            moderately: games.filter(g => g.playtime_forever >= 600 && g.playtime_forever < 3000), // 10-50 hours
            heavily: games.filter(g => g.playtime_forever >= 3000) // 50+ hours
        }

        console.log(`PLAYTIME CATEGORIES for your ${games.length} games:`)
        console.log(`   ΓÇó Unplayed: ${playtimeBuckets.unplayed.length} games`)
        console.log(`   ΓÇó Lightly Played (< 10h): ${playtimeBuckets.lightly.length} games`)
        console.log(`   ΓÇó Moderately Played (10-50h): ${playtimeBuckets.moderately.length} games`)
        console.log(`   ΓÇó Heavily Played (50h+): ${playtimeBuckets.heavily.length} games`)

        // Recent activity taxonomies
        const recentlyPlayed = games.filter(g => g.playtime_2weeks && g.playtime_2weeks > 0)

        console.log(`   ΓÇó Recently Played (last 2 weeks): ${recentlyPlayed.length} games`)

        // App ID ranges (can indicate release periods/publishers)
        const appIds = games.map(g => typeof g.appid === 'number' ? g.appid : parseInt(g.appid))
        const minAppId = Math.min(...appIds)
        const maxAppId = Math.max(...appIds)

        console.log(`   ΓÇó Oldest game (lowest ID): ${minAppId}`)
        console.log(`   ΓÇó Newest game (highest ID): ${maxAppId}`)

        // List some example games for context
        console.log(`\n≡ƒôï SAMPLE GAMES (first 5):`)
        games.slice(0, 5).forEach(game => {
            const hours = Math.round(game.playtime_forever / 60 * 10) / 10
            const recentHours = game.playtime_2weeks ? Math.round(game.playtime_2weeks / 60 * 10) / 10 : 0
            console.log(`   ΓÇó "${game.name}" - ${hours}h total, ${recentHours}h recent (ID: ${game.appid})`)
        })
    }
}

export const SceneLayer = {
    Interactable: 1
} as const

/**
 * Scene Coordinator - Complete 3D Scene Management and Coordination
 * 
 * This coordinator manag    private setupRenderer(options: SceneManagerOptions) { scene lifecycle and delegates
 * specific rendering tasks to specialized renderers:
 * - Three.js scene, camera, and renderer initialization
 * - Lighting and atmospheric setup
 * - Scene object management and coordination
 * - Render loop orchestration with performance monitoring
 * - Integration point for GameBoxRenderer, SignageRenderer, etc.
 * 
 * The App should only need to call high-level methods like setupScene()
 * and should not need direct access to individual renderers.
 */

import * as THREE from 'three'
import { RectAreaLightUniformsLib } from 'three/examples/jsm/lights/RectAreaLightUniformsLib.js'
import { BlockbusterColors } from '../utils/Colors'
import { SkyboxManager, SkyboxPresets } from './SkyboxManager'
import { PropRenderer } from './PropRenderer'
import { DataManager } from '../core/data/DataManager'
import { DataDomain, DataKey } from '../core/data/DataTypes'
import { RenderLoopRegistry } from './RenderLoopRegistry'
import { FrameBudgetScheduler } from '../utils/FrameBudgetScheduler'
import { ThreeWebGLRendererDebug } from '../debug/ThreeWebGLRendererDebug'

export interface SceneManagerOptions {
    antialias?: boolean
    outputColorSpace?: THREE.ColorSpace
}

export class SceneManager {
    private scene: THREE.Scene
    private camera: THREE.PerspectiveCamera
    private renderer: THREE.WebGLRenderer
    private propRenderer: PropRenderer | null = null
    private skyboxManager: SkyboxManager
    private renderLoopRegistry: RenderLoopRegistry

    constructor(options: SceneManagerOptions = {}) {
        // Initialize RectAreaLight uniforms (required for RectAreaLight to work)
        RectAreaLightUniformsLib.init()

        // Initialize Three.js components
        this.scene = new THREE.Scene()

        DataManager.getInstance().set('core.mainScene', this.scene, {
            domain: DataDomain.Scene
        })

        // Camera Configuration
        // FOV (Field of View): Vertical angle in degrees
        //   - Narrow (45-60┬░): Telephoto effect, less distortion, focused view
        //   - Normal (60-75┬░): Standard perspective, natural look
        //   - Wide (75-90┬░): Wider view, more peripheral vision (better for VR)
        //   - Ultra-wide (90-120┬░): Fisheye effect, maximum awareness but distortion
        // Aspect Ratio: Width/height ratio (auto-calculated from window)
        // Near Clipping Plane: Closest visible distance (smaller = can see closer objects)
        //   - Too small (<0.01): Z-fighting and precision issues
        //   - Too large (>1): Nearby objects disappear
        // Far Clipping Plane: Furthest visible distance
        //   - Too small: Objects pop out of view too soon
        //   - Too large (>10000): Reduces depth buffer precision
        // 70 deg: good flatscreen default. VR headsets use 90-110 but that causes
        // fisheye edge distortion on a flat monitor. When WebXR is active, the
        // headset takes over projection entirely so this value only affects desktop view.
        const CAMERA_FOV = 70;
        const CAMERA_ASPECT = window.innerWidth / window.innerHeight;
        const CAMERA_NEAR_DIST = 0.1;
        const CAMERA_FAR_DIST = 1000;
        this.camera = new THREE.PerspectiveCamera(CAMERA_FOV, CAMERA_ASPECT, CAMERA_NEAR_DIST, CAMERA_FAR_DIST)

        // Store camera in DataManager for access by other systems (e.g., camera settings panel)
        DataManager.getInstance().set(DataKey.MainCamera, this.camera, {
            domain: DataDomain.Scene
        })

        // Swap ThreeWebGLRendererDebug Γåö THREE.WebGLRenderer to toggle shader-compile
        // logging and slow-frame warnings. Both are identical at the type level.
        this.renderer = new ThreeWebGLRendererDebug({ antialias: options.antialias ?? true })
        // this.renderer = new THREE.WebGLRenderer({ antialias: options.antialias ?? true })

        DataManager.getInstance().set(DataKey.Renderer, this.renderer, {
            domain: DataDomain.Scene
        })

        // PropRenderer creation deferred to avoid blocking startup
        // Will be created on first use by LightingRenderer

        // Initialize skybox manager (retrieves scene from DataManager)
        this.skyboxManager = new SkyboxManager()

        // Initialize render loop registry
        this.renderLoopRegistry = RenderLoopRegistry.getInstance()

        this.setupRenderer(options)
        this.setupCamera()
        this.setupEventListeners()

        // Initialize skybox asynchronously (non-blocking)
        this.initializeSkybox()
    }

    /**
     * Initialize skybox asynchronously - called during construction
     */
    private async initializeSkybox(): Promise<void> {
        try {
            await this.skyboxManager.applySkybox(SkyboxPresets.aurora)
        } catch (error) {
            console.error('Failed to apply skybox, using default:', error)
            // Ultimate fallback to current gold color if something goes wrong
            this.scene.background = new THREE.Color(BlockbusterColors.walls)
        }
    }

    private setupRenderer(options: SceneManagerOptions) {
        this.renderer.setSize(window.innerWidth, window.innerHeight)
        this.renderer.setPixelRatio(window.devicePixelRatio)
        this.renderer.outputColorSpace = options.outputColorSpace ?? THREE.SRGBColorSpace

        // Enable WebXR
        this.renderer.xr.enabled = true

        document.body.appendChild(this.renderer.domElement)
    }

    private setupCamera() {
        // Position camera at average human eye height
        this.camera.position.set(0, 1.6, 0)
    }

    private setupEventListeners() {
        // Handle window resize
        window.addEventListener('resize', () => {
            this.camera.aspect = window.innerWidth / window.innerHeight
            this.camera.updateProjectionMatrix()
            this.renderer.setSize(window.innerWidth, window.innerHeight)
        })
    }

    public startRenderLoop() {
        let lastTime = performance.now()
        const scheduler = FrameBudgetScheduler.getInstance()

        this.renderer.setAnimationLoop(() => {
            const now = performance.now()
            const deltaTime = now - lastTime
            lastTime = now

            // Update frame budget scheduler (tracks frame times, processes pending tasks)
            scheduler.onFrameStart(now)

            // Execute all registered render loop callbacks
            this.renderLoopRegistry.executeAll(now, deltaTime)

            this.renderer.render(this.scene, this.camera)
        })
    }

    public stopRenderLoop() {
        this.renderer.setAnimationLoop(null)
    }

    // Atmospheric Props Methods (Phase 2.4)

    // Getters for accessing Three.js components
    public getScene(): THREE.Scene {
        return this.scene
    }

    public getCamera(): THREE.PerspectiveCamera {
        return this.camera
    }

    public getRenderer(): THREE.WebGLRenderer {
        return this.renderer
    }

    /**
     * Get PropRenderer (creates it if needed)
     */
    public getPropRenderer(): PropRenderer {
        if (!this.propRenderer) {
            this.propRenderer = new PropRenderer(this.scene)
        }
        return this.propRenderer
    }

    public dispose() {
        this.stopRenderLoop()
        this.skyboxManager.dispose()
        if (this.propRenderer) {
            this.propRenderer.dispose()
        }
        this.renderer.dispose()
        document.body.removeChild(this.renderer.domElement)
    }
}

