import { SceneSignManager } from './SceneSignManager'

describe('SceneSignManager above-shelf mount math', () => {
  beforeEach(() => {
    EventManager.getInstance().removeAllListeners()
    mockScene.clear()
    createSignMock.mockImplementation((config: { position: THREE.Vector3 }) => {
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial())
      mesh.position.copy(config.position)
      return mesh
    })
  })

  it('applies frontOffset along signFacingY and writes mesh.rotation.y', () => {
    const manager = new SceneSignManager()
    const anchor = new THREE.Vector3(10, 2, -5)
    const signFacingY = Math.PI / 2
    const frontOffset = 0.3

    const mesh = manager.setSign({
      label: 'Played This Week',
      anchorPosition: anchor,
      mount: {
        style: 'above-shelf',
        yOffset: 0.2,
        frontOffset,
        signFacingY,
      },
    })

    expect(mesh.position.x).toBeCloseTo(anchor.x + Math.sin(signFacingY) * frontOffset, 6)
    expect(mesh.position.y).toBeCloseTo(anchor.y + 0.2, 6)
    expect(mesh.position.z).toBeCloseTo(anchor.z + Math.cos(signFacingY) * frontOffset, 6)
    expect(mesh.rotation.y).toBeCloseTo(signFacingY, 6)

    manager.dispose()
  })

  it('places recently-played and time-bucket signs from GamesSort + ShelfReady', () => {
    const manager = new SceneSignManager()
    const events = EventManager.getInstance()

    const game: SteamGameData = {
      appid: 42,
      name: 'Half-Life 3',
      playtime_forever: 120,
      rtime_last_played: Math.floor(Date.now() / 1000) - 3600,
      img_icon_url: '',
      img_logo_url: '',
    } as SteamGameData

    events.emit<GamesSortEvent>(GameEventTypes.GamesSort, {
      sortedGames: [game],
      buckets: new Map([[1, 'Played Today']]),
    })

    events.emit<ShelfReadyEvent>(StorePropsEventTypes.ShelfReady, {
      batchIndex: 0,
      position: new THREE.Vector3(0, 0, -5),
      rotationY: 0,
    })

    expect(createSignMock.mock.calls.length).toBeGreaterThanOrEqual(2)
    const positions = createSignMock.mock.calls.map(([config]) => config.position as THREE.Vector3)
    expect(positions.some((p) => Math.abs(p.y - (3.2 - 0.5)) < 0.001)).toBe(true)

    manager.dispose()
  })
})

/**
 * SceneSignManager
 *
 * Generic scene-space sign system for category labels.
 * Tech debt link: docs/roadmaps/tech-debt.md ΓåÆ "Category System Tech Debt / SceneSignManager ΓåÆ SceneSignManager rename"
 *
 * A "sign" is a canvas-texture plane mesh with configurable:
 * - Text and color
 * - Mount style: above-shelf, wall-mounted, ceiling-hung
 *
 * This sits on top of SignageRenderer's createSign() primitive.
 * Visual styles (Blockbuster, neon, flat, etc.) are applied by passing
 * a SignStyle config. Multiple realizations share one code path.
 *
 * Phase 1: above-shelf signs only.
 * Phase 2: wall + ceiling mount styles.
 */

import * as THREE from 'three'
import { DataManager } from '../core/data/DataManager'
import { DataKey } from '../core/data/DataTypes'
import { EventManager } from '../core/EventManager'
import { SignageRenderer, type SignageConfig } from './SignageRenderer'
import {
    GameEventTypes,
    StorePropsEventTypes,
    type ShelfReadyEvent,
} from '../types/InteractionEvents'
import type { GamesSortEvent } from '../types/EnvironmentEvents'
import { RecentlyPlayedBucket } from './categorization/GameSorter'
import type { SteamGameData } from './game-box/types/GameData'
import { ShelfSurfaceUtils } from './props/shared/ShelfSurfaceUtils'
import {
    shelfBucket,
    shouldPlaceBucketSign,
    bucketSignAnchor,
    recentlyPlayedCeilingAnchor,
    bucketDisplayLabel,
} from './signs/TimeBucketSignHelpers'

// ΓöÇΓöÇΓöÇ Style definitions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface SignStyle {
    backgroundColor: number
    textColor: number
    width: number
    height: number
}

export const SignStyles = {
    /** Default Blockbuster-style blue sign */
    Category: {
        backgroundColor: 0x1a3a5c,
        textColor: 0xffffff,
        width: 2.2,
        height: 0.38,
    } satisfies SignStyle,

    /** Accent color ΓÇö for featured/highlighted sections */
    Featured: {
        backgroundColor: 0x8b0000,
        textColor: 0xffffff,
        width: 2.2,
        height: 0.38,
    } satisfies SignStyle,

    /** Small orientation/debug label */
    ShelfEndLabel: {
        backgroundColor: 0x2a2a2a,
        textColor: 0xffffff,
        width: 0.4,
        height: 0.25,
    } satisfies SignStyle,
} as const

// ΓöÇΓöÇΓöÇ Mount styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export type SignMountStyle = 'above-shelf' | 'wall' | 'ceiling'

export interface SignMount {
    style: SignMountStyle
    /**
     * Y offset from the mount anchor point.
     * For above-shelf: offset above the shelf top (default 0.3m).
     * For ceiling: offset below ceiling plane.
     * For wall: offset from wall surface.
     */
    yOffset?: number
    /**
     * For above-shelf mounts, push sign out from shelf face.
     * Uses signFacingY to compute local face direction.
     */
    frontOffset?: number
    /**
     * Yaw (radians) the sign should face.
     * Useful for curved/arc layouts where shelves are rotated.
     */
    signFacingY?: number
}

// ΓöÇΓöÇΓöÇ Category sign descriptor ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Geometry of the topmost surface of a shelf unit, used to anchor end-cap labels. */
export interface ShelfTopSurface {
    centerX: number
    topY: number
    /** Z extent furthest from the player (back face). */
    backZ: number
    /** Z extent closest to the player (front face). */
    frontZ: number
    width: number
}

export interface CategorySignDescriptor {
    label: string
    text?: string   // display text ΓÇö defaults to label if omitted
    anchorPosition: THREE.Vector3   // World position to anchor sign to (e.g. shelf center)
    mount: SignMount
    style?: SignStyle
}

// ΓöÇΓöÇΓöÇ Sign kind ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Discriminates what role a sign plays in the scene.
 * Used for targeted clear/query operations (e.g. clear only bucket signs).
 * Future sign types (neon tube, end-of-aisle topper, etc.) extend this union.
 */
export type SignKind =
    | 'category'    // generic named category label
    | 'bucket'      // time-bucket section divider
    | 'ceiling'     // ceiling-hung feature sign (e.g. Recently Played)
    | 'end-cap'     // orientation end-cap label on a shelf unit

// ΓöÇΓöÇΓöÇ Internal storage record ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface SignRecord {
    mesh: THREE.Mesh
    kind: SignKind
    /** Geometry dimensions ΓÇö cached so we can skip geometry recreation on same-size updates. */
    width: number
    height: number
}

// ΓöÇΓöÇΓöÇ System ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

// TODO(signage): split bucket-transition + anchor-placement helpers into dedicated modules when we do the SceneSignManager slimming pass.
export class SceneSignManager {
    private static _instance: SceneSignManager | null = null

    /** Shared instance for scene-level sign management. */
    static get instance(): SceneSignManager {
        if (!SceneSignManager._instance) {
            SceneSignManager._instance = new SceneSignManager()
        }
        return SceneSignManager._instance
    }

    private readonly renderer: SignageRenderer
    private readonly scene: THREE.Scene
    private readonly signs: Map<string, SignRecord> = new Map()
    private readonly shelfTransforms = new Map<number, { position: THREE.Vector3; rotationY: number }>()
    private readonly timeBucketSignLabels = new Set<string>()
    private sortedGames: ReadonlyArray<Readonly<SteamGameData>> = []
    private buckets: ReadonlyMap<number | string, string> = new Map()
    private lastPlacedBucket: RecentlyPlayedBucket | null = null

    /** True when any game has recent-play metadata (rtime_last_played > 0). */
    private get hasRecentlyPlayedData(): boolean {
        return this.sortedGames.some(game => (game.rtime_last_played ?? 0) > 0)
    }

    private static readonly ABOVE_SHELF_DEFAULT_Y_OFFSET = 0.6
    private static readonly SIGN_Z_FACE_PLAYER = 0.01 // slight forward push to avoid z-fighting

    // Tech debt link: docs/roadmaps/tech-debt.md ΓåÆ
    // - "Category System Tech Debt / SceneSignManager: scene access pattern / SceneManager"
    // - "Category System Tech Debt / SignageRenderer: singleton vs instance"
    constructor() {
        this.scene = DataManager.getInstance().get<THREE.Scene>(DataKey.MainScene)
        this.renderer = new SignageRenderer()

        // Self-subscribe to shelf creation events to place end-cap labels automatically.
        // This keeps sign placement logic where it belongs ΓÇö in the sign manager.
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.ShelfReady,
            (event: CustomEvent<ShelfReadyEvent>) => this.handleShelfCreated(event.detail)
        )

        EventManager.getInstance().registerEventHandler(
            GameEventTypes.GamesSort,
            (event: CustomEvent<GamesSortEvent>) => this.handleGamesSort(event.detail)
        )
    }

    private handleShelfCreated(detail: ShelfReadyEvent): void {
        const { position, rotationY, batchIndex } = detail
        const rotY = rotationY ?? 0
        const shelfPos = position as THREE.Vector3
        const shelfId = batchIndex

        const shelfSurfaces = ShelfSurfaceUtils.findShelfSurfaces(null, true)
        const topSurface = shelfSurfaces[0]
        if (topSurface) {
            this.placeShelfEndCapLabels(batchIndex, shelfPos, rotY, topSurface)
        }

        this.shelfTransforms.set(shelfId, { position: shelfPos.clone(), rotationY: rotY })

        if (this.hasRecentlyPlayedData && this.sortedGames.length > 0) {
            this.placeTimeBucketSignForShelf(shelfId, shelfPos, rotY)
        }
    }

    private handleGamesSort(detail: GamesSortEvent): void {
        this.sortedGames = detail.sortedGames
        this.buckets = detail.buckets
        this.lastPlacedBucket = null
        this.clearTimeBucketSigns()
        this.syncRecentlyPlayedCeilingSign()
        this.replayTimeBucketSignsFromCreatedShelves()
    }

    /**
     * Create or update a named sign.
     *
     * If a sign with this label already exists:
     * - Same geometry dimensions ΓåÆ texture is re-baked in place (geometry reused).
     * - Different dimensions ΓåÆ geometry is replaced; old one disposed.
     * - Position / rotation are always updated.
     */
    public setSign(descriptor: CategorySignDescriptor, kind: SignKind = 'category'): THREE.Mesh {
        const style = descriptor.style ?? SignStyles.Category
        const signPos = this.resolvePosition(descriptor.anchorPosition, descriptor.mount)
        const text = descriptor.text ?? descriptor.label

        const existing = this.signs.get(descriptor.label)

        if (existing) {
            // ΓöÇΓöÇ Recycle path ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
            const mesh = existing.mesh
            const mat = mesh.material as THREE.MeshStandardMaterial

            // Re-bake texture unconditionally (text or colors may have changed)
            mat.map?.dispose()
            mat.map = this.renderer.bakeTexture(text, style.backgroundColor, style.textColor)
            mat.needsUpdate = true

            // Replace geometry only if dimensions changed
            if (existing.width !== style.width || existing.height !== style.height) {
                mesh.geometry.dispose()
                mesh.geometry = new THREE.PlaneGeometry(style.width, style.height)
                existing.width = style.width
                existing.height = style.height
            }

            mesh.position.copy(signPos)
            this.applySignFacing(mesh, descriptor.mount)

            return mesh
        }

        // ΓöÇΓöÇ Create path ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        const config: SignageConfig = {
            text,
            position: signPos,
            backgroundColor: style.backgroundColor,
            textColor: style.textColor,
            width: style.width,
            height: style.height,
        }

        const mesh = this.renderer.createSign(config)
        mesh.userData.categoryLabel = descriptor.label
        mesh.userData.mountStyle = descriptor.mount.style
        mesh.userData.signKind = kind

        this.applySignFacing(mesh, descriptor.mount)

        this.scene.add(mesh)
        this.signs.set(descriptor.label, { mesh, kind, width: style.width, height: style.height })

        return mesh
    }

    /** Remove a named sign from the scene, disposing all GPU resources. */
    public removeSign(label: string): void {
        const record = this.signs.get(label)
        if (record) {
            this.scene.remove(record.mesh)
            const mat = record.mesh.material as THREE.MeshStandardMaterial
            mat.map?.dispose()
            mat.dispose()
            record.mesh.geometry.dispose()
            this.signs.delete(label)
        }
    }

    /** Remove all signs of a given kind. */
    public clearByKind(kind: SignKind): void {
        for (const [label, record] of this.signs) {
            if (record.kind === kind) this.removeSign(label)
        }
    }

    /**
     * Place FRONT/BACK orientation end-cap labels on a shelf unit.
     * Called on ShelfReady so labels describe shelf geometry, not game content.
     */
    public placeShelfEndCapLabels(
        shelfIndex: number,
        position: THREE.Vector3,
        rotY: number,
        surface: ShelfTopSurface
    ): void {
        const yAxis = new THREE.Vector3(0, 1, 0)
        const labelX = surface.centerX + (surface.width / 2) - 0.15
        const labelY = surface.topY + 0.1

        // Both local positions are rotated by the shelf's own rotY (not the sign facing)
        // so they correctly map to world space regardless of shelf orientation.
        // signFacingY controls which direction the sign face points.
        this.placeEndCapLabel(
            `shelf-front-label-${shelfIndex}`, 'FRONT',
            new THREE.Vector3(labelX, labelY, surface.backZ),
            position, rotY,
            rotY,          // sign face matches shelf facing
            yAxis
        )
        this.placeEndCapLabel(
            `shelf-back-label-${shelfIndex}`, 'BACK',
            new THREE.Vector3(labelX, labelY, surface.frontZ),
            position, rotY,
            rotY + Math.PI, // sign faces the opposite direction (back side)
            yAxis
        )
    }

    private placeEndCapLabel(
        label: string,
        text: string,
        localPos: THREE.Vector3,
        shelfOrigin: THREE.Vector3,
        shelfRotY: number,
        signFacingY: number,
        yAxis: THREE.Vector3
    ): void {
        const worldPos = localPos.clone().applyAxisAngle(yAxis, shelfRotY).add(shelfOrigin)
        this.setSign({
            label,
            text,
            anchorPosition: worldPos,
            mount: { style: 'above-shelf', yOffset: 0, signFacingY },
            style: SignStyles.ShelfEndLabel
        }, 'end-cap')
    }

    private applySignFacing(mesh: THREE.Mesh, mount: SignMount): void {
        if (mount.signFacingY !== undefined) {
            mesh.rotation.y = mount.signFacingY
        }
    }

    public clearAll(): void {
        for (const label of [...this.signs.keys()]) {
            this.removeSign(label)
        }
        this.timeBucketSignLabels.clear()
        this.lastPlacedBucket = null
    }

    /** Read-only snapshot of all signs, keyed by label. Useful for tests/debug. */
    public getSignsByKind(kind: SignKind): ReadonlyMap<string, THREE.Mesh> {
        const result = new Map<string, THREE.Mesh>()
        for (const [label, record] of this.signs) {
            if (record.kind === kind) result.set(label, record.mesh)
        }
        return result
    }

    public dispose(): void {
        this.clearAll()
        this.shelfTransforms.clear()
        this.sortedGames = []
        this.buckets = new Map()
        this.renderer.dispose()
    }

    private syncRecentlyPlayedCeilingSign(): void {
        const label = 'Recently Played'
        if (!this.hasRecentlyPlayedData) {
            this.removeSign(label)
            return
        }

        this.setSign({
            label,
            anchorPosition: recentlyPlayedCeilingAnchor(),
            mount: {
                style: 'ceiling',
                signFacingY: 0,
            },
            style: {
                backgroundColor: 0xd4a017,
                textColor: 0x003087,
                width: 4.0,
                height: 0.65,
            },
        }, 'ceiling')
    }

    private replayTimeBucketSignsFromCreatedShelves(): void {
        if (!this.hasRecentlyPlayedData || this.sortedGames.length === 0 || this.shelfTransforms.size === 0) {
            return
        }

        const sortedShelves = [...this.shelfTransforms.entries()].sort((a, b) => a[0] - b[0])
        for (const [shelfId, transform] of sortedShelves) {
            this.placeTimeBucketSignForShelf(shelfId, transform.position, transform.rotationY)
        }
    }

    private placeTimeBucketSignForShelf(shelfId: number, shelfPosition: THREE.Vector3, shelfRotationY: number): void {
        const bucket = shelfBucket(shelfId, this.sortedGames)
        const ceilingAnchor = recentlyPlayedCeilingAnchor()

        if (!shouldPlaceBucketSign(bucket, this.lastPlacedBucket, shelfPosition, ceilingAnchor)) {
            return
        }

        // bucket is non-null here (shouldPlaceBucketSign guarantees it)
        const label = bucketDisplayLabel(bucket!)
        const anchor = bucketSignAnchor(shelfPosition)

        this.setSign({
            label,
            anchorPosition: anchor,
            mount: {
                style: 'above-shelf',
                yOffset: 0,
                frontOffset: 0.28,
                signFacingY: shelfRotationY,
            },
            style: { ...SignStyles.Category, width: 1.8, height: 0.32 },
        }, 'bucket')
        this.timeBucketSignLabels.add(label)
        this.lastPlacedBucket = bucket!
    }

    private clearTimeBucketSigns(): void {
        this.clearByKind('bucket')
        this.timeBucketSignLabels.clear()
    }

    // ΓöÇΓöÇΓöÇ Position resolution ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    private resolvePosition(anchor: THREE.Vector3, mount: SignMount): THREE.Vector3 {
        switch (mount.style) {
            case 'above-shelf': {
                const yOff = mount.yOffset ?? SceneSignManager.ABOVE_SHELF_DEFAULT_Y_OFFSET
                const facingY = mount.signFacingY ?? Math.PI
                const frontOff = mount.frontOffset ?? SceneSignManager.SIGN_Z_FACE_PLAYER
                return new THREE.Vector3(
                    anchor.x + Math.sin(facingY) * frontOff,
                    anchor.y + yOff,
                    anchor.z + Math.cos(facingY) * frontOff
                )
            }
            case 'wall': {
                // TD: wall mount position resolution ∩┐╜ needs nearest wall Z (defer to SceneManager pass)
                const yOff = mount.yOffset ?? 0
                return new THREE.Vector3(anchor.x, anchor.y + yOff, anchor.z)
            }
            case 'ceiling': {
                // Ceiling mount: caller sets anchor.y directly to the desired sign height
                // (e.g. ceiling height minus drop). yOffset is not applied here.
                const facingY = mount.signFacingY ?? 0
                const frontOff = mount.frontOffset ?? 0
                return new THREE.Vector3(
                    anchor.x + Math.sin(facingY) * frontOff,
                    anchor.y,
                    anchor.z + Math.cos(facingY) * frontOff
                )
            }
        }
    }
}

/**
 * ShelfSectionPlanner
 *
 * Accumulates game data across progressive batches, then places
 * category signs in one pass after all batches complete.
 *
 * Signs appear only after planSections() ∩┐╜ no provisional signs during load.
 * planSections() is re-runnable: safe to call after filter/sort changes.
 */

import * as THREE from 'three'
import { EventManager } from '../core/EventManager'
import { StorePropsEventTypes, type BatchReadyForPlacementEvent } from '../types/InteractionEvents'
import { groupByGenre, KNOWN_GENRES, type ShelfGroup } from './categorization/GameSortFunctions'
import { SceneSignManager, type SignMount } from './SceneSignManager'
import type { SteamGameData } from './game-box/types/GameData'
import { Logger } from '../utils/Logger'

export interface ShelfSectionPlannerConfig {
    signYOffset?: number
    signMountStyle?: SignMount['style']
}

const DEFAULT_SIGN_Y_OFFSET = 2.2
const DEFAULT_MOUNT_STYLE: SignMount['style'] = 'above-shelf'

export class ShelfSectionPlanner {
    private static readonly logger = Logger.createLogFunctions(ShelfSectionPlanner.name)

    private get signSystem(): SceneSignManager { return SceneSignManager.instance }
    private readonly config: Required<ShelfSectionPlannerConfig>

    private games: SteamGameData[] = []

    constructor(config: ShelfSectionPlannerConfig = {}) {
        this.config = {
            signYOffset: config.signYOffset ?? DEFAULT_SIGN_Y_OFFSET,
            signMountStyle: config.signMountStyle ?? DEFAULT_MOUNT_STYLE,
        }
        // Self-register for batch events so callers don't need to invoke onBatchPlaced
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.BatchReadyForPlacement,
            this.handleBatchReady.bind(this)
        )
    }

    /** Accumulate games from one batch. Called from event handler; private by design. */
    private onBatchPlaced(games: readonly SteamGameData[]): void {
        this.games.push(...games)
    }

    private handleBatchReady(event: CustomEvent<BatchReadyForPlacementEvent>): void {
        this.onBatchPlaced(event.detail.games as readonly SteamGameData[])
    }

    /**
     * Place all category signs using the full accumulated game set.
     *
     * Each genre group is anchored to the shelf where its games start
     * in the playtime-sorted order. A minimum-advance rule ensures each
     * group gets a unique shelf even when multiple small groups would
     * otherwise map to the same position.
     *
     * "Other" is skipped ∩┐╜ it's a catch-all for tools/dedicated servers
     * and adds no navigation value as a section sign.
     */
    public planSections(shelfPositions: THREE.Vector3[]): void {
        if (this.games.length === 0) {
            ShelfSectionPlanner.logger.warn('planSections called with no games ∩┐╜ skipping')
            return
        }
        if (shelfPositions.length === 0) {
            ShelfSectionPlanner.logger.warn('planSections called with no shelf positions ∩┐╜ skipping')
            return
        }

        this.signSystem.clearAll()

        const groups = this.buildShelfGroups(this.games)
        ShelfSectionPlanner.logger.info(
            `[SIGN-DEBUG] planSections: ${groups.length} groups ∩┐╜ ` +
            groups.map(g => `${g.label}(${g.games.length})`).join(', ')
        )
        let placed = 0
        let gameOffset = 0
        const batchSize = 18
        let lastUsedAnchor = -1  // ensures each genre gets a unique shelf position

        for (const group of groups) {
            // Skip 'Other' ∩┐╜ catch-all for tools/servers, not useful as a section sign
            if (group.label === 'Other') {
                gameOffset += group.games.length
                continue
            }

            // Compute natural anchor from game offset, then advance past any collision
            const naturalIndex = Math.floor(gameOffset / batchSize)
            const anchorIndex = Math.min(
                Math.max(naturalIndex, lastUsedAnchor + 1),
                shelfPositions.length - 1
            )
            lastUsedAnchor = anchorIndex

            const anchorPos = shelfPositions[anchorIndex]
            if (!anchorPos) {
                ShelfSectionPlanner.logger.warn(`No shelf position for group "${group.label}" at index ${anchorIndex}`)
                gameOffset += group.games.length
                continue
            }

            this.signSystem.setSign({
                label: group.label,
                anchorPosition: anchorPos,
                mount: { style: this.config.signMountStyle, yOffset: this.config.signYOffset }
            })
            placed++
            gameOffset += group.games.length
        }

        ShelfSectionPlanner.logger.info(
            `[SIGN-DEBUG] planSections complete: placed ${placed}/${groups.length} signs ` +
            `(${this.games.length} total games, ${shelfPositions.length} shelves)`
        )
    }

    private buildShelfGroups(games: SteamGameData[]): ShelfGroup[] {
        if (games.length === 0) return []
        const grouped = groupByGenre(games)
        const shelfGroups: ShelfGroup[] = Array.from(grouped.entries()).map(([genre, groupGames]) => ({
            genre,
            label: genre,
            games: groupGames,
        }))
        shelfGroups.sort((a, b) => {
            const ai = KNOWN_GENRES.indexOf(a.genre)
            const bi = KNOWN_GENRES.indexOf(b.genre)
            if (a.genre === 'Other') return 1
            if (b.genre === 'Other') return -1
            if (ai !== -1 && bi !== -1) return ai - bi
            if (ai !== -1) return -1
            if (bi !== -1) return 1
            return b.games.length - a.games.length
        })
        return shelfGroups
    }

    public reset(): void {
        this.games = []
        this.signSystem.clearAll()
    }

    public dispose(): void {
        this.signSystem.dispose()
    }
}

