// ΓöÇΓöÇΓöÇ Recently-played bucket types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export enum RecentlyPlayedBucket {
    Today     = 'today',
    ThisWeek  = 'this-week',
    ThisMonth = 'this-month',
    ThisYear  = 'this-year',
    Before    = 'before',
    Unplayed  = 'unplayed',
}

const BUCKET_LABELS: Record<RecentlyPlayedBucket, string> = {
    [RecentlyPlayedBucket.Today]:     'Played Today',
    [RecentlyPlayedBucket.ThisWeek]:  'Played This Week',
    [RecentlyPlayedBucket.ThisMonth]: 'Played This Month',
    [RecentlyPlayedBucket.ThisYear]:  'Played This Year',
    [RecentlyPlayedBucket.Before]:    'Played Before',
    [RecentlyPlayedBucket.Unplayed]:  'Never Played',
}

export function getBucketLabel(bucket: RecentlyPlayedBucket): string {
    return BUCKET_LABELS[bucket]
}

export function getRecentlyPlayedBucket(game: SteamGameData, nowSeconds?: number): RecentlyPlayedBucket {
    const now = nowSeconds ?? Math.floor(Date.now() / 1000)
    const lastPlayed = game.rtime_last_played ?? 0
    if (lastPlayed === 0) return RecentlyPlayedBucket.Unplayed
    const diff = now - lastPlayed
    if (diff < 0) return RecentlyPlayedBucket.Today
    const DAY = 86_400
    if (diff < DAY)       return RecentlyPlayedBucket.Today
    if (diff < 7 * DAY)   return RecentlyPlayedBucket.ThisWeek
    if (diff < 30 * DAY)  return RecentlyPlayedBucket.ThisMonth
    if (diff < 365 * DAY) return RecentlyPlayedBucket.ThisYear
    return RecentlyPlayedBucket.Before
}

// ΓöÇΓöÇΓöÇ GameSorter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export class GameSorter {
    private static readonly logger = Logger.createLogFunctions(GameSorter.name)

    constructor() {
        EventManager.getInstance().registerEventHandler(
            GameEventTypes.AllBatchesComplete,
            (_event: CustomEvent<AllBatchesCompleteEvent>) => this.sortByRecentlyPlayed()
        )
        GameSorter.logger.debug('GameSorter initialized ΓÇö subscribed to AllBatchesComplete')
    }

    public sortByRecentlyPlayed(): void {
        const games = DataManager.getInstance().get<SteamGameData[]>('steam.games') ?? []

        if (games.length === 0) {
            GameSorter.logger.warn('AllBatchesComplete fired but no games in DataManager ΓÇö skipping emit')
            return
        }

        // Always include all games. rtime_last_played === 0 means "never played" ΓÇö
        // those go to RecentlyPlayedBucket.Unplayed, not dropped.
        const sortedGames: ReadonlyArray<Readonly<SteamGameData>> =
            [...games].sort(sortByNumericField<SteamGameData>('rtime_last_played', 'playtime_forever'))

        const buckets = this.buildBucketMap(sortedGames)

        EventManager.getInstance().emit<GamesSortEvent>(GameEventTypes.GamesSort, {
            sortedGames,
            buckets,
        })

        GameSorter.logger.debug(
            `GamesSort emitted: ${sortedGames.length} games, ${buckets.size} buckets`
        )
    }

    private buildBucketMap(
        sortedGames: ReadonlyArray<Readonly<SteamGameData>>
    ): ReadonlyMap<string, string> {
        const buckets = new Map<string, string>()
        for (const game of sortedGames) {
            const bucket = getRecentlyPlayedBucket(game as SteamGameData)
            if (!buckets.has(bucket)) {
                buckets.set(bucket, getBucketLabel(bucket))
            }
        }
        return buckets
    }
}

/**
 * GameBox Layout Utilities
 * 
 * Handles positioning, sorting, and layout calculations for game boxes:
 * - Game sorting by playtime and alphabetical order
 * - Position calculations for shelf layouts  
 * - Centering logic for game box arrangements
 * - Layout spacing and configuration management
 */

import type { SteamGameData } from './types/GameData'
import type { GameBoxPosition, ShelfConfiguration } from './types/GameBoxOptions'

export class GameBoxLayoutUtils {
    // TODO: Guessing at shelf offsets should be removed entirely
    public static readonly DEFAULT_SHELF_CONFIG: ShelfConfiguration = {
        surfaceY: -0.8,
        centerZ: -3,
        centerX: 0,
        spacing: 0.16
    }

    /**
     * Sort games by playtime (played games first by playtime, then unplayed alphabetically)
     */
    public static sortAndLimitGames(games: SteamGameData[]): SteamGameData[] {
        // Get games with recent playtime first, then alphabetical
        const playedGames = games
            .filter(game => GameBoxLayoutUtils.getGamePlaytime(game) > 0)
            .sort((a, b) => GameBoxLayoutUtils.getGamePlaytime(b) - GameBoxLayoutUtils.getGamePlaytime(a))
        
        // Add unplayed games alphabetically
        const unplayedGames = games
            .filter(game => GameBoxLayoutUtils.getGamePlaytime(game) === 0)
            .sort((a, b) => a.name.localeCompare(b.name))
        
        playedGames.push(...unplayedGames)
        
        return playedGames
    }

    /**
     * Calculate the starting X position to center a set of game boxes
     */
    public static calculateStartX(numBoxes: number, config: ShelfConfiguration): number {
        return -(numBoxes - 1) * config.spacing / 2
    }

    /**
     * Calculate the position for a specific game box in a linear layout
     */
    public static calculateBoxPosition(
        index: number, 
        startX: number, 
        config: ShelfConfiguration
    ): GameBoxPosition {
        return {
            x: config.centerX + startX + (index * config.spacing),
            y: config.surfaceY, // Use exact Y position calculated by StoreLayout
            z: config.centerZ    // Use exact Z position calculated by StoreLayout
        }
    }

    /**
     * Calculate positions for a batch of game boxes with centering
     */
    public static calculateBatchPositions(
        count: number,
        config: ShelfConfiguration = GameBoxLayoutUtils.DEFAULT_SHELF_CONFIG
    ): GameBoxPosition[] {
        const positions: GameBoxPosition[] = []
        const startX = GameBoxLayoutUtils.calculateStartX(count, config)
        
        for (let i = 0; i < count; i++) {
            positions.push(GameBoxLayoutUtils.calculateBoxPosition(i, startX, config))
        }
        
        return positions
    }

    /**
     * Get game playtime from Steam game data
     */
    public static getGamePlaytime(game: SteamGameData): number {
        return game.playtime_forever
    }

    /**
     * Get game ID from Steam game data
     */
    public static getGameId(game: SteamGameData): string | number {
        return game.appid
    }

    /**
     * Create a shelf configuration with custom overrides
     */
    public static createShelfConfig(overrides: Partial<ShelfConfiguration> = {}): ShelfConfiguration {
        return { ...GameBoxLayoutUtils.DEFAULT_SHELF_CONFIG, ...overrides }
    }

    /**
     * Calculate the total width required for a given number of game boxes
     */
    public static calculateTotalWidth(numBoxes: number, spacing: number): number {
        if (numBoxes <= 1) return 0
        return (numBoxes - 1) * spacing
    }

    /**
     * Calculate optimal spacing for a given number of boxes within a maximum width
     */
    public static calculateOptimalSpacing(numBoxes: number, maxWidth: number): number {
        if (numBoxes <= 1) return 0
        return Math.min(GameBoxLayoutUtils.DEFAULT_SHELF_CONFIG.spacing, maxWidth / (numBoxes - 1))
    }

    /**
     * Validate shelf configuration parameters
     */
    public static validateShelfConfig(config: ShelfConfiguration): boolean {
        return (
            typeof config.surfaceY === 'number' &&
            typeof config.centerZ === 'number' &&
            typeof config.centerX === 'number' &&
            typeof config.spacing === 'number' &&
            config.spacing > 0
        )
    }
}

/**
 * GameBox Performance Manager
 * 
 * Handles experimental performance features for game box rendering:
 * - Frustum culling for visibility optimization
 * - Distance-based texture resolution scaling
 * - Texture memory management and cleanup
 * - Performance statistics and monitoring
 * 
 * These features are designed for handling large numbers of textured game boxes.
 * Enable them when working with Steam artwork textures.
 */

import * as THREE from 'three'
import type { 
    TexturePerformanceConfig, 
    GameBoxPerformanceData, 
    PerformanceStats 
} from './types/PerformanceTypes'

export class GameBoxPerformanceManager {
    private performanceConfig: TexturePerformanceConfig
    private activeTextures: Map<string, THREE.Texture> = new Map()
    private gameBoxPerformanceData: Map<string, GameBoxPerformanceData> = new Map()
    private frustum: THREE.Frustum = new THREE.Frustum()
    private cameraMatrix: THREE.Matrix4 = new THREE.Matrix4()

    constructor(config: Partial<TexturePerformanceConfig> = {}) {
        // Initialize performance configuration with sensible defaults
        this.performanceConfig = {
            maxTextureSize: 1024,
            nearDistance: 2.0,
            farDistance: 10.0,
            highResolutionSize: 512,
            mediumResolutionSize: 256,
            lowResolutionSize: 128,
            maxActiveTextures: 50,
            frustumCullingEnabled: true,
            ...config
        }
    }

    /**
     * Get the current performance configuration
     */
    public getConfig(): TexturePerformanceConfig {
        return { ...this.performanceConfig }
    }

    /**
     * Update performance configuration
     */
    public updateConfig(config: Partial<TexturePerformanceConfig>): void {
        this.performanceConfig = { ...this.performanceConfig, ...config }
    }

    /**
     * Update performance data for all game boxes based on camera position
     * (Experimental - enable when working with many textured game boxes)
     */
    public updatePerformanceData(camera: THREE.Camera, scene: THREE.Scene): void {
        if (!this.performanceConfig.frustumCullingEnabled) return

        // Update frustum from camera
        this.cameraMatrix.multiplyMatrices(camera.projectionMatrix, camera.matrixWorldInverse)
        this.frustum.setFromProjectionMatrix(this.cameraMatrix)

        // Find all game boxes in scene
        const gameBoxes = scene.children.filter(child => 
            child.userData?.isGameBox && child instanceof THREE.Mesh
        ) as THREE.Mesh[]

        for (const gameBox of gameBoxes) {
            const gameId = gameBox.userData.gameId?.toString() ?? gameBox.userData.name ?? 'unknown'
            
            // Calculate distance from camera
            const distance = camera.position.distanceTo(gameBox.position)
            
            // Check if object is in camera frustum
            const isVisible = this.frustum.containsPoint(gameBox.position)
            
            // Update or create performance data
            const performanceData: GameBoxPerformanceData = {
                isVisible,
                distanceFromCamera: distance,
                lastUpdated: Date.now(),
                textureLoaded: gameBox.userData.textureLoaded ?? false,
                currentTextureSize: gameBox.userData.currentTextureSize ?? 0
            }
            
            this.gameBoxPerformanceData.set(gameId, performanceData)
            
            // Update game box user data
            gameBox.userData.isVisible = isVisible
            gameBox.userData.distanceFromCamera = distance
        }
    }

    /**
     * Get optimal texture resolution based on viewing distance
     * (Experimental - for dynamic texture quality)
     */
    public getOptimalTextureResolution(distance: number): number {
        const { nearDistance, farDistance, highResolutionSize, mediumResolutionSize, lowResolutionSize } = this.performanceConfig
        
        if (distance <= nearDistance) {
            return highResolutionSize
        } else if (distance <= farDistance) {
            return mediumResolutionSize
        } else {
            return lowResolutionSize
        }
    }

    /**
     * Check if a game should skip texture loading due to lazy loading rules
     */
    public shouldSkipTextureLoading(gameId: string, enableLazyLoading: boolean): boolean {
        if (!enableLazyLoading) return false
        
        const performanceData = this.gameBoxPerformanceData.get(gameId)
        return performanceData ? !performanceData.isVisible : false
    }

    /**
     * Get performance data for a specific game
     */
    public getPerformanceData(gameId: string): GameBoxPerformanceData | undefined {
        return this.gameBoxPerformanceData.get(gameId)
    }

    /**
     * Create texture at specific resolution from blob
     * (Experimental - for performance optimization)
     */
    public async createOptimizedTexture(blob: Blob, targetResolution: number): Promise<THREE.Texture> {
        return new Promise((resolve, reject) => {
            const img = new globalThis.Image()
            img.onload = () => {
                // Create canvas for resizing
                const canvas = document.createElement('canvas')
                const ctx = canvas.getContext('2d')
                
                if (!ctx) {
                    reject(new Error('Could not get canvas context'))
                    return
                }
                
                // Calculate optimal size maintaining aspect ratio
                const aspectRatio = img.width / img.height
                let width = targetResolution
                let height = targetResolution / aspectRatio
                
                if (height > targetResolution) {
                    height = targetResolution
                    width = targetResolution * aspectRatio
                }
                
                canvas.width = width
                canvas.height = height
                
                // Draw and resize image
                ctx.drawImage(img, 0, 0, width, height)
                
                // Create texture from canvas
                const texture = new THREE.CanvasTexture(canvas)
                texture.minFilter = THREE.LinearFilter
                texture.magFilter = THREE.LinearFilter
                texture.generateMipmaps = false
                
                resolve(texture)
                
                // Clean up
                URL.revokeObjectURL(img.src)
            }
            
            img.onerror = () => {
                URL.revokeObjectURL(img.src)
                reject(new Error('Failed to load image'))
            }
            
            img.src = URL.createObjectURL(blob)
        })
    }

    /**
     * Track a texture for performance management
     */
    public trackTexture(textureKey: string, texture: THREE.Texture): void {
        this.activeTextures.set(textureKey, texture)
    }

    /**
     * Get a tracked texture
     */
    public getTrackedTexture(textureKey: string): THREE.Texture | undefined {
        return this.activeTextures.get(textureKey)
    }

    /**
     * Check if we already have a suitable texture for a game
     */
    public hasSuitableTexture(gameId: string, targetResolution: number, mesh: THREE.Mesh): boolean {
        const textureKey = `${gameId}_${targetResolution}`
        const existingTexture = this.activeTextures.get(textureKey)
        return existingTexture !== undefined && mesh.userData.currentTextureSize === targetResolution
    }

    /**
     * Update performance data for a game when texture is loaded
     */
    public updateTextureLoadedData(gameId: string, textureSize: number): void {
        const performanceData = this.gameBoxPerformanceData.get(gameId)
        if (performanceData) {
            performanceData.textureLoaded = true
            performanceData.currentTextureSize = textureSize
        }
    }

    /**
     * Clean up textures for off-screen or distant objects
     * (Experimental - for memory management with many textures)
     */
    public cleanupOffScreenTextures(): void {
        const now = Date.now()
        const cleanupThreshold = 30000 // 30 seconds
        
        for (const [gameId, performanceData] of this.gameBoxPerformanceData.entries()) {
            // Clean up if object has been off-screen for a while
            if (!performanceData.isVisible && 
                (now - performanceData.lastUpdated) > cleanupThreshold &&
                performanceData.textureLoaded) {
                
                this.unloadTextureForGame(gameId)
            }
        }
        
        // Enforce maximum active texture limit
        if (this.activeTextures.size > this.performanceConfig.maxActiveTextures) {
            this.enforceTextureMemoryLimit()
        }
    }

    /**
     * Unload texture for a specific game
     * (Experimental - internal memory management)
     */
    private unloadTextureForGame(gameId: string): void {
        // Find textures for this game
        const textureKeys = Array.from(this.activeTextures.keys()).filter(key => key.startsWith(gameId))
        
        for (const key of textureKeys) {
            const texture = this.activeTextures.get(key)
            if (texture) {
                texture.dispose()
                this.activeTextures.delete(key)
                console.debug(`≡ƒº╣ Unloaded texture for off-screen game: ${gameId}`)
            }
        }
        
        // Update performance data
        const performanceData = this.gameBoxPerformanceData.get(gameId)
        if (performanceData) {
            performanceData.textureLoaded = false
            performanceData.currentTextureSize = 0
        }
    }

    /**
     * Enforce memory limits by removing least recently used textures
     * (Experimental - internal memory management)
     */
    private enforceTextureMemoryLimit(): void {
        const sortedGames = Array.from(this.gameBoxPerformanceData.entries())
            .filter(([_, data]) => data.textureLoaded)
            .sort((a, b) => a[1].lastUpdated - b[1].lastUpdated) // Sort by last updated (oldest first)
        
        const gamesToRemove = this.activeTextures.size - this.performanceConfig.maxActiveTextures
        
        for (let i = 0; i < gamesToRemove && i < sortedGames.length; i++) {
            const [gameId] = sortedGames[i]
            this.unloadTextureForGame(gameId)
        }
        
        console.log(`≡ƒº╣ Enforced texture memory limit: removed ${gamesToRemove} textures`)
    }

    /**
     * Get comprehensive performance statistics
     * (Experimental - for monitoring texture performance)
     */
    public getPerformanceStats(): PerformanceStats {
        const data = Array.from(this.gameBoxPerformanceData.values())
        const visibleData = data.filter(d => d.isVisible)
        const loadedTextures = data.filter(d => d.textureLoaded).length
        const averageDistance = data.length > 0 
            ? data.reduce((sum, d) => sum + d.distanceFromCamera, 0) / data.length 
            : 0
        
        return {
            totalGameBoxes: data.length,
            visibleGameBoxes: visibleData.length,
            loadedTextures,
            activeTextures: this.activeTextures.size,
            averageDistance
        }
    }

    /**
     * Dispose of all tracked textures and clear performance data
     */
    public dispose(): void {
        // Dispose all active textures
        for (const texture of this.activeTextures.values()) {
            texture.dispose()
        }
        
        // Clear tracking data
        this.activeTextures.clear()
        this.gameBoxPerformanceData.clear()
        
        console.log('≡ƒº╣ Disposed GameBoxPerformanceManager and all tracked textures')
    }
}

/**
 * GameBox Texture Manager
 * 
 * Handles all texture-related operations for game boxes:
 * - Texture loading from blobs
 * - Fallback texture creation and application
 * - Texture optimization and caching
 * - Integration with performance management
 */

import * as THREE from 'three'
import type { SteamGameData } from './types/GameData'
import type { GameBoxTextureOptions } from './types/GameBoxOptions'
import type { GameBoxPerformanceManager } from './GameBoxPerformanceManager'

export class GameBoxTextureManager {
    private textureLoader: THREE.TextureLoader
    private fallbackTexture: THREE.Texture | null = null
    private performanceManager?: GameBoxPerformanceManager

    constructor(performanceManager?: GameBoxPerformanceManager) {
        this.textureLoader = new THREE.TextureLoader()
        this.performanceManager = performanceManager
        this.createFallbackTexture()
    }

    /**
     * Set or update the performance manager
     */
    public setPerformanceManager(performanceManager: GameBoxPerformanceManager): void {
        this.performanceManager = performanceManager
    }

    /**
     * Apply texture to a game box mesh
     */
    public async applyTexture(
        mesh: THREE.Mesh,
        options: GameBoxTextureOptions = {}
    ): Promise<boolean> {
        // Dispose of existing texture
        if (mesh.userData.texture) {
            mesh.userData.texture.dispose()
        }
        
        const { artworkBlobs, fallbackColor, enableFallbackTexture } = options
        
        // Early return if no artwork blobs provided
        if (!artworkBlobs) {
            this.applyFallbackToMesh(mesh, fallbackColor, enableFallbackTexture)
            return false
        }

        // Try to get artwork blob (prioritize library > header > logo > icon)
        const artworkTypes = ['library', 'header', 'logo', 'icon'] as const
        let selectedBlob: Blob | null = null
        
        for (const artworkType of artworkTypes) {
            const blob = artworkBlobs[artworkType]
            if (blob) {
                selectedBlob = blob
                break
            }
        }

        if (!selectedBlob) {
            this.applyFallbackToMesh(mesh, fallbackColor, enableFallbackTexture)
            return false
        }

        try {
            const texture = await this.createTextureFromBlob(selectedBlob)
            
            // Apply texture to the game box - properly type the material
            const material = mesh.material as THREE.MeshPhongMaterial
            if (material && material instanceof THREE.MeshPhongMaterial) {
                material.map = texture
                material.color.set(0xffffff) // Reset color to white for proper texture display
                material.needsUpdate = true
                mesh.userData.texture = texture
            }
            
            return true
        } catch (error) {
            console.warn('ΓÜá∩╕Å Failed to create texture from blob:', error)
            this.applyFallbackToMesh(mesh, fallbackColor, enableFallbackTexture)
            return false
        }
    }

    /**
     * Apply texture with performance optimization
     * (Experimental - use when you need dynamic texture quality based on distance)
     */
    public async applyOptimizedTexture(
        mesh: THREE.Mesh, 
        game: SteamGameData, 
        options: GameBoxTextureOptions = {}
    ): Promise<boolean> {
        if (!this.performanceManager) {
            // Fall back to regular texture application if no performance manager
            return this.applyTexture(mesh, options)
        }

        const gameId = this.getGameId(game).toString()
        const performanceData = this.performanceManager.getPerformanceData(gameId)
        
        // Skip if not visible and lazy loading is enabled
        if (this.performanceManager.shouldSkipTextureLoading(gameId, options.enableLazyLoading ?? false)) {
            console.debug(`Skipping texture load for off-screen game: ${game.name}`)
            return false
        }
        
        // Determine optimal resolution
        const targetResolution = options.targetResolution ?? 
            this.performanceManager.getOptimalTextureResolution(
                options.viewingDistance ?? performanceData?.distanceFromCamera ?? 5.0
            )
        
        // Check if we already have a suitable texture
        if (this.performanceManager.hasSuitableTexture(gameId, targetResolution, mesh)) {
            return true
        }
        
        const { artworkBlobs, enableFallbackTexture } = options
        
        if (!artworkBlobs) {
            this.applyFallbackToMesh(mesh, options.fallbackColor, enableFallbackTexture)
            return false
        }
        
        // Try to get artwork blob (prioritize library > header > logo > icon)
        const artworkTypes = ['library', 'header', 'logo', 'icon'] as const
        let selectedBlob: Blob | null = null
        
        for (const artworkType of artworkTypes) {
            const blob = artworkBlobs[artworkType]
            if (blob) {
                selectedBlob = blob
                break
            }
        }
        
        if (!selectedBlob) {
            this.applyFallbackToMesh(mesh, options.fallbackColor, enableFallbackTexture)
            return false
        }
        
        try {
            // Create optimized texture using performance manager
            const texture = await this.performanceManager.createOptimizedTexture(selectedBlob, targetResolution)
            
            // Dispose of existing texture
            if (mesh.userData.texture) {
                mesh.userData.texture.dispose()
            }
            
            // Apply new texture
            const material = mesh.material as THREE.MeshPhongMaterial
            material.map = texture
            material.needsUpdate = true
            
            // Track texture with performance manager
            const textureKey = `${gameId}_${targetResolution}`
            this.performanceManager.trackTexture(textureKey, texture)
            
            // Update mesh user data
            mesh.userData.texture = texture
            mesh.userData.textureKey = textureKey
            mesh.userData.textureLoaded = true
            mesh.userData.currentTextureSize = targetResolution
            
            // Update performance data
            this.performanceManager.updateTextureLoadedData(gameId, targetResolution)
            
            console.log(`≡ƒû╝∩╕Å Applied optimized texture (${targetResolution}px) to: ${game.name}`)
            return true
            
        } catch (error) {
            console.warn(`ΓÜá∩╕Å Failed to create optimized texture for ${game.name}:`, error)
            this.applyFallbackToMesh(mesh, options.fallbackColor, enableFallbackTexture)
            return false
        }
    }

    /**
     * Create a Three.js texture from a Blob
     */
    private async createTextureFromBlob(blob: Blob): Promise<THREE.Texture> {
        return new Promise((resolve, reject) => {
            const objectUrl = URL.createObjectURL(blob)
            
            this.textureLoader.load(
                objectUrl,
                (texture) => {
                    // Configure texture for optimal quality
                    texture.anisotropy = Math.min(16, this.textureLoader.crossOrigin ? 16 : 4)
                    texture.wrapS = THREE.ClampToEdgeWrapping
                    texture.wrapT = THREE.ClampToEdgeWrapping
                    texture.minFilter = THREE.LinearFilter
                    texture.magFilter = THREE.LinearFilter
                    texture.needsUpdate = true
                    
                    // Clean up the object URL
                    URL.revokeObjectURL(objectUrl)
                    resolve(texture)
                },
                undefined,
                (error) => {
                    URL.revokeObjectURL(objectUrl)
                    reject(error)
                }
            )
        })
    }

    /**
     * Apply fallback appearance to a mesh
     */
    private applyFallbackToMesh(
        mesh: THREE.Mesh, 
        fallbackColor?: number, 
        enableFallbackTexture = true
    ): void {
        const material = mesh.material as THREE.MeshPhongMaterial
        
        if (enableFallbackTexture && this.fallbackTexture && material instanceof THREE.MeshPhongMaterial) {
            // Apply fallback texture pattern
            material.map = this.fallbackTexture
            material.color.set(0xffffff)
            material.needsUpdate = true
        } else if (material instanceof THREE.MeshPhongMaterial) {
            // Apply solid color fallback
            const color = fallbackColor ?? 0x808080 // Default gray
            material.map = null // Remove any existing texture
            material.color.set(color)
            material.needsUpdate = true
        }
    }

    /**
     * Create fallback texture for game boxes
     * Simple by default, can be enhanced with procedural generation
     */
    private createFallbackTexture(): void {
        const size = 128 // Reasonable balance between quality and performance
        const data = new Uint8Array(size * size * 3)
        
        // Create a subtle pattern instead of flat gray
        for (let i = 0; i < data.length; i += 3) {
            const baseColor = 120 + (Math.random() * 20 - 10) // Gray with slight variation
            data[i] = baseColor     // R
            data[i + 1] = baseColor // G
            data[i + 2] = baseColor // B
        }
        
        const texture = new THREE.DataTexture(data, size, size, THREE.RGBFormat)
        texture.needsUpdate = true
        this.fallbackTexture = texture
    }

    /**
     * Helper method to get game ID from Steam game data
     */
    private getGameId(game: SteamGameData): string | number {
        return game.appid
    }

    /**
     * Dispose of all textures and resources
     */
    public dispose(): void {
        if (this.fallbackTexture) {
            this.fallbackTexture.dispose()
            this.fallbackTexture = null
        }
        
        console.log('≡ƒº╣ Disposed GameBoxTextureManager resources')
    }
}

/**
 * Regression test: LodDistanceManager must start after AllBatchesComplete.
 *
 * Bug: GpuGameBoxRenderer created LodDistanceManager but never called
 * startAutoUpdate() or syncInstances(), so distance-based LOD switching
 * never ran. Games stayed at MID and only upgraded when spatial pre-warmer
 * happened to kick in (i.e., only on close approach).
 *
 * Fix (bc7d955): The subscription was moved INTO LodDistanceManager itself
 * (self-subscription pattern). GpuGameBoxRenderer no longer drives this;
 * LodDistanceManager registers for AllBatchesComplete
 * in its own constructor and calls syncInstances + startAutoUpdate when it fires.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { GameEventTypes } from '../../types/InteractionEvents'

// ---- minimal mocks ----
vi.mock('../../core/AppSettings', () => ({
    AppSettings: { get: vi.fn().mockReturnValue(undefined) },
    Setting: new Proxy({}, { get: (_t, k) => k }),
}))

const mockEventHandlers = new Map<string, (() => void)[]>()
vi.mock('../../core/EventManager', () => ({
    EventManager: {
        getInstance: () => ({
            registerEventHandler: vi.fn((type: string, fn: () => void) => {
                const list = mockEventHandlers.get(type) ?? []
                list.push(fn)
                mockEventHandlers.set(type, list)
            }),
        }),
    },
}))

const mockSyncInstances = vi.fn()
const mockStartAutoUpdate = vi.fn()

vi.mock('./instancing/LodDistanceManagerDebug', () => ({
    // Simulate self-subscription: the real LodDistanceManager registers for
    // AllBatchesComplete in its constructor and calls syncInstances/startAutoUpdate.
    LodDistanceManagerDebug: vi.fn().mockImplementation(function(this: Record<string, unknown>) {
        const instance = {
            syncInstances: mockSyncInstances,
            startAutoUpdate: mockStartAutoUpdate,
            dispose: vi.fn(),
        }
        const handlers = mockEventHandlers.get(GameEventTypes.AllBatchesComplete) ?? []
        handlers.push(() => {
            instance.syncInstances()
            instance.startAutoUpdate()
        })
        mockEventHandlers.set(GameEventTypes.AllBatchesComplete, handlers)
        return instance
    }),
}))
vi.mock('./instancing/LodArtworkOrchestratorDebug', () => ({
    LodArtworkOrchestratorDebug: vi.fn().mockImplementation(function() {
        return {
            setArtworkInstanceFromUrl: vi.fn(),
            getInstanceData: vi.fn().mockReturnValue(new Map()),
            getInstanceCount: vi.fn().mockReturnValue(0),
            dispose: vi.fn(),
            isReady: vi.fn().mockReturnValue(true),
        }
    }),
}))
vi.mock('./instancing/InstancedLabelRenderer', () => ({
    InstancedLabelRenderer: vi.fn().mockImplementation(function() {
        return {
            addLabelInstance: vi.fn(),
            isReady: vi.fn().mockReturnValue(true),
            dispose: vi.fn(),
        }
    }),
}))

import { GpuGameBoxRenderer } from './GpuGameBoxRenderer'

describe('GpuGameBoxRenderer - LOD distance manager lifecycle', () => {
    beforeEach(() => {
        mockEventHandlers.clear()
        mockSyncInstances.mockClear()
        mockStartAutoUpdate.mockClear()
    })

    it('registers for AllBatchesComplete in constructor', () => {
        new GpuGameBoxRenderer()
        expect(mockEventHandlers.has(GameEventTypes.AllBatchesComplete)).toBe(true)
    })

    it('does NOT start LOD distance manager before AllBatchesComplete fires', () => {
        new GpuGameBoxRenderer()
        expect(mockStartAutoUpdate).not.toHaveBeenCalled()
        expect(mockSyncInstances).not.toHaveBeenCalled()
    })

    it('syncs instances and starts auto-update when AllBatchesComplete fires', () => {
        new GpuGameBoxRenderer()
        const handlers = mockEventHandlers.get(GameEventTypes.AllBatchesComplete) ?? []
        expect(handlers).toHaveLength(1)
        handlers[0]()
        expect(mockSyncInstances).toHaveBeenCalledOnce()
        expect(mockStartAutoUpdate).toHaveBeenCalledOnce()
    })
})

/**
 * GpuGameBoxRenderer
 * 
 * ROLE: GPU-instanced rendering of game boxes with LOD (Level of Detail) support.
 * Creates and manages instanced meshes for game box geometry and artwork textures.
 * 
 * OWNS:
 * - Game box geometry and materials
 * - InstancedLabelRenderer for text labels
 * - LOD artwork orchestrator for texture management
 * - LOD distance manager for camera-based detail switching
 * - Box instance state (positions, orientations, LOD levels)
 * 
 * RECEIVES:
 * - createGameBox(request) ΓåÆ Creates box instance at position
 * - addToScene(scene) ΓåÆ Attaches instanced meshes to scene
 * - updateLODForCamera(camera) ΓåÆ Adjusts detail levels based on distance
 * - dispose() ΓåÆ Cleans up GPU resources
 * 
 * EMITS:
 * - (none currently - pure rendering)
 * 
 * DELEGATES TO:
 * - InstancedLabelRenderer: Text label rendering on boxes
 * - LodArtworkOrchestratorDebug: Texture loading, LOD management, devtools console commands
 * - LodDistanceManagerDebug: Camera distance calculations, LOD distribution diagnostics
 * 
 * DOES NOT:
 * - Know about shelves or layout (receives positions)
 * - Decide which games to display (told what to render)
 * - Handle batch processing (receives individual requests)
 * 
 * RELATED:
 * - GameBoxSpawner: Coordinates game placement and calls this renderer
 * - SharedPropsUtils: Game box dimensions and layout constants
 */

import * as THREE from 'three'
import type { SteamGameData } from './types/GameData'
import type {
    GameBoxDimensions,
    GameBoxTextureOptions
} from './types/GameBoxOptions'
import { InstancedLabelRenderer } from './instancing/InstancedLabelRenderer'
import { LOD_LEVEL, LOD_TIER_NAME, type LodLevel } from './instancing/ILodArtworkRenderer'
import type { ILodArtworkRendererDebug } from './instancing/ILodArtworkRenderer'
import { LodArtworkOrchestratorDebug, type LodConfig } from './instancing/LodArtworkOrchestratorDebug'
import { LodDistanceManagerDebug } from './instancing/LodDistanceManagerDebug'
import { ShelfSide } from '../props/SharedPropsUtils'
import { AppSettings, Setting } from '../../core/AppSettings'
import { EventManager } from '../../core/EventManager'
import { Logger } from '../../utils/Logger'
import { StorePropsEventTypes, type GameBoxSpawnedEvent } from '../../types/InteractionEvents'
import type { IGameBoxRenderer, GameBoxRequest } from '../IGameBoxRenderer'

// Steam capsule source dimensions (what CDN claims, though actual is ~460├ù690)
const STEAM_SOURCE_WIDTH = 600
const STEAM_SOURCE_HEIGHT = 900

export class GpuGameBoxRenderer implements IGameBoxRenderer {
    public static logger = Logger.createLogFunctions(GpuGameBoxRenderer.name)

    private static readonly DEFAULT_DIMENSIONS: GameBoxDimensions = {
        width: 0.3,   // 30cm width
        height: 0.4,  // 40cm height 
        depth: 0.08   // 8cm depth
    }

    private readonly dimensions: GameBoxDimensions
    private readonly instancedLabelRenderer: InstancedLabelRenderer
    private readonly lodArtworkRenderer: ILodArtworkRendererDebug
    private readonly lodDistanceManager: LodDistanceManagerDebug

    constructor(maxGames: number = 2000) {
        this.dimensions = { ...GpuGameBoxRenderer.DEFAULT_DIMENSIONS }

        GpuGameBoxRenderer.logger.debug(`Constructor: using LOD atlas (max ${maxGames})`)

        // Create label renderer (fallback for missing/failed artwork)
        this.instancedLabelRenderer = new InstancedLabelRenderer({
            maxInstances: maxGames
        })

        // Create LOD artwork renderer with settings-based configuration
        const lodConfigs = this.buildLodConfigsFromSettings()
        const maxHighSlots = AppSettings.get(Setting.LodMaxHighSlots)

        this.lodArtworkRenderer = new LodArtworkOrchestratorDebug({
            maxTextures: maxGames,
            maxGames,
            lazyHighTextures: true,  // Memory optimization: load HIGH textures on demand
            boxWidth: this.dimensions.width,
            boxHeight: this.dimensions.height,
            boxDepth: this.dimensions.depth,
            lodConfigs,
            maxHighTextureCache: maxHighSlots
        })

        // Create distance manager for automatic LOD switching
        this.lodDistanceManager = new LodDistanceManagerDebug(this.lodArtworkRenderer)

        // Self-subscribe: renderer owns the GameBoxSpawned ΓåÆ createGameBoxAuto wiring.
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.GameBoxSpawned,
            this.handleGameBoxSpawned.bind(this)
        )

        GpuGameBoxRenderer.logger.lifecycle(`LOD atlas initialized (max ${maxGames}, HIGH slots: ${maxHighSlots}, lazy HIGH enabled)`)
    }

    private handleGameBoxSpawned(event: CustomEvent<GameBoxSpawnedEvent>): void {
        const { game, position, side, rotation } = event.detail
        this.createGameBoxAuto(
            game as SteamGameData,
            position as THREE.Vector3,
            side as ShelfSide,
            rotation as THREE.Quaternion
        )
    }

    /**
     * Create game box with artwork by URL - entire fetch+process happens in worker
     * This is the preferred path - keeps main thread completely free
     */
    public createGameBoxFromUrl(
        game: SteamGameData,
        position: THREE.Vector3,
        artworkUrl: string,
        side: ShelfSide = ShelfSide.Front,
        rotation?: THREE.Quaternion
    ): void {
        GpuGameBoxRenderer.logger.debug(`[LOD] Loading artwork for "${game.name}"`)

        this.lodArtworkRenderer.setArtworkInstanceFromUrl(
            position,
            game.name,
            artworkUrl,
            typeof game.appid === 'number' ? game.appid : undefined,
            rotation
        ).then((result) => {
            if (!result.success && AppSettings.get(Setting.EnableLabels)) {
                this.createLabelGameBox(game, position, side, rotation)
            }
        }).catch((error) => {
            if (!(error instanceof Error && error.message.includes('Maximum'))) {
                GpuGameBoxRenderer.logger.debug(`Artwork fetch failed for "${game.name}": ${error}`)
            }
            if (AppSettings.get(Setting.EnableLabels)) {
                this.createLabelGameBox(game, position, side, rotation)
            }
        })
    }

    public createLabelGameBox(
        game: SteamGameData,
        position: THREE.Vector3,
        side: ShelfSide = ShelfSide.Front,
        rotation?: THREE.Quaternion
    ): void {
        const success = this.instancedLabelRenderer.addLabelInstance(
            position,
            game.name,
            typeof game.appid === 'number' ? game.appid : undefined,
            side,
            rotation
        )

        if (!success) {
            GpuGameBoxRenderer.logger.debug(`Failed to add label box for "${game.name}"`)
        }
    }

    /**
     * Create game box with automatic artwork/label decision
     * This is the preferred entry point - consolidates artwork decision here
     */
    public createGameBoxAuto(
        game: SteamGameData,
        position: THREE.Vector3,
        side: ShelfSide = ShelfSide.Front,
        rotation?: THREE.Quaternion
    ): void {
        const artworkUrl = this.selectBestArtworkUrl(game)

        GpuGameBoxRenderer.logger.debug(`createGameBoxAuto "${game.name}": artwork=${!!artworkUrl}`)

        if (artworkUrl) {
            this.createGameBoxFromUrl(game, position, artworkUrl, side, rotation)
        } else if (AppSettings.get(Setting.EnableLabels)) {
            this.createLabelGameBox(game, position, side, rotation)
        }
    }

    /**
     * Select best artwork URL from game metadata
     * Prioritizes portrait format (library_600x900.jpg) for consistent LOD rendering
     */
    private selectBestArtworkUrl(game: SteamGameData): string | undefined {
        // Priority 1: Use library URL from metadata (portrait format - ideal for game boxes)
        if (game.artwork?.library) {
            return game.artwork.library
        }

        // Priority 2: Use header URL from metadata (landscape - fallback)
        if (game.artwork?.header) {
            return game.artwork.header
        }

        // Priority 3: Construct portrait URL as last resort
        if (game.appid) {
            GpuGameBoxRenderer.logger.debug(`No artwork URLs in metadata for "${game.name}" - using constructed URL`)
            return `https://cdn.akamai.steamstatic.com/steam/apps/${game.appid}/library_600x900.jpg`
        }

        return undefined
    }

    public createBatchGameBoxes(requests: GameBoxRequest[]) {
        requests.forEach(request => {
            this.createGameBoxAuto(
                request.game,
                request.position,
                request.side
            )
        })
    }

    public getDimensions(): GameBoxDimensions {
        return { ...this.dimensions }
    }

    public dispose(): void {
        GpuGameBoxRenderer.logger.lifecycle('Disposing')

        EventManager.getInstance().deregisterEventHandler(
            StorePropsEventTypes.GameBoxSpawned,
            this.handleGameBoxSpawned.bind(this)
        )

        this.lodDistanceManager.dispose()
        this.instancedLabelRenderer.dispose()
        this.lodArtworkRenderer.dispose()

        // Remove global reference if present
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        ;(window as any).lodArtworkRenderer = null

        GpuGameBoxRenderer.logger.lifecycle('Disposed')
    }

    public getMemoryStats() {
        return this.lodArtworkRenderer.getMemoryStats()
    }

    public logMemoryStats(): void {
        this.lodArtworkRenderer.logMemoryStats()
    }

    /**
     * Build LOD configs from AppSettings
     * This allows user to control texture resolutions and VRAM usage
     */
    private buildLodConfigsFromSettings(): LodConfig[] {
        const highRatio = AppSettings.get(Setting.LodHighReductionRatio)
        const medRatio = AppSettings.get(Setting.LodMedReductionRatio)
        const maxHighSlots = AppSettings.get(Setting.LodMaxHighSlots)

        // Calculate dimensions from ratios
        const highWidth = Math.floor(STEAM_SOURCE_WIDTH * highRatio)
        const highHeight = Math.floor(STEAM_SOURCE_HEIGHT * highRatio)
        const medWidth = Math.floor(STEAM_SOURCE_WIDTH * medRatio)
        const medHeight = Math.floor(STEAM_SOURCE_HEIGHT * medRatio)

        GpuGameBoxRenderer.logger.info(`LOD config: HIGH ${highWidth}├ù${highHeight} (${maxHighSlots} slots), MED ${medWidth}├ù${medHeight}`)

        return [
            { level: LOD_LEVEL.HIGH, textureWidth: highWidth, textureHeight: highHeight, name: LOD_TIER_NAME.HIGH, maxDepth: maxHighSlots },
            { level: LOD_LEVEL.MID, textureWidth: medWidth, textureHeight: medHeight, name: LOD_TIER_NAME.MID }
        ]
    }
}

