/**
 * Utility for resizing pixel data.
 */

/**
 * Resize pixel data using a simple box-sampling approach.
 * 
 * @param src Source pixel data (RGBA)
 * @param srcWidth Source width
 * @param srcHeight Source height
 * @param dstWidth Target width
 * @param dstHeight Target height
 * @returns Resized pixel data (RGBA)
 */
export function resizePixels(
    src: Uint8ClampedArray,
    srcWidth: number,
    srcHeight: number,
    dstWidth: number,
    dstHeight: number
): Uint8ClampedArray {
    const dst = new Uint8ClampedArray(dstWidth * dstHeight * 4)
    const scaleX = srcWidth / dstWidth
    const scaleY = srcHeight / dstHeight

    for (let dstY = 0; dstY < dstHeight; dstY++) {
        for (let dstX = 0; dstX < dstWidth; dstX++) {
            const srcX0 = Math.floor(dstX * scaleX)
            const srcY0 = Math.floor(dstY * scaleY)
            const srcX1 = Math.min(Math.ceil((dstX + 1) * scaleX), srcWidth)
            const srcY1 = Math.min(Math.ceil((dstY + 1) * scaleY), srcHeight)

            let r = 0, g = 0, b = 0, a = 0, count = 0
            for (let sy = srcY0; sy < srcY1; sy++) {
                for (let sx = srcX0; sx < srcX1; sx++) {
                    const srcIdx = (sy * srcWidth + sx) * 4
                    r += src[srcIdx]
                    g += src[srcIdx + 1]
                    b += src[srcIdx + 2]
                    a += src[srcIdx + 3]
                    count++
                }
            }

            const dstIdx = (dstY * dstWidth + dstX) * 4
            if (count > 0) {
                dst[dstIdx] = Math.round(r / count)
                dst[dstIdx + 1] = Math.round(g / count)
                dst[dstIdx + 2] = Math.round(b / count)
                dst[dstIdx + 3] = Math.round(a / count)
            }
        }
    }

    return dst
}

/**
 * Game Artwork Provider - Universal artwork retrieval for any renderer
 *
 * TD: singleton-pattern-refactor
 *
 * - URL for the artwork
 * - Pixel data (Uint8ClampedArray) at requested dimensions
 * - Format information
 * 
 * Works with:
 * - LodGameArtworkRenderer (instanced boxes)
 * - GameBinder (legacy single-mesh boxes)
 * - Any future renderer that needs Steam artwork
 * 
 * Handles internally:
 * - URL strategy (primary vs fallback CDN URLs)
 * - Persistent failure/success caching
 * - Coordination with TextureWorker for fetching
 * - PixelDataCache for disk caching
 */

import { Logger } from '../../../utils/Logger'
import { TextureWorker } from './TextureWorker'
import { PixelDataCache } from './PixelDataCache'
import { GameArtworkRequest } from './GameArtworkRequest'
import { resizePixels } from './ArtworkPixelUtils'

// Class-scoped logger will be attached to the class

/** Supported artwork formats */
export type ArtworkFormat = 'library' | 'header' | 'capsule'

/** Artwork dimensions for each format */
export const ARTWORK_DIMENSIONS: Record<ArtworkFormat, { width: number; height: number }> = {
    library: { width: 300, height: 450 },   // Portrait (2:3 aspect)
    header: { width: 460, height: 215 },    // Landscape header
    capsule: { width: 616, height: 353 }    // Landscape capsule
}

/** Result of fetching pixel data */
export interface PixelDataResult {
    pixels: Uint8ClampedArray
    width: number
    height: number
    fromCache: boolean
}

/**
 * A handle to artwork for a specific game.
 * Lazily fetches data on demand, can be queried multiple times.
 */
export interface GameArtwork {
    readonly appId: number
    readonly gameName: string
    readonly format: ArtworkFormat

    /** Get the URL for this artwork (resolved from strategy) */
    getUrl(): string

    /** 
     * Get pixel data at native resolution for this format.
     * Returns cached data if available, otherwise fetches.
     */
    getPixels(): Promise<PixelDataResult>

    /**
     * Get pixel data resized to specific dimensions.
     * Useful for LOD tiers that need smaller textures.
     */
    getPixelsAtSize(width: number, height: number): Promise<PixelDataResult>

    /** Check if pixel data is already cached (won't trigger network) */
    isCached(): Promise<boolean>

    /** Get failure reason if artwork couldn't be loaded */
    getFailureReason(): FailureReason | null
}

/** Detailed failure reasons for artwork loading */
export type FailureReason = 
    | 'CORS'           // CORS policy blocked (permanent)
    | '404'            // Not found on CDN (permanent)
    | 'NO_ARTWORK'     // Game has no artwork available (permanent dead-end)
    | 'TIMEOUT'        // Request timed out (retryable)
    | 'NETWORK'        // Network error (retryable)
    | 'DECODE'         // Image decode failed (permanent)
    | 'UNKNOWN'        // Unknown error (retryable)

/** Internal tracking for URL failures/successes */
interface UrlCacheEntry {
    timestamp: number
    // For failures
    reason?: FailureReason
    urlsTried?: string[]
    attemptCount?: number
    isPermanent?: boolean  // True for dead-ends we shouldn't retry
    // For successes (fallback URL that worked)
    fallbackUrl?: string
    fallbackType?: string
}

/** Fallback URL patterns for Steam CDN */
const FALLBACK_PATTERNS: Record<ArtworkFormat, Array<{ pattern: string; name: string }>> = {
    library: [
        { pattern: 'library_600x900.jpg', name: 'library' }
    ],
    header: [
        { pattern: 'header.jpg', name: 'header' }
    ],
    capsule: [
        { pattern: 'capsule_616x353.jpg', name: 'capsule' },
        { pattern: 'header.jpg', name: 'header-fallback' }
    ]
}

/**
 * Provider for game artwork - singleton that manages caching and URL strategies.
 */
export class GameArtworkProvider {
    private static instance: GameArtworkProvider | null = null
    public static logger = Logger.createLogFunctions(GameArtworkProvider.name)

    private textureWorker: TextureWorker
    private pixelCache: PixelDataCache | null = null

    // Persistent URL caches (localStorage)
    public static readonly FAILURE_CACHE_KEY = 'steam-artwork-failures-v4'
    public static readonly SUCCESS_CACHE_KEY = 'steam-artwork-successes-v4'
    private static readonly CACHE_TTL_MS = 24 * 60 * 60 * 1000  // 24 hours

    private failureCache: Map<string, UrlCacheEntry> = new Map()  // key: appId-format
    private successCache: Map<string, UrlCacheEntry> = new Map()

    // Skip tracking (per session)
    private skipStats: Map<FailureReason, number> = new Map()
    private skippedGames: Array<{ appId: number; gameName: string; reason: FailureReason }> = []

    private constructor() {
        this.textureWorker = new TextureWorker()
        this.loadPersistentCaches()
        this.initPixelCache()
        this.logFailureStats()
    }

    public static getInstance(): GameArtworkProvider {
        if (!GameArtworkProvider.instance) {
            GameArtworkProvider.instance = new GameArtworkProvider()
        }
        return GameArtworkProvider.instance
    }

    private async initPixelCache(): Promise<void> {
        try {
            this.pixelCache = PixelDataCache.getInstance()
            await this.pixelCache.init()
        } catch (err) {
            GameArtworkProvider.logger.warn('PixelDataCache init failed:', err)
        }
    }

    /**
     * Get artwork for a game.
     * Returns a GameArtwork handle that can be queried for URL, pixels, etc.
     */
    public getArtwork(
        appId: number,
        gameName: string,
        format: ArtworkFormat = 'library',
        preferredUrl?: string
    ): GameArtwork {
        return new GameArtworkRequest(
            appId,
            gameName,
            format,
            preferredUrl,
            this
        )
    }

    /**
     * Build the URL strategy for an appId/format.
     * Returns ordered list of URLs to try.
     */
    public buildUrlStrategy(
        appId: number,
        format: ArtworkFormat,
        preferredUrl?: string
    ): Array<{ url: string; type: string }> {
        const cacheKey = `${appId}-${format}`
        const urls: Array<{ url: string; type: string }> = []

        // Check if we have a known-good fallback URL
        const cachedSuccess = this.successCache.get(cacheKey)
        if (cachedSuccess?.fallbackUrl) {
            urls.push({ url: cachedSuccess.fallbackUrl, type: `cached-${cachedSuccess.fallbackType}` })
        }

        // Add preferred URL if provided (usually from Steam API metadata)
        if (preferredUrl) {
            const alreadyAdded = urls.some(u => u.url === preferredUrl)
            if (!alreadyAdded) {
                urls.push({ url: preferredUrl, type: 'preferred' })
            }
        }

        // Add CDN fallback URLs
        const isNewCdn = preferredUrl?.includes('shared.akamai.steamstatic.com') || 
                         preferredUrl?.includes('store_item_assets')

        if (!isNewCdn) {
            const baseUrl = `https://cdn.akamai.steamstatic.com/steam/apps/${appId}`
            const patterns = FALLBACK_PATTERNS[format] || FALLBACK_PATTERNS.library

            for (const { pattern, name } of patterns) {
                const fallbackUrl = `${baseUrl}/${pattern}`
                const alreadyAdded = urls.some(u => u.url === fallbackUrl)
                if (!alreadyAdded) {
                    urls.push({ url: fallbackUrl, type: `cdn-${name}` })
                }
            }
        }

        return urls
    }

    /**
     * Fetch pixel data for a URL, with caching.
     */
    public async fetchPixels(
        url: string,
        targetWidth: number,
        targetHeight: number,
        cacheKey: string
    ): Promise<PixelDataResult> {
        // Build a size-qualified cache key for disk lookups
        const sizedCacheUrl = `${url}@${targetWidth}x${targetHeight}`

        // Check disk cache first
        if (this.pixelCache) {
            const cached = await this.pixelCache.get(sizedCacheUrl)
            if (cached) {
                // If cached at different size, we may need to resize
                if (cached.width === targetWidth && cached.height === targetHeight) {
                    return {
                        pixels: cached.pixelData,
                        width: cached.width,
                        height: cached.height,
                        fromCache: true
                    }
                }
                // Resize cached data to target size
                const resized = resizePixels(
                    cached.pixelData, cached.width, cached.height,
                    targetWidth, targetHeight
                )
                return {
                    pixels: resized,
                    width: targetWidth,
                    height: targetHeight,
                    fromCache: true
                }
            }
        }

        // Fetch from network
        const result = await this.textureWorker.fetchAndProcessWithOptions(
            url, 0, cacheKey,
            { textureWidth: targetWidth, textureHeight: targetHeight, timeout: 10000 }
        )

        // Always store using size-qualified key
        if (this.pixelCache) {
            await this.pixelCache.put(sizedCacheUrl, result.imageData, targetWidth, targetHeight)
        }

        return {
            pixels: result.imageData,
            width: targetWidth,
            height: targetHeight,
            fromCache: false
        }
    }

    /**
     * Check if pixels are cached for a URL.
     */
    public async isPixelsCached(url: string, width?: number, height?: number): Promise<boolean> {
        if (!this.pixelCache) return false
        const key = (width !== undefined && height !== undefined) ? `${url}@${width}x${height}` : url
        const cached = await this.pixelCache.get(key)
        return cached !== null
    }

    /**
     * Record a URL failure.
     */
    /**
     * Determine if a failure reason is permanent (should not retry).
     */
    private static isReasonPermanent(reason: FailureReason | undefined): boolean {
        return reason === 'NO_ARTWORK' || reason === 'CORS' || reason === 'DECODE' || reason === '404'
    }

    public recordFailure(
        appId: number,
        format: ArtworkFormat,
        reason: FailureReason,
        urlsTried: string[]
    ): void {
        const cacheKey = `${appId}-${format}`
        const existing = this.failureCache.get(cacheKey)
        const attemptCount = (existing?.attemptCount ?? 0) + 1

        // Permanent failures: NO_ARTWORK, CORS, DECODE, and 404.
        // 404 from Steam CDN is permanent ΓÇö the image doesn't exist on the CDN.
        // (CORS failures sometimes mask 404s; both are unretryable.)
        const isPermanent = GameArtworkProvider.isReasonPermanent(reason)

        this.failureCache.set(cacheKey, {
            timestamp: Date.now(),
            reason,
            urlsTried,
            attemptCount,
            isPermanent
        })
        this.savePersistentFailures()

        // Log permanent failures clearly
        if (isPermanent) {
            GameArtworkProvider.logger.info(
                `≡ƒÜ½ Permanent failure for appId ${appId}: ${reason} (will skip future attempts)`
            )
        }
    }

    /**
     * Record a URL success (when fallback worked).
     */
    public recordSuccess(
        appId: number,
        format: ArtworkFormat,
        fallbackUrl: string,
        fallbackType: string
    ): void {
        const cacheKey = `${appId}-${format}`
        this.successCache.set(cacheKey, {
            timestamp: Date.now(),
            fallbackUrl,
            fallbackType
        })
        this.savePersistentSuccesses()
    }

    /**
     * Check if an appId/format is known to have failed.
     */
    public isKnownFailure(appId: number, format: ArtworkFormat): boolean {
        const cacheKey = `${appId}-${format}`
        return this.failureCache.has(cacheKey)
    }

    /**
     * Get failure reason for an appId/format.
     */
    public getFailureReason(appId: number, format: ArtworkFormat): FailureReason | null {
        const cacheKey = `${appId}-${format}`
        return this.failureCache.get(cacheKey)?.reason ?? null
    }

    /**
     * Check if failure is permanent (should not retry).
     */
    public isPermanentFailure(appId: number, format: ArtworkFormat): boolean {
        const cacheKey = `${appId}-${format}`
        return this.failureCache.get(cacheKey)?.isPermanent ?? false
    }

    /**
     * Record a skipped attempt (permanent failure).
     */
    public recordSkip(appId: number, gameName: string, reason: FailureReason): void {
        this.skipStats.set(reason, (this.skipStats.get(reason) || 0) + 1)
        this.skippedGames.push({ appId, gameName, reason })
    }

    /**
     * Get skip statistics for this session.
     */
    public getSkipStats(): { total: number; byReason: Record<FailureReason, number> } {
        const byReason: Record<string, number> = {}
        for (const [reason, count] of this.skipStats) {
            byReason[reason] = count
        }
        return {
            total: this.skippedGames.length,
            byReason: byReason as Record<FailureReason, number>
        }
    }

    /**
     * Log skip statistics summary.
     */
    public logSkipSummary(): void {
        if (this.skippedGames.length === 0) return

        const reasons: string[] = []
        for (const [reason, count] of this.skipStats) {
            reasons.push(`${reason}: ${count}`)
        }

        GameArtworkProvider.logger.info(
            `≡ƒôè Skipped ${this.skippedGames.length} permanent failures this session (${reasons.join(', ')})`
        )
    }

    /**
     * Clear skip statistics.
     */
    public clearSkipStats(): void {
        this.skipStats.clear()
        this.skippedGames = []
    }

    /**
     * Get failure statistics grouped by reason.
     */
    public getFailureStats(): Record<FailureReason, number> & { total: number; permanent: number } {
        const stats: Record<string, number> = {
            total: 0,
            permanent: 0
        }

        for (const entry of this.failureCache.values()) {
            if (entry.reason) {
                stats[entry.reason] = (stats[entry.reason] || 0) + 1
                stats.total++
                if (entry.isPermanent) stats.permanent++
            }
        }

        return stats as Record<FailureReason, number> & { total: number; permanent: number }
    }

    /**
     * Clear all caches (force retry of failed URLs).
     */
    public clearCaches(): void {
        this.failureCache.clear()
        this.successCache.clear()
        try {
            localStorage.removeItem(GameArtworkProvider.FAILURE_CACHE_KEY)
            localStorage.removeItem(GameArtworkProvider.SUCCESS_CACHE_KEY)
            GameArtworkProvider.logger.info('Cleared artwork caches')
        } catch (e) {
            GameArtworkProvider.logger.debug('Could not clear localStorage:', e)
        }
    }

    /**
     * Log failure statistics summary at startup.
     */
    private logFailureStats(): void {
        const stats = this.getFailureStats()
        if (stats.total === 0) return

        const reasons: string[] = []
        for (const [reason, count] of Object.entries(stats)) {
            if (reason !== 'total' && reason !== 'permanent' && count > 0) {
                reasons.push(`${reason}: ${count}`)
            }
        }

        if (reasons.length > 0) {
            GameArtworkProvider.logger.info(
                `≡ƒôè Artwork failures: ${stats.total} total, ${stats.permanent} permanent dead-ends (${reasons.join(', ')})`
            )
        }
    }

    private loadPersistentCaches(): void {
        const now = Date.now()

        try {
            const failures = localStorage.getItem(GameArtworkProvider.FAILURE_CACHE_KEY)
            if (failures) {
                const data = JSON.parse(failures) as Record<string, UrlCacheEntry>
                let count = 0
                let migrated = 0
                for (const [key, entry] of Object.entries(data)) {
                    if (now - entry.timestamp < GameArtworkProvider.CACHE_TTL_MS) {
                        // Migrate old entries without isPermanent/attemptCount
                        if (entry.isPermanent === undefined) {
                            entry.attemptCount = entry.attemptCount ?? 1
                            entry.isPermanent = GameArtworkProvider.isReasonPermanent(entry.reason)
                            migrated++
                        }
                        this.failureCache.set(key, entry)
                        count++
                    }
                }
                if (count > 0) {
                    GameArtworkProvider.logger.info(`Loaded ${count} cached failures`)
                    if (migrated > 0) {
                        GameArtworkProvider.logger.info(`Migrated ${migrated} old cache entries`)
                        this.savePersistentFailures()  // Save migrated entries
                    }
                }
            }
        } catch (e) {
            GameArtworkProvider.logger.debug('Could not load failure cache:', e)
        }

        try {
            const successes = localStorage.getItem(GameArtworkProvider.SUCCESS_CACHE_KEY)
            if (successes) {
                const data = JSON.parse(successes) as Record<string, UrlCacheEntry>
                let count = 0
                for (const [key, entry] of Object.entries(data)) {
                    if (now - entry.timestamp < GameArtworkProvider.CACHE_TTL_MS) {
                        this.successCache.set(key, entry)
                        count++
                    }
                }
                if (count > 0) GameArtworkProvider.logger.info(`Loaded ${count} cached successes`)
            }
        } catch (e) {
            GameArtworkProvider.logger.debug('Could not load success cache:', e)
        }
    }

    private savePersistentFailures(): void {
        try {
            const data: Record<string, UrlCacheEntry> = {}
            for (const [key, entry] of this.failureCache) {
                data[key] = entry
            }
            localStorage.setItem(GameArtworkProvider.FAILURE_CACHE_KEY, JSON.stringify(data))
        } catch (e) {
            GameArtworkProvider.logger.debug('Could not save failure cache:', e)
        }
    }

    private savePersistentSuccesses(): void {
        try {
            const data: Record<string, UrlCacheEntry> = {}
            for (const [key, entry] of this.successCache) {
                data[key] = entry
            }
            localStorage.setItem(GameArtworkProvider.SUCCESS_CACHE_KEY, JSON.stringify(data))
        } catch (e) {
            GameArtworkProvider.logger.debug('Could not save success cache:', e)
        }
    }

    public dispose(): void {
        this.textureWorker.dispose()
        GameArtworkProvider.instance = null
        GameArtworkProvider.logger.lifecycle('Disposed')
    }
}

import { 
    ARTWORK_DIMENSIONS, 
    GameArtworkProvider 
} from './GameArtworkProvider'
import type { 
    GameArtwork, 
    ArtworkFormat, 
    FailureReason, 
    PixelDataResult 
} from './GameArtworkProvider'

/**
 * Handle to artwork for a specific game.
 * Implements GameArtwork interface with lazy loading.
 */
export class GameArtworkRequest implements GameArtwork {
    readonly appId: number
    readonly gameName: string
    readonly format: ArtworkFormat

    private readonly preferredUrl?: string
    private readonly provider: GameArtworkProvider

    private resolvedUrl: string | null = null
    private cachedPixels: PixelDataResult | null = null
    private failureReason: FailureReason | null = null

    constructor(
        appId: number,
        gameName: string,
        format: ArtworkFormat,
        preferredUrl: string | undefined,
        provider: GameArtworkProvider
    ) {
        this.appId = appId
        this.gameName = gameName
        this.format = format
        this.preferredUrl = preferredUrl
        this.provider = provider

        // Check if known failure
        this.failureReason = provider.getFailureReason(appId, format)
    }

    getUrl(): string {
        if (this.resolvedUrl) return this.resolvedUrl

        // Return first URL from strategy (may not be the one that works)
        const strategy = this.provider.buildUrlStrategy(this.appId, this.format, this.preferredUrl)
        return strategy[0]?.url ?? ''
    }

    async getPixels(): Promise<PixelDataResult> {
        const dims = ARTWORK_DIMENSIONS[this.format]
        return this.getPixelsAtSize(dims.width, dims.height)
    }

    async getPixelsAtSize(width: number, height: number): Promise<PixelDataResult> {
        // If we already loaded and it's the same size, return cached
        if (this.cachedPixels && 
            this.cachedPixels.width === width && 
            this.cachedPixels.height === height) {
            return this.cachedPixels
        }

        // Check if this is a permanent failure we should skip
        if (this.provider.isPermanentFailure(this.appId, this.format)) {
            const reason = this.failureReason ?? this.provider.getFailureReason(this.appId, this.format)
            if (reason) {
                this.provider.recordSkip(this.appId, this.gameName, reason)
            }
            throw new Error(`Permanent failure (${reason}) - skipping retry`)
        }

        // Known non-permanent failures should be retried.
        // They are historical hints, not hard blocks.

        const strategy = this.provider.buildUrlStrategy(this.appId, this.format, this.preferredUrl)
        const triedUrls: string[] = []
        let lastError: Error | null = null

        for (const { url, type } of strategy) {
            triedUrls.push(url)

            try {
                const result = await this.provider.fetchPixels(
                    url, width, height, `${this.appId}-${this.format}`
                )

                this.resolvedUrl = url
                this.cachedPixels = result

                // Record success if it was a fallback
                if (type !== 'preferred' && !type.startsWith('cached-')) {
                    this.provider.recordSuccess(this.appId, this.format, url, type)
                }

                return result
            } catch (e) {
                lastError = e instanceof Error ? e : new Error(String(e))
            }
        }

        // All URLs failed - categorize and record
        this.failureReason = this.categorizeError(lastError?.message ?? 'Unknown error', triedUrls)
        this.provider.recordFailure(this.appId, this.format, this.failureReason, triedUrls)

        throw new Error(`Failed to load artwork for ${this.gameName}: ${this.failureReason}`)
    }

    async isCached(): Promise<boolean> {
        const strategy = this.provider.buildUrlStrategy(this.appId, this.format, this.preferredUrl)
        const dims = ARTWORK_DIMENSIONS[this.format]
        for (const { url } of strategy) {
            if (await this.provider.isPixelsCached(url, dims.width, dims.height)) {
                return true
            }
        }
        return false
    }

    getFailureReason(): FailureReason | null {
        return this.failureReason
    }

    private categorizeError(msg: string, urlsTried: string[]): FailureReason {
        const lower = msg.toLowerCase()

        // CORS detection.
        // Firefox:  "TypeError: NetworkError when attempting to fetch resource."
        // Chrome:   "TypeError: Failed to fetch" (with no status) / "has been blocked by CORS policy"
        // Both:     fetch with mode:'cors' throws a TypeError ΓÇö NOT an HTTP error ΓÇö so response.status
        //           is never readable. We infer CORS from message patterns.
        if (lower.includes('cors') ||
            lower.includes('cross-origin') ||
            lower.includes('opaque') ||
            lower.includes('networkerror when attempting to fetch')) {
            return 'CORS'
        }

        // Decode/format errors
        if (lower.includes('decode') || lower.includes('invalid image')) return 'DECODE'

        // Timeouts
        if (lower.includes('timeout') || lower.includes('abort')) return 'TIMEOUT'

        // HTTP 404: worker throws 'HTTP 404: Not Found' when response is accessible.
        // When the CDN returns 404 WITH valid CORS headers we can read the status.
        // When it returns 404 WITHOUT CORS headers, CORS fires first (see above).
        // Treat any 404 as permanent ΓÇö the artwork doesn't exist on the CDN.
        if (lower.includes('http 404') || lower.includes('404') || lower.includes('not found')) {
            GameArtworkProvider.logger.debug(
                `Categorized as 404 (permanent): tried ${urlsTried.length} URL(s): ${urlsTried.join(', ')}`
            )
            return '404'
        }

        // Generic network errors not matching CORS patterns above.
        if (lower.includes('network') || lower.includes('failed to fetch')) return 'NETWORK'

        return 'UNKNOWN'
    }
}

/**
 * HIGH Texture Cache - LRU cache for high-resolution (512px) textures
 * 
 * Memory optimization: Instead of loading all HIGH textures upfront (~512MB for 512 games),
 * we only keep a limited number loaded (~64 textures = ~64MB) and dynamically
 * load/evict based on which games are actually at HIGH LOD.
 * 
 * Key Architecture:
 * - HIGH array has limited slots (e.g., 64)
 * - Games (0 to N) are dynamically mapped to available slots
 * - When a slot is needed: evict LRU, assign slot to new game, notify callback
 * - Shader uses highTextureSlot attribute (0-63 or -1 if not loaded)
 * 
 * Flow:
 * 1. Game added ΓåÆ MID texture loaded immediately (always available)
 * 2. LOD manager sets game to HIGH ΓåÆ Cache loads HIGH texture if slot available
 * 3. Cache full ΓåÆ Evict LRU game, notify via callback, assign slot to new game
 * 4. Evicted game set to HIGH again ΓåÆ Reload from network/disk cache
 */

import * as THREE from 'three'
import { Logger } from '../../../utils/Logger'
import { TextureWorker } from './TextureWorker'
import { PixelDataCache } from './PixelDataCache'
import { FrameBudgetScheduler } from '../../../utils/FrameBudgetScheduler'

// Logger will be attached to the class below

/** State of a HIGH texture for a game */
export enum HighTextureState {
    /** No HIGH texture loaded for this game */
    EMPTY = 'empty',
    /** Pixel data is being cached in background (stay on MID) */
    CACHING = 'caching',
    /** HIGH texture is currently being loaded from cache */
    LOADING = 'loading',
    /** HIGH texture is loaded and ready */
    LOADED = 'loaded',
    /** Loading failed - will retry on next request (up to maxLoadAttempts) */
    FAILED = 'failed',
    /** Permanently failed - will never retry (CORS, 404, etc) */
    PERMANENT_FAILURE = 'permanent_failure'
}

export interface HighTextureCacheConfig {
    /** Total slots in the HIGH texture array (e.g., 64) */
    totalSlots: number
    /** Width of HIGH textures (native Steam header = 460) */
    textureWidth: number
    /** Height of HIGH textures (native Steam header = 215) */
    textureHeight: number
    /** Maximum concurrent texture loads (throttling) */
    maxConcurrentLoads: number
    /** Maximum load attempts before permanent failure (default: 2) */
    maxLoadAttempts?: number
}

/** Callback when a game's HIGH slot assignment changes */
export type SlotChangeCallback = (gameIndex: number, slot: number) => void

interface GameEntry {
    /** Game index (texture index in MID array) */
    gameIndex: number
    /** Game name for debugging/logging */
    gameName: string
    /** URL to load HIGH texture from */
    artworkUrl: string
    /** Current state */
    state: HighTextureState
    /** Assigned slot in HIGH array (-1 if not assigned) */
    highSlot: number
    /** Last access timestamp for LRU */
    lastAccessTime: number
    /** Load attempt count for retry logic */
    loadAttempts: number
}

export interface HighTextureCacheStats {
    loaded: number
    loading: number
    caching: number
    failed: number
    permanentFailures: number
    empty: number
    totalSlots: number
    usedSlots: number
    evictions: number
    cacheHits: number
    cacheMisses: number
    pixelCacheHits: number
    pixelCacheMisses: number
    queueLength: number
    activeLoads: number
    backgroundCacheQueue: number
}

export class HighTextureCache {
    public static logger = Logger.createLogFunctions(HighTextureCache.name)
    private readonly config: HighTextureCacheConfig
    private readonly textureWorker: TextureWorker
    private readonly pixelCache: PixelDataCache

    /** The GPU texture array (reference - owned by LodArtworkRenderer) */
    private dataArrayTexture: THREE.DataArrayTexture | null = null

    /** Dirty flag: texture data changed, needs GPU upload */
    private isDirty: boolean = false

    /** Track which specific slots (layers) need GPU upload - enables partial updates */
    private dirtySlots: Set<number> = new Set()

    /** Game entries by game index */
    private games: Map<number, GameEntry> = new Map()

    /** Slot allocation: slot index ΓåÆ game index (or -1 if free) */
    private slotToGame: number[]

    /** Currently loading game indices (to prevent duplicate loads) */
    private loadingPromises: Map<number, Promise<boolean>> = new Map()

    /** Queue of game indices waiting to load (throttled) */
    private loadQueue: number[] = []

    /** Games currently being background-cached (pixel cache warming, no slot allocated yet) */
    private backgroundCachingGames: Set<number> = new Set()

    /** Callback to notify when slot assignments change */
    private onSlotChange: SlotChangeCallback | null = null

    /** Stats for monitoring */
    private stats = {
        evictions: 0,
        cacheHits: 0,
        cacheMisses: 0,
        pixelCacheHits: 0,
        pixelCacheMisses: 0
    }

    /** Timing samples for diagnostics (circular buffer, most recent 100 loads) */
    private timingSamples: Array<{
        gameIndex: number
        gameName: string
        fetchTime: number
        processTime: number
        copyTime: number
        totalTime: number
        timestamp: number
        pixelCacheHit: boolean
    }> = []
    private readonly MAX_TIMING_SAMPLES = 100

    /** Detailed profiling samples (optional, for deep analysis) */
    private profilingSamples: Array<{
        gameIndex: number
        gameName: string
        workerRoundTrip: number
        arrayBufferCopy: number
        textureArrayCopy: number
        callbackTime: number
        totalMainThread: number
        pixelCacheHit: boolean
        timestamp: number
    }> = []
    private profilingEnabled = false
    private readonly MAX_PROFILING_SAMPLES = 50

    /** Frame budget scheduler for deferring texture copies */
    private readonly scheduler: FrameBudgetScheduler

    constructor(config: Partial<HighTextureCacheConfig> = {}) {
        this.config = {
            totalSlots: config.totalSlots ?? 64,
            textureWidth: config.textureWidth ?? 600,
            textureHeight: config.textureHeight ?? 900,
            maxConcurrentLoads: config.maxConcurrentLoads ?? 2
        }

        // Initialize slot allocation array - all slots start free (-1)
        this.slotToGame = new Array(this.config.totalSlots).fill(-1)

        this.textureWorker = new TextureWorker()
        this.pixelCache = PixelDataCache.getInstance()
        this.scheduler = FrameBudgetScheduler.getInstance()

        HighTextureCache.logger.lifecycle(`Initialized: ${this.config.totalSlots} slots, ${this.config.maxConcurrentLoads} concurrent loads (${this.estimateMemoryMB()}MB)`)
    }

    /**
     * Set callback for slot changes (called by LodArtworkRenderer)
     */
    public setSlotChangeCallback(callback: SlotChangeCallback): void {
        this.onSlotChange = callback
    }

    /**
     * Set the GPU texture array reference (called by LodArtworkRenderer during init)
     */
    public setTextureArray(texture: THREE.DataArrayTexture): void {
        this.dataArrayTexture = texture
        HighTextureCache.logger.lifecycle('Texture array reference set')
    }

    /**
     * Check if texture data has changed and needs GPU upload
     */
    public needsGpuUpdate(): boolean {
        return this.isDirty
    }

    /**
     * Flush dirty texture data to GPU using PARTIAL layer updates
     * Instead of uploading all 64 slots (~34MB), only uploads changed slots (~540KB each)
     * Call this periodically (e.g., every N frames) instead of on every texture load
     * Returns true if an update was performed
     */
    public flushToGpu(): boolean {
        if (!this.isDirty || !this.dataArrayTexture || this.dirtySlots.size === 0) {
            return false
        }

        // Use partial layer updates instead of full texture upload
        // This is MUCH faster: ~540KB per slot vs ~34MB for all 64 slots
        for (const slot of this.dirtySlots) {
            this.dataArrayTexture.addLayerUpdate(slot)
        }

        // needsUpdate triggers the actual upload, but now only marked layers are sent
        this.dataArrayTexture.needsUpdate = true

        HighTextureCache.logger.debug(`GPU flush: ${this.dirtySlots.size} slot(s) ΓåÆ ~${(this.dirtySlots.size * 540).toFixed(0)}KB upload`)

        this.dirtySlots.clear()
        this.isDirty = false
        return true
    }

    /**
     * Convert any Steam artwork URL to portrait format (library_600x900.jpg)
     * HIGH textures need portrait format (300x450) not header format (460x215)
     * 
     * Handles both CDN domains:
     * - cdn.akamai.steamstatic.com/steam/apps/{appid}/header.jpg
     * - shared.akamai.steamstatic.com/store_item_assets/steam/apps/{appid}/header.jpg
     */
    private convertToPortraitUrl(artworkUrl: string): string {
        // Extract appid from URL patterns like:
        // https://cdn.akamai.steamstatic.com/steam/apps/1145350/header.jpg
        // https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1145350/.../header.jpg
        const appidMatch = artworkUrl.match(/\/apps\/(\d+)\//)
        if (!appidMatch) {
            HighTextureCache.logger.warn(`Could not extract appid from URL: ${artworkUrl}`)
            return artworkUrl // Return original if can't parse
        }

        const appid = appidMatch[1]
        // Use cdn.akamai domain for portrait images (more reliable for library art)
        return `https://cdn.akamai.steamstatic.com/steam/apps/${appid}/library_600x900.jpg`
    }

    /**
     * Register a game (called when a game is added)
     * Does NOT load the HIGH texture - just records that the game exists
     * 
     * Note: The artwork URL is converted to portrait format (library_600x900.jpg)
     * because HIGH textures expect 300x450 portrait dimensions, not 460x215 header dimensions.
     */
    public registerGame(gameIndex: number, gameName: string, artworkUrl: string): void {
        if (this.games.has(gameIndex)) {
            return // Already registered
        }

        // Convert to portrait URL for HIGH textures
        const portraitUrl = this.convertToPortraitUrl(artworkUrl)

        this.games.set(gameIndex, {
            gameIndex,
            gameName,
            artworkUrl: portraitUrl,
            state: HighTextureState.EMPTY,
            highSlot: -1,
            lastAccessTime: 0,
            loadAttempts: 0
        })
    }

    /**
     * Mark a game as permanently failed (e.g., CORS error during MID loading)
     * This prevents wasting network requests on artwork we know doesn't exist or isn't accessible
     */
    public markAsPermanentlyFailed(gameIndex: number, reason?: string): void {
        const entry = this.games.get(gameIndex)
        if (entry) {
            entry.state = HighTextureState.PERMANENT_FAILURE
            HighTextureCache.logger.info(`Game "${entry.gameName}" marked as permanent failure${reason ? `: ${reason}` : ''}`)
        }
    }

    /**
     * Unregister a game (e.g., when MID loading fails and we rollback)
     */
    public unregisterGame(gameIndex: number): void {
        this.games.delete(gameIndex)
    }

    /**
     * Request HIGH texture for a game
     * Returns the HIGH slot if loaded, otherwise triggers async load and returns -1
     * @returns HIGH slot (0-63) if ready, -1 if loading or unavailable
     */
    public requestHighTexture(gameIndex: number): number {
        const entry = this.games.get(gameIndex)
        if (!entry) {
            HighTextureCache.logger.warn(`requestHighTexture: unknown game ${gameIndex}`)
            return -1
        }

        // Update access time for LRU
        entry.lastAccessTime = window.performance.now()

        switch (entry.state) {
            case HighTextureState.LOADED:
                this.stats.cacheHits++
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ HIT slot ${entry.highSlot}`)
                return entry.highSlot

            case HighTextureState.LOADING:
                // Already loading - return -1, caller should use MID for now
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ LOADING (wait)`)
                return -1

            case HighTextureState.CACHING:
                // Background caching in progress - check if cache is now ready
                if (this.backgroundCachingGames.has(gameIndex)) {
                    // Still caching, stay on MID
                    HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ CACHING (wait)`)
                    return -1
                }
                // Background caching finished - transition to EMPTY so next request loads from cache
                entry.state = HighTextureState.EMPTY
                // Now trigger load which will hit pixel cache (fast path)
                this.stats.cacheMisses++
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ CACHE READY (triggering fast load)`)
                this.triggerLoad(entry)
                return -1

            case HighTextureState.PERMANENT_FAILURE:
                // Permanently failed (CORS, 404, etc) - never retry
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ PERMANENT FAILURE (skipped)`)
                return -1

            case HighTextureState.FAILED:
                // Check retry limit
                if (entry.loadAttempts >= (this.config.maxLoadAttempts ?? 2)) {
                    entry.state = HighTextureState.PERMANENT_FAILURE
                    HighTextureCache.logger.info(`Game "${entry.gameName}" exceeded max load attempts (${entry.loadAttempts}), marking as permanent failure`)
                    return -1
                }
                // Retry load - fall through to EMPTY handling
                this.stats.cacheMisses++
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ RETRY (attempt ${entry.loadAttempts + 1})`)
                this.triggerLoad(entry)
                return -1

            case HighTextureState.EMPTY:
                // Need to load - trigger async load
                this.stats.cacheMisses++
                HighTextureCache.logger.debug(`REQUEST game ${gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ MISS (triggering load)`)
                this.triggerLoad(entry)
                return -1
        }
    }

    /**
     * Get the HIGH slot for a game (-1 if not loaded)
     */
    public getHighSlot(gameIndex: number): number {
        return this.games.get(gameIndex)?.highSlot ?? -1
    }

    /**
     * Check if HIGH texture is loaded for a game
     */
    public isLoaded(gameIndex: number): boolean {
        return this.games.get(gameIndex)?.state === HighTextureState.LOADED
    }

    /**
     * Get current state of a game's HIGH texture
     */
    public getState(gameIndex: number): HighTextureState {
        return this.games.get(gameIndex)?.state ?? HighTextureState.EMPTY
    }

    /**
     * Trigger async load for a HIGH texture (throttled)
     */
    private triggerLoad(entry: GameEntry): void {
        // Already loading or queued?
        if (this.loadingPromises.has(entry.gameIndex)) {
            HighTextureCache.logger.debug(`TRIGGER game ${entry.gameIndex} ΓåÆ already loading, skip`)
            return
        }
        if (this.loadQueue.includes(entry.gameIndex)) {
            HighTextureCache.logger.debug(`TRIGGER game ${entry.gameIndex} ΓåÆ already queued at position ${this.loadQueue.indexOf(entry.gameIndex)}`)
            return
        }

        // Check if we're at the concurrent load limit
        if (this.loadingPromises.size >= this.config.maxConcurrentLoads) {
            // Queue for later
            this.loadQueue.push(entry.gameIndex)
            HighTextureCache.logger.debug(`TRIGGER game ${entry.gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ QUEUED (pos ${this.loadQueue.length}, active: ${this.loadingPromises.size})`)
            return
        }

        HighTextureCache.logger.debug(`TRIGGER game ${entry.gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ starting load`)
        this.startLoad(entry)
    }

    /**
     * Actually start loading a texture (called when under concurrent limit)
     */
    private startLoad(entry: GameEntry): void {
        // Allocate a slot (may evict if full)
        const slot = this.allocateSlot(entry.gameIndex)
        if (slot < 0) {
            HighTextureCache.logger.warn(`Cannot load HIGH texture ${entry.gameIndex}: no slots available`)
            return
        }

        entry.highSlot = slot
        entry.state = HighTextureState.LOADING
        entry.loadAttempts++

        const loadPromise = this.loadHighTexture(entry)
        this.loadingPromises.set(entry.gameIndex, loadPromise)

        loadPromise.finally(() => {
            this.loadingPromises.delete(entry.gameIndex)
            // Process next in queue
            this.processQueue()
        })
    }

    /**
     * Allocate a slot for a game, evicting LRU if necessary
     * @returns slot index (0-63), or -1 if allocation failed
     */
    private allocateSlot(gameIndex: number): number {
        // First, try to find a free slot
        for (let slot = 0; slot < this.config.totalSlots; slot++) {
            if (this.slotToGame[slot] === -1) {
                this.slotToGame[slot] = gameIndex
                return slot
            }
        }

        // All slots full - evict LRU
        const evictedSlot = this.evictLru()
        if (evictedSlot >= 0) {
            this.slotToGame[evictedSlot] = gameIndex
            return evictedSlot
        }

        return -1 // Should not happen
    }

    /**
     * Process the load queue, starting loads up to the concurrent limit
     */
    private processQueue(): void {
        while (
            this.loadQueue.length > 0 &&
            this.loadingPromises.size < this.config.maxConcurrentLoads
        ) {
            const gameIndex = this.loadQueue.shift()
            if (gameIndex === undefined) break

            const entry = this.games.get(gameIndex)

            if (entry && entry.state !== HighTextureState.LOADED && entry.state !== HighTextureState.LOADING) {
                this.startLoad(entry)
            }
        }
    }

    /**
     * Start background caching for a game (fetch + decode + store in pixel cache)
     * This runs in the background without blocking HIGH texture loading
     * When complete, the game will be re-requested and load from pixel cache (fast path)
     */
    private startBackgroundCaching(entry: GameEntry): void {
        if (this.backgroundCachingGames.has(entry.gameIndex)) {
            return // Already caching
        }

        this.backgroundCachingGames.add(entry.gameIndex)
        HighTextureCache.logger.debug(`BACKGROUND CACHE START ${entry.gameIndex} "${entry.gameName.slice(0, 15)}"`)

        // Fire and forget - fetch, decode, and store in pixel cache
        this.textureWorker.fetchAndProcessWithOptions(
            entry.artworkUrl,
            entry.gameIndex,
            entry.gameName,
            {
                useNativeSize: true,
                timeout: 15000
            }
        ).then(async (result) => {
            // Verify dimensions
            if (result.width !== this.config.textureWidth || result.height !== this.config.textureHeight) {
                HighTextureCache.logger.warn(`BACKGROUND CACHE: size mismatch for "${entry.gameName}": expected ${this.config.textureWidth}├ù${this.config.textureHeight}, got ${result.width}├ù${result.height}`)
                entry.state = HighTextureState.FAILED
                this.backgroundCachingGames.delete(entry.gameIndex)
                return
            }

            // Store in pixel cache
            await this.pixelCache.put(entry.artworkUrl, result.imageData, result.width, result.height)

            HighTextureCache.logger.debug(`BACKGROUND CACHE COMPLETE ${entry.gameIndex} "${entry.gameName.slice(0, 15)}" (${result.width}├ù${result.height})`)
            this.backgroundCachingGames.delete(entry.gameIndex)
            // Entry stays in CACHING state - next requestHighTexture() will detect cache ready
        }).catch((err) => {
            const msg = err instanceof Error ? err.message : String(err)
            HighTextureCache.logger.debug(`BACKGROUND CACHE FAILED ${entry.gameIndex} "${entry.gameName.slice(0, 15)}": ${msg}`)
            entry.state = HighTextureState.FAILED
            this.backgroundCachingGames.delete(entry.gameIndex)
        })
    }

    /**
     * Actually load a HIGH texture - first checks pixel cache, defers to background on miss
     */
    private async loadHighTexture(entry: GameEntry): Promise<boolean> {
        if (!this.dataArrayTexture) {
            HighTextureCache.logger.warn('Cannot load HIGH texture: texture array not set')
            entry.state = HighTextureState.FAILED
            return false
        }

        if (entry.highSlot < 0) {
            HighTextureCache.logger.warn('Cannot load HIGH texture: no slot assigned')
            entry.state = HighTextureState.FAILED
            return false
        }

        const loadStart = window.performance.now()
        let workerRoundTrip = 0
        let arrayBufferCopyTime = 0

        try {
            HighTextureCache.logger.debug(`START HIGH ${entry.gameIndex} ΓåÆ slot ${entry.highSlot} "${entry.gameName.slice(0, 20)}" | in-flight: ${this.loadingPromises.size}/${this.config.maxConcurrentLoads}, queue: ${this.loadQueue.length}`)

            // First, check the pixel cache for decoded RGBA data
            const fetchStart = window.performance.now()
            const cachedPixels = await this.pixelCache.get(entry.artworkUrl)
            workerRoundTrip = window.performance.now() - fetchStart

            let imageData: Uint8ClampedArray
            let processTime = 0
            let pixelCacheHit = false

            if (cachedPixels) {
                // Pixel cache HIT - schedule the processing to avoid frame spikes
                // when multiple worker responses arrive in the same frame
                this.stats.pixelCacheHits++
                pixelCacheHit = true

                // Measure time to access the transferred ArrayBuffer data
                const bufferAccessStart = window.performance.now()
                imageData = cachedPixels.pixelData
                // Force array access to measure actual time (not just reference assignment)
                const _len = imageData.length
                arrayBufferCopyTime = window.performance.now() - bufferAccessStart

                processTime = 0 // No decode needed
                HighTextureCache.logger.debug(`PIXEL CACHE HIT ${entry.gameIndex} "${entry.gameName.slice(0, 15)}" (${cachedPixels.width}├ù${cachedPixels.height})`)
            } else {
                // Pixel cache MISS - defer to background caching to avoid main thread lag
                // Release the slot and set CACHING state so we don't block
                this.stats.pixelCacheMisses++
                HighTextureCache.logger.debug(`PIXEL CACHE MISS ${entry.gameIndex} "${entry.gameName.slice(0, 15)}" ΓåÆ deferring to background caching`)

                // Release the allocated slot
                if (entry.highSlot >= 0) {
                    this.slotToGame[entry.highSlot] = -1
                    entry.highSlot = -1
                }

                // Start background caching (fire and forget)
                this.startBackgroundCaching(entry)

                // Set state to CACHING - will be re-requested when cache is ready
                entry.state = HighTextureState.CACHING
                return false
            }

            const fetchTime = window.performance.now() - fetchStart

            // Verify size matches texture array expectations
            const expectedSize = this.config.textureWidth * this.config.textureHeight * 4
            if (imageData.length !== expectedSize) {
                HighTextureCache.logger.warn(`HIGH texture data size mismatch for "${entry.gameName}": expected ${expectedSize}, got ${imageData.length}`)
                entry.state = HighTextureState.FAILED
                return false
            }

            // Schedule the texture copy to run when we have frame budget
            // This is the main optimization - spreads work across frames when
            // multiple worker responses arrive simultaneously
            const sliceSize = this.config.textureWidth * this.config.textureHeight * 4
            const offset = entry.highSlot * sliceSize
            const arrayData = this.dataArrayTexture.image.data as Uint8Array
            const capturedGameIndex = entry.gameIndex
            const capturedSlot = entry.highSlot
            const capturedGameName = entry.gameName

            // Schedule entire completion: copy + state update + callback
            // This ensures we don't flood the main thread when many textures complete at once
            const doTextureCompletion = () => {
                const copyStart = window.performance.now()
                arrayData.set(imageData, offset)
                const copyTime = window.performance.now() - copyStart

                // Mark this specific slot as dirty for partial GPU upload
                // This enables uploading just ~540KB per slot instead of ~34MB for all slots
                this.isDirty = true
                this.dirtySlots.add(capturedSlot)

                // State updates happen in the scheduled task
                entry.state = HighTextureState.LOADED
                entry.lastAccessTime = window.performance.now()

                // Notify callback so renderer can update highTextureSlot attribute
                if (this.onSlotChange) {
                    this.onSlotChange(capturedGameIndex, capturedSlot)
                }

                // Record profiling if enabled
                if (this.profilingEnabled) {
                    this.recordProfilingSample({
                        gameIndex: capturedGameIndex,
                        gameName: capturedGameName,
                        workerRoundTrip,
                        arrayBufferCopy: arrayBufferCopyTime,
                        textureArrayCopy: copyTime,
                        callbackTime: 0,
                        totalMainThread: arrayBufferCopyTime + copyTime,
                        pixelCacheHit,
                        timestamp: window.performance.now()
                    })
                }
            }

            // Use tryExecuteOrSchedule: runs immediately if we have budget, otherwise schedules
            const executedImmediately = this.scheduler.tryExecuteOrSchedule(doTextureCompletion, {
                estimatedMs: 0.5,  // Based on profiling: avg 0.2ms, max 1ms
                priority: 'normal',
                maxDeferMs: 500   // Don't wait more than 500ms (30 frames at 60fps)
            })

            const totalTime = window.performance.now() - loadStart
            const inFlight = this.loadingPromises.size - 1  // -1 because this one is about to complete
            const cacheStatus = pixelCacheHit ? '≡ƒƒó PIXEL HIT' : '≡ƒö┤ PIXEL MISS'
            const scheduled = executedImmediately ? 'immediate' : 'scheduled'
            HighTextureCache.logger.debug(`COMPLETE HIGH ${entry.gameIndex} ΓåÆ slot ${capturedSlot} "${capturedGameName.slice(0, 20)}" | ${cacheStatus} | total: ${totalTime.toFixed(0)}ms (fetch: ${fetchTime.toFixed(0)}ms, copy: ${scheduled}) | in-flight: ${inFlight}, queue: ${this.loadQueue.length}`)

            // Record timing sample for diagnostics (copyTime tracked separately in scheduler callback)
            this.recordTimingSample({
                gameIndex: entry.gameIndex,
                gameName: entry.gameName,
                fetchTime,
                processTime,
                copyTime: 0,  // Now measured in scheduler callback
                totalTime,
                timestamp: window.performance.now(),
                pixelCacheHit
            })

            return true

        } catch (error) {
            const msg = error instanceof Error ? error.message : String(error)
            HighTextureCache.logger.debug(`Failed to load HIGH texture "${entry.gameName}": ${msg}`)
            entry.state = HighTextureState.FAILED
            // Free the slot since we failed
            if (entry.highSlot >= 0) {
                this.slotToGame[entry.highSlot] = -1
                entry.highSlot = -1
            }
            return false
        }
    }

    /**
     * Mark a specific game for eviction (e.g., player moved away)
     * This is a hint - the texture will be evicted when space is needed
     */
    public markForEviction(gameIndex: number): void {
        const entry = this.games.get(gameIndex)
        if (!entry || entry.state !== HighTextureState.LOADED) {
            return
        }

        // Set access time to 0 so it's evicted first
        entry.lastAccessTime = 0
        HighTextureCache.logger.debug(`Marked for eviction: game ${gameIndex} slot ${entry.highSlot} "${entry.gameName.slice(0, 20)}"`)
    }

    /**
     * Evict the least-recently-used loaded HIGH texture
     * @returns the freed slot index, or -1 if nothing to evict
     */
    private evictLru(): number {
        let lruEntry: GameEntry | null = null
        let lruTime = Infinity

        for (const entry of this.games.values()) {
            if (entry.state === HighTextureState.LOADED && entry.lastAccessTime < lruTime) {
                lruTime = entry.lastAccessTime
                lruEntry = entry
            }
        }

        if (!lruEntry || lruEntry.highSlot < 0) {
            return -1
        }

        const freedSlot = lruEntry.highSlot

        // Clear the slot assignment
        this.slotToGame[freedSlot] = -1

        // Reset entry state
        lruEntry.state = HighTextureState.EMPTY
        lruEntry.highSlot = -1
        this.stats.evictions++

        // Notify callback so renderer can update highTextureSlot attribute to -1
        if (this.onSlotChange) {
            this.onSlotChange(lruEntry.gameIndex, -1)
        }

        HighTextureCache.logger.runtime(`Evicted game ${lruEntry.gameIndex} from slot ${freedSlot} "${lruEntry.gameName.slice(0, 20)}"`)
        return freedSlot
    }

    /**
     * Count used slots
     */
    private getUsedSlotCount(): number {
        return this.slotToGame.filter(g => g >= 0).length
    }

    /**
     * Estimate memory usage in MB
     */
    private estimateMemoryMB(): number {
        const bytesPerTexture = this.config.textureWidth * this.config.textureHeight * 4
        return (this.config.totalSlots * bytesPerTexture) / (1024 * 1024)
    }

    /**
     * Get cache statistics
     */
    public getStats(): HighTextureCacheStats {
        let loaded = 0, loading = 0, failed = 0, empty = 0, caching = 0, permanentFailures = 0

        for (const entry of this.games.values()) {
            switch (entry.state) {
                case HighTextureState.LOADED: loaded++; break
                case HighTextureState.LOADING: loading++; break
                case HighTextureState.FAILED: failed++; break
                case HighTextureState.EMPTY: empty++; break
                case HighTextureState.CACHING: caching++; break
                case HighTextureState.PERMANENT_FAILURE: permanentFailures++; break
            }
        }

        return {
            loaded,
            loading,
            failed,
            empty,
            caching,
            permanentFailures,
            backgroundCacheQueue: this.backgroundCachingGames.size,
            totalSlots: this.config.totalSlots,
            usedSlots: this.getUsedSlotCount(),
            queueLength: this.loadQueue.length,
            activeLoads: this.loadingPromises.size,
            ...this.stats
        }
    }

    /**
     * Log cache statistics
     */
    public logStats(): void {
        const stats = this.getStats()
        HighTextureCache.logger.info(`HIGH Texture Cache: ${stats.loaded}/${stats.totalSlots} loaded, ${stats.loading} loading, ${stats.failed} failed, ${stats.evictions} evictions, ${stats.cacheHits}/${stats.cacheHits + stats.cacheMisses} cache hits`)
    }

    // ========================================================================
    // Protected getters for debug class access
    // ========================================================================

    protected getGames(): Map<number, GameEntry> {
        return this.games
    }

    protected getSlotToGame(): number[] {
        return this.slotToGame
    }

    protected getLoadQueue(): number[] {
        return this.loadQueue
    }

    protected getLoadingPromises(): Map<number, Promise<boolean>> {
        return this.loadingPromises
    }

    protected getConfig(): HighTextureCacheConfig {
        return this.config
    }

    protected getInternalStats(): typeof this.stats {
        return this.stats
    }

    protected getDataArrayTexture(): THREE.DataArrayTexture | null {
        return this.dataArrayTexture
    }

    protected getTimingSamples(): typeof this.timingSamples {
        return this.timingSamples
    }

    protected getMaxTimingSamples(): number {
        return this.MAX_TIMING_SAMPLES
    }

    protected getProfilingSamples(): typeof this.profilingSamples {
        return this.profilingSamples
    }

    protected isProfilingEnabled(): boolean {
        return this.profilingEnabled
    }

    protected setProfilingEnabled(enabled: boolean): void {
        this.profilingEnabled = enabled
    }

    protected clearProfilingSamples(): void {
        this.profilingSamples = []
    }

    protected clearTimingSamplesInternal(): void {
        this.timingSamples = []
    }

    /**
     * Force-evict a specific game's HIGH texture
     */
    public evictGame(gameIndex: number): boolean {
        const entry = this.games.get(gameIndex)
        if (!entry || entry.highSlot < 0) {
            return false
        }

        const freedSlot = entry.highSlot
        this.slotToGame[freedSlot] = -1
        entry.state = HighTextureState.EMPTY
        entry.highSlot = -1
        this.stats.evictions++

        if (this.onSlotChange) {
            this.onSlotChange(entry.gameIndex, -1)
        }

        return true
    }

    public dispose(): void {
        this.games.clear()
        this.loadingPromises.clear()
        this.loadQueue = []
        this.slotToGame = []
        this.textureWorker.dispose()
        HighTextureCache.logger.lifecycle('Disposed')
    }

    private recordTimingSample(sample: {
        gameIndex: number
        gameName: string
        fetchTime: number
        processTime: number
        copyTime: number
        totalTime: number
        timestamp: number
        pixelCacheHit: boolean
    }): void {
        this.timingSamples.push(sample)
        if (this.timingSamples.length > this.MAX_TIMING_SAMPLES) {
            this.timingSamples.shift()
        }
    }

    private recordProfilingSample(sample: {
        gameIndex: number
        gameName: string
        workerRoundTrip: number
        arrayBufferCopy: number
        textureArrayCopy: number
        callbackTime: number
        totalMainThread: number
        pixelCacheHit: boolean
        timestamp: number
    }): void {
        this.profilingSamples.push(sample)
        if (this.profilingSamples.length > this.MAX_PROFILING_SAMPLES) {
            this.profilingSamples.shift()
        }
    }
}

