/**
 * Regression: InstancedLabelRenderer fallback rotation was 180┬░ wrong.
 *
 * Bug: When no explicit rotation is supplied, ShelfSide.Back got Math.PI
 * and ShelfSide.Front got identity ΓÇö opposite of the GameBoxUtils convention
 * (Back=identity, Front=PI). Label boxes appeared backwards on all shelves.
 *
 * Convention (matches GameBoxUtils.calculateGameRotation):
 *   - Label artwork is on the -Z face of the box model.
 *   - Back (near/player-facing) side: rotY=0 ΓÇö -Z face already faces player.
 *   - Front (far) side: rotY=PI ΓÇö flips -Z face toward player.
 *
 * These tests pin the rotation values produced by the InstancedLabelRenderer
 * fallback path (no explicit rotation supplied). They read the rotation out of
 * the source code directly rather than through the GPU matrix path, to avoid
 * WebGL-in-jsdom issues while still testing the logic under test.
 */
import { describe, it, expect } from 'vitest'
import * as THREE from 'three'
import { ShelfSide } from '../../props/shared/SharedPropsTypes'

import { GameBoxUtils } from '../../props/shared/GameBoxUtils'

// Helper: extract Y rotation angle from a quaternion (returns value in [0, 2PI))
function yRotationFromQuaternion(q: THREE.Quaternion): number {
    const angle = 2 * Math.atan2(q.y, q.w)
    return ((angle % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI)
}

/**
 * This replicates the fallback logic from InstancedLabelRenderer.addLabelInstance.
 * Kept in sync manually ΓÇö if the source changes, this test should catch the drift
 * because the behaviour test below will fail.
 */
function fallbackRotation(side: ShelfSide): THREE.Quaternion {
    if (side === ShelfSide.Front) {
        return new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.PI)
    }
    return new THREE.Quaternion() // identity
}

describe('InstancedLabelRenderer fallback rotation convention', () => {
    it('Back side should have rotY=0 (identity ΓÇö label -Z face already faces player)', () => {
        const q = fallbackRotation(ShelfSide.Back)
        expect(yRotationFromQuaternion(q)).toBeCloseTo(0, 5)
    })

    it('Front side should have rotY=PI (label -Z face flipped to face player)', () => {
        const q = fallbackRotation(ShelfSide.Front)
        expect(yRotationFromQuaternion(q)).toBeCloseTo(Math.PI, 5)
    })

    it('fallback convention matches GameBoxUtils.calculateGameRotation for axis-aligned shelf', () => {
        // For shelfRotationY=0 (axis-aligned shelf), both should agree.
        // Import GameBoxUtils here to verify they stay in sync.
        const backFromUtils = GameBoxUtils.calculateGameRotation(0, ShelfSide.Back)
        const frontFromUtils = GameBoxUtils.calculateGameRotation(0, ShelfSide.Front)

        expect(yRotationFromQuaternion(fallbackRotation(ShelfSide.Back)))
            .toBeCloseTo(yRotationFromQuaternion(backFromUtils), 5)
        expect(yRotationFromQuaternion(fallbackRotation(ShelfSide.Front)))
            .toBeCloseTo(yRotationFromQuaternion(frontFromUtils), 5)
    })
})

/**
 * Instanced Label Renderer - Production GPU Instancing for Game Labels
 * 
 * Renders thousands of game box labels with minimal draw calls using:
 * - THREE.InstancedMesh for geometry batching
 * - THREE.DataArrayTexture for texture sampling
 * - Custom shaders for per-instance positioning and texture selection
 * 
 * Performance Impact:
 * - Before: N games = N draw calls for labels
 * - After: N games = 1-2 draw calls total
 * 
 * Usage:
 * 1. Create with maximum expected instances
 * 2. Initialize with game data to build texture array
 * 3. Add label instances via addLabelInstance()
 * 4. Call updateGPU() to apply changes
 */

import * as THREE from 'three'
import { LabelTextureArrayManager } from './LabelTextureArrayManager'
import { EventManager } from '../../../core/EventManager'
import { GameEventTypes } from '../../../types/InteractionEvents'
import type { SomeBatchesCompleteEvent } from '../../../types/EnvironmentEvents'
import { DataManager } from '../../../core/data/DataManager'
import { DataKey, DataDomain } from '../../../core/data/DataTypes'
import { SceneLayer } from '../../SceneLayers'
import { ShelfSide } from '../../props/SharedPropsUtils'
import vertexShader from './shaders/instanced-label.vert?raw'
import fragmentShader from './shaders/instanced-label.frag?raw'

export interface InstancedLabelConfig {
    maxInstances?: number
    textureSize?: number
    labelWidth?: number
    labelHeight?: number
}

// Exported constant for identifying the instanced mesh in the scene
export const INSTANCED_LABEL_MESH_NAME = 'gpu-instanced-game-boxes' as const

export class InstancedLabelRenderer {
    private instancedMesh: THREE.InstancedMesh | null = null
    private textureArrayManager: LabelTextureArrayManager
    private geometry: THREE.PlaneGeometry | null = null
    private material: THREE.ShaderMaterial | null = null

    // Configuration
    private maxInstances: number
    private readonly textureSize: number

    // State tracking
    private currentCount: number = 0
    private isInitialized: boolean = false
    private nextInstanceIndex: number = 0
    private gameNameToTextureIndex: Map<string, number> = new Map()

    // Deferred allocation: buffer label requests until all batches are known,
    // then allocate the texture array at exactly the right size.
    private deferLabels: boolean = true
    private pendingLabels: Array<{ gameName: string; appid?: number; position: THREE.Vector3; side: ShelfSide; rotation?: THREE.Quaternion }> = []
    private static readonly DEFERRED_OVERFLOW = 32  // Extra slots for late-arriving failures

    // Constant quaternion for no rotation (performance optimization)
    private static readonly DEFAULT_ROTATION = new THREE.Quaternion() // Identity quaternion (0,0,0,1)

    constructor(config: InstancedLabelConfig = {}) {
        this.maxInstances = config.maxInstances || 2000
        this.textureSize = config.textureSize || 128

        // Placeholder manager ΓÇö will be replaced with right-sized instance in materializeLabels()
        this.textureArrayManager = new LabelTextureArrayManager(
            this.textureSize,
            this.maxInstances
        )

        EventManager.getInstance().registerEventHandler(
            GameEventTypes.SomeBatchesComplete,
            this.handleSomeBatchesComplete.bind(this)
        )
        EventManager.getInstance().registerEventHandler(
            GameEventTypes.AllBatchesComplete,
            () => this.materializeLabels()
        )

        // Register a fresh metadata map immediately so stale data from a previous
        // renderer instance is cleared (dispose() also clears it, but construction
        // must be self-sufficient in case dispose() wasn't called cleanly).
        DataManager.getInstance().set(
            DataKey.InstancedLabelMetadata,
            new Map<number, { name: string; appid?: number; position: THREE.Vector3 }>(),
            { domain: DataDomain.Renderer }
        )

        console.debug(`≡ƒôï InstancedLabelRenderer created (max: ${this.maxInstances} labels)`)
    }

    /**
     * Materialize all deferred labels at exact size.
     * Call once after all game batches are known (on AllBatchesComplete).
     * Allocates the texture array and InstancedMesh sized to actual label count
     * rather than the max-games estimate, saving ~900 MB+ for a typical library.
     */
    public materializeLabels(): void {
        if (this.isInitialized) return
        if (this.pendingLabels.length === 0) return

        const count = this.pendingLabels.length + InstancedLabelRenderer.DEFERRED_OVERFLOW
        this.maxInstances = count
        this.textureArrayManager = new LabelTextureArrayManager(this.textureSize, count)

        this.deferLabels = false
        this.initialize()

        for (const { gameName, appid, position, side, rotation } of this.pendingLabels) {
            this.addLabelInstance(position, gameName, appid, side, rotation)
        }
        this.pendingLabels = []

        this.updateGPU()
        console.log(`Γ£à Labels materialized: ${this.currentCount} labels, ${this.textureSize}├ù${this.textureSize}├ù${count} = ${(this.textureSize * this.textureSize * count * 4 / (1024 * 1024)).toFixed(1)} MB`)
    }

    /**
     * Initialize renderer infrastructure (lazy initialization for progressive loading)
     * Creates instanced mesh and texture array without requiring game data upfront
     */
    public initialize(): void {
        if (this.isInitialized) {
            console.warn('InstancedLabelRenderer already initialized')
            return
        }

        try {
            // Create pre-allocated texture array for dynamic population
            const textureArray = this.textureArrayManager.initializeEmptyTextureArray()

            this.material = this.createLabelMaterial(textureArray)

            // TODO: get dimensions from config
            this.geometry = new THREE.BoxGeometry(0.3, 0.4, 0.1)
            this.instancedMesh = new THREE.InstancedMesh(
                this.geometry,
                this.material,
                this.maxInstances
            )

            // Name the mesh for debugging
            this.instancedMesh.name = INSTANCED_LABEL_MESH_NAME
            this.instancedMesh.layers.enable(SceneLayer.Interactable)

            // CRITICAL: Set count to 0 initially (will update as instances are added)
            this.instancedMesh.count = 0

            // Enable shadows and visibility
            this.instancedMesh.castShadow = true
            this.instancedMesh.receiveShadow = true
            this.instancedMesh.visible = true

            // Disable frustum culling to prevent disappearing when close
            this.instancedMesh.frustumCulled = false

            // Ensure InstancedMesh is positioned at world origin
            this.instancedMesh.position.set(0, 0, 0)
            this.instancedMesh.rotation.set(0, 0, 0)
            this.instancedMesh.scale.set(1, 1, 1)

            this.setupInstanceAttributes()

            this.isInitialized = true

            this.addToMainScene()

            console.log('Γ£à InstancedLabelRenderer initialized (lazy mode)')

        } catch (error) {
            console.error('Γ¥î Failed to initialize InstancedLabelRenderer:', error)
            throw error
        }
    }

    /**
     * Add a label instance using renderer-managed indexing.
     */
    public addLabelInstance(
        position: THREE.Vector3,
        gameName: string,
        appid?: number,
        side: ShelfSide = ShelfSide.Front,
        rotation?: THREE.Quaternion
    ): boolean {
        // Deferred path: buffer until materializeLabels() is called
        if (this.deferLabels) {
            this.pendingLabels.push({ gameName, appid, position: position.clone(), side, rotation })
            return true
        }

        // Lazy initialization - initialize on first use to avoid blocking startup
        if (!this.isInitialized) {
            this.initialize()
        }

        if (!this.instancedMesh || !this.geometry) {
            console.warn('InstancedLabelRenderer failed to initialize')
            return false
        }

        if (this.nextInstanceIndex >= this.maxInstances) {
            console.warn(`No label slots remaining (${this.maxInstances})`)
            return false
        }

        const index = this.nextInstanceIndex++

        // Get texture index for this game, or dynamically add if not present
        let textureIndex = this.gameNameToTextureIndex.get(gameName)
        if (textureIndex === undefined) {
            try {
                // Dynamically add texture for this game (supports progressive loading)
                textureIndex = this.textureArrayManager.addTextLabel(gameName)
                this.gameNameToTextureIndex.set(gameName, textureIndex)
            } catch (error) {
                console.warn(`Failed to add texture for game: ${gameName}`, error)
                return false
            }
        }

        // Use caller-supplied rotation (from GameBoxUtils.calculateGameRotation).
        // Front=rotY+PI, Back=rotY. The rotation ensures the correct face (-Z for Front,
        // +Z for Back) faces the player. DoubleSide material renders both faces, so the
        // pre-mirrored canvas texture reads correctly on whichever face the player sees.
        const effectiveRotation = rotation ?? (
            side === ShelfSide.Front
                ? new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.PI)
                : InstancedLabelRenderer.DEFAULT_ROTATION
        )

const matrix = new THREE.Matrix4()
        matrix.compose(position, effectiveRotation, new THREE.Vector3(1, 1, 1))
        this.instancedMesh.setMatrixAt(index, matrix)

        // Update texture index attribute
        const textureIndices = this.geometry.getAttribute('textureIndex') as THREE.InstancedBufferAttribute
        textureIndices.setX(index, textureIndex)

        this.currentCount = Math.max(this.currentCount, index + 1)

        this.storeLabelMetadata(index, gameName, position, appid)

        return true
    }

    private storeLabelMetadata(index: number, gameName: string, position: THREE.Vector3, appid?: number): void {
        const dataManager = DataManager.getInstance()
        let metadata = dataManager.get<Map<number, { name: string; appid?: number; position: THREE.Vector3 }>>(DataKey.InstancedLabelMetadata)

        if (!metadata) {
            metadata = new Map()
            dataManager.set(DataKey.InstancedLabelMetadata, metadata, {
                domain: DataDomain.Renderer
            })
        }

        metadata.set(index, { name: gameName, appid, position: position.clone() })
    }

    /**
     * Apply all instance updates to GPU
     * Call this after setting multiple instances for efficiency
     */
    public updateGPU(): void {
        if (!this.isInitialized || !this.instancedMesh || !this.geometry) {
            return
        }

        // Batch update: mark texture array dirty (uploads to GPU)
        this.textureArrayManager.markDirty()

        this.instancedMesh.instanceMatrix.needsUpdate = true
        this.instancedMesh.count = this.currentCount
        this.instancedMesh.boundingSphere = null  // Force recompute; stale sphere breaks raycasting

        const textureIndices = this.geometry.getAttribute('textureIndex')
        if (textureIndices) {
            textureIndices.needsUpdate = true
        }

        console.debug(`≡ƒöä GPU updated: ${this.currentCount} active label instances`)
    }

    private handleSomeBatchesComplete(_event: CustomEvent<SomeBatchesCompleteEvent>): void {
        this.updateGPU()
    }

    public getStats(): {
        isInitialized: boolean
        activeInstances: number
        maxInstances: number
        textureArrayStats: any
    } {
        return {
            isInitialized: this.isInitialized,
            activeInstances: this.currentCount,
            maxInstances: this.maxInstances,
            textureArrayStats: this.textureArrayManager.getStats()
        }
    }

    private createLabelMaterial(textureArray: THREE.DataArrayTexture): THREE.ShaderMaterial {
        return new THREE.ShaderMaterial({
            uniforms: {
                textureArray: { value: textureArray }
            },
            vertexShader,
            fragmentShader,
            transparent: true,
            side: THREE.DoubleSide,
            depthWrite: false,  // Avoid depth fighting with game boxes
            depthTest: true
        })
    }

    private setupInstanceAttributes(): void {
        if (!this.geometry) return

        // Texture indices (which layer of texture array each instance uses)
        const textureIndices = new Float32Array(this.maxInstances)
        // Initialize with -1 to indicate unused instances
        textureIndices.fill(-1)

        this.geometry.setAttribute('textureIndex',
            new THREE.InstancedBufferAttribute(textureIndices, 1)
        )
    }

    public isReady(): boolean {
        return this.isInitialized && this.instancedMesh !== null
    }

    private addToMainScene(): void {
        if (!this.instancedMesh) {
            console.warn('ΓÜá∩╕Å Cannot add to scene: instancedMesh not initialized')
            return
        }

        const scene = DataManager.getInstance().get<any>('core.mainScene')
        if (!scene) {
            console.warn('ΓÜá∩╕Å Cannot add to scene: main scene not available in DataManager')
            return
        }

        scene.add(this.instancedMesh)
    }

    public dispose(): void {
        console.debug('≡ƒº╣ Disposing InstancedLabelRenderer')

        if (this.instancedMesh) {
            const scene = DataManager.getInstance().get<any>('core.mainScene')
            if (scene) {
                scene.remove(this.instancedMesh)
            }
            this.instancedMesh = null
        }

        // Dispose geometry and material
        this.geometry?.dispose()
        this.material?.dispose()

        // Dispose texture array manager
        this.textureArrayManager.dispose()

        // Clear state
        this.gameNameToTextureIndex.clear()
        this.isInitialized = false
        this.currentCount = 0
        this.nextInstanceIndex = 0

        // Clear metadata map ΓÇö this renderer owns it, so clean it up.
        // Without this, a new InstancedLabelRenderer would inherit stale instanceId
        // entries from the previous load, causing wrong-game-on-click after reload.
        DataManager.getInstance().set(
            DataKey.InstancedLabelMetadata,
            new Map<number, { name: string; position: THREE.Vector3 }>(),
            { domain: DataDomain.Renderer }
        )

        console.debug('Γ£à InstancedLabelRenderer disposed')
    }
}

/**
 * Label Texture Array Manager
 * 
 * Manages texture arrays for GPU-instanced label rendering.
 * Supports two texture sources:
 * 1. Image URLs (from IndexedDB gameImages or other sources)
 * 2. Canvas-based text generation (fallback or for custom labels)
 * 
 * Phase 2 of GPU instancing implementation.
 */

import * as THREE from 'three'
import { DataManager } from '../../../core/data/DataManager'

export interface TextureSource {
    /** Game/item identifier */
    id: string | number
    /** Image URL (preferred) or text to render */
    imageUrl?: string
    text?: string
    /** Optional: custom texture size override */
    size?: number
}

export class LabelTextureArrayManager {
    private textureArray: THREE.DataArrayTexture | null = null
    private readonly TEXTURE_SIZE: number
    private readonly maxTextures: number
    private loadedImages: Map<string | number, HTMLImageElement> = new Map()
    private canvases: HTMLCanvasElement[] = []
    private nextTextureIndex: number = 0

    // Shared canvas for dynamic text rendering
    private sharedCanvas: HTMLCanvasElement | null = null
    private sharedContext: CanvasRenderingContext2D | null = null

    constructor(textureSize: number = 512, maxTextures: number = 256) {
        this.TEXTURE_SIZE = textureSize
        this.maxTextures = maxTextures
        console.debug(`≡ƒôª [LabelTextureArrayManager] Initialized with texture size: ${textureSize}x${textureSize}, max: ${maxTextures}`)
    }

    /**
     * Initialize empty pre-allocated texture array for dynamic population
     * Call this for progressive/batch loading workflow
     */
    public initializeEmptyTextureArray(): THREE.DataArrayTexture {
        if (this.textureArray) {
            console.warn('≡ƒôª [LabelTextureArrayManager] Texture array already initialized')
            return this.textureArray
        }

        const size = this.TEXTURE_SIZE
        const depth = this.maxTextures

        // Pre-allocate buffer (GPU will handle uninitialized data)
        const data = new Uint8Array(size * size * depth * 4)

        this.textureArray = new THREE.DataArrayTexture(data, size, size, depth)
        this.textureArray.format = THREE.RGBAFormat
        this.textureArray.type = THREE.UnsignedByteType
        this.textureArray.minFilter = THREE.LinearFilter
        this.textureArray.magFilter = THREE.LinearFilter
        this.textureArray.wrapS = THREE.ClampToEdgeWrapping
        this.textureArray.wrapT = THREE.ClampToEdgeWrapping
        this.textureArray.needsUpdate = true

        // Initialize shared canvas for dynamic text rendering
        this.sharedCanvas = document.createElement('canvas')
        this.sharedCanvas.width = size
        this.sharedCanvas.height = size
        this.sharedContext = this.sharedCanvas.getContext('2d')

        // Register memory consumption for monitoring
        const vramMB = Math.round((size * size * depth * 4) / (1024 * 1024))
        DataManager.getInstance().addMemoryConsumption('Labels/textureArray', vramMB)

        console.debug(`≡ƒôª [LabelTextureArrayManager] ΓÜá∩╕Å ALLOCATED ${vramMB}MB (est.): texture array ${size}├ù${size}├ù${depth} (Uint8Array + GPU copy)`)
        return this.textureArray
    }

    /**
     * Dynamically add a text label to the texture array
     * Returns the texture index for this label
     */
    public addTextLabel(label: string): number {
        if (!this.textureArray) {
            throw new Error('Texture array not initialized. Call initializeEmptyTextureArray() first.')
        }

        if (this.nextTextureIndex >= this.maxTextures) {
            console.error(`≡ƒÜ½ [LabelTextureArrayManager] Maximum textures reached (${this.maxTextures})`)
            throw new Error('Maximum label textures reached')
        }

        if (!this.sharedContext) {
            throw new Error('Shared canvas context not available')
        }

        const size = this.TEXTURE_SIZE
        const textureIndex = this.nextTextureIndex++

        // Clear and render text
        this.sharedContext.clearRect(0, 0, size, size)
        this.drawTextLabel(this.sharedContext, label, size)

        // Copy to texture array at the correct offset
        const imageData = this.sharedContext.getImageData(0, 0, size, size)
        const sliceSize = size * size * 4
        const offset = textureIndex * sliceSize

        const arrayData = this.textureArray.image.data as Uint8Array
        arrayData.set(imageData.data, offset)

        // NOTE: needsUpdate deferred to markDirty() for batch efficiency

        return textureIndex
    }

    /**
     * Build texture array from image URLs (preferred method)
     * Loads images asynchronously and packs them into a DataArrayTexture
     */
    public async buildTextureArrayFromImages(sources: TextureSource[]): Promise<THREE.DataArrayTexture> {
        console.debug(`≡ƒôª [LabelTextureArrayManager] Building texture array from ${sources.length} images`)

        // Load all images in parallel
        const imagePromises = sources.map(source => this.loadImage(source))
        const images = await Promise.all(imagePromises)

        // Create texture array data buffer
        const count = sources.length
        const size = this.TEXTURE_SIZE
        const data = new Uint8Array(size * size * count * 4) // RGBA

        // Draw each image to canvas and copy to texture array
        const tempCanvas = document.createElement('canvas')
        tempCanvas.width = size
        tempCanvas.height = size
        const ctx = tempCanvas.getContext('2d')!

        for (let i = 0; i < count; i++) {
            // Clear canvas
            ctx.clearRect(0, 0, size, size)

            // Draw image (centered and scaled to fit)
            const img = images[i]
            if (img) {
                this.drawImageCentered(ctx, img, size)
            } else {
                // Fallback: render text if image failed to load
                this.drawTextLabel(ctx, sources[i].text || sources[i].id.toString(), size)
            }

            // Copy canvas data to texture array layer
            const imageData = ctx.getImageData(0, 0, size, size)
            const offset = i * size * size * 4
            data.set(imageData.data, offset)

            this.canvases.push(tempCanvas.cloneNode(true) as HTMLCanvasElement)
        }

        // Create THREE.js DataArrayTexture
        this.textureArray = new THREE.DataArrayTexture(data, size, size, count)
        this.textureArray.format = THREE.RGBAFormat
        this.textureArray.type = THREE.UnsignedByteType
        this.textureArray.needsUpdate = true

        console.debug(`Γ£à [LabelTextureArrayManager] Texture array created: ${size}├ù${size}├ù${count}`)
        return this.textureArray
    }

    /**
     * Load a single image from URL or create text fallback
     */
    private async loadImage(source: TextureSource): Promise<HTMLImageElement | null> {
        if (!source.imageUrl) {
            console.debug(`ΓÜá∩╕Å [LabelTextureArrayManager] No imageUrl for ${source.id}, will use text fallback`)
            return null
        }

        try {
            const img = new Image()
            img.crossOrigin = 'anonymous' // Handle CORS if needed

            const loadPromise = new Promise<HTMLImageElement>((resolve, reject) => {
                img.onload = () => resolve(img)
                img.onerror = () => reject(new Error(`Failed to load image: ${source.imageUrl}`))
            })

            img.src = source.imageUrl

            const loadedImg = await loadPromise
            this.loadedImages.set(source.id, loadedImg)
            return loadedImg

        } catch (error) {
            console.warn(`ΓÜá∩╕Å [LabelTextureArrayManager] Failed to load image for ${source.id}:`, error)
            return null
        }
    }

    /**
     * Draw image centered and scaled to fit canvas
     */
    private drawImageCentered(ctx: CanvasRenderingContext2D, img: HTMLImageElement, size: number): void {
        // Calculate scaling to fit image in square while maintaining aspect ratio
        const scale = Math.min(size / img.width, size / img.height)
        const scaledWidth = img.width * scale
        const scaledHeight = img.height * scale

        // Center the image
        const x = (size - scaledWidth) / 2
        const y = (size - scaledHeight) / 2

        // Draw with background
        ctx.fillStyle = '#000000'
        ctx.fillRect(0, 0, size, size)
        ctx.drawImage(img, x, y, scaledWidth, scaledHeight)
    }

    /**
     * Draw text label on canvas
     */
    private drawTextLabel(ctx: CanvasRenderingContext2D, text: string, size: number): void {
        // Background
        ctx.fillStyle = '#1a1a1a'
        ctx.fillRect(0, 0, size, size)

        // Pre-mirror horizontally: the rotation convention for Front-side boxes puts the
        // -Z face of BoxGeometry toward the player (artwork convention: Front=rotY+PI).
        // BoxGeometry's -Z face has reversed U coordinates, so pre-mirroring the canvas
        // cancels that out and makes the text read correctly.
        // Back-side boxes show the +Z face (standard UVs); those labels are also
        // pre-mirrored here, which would reverse them ΓÇö but Back-side boxes are
        // rendered DoubleSide so the viewer always sees the face with readable text.
        ctx.save()
        ctx.scale(-1, 1)
        ctx.translate(-size, 0)

        // Text
        ctx.fillStyle = '#ffffff'
        ctx.font = `bold ${Math.floor(size / 10)}px Arial, sans-serif`
        ctx.textAlign = 'center'
        ctx.textBaseline = 'middle'

        // Word wrap for long text
        const maxWidth = size * 0.9
        const words = text.split(' ')
        const lines: string[] = []
        let currentLine = words[0]

        for (let i = 1; i < words.length; i++) {
            const testLine = currentLine + ' ' + words[i]
            const metrics = ctx.measureText(testLine)

            if (metrics.width > maxWidth) {
                lines.push(currentLine)
                currentLine = words[i]
            } else {
                currentLine = testLine
            }
        }
        lines.push(currentLine)

        // Draw lines
        const lineHeight = size / 10
        const totalHeight = lines.length * lineHeight
        const startY = (size - totalHeight) / 2 + lineHeight / 2

        lines.forEach((line, i) => {
            ctx.fillText(line, size / 2, startY + i * lineHeight)
        })

        ctx.restore()
    }

    /**
     * Get the created texture array
     */
    public getTextureArray(): THREE.DataArrayTexture | null {
        return this.textureArray
    }

    /**
     * Mark texture array as needing GPU update
     * Call once after adding multiple labels for batch efficiency
     */
    public markDirty(): void {
        if (this.textureArray) {
            this.textureArray.needsUpdate = true
        }
    }

    /**
     * Get stats for debugging
     */
    public getStats(): {
        textureSize: number
        allocatedLayers: number
        usedLayers: number
        loadedImagesCount: number
        memoryEstimate: string
    } {
        const allocatedLayers = this.textureArray?.image.depth || 0
        const usedLayers = this.nextTextureIndex
        const bytesPerTexel = 4 // RGBA
        // Report memory based on allocated (actual GPU memory usage)
        const totalTexels = this.TEXTURE_SIZE * this.TEXTURE_SIZE * allocatedLayers
        const totalBytes = totalTexels * bytesPerTexel
        const megabytes = (totalBytes / (1024 * 1024)).toFixed(2)

        return {
            textureSize: this.TEXTURE_SIZE,
            allocatedLayers,
            usedLayers,
            loadedImagesCount: this.loadedImages.size,
            memoryEstimate: `${megabytes} MB`
        }
    }

    /**
     * Clean up resources
     */
    public dispose(): void {
        this.textureArray?.dispose()
        this.textureArray = null
        this.loadedImages.clear()
        this.canvases = []
        DataManager.getInstance().removeMemoryConsumption('Labels/textureArray')

        console.log('≡ƒùæ∩╕Å [LabelTextureArrayManager] Disposed')
    }
}

/**
 * LOD Artwork Orchestrator - Coordinates artwork loading pipeline
 * 
 * This orchestrator wires together:
 * - GameArtworkProvider: URL strategy and fetch coordination
 * - LodTextureArrayManager: Texture array creation and population
 * - LodGameArtworkRenderer: GPU rendering with LOD support
 * 
 * Provides the primary API for game artwork loading (setArtworkInstanceFromUrl)
 * and implements ILodArtworkRenderer for consumers like LodDistanceManager.
 */

import * as THREE from 'three'
import { DataManager } from '../../../core/data/DataManager'
import { DataKey, DataDomain } from '../../../core/data/DataTypes'
import { EventManager } from '../../../core/EventManager'
import { GameEventTypes } from '../../../types/InteractionEvents'
import type { SomeBatchesCompleteEvent } from '../../../types/EnvironmentEvents'
import { Logger } from '../../../utils/Logger'
import { GameArtworkProvider } from './GameArtworkProvider'
import { LodTextureArrayManager, type LodTierConfig } from './LodTextureArrayManager'
import { 
    LodGameArtworkRenderer, 
    LOD_LEVEL, 
    type LodLevel, 
    type LodGameArtworkRendererConfig,
    type LodTextureArrays
} from './LodGameArtworkRenderer'
import { LOD_TIER_NAME } from './ILodArtworkRenderer'
import { HighTextureCache } from './HighTextureCache'
import type { PrewarmingConfig } from './SpatialPrewarmingManager'
import type { InstanceMetadata } from '../../../debug/GameFinder'

// Class-scoped logger will be attached to the class

// Re-export for backward compatibility
export { LOD_LEVEL, LOD_TIER_NAME, type LodLevel }

/** Steam library capsule dimensions */
export const STEAM_CAPSULE_WIDTH = 300
export const STEAM_CAPSULE_HEIGHT = 450

export const DEFAULT_BOX_WIDTH = 0.2
export const DEFAULT_BOX_HEIGHT = 0.3

/** LOD configuration - matches old interface */
export interface LodConfig {
    level: LodLevel
    textureSize?: number
    textureWidth?: number
    textureHeight?: number
    name: string
    maxDepth?: number
}

export const DEFAULT_LOD_CONFIGS: LodConfig[] = [
    { level: LOD_LEVEL.HIGH, textureWidth: STEAM_CAPSULE_WIDTH, textureHeight: STEAM_CAPSULE_HEIGHT, name: LOD_TIER_NAME.HIGH, maxDepth: 128 },
    { level: LOD_LEVEL.MID, textureWidth: 150, textureHeight: 225, name: LOD_TIER_NAME.MID }
]

/** Config matching old LodArtworkConfig */
export interface LodArtworkConfig {
    maxTextures?: number
    lodConfigs?: LodConfig[]
    boxWidth?: number
    boxHeight?: number
    boxDepth?: number
    defaultLod?: LodLevel
    lazyHighTextures?: boolean
    maxHighTextureCache?: number
    prewarmingConfig?: Partial<PrewarmingConfig>
}

/**
 * Orchestrates the complete artwork loading and rendering pipeline.
 * Implements ILodArtworkRenderer for use by LodDistanceManager.
 */
export class LodArtworkOrchestrator {
    public static logger = Logger.createLogFunctions(LodArtworkOrchestrator.name)
    private artworkProvider: GameArtworkProvider
    private textureManager: LodTextureArrayManager
    private renderer: LodGameArtworkRenderer

    private readonly maxTextures: number
    private readonly lodConfigs: LodConfig[]
    private readonly lazyHighTextures: boolean

    // Track game names to texture indices
    private gameNameToTextureIndex: Map<string, number> = new Map()
    private textureIndexToGameName: Map<number, string> = new Map()
    private instanceMetadata: Map<number, InstanceMetadata> = new Map()

    // Track failed artwork (for backward compat)
    private failedArtwork: Map<string, { reason: string; url: string; urlsTried: string[]; timestamp: number }> = new Map()

    // Prevent log spam when atlas is full
    private atlasFullLogged: boolean = false

    constructor(config: LodArtworkConfig = {}) {
        this.maxTextures = config.maxTextures ?? 512
        this.lodConfigs = config.lodConfigs ?? DEFAULT_LOD_CONFIGS
        this.lazyHighTextures = config.lazyHighTextures ?? false

        // Get singleton provider
        this.artworkProvider = GameArtworkProvider.getInstance()

        // Create texture array manager
        const tierConfigs: LodTierConfig[] = this.lodConfigs.map(lc => ({
            name: lc.name,
            width: lc.textureWidth ?? lc.textureSize ?? 128,
            height: lc.textureHeight ?? lc.textureSize ?? 128,
            maxDepth: lc.maxDepth ?? this.maxTextures
        }))
        this.textureManager = new LodTextureArrayManager({ tiers: tierConfigs })

        // Create renderer
        const highConfig = this.lodConfigs.find(c => c.level === LOD_LEVEL.HIGH)
        const rendererConfig: LodGameArtworkRendererConfig = {
            maxInstances: this.maxTextures,
            boxWidth: config.boxWidth ?? DEFAULT_BOX_WIDTH,
            boxHeight: config.boxHeight ?? DEFAULT_BOX_HEIGHT,
            boxDepth: config.boxDepth ?? 0.1,
            defaultLod: config.defaultLod,
            lazyHighTextures: this.lazyHighTextures,
            gpuUpdateInterval: 10
        }

        if (this.lazyHighTextures) {
            rendererConfig.highTextureCacheConfig = {
                totalSlots: highConfig?.maxDepth ?? 64,
                textureWidth: highConfig?.textureWidth ?? STEAM_CAPSULE_WIDTH,
                textureHeight: highConfig?.textureHeight ?? STEAM_CAPSULE_HEIGHT,
                maxConcurrentLoads: 2
            }
            rendererConfig.prewarmingConfig = config.prewarmingConfig
        }

        this.renderer = this.createRenderer(rendererConfig)

        // Initialize with texture arrays
        const scene = DataManager.getInstance().get<THREE.Scene>(DataKey.MainScene)
        if (scene) {
            this.initialize(scene)
        }

        EventManager.getInstance().registerEventHandler(
            GameEventTypes.SomeBatchesComplete,
            this.handleSomeBatchesComplete.bind(this)
        )
        EventManager.getInstance().registerEventHandler(
            GameEventTypes.AllBatchesComplete,
            this.compactMidTierAfterLoad.bind(this)
        )

        this.logConfig()
    }

    private handleSomeBatchesComplete(_event: CustomEvent<SomeBatchesCompleteEvent>): void {
        this.updateGPU()
    }

    private compactMidTierAfterLoad(): void {
        this.textureManager.compactMidTier()
    }

    /** Factory method - override in debug subclass */
    protected createRenderer(config: LodGameArtworkRendererConfig): LodGameArtworkRenderer {
        return new LodGameArtworkRenderer(config)
    }

    private initialize(scene: THREE.Scene): void {
        const highTexture = this.textureManager.getTextureArray(LOD_TIER_NAME.HIGH)
        const midTexture = this.textureManager.getTextureArray(LOD_TIER_NAME.MID)

        if (!highTexture || !midTexture) {
            throw new Error(`Failed to get texture arrays - expected tiers '${LOD_TIER_NAME.HIGH}' and '${LOD_TIER_NAME.MID}'`)
        }

        const textureArrays: LodTextureArrays = {
            high: highTexture,
            mid: midTexture
        }
        this.renderer.initialize(textureArrays, scene)

        // Register instance metadata map for downstream systems (raycast, diagnostics)
        DataManager.getInstance().set(
            DataKey.InstancedArtworkMetadata,
            this.instanceMetadata,
            { domain: DataDomain.Renderer }
        )
    }

    private logConfig(): void {
        let totalVRAM = 0
        const lodInfo: string[] = []

        for (const tierName of this.textureManager.getTierNames()) {
            const config = this.textureManager.getTierConfig(tierName)
            if (config) {
                const vram = config.width * config.height * config.maxDepth * 4
                totalVRAM += vram
                lodInfo.push(`${tierName}: ${config.maxDepth} slots ├ù ${config.width}├ù${config.height}px = ${(vram / (1024 * 1024)).toFixed(1)}MB`)
            }
        }

        LodArtworkOrchestrator.logger.lifecycle(`LOD VRAM: ${lodInfo.join(', ')} | Total: ${(totalVRAM / (1024 * 1024)).toFixed(0)}MB`)
    }

    /**
     * Main entry point - matches old LodArtworkRenderer API
     */
    public async setArtworkInstanceFromUrl(
        position: THREE.Vector3,
        gameName: string,
        artworkUrl: string,
        appid?: number,
        rotation?: THREE.Quaternion
    ): Promise<{ success: boolean; instanceIndex: number }> {
        // Check if already loaded
        const existingIndex = this.gameNameToTextureIndex.get(gameName)
        if (existingIndex !== undefined) {
            return { success: true, instanceIndex: existingIndex }
        }

        // Only skip known permanent failures. Non-permanent historical failures
        // (UNKNOWN/TIMEOUT/NETWORK) should be retried.
        if (this.artworkProvider.isPermanentFailure(appid ?? 0, 'library')) {
            const reason = this.artworkProvider.getFailureReason(appid ?? 0, 'library')
            LodArtworkOrchestrator.logger.debug(`Skipping "${gameName}": permanent failure (${reason})`)
            return { success: false, instanceIndex: -1 }
        }

        // Allocate texture slot
        const textureIndex = this.textureManager.allocateSlot()
        if (textureIndex < 0) {
            if (!this.atlasFullLogged) {
                LodArtworkOrchestrator.logger.warn(`Atlas full (${this.maxTextures} configured) - further games will not have artwork`)
                this.atlasFullLogged = true
            }
            return { success: false, instanceIndex: -1 }
        }

        try {
            // Get artwork handle
            const artwork = this.artworkProvider.getArtwork(
                appid ?? 0,
                gameName,
                'library',
                artworkUrl
            )

            // Load MID texture (always needed)
            const midConfig = this.lodConfigs.find(c => c.level === LOD_LEVEL.MID)
            const midWidth = midConfig?.textureWidth ?? midConfig?.textureSize ?? 150
            const midHeight = midConfig?.textureHeight ?? midConfig?.textureSize ?? 225

            const midResult = await artwork.getPixelsAtSize(midWidth, midHeight)
            this.textureManager.setSlotPixels(LOD_TIER_NAME.MID, textureIndex, midResult.pixels, midWidth, midHeight)

            // For non-lazy mode, also load HIGH
            if (!this.lazyHighTextures) {
                const highConfig = this.lodConfigs.find(c => c.level === LOD_LEVEL.HIGH)
                const highWidth = highConfig?.textureWidth ?? STEAM_CAPSULE_WIDTH
                const highHeight = highConfig?.textureHeight ?? STEAM_CAPSULE_HEIGHT

                const highResult = await artwork.getPixelsAtSize(highWidth, highHeight)
                this.textureManager.setSlotPixels(LOD_TIER_NAME.HIGH, textureIndex, highResult.pixels, highWidth, highHeight)
            }

            // Flush texture to GPU immediately after pixel data is ready.
            // Without this, MID textures only reach the GPU on the next SomeBatchesComplete
            // event ΓÇö which may have already fired in a single-batch load (e.g. demo store).
            // TODO: tear this back out and probably force a gpu update when we get an event after SomeBatchesComplete
            this.updateGPU()

            // Create instance
            const resolvedUrl = artwork.getUrl()
            const instanceIndex = this.renderer.addInstance({
                position,
                textureIndex,
                gameName,
                artworkUrl: resolvedUrl,
                lodLevel: this.lazyHighTextures ? LOD_LEVEL.MID : LOD_LEVEL.HIGH,
                rotation,
            })

            if (instanceIndex < 0) {
                return { success: false, instanceIndex: -1 }
            }

            // Track mapping
            this.gameNameToTextureIndex.set(gameName, textureIndex)
            this.textureIndexToGameName.set(textureIndex, gameName)
            this.instanceMetadata.set(instanceIndex, {
                name: gameName,
                appid,
                position: position.clone()
            })

            return { success: true, instanceIndex }

        } catch (error) {
            const reason = error instanceof Error ? error.message : String(error)
            this.failedArtwork.set(gameName, {
                reason: this.categorizeFailure(reason),
                url: artworkUrl,
                urlsTried: [artworkUrl],
                timestamp: Date.now()
            })
            LodArtworkOrchestrator.logger.debug(`Artwork failed for "${gameName}": ${reason}`)
            return { success: false, instanceIndex: -1 }
        }
    }

    private categorizeFailure(msg: string): string {
        const lower = msg.toLowerCase()
        if (lower.includes('cors')) return 'CORS'
        if (lower.includes('404') || lower.includes('not found')) return '404'
        if (lower.includes('timeout') || lower.includes('abort')) return 'TIMEOUT'
        if (lower.includes('network') || lower.includes('failed to fetch')) return 'NETWORK'
        return 'UNKNOWN'
    }

    // === Delegated methods to renderer ===

    public setInstanceLod(instanceIndex: number, lodLevel: LodLevel): boolean {
        return this.renderer.setInstanceLod(instanceIndex, lodLevel)
    }

    public setGlobalLod(lodLevel: LodLevel): void {
        this.renderer.setGlobalLod(lodLevel)
    }

    public getInstanceLod(instanceIndex: number): LodLevel | null {
        const data = this.renderer.getInstance(instanceIndex)
        return data?.lodLevel ?? null
    }

    private updateGPU(): void {
        this.textureManager.flushToGpu()
        this.renderer.flushToGpu()
    }

    public isReady(): boolean {
        return this.renderer.isReady()
    }

    public getInstanceCount(): number {
        return this.renderer.getInstanceCount()
    }

    public getInstanceData(): ReadonlyMap<number, { position: THREE.Vector3; lodLevel: LodLevel }> {
        return this.renderer.getAllInstances() as ReadonlyMap<number, { position: THREE.Vector3; lodLevel: LodLevel }>
    }

    public isHighTextureLoaded(instanceIndex: number): boolean {
        return this.renderer.isHighTextureLoaded(instanceIndex)
    }

    public getHighTextureCache(): HighTextureCache | null {
        return this.renderer.getHighTextureCache()
    }

    public startPrewarming(): void {
        this.renderer.startPrewarming()
    }

    public stopPrewarming(): void {
        this.renderer.stopPrewarming()
    }

    public clearFailureCache(): void {
        this.failedArtwork.clear()
        this.artworkProvider.clearCaches()
        LodArtworkOrchestrator.logger.info('Cleared artwork caches - all URLs will be retried on next load')
    }

    // === Protected accessors for debug subclass ===

    protected getTextureManager(): LodTextureArrayManager {
        return this.textureManager
    }

    protected getInternalRenderer(): LodGameArtworkRenderer {
        return this.renderer
    }

    protected getFailedArtwork(): Map<string, { reason: string; url: string; urlsTried: string[]; timestamp: number }> {
        return this.failedArtwork
    }

    public dispose(): void {
        this.renderer.dispose()
        this.textureManager.dispose()
        this.gameNameToTextureIndex.clear()
        this.textureIndexToGameName.clear()
        this.instanceMetadata.clear()
        this.failedArtwork.clear()

        LodArtworkOrchestrator.logger.lifecycle('Disposed')
    }
}

/**
