/* eslint-enable @typescript-eslint/no-explicit-any */

/**
 * LOD Game Artwork Renderer - Clean separation of concerns
 * 
 * This renderer is responsible for:
 * - Holding the InstancedMesh and ShaderMaterial
 * - Updating GPU state each frame
 * - Managing per-instance LOD levels
 * - HIGH texture cache (LRU for memory optimization)
 * - Spatial pre-warming (proactive loading based on player movement)
 * 
 * It does NOT:
 * - Load textures from URLs (handled by GameArtworkProvider)
 * - Know anything about Steam APIs
 * 
 * Texture arrays are passed in via constructor, populated upstream.
 */

import * as THREE from 'three'
import { RenderLoopRegistry } from '../../RenderLoopRegistry'
import { SceneLayer } from '../../SceneLayers'
import { Logger } from '../../../utils/Logger'
import { HighTextureCache, type HighTextureCacheConfig } from './HighTextureCache'
import { SpatialPrewarmingManager, type PrewarmingConfig } from './SpatialPrewarmingManager'
import vertexShader from './shaders/instanced-artwork-lod.vert?raw'
import fragmentShader from './shaders/instanced-artwork-lod.frag?raw'

// Class-scoped logger will be attached to the class

/** Mesh name used by the LOD artwork InstancedMesh ΓÇö used by GameFinder for raycast identity checks. */
export const LOD_ARTWORK_MESH_NAME = 'lod-game-artwork' as const

/** LOD level constants */
export const LOD_LEVEL = {
    HIGH: 0,
    MID: 1
} as const

export type LodLevel = typeof LOD_LEVEL[keyof typeof LOD_LEVEL]

/** Configuration for the renderer */
export interface LodGameArtworkRendererConfig {
    /** Maximum number of instances */
    maxInstances: number
    /** Box dimensions for each instance */
    boxWidth: number
    boxHeight: number
    boxDepth: number
    /** Default LOD level for new instances */
    defaultLod?: LodLevel
    /** How often to flush pending updates to GPU (in frames) */
    gpuUpdateInterval?: number
    /** Enable lazy HIGH texture loading (memory optimization) */
    lazyHighTextures?: boolean
    /** HIGH texture cache config (only used with lazyHighTextures) */
    highTextureCacheConfig?: Partial<HighTextureCacheConfig>
    /** Spatial pre-warming config (only used with lazyHighTextures) */
    prewarmingConfig?: Partial<PrewarmingConfig>
}

/** Texture arrays for each LOD level, passed in from upstream */
export interface LodTextureArrays {
    high: THREE.DataArrayTexture
    mid: THREE.DataArrayTexture
}

/** Per-instance data for external tracking */
export interface InstanceData {
    instanceIndex: number
    textureIndex: number
    gameName: string
    position: THREE.Vector3
    lodLevel: LodLevel
    highTextureSlot: number  // -1 if HIGH not loaded
}

/** Parameters for addInstance() - extracted per PR review. */
export interface AddInstanceParams {
    position: THREE.Vector3
    textureIndex: number
    gameName: string
    artworkUrl?: string
    lodLevel?: LodLevel
    highTextureSlot?: number
    rotation?: THREE.Quaternion
}

/**
 * Clean renderer focused solely on GPU rendering.
 * Texture population is handled externally.
 */
export class LodGameArtworkRenderer {
    public static logger = Logger.createLogFunctions(LodGameArtworkRenderer.name)
    private instancedMesh: THREE.InstancedMesh | null = null
    private geometry: THREE.BoxGeometry | null = null
    private material: THREE.ShaderMaterial | null = null

    // Texture arrays (owned externally, referenced here)
    private textureArrays: LodTextureArrays | null = null

    // Per-instance GPU attributes
    private lodLevels: Float32Array | null = null
    private highTextureSlots: Float32Array | null = null
    private textureIndices: Float32Array | null = null

    // Instance tracking
    private currentInstanceCount: number = 0
    private instanceData: Map<number, InstanceData> = new Map()
    private textureIndexToInstance: Map<number, number> = new Map()

    // GPU update throttling
    private gpuUpdateFrameCounter: number = 0
    private readonly gpuUpdateInterval: number
    private pendingAttributeUpdate: boolean = false

    // HIGH texture lazy loading (memory optimization)
    private readonly lazyHighTextures: boolean
    private highTextureCache: HighTextureCache | null = null
    private spatialPrewarming: SpatialPrewarmingManager | null = null
    private pendingHighPromotion: Map<number, number> = new Map()  // textureIndex ΓåÆ highSlot

    // Render loop registration
    private isRegisteredForRenderLoop: boolean = false

    private readonly config: Required<Omit<LodGameArtworkRendererConfig, 'highTextureCacheConfig' | 'prewarmingConfig'>> & 
                             Pick<LodGameArtworkRendererConfig, 'highTextureCacheConfig' | 'prewarmingConfig'>

    private static readonly DEFAULT_ROTATION = new THREE.Quaternion()

    constructor(config: LodGameArtworkRendererConfig) {
        this.lazyHighTextures = config.lazyHighTextures ?? false
        this.config = {
            maxInstances: config.maxInstances,
            boxWidth: config.boxWidth,
            boxHeight: config.boxHeight,
            boxDepth: config.boxDepth,
            // With lazy loading, default to MID since HIGH may not be loaded yet
            defaultLod: this.lazyHighTextures ? LOD_LEVEL.MID : (config.defaultLod ?? LOD_LEVEL.HIGH),
            gpuUpdateInterval: config.gpuUpdateInterval ?? 10,
            lazyHighTextures: this.lazyHighTextures,
            highTextureCacheConfig: config.highTextureCacheConfig,
            prewarmingConfig: config.prewarmingConfig
        }
        this.gpuUpdateInterval = this.config.gpuUpdateInterval

        LodGameArtworkRenderer.logger.lifecycle(`Created with maxInstances=${this.config.maxInstances}, defaultLod=${this.config.defaultLod}, lazyHigh=${this.lazyHighTextures}`)
    }

    /**
     * Initialize the renderer with texture arrays.
     * Must be called before adding instances.
     */
    public initialize(textureArrays: LodTextureArrays, scene: THREE.Scene): void {
        if (this.instancedMesh) {
            LodGameArtworkRenderer.logger.warn('Already initialized')
            return
        }

        this.textureArrays = textureArrays

        // Initialize HIGH texture cache if lazy loading enabled
        if (this.lazyHighTextures) {
            const highConfig = this.config.highTextureCacheConfig ?? {}
            this.highTextureCache = new HighTextureCache({
                totalSlots: highConfig.totalSlots ?? 64,
                textureWidth: highConfig.textureWidth ?? 300,
                textureHeight: highConfig.textureHeight ?? 450,
                maxConcurrentLoads: highConfig.maxConcurrentLoads ?? 2,
                ...highConfig
            })
            this.highTextureCache.setSlotChangeCallback(this.onHighSlotChange.bind(this))
            this.highTextureCache.setTextureArray(textureArrays.high)

            // Initialize spatial pre-warming
            this.spatialPrewarming = new SpatialPrewarmingManager(
                this.highTextureCache,
                this.config.prewarmingConfig ?? {}
            )
        }

        // Create material referencing the texture arrays
        this.material = new THREE.ShaderMaterial({
            uniforms: {
                textureArrayHigh: { value: textureArrays.high },
                textureArrayMid: { value: textureArrays.mid }
            },
            vertexShader,
            fragmentShader,
            transparent: true,
            side: THREE.FrontSide
        })

        // Create geometry
        this.geometry = new THREE.BoxGeometry(
            this.config.boxWidth,
            this.config.boxHeight,
            this.config.boxDepth
        )

        // Create instanced mesh
        this.instancedMesh = new THREE.InstancedMesh(
            this.geometry,
            this.material,
            this.config.maxInstances
        )
        this.instancedMesh.name = LOD_ARTWORK_MESH_NAME
        this.instancedMesh.layers.enable(SceneLayer.Interactable)
        this.instancedMesh.count = 0
        this.instancedMesh.castShadow = true
        this.instancedMesh.receiveShadow = true
        this.instancedMesh.frustumCulled = false

        // Setup per-instance attributes
        this.textureIndices = new Float32Array(this.config.maxInstances)
        this.lodLevels = new Float32Array(this.config.maxInstances)
        this.highTextureSlots = new Float32Array(this.config.maxInstances)

        this.textureIndices.fill(0)
        this.lodLevels.fill(this.config.defaultLod)
        this.highTextureSlots.fill(-1)

        const textureIndexAttr = new THREE.InstancedBufferAttribute(this.textureIndices, 1)
        const lodLevelAttr = new THREE.InstancedBufferAttribute(this.lodLevels, 1)
        const highTextureSlotAttr = new THREE.InstancedBufferAttribute(this.highTextureSlots, 1)

        textureIndexAttr.setUsage(THREE.DynamicDrawUsage)
        lodLevelAttr.setUsage(THREE.DynamicDrawUsage)
        highTextureSlotAttr.setUsage(THREE.DynamicDrawUsage)

        this.geometry.setAttribute('textureIndex', textureIndexAttr)
        this.geometry.setAttribute('lodLevel', lodLevelAttr)
        this.geometry.setAttribute('highTextureSlot', highTextureSlotAttr)

        // Add to scene
        scene.add(this.instancedMesh)

        // Register for render loop
        if (!this.isRegisteredForRenderLoop) {
            RenderLoopRegistry.getInstance().register(
                'LodGameArtworkRenderer',
                this.onFrame.bind(this)
            )
            this.isRegisteredForRenderLoop = true
        }

        LodGameArtworkRenderer.logger.lifecycle('Initialized and added to scene')
    }

    /**
     * Called every frame by the render loop.
     * Handles periodic GPU updates.
     */
    private onFrame(_now: number, _deltaTime: number): void {
        this.gpuUpdateFrameCounter++

        if (this.gpuUpdateFrameCounter >= this.gpuUpdateInterval) {
            this.gpuUpdateFrameCounter = 0

            // Flush HIGH texture cache to GPU if dirty
            const didFlush = this.highTextureCache?.flushToGpu() ?? false

            // After GPU flush, promote pending games to HIGH LOD
            if (didFlush || this.pendingHighPromotion.size > 0) {
                this.promotePendingHighTextures()
            }

            this.flushToGpu()
        }
    }

    private promotePendingHighTextures(): void {
        if (this.pendingHighPromotion.size === 0 || !this.lodLevels) return

        let promotedCount = 0
        for (const [textureIndex, _slot] of this.pendingHighPromotion) {
            const instanceIndex = this.textureIndexToInstance.get(textureIndex)
            if (instanceIndex === undefined) continue

            this.lodLevels[instanceIndex] = LOD_LEVEL.HIGH

            const data = this.instanceData.get(instanceIndex)
            if (data) data.lodLevel = LOD_LEVEL.HIGH

            promotedCount++
        }

        if (promotedCount > 0) {
            this.pendingAttributeUpdate = true
            LodGameArtworkRenderer.logger.runtime(`Promoted ${promotedCount} games to HIGH LOD (after GPU flush)`)
        }

        this.pendingHighPromotion.clear()
    }

    private onHighSlotChange(textureIndex: number, slot: number): void {
        if (!this.highTextureSlots) return

        const instanceIndex = this.textureIndexToInstance.get(textureIndex)
        if (instanceIndex === undefined) {
            LodGameArtworkRenderer.logger.runtime(`HIGH slot change for unknown textureIndex ${textureIndex}`)
            return
        }

        // Update slot attribute
        this.highTextureSlots[instanceIndex] = slot

        const data = this.instanceData.get(instanceIndex)
        if (data) data.highTextureSlot = slot

        if (slot >= 0) {
            // Queue for HIGH promotion AFTER GPU flush (prevents texture flash)
            this.pendingHighPromotion.set(textureIndex, slot)
        } else {
            // Eviction: immediately downgrade to MID
            this.pendingHighPromotion.delete(textureIndex)
            if (this.lodLevels) {
                this.lodLevels[instanceIndex] = LOD_LEVEL.MID
            }
            if (data) data.lodLevel = LOD_LEVEL.MID
        }

        this.pendingAttributeUpdate = true
    }

    /**
     * Flush any pending updates to the GPU.
     * Called periodically from onFrame and can be called manually.
     */
    public flushToGpu(): void {
        if (!this.instancedMesh || !this.geometry) return
        if (!this.pendingAttributeUpdate) return

        this.instancedMesh.instanceMatrix.needsUpdate = true
        this.instancedMesh.count = this.currentInstanceCount
        this.instancedMesh.boundingSphere = null  // Force recompute; stale sphere breaks raycasting

        const textureIndexAttr = this.geometry.getAttribute('textureIndex')
        const lodLevelAttr = this.geometry.getAttribute('lodLevel')
        const highSlotAttr = this.geometry.getAttribute('highTextureSlot')

        if (textureIndexAttr) textureIndexAttr.needsUpdate = true
        if (lodLevelAttr) lodLevelAttr.needsUpdate = true
        if (highSlotAttr) highSlotAttr.needsUpdate = true

        this.pendingAttributeUpdate = false
    }

    /**
     * Add a new instance at the given position.
     * Returns the instance index, or -1 if at capacity.
     */
    public addInstance({
        position,
        textureIndex,
        gameName,
        artworkUrl,
        lodLevel = this.config.defaultLod,
        highTextureSlot = -1,
        rotation,
    }: AddInstanceParams): number {
        if (!this.instancedMesh || !this.geometry) {
            LodGameArtworkRenderer.logger.warn('Cannot add instance: renderer not initialized')
            return -1
        }

        if (this.currentInstanceCount >= this.config.maxInstances) {
            LodGameArtworkRenderer.logger.warn(`Cannot add instance: at capacity (${this.config.maxInstances})`)
            return -1
        }

        const instanceIndex = this.currentInstanceCount++

        // Set transform
        const matrix = new THREE.Matrix4()
        matrix.compose(position, rotation ?? LodGameArtworkRenderer.DEFAULT_ROTATION, new THREE.Vector3(1, 1, 1))
        this.instancedMesh.setMatrixAt(instanceIndex, matrix)

        // Set attributes
        this.textureIndices![instanceIndex] = textureIndex
        this.lodLevels![instanceIndex] = lodLevel
        this.highTextureSlots![instanceIndex] = highTextureSlot

        // Track instance data
        this.instanceData.set(instanceIndex, {
            instanceIndex,
            textureIndex,
            gameName,
            position: position.clone(),
            lodLevel,
            highTextureSlot
        })
        this.textureIndexToInstance.set(textureIndex, instanceIndex)

        // Register with HIGH texture cache if lazy loading
        if (this.lazyHighTextures && this.highTextureCache && artworkUrl) {
            this.highTextureCache.registerGame(textureIndex, gameName, artworkUrl)
        }

        // Register position for spatial prewarming
        this.spatialPrewarming?.registerGamePosition(textureIndex, gameName, position)

        this.pendingAttributeUpdate = true
        return instanceIndex
    }

    /**
     * Update the LOD level for a specific instance.
     */
    public setInstanceLod(instanceIndex: number, lodLevel: LodLevel): boolean {
        if (!this.geometry || !this.lodLevels) return false
        if (instanceIndex < 0 || instanceIndex >= this.currentInstanceCount) return false

        let effectiveLod = lodLevel

        // If lazy HIGH textures enabled and requesting HIGH, check availability
        if (this.lazyHighTextures && lodLevel === LOD_LEVEL.HIGH && this.highTextureCache) {
            const textureIndex = this.textureIndices![instanceIndex]

            // Check if texture is pending GPU flush
            if (this.pendingHighPromotion.has(textureIndex)) {
                effectiveLod = LOD_LEVEL.MID
            } else {
                const highSlot = this.highTextureCache.requestHighTexture(textureIndex)
                if (highSlot < 0) {
                    // HIGH not ready - stay at MID, will be promoted via onHighSlotChange
                    effectiveLod = LOD_LEVEL.MID
                }
            }
        }

        this.lodLevels[instanceIndex] = effectiveLod

        const data = this.instanceData.get(instanceIndex)
        if (data) data.lodLevel = effectiveLod

        this.pendingAttributeUpdate = true
        return effectiveLod === lodLevel
    }

    /**
     * Update the HIGH texture slot for a specific instance.
     */
    public setInstanceHighSlot(instanceIndex: number, slot: number): boolean {
        if (!this.geometry || !this.highTextureSlots) return false
        if (instanceIndex < 0 || instanceIndex >= this.currentInstanceCount) return false

        this.highTextureSlots[instanceIndex] = slot

        const data = this.instanceData.get(instanceIndex)
        if (data) data.highTextureSlot = slot

        this.pendingAttributeUpdate = true
        return true
    }

    /**
     * Set LOD level for all instances.
     */
    public setGlobalLod(lodLevel: LodLevel): void {
        if (!this.lodLevels) return

        for (let i = 0; i < this.currentInstanceCount; i++) {
            this.lodLevels[i] = lodLevel
            const data = this.instanceData.get(i)
            if (data) data.lodLevel = lodLevel
        }

        this.pendingAttributeUpdate = true
        LodGameArtworkRenderer.logger.debug(`Set global LOD to ${lodLevel} for ${this.currentInstanceCount} instances`)
    }

    /**
     * Get instance data for a specific instance.
     */
    public getInstance(instanceIndex: number): InstanceData | undefined {
        return this.instanceData.get(instanceIndex)
    }

    /**
     * Get all instance data (readonly).
     */
    public getAllInstances(): ReadonlyMap<number, InstanceData> {
        return this.instanceData
    }

    public getInstanceCount(): number {
        return this.currentInstanceCount
    }

    public getMaxInstances(): number {
        return this.config.maxInstances
    }

    public isReady(): boolean {
        return this.instancedMesh !== null
    }

    public getMesh(): THREE.InstancedMesh | null {
        return this.instancedMesh
    }

    public getHighTextureCache(): HighTextureCache | null {
        return this.highTextureCache
    }

    public startPrewarming(): void {
        this.spatialPrewarming?.start()
    }

    public stopPrewarming(): void {
        this.spatialPrewarming?.stop()
    }

    public isHighTextureLoaded(instanceIndex: number): boolean {
        if (!this.lazyHighTextures || !this.highTextureCache) {
            return true  // Not using lazy loading
        }
        const textureIndex = this.textureIndices?.[instanceIndex]
        if (textureIndex === undefined) return false
        return this.highTextureCache.isLoaded(textureIndex)
    }

    public dispose(): void {
        if (this.isRegisteredForRenderLoop) {
            RenderLoopRegistry.getInstance().unregister('LodGameArtworkRenderer')
            this.isRegisteredForRenderLoop = false
        }

        this.instancedMesh?.removeFromParent()
        this.geometry?.dispose()
        this.material?.dispose()

        // Dispose HIGH texture management
        this.spatialPrewarming?.dispose()
        this.highTextureCache?.dispose()

        // Note: We don't dispose texture arrays - they're owned externally

        this.instanceData.clear()
        this.textureIndexToInstance.clear()
        this.pendingHighPromotion.clear()
        this.textureIndices = null
        this.lodLevels = null
        this.highTextureSlots = null

        LodGameArtworkRenderer.logger.lifecycle('Disposed')
    }
}

/**
 * LOD Texture Array Manager
 * 
 * Manages the creation and population of texture arrays for LOD rendering.
 * This class owns the texture arrays and handles:
 * - Creating DataArrayTextures at appropriate resolutions
 * - Copying pixel data into texture array slots
 * - Tracking pending GPU updates per-layer
 * - Flushing changed layers to GPU efficiently
 * 
 * Decoupled from:
 * - URL fetching (handled by upstream texture loading)
 * - Rendering (handled by LodGameArtworkRenderer)
 */

import * as THREE from 'three'
import { Logger } from '../../../utils/Logger'
import { DataManager } from '../../../core/data/DataManager'
import { LOD_TIER_NAME } from './ILodArtworkRenderer'

// Class-scoped logger will be added inside the class

/** Configuration for a single LOD tier */
export interface LodTierConfig {
    name: string
    width: number
    height: number
    maxDepth: number  // How many texture slots in this array
}

/** Configuration for the texture array manager */
export interface LodTextureArrayManagerConfig {
    tiers: LodTierConfig[]
}

/** State for a single LOD texture array */
interface TextureArrayState {
    config: LodTierConfig
    dataArrayTexture: THREE.DataArrayTexture
    pendingUpdates: Set<number>  // Layer indices that need GPU update
}

/**
 * Manages LOD texture arrays - creation, population, and GPU updates.
 */
export class LodTextureArrayManager {
    public static logger = Logger.createLogFunctions(LodTextureArrayManager.name)
    private tiers: Map<string, TextureArrayState> = new Map()
    private nextSlotIndex: number = 0
    private atlasFullLogged: boolean = false

    constructor(config: LodTextureArrayManagerConfig) {
        this.initializeTextureArrays(config.tiers)
    }

    private initializeTextureArrays(tierConfigs: LodTierConfig[]): void {
        let totalVRAM = 0
        const tierInfo: string[] = []
        const dataManager = DataManager.getInstance()

        for (const tierConfig of tierConfigs) {
            const { name, width, height, maxDepth } = tierConfig

            // Create backing data
            const data = new Uint8Array(width * height * maxDepth * 4)

            // Create DataArrayTexture
            const texture = new THREE.DataArrayTexture(data, width, height, maxDepth)
            texture.format = THREE.RGBAFormat
            texture.type = THREE.UnsignedByteType
            texture.minFilter = THREE.LinearFilter
            texture.magFilter = THREE.LinearFilter
            texture.wrapS = THREE.ClampToEdgeWrapping
            texture.wrapT = THREE.ClampToEdgeWrapping
            texture.needsUpdate = true

            this.tiers.set(name, {
                config: tierConfig,
                dataArrayTexture: texture,
                pendingUpdates: new Set()
            })

            // Track VRAM
            const vram = width * height * maxDepth * 4
            totalVRAM += vram
            tierInfo.push(`${name}: ${maxDepth} slots ├ù ${width}├ù${height}px = ${(vram / (1024 * 1024)).toFixed(1)}MB`)

            // Register memory consumption
            const vramMB = Math.round(vram / (1024 * 1024))
            dataManager.addMemoryConsumption(`LOD/${name}`, vramMB)

            LodTextureArrayManager.logger.debug(`Created texture array: ${name} (${width}├ù${height}├ù${maxDepth})`)
        }

        LodTextureArrayManager.logger.lifecycle(`LOD VRAM: ${tierInfo.join(', ')} | Total: ${(totalVRAM / (1024 * 1024)).toFixed(0)}MB`)
    }

    /**
     * Allocate the next available slot index.
     * Returns -1 if the MID tier is full.
     * 
     * Note: We use the MID tier's depth as the limit because:
     * - MID is the "base" tier that holds all game textures
     * - HIGH tier is a separate LRU cache managed by HighTextureCache
     * - The slot index maps games to their MID texture, HIGH is loaded on-demand
     */
    public allocateSlot(): number {
        // Use MID tier depth as the limit (it's the base tier for all games)
        const midTier = this.tiers.get(LOD_TIER_NAME.MID)
        if (!midTier) {
            LodTextureArrayManager.logger.error('MID tier not found - texture manager misconfigured')
            return -1
        }

        const maxSlots = midTier.config.maxDepth

        if (this.nextSlotIndex >= maxSlots) {
            if (!this.atlasFullLogged) {
                LodTextureArrayManager.logger.warn(`MID texture atlas full (${maxSlots} slots) - no more games can be added`)
                this.atlasFullLogged = true
            }
            return -1
        }

        return this.nextSlotIndex++
    }

    /**
     * Get the current slot count (next index to be allocated).
     */
    public getSlotCount(): number {
        return this.nextSlotIndex
    }

    /**
     * Copy pixel data into a specific tier and slot.
     */
    public setSlotPixels(
        tierName: string,
        slotIndex: number,
        pixelData: Uint8ClampedArray,
        expectedWidth?: number,
        expectedHeight?: number
    ): boolean {        
        const tier = this.tiers.get(tierName)
        if (!tier) {
            LodTextureArrayManager.logger.error(`Unknown tier: ${tierName}`)
            return false
        }

        const { width, height, maxDepth } = tier.config

        if (slotIndex < 0 || slotIndex >= maxDepth) {
            LodTextureArrayManager.logger.error(`Slot index ${slotIndex} out of range for tier ${tierName} (max: ${maxDepth})`)
            return false
        }

        const expectedSize = width * height * 4
        if (pixelData.length !== expectedSize) {
            LodTextureArrayManager.logger.error(`Pixel data size mismatch for ${tierName}[${slotIndex}]: expected ${expectedSize}, got ${pixelData.length}`)
            return false
        }

        // Validate dimensions if provided
        if (expectedWidth !== undefined && expectedHeight !== undefined) {
            if (expectedWidth !== width || expectedHeight !== height) {
                LodTextureArrayManager.logger.warn(`Dimension mismatch for ${tierName}[${slotIndex}]: expected ${width}├ù${height}, got ${expectedWidth}├ù${expectedHeight}`)
            }
        }

        // Copy to texture array backing data
        const offset = slotIndex * expectedSize
        const arrayData = tier.dataArrayTexture.image.data as Uint8Array
        arrayData.set(pixelData, offset)

        // Mark layer as pending GPU update
        tier.pendingUpdates.add(slotIndex)

        return true
    }

    /**
     * Flush all pending layer updates to GPU.
     * Uses partial layer updates for efficiency.
     */
    public flushToGpu(): boolean {
        let anyUpdates = false

        for (const [tierName, tier] of this.tiers.entries()) {
            if (tier.pendingUpdates.size > 0) {
                LodTextureArrayManager.logger.debug(`≡ƒöä GPU FLUSH ${tierName}: ${tier.pendingUpdates.size} layers`)

                tier.dataArrayTexture.needsUpdate = true

                // Use partial layer updates (massive GPU bandwidth savings)
                for (const slotIndex of tier.pendingUpdates) {
                    tier.dataArrayTexture.addLayerUpdate(slotIndex)
                }

                LodTextureArrayManager.logger.debug(`≡ƒöä ${tierName} flushed, needsUpdate=${tier.dataArrayTexture.needsUpdate}, version=${tier.dataArrayTexture.version}`)

                tier.pendingUpdates.clear()
                anyUpdates = true
            }
        }

        return anyUpdates
    }

    /**
     * Get the texture array for a specific tier.
     * Used when initializing the renderer.
     */
    public getTextureArray(tierName: string): THREE.DataArrayTexture | null {
        return this.tiers.get(tierName)?.dataArrayTexture ?? null
    }

    /**
     * Get tier configuration.
     */
    public getTierConfig(tierName: string): LodTierConfig | null {
        return this.tiers.get(tierName)?.config ?? null
    }

    /**
     * Get all tier names.
     */
    public getTierNames(): string[] {
        return Array.from(this.tiers.keys())
    }

    /**
     * Compact the MID tier to the actual number of allocated slots.
     * After all games are loaded, the MID array was pre-allocated to an estimate
     * (totalBatches * 18 + 100). This trims it to the exact slot count used.
     *
     * Mutates the existing DataArrayTexture in-place so any renderer uniform
     * already holding a reference to it will see the new data automatically
     * on the next Three.js render upload ΓÇö no reference threading required.
     */
    public compactMidTier(): void {
        const tier = this.tiers.get(LOD_TIER_NAME.MID)
        if (!tier) return

        const actualDepth = this.nextSlotIndex
        if (actualDepth >= tier.config.maxDepth) return  // Already exact ΓÇö nothing to do

        const { width, height } = tier.config
        const bytesPerSlice = width * height * 4

        const oldData = tier.dataArrayTexture.image.data as Uint8Array
        const newData = new Uint8Array(bytesPerSlice * actualDepth)
        newData.set(oldData.subarray(0, bytesPerSlice * actualDepth))

        const oldMB = Math.round((width * height * tier.config.maxDepth * 4) / (1024 * 1024))
        const newMB = Math.round((bytesPerSlice * actualDepth) / (1024 * 1024))
        const oldMaxDepth = tier.config.maxDepth

        // Mutate in-place ΓÇö Three.js re-uploads via texImage3D on next needsUpdate cycle.
        // Any material uniform already referencing this texture stays valid.
        const image = tier.dataArrayTexture.image as { data: Uint8Array; width: number; height: number; depth: number }
        image.data = newData
        image.depth = actualDepth
        tier.dataArrayTexture.needsUpdate = true

        tier.config = { ...tier.config, maxDepth: actualDepth }
        tier.pendingUpdates.clear()

        const dataManager = DataManager.getInstance()
        dataManager.removeMemoryConsumption(`LOD/${LOD_TIER_NAME.MID}`)
        dataManager.addMemoryConsumption(`LOD/${LOD_TIER_NAME.MID}`, newMB)

        LodTextureArrayManager.logger.info(
            `MID compacted: ${width}├ù${height}├ù${oldMaxDepth} ΓåÆ ${width}├ù${height}├ù${actualDepth} (~${oldMB - newMB} MB freed est.)`
        )
    }

    /**
     * Check if a tier has pending updates.
     */
    public hasPendingUpdates(tierName?: string): boolean {
        if (tierName) {
            return (this.tiers.get(tierName)?.pendingUpdates.size ?? 0) > 0
        }
        return Array.from(this.tiers.values()).some(t => t.pendingUpdates.size > 0)
    }

    public dispose(): void {
        const dataManager = DataManager.getInstance()

        for (const [name, tier] of this.tiers) {
            tier.dataArrayTexture.dispose()
            tier.pendingUpdates.clear()
            dataManager.removeMemoryConsumption(`LOD/${name}`)
        }

        this.tiers.clear()
        LodTextureArrayManager.logger.lifecycle('Disposed')
    }
}

/**
 * PixelDataCache
 *
 * Web Worker-based IndexedDB cache for decoded texture pixel data.
 * Extends ManagedWorker for standardised lifecycle and error handling.
 *
 * Two-phase lifecycle:
 *   1. Construction: worker is started (by ManagedWorker base)
 *   2. init(): sends INIT message, waits for IndexedDB connection confirmation
 *
 * Performance: All IndexedDB operations run off the main thread to prevent
 * frame drops during texture loading.
 *
 * Storage trade-off (kept as design note):
 * - JPEG blob: ~30-50KB per image
 * - Decoded RGBA pixels (300x450): ~540KB per image (~10-18x larger)
 * - For 800 games: ~432MB IndexedDB storage
 */

import { Logger } from '../../../utils/Logger'
import { ManagedWorker } from '../../../utils/ManagedWorker'
import type {
    WorkerInMessage,
    WorkerOutMessage,
    GetResult,
    PutResult,
    InitResult,
    ClearResult,
    StatsResult
} from './pixel-cache.worker'
import PixelCacheWorker from './pixel-cache.worker?worker'

export interface PixelDataCacheConfig {
    dbName?: string
    storeName?: string
    version?: number
}

export interface PixelCacheStats {
    hits: number
    misses: number
    stores: number
    errors: number
    workerReady: boolean
}

export interface CachedPixelResult {
    pixelData: Uint8ClampedArray
    width: number
    height: number
}

/** Current cache version - bump when pixel format or dimensions change */
const CACHE_VERSION = 1

export class PixelDataCache extends ManagedWorker<WorkerInMessage, WorkerOutMessage> {
    private static instance: PixelDataCache | null = null
    public static logger = Logger.createLogFunctions(PixelDataCache.name)

    private readonly dbName: string
    private readonly storeName: string
    private readonly version: number
    private initPromise: Promise<void> | null = null
    private workerReady = false

    private stats: PixelCacheStats = {
        hits: 0,
        misses: 0,
        stores: 0,
        errors: 0,
        workerReady: false
    }

    private constructor(config: PixelDataCacheConfig = {}) {
        super(PixelCacheWorker as unknown as new () => Worker, 'PixelDataCache')
        this.dbName = config.dbName ?? 'SteamTexturePixels'
        this.storeName = config.storeName ?? 'pixels'
        this.version = config.version ?? CACHE_VERSION
    }

    public static getInstance(): PixelDataCache {
        if (!PixelDataCache.instance) {
            PixelDataCache.instance = new PixelDataCache()
        }
        return PixelDataCache.instance
    }

    protected override onWorkerCrash(_err: Error): void {
        // Generic crash logging/rejection is handled by ManagedWorker.
        // PixelDataCache-specific state reset lives here.
        this.stats.errors++
        this.workerReady = false
        this.initPromise = null
    }

    /**
     * Initialize the worker's IndexedDB connection.
     * Safe to call multiple times; only initializes once.
     *
     * Two-phase lifecycle (construct -> init):
     * The worker starts on construction (ManagedWorker base), but requires
     * an explicit INIT message to open the IndexedDB connection before
     * it can serve GET/PUT requests.
     */
    public async init(): Promise<void> {
        if (this.workerReady) return
        if (this.initPromise) return this.initPromise

        this.initPromise = (async () => {
            const result = await this.send<InitResult>({
                type: 'INIT',
                dbName: this.dbName,
                storeName: this.storeName,
                version: this.version,
                messageId: this.nextId()
            })
            if (!result.success) {
                throw new Error(result.error ?? 'Worker init failed')
            }
            this.workerReady = true
            this.stats.workerReady = true
            PixelDataCache.logger.lifecycle(`Worker initialized: ${this.dbName}/${this.storeName}`)
        })()

        return this.initPromise
    }

    private async ensureReady(): Promise<void> {
        if (!this.workerReady) await this.init()
    }

    /**
     * Get cached pixel data for a URL (runs off main thread)
     */
    public async get(url: string): Promise<CachedPixelResult | null> {
        await this.ensureReady()
        try {
            const result = await this.send<GetResult>({
                type: 'GET',
                url,
                version: this.version,
                messageId: this.nextId()
            })
            if (result.found && result.pixels) {
                this.stats.hits++
                return { pixelData: result.pixels, width: result.width!, height: result.height! }
            }
            this.stats.misses++
            return null
        } catch {
            this.stats.errors++
            return null
        }
    }

    /**
     * Store pixel data for a URL (runs off main thread, zero-copy transfer)
     */
    public async put(
        url: string,
        pixels: Uint8ClampedArray,
        width: number,
        height: number
    ): Promise<boolean> {
        await this.ensureReady()
        return this.send<PutResult>({
            type: 'PUT',
            url,
            pixels,
            width,
            height,
            version: this.version,
            messageId: this.nextId()
        }).then((result) => {
            if (result.success) this.stats.stores++
            return result.success
        }).catch(() => {
            this.stats.errors++
            return false
        })
    }

    /**
     * Clear all cached data
     */
    public async clear(): Promise<boolean> {
        await this.ensureReady()
        try {
            const result = await this.send<ClearResult>({
                type: 'CLEAR',
                messageId: this.nextId()
            })
            return result.success
        } catch {
            return false
        }
    }

    public getStats(): PixelCacheStats & { hitRate: string } {
        const total = this.stats.hits + this.stats.misses
        const hitRate = total > 0 ? `${((this.stats.hits / total) * 100).toFixed(1)}%` : 'N/A'
        return { ...this.stats, hitRate }
    }

    public async getStorageEstimate(): Promise<{ count: number; estimatedMB: number }> {
        if (!this.workerReady) return { count: 0, estimatedMB: 0 }
        try {
            const result = await this.send<StatsResult>({
                type: 'GET_STATS',
                messageId: this.nextId()
            })
            return { count: result.count, estimatedMB: result.estimatedMB }
        } catch {
            return { count: 0, estimatedMB: 0 }
        }
    }

    public async diagnose(): Promise<void> {
        const stats = this.getStats()
        const storage = await this.getStorageEstimate()
        console.group('PixelDataCache Stats (Worker-based)')
        console.log(`Worker ready: ${stats.workerReady}`)
        console.log(`Hits: ${stats.hits}, Misses: ${stats.misses}, Hit Rate: ${stats.hitRate}`)
        console.log(`Stores: ${stats.stores}, Errors: ${stats.errors}`)
        console.log(`Cached entries: ${storage.count}, Estimated size: ${storage.estimatedMB.toFixed(1)}MB`)
        console.groupEnd()
    }

    public override dispose(): void {
        super.dispose()
        this.workerReady = false
        this.initPromise = null
        PixelDataCache.logger.lifecycle('Disposed')
    }
}

/**
 * Spatial Pre-warming Manager - Proactive HIGH texture loading based on player movement
 * 
 * Option C from the LOD memory optimization analysis:
 * - Detect player movement direction
 * - Pre-load HIGH textures in that direction BEFORE the LOD manager asks
 * - Aggressively evict textures behind the player
 * - Throttle loads to prevent lag spikes (max 2-3 concurrent loads)
 * 
 * Flow:
 * 1. Track camera position/velocity over time
 * 2. Identify games in the movement direction
 * 3. Queue those games for HIGH texture loading
 * 4. Process queue gradually (throttled)
 * 5. Evict HIGH textures for games behind player
 */

import * as THREE from 'three'
import { RenderLoopRegistry } from '../../RenderLoopRegistry'
import { DataManager } from '../../../core/data/DataManager'
import { DataKey } from '../../../core/data/DataTypes'
import { Logger } from '../../../utils/Logger'
import { HighTextureCache, HighTextureState } from './HighTextureCache'

export interface PrewarmingConfig {
    /** How far ahead to pre-warm (meters) */
    prewarmDistance: number
    /** Max concurrent texture loads */
    maxConcurrentLoads: number
    /** How often to check player direction (frames) */
    directionUpdateFrequency: number
    /** How often to process the load queue (frames) */
    loadQueueProcessFrequency: number
    /** Angle threshold for "in front" (radians) - 90┬░ = PI/2 */
    frontHalfAngle: number
    /** Enable aggressive eviction of behind-player textures */
    aggressiveEviction: boolean
    /** Distance behind player to evict (meters) */
    evictBehindDistance: number
}

const DEFAULT_CONFIG: PrewarmingConfig = {
    prewarmDistance: 6.0,        // Pre-load 6m ahead
    maxConcurrentLoads: 2,       // Max 2 loads at a time
    directionUpdateFrequency: 30, // Check direction every 30 frames
    loadQueueProcessFrequency: 15, // Process queue every 15 frames
    frontHalfAngle: Math.PI / 2,  // 90┬░ cone in front
    aggressiveEviction: true,
    evictBehindDistance: 4.0      // Evict textures 4m+ behind player
}

interface GamePosition {
    textureIndex: number
    gameName: string
    position: THREE.Vector3
}

interface PrewarmStats {
    totalPrewarmed: number
    totalEvicted: number
    queueLength: number
    currentLoads: number
}

export class SpatialPrewarmingManager {
    public static logger = Logger.createLogFunctions(SpatialPrewarmingManager.name)
    private readonly config: PrewarmingConfig
    private readonly highTextureCache: HighTextureCache
    private readonly renderLoopRegistry: RenderLoopRegistry
    private readonly dataManager: DataManager

    // Game position tracking
    private gamePositions: Map<number, GamePosition> = new Map()

    // Movement tracking
    private lastCameraPos = new THREE.Vector3()
    private movementDirection = new THREE.Vector3(0, 0, -1) // Default: forward
    private velocitySamples: THREE.Vector3[] = []

    // Pre-warm queue
    private prewarmQueue: number[] = []
    private currentlyLoading: Set<number> = new Set()

    // Frame counting
    private frameCount = 0

    // Stats
    private stats: PrewarmStats = {
        totalPrewarmed: 0,
        totalEvicted: 0,
        queueLength: 0,
        currentLoads: 0
    }

    // Reusable vectors
    // TODO: Don't use these, they're brittle and problematic
    private readonly tmpVec = new THREE.Vector3()
    private readonly tmpDir = new THREE.Vector3()

    private isRegistered = false

    constructor(highTextureCache: HighTextureCache, config: Partial<PrewarmingConfig> = {}) {
        this.config = { ...DEFAULT_CONFIG, ...config }
        this.highTextureCache = highTextureCache
        this.renderLoopRegistry = RenderLoopRegistry.getInstance()
        this.dataManager = DataManager.getInstance()

        SpatialPrewarmingManager.logger.lifecycle(`Initialized: prewarm ${this.config.prewarmDistance}m ahead, max ${this.config.maxConcurrentLoads} concurrent loads`)
    }

    /**
     * Register a game's position for spatial tracking
     */
    public registerGamePosition(textureIndex: number, gameName: string, position: THREE.Vector3): void {
        this.gamePositions.set(textureIndex, {
            textureIndex,
            gameName,
            position: position.clone()
        })
    }

    /**
     * Start the pre-warming system
     */
    public start(): void {
        if (this.isRegistered) return

        this.renderLoopRegistry.register('SpatialPrewarming', this.onFrame.bind(this))
        this.isRegistered = true

        // Initialize camera position
        const camera = this.dataManager.get<THREE.Camera>(DataKey.MainCamera)
        if (camera) {
            this.lastCameraPos.copy(camera.position)
        }

        SpatialPrewarmingManager.logger.lifecycle(`Started with ${this.gamePositions.size} registered games`)
    }

    /**
     * Stop the pre-warming system
     */
    public stop(): void {
        if (!this.isRegistered) return

        this.renderLoopRegistry.unregister('SpatialPrewarming')
        this.isRegistered = false
        SpatialPrewarmingManager.logger.lifecycle('Stopped')
    }

    /**
     * Render loop callback
     */
    // TODO: replace with renderer registration for update frequency
    private onFrame(_now: number, _deltaTime: number): void {
        const camera = this.dataManager.get<THREE.Camera>(DataKey.MainCamera)
        if (!camera) return

        this.frameCount++

        // Update movement direction periodically
        // TODO: This feels like an unnecessarily expensive way to do this
        if (this.frameCount % this.config.directionUpdateFrequency === 0) {
            this.updateMovementDirection(camera)
        }

        // Process load queue periodically
        if (this.frameCount % this.config.loadQueueProcessFrequency === 0) {
            this.processLoadQueue()
        }
    }

    /**
     * Update the estimated movement direction based on velocity samples
     */
    private updateMovementDirection(camera: THREE.Camera): void {
        const currentPos = camera.position

        // Calculate velocity this frame
        this.tmpVec.copy(currentPos).sub(this.lastCameraPos)

        // Only track significant movement (> 1cm)
        if (this.tmpVec.lengthSq() > 0.0001) {
            // Add velocity sample
            this.velocitySamples.push(this.tmpVec.clone())

            // Keep only last 10 samples
            if (this.velocitySamples.length > 10) {
                this.velocitySamples.shift()
            }

            // Average the samples for smooth direction
            if (this.velocitySamples.length >= 3) {
                this.movementDirection.set(0, 0, 0)
                for (const sample of this.velocitySamples) {
                    this.movementDirection.add(sample)
                }
                this.movementDirection.normalize()

                // Rebuild pre-warm queue based on new direction
                this.rebuildPrewarmQueue(currentPos)
            }
        }

        // Update last position
        this.lastCameraPos.copy(currentPos)

        // Handle eviction if enabled
        if (this.config.aggressiveEviction) {
            this.evictBehindPlayer(currentPos)
        }
    }

    /**
     * Build the pre-warm queue for games in the movement direction
     */
    private rebuildPrewarmQueue(cameraPos: THREE.Vector3): void {
        const candidates: Array<{ textureIndex: number; score: number }> = []

        for (const [textureIndex, game] of this.gamePositions) {
            // Skip if already loaded or loading
            const state = this.highTextureCache.getState(textureIndex)
            if (state === HighTextureState.LOADED || state === HighTextureState.LOADING) {
                continue
            }

            // Direction to game
            this.tmpDir.copy(game.position).sub(cameraPos)
            const distance = this.tmpDir.length()

            // Skip if too far
            if (distance > this.config.prewarmDistance) {
                continue
            }

            // Normalize for dot product
            this.tmpDir.normalize()

            // Dot product with movement direction
            // +1 = same direction, 0 = perpendicular, -1 = opposite
            const dot = this.tmpDir.dot(this.movementDirection)

            // Only consider games "in front" (positive dot product within cone)
            const minDot = Math.cos(this.config.frontHalfAngle)
            if (dot > minDot) {
                // Score: prioritize closer games in the movement direction
                // Higher dot = more aligned, lower distance = closer
                const score = dot * 10 - distance
                candidates.push({ textureIndex, score })
            }
        }

        // Sort by score (highest first)
        candidates.sort((a, b) => b.score - a.score)

        // Update queue
        this.prewarmQueue = candidates.map(c => c.textureIndex)
        this.stats.queueLength = this.prewarmQueue.length

        if (this.prewarmQueue.length > 0) {
            SpatialPrewarmingManager.logger.runtime(`Pre-warm queue: ${this.prewarmQueue.length} games ahead`)
        }
    }

    /**
     * Process the load queue, respecting concurrency limits
     */
    private processLoadQueue(): void {
        // Remove any finished loads from tracking
        for (const textureIndex of this.currentlyLoading) {
            const state = this.highTextureCache.getState(textureIndex)
            if (state !== HighTextureState.LOADING) {
                this.currentlyLoading.delete(textureIndex)
            }
        }

        this.stats.currentLoads = this.currentlyLoading.size

        // Start new loads up to the limit
        while (
            this.currentlyLoading.size < this.config.maxConcurrentLoads &&
            this.prewarmQueue.length > 0
        ) {
            const textureIndex = this.prewarmQueue.shift()!

            // Double-check it's not already loaded
            const state = this.highTextureCache.getState(textureIndex)
            if (state === HighTextureState.LOADED || state === HighTextureState.LOADING) {
                continue
            }

            // Request the HIGH texture
            this.highTextureCache.requestHighTexture(textureIndex)
            this.currentlyLoading.add(textureIndex)
            this.stats.totalPrewarmed++

            const game = this.gamePositions.get(textureIndex)
            SpatialPrewarmingManager.logger.runtime(`Pre-warming "${game?.gameName?.slice(0, 20)}" (${this.currentlyLoading.size}/${this.config.maxConcurrentLoads})`)
        }
    }

    /**
     * Evict HIGH textures for games behind the player
     */
    private evictBehindPlayer(cameraPos: THREE.Vector3): void {
        for (const [textureIndex, game] of this.gamePositions) {
            const state = this.highTextureCache.getState(textureIndex)
            if (state !== HighTextureState.LOADED) continue

            // Direction to game
            this.tmpDir.copy(game.position).sub(cameraPos)
            const distance = this.tmpDir.length()
            this.tmpDir.normalize()

            // Check if behind player (negative dot product)
            const dot = this.tmpDir.dot(this.movementDirection)

            // Evict if behind player AND beyond threshold
            if (dot < -0.3 && distance > this.config.evictBehindDistance) {
                this.highTextureCache.markForEviction(textureIndex)
                this.stats.totalEvicted++
                SpatialPrewarmingManager.logger.runtime(`Marked for eviction: "${game.gameName.slice(0, 20)}" (behind player)`)
            }
        }
    }

    /**
     * Get current stats
     */
    public getStats(): PrewarmStats {
        return { ...this.stats }
    }

    /**
     * Force a direction update and queue rebuild (e.g., after teleport)
     */
    public forceUpdate(): void {
        const camera = this.dataManager.get<THREE.Camera>(DataKey.MainCamera)
        if (camera) {
            this.updateMovementDirection(camera)
            this.processLoadQueue()
        }
    }

    public dispose(): void {
        this.stop()
        this.gamePositions.clear()
        this.prewarmQueue = []
        this.currentlyLoading.clear()
        this.velocitySamples = []
        SpatialPrewarmingManager.logger.lifecycle('Disposed')
    }
}

/**
 * Texture Processor - Handles texture blob processing for instanced renderers
 * 
 * Converts image blobs to texture array data using Web Workers for offscreen
 * processing. Manages texture slot allocation and performance monitoring.
 */

import * as THREE from 'three'
import { TextureWorker } from './TextureWorker'

export interface TextureProcessorConfig {
    textureSize: number
    maxTextures: number
    enablePerformanceLogging?: boolean
}

export interface TextureProcessingResult {
    textureIndex: number
    processingTime: number
    /** Blob returned from worker for optional caching */
    blob?: Blob
}

export interface TextureProcessorStats {
    texturesProcessed: number
    averageProcessingTime: number
    totalProcessingTime: number
    textureSlots: number
    nextTextureIndex: number
}

export class TextureProcessor {
    private readonly textureSize: number
    private readonly maxTextures: number
    private readonly enablePerfLogging: boolean

    private textureSlots: Map<string, number> = new Map()
    private nextTextureIndex: number = 0
    private hasLoggedMaxWarning: boolean = false

    private textureWorker: TextureWorker

    // Performance stats
    private perfStats = {
        textureProcessingTime: 0,
        totalTextures: 0,
        averageProcessingTime: 0
    }

    constructor(config: TextureProcessorConfig) {
        this.textureSize = config.textureSize
        this.maxTextures = config.maxTextures
        this.enablePerfLogging = config.enablePerformanceLogging ?? false

        this.textureWorker = new TextureWorker()
        console.debug('≡ƒöº TextureWorker initialized - texture processing offloaded from main thread')
    }

    private logPerformance(operation: string, duration: number): void {
        if (!this.enablePerfLogging) return

        console.debug(`ΓÜí ${operation}: ${duration.toFixed(2)}ms`)

        this.perfStats.textureProcessingTime += duration
        this.perfStats.totalTextures++
        this.perfStats.averageProcessingTime = this.perfStats.textureProcessingTime / this.perfStats.totalTextures
    }

    /**
     * Check if we can accept another texture, throwing if at capacity
     */
    private ensureCapacity(): void {
        if (this.nextTextureIndex >= this.maxTextures) {
            if (!this.hasLoggedMaxWarning) {
                console.warn(`ΓÜá∩╕Å Maximum artwork textures reached (${this.maxTextures}). Additional games will use labels.`)
                this.hasLoggedMaxWarning = true
            }
            throw new Error('Maximum textures reached')
        }
    }

    /**
     * Reserve a texture slot and return the index
     * Returns existing index if game already has a texture
     */
    private reserveSlot(gameName: string): { index: number; isExisting: boolean } {
        const existingIndex = this.textureSlots.get(gameName)
        if (existingIndex !== undefined) {
            return { index: existingIndex, isExisting: true }
        }
        return { index: this.nextTextureIndex++, isExisting: false }
    }

    /**
     * Copy processed image data to texture array at the reserved slot
     */
    private copyToTextureArray(
        imageData: Uint8ClampedArray | Uint8Array,
        textureIndex: number,
        dataArrayTexture: THREE.DataArrayTexture
    ): void {
        const sliceSize = this.textureSize * this.textureSize * 4
        const offset = textureIndex * sliceSize
        const arrayData = dataArrayTexture.image.data as Uint8Array
        arrayData.set(imageData, offset)
        // NOTE: needsUpdate deferred to batch update for efficiency
    }

    /**
     * Process a texture blob and add it to the texture array
     * Returns the texture index in the array
     */
    public async processTexture(
        blob: Blob,
        gameName: string,
        dataArrayTexture: THREE.DataArrayTexture
    ): Promise<number> {
        this.ensureCapacity()

        const { index: reservedIndex, isExisting } = this.reserveSlot(gameName)
        if (isExisting) {
            return reservedIndex
        }

        // Validate blob
        if (blob.size === 0) {
            console.warn(`ΓÜá∩╕Å Zero-byte blob for "${gameName}" - cached artwork may be corrupted`)
            throw new Error(`Zero-byte blob for "${gameName}"`)
        }

        if (blob.size < 100) {
            console.warn(`ΓÜá∩╕Å Suspiciously small blob for "${gameName}": ${blob.size} bytes`)
        }

        const startTime = performance.now()

        // Process texture in web worker
        const imageData = await this.textureWorker.processTexture(blob, this.textureSize, reservedIndex)

        this.copyToTextureArray(imageData, reservedIndex, dataArrayTexture)
        this.textureSlots.set(gameName, reservedIndex)

        this.logPerformance(`texture processing for "${gameName}"`, performance.now() - startTime)

        return reservedIndex
    }

    /**
     * Fetch image from URL and process entirely in web worker
     * This is the preferred path - keeps network + canvas operations off main thread
     * 
     * @param url - URL to fetch image from
     * @param gameName - Game name for mapping and logging
     * @param dataArrayTexture - Target texture array to write to
     * @param timeout - Network timeout in ms (default 10000)
     * @returns Texture index and optional blob for caching
     */
    public async fetchAndProcessTexture(
        url: string,
        gameName: string,
        dataArrayTexture: THREE.DataArrayTexture,
        timeout: number = 10000
    ): Promise<TextureProcessingResult> {
        this.ensureCapacity()

        const { index: reservedIndex, isExisting } = this.reserveSlot(gameName)
        if (isExisting) {
            return { textureIndex: reservedIndex, processingTime: 0 }
        }

        const startTime = performance.now()

        // Fetch and process texture entirely in web worker
        const result = await this.textureWorker.fetchAndProcess(
            url,
            this.textureSize,
            reservedIndex,
            gameName,
            timeout
        )

        this.copyToTextureArray(result.imageData, reservedIndex, dataArrayTexture)
        this.textureSlots.set(gameName, reservedIndex)

        const totalTime = performance.now() - startTime
        this.logPerformance(`fetch+process for "${gameName}"`, totalTime)

        return { 
            textureIndex: reservedIndex, 
            processingTime: totalTime,
            blob: result.blob
        }
    }

    public getStats(): TextureProcessorStats {
        return {
            texturesProcessed: this.perfStats.totalTextures,
            averageProcessingTime: this.perfStats.averageProcessingTime,
            totalProcessingTime: this.perfStats.textureProcessingTime,
            textureSlots: this.textureSlots.size,
            nextTextureIndex: this.nextTextureIndex
        }
    }

    public hasTexture(gameName: string): boolean {
        return this.textureSlots.has(gameName)
    }

    public getTextureIndex(gameName: string): number | undefined {
        return this.textureSlots.get(gameName)
    }

    public dispose(): void {
        console.debug('≡ƒº╣ Disposing TextureProcessor')

        this.textureWorker.dispose()
        this.textureSlots.clear()
    }
}

/**
 * TextureWorker
 *
 * Main-thread manager for texture-processing.worker.
 * Extends ManagedWorker for standardised lifecycle and error handling.
 */

import type { 
    TextureProcessingMessage,
    TextureFetchMessage,
    TextureProcessingResult, 
    TextureProcessingError 
} from './texture-processing.worker'
import { Logger } from '../../../utils/Logger'
import { ManagedWorker } from '../../../utils/ManagedWorker'
import TextureProcessingWorker from './texture-processing.worker?worker'

export interface FetchAndProcessResult {
    imageData: Uint8ClampedArray
    blob?: Blob
    processingTime: number
    /** Actual width of returned image data */
    width: number
    /** Actual height of returned image data */
    height: number
}

export interface FetchAndProcessOptions {
    /** For square textures (legacy) */
    textureSize?: number
    /** For non-square textures */
    textureWidth?: number
    textureHeight?: number
    /** If true, use native image dimensions (skip resize entirely) */
    useNativeSize?: boolean
    timeout?: number
}

type TWIn = TextureProcessingMessage | TextureFetchMessage
type TWOut = TextureProcessingResult | TextureProcessingError

export class TextureWorker extends ManagedWorker<TWIn, TWOut> {
    public static logger = Logger.createLogFunctions(TextureWorker.name)
    // Side-channel: tracks whether to include blob in resolved result per messageId
    private readonly includeBlobFor = new Set<string>()
    private twCounter = 0

    constructor() {
        super(TextureProcessingWorker as unknown as new () => Worker, 'TextureWorker')
        TextureWorker.logger.lifecycle('Initialized')
    }

    protected override onWorkerCrash(err: Error): void {
        TextureWorker.logger.error('Worker crashed:', err.message)
        this.includeBlobFor.clear()
    }

    private nextMsgId(prefix: string): string {
        return `${prefix}_${this.twCounter++}_${Date.now()}`
    }

    /**
     * Process texture from blob in web worker (legacy mode)
     */
    public async processTexture(blob: Blob, textureSize: number, textureIndex: number): Promise<Uint8ClampedArray> {
        const messageId = this.nextMsgId(`texture_${textureIndex}`)
        const result = await this.send<TextureProcessingResult>({
            type: 'PROCESS_TEXTURE',
            blob,
            textureSize,
            textureIndex,
            messageId
        } as TextureProcessingMessage)
        if (result.type !== 'TEXTURE_PROCESSED') throw new Error((result as unknown as TextureProcessingError).error)
        return result.imageData
    }

    /**
     * Fetch image from URL and process in web worker (legacy square textures)
     */
    public async fetchAndProcess(
        url: string, 
        textureSize: number, 
        textureIndex: number,
        gameName: string,
        timeout: number = 10000
    ): Promise<FetchAndProcessResult> {
        return this.fetchAndProcessWithOptions(url, textureIndex, gameName, { textureSize, timeout })
    }

    /**
     * Fetch image from URL and process in web worker with flexible options.
     */
    public async fetchAndProcessWithOptions(
        url: string,
        textureIndex: number,
        gameName: string,
        options: FetchAndProcessOptions = {}
    ): Promise<FetchAndProcessResult> {
        const messageId = this.nextMsgId(`fetch_${textureIndex}`)
        this.includeBlobFor.add(messageId)
        try {
            const result = await this.send<TextureProcessingResult>({
                type: 'FETCH_AND_PROCESS',
                url,
                textureSize: options.textureSize,
                textureWidth: options.textureWidth,
                textureHeight: options.textureHeight,
                useNativeSize: options.useNativeSize,
                textureIndex,
                messageId,
                gameName,
                timeout: options.timeout ?? 10000
            } as TextureFetchMessage)

            if (result.type !== 'TEXTURE_PROCESSED') {
                throw new Error((result as unknown as TextureProcessingError).error)
            }

            const includeBlob = this.includeBlobFor.has(messageId)
            this.includeBlobFor.delete(messageId)
            return {
                imageData: result.imageData,
                blob: includeBlob ? result.blob : undefined,
                processingTime: result.processingTime,
                width: result.width,
                height: result.height
            }
        } catch (err) {
            this.includeBlobFor.delete(messageId)
            throw err
        }
    }

    public override dispose(): void {
        this.includeBlobFor.clear()
        super.dispose()
    }
}

/// <reference lib="webworker" />
/**
 * Web Worker for IndexedDB pixel cache operations
 * 
 * Offloads IndexedDB read/write from the main thread to eliminate frame drops.
 * IndexedDB operations can take 20-40ms and block rendering when on main thread.
 * 
 * This worker handles:
 * - Opening/initializing the IndexedDB database
 * - Reading cached pixel data (get)
 * - Writing pixel data (put) with batching
 * - Cache management (clear, delete)
 */

const ctx: DedicatedWorkerGlobalScope = self as unknown as DedicatedWorkerGlobalScope

export {}

// === Message Types ===

export interface InitMessage {
    type: 'INIT'
    dbName: string
    storeName: string
    version: number
    messageId: string
}

export interface GetMessage {
    type: 'GET'
    url: string
    version: number
    messageId: string
}

export interface PutMessage {
    type: 'PUT'
    url: string
    pixels: Uint8ClampedArray
    width: number
    height: number
    version: number
    messageId: string
}

export interface ClearMessage {
    type: 'CLEAR'
    messageId: string
}

export interface DeleteMessage {
    type: 'DELETE'
    url: string
    messageId: string
}

export interface GetStatsMessage {
    type: 'GET_STATS'
    messageId: string
}

export type WorkerInMessage = InitMessage | GetMessage | PutMessage | ClearMessage | DeleteMessage | GetStatsMessage

export interface InitResult {
    type: 'INIT_RESULT'
    success: boolean
    error?: string
    messageId: string
}

export interface GetResult {
    type: 'GET_RESULT'
    found: boolean
    pixels?: Uint8ClampedArray
    width?: number
    height?: number
    messageId: string
}

export interface PutResult {
    type: 'PUT_RESULT'
    success: boolean
    error?: string
    messageId: string
}

export interface ClearResult {
    type: 'CLEAR_RESULT'
    success: boolean
    messageId: string
}

export interface DeleteResult {
    type: 'DELETE_RESULT'
    success: boolean
    messageId: string
}

export interface StatsResult {
    type: 'STATS_RESULT'
    count: number
    estimatedMB: number
    messageId: string
}

export type WorkerOutMessage = InitResult | GetResult | PutResult | ClearResult | DeleteResult | StatsResult

// === Worker State ===

interface CachedPixelData {
    url: string
    pixels: Uint8ClampedArray
    width: number
    height: number
    cachedAt: number
    version: number
}

let db: IDBDatabase | null = null
let storeName = 'pixels'
let dbVersion = 1

// Write batching
const writeQueue: CachedPixelData[] = []
let flushTimer: ReturnType<typeof setTimeout> | null = null
const FLUSH_INTERVAL_MS = 500
const MAX_QUEUE_SIZE = 10

// === IndexedDB Operations ===

function openDatabase(dbName: string, version?: number): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        const request = version == null ? indexedDB.open(dbName) : indexedDB.open(dbName, version)

        request.onerror = () => {
            reject(new Error(`Failed to open IndexedDB: ${request.error?.message}`))
        }

        request.onblocked = () => {
            reject(new Error('Failed to open IndexedDB: open request was blocked by another tab/session'))
        }

        request.onsuccess = () => {
            resolve(request.result)
        }
    })
}

async function ensureStoreExists(dbName: string): Promise<IDBDatabase> {
    const initialDb = await openDatabase(dbName)

    if (initialDb.objectStoreNames.contains(storeName)) {
        return initialDb
    }

    // Newly-created DBs (or legacy DBs) may be missing the store.
    // Reopen with a bumped schema version to create it.
    const nextVersion = Math.max(1, initialDb.version + 1)
    initialDb.close()

    return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, nextVersion)

        request.onerror = () => {
            reject(new Error(`Failed to upgrade IndexedDB schema: ${request.error?.message}`))
        }

        request.onblocked = () => {
            reject(new Error('Failed to upgrade IndexedDB schema: request was blocked by another tab/session'))
        }

        request.onupgradeneeded = (event) => {
            const database = (event.target as IDBOpenDBRequest).result
            if (!database.objectStoreNames.contains(storeName)) {
                const objectStore = database.createObjectStore(storeName, { keyPath: 'url' })
                objectStore.createIndex('cachedAt', 'cachedAt', { unique: false })
            }
        }

        request.onsuccess = () => {
            resolve(request.result)
        }
    })
}

async function initDatabase(dbName: string, store: string, version: number): Promise<void> {
    storeName = store
    dbVersion = version
    db = await ensureStoreExists(dbName)
}

async function getPixelData(url: string, version: number): Promise<CachedPixelData | null> {
    if (!db) return null

    return new Promise((resolve) => {
        const transaction = db!.transaction(storeName, 'readonly')
        const store = transaction.objectStore(storeName)
        const request = store.get(url)

        request.onerror = () => resolve(null)
        request.onsuccess = () => {
            const cached = request.result as CachedPixelData | undefined

            if (!cached || cached.version !== version) {
                resolve(null)
                return
            }

            resolve(cached)
        }
    })
}

function queueWrite(entry: CachedPixelData): void {
    writeQueue.push(entry)

    if (writeQueue.length >= MAX_QUEUE_SIZE) {
        flushWriteQueue()
        return
    }

    if (!flushTimer) {
        flushTimer = setTimeout(() => flushWriteQueue(), FLUSH_INTERVAL_MS)
    }
}

function flushWriteQueue(): void {
    if (flushTimer) {
        clearTimeout(flushTimer)
        flushTimer = null
    }

    if (writeQueue.length === 0 || !db) return

    const itemsToWrite = writeQueue.splice(0)

    const transaction = db.transaction(storeName, 'readwrite')
    const store = transaction.objectStore(storeName)

    for (const entry of itemsToWrite) {
        store.put(entry)
    }

    // Don't wait for completion - fire and forget
}

async function clearCache(): Promise<void> {
    if (!db) return

    return new Promise((resolve) => {
        const transaction = db!.transaction(storeName, 'readwrite')
        const store = transaction.objectStore(storeName)
        const request = store.clear()

        request.onerror = () => resolve()
        request.onsuccess = () => resolve()
    })
}

async function deleteEntry(url: string): Promise<void> {
    if (!db) return

    return new Promise((resolve) => {
        const transaction = db!.transaction(storeName, 'readwrite')
        const store = transaction.objectStore(storeName)
        const request = store.delete(url)

        request.onerror = () => resolve()
        request.onsuccess = () => resolve()
    })
}

async function getStats(): Promise<{ count: number; estimatedMB: number }> {
    if (!db) return { count: 0, estimatedMB: 0 }

    return new Promise((resolve) => {
        const transaction = db!.transaction(storeName, 'readonly')
        const store = transaction.objectStore(storeName)
        const countRequest = store.count()

        countRequest.onerror = () => resolve({ count: 0, estimatedMB: 0 })
        countRequest.onsuccess = () => {
            const count = countRequest.result
            // Estimate: 300├ù450├ù4 = 540KB per entry + ~100 bytes overhead
            const estimatedMB = (count * (540 * 1024 + 100)) / (1024 * 1024)
            resolve({ count, estimatedMB })
        }
    })
}

// === Message Handler ===

ctx.onmessage = async (event: MessageEvent<WorkerInMessage>) => {
    const message = event.data

    switch (message.type) {
        case 'INIT': {
            try {
                await initDatabase(message.dbName, message.storeName, message.version)
                ctx.postMessage({
                    type: 'INIT_RESULT',
                    success: true,
                    messageId: message.messageId
                } satisfies InitResult)
            } catch (error) {
                ctx.postMessage({
                    type: 'INIT_RESULT',
                    success: false,
                    error: error instanceof Error ? error.message : String(error),
                    messageId: message.messageId
                } satisfies InitResult)
            }
            break
        }

        case 'GET': {
            const cached = await getPixelData(message.url, message.version)

            if (cached) {
                // Transfer the ArrayBuffer for zero-copy
                const buffer = cached.pixels.buffer
                ctx.postMessage({
                    type: 'GET_RESULT',
                    found: true,
                    pixels: cached.pixels,
                    width: cached.width,
                    height: cached.height,
                    messageId: message.messageId
                } satisfies GetResult, [buffer])
            } else {
                ctx.postMessage({
                    type: 'GET_RESULT',
                    found: false,
                    messageId: message.messageId
                } satisfies GetResult)
            }
            break
        }

        case 'PUT': {
            const entry: CachedPixelData = {
                url: message.url,
                pixels: message.pixels,
                width: message.width,
                height: message.height,
                cachedAt: Date.now(),
                version: message.version
            }

            queueWrite(entry)

            ctx.postMessage({
                type: 'PUT_RESULT',
                success: true,
                messageId: message.messageId
            } satisfies PutResult)
            break
        }

        case 'CLEAR': {
            await clearCache()
            ctx.postMessage({
                type: 'CLEAR_RESULT',
                success: true,
                messageId: message.messageId
            } satisfies ClearResult)
            break
        }

        case 'DELETE': {
            await deleteEntry(message.url)
            ctx.postMessage({
                type: 'DELETE_RESULT',
                success: true,
                messageId: message.messageId
            } satisfies DeleteResult)
            break
        }

        case 'GET_STATS': {
            const stats = await getStats()
            ctx.postMessage({
                type: 'STATS_RESULT',
                count: stats.count,
                estimatedMB: stats.estimatedMB,
                messageId: message.messageId
            } satisfies StatsResult)
            break
        }
    }
}

// Global error handler
ctx.onerror = (event: ErrorEvent): boolean => {
    console.error('PixelCacheWorker error:', event.message)
    return true
}

/// <reference lib="webworker" />
/* eslint-disable @typescript-eslint/no-non-null-assertion */
/**
 * Web Worker for texture processing using OffscreenCanvas
 * 
 * Offloads expensive image operations from the main thread:
 * - Network fetch of image URLs
 * - Blob to ImageBitmap conversion
 * - Canvas rendering and scaling
 * - getImageData extraction (the expensive operation)
 * 
 * This file is loaded as a dedicated worker via Vite's ?worker import.
 */

// Worker global scope - these are available in web worker context
const ctx: DedicatedWorkerGlobalScope = self as unknown as DedicatedWorkerGlobalScope

// Empty export to make this a module (required for isolatedModules)
export {}

// === Message Types ===

/** Process texture from a Blob (legacy mode) */
export interface TextureProcessingMessage {
    type: 'PROCESS_TEXTURE'
    blob: Blob
    textureSize: number
    textureIndex: number
    messageId: string
}

/** Fetch and process texture from a URL (new mode) */
export interface TextureFetchMessage {
    type: 'FETCH_AND_PROCESS'
    url: string
    /** For square textures (legacy) */
    textureSize?: number
    /** For non-square textures (native resolution) */
    textureWidth?: number
    textureHeight?: number
    /** If true, use native image dimensions (skip resize entirely) */
    useNativeSize?: boolean
    textureIndex: number
    messageId: string
    gameName: string
    timeout?: number
}

export interface TextureProcessingResult {
    type: 'TEXTURE_PROCESSED'
    imageData: Uint8ClampedArray
    textureIndex: number
    messageId: string
    processingTime: number
    /** Actual dimensions of returned image data */
    width: number
    height: number
    gameName?: string
    /** Original blob for caching on main thread */
    blob?: Blob
}

export interface TextureProcessingError {
    type: 'TEXTURE_ERROR'
    error: string
    messageId: string
    gameName?: string
}

export type WorkerMessage = TextureProcessingMessage | TextureFetchMessage
export type WorkerResponse = TextureProcessingResult | TextureProcessingError

// Worker state
let offscreenCanvas: OffscreenCanvas | null = null
let offscreenContext: OffscreenCanvasRenderingContext2D | null = null
let canvasWidth = 0
let canvasHeight = 0

// Global error handler
ctx.onerror = (event: ErrorEvent): boolean => {
    console.error('Worker script error:', event)
    ctx.postMessage({
        type: 'TEXTURE_ERROR',
        error: 'Worker script error: ' + event.message,
        messageId: 'global-error'
    } satisfies TextureProcessingError)
    return true
}

/**
 * Initialize or reuse offscreen canvas for the given dimensions
 */
function ensureCanvas(width: number, height: number): void {
    if (!offscreenCanvas || canvasWidth !== width || canvasHeight !== height) {
        offscreenCanvas = new OffscreenCanvas(width, height)
        offscreenContext = offscreenCanvas.getContext('2d')
        canvasWidth = width
        canvasHeight = height

        if (!offscreenContext) {
            throw new Error('Failed to create OffscreenCanvas context')
        }
    }
}

/**
 * Process a blob into texture pixel data (legacy square mode)
 */
async function processBlob(
    blob: Blob, 
    textureSize: number
): Promise<Uint8ClampedArray> {
    ensureCanvas(textureSize, textureSize)

    // Create image bitmap from blob
    const imageBitmap = await createImageBitmap(blob)

    // Clear and draw scaled to texture size
    offscreenContext!.clearRect(0, 0, textureSize, textureSize)
    offscreenContext!.drawImage(imageBitmap, 0, 0, textureSize, textureSize)

    // Extract image data (the expensive operation we're offloading)
    const imageData = offscreenContext!.getImageData(0, 0, textureSize, textureSize)

    // Clean up bitmap
    imageBitmap.close()

    return imageData.data
}

interface ProcessBlobResult {
    imageData: Uint8ClampedArray
    width: number
    height: number
}

/**
 * Process a blob into texture pixel data with flexible dimensions
 * @param useNativeSize If true, use image's native dimensions (no resize)
 */
async function processBlobWithDimensions(
    blob: Blob,
    targetWidth?: number,
    targetHeight?: number,
    useNativeSize?: boolean
): Promise<ProcessBlobResult> {
    // Create image bitmap from blob
    const imageBitmap = await createImageBitmap(blob)

    // Determine output dimensions
    let width: number
    let height: number

    if (useNativeSize) {
        // Use native image dimensions
        width = imageBitmap.width
        height = imageBitmap.height
    } else if (targetWidth && targetHeight) {
        // Use specified dimensions
        width = targetWidth
        height = targetHeight
    } else {
        // Fallback: use native
        width = imageBitmap.width
        height = imageBitmap.height
    }

    ensureCanvas(width, height)

    // Clear and draw (scaled if dimensions differ from native)
    offscreenContext!.clearRect(0, 0, width, height)
    offscreenContext!.drawImage(imageBitmap, 0, 0, width, height)

    // Extract image data
    const imageData = offscreenContext!.getImageData(0, 0, width, height)

    // Clean up bitmap
    imageBitmap.close()

    return {
        imageData: imageData.data,
        width,
        height
    }
}

/**
 * Fetch image from URL with timeout
 */
async function fetchImage(url: string, timeout: number = 10000): Promise<Blob> {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), timeout)

    try {
        const response = await fetch(url, {
            signal: controller.signal,
            mode: 'cors'
        })

        clearTimeout(timeoutId)

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`)
        }

        const blob = await response.blob()

        if (!blob.type.startsWith('image/')) {
            throw new Error(`Invalid content type: ${blob.type}`)
        }

        return blob
    } catch (error) {
        clearTimeout(timeoutId)
        throw error
    }
}

ctx.onmessage = async (event: MessageEvent<WorkerMessage>): Promise<void> => {
    const { type, messageId } = event.data
    const startTime = performance.now()

    try {
        if (type === 'PROCESS_TEXTURE') {
            // Legacy mode: process blob directly (square textures)
            const { blob, textureSize, textureIndex } = event.data as TextureProcessingMessage

            const imageData = await processBlob(blob, textureSize)
            const processingTime = performance.now() - startTime

            const result: TextureProcessingResult = {
                type: 'TEXTURE_PROCESSED',
                imageData: imageData,
                textureIndex: textureIndex,
                messageId: messageId,
                processingTime: processingTime,
                width: textureSize,
                height: textureSize
            }

            // Transfer the ArrayBuffer to avoid copying
            ctx.postMessage(result, [imageData.buffer])

        } else if (type === 'FETCH_AND_PROCESS') {
            // New mode: fetch URL and process with flexible dimensions
            const { url, textureSize, textureWidth, textureHeight, useNativeSize, textureIndex, gameName, timeout } = event.data as TextureFetchMessage

            // Fetch image from network
            const blob = await fetchImage(url, timeout || 10000)

            // Process the blob with appropriate dimensions
            let processed: ProcessBlobResult

            if (useNativeSize || (textureWidth && textureHeight)) {
                // Use new flexible processing
                processed = await processBlobWithDimensions(blob, textureWidth, textureHeight, useNativeSize)
            } else if (textureSize) {
                // Legacy square mode
                const imageData = await processBlob(blob, textureSize)
                processed = { imageData, width: textureSize, height: textureSize }
            } else {
                // Default to native size if nothing specified
                processed = await processBlobWithDimensions(blob, undefined, undefined, true)
            }

            const processingTime = performance.now() - startTime

            const result: TextureProcessingResult = {
                type: 'TEXTURE_PROCESSED',
                imageData: processed.imageData,
                textureIndex: textureIndex,
                messageId: messageId,
                processingTime: processingTime,
                width: processed.width,
                height: processed.height,
                gameName: gameName,
                blob: blob // Return blob for main thread caching
            }

            // Transfer the ArrayBuffer to avoid copying
            ctx.postMessage(result, [processed.imageData.buffer])

        } else {
            console.log('Worker ignoring unknown message type:', type)
        }

    } catch (error) {
        const gameName = (event.data as TextureFetchMessage).gameName
        const errorResult: TextureProcessingError = {
            type: 'TEXTURE_ERROR',
            error: error instanceof Error ? error.message : String(error),
            messageId: messageId,
            gameName: gameName
        }
        ctx.postMessage(errorResult)
    }
}

