/**
 * Shared Interface for Instanced Renderers
 * 
 * Defines common lifecycle and management methods for GPU instanced rendering.
 * Enables consistent patterns across different instanced renderer implementations.
 * 
 * Implementing classes: InstancedLabelRenderer, InstancedArtworkRenderer, InstancedShelfRenderer
 */

import * as THREE from 'three'

export interface InstancedRendererConfig {
    maxInstances?: number
    enablePerformanceLogging?: boolean
}

export const DEFAULT_INSTANCED_RENDERER_CONFIG: InstancedRendererConfig = {
    maxInstances: 500
}

export interface InstancedRendererStats {
    /** Whether the renderer has been initialized */
    isInitialized: boolean
    /** Number of currently active instances */
    activeInstances: number
    /** Maximum instances configured */
    maxInstances: number
    /** Renderer-specific additional stats */
    [key: string]: any
}

export interface InstanceData {
    /** World position for this instance */
    position: THREE.Vector3
    /** Optional rotation (defaults to identity) */
    rotation?: THREE.Quaternion
    /** Optional scale (defaults to 1,1,1) */
    scale?: THREE.Vector3
    /** Renderer-specific configuration */
    [key: string]: any
}

export interface IInstancedRenderer {
    /**
     * Initialize the renderer - creates geometry, materials, and instanced meshes
     * @param initData Optional initialization data specific to renderer type
     */
    initialize(initData?: any): Promise<void> | void
    
    /**
     * Set configuration for a specific instance
     * @param index Instance index (0 to maxInstances-1)
     * @param data Instance configuration data
     */
    setInstance(index: number, data: InstanceData): Promise<boolean> | boolean
    
    updateGPU(): void
    
    reset(): void
    
    isReady(): boolean
    
    getStats(): InstancedRendererStats
    
    dispose(): void
}

export interface InstancedMeshConfig {
    /** Geometry for the instanced mesh */
    geometry: THREE.BufferGeometry
    /** Material for the instanced mesh */
    material: THREE.Material
    /** Maximum instances for this mesh */
    maxInstances: number
    /** Optional name for debugging */
    name?: string
}

export interface InstanceAttribute {
    /** Attribute name */
    name: string
    /** Values per instance (1 for float, 3 for Vector3, etc.) */
    itemSize: number
    /** Default value for new instances */
    defaultValue?: number | number[]
    /** Usage hint for GPU optimization */
    usage?: THREE.Usage
}

import * as THREE from 'three'
import { DataManager } from '../../core/data/DataManager'
import { Logger } from '../../utils/Logger'
import type { InstancedMeshConfig, InstanceAttribute } from './IInstancedRenderer'

export class InstancedMeshManager {
    private static readonly logger = Logger.createLogFunctions(InstancedMeshManager.name)
    private instancedMesh: THREE.InstancedMesh | null = null
    private maxInstances: number
    private currentCount: number = 0
    private isInitialized: boolean = false
    private debugName: string

    // Reusable objects for performance
    private static readonly DEFAULT_QUATERNION = new THREE.Quaternion()
    private static readonly DEFAULT_SCALE = new THREE.Vector3(1, 1, 1)
    private static readonly TEMP_MATRIX = new THREE.Matrix4()

    constructor(debugName: string = 'InstancedMesh') {
        this.debugName = debugName
        this.maxInstances = 1000 // Default, overridden in initialize
    }

    public initialize(config: InstancedMeshConfig): void {
        if (this.isInitialized) {
            InstancedMeshManager.logger.warn(`${this.debugName} already initialized`)
            return
        }

        this.maxInstances = config.maxInstances

        // Create instanced mesh
        this.instancedMesh = new THREE.InstancedMesh(
            config.geometry,
            config.material,
            this.maxInstances
        )

        // Configure mesh properties
        this.instancedMesh.name = config.name || this.debugName
        this.instancedMesh.count = 0
        this.instancedMesh.castShadow = true
        this.instancedMesh.receiveShadow = true
        this.instancedMesh.visible = true
        this.instancedMesh.frustumCulled = false

        // Ensure mesh is positioned at world origin (instances handle their own positions)
        this.instancedMesh.position.set(0, 0, 0)
        this.instancedMesh.rotation.set(0, 0, 0)
        this.instancedMesh.scale.set(1, 1, 1)

        this.isInitialized = true
        InstancedMeshManager.logger.debug(`Γ£à ${this.debugName} initialized (max: ${this.maxInstances} instances)`)
    }

    public addInstanceAttributes(attributes: InstanceAttribute[]): void {
        if (!this.instancedMesh) {
            InstancedMeshManager.logger.error(`Cannot add attributes: ${this.debugName} not initialized`)
            throw new Error(`Cannot add attributes: ${this.debugName} not initialized`)
        }

        const geometry = this.instancedMesh.geometry

        for (const attr of attributes) {
            // Create buffer with appropriate size
            const buffer = new Float32Array(this.maxInstances * attr.itemSize)

            // Fill with default values if provided
            if (attr.defaultValue !== undefined) {
                const defaultValues = Array.isArray(attr.defaultValue) 
                    ? attr.defaultValue 
                    : [attr.defaultValue]

                for (let i = 0; i < this.maxInstances; i++) {
                    for (let j = 0; j < attr.itemSize; j++) {
                        buffer[i * attr.itemSize + j] = defaultValues[j] || defaultValues[0] || 0
                    }
                }
            }

            // Create and add attribute
            const bufferAttribute = new THREE.InstancedBufferAttribute(buffer, attr.itemSize)
            if (attr.usage) {
                bufferAttribute.setUsage(attr.usage)
            }

            geometry.setAttribute(attr.name, bufferAttribute)

            InstancedMeshManager.logger.debug(`≡ƒôè Added instance attribute "${attr.name}" (${attr.itemSize} components) to ${this.debugName}`)
        }
    }

    public setInstanceMatrix(
        index: number,
        position: THREE.Vector3,
        rotation: THREE.Quaternion = InstancedMeshManager.DEFAULT_QUATERNION,
        scale: THREE.Vector3 = InstancedMeshManager.DEFAULT_SCALE
    ): boolean {
        if (!this.instancedMesh) {
            InstancedMeshManager.logger.warn(`Cannot set instance: ${this.debugName} not initialized`)
            return false
        }

        if (index >= this.maxInstances) {
            InstancedMeshManager.logger.warn(`Instance index ${index} exceeds max ${this.maxInstances} for ${this.debugName}`)
            return false
        }

        // Compose matrix from transform components
        InstancedMeshManager.TEMP_MATRIX.compose(position, rotation, scale)
        this.instancedMesh.setMatrixAt(index, InstancedMeshManager.TEMP_MATRIX)

        // Track highest index used
        this.currentCount = Math.max(this.currentCount, index + 1)

        return true
    }

    public setInstanceAttribute(
        attributeName: string,
        index: number,
        value: number | number[]
    ): boolean {
        if (!this.instancedMesh) {
            InstancedMeshManager.logger.warn(`Cannot set attribute: ${this.debugName} not initialized`)
            return false
        }

        const geometry = this.instancedMesh.geometry
        const attribute = geometry.getAttribute(attributeName) as THREE.InstancedBufferAttribute

        if (!attribute) {
            InstancedMeshManager.logger.warn(`Attribute "${attributeName}" not found on ${this.debugName}`)
            return false
        }

        if (index >= this.maxInstances) {
            InstancedMeshManager.logger.warn(`Instance index ${index} exceeds max ${this.maxInstances} for ${this.debugName}`)
            return false
        }

        // Set attribute values
        if (Array.isArray(value)) {
            for (let i = 0; i < value.length && i < attribute.itemSize; i++) {
                (attribute as any).setComponent(index, i, value[i])
            }
        } else {
            attribute.setX(index, value)
        }

        return true
    }

    public setInstanceColor(index: number, color: THREE.Color): boolean {
        if (!this.instancedMesh) return false
        if (index >= this.maxInstances) return false
        // Ensure instanceColor buffer is allocated on first use
        if (!this.instancedMesh.instanceColor) {
            this.instancedMesh.setColorAt(index, color)
        } else {
            this.instancedMesh.setColorAt(index, color)
        }
        return true
    }

    public updateGPU(): void {
        if (!this.instancedMesh) {
            return
        }

        // Update instance matrices
        this.instancedMesh.instanceMatrix.needsUpdate = true
        if (this.instancedMesh.instanceColor) {
            this.instancedMesh.instanceColor.needsUpdate = true
        }

        // Update instance count
        this.instancedMesh.count = this.currentCount

        // Update all instance attributes
        const geometry = this.instancedMesh.geometry
        for (const attributeName in geometry.attributes) {
            const attribute = geometry.attributes[attributeName]
            if (attribute instanceof THREE.InstancedBufferAttribute) {
                attribute.needsUpdate = true
            }
        }

        InstancedMeshManager.logger.debug(`≡ƒöä ${this.debugName} GPU updated: ${this.currentCount} active instances`)
    }

    public reset(): void {
        this.currentCount = 0
        if (this.instancedMesh) {
            this.instancedMesh.count = 0
        }
        InstancedMeshManager.logger.debug(`≡ƒöä ${this.debugName} instances reset`)
    }

    public addToMainScene(): void {
        if (!this.instancedMesh) {
            InstancedMeshManager.logger.warn(`ΓÜá∩╕Å Cannot add to scene: ${this.debugName} not initialized`)
            return
        }

        const scene = DataManager.getInstance().get<any>('core.mainScene')
        if (!scene) {
            InstancedMeshManager.logger.warn(`ΓÜá∩╕Å Cannot add to scene: main scene not available in DataManager`)
            return
        }

        scene.add(this.instancedMesh)
        InstancedMeshManager.logger.debug(`Γ₧ò ${this.debugName} added to main scene`)
    }

    public removeFromMainScene(): void {
        if (!this.instancedMesh) {
            return
        }

        const scene = DataManager.getInstance().get<any>('core.mainScene')
        if (scene) {
            scene.remove(this.instancedMesh)
            InstancedMeshManager.logger.debug(`Γ₧û ${this.debugName} removed from main scene`)
        }
    }

    // For advanced operations only
    public getInstancedMesh(): THREE.InstancedMesh | null {
        return this.instancedMesh
    }

    public isReady(): boolean {
        return this.isInitialized && this.instancedMesh !== null
    }

    public getStats() {
        return {
            isInitialized: this.isInitialized,
            activeInstances: this.currentCount,
            maxInstances: this.maxInstances,
            debugName: this.debugName
        }
    }

    public dispose(): void {
        InstancedMeshManager.logger.debug(`≡ƒº╣ Disposing ${this.debugName}`)

        this.removeFromMainScene()

        // NOTE: Geometry and material are shared - caller handles disposal

        this.instancedMesh = null
        this.isInitialized = false
        this.currentCount = 0

        InstancedMeshManager.logger.debug(`Γ£à ${this.debugName} disposed`)
    }
}

/**
 * InstancedShelfRenderer
 * 
 * ROLE: GPU-instanced rendering of shelf units. Handles geometry, materials,
 * and efficient batch rendering of multiple shelf instances.
 * 
 * OWNS:
 * - Shelf geometry templates (angled boards, side boards, shelf boards, interior surfaces)
 * - InstancedMesh managers for each geometry type
 * - Shelf unit instances (position + config)
 * - GPU buffer updates
 * 
 * RECEIVES:
 * - setInstance(index, data) ΓåÆ Creates/updates shelf at index
 * - updateGPU() ΓåÆ Flushes instance changes to GPU
 * - SomeBatchesComplete event ΓåÆ Triggers coalesced GPU update
 * 
 * EMITS:
 * - RendererReady ΓåÆ When initialize() completes (Phase 3: replaces polling)
 * 
 * DELEGATES TO:
 * - InstancedMeshManager: Per-geometry-type instancing
 * - SharedMaterialManager: Material acquisition
 * - ShelfStickerHandler: Sticker placement on side boards
 * 
 * DOES NOT:
 * - Calculate shelf positions (that's layout's job)
 * - Know about games or batches (pure rendering)
 * - Handle events for shelf creation (receives method calls currently)
 * 
 * INITIALIZATION:
 * - initialize() is async and emits RendererReady event when complete
 * - Callers can await promise OR listen for event (dual-mode for backward compat)
 * - Legacy isReady() polling still available but deprecated
 */

import * as THREE from 'three'
import { InstancedMeshManager } from './InstancedMeshManager'
import { SharedMaterialManager, MaterialType } from '../../utils/SharedMaterialManager'
import { DEFAULT_SHELF_CONFIG, ShelfCalculationUtils, type ShelfConfig } from '../props/SharedPropsUtils'
import { DEFAULT_INSTANCED_RENDERER_CONFIG, type InstancedRendererConfig, type InstanceData } from './IInstancedRenderer'
import type { 
    IInstancedRenderer, 
    InstancedRendererStats
} from './IInstancedRenderer'
import { ShelfStickerHandler } from '../stickers/ShelfStickerHandler'
import { buildShelfGeometryTemplates, buildShelfUnitTemplate, ShelfGeometryType, type ShelfPartTemplate } from './ShelfGeometryBuilder'
import { EventManager } from '../../core/EventManager'
import { GameEventTypes, StorePropsEventTypes, type RendererReadyEvent, type ShelfReadyEvent } from '../../types/InteractionEvents'
import { Logger } from '../../utils/Logger'
import { MeshPrewarmer } from '../../utils/MeshPrewarmer'
import { SystemCapabilitiesDetector } from '../../utils/SystemCapabilities'
import { FrameBudgetScheduler } from '../../utils/FrameBudgetScheduler'

export interface InstancedShelfConfig extends InstancedRendererConfig {
    defaultShelfConfig?: ShelfConfig
    maxShelfUnits?: number
}

export const DEFAULT_INSTANCED_SHELF_CONFIG = {
    ...DEFAULT_INSTANCED_RENDERER_CONFIG,
    maxShelfUnits: 100,
    defaultShelfConfig: DEFAULT_SHELF_CONFIG
} as const

export interface ShelfInstanceData extends InstanceData {
    shelfConfig?: ShelfConfig
}

interface ShelfUnitInstance {
    position: THREE.Vector3
    instanceIndices: {
        angledBoards: number[]
        sideBoards: number[]
        shelfBoards: number[]
        interiorSurfaces: number[]
    }
}

// TODO: Explore pre-baking shelf geometry as GLTF/FBX for faster load (after dynamic config needs are settled)
export class InstancedShelfRenderer implements IInstancedRenderer {
    private static readonly logger = Logger.createLogFunctions('InstancedShelfRenderer')

    private angledBoardManager: InstancedMeshManager
    private sideBoardManager: InstancedMeshManager
    private shelfBoardManager: InstancedMeshManager
    private interiorSurfaceManager: InstancedMeshManager

    private readonly maxShelfUnits: number
    private readonly defaultShelfConfig: Required<ShelfConfig>
    private isInitialized: boolean = false
    private shelfUnits: Map<number, ShelfUnitInstance> = new Map()
    private nextInstanceIndex: { [K in ShelfGeometryType]: number } = {
        angledBoard: 0,
        sideBoard: 0,
        shelfBoard: 0,
        interior: 0
    }

    private geometryTemplates: { [K in ShelfGeometryType]?: THREE.BufferGeometry } = {}

    // Pre-calculated shelf data (computed ONCE since all shelves are identical)
    private readonly shelfYPositions: number[]
    private readonly shelfDepthsAndOffsets: Array<{ shelfDepth: number; forwardOffset: number }>

    // Shelf unit template (computed ONCE, applied to each shelf position)
    private shelfUnitTemplate: ShelfPartTemplate[] = []
    private hasParallelShaderCompile = false
    private pendingShelfReady = new Map<number, ShelfReadyEvent>()
    private meshesAddedToScene = false
    private sceneInsertCancelled = false

    // TODO: Consider making sticker system fully pluggable (dependency injection or optional feature)
    private readonly stickerHandler: ShelfStickerHandler

    constructor(config: InstancedShelfConfig = {}) {
        this.maxShelfUnits = config.maxShelfUnits ?? DEFAULT_INSTANCED_SHELF_CONFIG.maxShelfUnits

        // TODO: Make sticker system optional/pluggable to reduce coupling
        this.stickerHandler = new ShelfStickerHandler()

        this.defaultShelfConfig = {
            ...DEFAULT_INSTANCED_SHELF_CONFIG.defaultShelfConfig,
            ...config.defaultShelfConfig
        } as Required<ShelfConfig>

        // PRE-CALCULATE shelf positions once (all shelf units are identical)
        this.shelfYPositions = ShelfCalculationUtils.calculateAllShelfYPositions({
            height: this.defaultShelfConfig.height,
            shelfCount: this.defaultShelfConfig.shelfCount,
            shelfVerticalOffset: this.defaultShelfConfig.shelfVerticalOffset
        })

        // PRE-CALCULATE shelf depths once (all shelf units are identical)
        // Use 0-indexed loop to match createHorizontalShelves access pattern
        this.shelfDepthsAndOffsets = []
        for (let i = 0; i < this.defaultShelfConfig.shelfCount; i++) {
            this.shelfDepthsAndOffsets.push(
                ShelfCalculationUtils.calculateShelfDepthAndOffset(i, {
                    depth: this.defaultShelfConfig.depth,
                    boardThickness: this.defaultShelfConfig.boardThickness,
                    shelfCount: this.defaultShelfConfig.shelfCount,
                    shelfExtensionPerLevel: this.defaultShelfConfig.shelfExtensionPerLevel
                })
            )
        }

        // Initialize managers
        this.angledBoardManager = new InstancedMeshManager('InstancedShelf-AngledBoards')
        this.sideBoardManager = new InstancedMeshManager('InstancedShelf-SideBoards')
        this.shelfBoardManager = new InstancedMeshManager('InstancedShelf-ShelfBoards')
        this.interiorSurfaceManager = new InstancedMeshManager('InstancedShelf-InteriorSurfaces')

        EventManager.getInstance().registerEventHandler(
            GameEventTypes.SomeBatchesComplete,
            this.updateGPU.bind(this)
        )

        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.ShelfReady,
            (event: CustomEvent<ShelfReadyEvent>) => this.handleShelfReady(event.detail)
        )

        InstancedShelfRenderer.logger.debug(`≡ƒÅ¬ Created (max units: ${this.maxShelfUnits})`)
    }

    public async initialize(): Promise<void> {
        if (this.isInitialized) {
            InstancedShelfRenderer.logger.warn('Already initialized')
            return
        }

        try {
            const materialManager = SharedMaterialManager.getInstance()
            const mdfVeneerMaterial = materialManager.getMaterial(MaterialType.MdfVeneer)
            const shelfInteriorMaterial = materialManager.getMaterial(MaterialType.ShelfInterior)
            const brandAccentMaterial = materialManager.getMaterial(MaterialType.BrandAccent)

            this.geometryTemplates = buildShelfGeometryTemplates(this.defaultShelfConfig)

            const angledBoardGeometry = this.geometryTemplates[ShelfGeometryType.AngledBoard]
            const sideBoardGeometry = this.geometryTemplates[ShelfGeometryType.SideBoard]
            const shelfBoardGeometry = this.geometryTemplates[ShelfGeometryType.ShelfBoard]
            const interiorSurfaceGeometry = this.geometryTemplates[ShelfGeometryType.InteriorSurface]

            if (!angledBoardGeometry || !sideBoardGeometry || !shelfBoardGeometry || !interiorSurfaceGeometry) {
                throw new Error('Failed to create geometry templates')
            }

            this.angledBoardManager.initialize({
                geometry: angledBoardGeometry,
                material: mdfVeneerMaterial,
                maxInstances: this.maxShelfUnits * 2,
                name: 'instanced-shelf-angled-boards'
            })

            // TODO: Consider material decoration pattern to avoid direct material modification here
            // Clone and modify side board material to support stickers (macro texture mode)
            const stickerEnabledMaterial = brandAccentMaterial.clone()
            const stickerIntegration = this.stickerHandler.getStickerIntegration()
            if (stickerIntegration) {
                stickerIntegration.setupStickerMaterial(stickerEnabledMaterial)
            }

            this.sideBoardManager.initialize({
                geometry: sideBoardGeometry,
                material: stickerEnabledMaterial,
                maxInstances: this.maxShelfUnits * 2,
                name: 'instanced-shelf-side-boards'
            })

            this.shelfBoardManager.initialize({
                geometry: shelfBoardGeometry,
                material: mdfVeneerMaterial,
                maxInstances: this.maxShelfUnits * 5,
                name: 'instanced-shelf-boards'
            })

            this.interiorSurfaceManager.initialize({
                geometry: interiorSurfaceGeometry,
                material: shelfInteriorMaterial,
                maxInstances: this.maxShelfUnits * 5,
                name: 'instanced-shelf-interior-surfaces'
            })

            // Add custom instance attributes for dynamic sizing/positioning
            this.setupInstanceAttributes()

            // Build shelf unit template (stamp pattern for creating shelves)
            this.shelfUnitTemplate = buildShelfUnitTemplate(this.defaultShelfConfig, this.shelfYPositions, this.shelfDepthsAndOffsets)

            // Register meshes with MeshPrewarmer ΓÇö it batches all registrations
            // across a debounce window and calls compileAsync once, non-blocking.
            // We detect KHR here for future use: if we later need to stagger mesh registration
            // *into* the prewarm scene on capable hardware, this flag drives that gate.
            // It does NOT control how we insert into the main scene (always staggered).
            this.hasParallelShaderCompile = SystemCapabilitiesDetector.detect().hasParallelShaderCompile
            for (const manager of [this.angledBoardManager, this.sideBoardManager, this.shelfBoardManager, this.interiorSurfaceManager]) {
                const mesh = manager.getInstancedMesh()
                if (mesh) MeshPrewarmer.register(mesh)
            }

            this.isInitialized = true
            this.flushPendingShelfReady()

            // Emit RendererReady event (Phase 3: replace polling with events)
            EventManager.getInstance().emit<RendererReadyEvent>(
                StorePropsEventTypes.RendererReady,
                { rendererType: 'shelf' }
            )
            InstancedShelfRenderer.logger.debug('Γ£à Initialized, emitted RendererReady event')

        } catch (err) {
            InstancedShelfRenderer.logger.error('Γ¥î Failed to initialize:', err)
            throw err
        }
    }

    private setupInstanceAttributes(): void {
        this.angledBoardManager.addInstanceAttributes([
            { name: 'rotationAngle', itemSize: 1, defaultValue: 0 }
        ])

        this.shelfBoardManager.addInstanceAttributes([
            { name: 'shelfScale', itemSize: 2, defaultValue: [1, 1] }
        ])

        this.interiorSurfaceManager.addInstanceAttributes([
            { name: 'surfaceScale', itemSize: 2, defaultValue: [1, 1] }
        ])

        const stickerIntegration = this.stickerHandler.getStickerIntegration()
        if (stickerIntegration) {
            stickerIntegration.setupInstanceAttributes(this.sideBoardManager)
        }
        this.stickerHandler.setManagers(this.sideBoardManager, this.shelfUnits.size)
    }

    public setInstance(index: number, data: ShelfInstanceData): boolean {
        if (!this.isInitialized) {
            InstancedShelfRenderer.logger.warn('Not initialized')
            return false
        }

        if (index >= this.maxShelfUnits) {
            InstancedShelfRenderer.logger.warn(`Shelf unit index ${index} exceeds max ${this.maxShelfUnits}`)
            return false
        }

        // Merge with default configuration
        const shelfConfig: Required<ShelfConfig> = {
            ...this.defaultShelfConfig,
            ...data.shelfConfig
        }

        try {
            if (this.shelfUnits.size === 0) {
                this.ensureMeshesAddedToScene()
            }

            // Idempotent: if this shelfId already exists, reuse its instance slots.
            // This lets runtime relayout update positions without allocating new GPU slots.
            const existing = this.shelfUnits.get(index)
            if (existing) {
                this.updateShelfUnitTransform(index, existing, data.position, data.rotation)
                InstancedShelfRenderer.logger.debug(`≡ƒöä Updated shelf unit ${index} at (${data.position.x.toFixed(2)}, ${data.position.y.toFixed(2)}, ${data.position.z.toFixed(2)})`)
                return true
            }

            const shelfUnit = this.applyShelfUnitTemplate(index, data.position, data.rotation)
            this.shelfUnits.set(index, shelfUnit)

            InstancedShelfRenderer.logger.debug(`≡ƒÅ¬ Set shelf unit ${index} at position (${data.position.x.toFixed(2)}, ${data.position.y.toFixed(2)}, ${data.position.z.toFixed(2)})`)
            return true

        } catch (err) {
            InstancedShelfRenderer.logger.error(`Γ¥î Failed to set shelf unit ${index}:`, err)
            return false
        }
    }

    private ensureMeshesAddedToScene(): void {
        if (this.meshesAddedToScene) {
            return
        }
        this.meshesAddedToScene = true
        this.sceneInsertCancelled = false

        // Schedule one mesh per frame via FrameBudgetScheduler.
        // The scheduler runs at most one task per frame by default, so the 4 inserts
        // spread across 4 consecutive frames naturally ΓÇö keeping any residual GPU compile
        // work from landing in a single frame regardless of whether compileAsync ran.
        // (hasParallelShaderCompile is retained for a future gate: staggering registration
        // *into* the prewarm scene on capable hardware ΓÇö not yet needed.)
        const scheduler = FrameBudgetScheduler.getInstance()
        for (const manager of [this.angledBoardManager, this.sideBoardManager,
                                this.shelfBoardManager, this.interiorSurfaceManager]) {
            scheduler.schedule(() => {
                if (!this.sceneInsertCancelled) manager.addToMainScene()
            }, { priority: 'high', maxDeferMs: 0 })
        }

        InstancedShelfRenderer.logger.debug('Scheduled 4 instanced shelf mesh insertions (one per frame, never forced)')
    }

    private applyShelfUnitTemplate(
        shelfUnitIndex: number,
        position: THREE.Vector3,
        unitRotation?: THREE.Quaternion
    ): ShelfUnitInstance {
        const instanceIndices = {
            angledBoards: [] as number[],
            sideBoards: [] as number[],
            shelfBoards: [] as number[],
            interiorSurfaces: [] as number[]
        }

        for (const part of this.shelfUnitTemplate) {
            // Rotate the part offset around the unit origin if a Y rotation is provided
            const rotatedOffset = unitRotation
                ? part.offset.clone().applyQuaternion(unitRotation)
                : part.offset.clone()
            const worldPos = position.clone().add(rotatedOffset)
            let instanceIndex: number
            let manager: InstancedMeshManager
            let indicesArray: number[]

            switch (part.type) {
                case ShelfGeometryType.AngledBoard:
                    instanceIndex = this.nextInstanceIndex.angledBoard++
                    manager = this.angledBoardManager
                    indicesArray = instanceIndices.angledBoards
                    break
                case ShelfGeometryType.SideBoard:
                    instanceIndex = this.nextInstanceIndex.sideBoard++
                    manager = this.sideBoardManager
                    indicesArray = instanceIndices.sideBoards
                    break
                case ShelfGeometryType.ShelfBoard:
                    instanceIndex = this.nextInstanceIndex.shelfBoard++
                    manager = this.shelfBoardManager
                    indicesArray = instanceIndices.shelfBoards
                    break
                case ShelfGeometryType.InteriorSurface:
                    instanceIndex = this.nextInstanceIndex.interior++
                    manager = this.interiorSurfaceManager
                    indicesArray = instanceIndices.interiorSurfaces
                    break
            }

            // Combine unit-level Y rotation with part's own rotation (e.g. shelf board tilt)
            const finalRotation = unitRotation
                ? (part.rotation ? unitRotation.clone().multiply(part.rotation) : unitRotation.clone())
                : part.rotation
            manager.setInstanceMatrix(instanceIndex, worldPos, finalRotation, part.scale)

            if (part.customAttributes) {
                for (const attr of part.customAttributes) {
                    manager.setInstanceAttribute(attr.name, instanceIndex, attr.value)
                }
            }

            if (part.isSideBoard) {
                this.stickerHandler.initializeSideboardStickers(
                    this.sideBoardManager,
                    instanceIndex,
                    shelfUnitIndex,
                    part.sideboardIsLeft ?? true
                )
            }

            indicesArray.push(instanceIndex)
        }

        return {
            position: position.clone(),
            instanceIndices
        }
    }

    /**
     * Update the world-space matrices of an already-instanced shelf unit.
     * Reuses the existing GPU instance slots rather than allocating new ones.
     * Called by setInstance when the shelfId already exists.
     */
    private updateShelfUnitTransform(
        _shelfUnitIndex: number,
        existing: ShelfUnitInstance,
        position: THREE.Vector3,
        unitRotation?: THREE.Quaternion
    ): void {
        existing.position.copy(position)

        const partsWithIndices = [
            { type: ShelfGeometryType.AngledBoard,       indices: existing.instanceIndices.angledBoards,    manager: this.angledBoardManager },
            { type: ShelfGeometryType.SideBoard,         indices: existing.instanceIndices.sideBoards,      manager: this.sideBoardManager },
            { type: ShelfGeometryType.ShelfBoard,        indices: existing.instanceIndices.shelfBoards,     manager: this.shelfBoardManager },
            { type: ShelfGeometryType.InteriorSurface,   indices: existing.instanceIndices.interiorSurfaces, manager: this.interiorSurfaceManager },
        ]

        let partIdx = 0
        for (const part of this.shelfUnitTemplate) {
            const rotatedOffset = unitRotation
                ? part.offset.clone().applyQuaternion(unitRotation)
                : part.offset.clone()
            const worldPos = position.clone().add(rotatedOffset)

            const entry = partsWithIndices.find(p => p.type === part.type)
            if (!entry || partIdx >= entry.indices.length) continue

            // Each geometry type has its own index cursor; use partIdx relative to type group
            const typeIdx = partsWithIndices
                .filter(p => p.type === part.type)
                .indexOf(entry)
            const instanceIndex = entry.indices[typeIdx] ?? entry.indices[0]

            const finalRotation = unitRotation
                ? (part.rotation ? unitRotation.clone().multiply(part.rotation) : unitRotation.clone())
                : part.rotation
            entry.manager.setInstanceMatrix(instanceIndex, worldPos, finalRotation, part.scale)

            partIdx++
        }
    }

    private handleShelfReady(detail: ShelfReadyEvent): void {
        if (!this.isReady()) {
            this.pendingShelfReady.set(detail.batchIndex, detail)
            return
        }

        // Idempotent: if a shelf with this shelfId already exists, treat as a position update.
        // This allows runtime relayout to reuse the same shelfId without re-instancing churn.
        // Full matrix rewrite is safe because setInstance overwrites the instance slot.
        const rotation = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, detail.rotationY, 0))
        this.setInstance(detail.batchIndex, {
            position: detail.position as THREE.Vector3,
            rotation,
        })
    }

    private flushPendingShelfReady(): void {
        if (!this.isReady() || this.pendingShelfReady.size === 0) {
            return
        }

        const pending = Array.from(this.pendingShelfReady.values()).sort((a, b) => a.batchIndex - b.batchIndex)
        this.pendingShelfReady.clear()

        for (const detail of pending) {
            this.handleShelfReady(detail)
        }
    }

    public updateGPU(): void {
        if (!this.isInitialized) {
            return
        }

        this.angledBoardManager.updateGPU()
        this.sideBoardManager.updateGPU()
        this.shelfBoardManager.updateGPU()
        this.interiorSurfaceManager.updateGPU()

        InstancedShelfRenderer.logger.debug(`≡ƒöä GPU updated: ${this.shelfUnits.size} shelf units`)
    }

    public reset(): void {
        this.angledBoardManager.reset()
        this.sideBoardManager.reset()
        this.shelfBoardManager.reset()
        this.interiorSurfaceManager.reset()

        this.shelfUnits.clear()
        this.stickerHandler.setManagers(this.sideBoardManager, 0)
        this.nextInstanceIndex = {
            angledBoard: 0,
            sideBoard: 0,
            shelfBoard: 0,
            interior: 0
        }
        this.meshesAddedToScene = false
        this.sceneInsertCancelled = true
        this.pendingShelfReady.clear()

        InstancedShelfRenderer.logger.debug('≡ƒöä Reset')
    }

    public isReady(): boolean {
        return this.isInitialized &&
               this.angledBoardManager.isReady() &&
               this.sideBoardManager.isReady() &&
               this.shelfBoardManager.isReady() &&
               this.interiorSurfaceManager.isReady()
    }

    public getStats(): InstancedRendererStats {
        const angledStats = this.angledBoardManager.getStats()
        const sideStats = this.sideBoardManager.getStats()
        const shelfStats = this.shelfBoardManager.getStats()
        const interiorStats = this.interiorSurfaceManager.getStats()

        const activeGeometryTypes = [
            this.angledBoardManager.isReady() ? 1 : 0,
            this.sideBoardManager.isReady() ? 1 : 0, 
            this.shelfBoardManager.isReady() ? 1 : 0,
            this.interiorSurfaceManager.isReady() ? 1 : 0
        ].reduce((sum, count) => sum + count, 0)

        return {
            isInitialized: this.isInitialized,
            activeInstances: this.shelfUnits.size,
            maxInstances: this.maxShelfUnits,
            shelfUnits: this.shelfUnits.size,
            geometryStats: {
                angledBoards: angledStats,
                sideBoards: sideStats,
                shelfBoards: shelfStats,
                interiorSurfaces: interiorStats
            },
            activeGeometryMaterialCombinations: activeGeometryTypes
        }
    }

    public dispose(): void {
        InstancedShelfRenderer.logger.debug('≡ƒº╣ Disposing')

        // Dispose all managers
        this.angledBoardManager.dispose()
        this.sideBoardManager.dispose()
        this.shelfBoardManager.dispose()
        this.interiorSurfaceManager.dispose()

        // Dispose geometry templates
        Object.values(this.geometryTemplates).forEach(geometry => {
            geometry?.dispose()
        })
        this.geometryTemplates = {}

        this.shelfUnits.clear()
        this.isInitialized = false
        this.meshesAddedToScene = false
        this.sceneInsertCancelled = true
        this.hasParallelShaderCompile = false
        this.pendingShelfReady.clear()

        InstancedShelfRenderer.logger.debug('Γ£à Disposed')
    }
}

/**
 * ShelfGeometryBuilder
 *
 * Pure functions for building shelf geometry templates and shelf unit part templates.
 * Extracted from InstancedShelfRenderer for testability and separation of concerns.
 */

import * as THREE from 'three'
import { ShelfCalculationUtils, type ShelfConfig } from '../props/SharedPropsUtils'

// ΓöÇΓöÇΓöÇ Geometry types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export enum ShelfGeometryType {
    AngledBoard = 'angledBoard',
    SideBoard = 'sideBoard',
    ShelfBoard = 'shelfBoard',
    InteriorSurface = 'interior'
}

export interface ShelfPartTemplate {
    type: ShelfGeometryType
    offset: THREE.Vector3
    rotation?: THREE.Quaternion
    scale?: THREE.Vector3
    customAttributes?: { name: string; value: number | number[] }[]
    isSideBoard?: boolean
    sideboardIsLeft?: boolean
}

// ΓöÇΓöÇΓöÇ Builder functions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Build one BufferGeometry per ShelfGeometryType using the given shelf config.
 */
export function buildShelfGeometryTemplates(
    config: Required<ShelfConfig>
): Record<ShelfGeometryType, THREE.BufferGeometry> {
    const { width, height, depth, boardThickness } = config

    return {
        [ShelfGeometryType.AngledBoard]: new THREE.BoxGeometry(width, height, boardThickness),
        [ShelfGeometryType.SideBoard]: new THREE.BoxGeometry(boardThickness, height, depth),
        [ShelfGeometryType.ShelfBoard]: new THREE.BoxGeometry(width, boardThickness, depth),
        [ShelfGeometryType.InteriorSurface]: new THREE.BoxGeometry(
            width * 0.98,
            boardThickness * 0.1,
            depth * 0.98
        ),
    }
}

/**
 * Build the per-shelf-unit part template (stamp pattern used when placing each shelf).
 * This is computed once and reused for every shelf unit position.
 */
export function buildShelfUnitTemplate(
    config: Required<ShelfConfig>,
    shelfYPositions: number[],
    shelfDepthsAndOffsets: Array<{ shelfDepth: number; forwardOffset: number }>
): ShelfPartTemplate[] {
    const angleRad = (config.angle * Math.PI) / 180
    const boardSeparation = config.depth * 0.8

    const template: ShelfPartTemplate[] = []

    // Angled boards (front and back)
    template.push({
        type: ShelfGeometryType.AngledBoard,
        offset: new THREE.Vector3(0, config.height / 2, boardSeparation / 2),
        rotation: new THREE.Quaternion().setFromEuler(new THREE.Euler(-angleRad, 0, 0)),
        customAttributes: [{ name: 'rotationAngle', value: -config.angle }]
    })

    template.push({
        type: ShelfGeometryType.AngledBoard,
        offset: new THREE.Vector3(0, config.height / 2, -boardSeparation / 2),
        rotation: new THREE.Quaternion().setFromEuler(new THREE.Euler(angleRad, 0, 0)),
        customAttributes: [{ name: 'rotationAngle', value: config.angle }]
    })

    // Side boards (left and right)
    template.push({
        type: ShelfGeometryType.SideBoard,
        offset: new THREE.Vector3(-config.width / 2 - config.boardThickness * 0.5, config.height / 2, 0),
        isSideBoard: true,
        sideboardIsLeft: true
    })

    template.push({
        type: ShelfGeometryType.SideBoard,
        offset: new THREE.Vector3(config.width / 2 + config.boardThickness * 0.5, config.height / 2, 0),
        isSideBoard: true,
        sideboardIsLeft: false
    })

    // Horizontal shelves and interior surfaces
    for (let i = 0; i < config.shelfCount; i++) {
        const shelfY = shelfYPositions[i]
        const widthAtHeight = config.width - 2 * (config.height - shelfY) * Math.tan(angleRad)
        const { shelfDepth, forwardOffset } = shelfDepthsAndOffsets[i]

        const widthScale = widthAtHeight / config.width
        const depthScale = shelfDepth / config.depth

        // Shelf board
        template.push({
            type: ShelfGeometryType.ShelfBoard,
            offset: new THREE.Vector3(0, shelfY, forwardOffset),
            scale: new THREE.Vector3(widthScale, 1, depthScale),
            customAttributes: [{ name: 'shelfScale', value: [widthScale, depthScale] }]
        })

        // Interior surface
        template.push({
            type: ShelfGeometryType.InteriorSurface,
            offset: new THREE.Vector3(0, shelfY + config.boardThickness * 0.55, forwardOffset),
            scale: new THREE.Vector3(widthScale, 1, depthScale),
            customAttributes: [{ name: 'surfaceScale', value: [widthScale, depthScale] }]
        })
    }

    return template
}

/**
 * Convenience: compute shelfYPositions and shelfDepthsAndOffsets from a config.
 * Matches the logic in InstancedShelfRenderer constructor.
 */
export function computeShelfLayout(config: Required<ShelfConfig>): {
    shelfYPositions: number[]
    shelfDepthsAndOffsets: Array<{ shelfDepth: number; forwardOffset: number }>
} {
    const shelfYPositions = ShelfCalculationUtils.calculateAllShelfYPositions({
        height: config.height,
        shelfCount: config.shelfCount,
        shelfVerticalOffset: config.shelfVerticalOffset,
    })

    const shelfDepthsAndOffsets: Array<{ shelfDepth: number; forwardOffset: number }> = []
    for (let i = 0; i < config.shelfCount; i++) {
        shelfDepthsAndOffsets.push(
            ShelfCalculationUtils.calculateShelfDepthAndOffset(i, {
                depth: config.depth,
                boardThickness: config.boardThickness,
                shelfCount: config.shelfCount,
                shelfExtensionPerLevel: config.shelfExtensionPerLevel,
            })
        )
    }

    return { shelfYPositions, shelfDepthsAndOffsets }
}

/**
 * Regression: SceneClickGameBoxRaycast must check which InstancedMesh was hit
 * before consulting metadata maps.
 *
 * Bug (recurring): Artwork and label renderers both use InstancedMesh with
 * instanceIds starting at 0. Without identity check, clicking label box #N
 * consulted artworkMetadata at index N and returned the wrong game.
 *
 * Fix: check object.name ('lod-game-artwork' vs 'gpu-instanced-game-boxes')
 * before consulting each map, so the correct game is always returned.
 */
import { describe, it, expect } from 'vitest'
import { INSTANCED_LABEL_MESH_NAME } from '../../scene/game-box/instancing/InstancedLabelRenderer'
import { LOD_ARTWORK_MESH_NAME } from '../../scene/game-box/instancing/LodGameArtworkRenderer'

// Inline the minimal metadata type to avoid cross-module import in test
interface InstanceMetadata { name: string; appid?: number | string; position: any }

/** Simulate what resolveGameBoxIntersection does with mesh identity check. */
function resolveHit(
    meshName: string,
    instanceId: number,
    artworkMetadata: Map<number, InstanceMetadata>,
    labelMetadata: Map<number, { name: string; appid?: number | string }>
): { name?: string; appid?: number | string } | null {
    const isLabelMesh = meshName === 'gpu-instanced-game-boxes'
    const isArtworkMesh = meshName === 'lod-game-artwork'

    if (!isLabelMesh) {
        const hit = artworkMetadata.get(instanceId)
        if (hit) return { name: hit.name, appid: hit.appid }
    }

    if (!isArtworkMesh) {
        const hit = labelMetadata.get(instanceId)
        if (hit) return { name: hit.name, appid: hit.appid }
    }

    return null
}

describe('raycast mesh identity check', () => {
    const artworkMeta = new Map<number, InstanceMetadata>([
        [0, { name: 'ArtGame0', appid: 100, position: null as any }],
        [1, { name: 'ArtGame1', appid: 101, position: null as any }],
        [2, { name: 'ArtGame2', appid: 102, position: null as any }],
    ])

    const labelMeta = new Map<number, { name: string; appid?: number | string }>([
        [0, { name: 'LabelGame0', appid: 200 }],
        [1, { name: 'LabelGame1', appid: 201 }],
        [2, { name: 'LabelGame2', appid: 202 }],
    ])

    it('hitting artwork mesh at index 1 returns artwork game, not label game', () => {
        const hit = resolveHit('lod-game-artwork', 1, artworkMeta, labelMeta)
        expect(hit?.appid).toBe(101)
        expect(hit?.name).toBe('ArtGame1')
    })

    it('hitting label mesh at index 1 returns label game, not artwork game', () => {
        const hit = resolveHit('gpu-instanced-game-boxes', 1, artworkMeta, labelMeta)
        expect(hit?.appid).toBe(201)
        expect(hit?.name).toBe('LabelGame1')
    })

    it('same instanceId on different meshes returns different games', () => {
        const artHit = resolveHit('lod-game-artwork', 0, artworkMeta, labelMeta)
        const labelHit = resolveHit('gpu-instanced-game-boxes', 0, artworkMeta, labelMeta)
        expect(artHit?.appid).toBe(100)
        expect(labelHit?.appid).toBe(200)
    })

    it('unknown mesh name falls through both maps gracefully', () => {
        // Unknown mesh: tries artwork first (not isLabelMesh), then label (not isArtworkMesh).
        // Index 5 doesn't exist in either map ??? should return null.
        const hit = resolveHit('some-other-mesh', 5, artworkMeta, labelMeta)
        expect(hit).toBeNull()
    })

    it('unknown mesh with matching index returns artwork map entry first', () => {
        // Unknown mesh: not a label mesh, so artwork is checked first.
        const hit = resolveHit('some-other-mesh', 0, artworkMeta, labelMeta)
        expect(hit?.appid).toBe(100)  // artwork wins for unknown mesh
    })

    describe('DataKey names match the actual mesh names used in renderers', () => {
        it('INSTANCED_LABEL_MESH_NAME is gpu-instanced-game-boxes', () => {
            // Imported from InstancedLabelRenderer. If the mesh name changes, this fails.
            expect(INSTANCED_LABEL_MESH_NAME).toBe('gpu-instanced-game-boxes')
        })

        it('LOD_ARTWORK_MESH_NAME is lod-game-artwork', () => {
            // Imported from LodGameArtworkRenderer. If the mesh name changes, this fails.
            expect(LOD_ARTWORK_MESH_NAME).toBe('lod-game-artwork')
        })
    })
})

/**
 * SceneClickGameBoxRaycast ΓÇö click-to-game-detail regression coverage.
 *
 * History:
 * - maxDistance=10m default failed to reach back-wall shelves at r=21.5m (fixed).
 * - setMaxDistance() was later removed; raycast reach is now set at construction
 *   time via options (default 7m, set to arc depth by SystemUICoordinator).
 * - Wrong game resolved on click due to stale InstancedLabelMetadata (fixed in
 *   InstancedLabelRenderer: fresh map on construction, cleared on reset()).
 */
import { describe, it, expect } from 'vitest'

describe('raycast maxDistance covers arc layout depth', () => {
    it('arc back-wall shelf at r=21.5m is beyond the old 10m default', () => {
        // Production arc config: firstRowRadius=5.5, rowRadiusStep=4, rows=5
        // Row 4 radius = 5.5 + 4*4 = 21.5m
        const backWallRadius = 5.5 + 4 * 4.0
        const OLD_DEFAULT_MAX_DISTANCE = 10
        expect(OLD_DEFAULT_MAX_DISTANCE).toBeLessThan(backWallRadius)
    })

    it('SystemUICoordinator reach formula covers back wall with margin', () => {
        // Simulate what SystemUICoordinator does: abs(minZ) + 2m margin
        const mockBounds = { minX: -22, maxX: 22, minZ: -21.5, maxZ: 0 }
        const reach = Math.abs(mockBounds.minZ) + 2
        expect(reach).toBeGreaterThan(21.5)
        expect(reach).toBe(23.5)
    })
})

describe('instance metadata contract', () => {
    it('instanceId from Three.js intersection maps to correct game via metadata', () => {
        // The raycast resolves games by looking up intersection.instanceId in
        // DataKey.InstancedArtworkMetadata or DataKey.InstancedLabelMetadata.
        // This test pins the shape of that lookup to catch API drift.
        const artworkMetadata = new Map([
            [0, { name: 'Game A', appid: 100, position: null }],
            [1, { name: 'Game B', appid: 200, position: null }],
        ])
        const hit0 = artworkMetadata.get(0)
        const hit1 = artworkMetadata.get(1)
        expect(hit0?.name).toBe('Game A')
        expect(hit0?.appid).toBe(100)
        expect(hit1?.name).toBe('Game B')
        // Stale entry at index 2 must not exist
        expect(artworkMetadata.get(2)).toBeUndefined()
    })

    it('label metadata uses same instanceId key shape as artwork metadata', () => {
        const labelMetadata = new Map([
            [0, { name: 'Label Game', position: null }],
        ])
        const hit = labelMetadata.get(0)
        expect(hit?.name).toBe('Label Game')
    })
})

