}

export class SceneClickGameBoxRaycast {
    private static readonly logger = Logger.createLogFunctions(SceneClickGameBoxRaycast.name)
    private readonly sceneOption: THREE.Scene | undefined
    private readonly cameraOption: THREE.Camera | undefined
    private readonly maxDistance: number
    private readonly enableDebugLogs: boolean
    private readonly enableDebugLine: boolean
    private readonly eventManager: EventManager

    private resolvedScene: THREE.Scene | null = null
    private resolvedCamera: THREE.Camera | null = null

    private readonly raycaster = new THREE.Raycaster()
    private readonly pointer = new THREE.Vector2()
    private readonly direction = new THREE.Vector3()

    private debugLine: THREE.Line | null = null
    private readonly lineGeometry = new THREE.BufferGeometry()
    private readonly lineMaterial: THREE.LineBasicMaterial

    constructor(options: SceneClickGameBoxRaycastOptions) {
        this.sceneOption = options.scene
        this.cameraOption = options.camera
        this.maxDistance = options.maxDistance ?? 5
        this.enableDebugLogs = options.enableDebugLogs ?? false
        this.enableDebugLine = options.enableDebugLine ?? false
        this.eventManager = EventManager.getInstance()

        this.lineMaterial = new THREE.LineBasicMaterial({
            color: options.lineColor ?? 0xff0000
        })

        // Direct mask: only bit for SceneLayer.Interactable. THREE.Layers.set() always
        // ORs in layer 0 (its implementation is `1 | (1 << channel)`), which would
        // test non-interactable objects and require a redundant post-filter.
        this.raycaster.layers.mask = 1 << SceneLayer.Interactable

        this.eventManager.registerEventHandler<SceneCanvasClickEvent>(
            InputEventTypes.SceneCanvasClick,
            this.handleSceneCanvasClick
        )
    }

    public dispose(): void {
        this.eventManager.deregisterEventHandler<SceneCanvasClickEvent>(
            InputEventTypes.SceneCanvasClick,
            this.handleSceneCanvasClick
        )

        if (this.debugLine && this.resolvedScene) {
            this.resolvedScene.remove(this.debugLine)
            this.debugLine = null
        }

        this.lineGeometry.dispose()
        this.lineMaterial.dispose()
    }

    private readonly handleSceneCanvasClick = (event: CustomEvent<SceneCanvasClickEvent>): void => {
        const { button, ndcX, ndcY } = event.detail

        if (button !== 0) {
            return
        }

        // Lazy-resolve scene/camera: DataManager may not be populated at construction time
        const dm = DataManager.getInstance()
        const scene = this.resolvedScene ?? (this.sceneOption ?? dm.get<THREE.Scene>(DataKey.MainScene) ?? null)
        const camera = this.resolvedCamera ?? (this.cameraOption ?? dm.get<THREE.Camera>(DataKey.MainCamera) ?? null)

        if (!scene || !camera) {
            return
        }

        this.resolvedScene = scene
        this.resolvedCamera = camera

        this.pointer.x = ndcX
        this.pointer.y = ndcY

        this.raycaster.far = this.maxDistance
        this.raycaster.setFromCamera(this.pointer, camera)

        const lineStart = this.raycaster.ray.origin.clone()
        const lineEnd = lineStart.clone().add(this.direction.copy(this.raycaster.ray.direction).multiplyScalar(this.maxDistance))
        if (this.enableDebugLine) {
            this.updateDebugLine(lineStart, lineEnd, scene)
        }

        const intersections = this.raycaster.intersectObjects(scene.children, true)

        for (const intersection of intersections) {
            const hit = this.resolveGameBoxIntersection(intersection)
            if (hit) {
                this.highlightHit(hit)
                return
            }
        }

        if (this.enableDebugLogs) {
            SceneClickGameBoxRaycast.logger.debug('No game box hit', { maxDistance: this.maxDistance })
        }
    }

    private updateDebugLine(start: THREE.Vector3, end: THREE.Vector3, scene: THREE.Scene): void {
        this.lineGeometry.setFromPoints([start, end])

        if (!this.debugLine) {
            this.debugLine = new THREE.Line(this.lineGeometry, this.lineMaterial)
            this.debugLine.name = 'scene-click-raycast-debug-line'
            scene.add(this.debugLine)
        }
    }

    private resolveGameBoxIntersection(intersection: THREE.Intersection<THREE.Object3D>): SceneGameBoxHit | null {
        const object = intersection.object

        if (intersection.instanceId !== undefined) {
            // GameFinder.findByIntersection disambiguates artwork vs label mesh by name,
            // then looks up the appropriate metadata map. instanceId is per-mesh (0..N)
            // so mesh identity must be checked before map lookup.
            const result = GameFinder.findByInstancedObject({ object, instanceId: intersection.instanceId! })
            if (result) {
                return {
                    name: result.name,
                    appid: result.appid,
                    point: intersection.point.clone(),
                    distance: intersection.distance,
                    object,
                    instanceId: intersection.instanceId
                }
            }

            // Fallback: unknown instanced mesh not in our maps
            return {
                point: intersection.point.clone(),
                distance: intersection.distance,
                object,
                instanceId: intersection.instanceId
            }
        }

        if (object.userData?.isGameBox) {
            return {
                name: object.userData?.name ?? object.name,
                appid: object.userData?.appid,
                point: intersection.point.clone(),
                distance: intersection.distance,
                object
            }
        }

        return null
    }

    private highlightHit(hit: SceneGameBoxHit): void {
        const appid = hit.appid

        // Development aid: log resolved hit so appid is visible in console.
        // Gated on enableDebugLogs ΓÇö remove gate when raycast is fully stable.
        if (this.enableDebugLogs) {
            SceneClickGameBoxRaycast.logger.debug(
                `hit: name="${hit.name ?? '?'}" appid=${appid ?? 'none'} instanceId=${hit.instanceId ?? '?'} mesh="${hit.object.name}"`
            )
        }

        if (appid !== undefined) {
            this.eventManager.emit<GameSelectedEvent>(GameEventTypes.Selected, {
                appid
            })
        } else if (this.enableDebugLogs) {
            SceneClickGameBoxRaycast.logger.debug('Hit had no appid metadata', {
                instanceId: hit.instanceId
            })
        }

        if (this.enableDebugLogs) {
            SceneClickGameBoxRaycast.logger.debug('Hit game box', {
                name: hit.name,
                appid: hit.appid,
                distance: hit.distance,
                instanceId: hit.instanceId
            })
        }
    }

}

/**
 * GPU Store Props Event Handler - High-Performance Event Handler
 * 
 * Registers as an override handler for store props events IF the system
 * has the required capabilities (WebGL2 + instanced arrays).
 * 
 * Wraps the GpuStorePropsRenderer for high-performance GPU-based rendering.
 * Falls back to default handler if initialization or rendering fails.
 */

import * as THREE from 'three'
import { EventManager } from '../../core/EventManager'
import { GpuStorePropsRenderer } from '../GpuStorePropsRenderer'
import { Logger } from '../../utils/Logger'
import { StorePropsEventTypes, type StorePropsSetupRequestEvent, type StorePropsSetupStartedEvent, type StorePropsSetupCompletedEvent, type StorePropsClearRequestEvent, type StorePropsAtmosphericRequestEvent } from './PropsEvents'
import { EventSource } from '../../core/EventManager'
import { hasWebGL2, hasInstancedArrays, hasHardwareRenderer, supportsLargeTextures } from '../../utils/SystemCapabilities'
import { RoomEventTypes, type RoomResizedEvent } from '../../types/InteractionEvents'
import { PropRenderer } from '../PropRenderer'

// TODO: I think this can just be merged down into the gpu renderer class.
// This is an added layer, separating out the event handling, but could be slim enough to sit inside the class proper
export class GpuStorePropsEventHandler {
    private static readonly logger = Logger.createLogFunctions(GpuStorePropsEventHandler.name)
    private eventManager: EventManager
    private renderer: GpuStorePropsRenderer | null = null
    private isCapable: boolean
    private entranceMat: THREE.Group | null = null
    private scene: THREE.Scene | null = null

    static {
        new GpuStorePropsEventHandler();
    }

    // TODO: enforce only one exists
    private constructor() {
        this.eventManager = EventManager.getInstance()
        this.isCapable = this.checkCapabilities()

        if (this.isCapable) {
            this.registerAsReplacement()
            GpuStorePropsEventHandler.logger.info('GpuStorePropsEventHandler initialized and registered as replacement (system is capable)')
        } else {
            GpuStorePropsEventHandler.logger.info('GpuStorePropsEventHandler not registered - system lacks required capabilities')
        }

        // Listen for room resize events to reposition entrance mat
        this.eventManager.registerEventHandler(RoomEventTypes.Resized, this.handleRoomResized.bind(this))
    }

    private checkCapabilities(): boolean {
        const hasRequiredFeatures = hasWebGL2() && hasInstancedArrays() && hasHardwareRenderer()
        const hasLargeTextures = supportsLargeTextures()

        GpuStorePropsEventHandler.logger.debug('Capability check:', {
            hasWebGL2: hasWebGL2(),
            hasInstancedArrays: hasInstancedArrays(), 
            hasHardwareRenderer: hasHardwareRenderer(),
            supportsLargeTextures: hasLargeTextures,
            overall: hasRequiredFeatures
        })

        // Warn if missing large texture support but proceed anyway
        if (hasRequiredFeatures && !hasLargeTextures) {
            GpuStorePropsEventHandler.logger.warn('System meets core requirements but lacks large texture support - proceeding with potential performance impact')
        }

        // Only fail if missing core requirements (WebGL2, instanced arrays, hardware renderer)
        return hasRequiredFeatures
    }

    private registerAsReplacement(): void {
        // Register as override handler to replace default handler when system is capable
        this.eventManager.registerOverrideHandler(
            StorePropsEventTypes.SetupRequest,
            this.handleSetupRequest.bind(this)
        )

        this.eventManager.registerOverrideHandler(
            StorePropsEventTypes.ClearRequest,
            this.handleClearRequest.bind(this)
        )

        this.eventManager.registerOverrideHandler(
            StorePropsEventTypes.AtmosphericRequest,
            this.handleAtmosphericRequest.bind(this)
        )

        GpuStorePropsEventHandler.logger.debug('Registered as override handler for store props events')
    }

    private async handleSetupRequest(event: CustomEvent<StorePropsSetupRequestEvent>): Promise<void> {
        const startTime = performance.now()
        const { config } = event.detail

        try {
            GpuStorePropsEventHandler.logger.info('Handling store props setup request with instanced renderer')

            // Initialize instanced renderer if not already done
            if (!this.renderer) {
                // Get dependencies from singletons - no DI through events
                const { DataManager } = await import('../../core/data')
                const dataManager = DataManager.getInstance()
                const scene = dataManager.get<THREE.Scene>('core.mainScene')

                if (!scene) {
                    throw new Error('Main scene not available in DataManager')
                }

                // Create renderer with own GameBoxRenderer (composition, not injection)
                this.renderer = new GpuStorePropsRenderer(scene)
            }

            // Emit setup started event
            this.eventManager.emit<StorePropsSetupStartedEvent>(StorePropsEventTypes.SetupStarted, {
                timestamp: Date.now(),
                source: EventSource.System
            })

            // Perform instanced setup
            await this.renderer.setupProps(config as any)

            const endTime = performance.now()
            const setupTimeMs = endTime - startTime

            // Emit completion event
            this.eventManager.emit<StorePropsSetupCompletedEvent>(StorePropsEventTypes.SetupCompleted, {
                timestamp: Date.now(),
                source: EventSource.System
            })

            GpuStorePropsEventHandler.logger.info(`Instanced store props setup completed in ${setupTimeMs.toFixed(2)}ms`)

        } catch (error) {
            GpuStorePropsEventHandler.logger.warn('Instanced store props setup failed, falling back to default:', error)

            // Clean up failed renderer
            if (this.renderer) {
                try {
                    this.renderer.dispose()
                } catch (disposeError) {
                    GpuStorePropsEventHandler.logger.error('Failed to dispose renderer during fallback:', disposeError)
                }
                this.renderer = null
            }

            // Note: Default handler will be used for subsequent events since override failed
            GpuStorePropsEventHandler.logger.warn('Setup failed - default handler will handle future requests')
        }
    }

    // TODO: This wrapping is unnecessary
    private async handleClearRequest(event: CustomEvent<StorePropsClearRequestEvent>): Promise<void> {
        try {
            if (this.renderer) {
                this.renderer.clearProps()
                GpuStorePropsEventHandler.logger.debug('Instanced store props cleared')
            }
        } catch (error) {
            GpuStorePropsEventHandler.logger.warn('Instanced clear failed:', error);
            // Note: Default handler will be used for subsequent requests
        }
    }

    private async handleAtmosphericRequest(event: CustomEvent<StorePropsAtmosphericRequestEvent>): Promise<void> {
        try {
            if (this.renderer) {
                await this.renderer.addAtmosphericProps()
                GpuStorePropsEventHandler.logger.debug('Instanced atmospheric props added')
            }
        } catch (error) {
            GpuStorePropsEventHandler.logger.warn('Instanced atmospheric props failed:', error);
            // Note: Default handler will be used for subsequent requests
        }
    }


    private async handleRoomResized(event: CustomEvent<RoomResizedEvent>): Promise<void> {
        const { dimensions } = event.detail

        // Get scene reference if we don't have it yet
        if (!this.scene && this.renderer) {
            const { DataManager } = await import('../../core/data')
            const dataManager = DataManager.getInstance()
            this.scene = dataManager.get<THREE.Scene>('core.mainScene')
        }

        if (!this.scene) {
            GpuStorePropsEventHandler.logger.warn('Cannot create entrance mat - no scene reference')
            return
        }

        // Remove old entrance mat if it exists
        if (this.entranceMat) {
            this.scene.remove(this.entranceMat)
            this.entranceMat = null
        }

        // Create new entrance mat where player spawns (inside the store)
        const propRenderer = new PropRenderer(this.scene)
        this.entranceMat = propRenderer.createEntranceFloorMat(dimensions.width, dimensions.depth)

    // Position at origin - keep entrance mat/player spawn fixed at (0,0,0)
    // Room/front wall will be offset instead to encapsulate the mat
    this.entranceMat.position.set(0, 0, 0)

    this.scene.add(this.entranceMat)
    GpuStorePropsEventHandler.logger.debug(`≡ƒÜ¬ Entrance mat positioned at origin (0,0,0) - player spawn`) 
    }

    public dispose(): void {
        if (this.renderer) {
            this.renderer.dispose()
            this.renderer = null
        }

        if (this.entranceMat && this.scene) {
            this.scene.remove(this.entranceMat)
            this.entranceMat = null
        }

        GpuStorePropsEventHandler.logger.info('GpuStorePropsEventHandler disposed')
    }
}

/**
 * Store Props Events - Event definitions for the props rendering system
 * 
 * This module contains all event types and interfaces related to store props
 * (shelves, games, signage, and interactive objects) rendering and management.
 */

import type { BaseInteractionEvent } from '../../core/EventManager'
import { EventSource } from '../../core/EventManager'

// =============================================================================
// STORE PROPS EVENT INTERFACES
// =============================================================================

export interface StorePropsSetupRequestEvent extends BaseInteractionEvent {
    readonly config: {
        readonly enableShelves?: boolean
        readonly enableGameBoxes?: boolean
        readonly enableSignage?: boolean
        readonly enableTestObjects?: boolean
        readonly enableDebugObjects?: boolean
        readonly enableAtmosphericProps?: boolean
    }
}

export interface StorePropsSetupStartedEvent extends BaseInteractionEvent {
    // No additional data needed - start signal is sufficient
}

export interface StorePropsSetupCompletedEvent extends BaseInteractionEvent {
    // No additional data needed - completion is the signal itself
}

export interface StorePropsClearRequestEvent extends BaseInteractionEvent {
    // No additional data needed
}

export interface StorePropsAtmosphericRequestEvent extends BaseInteractionEvent {
    // No additional data needed
}

// =============================================================================
// STORE PROPS EVENT TYPES
// =============================================================================

export const StorePropsEventTypes = {
    SetupRequest: 'store-props:setup-request',
    SetupStarted: 'store-props:setup-started',
    SetupCompleted: 'store-props:setup-completed',
    ClearRequest: 'store-props:clear-request',
    AtmosphericRequest: 'store-props:atmospheric-request'
} as const

// =============================================================================
// TYPE EXPORTS FOR CONVENIENCE
// =============================================================================

export type { BaseInteractionEvent, EventSource }

import { describe, it, expect } from 'vitest'
import { computeArcShelfLayout } from './ArcLayoutUtils'

describe('computeArcShelfLayout', () => {
    it('generates the correct number of shelf positions', () => {
        const shelves = computeArcShelfLayout(20)
        expect(shelves).toHaveLength(20)
    })

    it('does not exceed totalShelves even if row capacity is larger', () => {
        const shelves = computeArcShelfLayout(7)
        expect(shelves).toHaveLength(7)
    })

    it('all positions have y = 0', () => {
        const shelves = computeArcShelfLayout(10)
        shelves.forEach(s => expect(s.position.y).toBe(0))
    })

    it('all positions are in the -Z half-space (in front of player)', () => {
        const shelves = computeArcShelfLayout(20)
        shelves.forEach(s => expect(s.position.z).toBeLessThan(0))
    })

    it('successive rows have increasing arc radius (further from origin)', () => {
        const shelves = computeArcShelfLayout(20, { rows: 4, shelvesPerRow: 4 })
        // Centre shelf of each row (index 1 in a 4-shelf row) should be further each time
        const centreShelves = [0, 4, 8, 12].map(i => shelves[i + 1])
        const radii = centreShelves.map(s => Math.sqrt(s.position.x ** 2 + s.position.z ** 2))
        for (let i = 1; i < radii.length; i++) {
            expect(radii[i]).toBeGreaterThan(radii[i - 1])
        }
    })

    it('shelves face toward origin: the shelf-front direction (after rotY) points at (0,0,0)', () => {
        const shelves = computeArcShelfLayout(8, { rows: 2, shelvesPerRow: 4 })
        for (const s of shelves) {
            // Shelf front in local space is +Z before rotation.
            // After rotationY, front direction = (sin(rotY), 0, cos(rotY)).
            // For inward facing, this vector should point from shelf position toward origin,
            // i.e., roughly (-x, 0, -z) normalised.
            const dx = -s.position.x
            const dz = -s.position.z
            const len = Math.sqrt(dx * dx + dz * dz)
            const toOriginX = dx / len
            const toOriginZ = dz / len

            const frontX = Math.sin(s.rotationY)
            const frontZ = Math.cos(s.rotationY)

            const dot = frontX * toOriginX + frontZ * toOriginZ
            // Dot product > 0.95 means within ~18 deg of pointing at origin
            expect(dot).toBeGreaterThan(0.95)
        }
    })

    it('44-shelf layout keeps walkable side gaps on rows 0-3 and allows tighter last row', () => {
        const shelves = computeArcShelfLayout(44, {
            rows: 5,
            shelvesPerRowByRow: [4, 6, 10, 12, 12],
            firstRowRadius: 4.5,
            rowRadiusStep: 4.0,
            halfAngle: Math.PI / 3,
            halfAngleByRow: [Math.PI / 4.2, Math.PI / 3.8, Math.PI / 3.2, Math.PI / 3.0, Math.PI / 2.6],
            minShelfGap: 1.0,
            shelfWidthMetres: 2.0,
        })

        const rows = new Map<number, typeof shelves>()
        for (const s of shelves) {
            if (!rows.has(s.row)) rows.set(s.row, [])
            rows.get(s.row)!.push(s)
        }

        // For each row, sort by indexInRow then compute adjacent centre distances
        const SHELF_WIDTH = 2.0
        for (let row = 0; row < 5; row++) {
            const rowShelves = (rows.get(row) ?? []).sort((a, b) => a.indexInRow - b.indexInRow)
            for (let i = 1; i < rowShelves.length; i++) {
                const a = rowShelves[i - 1].position
                const b = rowShelves[i].position
                const dist = Math.hypot(b.x - a.x, b.z - a.z)
                const gap = dist - SHELF_WIDTH

                if (row < 4) {
                    // Rows 0-3 should keep at least 1m side aisle gap
                    expect(gap).toBeGreaterThanOrEqual(0.95)
                } else {
                    // Last row may be tighter to maximize back wall density
                    expect(gap).toBeGreaterThan(0.2)
                }
            }
        }
    })

    // --- Regression: batch-count mismatch (shelf position overflow) ---
    // Verifies the production arc config never allocates fewer positions than requested.
    // This catches the "CRITICAL: Shelf position N is undefined" bug (ea54d8d).
    it.each([
        [44, 'lower bound typical library'],
        [47, 'observed production count (spitemonger)'],
        [52, 'headroom for larger libraries'],
        [80, 'large library'],
    ])('allocates exactly %i positions for %s', (total) => {
        const FIXED = 4 + 6 + 10 + 12
        const shelves = computeArcShelfLayout(total, {
            rows: 5,
            shelvesPerRow: 10,
            shelvesPerRowByRow: [4, 6, 10, 12, Math.max(1, total - FIXED)],
            halfAngle: Math.PI / 3,
            halfAngleByRow: [
                Math.PI / 3,
                Math.PI / 3.5,
                Math.PI / 3,
                Math.PI / 3,
                Math.PI / 2.6,
            ],
            minShelfGap: 1.0,
            shelfWidthMetres: 2.0,
            rowRadiusStep: 4.0,
            firstRowRadius: 5.5,
        })
        expect(shelves.length).toBe(total)
        // Every position must be defined (no undefined slot)
        shelves.forEach((s, i) => {
            expect(s, `shelf ${i} should be defined`).toBeDefined()
            expect(isFinite(s.position.x), `shelf ${i} x must be finite`).toBe(true)
            expect(isFinite(s.position.z), `shelf ${i} z must be finite`).toBe(true)
        })
    })
})

describe('partial-row centering', () => {
    it('single shelf in a row lands at angle=0 (straight ahead, not off to the side)', () => {
        const shelves = computeArcShelfLayout(1, {
            rows: 5,
            shelvesPerRow: 4,
            firstRowRadius: 5.5,
            halfAngle: Math.PI / 3,
        })
        expect(shelves).toHaveLength(1)
        // Straight ahead is xΓëê0, zΓëê-radius. Allow ┬▒0.01m tolerance.
        expect(Math.abs(shelves[0].position.x)).toBeLessThan(0.01)
        expect(shelves[0].position.z).toBeCloseTo(-5.5, 1)
    })

    it('two shelves in a four-slot row are symmetric around x=0', () => {
        const shelves = computeArcShelfLayout(2, {
            rows: 5,
            shelvesPerRow: 4,
            firstRowRadius: 5.5,
            halfAngle: Math.PI / 3,
        })
        expect(shelves).toHaveLength(2)
        const xSum = shelves[0].position.x + shelves[1].position.x
        expect(Math.abs(xSum)).toBeLessThan(0.01) // symmetric around x=0
    })
})

/**
 * ArcLayoutUtils
 *
 * Shelf positions for the concentric-arc (semicircle) layout.
 *
 * Geometry:
 * - Player stands at origin (0, 0, 0) facing -Z
 * - Shelves are arranged along arcs centred on the player origin
 * - Arc rows extend from directly in front and curve outward as they recede
 * - Shelves face inward (toward the player)
 *
 * Arc parameters are tuned so:
 * - The front row sits at a comfortable browsing distance
 * - Each successive row is a wider, deeper arc segment
 * - The total span stays within room width bounds
 */

import * as THREE from 'three'

export interface ArcLayoutConfig {
    /** Number of concentric arc rows. Default 5. */
    rows?: number
    /** Shelves per row (arc segment). Default 4. */
    shelvesPerRow?: number
    /** Radius increment per row (metres). Default 4. */
    rowRadiusStep?: number
    /** Radius of the first row (metres from player origin). Default 5. */
    firstRowRadius?: number
    /** Half-angle of the arc in radians. Default PI/3 (60 deg each side = 120 deg span). */
    halfAngle?: number
    /** Optional per-row half-angle overrides (radians). */
    halfAngleByRow?: number[]
    /** Physical width of one shelf unit in metres (used with minShelfGap). Default 2.0. */
    shelfWidthMetres?: number
    /**
     * Minimum centre-to-centre gap between adjacent shelves in a row (metres).
     * If set, the per-row shelf count is capped so no row violates this gap.
     * Row 0 always respects this; for the last row it is relaxed to allow the back wall.
     * Default: undefined (no enforcement).
     */
    minShelfGap?: number
    /**
     * Per-row shelf counts. If provided, overrides shelvesPerRow for each row index.
     * Allows outer rings to have more shelves than inner rings.
     * TD: inverted-layout - use this to implement the "wider-outer-ring" plan:
     *   front ring: 3 shelves (sparse, close), back rings: 6-8 (dense, far)
     *   combine with decreasing halfAngle toward front for the narrowing effect
     *   docs/roadmaps/tech-debt.md -> "Inverted arc layout"
     */
    shelvesPerRowByRow?: number[]
}

const DEFAULTS: Required<Pick<ArcLayoutConfig, 'rows' | 'shelvesPerRow' | 'rowRadiusStep' | 'firstRowRadius' | 'halfAngle'>> = {
    rows: 5,
    shelvesPerRow: 4,
    rowRadiusStep: 4.0,
    firstRowRadius: 5.0,
    halfAngle: Math.PI / 3, // 60 deg each side
}

export interface ArcShelfInfo {
    position: THREE.Vector3
    /** Y rotation so shelf faces player origin (0,0,0). */
    rotationY: number
    row: number
    indexInRow: number
}

/**
 * Maximum number of shelves that can fit in an arc row while keeping inter-shelf
 * chord distance >= shelfWidth + minGap.
 */
function maxShelvesForGap(radius: number, halfAngle: number, minGap: number, shelfWidth: number): number {
    for (let n = 40; n >= 2; n--) {
        const angleStep = (2 * halfAngle) / (n - 1)
        const chord = 2 * radius * Math.sin(angleStep / 2)
        if (chord >= shelfWidth + minGap) return n
    }
    return 1
}

/**
 * Generate shelf positions and orientations for a concentric-arc layout.
 * Returns positions in row-major order (all shelves of row 0, then row 1, etc).
 */
export function computeArcShelfLayout(
    totalShelves: number,
    config: ArcLayoutConfig = {}
): ArcShelfInfo[] {
    const cfg = { ...DEFAULTS, ...config }
    const result: ArcShelfInfo[] = []

    let shelfIndex = 0
    for (let row = 0; row < cfg.rows && shelfIndex < totalShelves; row++) {
        const radius = cfg.firstRowRadius + row * cfg.rowRadiusStep
        const rowHalfAngle = cfg.halfAngleByRow?.[row] ?? cfg.halfAngle
        let count = cfg.shelvesPerRowByRow?.[row] ?? cfg.shelvesPerRow

        // Enforce minimum walkable gap unless this is the last row (back wall)
        if (cfg.minShelfGap !== undefined && row < cfg.rows - 1) {
            const shelfWidth = cfg.shelfWidthMetres ?? 2.0
            const max = maxShelvesForGap(radius, rowHalfAngle, cfg.minShelfGap, shelfWidth)
            if (count > max) count = max
        }

        // Clamp to how many shelves we'll actually place in this row so the
        // placed shelves are centred at angle=0 rather than bunched to one side.
        const actualCount = Math.min(count, totalShelves - shelfIndex)

        for (let i = 0; i < count && shelfIndex < totalShelves; i++) {
            // Spread shelves evenly across the arc span, using actualCount for
            // spacing so a partial row stays centred (not left-justified).
            const t = actualCount === 1 ? 0 : (i / (actualCount - 1)) - 0.5   // -0.5 .. +0.5
            const angle = t * 2 * rowHalfAngle                     // -halfAngle .. +halfAngle

            // Arc is in the -Z half-space (in front of player)
            // angle = 0 means straight ahead (-Z axis), positive angle = left, negative = right
            const x = radius * Math.sin(angle)
            const z = -radius * Math.cos(angle)

            // Rotate shelf to face player origin (0, 0, 0)
            const facingAngle = Math.atan2(x, z)     // model front is -Z; rotate so -Z points toward origin
            const rotationY = facingAngle + Math.PI  // shelf front faces inward

            result.push({
                position: new THREE.Vector3(x, 0, z),
                rotationY,
                row,
                indexInRow: i,
            })
            shelfIndex++
        }
    }

    return result
}

import * as THREE from 'three'
import type { GameBoxTextureOptions } from '../../game-box/types/GameBoxOptions'

export class ArtworkUtils {
    static async createTextureOptionsFromBlob(blob: Blob, gameName: string): Promise<GameBoxTextureOptions> {
        return new Promise((resolve, reject) => {
            const img = document.createElement('img') as HTMLImageElement
            img.onload = () => {
                try {
                    const canvas = document.createElement('canvas')
                    const ctx = canvas.getContext('2d')

                    if (!ctx) {
                        console.error(`Γ¥î Could not create canvas context for ${gameName}`)
                        reject(new Error('Could not create canvas context'))
                        return
                    }

                    const maxSize = 512
                    const scale = Math.min(maxSize / img.width, maxSize / img.height, 1)
                    canvas.width = Math.floor(img.width * scale)
                    canvas.height = Math.floor(img.height * scale)

                    ctx.drawImage(img, 0, 0, canvas.width, canvas.height)

                    const texture = new THREE.CanvasTexture(canvas)
                    texture.needsUpdate = true

                    resolve({
                        artworkBlobs: { 'header': blob },
                        preferredArtworkType: 'header'
                    })

                    URL.revokeObjectURL(img.src)
                } catch (error) {
                    console.error(`Γ¥î Error processing image for ${gameName}:`, error)
                    reject(error)
                    URL.revokeObjectURL(img.src)
                }
            }

            img.onerror = (event) => {
                console.error(`Γ¥î Failed to load image for ${gameName}:`, event)
                reject(new Error(`Failed to load image for ${gameName}`))
                URL.revokeObjectURL(img.src)
            }

            img.src = URL.createObjectURL(blob)
        })
    }
}

