describe('GameBoxUtils.calculateGameRotation', () => {
    // Convention: game box artwork is on the -Z face of the model.
    // Arc shelves have rotationY = atan2(x,z)+PI so their +Z front faces inward (toward origin).
    // Front side: totalY = shelfRotationY + PI so -Z artwork faces player.
    // Back side:  totalY = shelfRotationY     so -Z artwork faces outward (away from player).

    it('front side with no shelf rotation applies PI flip so artwork (-Z) faces +Z (toward player at origin)', () => {
        const q = GameBoxUtils.calculateGameRotation(0, ShelfSide.Front)
        // totalY = PI: sin(PI/2)=1, cos(PI/2)=0
        expect(q.y).toBeCloseTo(Math.sin(Math.PI / 2), 2)
        expect(q.w).toBeCloseTo(Math.cos(Math.PI / 2), 2)
    })

    it('back side with no shelf rotation returns near-identity so -Z artwork faces away from player', () => {
        const q = GameBoxUtils.calculateGameRotation(0, ShelfSide.Back)
        expect(q.x).toBeCloseTo(0); expect(q.y).toBeCloseTo(0)
        expect(q.z).toBeCloseTo(0); expect(q.w).toBeCloseTo(1)
    })

    it('front side combines shelf rotation with PI flip', () => {
        const rotY = Math.PI / 3
        const totalY = rotY + Math.PI
        const q = GameBoxUtils.calculateGameRotation(rotY, ShelfSide.Front)
        expect(q.y).toBeCloseTo(Math.sin(totalY / 2), 3)
        expect(q.w).toBeCloseTo(Math.cos(totalY / 2), 3)
    })

    it('back side uses shelf rotation only (no extra flip)', () => {
        const rotY = Math.PI / 4
        const q = GameBoxUtils.calculateGameRotation(rotY, ShelfSide.Back)
        expect(q.y).toBeCloseTo(Math.sin(rotY / 2), 3)
        expect(q.w).toBeCloseTo(Math.cos(rotY / 2), 3)
    })

    it('front and back produce different rotations for the same shelf', () => {
        const rotY = Math.PI / 3
        const qFront = GameBoxUtils.calculateGameRotation(rotY, ShelfSide.Front)
        const qBack = GameBoxUtils.calculateGameRotation(rotY, ShelfSide.Back)
        expect(qFront.y).not.toBeCloseTo(qBack.y, 3)
    })
})

import * as THREE from 'three'
import type { SteamGameData } from '../../game-box/types/GameData'
import type { GameBoxDimensions } from '../../game-box/types/GameBoxOptions'
import { ShelfSide, type ShelfSurface } from './SharedPropsTypes'

// TD: approximated-placement-tripwire
// NOTE: Game positions are approximated from DEFAULT_SHELF_CONFIG (width, shelfCount, etc.).
// If shelf GLTF geometry changes, update GameBoxUtils.calculateGamePositions or
// run `test/unit/scene/placement-tripwire.test.ts` to validate positions don't
// float outside the modeled shelf. This is a deliberate tripwire to catch model-sync regressions.
export const GameLayoutConstants = {
    // Games per shelf board surface (front or back).
    // Intentionally low ΓÇö readability over density. With 800 games, layout and FOV
    // constrain what's visible; we don't want to cram the shelves.
    GAMES_PER_SURFACE: 3,
    // Number of shelf board surfaces per shelf unit (3 boards ├ù front+back = 6).
    SURFACES_PER_SHELF: 6,
    // Spacing between game box centers. Box width is 0.3m.
    // 0.55m gives comfortable spacing at VR scale ΓÇö readable from player distance.
    GAME_SPACING: 0.55
} as const

/** Shelf construction constant - 6┬░ backward tilt for stability */
const SHELF_ANGLE_DEGREES = 6

export class GameBoxUtils {
    static generateGameBoxName(game: SteamGameData, side: ShelfSide, index: number, rendererType: 'gpu' | 'legacy'): string {
        const safeName = game.name?.replace(/[^a-zA-Z0-9]/g, '-') ?? 'unknown'
        return `${rendererType}-game-${safeName}-${side}-${index}`
    }

    static calculateGamePositions(
        shelfPosition: THREE.Vector3,
        surface: ShelfSurface,
        games: SteamGameData[],
        side: ShelfSide,
        boxDimensions: GameBoxDimensions,
        shelfRotationY: number = 0
    ): THREE.Vector3[] {
        const positions: THREE.Vector3[] = []

        const gameY = shelfPosition.y + surface.topY + boxDimensions.height / 2

        const shelfAngleRad = (SHELF_ANGLE_DEGREES * Math.PI) / 180

        const heightFromBottom = surface.topY
        const angleOffset = heightFromBottom * Math.tan(shelfAngleRad)

        const gameHalfDepth = boxDimensions.depth / 2

        const localZ = (side === ShelfSide.Front
            ? surface.frontZ + (gameHalfDepth * 3)
            : surface.backZ - (gameHalfDepth * 3))
        const localZWithAngle = localZ + (side === ShelfSide.Front ? angleOffset : -angleOffset)

        const totalWidth = (games.length - 1) * GameLayoutConstants.GAME_SPACING
        // Center games on surface. If the span exceeds shelf width, the games will overflow
        // the shelf edge ΓÇö the spawner should limit GAMES_PER_SURFACE to prevent this.
        // TODO(approx-geometry): clamp based on actual shelf geometry once dynamic surfaces are used.
        const startLocalX = surface.centerX - totalWidth / 2

        const hasRotation = Math.abs(shelfRotationY) > 1e-6
        const shelfQuat = hasRotation
            ? new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), shelfRotationY)
            : null

        for (let i = 0; i < games.length; i++) {
            const localX = startLocalX + (i * GameLayoutConstants.GAME_SPACING)

            if (shelfQuat) {
                const rotated = new THREE.Vector3(localX, 0, localZWithAngle).applyQuaternion(shelfQuat)
                positions.push(new THREE.Vector3(
                    shelfPosition.x + rotated.x,
                    gameY,
                    shelfPosition.z + rotated.z
                ))
            } else {
                positions.push(new THREE.Vector3(
                    shelfPosition.x + localX,
                    gameY,
                    shelfPosition.z + localZWithAngle
                ))
            }
        }

        return positions
    }

    /**
     * Calculate world-space quaternion for a game box given shelf orientation and side.
     *
     * Convention: game box artwork is on the -Z face of the model.
     * Arc shelves have rotationY = atan2(x,z) + PI so their +Z front faces inward (toward origin).
     * For the game artwork (-Z face) to face the player, we need rotationY + PI on the front side.
     * For the back side, rotationY alone points the -Z artwork face outward.
     *
     * Front: totalY = shelfRotationY + PI
     * Back:  totalY = shelfRotationY  (no extra flip - already facing outward)
     */
    static calculateGameRotation(shelfRotationY: number, side: ShelfSide): THREE.Quaternion {
        const frontFlip = side === ShelfSide.Front ? Math.PI : 0
        const totalY = shelfRotationY + frontFlip
        return new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), totalY)
    }
}

export class ShelfCalculationUtils {
    static calculateShelfY(
        shelfLevel: number,
        height: number,
        shelfCount: number,
        verticalOffset: number = 0
    ): number {
        const shelfSpacing = height / (shelfCount + 1)
        return shelfLevel * shelfSpacing + verticalOffset
    }

    static calculateAllShelfYPositions(config: {
        height: number
        shelfCount: number
        shelfVerticalOffset?: number
    }): number[] {
        const positions: number[] = []
        for (let i = 1; i <= config.shelfCount; i++) {
            positions.push(ShelfCalculationUtils.calculateShelfY(
                i,
                config.height,
                config.shelfCount,
                config.shelfVerticalOffset ?? 0
            ))
        }
        return positions
    }

    static calculateShelfDepthAndOffset(
        shelfLevel: number,
        config: {
            depth: number
            boardThickness: number
            shelfCount: number
            shelfExtensionPerLevel: number
        }
    ): { shelfDepth: number; forwardOffset: number } {
        const middleShelf = (config.shelfCount + 1) / 2
        const baseExtension = config.shelfExtensionPerLevel
        const graduatedExtension = (middleShelf - shelfLevel) * (config.shelfExtensionPerLevel * 0.64)
        const totalExtension = baseExtension + graduatedExtension

        const shelfDepth = (config.depth * 2) - config.boardThickness * 2 + totalExtension
        const forwardOffset = 0

        return { shelfDepth, forwardOffset }
    }
}

