import * as THREE from 'three'
import { ShelfCalculationUtils } from './ShelfCalculations'
import { DEFAULT_SHELF_CONFIG, type ShelfSurface } from './SharedPropsTypes'

export class ShelfSurfaceUtils {
    static findShelfSurfaces(shelfUnit: THREE.Group | null, useHardcodedSurfaces: boolean = false, shelfPosition?: THREE.Vector3): ShelfSurface[] {
        if (useHardcodedSurfaces || !shelfUnit) {
            return ShelfSurfaceUtils.getStandardShelfSurfaces()
        }

        return ShelfSurfaceUtils.findDynamicShelfSurfaces(shelfUnit, shelfPosition)
    }

    private static getStandardShelfSurfaces(): ShelfSurface[] {
        const config = DEFAULT_SHELF_CONFIG
        const surfaces: ShelfSurface[] = []

        const shelfYPositions = ShelfCalculationUtils.calculateAllShelfYPositions({
            height: config.height,
            shelfCount: config.shelfCount,
            shelfVerticalOffset: config.shelfVerticalOffset
        })

        shelfYPositions.forEach(shelfY => {
            surfaces.push({
                topY: shelfY + config.boardThickness * 0.55,
                frontZ: -0.5,
                backZ: 0.5,
                centerX: 0,
                width: config.width
            })
        })

        // Sort top-to-bottom: partially-filled shelves fill from eye level down
        return surfaces.sort((a, b) => b.topY - a.topY)
    }

    private static findDynamicShelfSurfaces(shelfUnit: THREE.Group, shelfPosition?: THREE.Vector3): ShelfSurface[] {
        const surfaces: ShelfSurface[] = []

        shelfUnit.traverse((child) => {
            if (child instanceof THREE.Mesh && child.geometry instanceof THREE.BoxGeometry) {
                const box = new THREE.Box3().setFromObject(child)
                const size = box.getSize(new THREE.Vector3())

                if (size.x > 1.5 && size.y < 0.1 && size.z > 0.3) {
                    const relativeTopY = shelfPosition ? box.max.y - shelfPosition.y : box.max.y

                    surfaces.push({
                        topY: relativeTopY,
                        frontZ: box.min.z,
                        backZ: box.max.z,
                        centerX: (box.min.x + box.max.x) / 2,
                        width: size.x
                    })
                }
            }
        })

        const uniqueSurfaces = surfaces.filter((surface, index, array) => {
            return index === 0 || Math.abs(surface.topY - array[index - 1].topY) > 0.02
        })

        return uniqueSurfaces.sort((a, b) => b.topY - a.topY)
    }
}

import { RoomConstants } from '../../RoomManager'

export class VRLayoutUtils {
    static calculateOptimalShelfSpacing(shelfCount: number): number {
        const baseSpacing = RoomConstants.SHELF_SPACING_X
        const minSpacing = 2.0
        const maxSpacing = 3.5

        if (shelfCount <= 2) {
            return Math.min(maxSpacing, baseSpacing * 1.2)
        } else if (shelfCount >= 6) {
            return Math.max(minSpacing, baseSpacing * 0.9)
        } else {
            return baseSpacing
        }
    }

    static calculateOptimalRowPosition(rowIndex: number): number {
        const baseRowSpacing = RoomConstants.SHELF_SPACING_Z

        // Position shelves starting behind player (negative Z) going further back
        // Player and entrance mat are at origin, shelves start at -ENTRANCE_CLEARANCE
        const entranceClearance = RoomConstants.STORE_ENTRANCE_CLEARANCE
        const startZ = -entranceClearance - baseRowSpacing // First shelf row behind entrance area
        const rowZ = startZ - (rowIndex * baseRowSpacing) // Each row goes further back

        return rowZ
    }
}

/**
 * Shelf layout integration test
 *
 * Simulates the arc layout -> shelf creation -> game placement pipeline with a
 * realistic game count matching production (47 batches). Verifies:
 *   - Every shelf gets a position and correct rotation from its arc row
 *   - rowIndex uses stored arc row, not batchIndex/maxPerRow grid formula
 *   - Game boxes placed on arc shelves face the player (Three.js BoxGeometry front is +Z;
 *     after shelf rotation, +Z should point toward origin)
 *   - Back-wall row (row 4) is correctly identified for backside suppression
 *
 * Heavier than unit tests -- use yarn vitest run with explicit path or yarn test:integration.
 * @tag integration
 */

import { describe, it, expect } from 'vitest'
import * as THREE from 'three'
import { computeArcShelfLayout } from '../scene/props/shared/ArcLayoutUtils'
import { GameBoxUtils } from '../scene/props/shared/GameBoxUtils'
import { ShelfSide } from '../scene/props/shared/SharedPropsTypes'

// Match production config exactly
const TOTAL_BATCHES = 47
const FIXED_ROWS = 4 + 6 + 10 + 12  // 32

const ARC_CONFIG = {
    rows: 5,
    shelvesPerRow: 10,
    shelvesPerRowByRow: [4, 6, 10, 12, Math.max(1, TOTAL_BATCHES - FIXED_ROWS)],
    halfAngle: Math.PI / 3,
    halfAngleByRow: [
        Math.PI / 3,
        Math.PI / 3.5,
        Math.PI / 3,
        Math.PI / 3,
        Math.PI / 2.6,
    ],
    minShelfGap: 1.0,
    shelfWidthMetres: 2.0,
    rowRadiusStep: 4.0,
    firstRowRadius: 5.5,
}

const BOX_DIMS = { width: 0.2, height: 0.3, depth: 0.1 }
const MAX_PER_ROW = 4  // matches GpuStorePropsRenderer.maxShelvesPerRow

describe('arc shelf layout integration', () => {
    const shelves = computeArcShelfLayout(TOTAL_BATCHES, ARC_CONFIG)

    it('allocates exactly one slot per batch', () => {
        expect(shelves.length).toBe(TOTAL_BATCHES)
    })

    it('shelf positions are all in the -Z half-space (in front of player)', () => {
        shelves.forEach((s, i) => {
            expect(s.position.z, `shelf ${i} should be at negative Z`).toBeLessThan(0)
        })
    })

    it('each shelf rotation Y points its front face (+Z) toward player at origin', () => {
        // Three.js BoxGeometry front face is +Z in local space.
        // rotationY in ArcLayoutUtils = atan2(x, z) + PI so that +Z rotated faces inward.
        shelves.forEach((s, i) => {
            const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), s.rotationY)
            const front = new THREE.Vector3(0, 0, 1).applyQuaternion(q)  // +Z front face
            const toOrigin = new THREE.Vector3(-s.position.x, 0, -s.position.z).normalize()
            const dot = front.dot(toOrigin)
            expect(dot, `shelf ${i} (row ${s.row}, rotY=${s.rotationY.toFixed(2)}) +Z front should face origin`).toBeGreaterThan(0.99)
        })
    })

    it('stored arc rowIndex differs from grid formula for middle rows', () => {
        // Documents that GpuStorePropsRenderer must use shelfRowIndices[], not Math.floor(batchIndex/4)
        const mismatches = shelves.filter((s, i) => Math.floor(i / MAX_PER_ROW) !== s.row)
        expect(mismatches.length).toBeGreaterThan(0)
    })

    it('game box rotation for front side faces player at all arc angles', () => {
        // calculateGameRotation(rotY, Front) applies rotY only.
        // Since shelf front is +Z and game front is -Z (artwork face), adding PI for back flip:
        // front game: same rotation as shelf -> -Z game front should face same direction as shelf +Z front
        // Actually: game box model has artwork on -Z face. rotationY = shelf rotation.
        // After rotation, game -Z face points same direction as shelf +Z = toward origin. Check dot > 0.9.
        shelves.forEach((s, i) => {
            const rotation = GameBoxUtils.calculateGameRotation(s.rotationY, ShelfSide.Front)
            const gameFront = new THREE.Vector3(0, 0, -1).applyQuaternion(rotation)
            const toOrigin = new THREE.Vector3(-s.position.x, 0, -s.position.z).normalize()
            const dot = gameFront.dot(toOrigin)
            expect(dot, `game at shelf ${i} (row ${s.row}, rotY=${s.rotationY.toFixed(2)}) -Z artwork face should face player`).toBeGreaterThan(0.99)
        })
    })

    it('back-side game rotation is opposite to front-side rotation for inner rows', () => {
        shelves.filter(s => s.row < 4).forEach((s, i) => {
            const front = GameBoxUtils.calculateGameRotation(s.rotationY, ShelfSide.Front)
            const back = GameBoxUtils.calculateGameRotation(s.rotationY, ShelfSide.Back)
            const frontVec = new THREE.Vector3(0, 0, -1).applyQuaternion(front)
            const backVec = new THREE.Vector3(0, 0, -1).applyQuaternion(back)
            const dot = frontVec.dot(backVec)
            expect(dot, `inner shelf ${i} (row ${s.row}) front/back artwork faces should be opposite`).toBeLessThan(-0.99)
        })
    })

    it('back-wall row (row 4) shelves are all identified with row===4', () => {
        const backWall = shelves.filter(s => s.row === 4)
        expect(backWall.length).toBe(15)  // TOTAL_BATCHES - FIXED_ROWS = 47 - 32
        backWall.forEach(s => expect(s.row).toBe(4))
    })

    it('game positions are all finite for front side on all arc shelves', () => {
        const surface = { topY: 0.5, frontZ: 0.3, backZ: -0.3, centerX: 0, width: 2.0 }
        const game = { appid: 1, name: 'Test', playtime_forever: 0 } as never

        shelves.forEach((s, i) => {
            const [pos] = GameBoxUtils.calculateGamePositions(s.position, surface, [game], ShelfSide.Front, BOX_DIMS, s.rotationY)
            expect(isFinite(pos.x), `game at shelf ${i} x must be finite`).toBe(true)
            expect(isFinite(pos.z), `game at shelf ${i} z must be finite`).toBe(true)
        })
    })

    it('row distribution matches expected [4, 6, 10, 12, 15]', () => {
        const counts = [0, 0, 0, 0, 0]
        shelves.forEach(s => counts[s.row]++)
        expect(counts).toEqual([4, 6, 10, 12, 15])
    })
})

import * as THREE from 'three'
import { EventManager } from '../../core/EventManager'
import { Logger } from '../../utils/Logger'
import {
    StorePropsEventTypes,
    GameEventTypes,
    type BatchReadyForPlacementEvent,
    type ShelfReadyEvent,
    type ShelfLayoutDeterminedEvent,
    type StorePropsProgressEvent,
} from '../../types/InteractionEvents'
import { computeArcShelfLayout, type ArcLayoutConfig, type ArcShelfInfo } from '../props/shared/ArcLayoutUtils'

/**
 * ShelfLayoutCoordinator
 *
 * Listens to the first BatchReadyForPlacement event. Uses totalBatches (known
 * immediately) to compute the full arc shelf layout without waiting for game
 * content or sort. Emits:
 *   - ShelfLayoutDetermined  once, with shelfBounds for room/lighting systems
 *   - ShelfReady             one per shelf, with position + rotationY
 *
 * NOTE: ShelfReady is emitted once per BatchReadyForPlacement ΓÇö progressively
 * as batches arrive. This means 40+ events can fire back-to-back on load.
 * A future ShelfLayoutBatch event could coalesce these if consumers need it.
 *
 * Current assumption: 1 batch Γëê 1 shelf. This holds while shelves have a
 * uniform game-slot count. Wall shelves or variable-capacity shelves will
 * need a separate mapping from batch count ΓåÆ shelf count.
 *
 * Knows nothing about games, GPU, or rendering. Pure layout authority.
 */
export class ShelfLayoutCoordinator {
    private static readonly logger = Logger.createLogFunctions(ShelfLayoutCoordinator.name)

    private static readonly FIXED_ROWS_COUNT = 4 + 6 + 10 + 12 // 32 ΓÇö rows 0ΓÇô3 with fixed counts

    /** Current assumption: totalBatches maps 1:1 to shelves. See class doc. */

    private layoutComputed = false
    private shelvesByBatch = new Map<number, { position: THREE.Vector3; rotationY: number; row: number; indexInRow: number }>()
    private emittedShelfIds = new Set<number>()
    private totalShelves = 0

    constructor() {
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.BatchReadyForPlacement,
            (event: CustomEvent<BatchReadyForPlacementEvent>) => this.handleFirstBatch(event.detail)
        )
        ShelfLayoutCoordinator.logger.debug('Subscribed to BatchReadyForPlacement')
    }

    public dispose(): void {
        this.layoutComputed = false
        this.shelvesByBatch.clear()
        this.emittedShelfIds.clear()
        this.totalShelves = 0
    }

    private handleFirstBatch(detail: BatchReadyForPlacementEvent): void {
        if (!this.layoutComputed) {
            this.layoutComputed = true
            this.totalShelves = detail.totalBatches

            if (this.totalShelves === 0) {
                ShelfLayoutCoordinator.logger.warn('totalBatches is 0 ΓÇö no shelves to lay out')
                return
            }

            ShelfLayoutCoordinator.logger.debug(`Computing arc layout for ${this.totalShelves} shelves`)
            this.computeLayout(this.totalShelves)
        }

        this.emitShelfForBatch(detail.batchIndex)
    }

    private computeLayout(totalShelves: number): void {
        const arcConfig: ArcLayoutConfig = {
            // Only override where we need non-default values; ArcLayoutUtils.DEFAULTS handle the rest.
            shelvesPerRowByRow: [
                4,
                6,
                10,
                12,
                Math.max(1, totalShelves - ShelfLayoutCoordinator.FIXED_ROWS_COUNT),
            ],
            halfAngleByRow: [
                Math.PI / 3.5,
                Math.PI / 3.5,
                Math.PI / 3,
                Math.PI / 3,
                Math.PI / 2.6,
            ],
            minShelfGap: 1.0,
            rowRadiusStep: 4.0,
            firstRowRadius: 5.5,
        }

        const shelves = computeArcShelfLayout(totalShelves, arcConfig)

        // Compute spatial bounds for room/lighting systems
        const bounds = { minX: Infinity, maxX: -Infinity, minZ: Infinity, maxZ: -Infinity }
        // Use shelf width/depth from ArcLayoutUtils defaults rather than duplicating them here
        const hw = 2.0 / 2  // default shelfWidthMetres / 2
        const hd = 1.0 / 2  // default shelfDepth / 2
        for (const s of shelves) {
            bounds.minX = Math.min(bounds.minX, s.position.x - hw)
            bounds.maxX = Math.max(bounds.maxX, s.position.x + hw)
            bounds.minZ = Math.min(bounds.minZ, s.position.z - hd)
            bounds.maxZ = Math.max(bounds.maxZ, s.position.z + hd)
        }

        EventManager.getInstance().emit<ShelfLayoutDeterminedEvent>(
            GameEventTypes.ShelfLayoutDetermined,
            {
                shelfBounds: bounds,
                shelfLayout: {
                    rows: (shelves[shelves.length - 1]?.row ?? 0) + 1,
                    // shelvesPerRow omitted ΓÇö it varies by row; consumers should not rely on it
                },
            }
        )

        this.shelvesByBatch.clear()
        for (let i = 0; i < shelves.length; i++) {
            const s: ArcShelfInfo = shelves[i]
            this.shelvesByBatch.set(i, {
                position: s.position.clone(),
                rotationY: s.rotationY,
                row: s.row,
                indexInRow: s.indexInRow,
            })
        }

        ShelfLayoutCoordinator.logger.debug(`Layout determined for ${shelves.length} shelves`) 
    }

    private emitShelfForBatch(batchIndex: number): void {
        if (this.emittedShelfIds.has(batchIndex)) return

        const shelf = this.shelvesByBatch.get(batchIndex)
        if (!shelf) {
            ShelfLayoutCoordinator.logger.warn(`No shelf layout found for batch ${batchIndex}`)
            return
        }

        this.emittedShelfIds.add(batchIndex)

        // Emit progress synchronously so the progress bar updates immediately.
        EventManager.getInstance().emit<StorePropsProgressEvent>(StorePropsEventTypes.Progress, {
            step: 'shelves',
            current: batchIndex + 1,
            total: this.totalShelves,
            detail: `Placing shelf ${batchIndex + 1}`,
        })

        // Defer ShelfReady to the next microtask.
        // ShelfReady fires inside the BatchReadyForPlacement dispatch;
        // GameBoxSpawner's BatchReadyForPlacement handler hasn't run yet at that point.
        // queueMicrotask ensures all BatchReadyForPlacement handlers complete first,
        // so GameBoxSpawner has stored the pending games before ShelfReady arrives.
        queueMicrotask(() => {
            EventManager.getInstance().emit<ShelfReadyEvent>(
                StorePropsEventTypes.ShelfReady,
                {
                    batchIndex,
                    position: shelf.position.clone(),
                    rotationY: shelf.rotationY,
                }
            )
        })
    }
}

/**
 * TimeBucketSignHelpers
 *
 * Pure utility functions for time-bucket sign placement decisions and anchor
 * generation. Extracted from SceneSignManager to keep the manager as
 * orchestration + object lifecycle only.
 *
 * These helpers are stateless: all required context is passed in as arguments.
 * They can be unit-tested without a scene or EventManager.
 */

import * as THREE from 'three'
import { RecentlyPlayedBucket, getRecentlyPlayedBucket, getBucketLabel } from '../categorization/GameSorter'
import type { SteamGameData } from '../game-box/types/GameData'
import { RoomConstants } from '../RoomManager'

/** Number of games packed onto a single shelf unit. */
export const SHELF_BATCH_SIZE = 18

/**
 * Determine which time bucket corresponds to the first game on a given shelf
 * (identified by batch index). Returns null if the shelf index is out of range.
 * Unplayed is a valid return value ΓÇö it represents the final "Never Played" section.
 */
export function shelfBucket(
    shelfId: number,
    sortedGames: ReadonlyArray<Readonly<SteamGameData>>
): RecentlyPlayedBucket | null {
    const firstGameIndex = shelfId * SHELF_BATCH_SIZE
    if (firstGameIndex >= sortedGames.length) return null

    return getRecentlyPlayedBucket(sortedGames[firstGameIndex] as SteamGameData)
}

/**
 * Determine whether a time-bucket sign should be placed at this shelf.
 *
 * A sign is placed when:
 * - The shelf has a non-null bucket (see shelfBucket)
 * - The bucket differs from the last placed bucket (transition boundary)
 * - The sign anchor doesn't collide with the ceiling sign anchor
 */
export function shouldPlaceBucketSign(
    bucket: RecentlyPlayedBucket | null,
    lastPlacedBucket: RecentlyPlayedBucket | null,
    shelfPosition: THREE.Vector3,
    ceilingSignAnchor: THREE.Vector3,
    collisionRadius = 1.5
): boolean {
    if (bucket === null) return false
    if (bucket === lastPlacedBucket) return false

    const signAnchor = bucketSignAnchor(shelfPosition)
    if (ceilingSignAnchor.distanceTo(signAnchor) <= collisionRadius) return false

    return true
}

/**
 * Compute the world-space anchor position for a time-bucket sign above a shelf.
 * The sign floats slightly above the default shelf-sign height (extra 0.02 m headroom).
 */
export function bucketSignAnchor(shelfPosition: THREE.Vector3): THREE.Vector3 {
    return new THREE.Vector3(
        shelfPosition.x,
        shelfPosition.y + 2.0 + 0.02,
        shelfPosition.z
    )
}

/**
 * Compute the world-space anchor for the ceiling "Recently Played" feature sign.
 * Kept here so both SceneSignManager and any future tests use the same source of truth.
 */
export function recentlyPlayedCeilingAnchor(): THREE.Vector3 {
    return new THREE.Vector3(0, RoomConstants.STORE_CEILING_HEIGHT - 0.5, -6.4)
}

/**
 * Return the display label for a bucket.
 * Unplayed maps to "Never Played" (final section in a recency sort).
 */
export function bucketDisplayLabel(bucket: RecentlyPlayedBucket): string {
    if (bucket === RecentlyPlayedBucket.Unplayed) return 'Never Played'
    return getBucketLabel(bucket)
}

import { describe, it, expect } from 'vitest'
import * as THREE from 'three'
import { computeArcShelfLayout } from '../props/shared/ArcLayoutUtils'

/**
 * Regression: arc rowIndex must be taken from ArcShelfInfo.row, not derived from
 * Math.floor(batchIndex / maxShelvesPerRow).
 *
 * With arc layout rows = [4, 6, 10, 12, 15], maxShelvesPerRow = 4:
 *   batchIndex 8 = row 1 shelf 4 (arc row 1)
 *   Math.floor(8 / 4) = 2  ΓåÉ WRONG
 *
 * Consequence: wrong rowIndex fed to back-side suppression logic in GameBoxSpawner.
 * Shelves in rows 1-3 get wrong backside treatment (some suppressed, some not).
 *
 * Fix: GpuStorePropsRenderer stores shelfRowIndices[] from ArcShelfInfo.row
 * and uses that instead of the grid formula.
 */
describe('Arc shelf rowIndex derivation', () => {
    const FIXED = 4 + 6 + 10 + 12
    const TOTAL = 47
    const shelves = computeArcShelfLayout(TOTAL, {
        rows: 5,
        shelvesPerRow: 10,
        shelvesPerRowByRow: [4, 6, 10, 12, Math.max(1, TOTAL - FIXED)],
        halfAngle: Math.PI / 3,
        halfAngleByRow: [
            Math.PI / 3, Math.PI / 3.5,
            Math.PI / 3, Math.PI / 3,
            Math.PI / 2.6,
        ],
        minShelfGap: 1.0, shelfWidthMetres: 2.0,
        rowRadiusStep: 4.0, firstRowRadius: 5.5,
    })
    const MAX_PER_ROW = 4  // matches GpuStorePropsRenderer.maxShelvesPerRow

    it('arc row counts match expected distribution [4, 6, 10, 12, 15]', () => {
        const counts = [0, 0, 0, 0, 0]
        shelves.forEach(s => counts[s.row]++)
        expect(counts).toEqual([4, 6, 10, 12, 15])
    })

    it('stored row indices differ from grid formula for rows 1-3', () => {
        // Rows 1+ have more than maxShelvesPerRow shelves, so the grid formula diverges
        const mismatches: number[] = []
        shelves.forEach((s, batchIndex) => {
            const gridRow = Math.floor(batchIndex / MAX_PER_ROW)
            if (gridRow !== s.row) mismatches.push(batchIndex)
        })
        // There MUST be mismatches - if there are none, the grid formula happens to be correct
        // and the regression fix is unnecessary. This test documents that it IS necessary.
        expect(mismatches.length).toBeGreaterThan(0)
    })

    it('using stored row index, back-wall row (4) is correctly identified for all its shelves', () => {
        const backWallShelves = shelves.filter(s => s.row === 4)
        expect(backWallShelves.length).toBe(15)
        // All back-wall shelves should be identified as row 4, not row 2-3
        backWallShelves.forEach((s, i) => {
            expect(s.row, `back-wall shelf ${i} should have row=4`).toBe(4)
        })
    })

    it('using stored row index, rows 0-3 are correctly identified and allow backside content', () => {
        const innerShelves = shelves.filter(s => s.row < 4)
        expect(innerShelves.length).toBe(32)
        innerShelves.forEach((s, i) => {
            // allowBackSide = rowIndex < 4
            const allowBackSide = s.row < 4
            expect(allowBackSide, `inner shelf ${i} (row ${s.row}) should allow backside`).toBe(true)
        })
    })

    it('grid formula incorrectly classifies some row-1 shelves as row-2', () => {
        // Row 1 contains batches 4-9 (6 shelves). Grid formula: Math.floor(8/4)=2, Math.floor(9/4)=2
        // Those shelves would get rowIndex=2 with grid formula, but are actually row 1
        const row1Batches = shelves
            .map((s, idx) => ({ s, idx }))
            .filter(({ s }) => s.row === 1)
        const wronglyClassified = row1Batches.filter(({ idx }) => Math.floor(idx / MAX_PER_ROW) !== 1)
        expect(wronglyClassified.length).toBeGreaterThan(0)
    })
})

import * as THREE from 'three'
import type { SteamGameData } from '../game-box/types/GameData'
import { ShelfSurfaceUtils, type ShelfSurface, ShelfSide, GameBoxUtils, GameLayoutConstants } from '../props/SharedPropsUtils'
import { EventManager } from '../../core/EventManager'
import { 
    BatchProcessingStatus,
    StorePropsEventTypes, 
    type BatchReadyForPlacementEvent,
    type ShelfReadyEvent,
    type GamesPlacedEvent,
    type GameBoxSpawnedEvent
} from '../../types/InteractionEvents'
import { Logger } from '../../utils/Logger'

/**
 * GameBoxSpawner
 *
 * Responsible for spawning game boxes on shelves using the instanced renderer.
 * Event-driven flow:
 * - Observes BatchReadyForPlacement ΓåÆ stores games as pending
 * - Observes ShelfReady ΓåÆ places stored games on shelf, emits GamesPlaced
 *
 * Category assignment is NOT this class's responsibility. Signs are placed
 * by ShelfSectionPlanner after all batches complete.
 */
export class GameBoxSpawner {
    private static logger = Logger.createLogFunctions(GameBoxSpawner.name)
    private pendingGames: Map<number, readonly SteamGameData[]> = new Map()

    constructor() {
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.BatchReadyForPlacement,
            this.handleBatchReadyForPlacement.bind(this)
        )
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.ShelfReady,
            this.handleShelfReady.bind(this)
        )
        GameBoxSpawner.logger.debug('Registered listeners for BatchReadyForPlacement and ShelfReady events')
    }

    private handleBatchReadyForPlacement(event: CustomEvent<BatchReadyForPlacementEvent>): void {
        const { games, batchIndex, totalBatches } = event.detail

        GameBoxSpawner.logger.debug(
            `[EVENT PATH] BatchReadyForPlacement received: batch ${batchIndex + 1}/${totalBatches}, ${games.length} games ΓÇö stored as pending`
        )

        this.pendingGames.set(batchIndex, games)
    }

    private handleShelfReady(event: CustomEvent<ShelfReadyEvent>): void {
        const { position, batchIndex, rotationY } = event.detail

        GameBoxSpawner.logger.debug(
            `[EVENT PATH] ShelfReady received for batch ${batchIndex + 1}. ` +
            `Spawning games at (${position.x.toFixed(1)}, ${position.y.toFixed(1)}, ${position.z.toFixed(1)})`
        )

        const games = this.pendingGames.get(batchIndex)
        if (!games) {
            GameBoxSpawner.logger.warn(`No pending games found for batch ${batchIndex}`)
            EventManager.getInstance().emit<GamesPlacedEvent>(
                StorePropsEventTypes.GamesPlaced,
                { batchIndex, status: BatchProcessingStatus.Failed }
            )
            return
        }

        this.spawnGamesOnShelf(position, games, rotationY)
        this.pendingGames.delete(batchIndex)

        EventManager.getInstance().emit<GamesPlacedEvent>(
            StorePropsEventTypes.GamesPlaced,
            { batchIndex, status: BatchProcessingStatus.GamesPlaced }
        )
        GameBoxSpawner.logger.debug(`[EVENT PATH] Spawned ${games.length} games, emitted GamesPlaced for batch ${batchIndex + 1}`)
    }

    spawnGamesOnShelf(
        shelfPosition: THREE.Vector3,
        games: readonly SteamGameData[],
        shelfRotationY: number = 0
    ): void {
        const shelfSurfaces = ShelfSurfaceUtils.findShelfSurfaces(null, true)
        if (shelfSurfaces.length === 0) return

        // ShelfSide.Front = far face (-localZ), ShelfSide.Back = near/player-facing face (+localZ).
        // Names are counterintuitive for arc shelves ΓÇö rename deferred.
        let gameIndex = 0
        for (const surface of shelfSurfaces) {
            if (gameIndex >= games.length) break
            const nearGames = games.slice(gameIndex, gameIndex + GameLayoutConstants.GAMES_PER_SURFACE)
            if (nearGames.length > 0) {
                this.createGameBoxes(shelfPosition, surface, nearGames, ShelfSide.Back, shelfRotationY)
                gameIndex += nearGames.length
            }
            if (gameIndex < games.length) {
                const farGames = games.slice(gameIndex, gameIndex + GameLayoutConstants.GAMES_PER_SURFACE)
                if (farGames.length > 0) {
                    this.createGameBoxes(shelfPosition, surface, farGames, ShelfSide.Front, shelfRotationY)
                    gameIndex += farGames.length
                }
            }
        }
    }

    private createGameBoxes(
        shelfPosition: THREE.Vector3,
        surface: ShelfSurface,
        games: readonly SteamGameData[],
        side: ShelfSide,
        shelfRotationY: number
    ): void {
        const boxDimensions = { width: 0.3, height: 0.4, depth: 0.08 }
        const gamePositions = GameBoxUtils.calculateGamePositions(
            shelfPosition, surface, games as SteamGameData[], side, boxDimensions, shelfRotationY
        )
        for (let i = 0; i < games.length; i++) {
            this.createSingleGameBox(games[i], gamePositions[i], side, i, shelfRotationY)
        }
    }

    private createSingleGameBox(
        game: SteamGameData,
        worldPosition: THREE.Vector3,
        side: ShelfSide,
        _index: number,
        shelfRotationY: number
    ): void {
        const rotation = GameBoxUtils.calculateGameRotation(shelfRotationY, side)
        EventManager.getInstance().emit<GameBoxSpawnedEvent>(
            StorePropsEventTypes.GameBoxSpawned,
            {
                game,
                position: worldPosition.clone(),
                side,
                rotation,
            }
        )
    }
}

/**
 * Shelf Sticker Handler - Manages sticker lifecycle for shelf rendering
 * 
 * TD: sticker-coordinator
 * This class is a candidate for dissolution into a StickerCoordinator that
 * self-subscribes to StickerSurfaceReady events (emitted per sideboard instance)
 * rather than receiving mesh managers via setManagers(). See tech-debt.md.
 *
 * Coordinates between:
 * - StickerManager (data/placement logic)
 * - ShelfStickerIntegration (shader/GPU attributes)
 * - ShelfUnitIndexSystem (numeric indices)
 * - InstancedMeshManager (sideboard rendering)
 * 
 * Extracted from InstancedShelfRenderer to separate concerns and reduce class complexity.
 */

import { EventManager } from '../../core/EventManager'
import { StorePropsEventTypes, GameEventTypes } from '../../types/InteractionEvents'
import { StickerManager } from './StickerManager'
import { ShelfStickerIntegration } from './ShelfStickerIntegration'
import { ShelfUnitIndexSystem } from './ShelfUnitIndexSystem'
import { AppSettings, Setting } from '../../core/AppSettings'
import type { InstancedMeshManager } from '../instancing/InstancedMeshManager'

// Toggle verbose sticker-system debug logging in this module
const STICKERS_DEBUG = false

export class ShelfStickerHandler {
    private stickerManager: StickerManager | null = null
    private stickerIntegration: ShelfStickerIntegration | null = null
    private indexSystem: ShelfUnitIndexSystem | null = null
    private sideBoardManager?: InstancedMeshManager
    private shelfUnitCount: number = 0

    private isStickersEnabled(): boolean {
        return AppSettings.get(Setting.EnableStickers)
    }

    constructor() {
        if (!this.isStickersEnabled()) {
            if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ Stickers DISABLED - skipping initialization')
            return
        }

        // Initialize sticker system (macro texture mode - no sticker limits)
        this.stickerManager = new StickerManager()
        this.stickerIntegration = new ShelfStickerIntegration({
            stickerManager: this.stickerManager
        })
        this.indexSystem = new ShelfUnitIndexSystem(this.stickerManager)
        this.registerEventListeners()
    }

    public setManagers(sideBoardManager: InstancedMeshManager, shelfUnitCount: number): void {
        this.sideBoardManager = sideBoardManager
        this.shelfUnitCount = shelfUnitCount
    }

    private registerEventListeners(): void {
        // Populate stickers after GPU batch completes
        EventManager.getInstance().registerEventHandler(
            GameEventTypes.SomeBatchesComplete,
            this.populateStickersAfterGeneration.bind(this)
        )

        // Handle shelf index visibility toggles
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.EnableShelfIndices,
            () => {
                if (this.sideBoardManager) {
                    this.enableIndices(this.sideBoardManager, this.shelfUnitCount)
                }
            }
        )
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.DisableShelfIndices,
            () => {
                if (this.sideBoardManager) {
                    this.disableIndices(this.sideBoardManager, this.shelfUnitCount)
                }
            }
        )
    }

    /**
     * Initialize sticker data for a sideboard surface
     * Called when creating left/right sideboards for a shelf unit
     * 
     * Macro texture mode: Use boardIndex directly as shelfId (0-255)
     * This maps each sideboard to a unique tile in the texture atlas
     */
    public initializeSideboardStickers(
        meshManager: InstancedMeshManager,
        boardIndex: number,
        shelfUnitIndex: number,
        isLeftBoard: boolean
    ): void {
        if (!this.isStickersEnabled() || !this.stickerIntegration || !this.indexSystem) return

        // Use boardIndex directly - it's already sequential (0, 1, 2, 3, ...)
        // Each sideboard gets its own tile in the macro texture
        const tileId = boardIndex

        this.stickerIntegration.updateSurfaceStickers(meshManager, boardIndex, tileId)

        // Add index to left board if system is enabled
        if (isLeftBoard && this.indexSystem.isEnabled()) {
            this.indexSystem.addIndexToSideboard(shelfUnitIndex, tileId)
            // Refresh after adding index
            this.stickerIntegration.updateSurfaceStickers(meshManager, boardIndex, tileId)
        }
    }

    /**
     * Populate stickers after shelf generation completes
     * Called via event handler after GPU update
     */
    public populateStickersAfterGeneration(): void {
        if (!this.isStickersEnabled()) return
        if (!this.sideBoardManager) return
        this.populateRandomStickers(this.sideBoardManager, this.shelfUnitCount, 0.3)
    }

    /**
     * Populate random stickers after shelf generation
     * Called via event handler after GPU update
     * 
     * Macro texture mode: Each left sideboard gets sequential tile IDs (0, 2, 4, 6, ...)
     * since left boards are at even indices (0=left, 1=right, 2=left, 3=right, ...)
     */
    public populateRandomStickers(
        meshManager: InstancedMeshManager,
        totalShelfUnits: number,
        density: number = 0.8
    ): void {
        if (!this.isStickersEnabled() || !this.stickerIntegration) return

        // Populate with random stickers on left side boards only
        // Left boards are at even indices: 0, 2, 4, 6, ... (boardIndex = shelfUnitIndex * 2)
        this.stickerIntegration.populateAndRefresh(
            meshManager,
            totalShelfUnits,
            (shelfUnitIndex: number) => shelfUnitIndex * 2,  // Left sideboard tile IDs: 0, 2, 4, 6, ...
            density
        )
    }

    /**
     * Enable shelf unit index display
     */
    public enableIndices(
        meshManager: InstancedMeshManager,
        shelfUnitCount: number
    ): void {
        if (!this.isStickersEnabled() || !this.indexSystem) return
        this.indexSystem.enable()
        this.refreshAllIndices(meshManager, shelfUnitCount)
        if (STICKERS_DEBUG) console.debug('≡ƒöì Shelf unit indices enabled')
    }

    /**
     * Disable shelf unit index display
     */
    public disableIndices(
        meshManager: InstancedMeshManager,
        shelfUnitCount: number
    ): void {
        if (!this.isStickersEnabled() || !this.indexSystem) return
        this.indexSystem.disable()
        this.refreshAllIndices(meshManager, shelfUnitCount)
        if (STICKERS_DEBUG) console.debug('≡ƒöì Shelf unit indices disabled')
    }

    /**
     * Toggle shelf unit index display
     */
    public toggleIndices(
        meshManager: InstancedMeshManager,
        shelfUnitCount: number
    ): void {
        if (!this.isStickersEnabled() || !this.indexSystem) return
        this.indexSystem.toggle()
        this.refreshAllIndices(meshManager, shelfUnitCount)
    }

    /**
     * Refresh indices for all shelf units
     * Macro texture mode: left board for shelf N is at boardIndex N*2
     */
    private refreshAllIndices(
        meshManager: InstancedMeshManager,
        shelfUnitCount: number
    ): void {
        if (!this.stickerManager || !this.stickerIntegration || !this.indexSystem) return

        for (let shelfUnitIndex = 0; shelfUnitIndex < shelfUnitCount; shelfUnitIndex++) {
            const leftBoardIndex = shelfUnitIndex * 2
            const leftTileId = leftBoardIndex

            this.stickerManager!.clearShelf(leftTileId)

            if (this.indexSystem!.isEnabled()) {
                this.indexSystem!.addIndexToSideboard(shelfUnitIndex, leftTileId)
            }

            this.stickerIntegration!.updateSurfaceStickers(meshManager, leftBoardIndex, leftTileId)
        }

        this.stickerIntegration.getMacroTexture().updateTexture()
        meshManager.updateGPU()
        if (STICKERS_DEBUG) console.debug(`≡ƒöì Refreshed indices for ${shelfUnitCount} shelf units`)
    }

    /**
     * Get the sticker manager for runtime operations
     * Returns null when stickers are disabled
     */
    public getStickerManager(): StickerManager | null {
        return this.stickerManager
    }

    /**
     * Get the sticker integration for material setup
     * Returns null when stickers are disabled
     */
    public getStickerIntegration(): ShelfStickerIntegration | null {
        return this.stickerIntegration
    }
}

/**
 * Shelf Sticker Integration - Manages sticker rendering on shelf surfaces
 * 
 * Uses macro texture approach:
 * - Single large texture with tile per shelf
 * - Stickers rendered directly onto tiles
 * - Simple shader (just texture blend)
 * - Zero attribute overhead
 * - No WebGL limits
 * 
 * Kept separate from InstancedShelfRenderer to reduce class complexity
 * and enable reuse across different shelf renderer implementations.
 */

import * as THREE from 'three'
import { StickerManager } from './StickerManager'
import { ShelfStickerTextureAtlas } from './ShelfStickerTextureAtlas'
import type { InstancedMeshManager } from '../instancing/InstancedMeshManager'
import vertexShader from './shaders/sticker-macro-texture.vert.glsl?raw'
import fragmentShader from './shaders/sticker-macro-texture.frag.glsl?raw'

// Toggle verbose sticker-system debug logging and runtime exposures in this module
const STICKERS_DEBUG = false

export interface StickerIntegrationConfig {
    stickerManager: StickerManager
}

export class ShelfStickerIntegration {
    private stickerManager: StickerManager
    private macroTexture: ShelfStickerTextureAtlas

    constructor(config: StickerIntegrationConfig) {
        this.stickerManager = config.stickerManager

        // Create macro texture atlas - one texture for all shelves
        // Each shelf gets its own tile region in the texture
        this.macroTexture = new ShelfStickerTextureAtlas(
            this.stickerManager.getEmojiAtlas(),
            {
                tileSize: 256,      // 256x256 pixels per shelf
                tilesPerRow: 16     // 16x16 = 256 shelves max, 4096x4096 texture (~64MB)
            }
        )

        if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ ShelfStickerIntegration: Using macro texture approach (no attribute limits)')
    }

    /**
     * Add sticker instance attributes to a mesh manager
     * Macro texture approach only needs shelfId (1 float)
     */
    public setupInstanceAttributes(meshManager: InstancedMeshManager): void {
        meshManager.addInstanceAttributes([
            { name: 'shelfId', itemSize: 1, defaultValue: 0 }
        ])
    if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ Added shelfId attribute for macro texture stickers')
    }

    /**
     * Modify material to support sticker rendering via macro texture
     * Simple shader: just blend the pre-rendered sticker texture
     */
    public setupStickerMaterial(material: THREE.MeshStandardMaterial): void {
        const macroTextureInfo = this.macroTexture.getAtlasInfo()

    if (STICKERS_DEBUG) console.debug(`≡ƒÄ¿ Setting up macro texture sticker material (${macroTextureInfo.tilesPerRow}x${macroTextureInfo.tilesPerRow} tiles)`)

        material.onBeforeCompile = (shader) => {
            // Add uniforms
            shader.uniforms.stickerMacroTexture = { value: this.macroTexture.getTexture() }
            shader.uniforms.tilesPerRow = { value: macroTextureInfo.tilesPerRow }

            // Split vertex shader into declarations and implementation
            const vertexLines = vertexShader.trim().split('\n')
            const vertexDeclarations: string[] = []
            const vertexImpl: string[] = []

            for (const line of vertexLines) {
                if (line.includes('attribute') || line.includes('varying') || line.startsWith('//')) {
                    vertexDeclarations.push(line)
                } else if (line.trim()) {
                    vertexImpl.push(line)
                }
            }

            // Split fragment shader into declarations and implementation
            const fragmentLines = fragmentShader.trim().split('\n')
            const fragmentDeclarations: string[] = []
            const fragmentImpl: string[] = []

            for (const line of fragmentLines) {
                if (line.includes('uniform') || line.includes('varying') || line.startsWith('//')) {
                    fragmentDeclarations.push(line)
                } else if (line.trim()) {
                    fragmentImpl.push(line)
                }
            }

            // Inject vertex shader declarations and logic
            shader.vertexShader = shader.vertexShader.replace(
                '#include <common>',
                '#include <common>\n' + vertexDeclarations.join('\n')
            )

            shader.vertexShader = shader.vertexShader.replace(
                '#include <begin_vertex>',
                '#include <begin_vertex>\n' + vertexImpl.join('\n')
            )

            // Inject fragment shader declarations and logic
            shader.fragmentShader = shader.fragmentShader.replace(
                '#include <common>',
                '#include <common>\n' + fragmentDeclarations.join('\n')
            )

            shader.fragmentShader = shader.fragmentShader.replace(
                '#include <map_fragment>',
                '#include <map_fragment>\n' + fragmentImpl.join('\n')
            )
        }

        // Force material recompilation
        material.needsUpdate = true

    if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ Sticker material shader modified (macro texture mode)')
    }

    /**
     * Update sticker data for a specific surface instance
     * Sets shelfId attribute and renders stickers to macro texture
     */
    public updateSurfaceStickers(
        meshManager: InstancedMeshManager,
        instanceIndex: number,
        surfaceId: number
    ): void {
        // Set shelfId attribute so shader knows which tile to use
        meshManager.setInstanceAttribute('shelfId', instanceIndex, surfaceId)

        // Render stickers for this shelf to its tile in the macro texture
        const stickers = this.stickerManager.getStickersForShelf(surfaceId)

        // Clear existing stickers for this shelf
        this.macroTexture.clearShelf(surfaceId)

        // Add each sticker to the macro texture
        stickers.forEach(sticker => {
            if (sticker.enabled) {
                this.macroTexture.addStickerToShelf(
                    surfaceId,
                    sticker.emoji,
                    [sticker.position[0], sticker.position[1]],
                    sticker.rotation,
                    sticker.scale
                )
            }
        })
    }

    /**
     * Populate random stickers and update macro texture
     */
    public populateAndRefresh(
        meshManager: InstancedMeshManager,
        surfaceCount: number,
        getSurfaceId: (index: number) => number,
        density: number = 0.8
    ): void {
        // Generate surface IDs for all surfaces
        const surfaceIds: number[] = []
        for (let i = 0; i < surfaceCount; i++) {
            surfaceIds.push(getSurfaceId(i))
        }

        // Populate sticker data in manager using actual surface IDs
        this.stickerManager.populateRandomStickersWithIds(surfaceIds, density)

        // Update each surface: set shelfId attribute and render to macro texture
        let stickersRendered = 0
        for (let i = 0; i < surfaceCount; i++) {
            const surfaceId = surfaceIds[i]
            this.updateSurfaceStickers(meshManager, i, surfaceId)
            const stickers = this.stickerManager.getStickersForShelf(surfaceId)
            if (stickers.length > 0) {
                stickersRendered += stickers.length
            }
        }

        // Update macro texture with all rendered stickers
        this.macroTexture.updateTexture()

        // Update GPU with new instance attributes
        meshManager.updateGPU()

    if (STICKERS_DEBUG) console.debug(`≡ƒÄ¿ Populated ${stickersRendered} stickers across ${surfaceCount} surfaces (${Math.round(density * 100)}% density)`)
    }

    /**
     * Get the macro texture atlas for direct manipulation
     */
    public getMacroTexture(): ShelfStickerTextureAtlas {
        return this.macroTexture
    }
}

/**
 * Shelf Sticker Texture Atlas - Macro texture layer for all shelf stickers
 * 
 * Creates a single large texture where each shelf gets its own tile.
 * Stickers are rendered directly onto the shelf's tile region.
 * Transparent pixels = no sticker (natural default).
 * 
 * Benefits:
 * - Zero attribute overhead (uses existing UVs)
 * - No WebGL attribute limits
 * - Simple shader (just texture blend)
 * - Supports many stickers per shelf
 * - Easy to update individual shelves
 */

import * as THREE from 'three'
import type { EmojiTextureAtlas } from '../../utils/EmojiTextureAtlas'

// Toggle verbose sticker-system debug logging in this module
const STICKERS_DEBUG = false

export interface ShelfStickerTextureAtlasConfig {
    tileSize?: number       // Pixels per shelf tile (default: 256)
    tilesPerRow?: number    // Tiles in each row/column (default: 16 = 256 shelves max)
    backgroundColor?: string
}

interface StickerPlacement {
    emoji: string
    position: [number, number]  // 0-1 relative to tile
    rotation: number            // degrees
    scale: number               // multiplier
}

export class ShelfStickerTextureAtlas {
    private canvas: HTMLCanvasElement
    private context: CanvasRenderingContext2D
    private texture: THREE.CanvasTexture
    private emojiAtlas: EmojiTextureAtlas

    private readonly tileSize: number
    private readonly tilesPerRow: number
    private readonly atlasSize: number

    // Track which shelves have stickers for optimization
    private dirtyTiles: Set<number> = new Set()
    private stickerPlacements: Map<number, StickerPlacement[]> = new Map()

    constructor(emojiAtlas: EmojiTextureAtlas, config: ShelfStickerTextureAtlasConfig = {}) {
        this.emojiAtlas = emojiAtlas
        this.tileSize = config.tileSize ?? 256
        this.tilesPerRow = config.tilesPerRow ?? 16
        this.atlasSize = this.tileSize * this.tilesPerRow

        // Create canvas
        this.canvas = document.createElement('canvas')
        this.canvas.width = this.atlasSize
        this.canvas.height = this.atlasSize

        const ctx = this.canvas.getContext('2d', { alpha: true })
        if (!ctx) {
            throw new Error('Failed to get 2D context for sticker texture atlas')
        }
        this.context = ctx

        // Clear to transparent
        this.context.clearRect(0, 0, this.atlasSize, this.atlasSize)

        // Create Three.js texture
        this.texture = new THREE.CanvasTexture(this.canvas)
        this.texture.minFilter = THREE.LinearFilter
        this.texture.magFilter = THREE.LinearFilter
        this.texture.needsUpdate = true

        // Canvas textures in Three.js don't need flipY (unlike image textures)
        // But let's be explicit about it
        this.texture.flipY = false

    if (STICKERS_DEBUG) console.debug(`≡ƒÄ¿ Created ShelfStickerTextureAtlas: ${this.atlasSize}x${this.atlasSize} (${this.tilesPerRow}x${this.tilesPerRow} tiles, ${this.tileSize}px each)`)
    }

    /**
     * Add a sticker to a specific shelf's tile
     */
    public addStickerToShelf(
        shelfId: number,
        emoji: string,
        position: [number, number],
        rotation: number = 0,
        scale: number = 1.0
    ): void {
        if (shelfId >= this.tilesPerRow * this.tilesPerRow) {
            console.warn(`ShelfStickerTextureAtlas: shelfId ${shelfId} exceeds capacity (max: ${this.tilesPerRow * this.tilesPerRow})`)
            return
        }

        // Store placement for this shelf
        if (!this.stickerPlacements.has(shelfId)) {
            this.stickerPlacements.set(shelfId, [])
        }
        const placements = this.stickerPlacements.get(shelfId)
        if (placements) {
            placements.push({ emoji, position, rotation, scale })
        }

        // Mark tile as dirty for next render
        this.dirtyTiles.add(shelfId)
    }

    /**
     * Clear all stickers from a shelf's tile
     */
    public clearShelf(shelfId: number): void {
        this.stickerPlacements.delete(shelfId)
        this.dirtyTiles.add(shelfId)
    }

    /**
     * Clear all stickers from all shelves
     */
    public clearAll(): void {
    this.stickerPlacements.clear()
    this.context.clearRect(0, 0, this.atlasSize, this.atlasSize)
    this.texture.needsUpdate = true
    this.dirtyTiles.clear()
    if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ Cleared all shelf stickers')
    }

    /**
     * Render all dirty tiles to the canvas texture
     */
    public updateTexture(): void {
        if (this.dirtyTiles.size === 0) return

        this.dirtyTiles.forEach(shelfId => {
            this.renderShelfTile(shelfId)
        })

        this.texture.needsUpdate = true
        this.dirtyTiles.clear()
    }

    /**
     * Render a specific shelf's tile with all its stickers
     */
    private renderShelfTile(shelfId: number): void {
        const row = Math.floor(shelfId / this.tilesPerRow)
        const col = shelfId % this.tilesPerRow
        const tileX = col * this.tileSize
        const tileY = row * this.tileSize

        // Clear this tile
        this.context.clearRect(tileX, tileY, this.tileSize, this.tileSize)

        // Get stickers for this shelf
        const stickers = this.stickerPlacements.get(shelfId)
        if (!stickers || stickers.length === 0) return

        // Render each sticker
        stickers.forEach((sticker) => {
            this.renderSticker(tileX, tileY, sticker)
        })
    }

    /**
     * Render a single sticker onto the canvas
     */
    private renderSticker(
        tileX: number,
        tileY: number,
        sticker: StickerPlacement
    ): void {
        const { emoji, position, rotation, scale } = sticker

        // Calculate position within tile
        const x = tileX + position[0] * this.tileSize
        const y = tileY + position[1] * this.tileSize

        // Save context state
        this.context.save()

        // Transform context for rotation and scale
        this.context.translate(x, y)
        if (rotation !== 0) {
            this.context.rotate((rotation * Math.PI) / 180)
        }
        if (scale !== 1.0) {
            this.context.scale(scale, scale)
        }

        // Render emoji
        const fontSize = this.tileSize * 0.15 // Emoji size relative to tile
        this.context.font = `${fontSize}px Arial`
        this.context.textAlign = 'center'
        this.context.textBaseline = 'middle'
        this.context.fillStyle = 'lime' // Bright green for maximum visibility!
        this.context.fillText(emoji, 0, 0)

        // Restore context state
        this.context.restore()
    }

    /**
     * Get the Three.js texture for shader use
     */
    public getTexture(): THREE.CanvasTexture {
        return this.texture
    }

    /**
     * Get atlas configuration info
     */
    public getAtlasInfo() {
        return {
            atlasSize: this.atlasSize,
            tileSize: this.tileSize,
            tilesPerRow: this.tilesPerRow,
            maxShelves: this.tilesPerRow * this.tilesPerRow,
            memorySizeMB: ((this.atlasSize * this.atlasSize * 4) / (1024 * 1024)).toFixed(2)
        }
    }

    /**
     * Dispose of resources
     */
    public dispose(): void {
        this.texture.dispose()
        this.stickerPlacements.clear()
        this.dirtyTiles.clear()
    }
}

/**
 * Shelf Unit Index System - Display shelf unit numbers using sticker/decal system
 * 
 * Uses the sticker system to display numeric indices on shelf units,
 * making it easy to identify which shelf unit is being referenced in logs.
 * 
 * Numbers 0-9 are available in the emoji atlas for rendering.
 */

import type { StickerManager } from './StickerManager'

// Toggle verbose sticker-system debug logging in this module
const STICKERS_DEBUG = false

export class ShelfUnitIndexSystem {
    private stickerManager: StickerManager
    private enabled: boolean = false // Default to disabled (enable via UI toggle)

    // Map digit to emoji in atlas (0-9 use number emojis if available)
    private readonly digitEmojis = ['0∩╕ÅΓâú', '1∩╕ÅΓâú', '2∩╕ÅΓâú', '3∩╕ÅΓâú', '4∩╕ÅΓâú', '5∩╕ÅΓâú', '6∩╕ÅΓâú', '7∩╕ÅΓâú', '8∩╕ÅΓâú', '9∩╕ÅΓâú']

    constructor(stickerManager: StickerManager) {
        this.stickerManager = stickerManager
    }

    /**
     * Enable index display on shelf units
     */
    public enable(): void {
    this.enabled = true
    if (STICKERS_DEBUG) console.debug('≡ƒöì Shelf unit indices enabled')
    }

    /**
     * Disable index display
     * Note: Caller must call refreshAllIndices() after this to update the display
     */
    public disable(): void {
    this.enabled = false
    if (STICKERS_DEBUG) console.debug('≡ƒöì Shelf unit indices disabled')
    }

    /**
     * Toggle index display
     */
    public toggle(): void {
        if (this.enabled) {
            this.disable()
        } else {
            this.enable()
        }
    }

    /**
     * Add index sticker to a shelf unit's side board
     * @param shelfUnitIndex The shelf unit index (0-based)
     * @param sideboardSurfaceId The surface ID for the sideboard
     */
    public addIndexToSideboard(shelfUnitIndex: number, sideboardSurfaceId: number): void {
        if (!this.enabled) return

        // Support up to 3-digit indices (0-999)
        if (shelfUnitIndex > 999) {
            console.warn(`Shelf unit index ${shelfUnitIndex} > 999, skipping label`)
            return
        }

        // Convert number to string and get individual digits
        const digits = shelfUnitIndex.toString().split('')
        const digitCount = digits.length

        // Calculate spacing between digits (closer together for multi-digit numbers)
        const digitSpacing = 0.15 // UV units between digit centers
        const totalWidth = (digitCount - 1) * digitSpacing
        const startX = 0.5 - totalWidth / 2 // Center the whole number

        // Place at top-center of sideboard
        // Note: After Y-flip in shader, lower V values are at the top
        digits.forEach((digit, index) => {
            const digitEmoji = this.digitEmojis[parseInt(digit)]
            const xPos = startX + index * digitSpacing

            this.stickerManager.addSticker(
                sideboardSurfaceId,
                digitEmoji,
                [xPos, 0.1],  // Top-center (low V = top after Y-flip)
                0,           // No rotation
                1.5          // Larger scale for visibility
            )
        })
    }

    public isEnabled(): boolean {
        return this.enabled
    }
}

/**
 * Sticker Manager
 * 
 * Manages sticker placement on shelves with runtime modification support.
 * Handles indexing, placement logic, and sticker state persistence.
 */

import { EmojiTextureAtlas, DEFAULT_SHELF_EMOJIS } from '../../utils/EmojiTextureAtlas'

// Toggle verbose sticker-system debug logging in this module
const STICKERS_DEBUG = false

export interface StickerPlacement {
    shelfId: number          // Which shelf instance
    emoji: string            // Emoji character
    position: [number, number]  // UV position on shelf face (0-1 range for u, v)
    rotation: number         // Rotation in degrees (0-360)
    scale: number            // Scale factor (0.5-2.0 typical range)
    enabled: boolean         // Whether sticker is visible
}

export interface StickerData {
    uvOffset: [number, number]  // Atlas UV offset for emoji
    position: [number, number]  // Surface position (0-1 range)
    rotation: number            // Rotation in degrees
    scale: number               // Scale factor
    enabled: number             // 0 or 1 for shader
}

export class StickerManager {
    private atlas: EmojiTextureAtlas | null = null
    private placements: Map<number, StickerPlacement[]>  // shelfId -> stickers
    private readonly maxStickersPerShelf: number = 10 // Macro texture has no attribute limits!

    constructor() {
        // Atlas creation deferred to initializeAtlas() to avoid blocking startup
        this.placements = new Map()

        if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ StickerManager created (atlas deferred)')
    }

    /**
     * Initialize the emoji texture atlas (deferred from constructor to avoid blocking startup)
     * Call this during non-essential systems phase or before first sticker use
     */
    public initializeAtlas(): void {
        if (this.atlas) return // Already initialized

        this.atlas = new EmojiTextureAtlas({
            emojis: [...DEFAULT_SHELF_EMOJIS],
            emojiSize: 128,
            padding: 4,
            atlasSize: 512
        })

        if (STICKERS_DEBUG) console.debug('≡ƒÄ¿ EmojiTextureAtlas initialized')
    }

    /**
     * Add a sticker to a shelf with arbitrary position, rotation, and scale
     * @param position UV coordinates [u, v] in 0-1 range
     * @param rotation Rotation in degrees (0-360)
     * @param scale Scale factor (default 1.0)
     */
    public addSticker(
        shelfId: number, 
        emoji: string, 
        position: [number, number] = [0.5, 0.5],
        rotation: number = 0,
        scale: number = 1.0
    ): boolean {
        // Auto-initialize atlas if needed
        const atlas = this.getAtlas()

        if (!atlas.hasEmoji(emoji)) {
            console.warn(`Emoji "${emoji}" not in atlas`)
            return false
        }

        const currentStickers = this.placements.get(shelfId) || []

        if (currentStickers.length >= this.maxStickersPerShelf) {
            console.warn(`Shelf ${shelfId} already has maximum stickers (${this.maxStickersPerShelf})`)
            return false
        }

        const sticker: StickerPlacement = {
            shelfId,
            emoji,
            position,
            rotation,
            scale,
            enabled: true
        }

        currentStickers.push(sticker)
        this.placements.set(shelfId, currentStickers)

        return true
    }

    /**
     * Remove a sticker from a shelf by index
     */
    public removeStickerByIndex(shelfId: number, index: number): boolean {
        const currentStickers = this.placements.get(shelfId)
        if (!currentStickers || index < 0 || index >= currentStickers.length) {
            return false
        }

        currentStickers.splice(index, 1)

        if (currentStickers.length === 0) {
            this.placements.delete(shelfId)
        } else {
            this.placements.set(shelfId, currentStickers)
        }

        return true
    }

    /**
     * Get sticker data for a specific sticker by index (for shader attributes)
     * @param index The sticker index (0-2) on the shelf
     */
    public getStickerDataForShelf(shelfId: number, index: number): StickerData {
        const stickers = this.placements.get(shelfId)
        if (!stickers || index < 0 || index >= stickers.length) {
            return { 
                uvOffset: [0, 0], 
                position: [0.5, 0.5],
                rotation: 0,
                scale: 1.0,
                enabled: 0 
            }
        }

        const sticker = stickers[index]
        if (!sticker?.enabled || !this.atlas) {
            return { 
                uvOffset: [0, 0], 
                position: sticker?.position ?? [0.5, 0.5],
                rotation: sticker?.rotation ?? 0,
                scale: sticker?.scale ?? 1.0,
                enabled: 0 
            }
        }

        const uvOffset = this.atlas.getEmojiUVOffset(sticker.emoji)
        if (!uvOffset) {
            return { 
                uvOffset: [0, 0], 
                position: sticker.position,
                rotation: sticker.rotation,
                scale: sticker.scale,
                enabled: 0 
            }
        }

        return {
            uvOffset,
            position: sticker.position,
            rotation: sticker.rotation,
            scale: sticker.scale,
            enabled: 1
        }
    }

    /**
     * Get all stickers for a shelf
     */
    public getStickersForShelf(shelfId: number): StickerPlacement[] {
        return this.placements.get(shelfId) || []
    }

    /**
     * Toggle sticker visibility by index
     */
    public toggleStickerByIndex(shelfId: number, index: number): boolean {
        const stickers = this.placements.get(shelfId)
        if (!stickers || index < 0 || index >= stickers.length) {
            return false
        }

        stickers[index].enabled = !stickers[index].enabled
        return true
    }

    /**
     * Clear all stickers
     */
    public clearAll(): void {
    this.placements.clear()
    if (STICKERS_DEBUG) console.debug('Cleared all stickers')
    }

    /**
     * Clear stickers for a specific shelf
     */
    public clearShelf(shelfId: number): void {
        this.placements.delete(shelfId)
    }

    /**
     * Get the emoji texture atlas (initializes if needed)
     */
    public getAtlas(): EmojiTextureAtlas {
        if (!this.atlas) {
            this.initializeAtlas()
        }
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        return this.atlas!
    }

    /**
     * Get atlas info for shader configuration
     */
    public getAtlasInfo() {
        if (!this.atlas) {
            this.initializeAtlas()
        }
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        return this.atlas!.getAtlasInfo()
    }

    /**
     * Populate random stickers for testing with arbitrary positioning
     */
    public populateRandomStickers(shelfCount: number, density: number = 0.8): void {
        const emojis = [...DEFAULT_SHELF_EMOJIS]

        for (let shelfId = 0; shelfId < shelfCount; shelfId++) {
            // Random chance to add stickers (80% by default)
            if (Math.random() > density) continue

            // Add 2-5 stickers per shelf (varied for visual interest)
            const stickerCount = Math.floor(Math.random() * 4) + 2 // 2, 3, 4, or 5 stickers

            for (let i = 0; i < stickerCount; i++) {
                const emoji = emojis[Math.floor(Math.random() * emojis.length)]

                // Random position (with some margin from edges)
                const position: [number, number] = [
                    0.2 + Math.random() * 0.6,  // u: 0.2 to 0.8
                    0.2 + Math.random() * 0.6   // v: 0.2 to 0.8
                ]

                // Random rotation
                const rotation = Math.random() * 360

                // Random scale (0.8 to 1.2)
                const scale = 0.8 + Math.random() * 0.4

                this.addSticker(shelfId, emoji, position, rotation, scale)
            }
        }

    const totalStickers = Array.from(this.placements.values()).reduce((sum, stickers) => sum + stickers.length, 0)
    if (STICKERS_DEBUG) console.debug(`≡ƒÄ¿ Populated ${totalStickers} random stickers across ${this.placements.size} shelves (${shelfCount} total, ${Math.round(density * 100)}% density)`)
    }

    /**
     * Populate random stickers using specific surface IDs (for macro texture with non-sequential IDs)
     */
    public populateRandomStickersWithIds(surfaceIds: number[], density: number = 0.8): void {
        const emojis = [...DEFAULT_SHELF_EMOJIS]

        for (const surfaceId of surfaceIds) {
            // Random chance to add stickers (80% by default)
            if (Math.random() > density) continue

            // Add 2-5 stickers per shelf (varied for visual interest)
            const stickerCount = Math.floor(Math.random() * 4) + 2 // 2, 3, 4, or 5 stickers

            for (let i = 0; i < stickerCount; i++) {
                const emoji = emojis[Math.floor(Math.random() * emojis.length)]

                // Random position (with some margin from edges)
                const position: [number, number] = [
                    0.2 + Math.random() * 0.6,  // u: 0.2 to 0.8
                    0.2 + Math.random() * 0.6   // v: 0.2 to 0.8
                ]

                // Random rotation
                const rotation = Math.random() * 360

                // Random scale (0.8 to 1.2)
                const scale = 0.8 + Math.random() * 0.4

                this.addSticker(surfaceId, emoji, position, rotation, scale)
            }
        }

    const totalStickers = Array.from(this.placements.values()).reduce((sum, stickers) => sum + stickers.length, 0)
    if (STICKERS_DEBUG) console.debug(`≡ƒÄ¿ Populated ${totalStickers} random stickers across ${this.placements.size} surfaces (${surfaceIds.length} total, ${Math.round(density * 100)}% density)`)
    }

    /**
     * Get the emoji texture atlas for shader rendering
     */
    public getEmojiAtlas(): EmojiTextureAtlas {
        return this.atlas
    }

    public dispose(): void {
        this.atlas.dispose()
        this.placements.clear()
    }
}

/**
 * Game Library Manager
 * 
 * Manages game library state including:
 * - Current game data tracking
 * - Sorting and filtering (future)
 * - Game selection state (future)
 */

import type { SteamGame, SteamUser } from '../steam'
import { EventManager } from '../core/EventManager'
import { SteamEventTypes } from '../types/InteractionEvents'
import type { SteamGamesBatchEvent } from '../types/InteractionEvents'

export interface GameLibraryState {
    userData: SteamUser | null
    currentGameIndex: number
    isLoading: boolean
    error: string | null
}

/**
 * Manages the state of the Steam game library
 */
export class GameLibraryManager {
    private state: GameLibraryState = {
        userData: null,
        currentGameIndex: 0,
        isLoading: false,
        error: null
    }

    private eventManager: EventManager

    constructor() {
        this.eventManager = EventManager.getInstance()
        this.eventManager.registerEventHandler(SteamEventTypes.GamesBatchReady, this.handleGamesBatch.bind(this))
    }

    private handleGamesBatch(event: CustomEvent<SteamGamesBatchEvent>): void {
        const { games } = event.detail

        for (const game of games) {
            this.updateGameData(game as SteamGame)
        }
    }

    /**
     * Set the user data from Steam API
     */
    setUserData(userData: SteamUser): void {
        this.state.userData = userData
        this.state.currentGameIndex = 0
        this.state.error = null
    }

    /**
     * Update a specific game's data
     */
    updateGameData(updatedGame: SteamGame): void {
        if (!this.state.userData?.games) {
            return
        }

        const gameIndex = this.state.userData.games.findIndex(
            game => game.appid === updatedGame.appid
        )

        if (gameIndex !== -1) {
            this.state.userData.games[gameIndex] = updatedGame
        }
    }

    /**
     * Get current game library state
     */
    getState(): GameLibraryState {
        return { ...this.state }
    }

    /**
     * Set loading state
     */
    setLoading(isLoading: boolean): void {
        this.state.isLoading = isLoading
    }

    /**
     * Set error state
     */
    setError(error: string | null): void {
        this.state.error = error
    }

    /**
     * Get current game count
     */
    getGameCount(): number {
        return this.state.userData?.game_count ?? 0
    }

    /**
     * Get games array
     */
    getGames(): SteamGame[] {
        return this.state.userData?.games ?? []
    }

    /**
     * Get current game index
     */
    getCurrentGameIndex(): number {
        return this.state.currentGameIndex
    }

    /**
     * Set current game index
     */
    setCurrentGameIndex(index: number): void {
        this.state.currentGameIndex = index
    }

    /**
     * Increment current game index
     */
    incrementGameIndex(): number {
        return ++this.state.currentGameIndex
    }

    /**
     * Clear all data
     */
    clear(): void {
        this.state = {
            userData: null,
            currentGameIndex: 0,
            isLoading: false,
            error: null
        }
    }

    /**
     * Check if we have user data
     */
    hasUserData(): boolean {
        return this.state.userData !== null
    }

    /**
     * Get vanity URL if available
     */
    getVanityUrl(): string | null {
        return this.state.userData?.vanity_url ?? null
    }
}

/**
 * Steam Integration Manager
 * 
 * High-level Steam game library integration that orchestrates:
 * - Steam API calls
 * - Progressive loading workflow
 * - Steam data transformation
 * - Cache management
 */

import { SteamApiClient, type SteamGame, type SteamUser, type SteamResolveResponse } from '../steam'
import { ANONYMOUS_STORE_USER } from '../steam/fixtures/demo-games'
import { ValidationUtils } from '../utils'
import { Logger } from '../utils/Logger'
import { GameLibraryManager, type GameLibraryState } from './GameLibraryManager'
import type { SteamGameData } from '../scene'
import { SteamErrorMessages, type SteamErrorContext } from '../utils/SteamErrorMessages'
import { EventManager } from '../core/EventManager'
import { SteamEventTypes, AppSettingsEventTypes, GameEventTypes } from '../types/InteractionEvents'
import type { SteamLoadGamesEvent, SteamLoadFromCacheEvent, SteamCacheRefreshEvent, SteamCacheClearEvent, SteamGamesBatchEvent, SteamDataLoadedEvent } from '../types/InteractionEvents'
import type { SettingChangedEvent } from '../core/AppSettings'
import { AppSettings } from '../core/AppSettings'
import { DataManager, DataDomain } from '../core/data'
import { sortByNumericField } from '../scene/categorization/GameSortFunctions'

export interface SteamIntegrationConfig {
    apiBaseUrl?: string
    maxGames?: number
}

export interface SteamUserIdentifier {
    vanityUrl: string
    displayName?: string
    steamId?: string
}

export interface ProgressCallbacks {
    onProgress?: (current: number, total: number, message: string) => void
    onStatusUpdate?: (message: string, type: 'loading' | 'success' | 'error') => void
}

export interface LoadGamesOptions {
    maxGames?: number
    onProgress?: (current: number, total: number) => void
}

export class SteamIntegration {
    private static readonly logger = Logger.createLogFunctions(SteamIntegration.name)
    private static _instance: SteamIntegration | null = null
    
    private steamClient: SteamApiClient
    private gameLibrary: GameLibraryManager
    private eventManager: EventManager
    private config: {
        apiBaseUrl: string
        maxGames: number
    }

    constructor(config: SteamIntegrationConfig = {}) {
        this.config = {
            apiBaseUrl: config.apiBaseUrl || 'https://steam-api-dev.wehrly.com',
            maxGames: config.maxGames || 10
        }
        
        this.eventManager = EventManager.getInstance()
        this.steamClient = new SteamApiClient(this.config.apiBaseUrl)
        this.gameLibrary = new GameLibraryManager()
        
        SteamIntegration._instance = this
        
        // Register event handlers directly - no workflow manager needed
        this.registerEventHandlers()
    }
    
    /**
     * Register Steam event handlers directly in SteamIntegration
     */
    private registerEventHandlers(): void {
        this.eventManager.registerEventHandler(SteamEventTypes.LoadGames, this.handleLoadGames.bind(this))
        this.eventManager.registerEventHandler(SteamEventTypes.LoadFromCache, this.handleLoadFromCache.bind(this))
        this.eventManager.registerEventHandler(SteamEventTypes.CacheRefresh, this.handleRefreshCache.bind(this))
        this.eventManager.registerEventHandler(SteamEventTypes.CacheClear, this.handleClearCache.bind(this))
        this.eventManager.registerEventHandler(AppSettingsEventTypes.Changed, this.handleSettingsChange.bind(this))
        this.eventManager.registerEventHandler(GameEventTypes.Start, this.handleGameStart.bind(this))
    }
    
    /**
     * Store Steam data in DataManager and emit event
     * CRITICAL: Data ownership - store data before emitting events that depend on it
     */
    private storeSteamDataAndEmitEvent(userInput: string): void {
        const gameLibraryState = this.getGameLibraryState()
        const games: SteamGameData[] = gameLibraryState.userData?.games || []
        
        SteamIntegration.logger.debug(`Storing ${games.length} games in DataManager`)
        
        const dataManager = DataManager.getInstance()
        dataManager.set<SteamGameData[]>('steam.games', games, {
            domain: DataDomain.SteamIntegration
        })
        
        if (userInput) {
            dataManager.set('steam.userInput', userInput, {
                domain: DataDomain.SteamIntegration
            })
        }
        
        this.eventManager.emit<SteamDataLoadedEvent>(SteamEventTypes.DataLoaded, {
            userInput
        })
    }

    static getInstance(): SteamIntegration | null {
        return SteamIntegration._instance
    }

    /**
     * Load Steam games for a user with progressive loading
     */
    async loadGamesForUser(userInput: string, callbacks: ProgressCallbacks = {}): Promise<GameLibraryState> {
        const parsedInput = ValidationUtils.parseSteamUserInput(userInput)
        let steamId: string | undefined
        let vanityUrl: string
        
        try {
            // Step 1: Get steamID (either directly provided or resolved from custom URL)
            callbacks.onStatusUpdate?.('Loading Steam games...', 'loading')
            callbacks.onProgress?.(0, 100, 'Fetching game library...')
            
            SteamIntegration.logger.info(`Loading games for Steam user: ${parsedInput.value} (type: ${parsedInput.type})`)
            
            if (parsedInput.type === 'steamid') {
                // Direct steamID - no resolution needed
                steamId = parsedInput.value
                vanityUrl = `steamid:${steamId}` // Use a placeholder since we don't know the actual custom URL
            } else {
                // Custom URL - resolve to get steamID
                const resolveResponse = await this.steamClient.resolveVanityUrl(parsedInput.value)
                steamId = resolveResponse.steamid
                vanityUrl = resolveResponse.vanity_url
            }
            
            // Validate we have a steamID before proceeding
            if (!steamId) {
                throw new Error('Failed to obtain valid Steam ID')
            }
            
            const userGames = await this.steamClient.getUserGames(steamId)
            
            // Add the vanity URL to the userGames for reference
            userGames.vanity_url = vanityUrl
            
            // Update game library state
            this.gameLibrary.setUserData(userGames)
            
            callbacks.onProgress?.(10, 100, `Found ${userGames.game_count} games. Loading details for top ${Math.min(this.config.maxGames, userGames.game_count)}...`)
            
            // Progressive loading via events - GameLibraryManager listens to GamesBatchReady
            await this.steamClient.loadGamesProgressively(userGames, {
                maxGames: this.config.maxGames,
                sortFn: sortByNumericField('rtime_last_played', 'playtime_forever'),
            })
            
            // Complete loading - actual count from library state (populated via onBatchReady)
            const actualGamesLoaded = Math.min(this.config.maxGames, userGames.game_count)
            callbacks.onProgress?.(100, 100, 'Loading complete!')
            callbacks.onStatusUpdate?.(
                `Γ£à Successfully loaded ${actualGamesLoaded} games for ${userGames.vanity_url}!`, 
                'success'
            )
            
            SteamIntegration.logger.info(`Progressive loading complete for ${actualGamesLoaded} games (max: ${this.config.maxGames})`)
            
            return this.gameLibrary.getState()
            
        } catch (error) {
            // Log error with context about what step failed
            const errorMessage = (error as Error).message
            if (errorMessage.includes('vanity') || errorMessage.includes('resolve')) {
                SteamIntegration.logger.error(`Failed to resolve Steam input "${parsedInput.value}" (${parsedInput.type}):`, error)
            } else if (errorMessage.includes('games') || errorMessage.includes('getUserGames')) {
                SteamIntegration.logger.error(`Failed to load games for Steam ID "${steamId || 'Unknown'}":`, error)
            } else {
                SteamIntegration.logger.error(`Failed during Steam integration for "${userInput}":`, error)
            }
            
            // Generate contextual error message based on input and error type
            const errorContext: SteamErrorContext = {
                userInput: userInput,
                parsedInputType: parsedInput.type,
                parsedInputValue: parsedInput.value,
                errorType: SteamErrorMessages.categorizeError(error as Error),
                originalError: error as Error
            }
            
            const userFriendlyMessage = SteamErrorMessages.generateErrorMessage(errorContext)
            callbacks.onStatusUpdate?.(userFriendlyMessage, 'error')
            
            throw error
        }
    }

    async refreshData(callbacks: ProgressCallbacks = {}): Promise<GameLibraryState | null> {
        const currentState = this.gameLibrary.getState()
        
        // TODO: Support refresh without vanity url
        if (!currentState.userData?.vanity_url) {
            callbacks.onStatusUpdate?.('No data to refresh', 'error')
            return null
        }
        
        callbacks.onStatusUpdate?.('≡ƒöä Reloading data...', 'loading')
        return this.loadGamesForUser(currentState.userData.vanity_url, callbacks)
    }

    async clearCache(): Promise<void> {
        await this.steamClient.clearCache()
        this.gameLibrary.clear()
    }

    getGameLibraryState(): GameLibraryState {
        return this.gameLibrary.getState()
    }

    /**
     * Check if cached data is available for a user
     * 
     * TODO: Story 5.5.1 (backlogged) - Potential optimization to reduce from 2 cache lookups to 1,
     * but previous implementation created data duplication issues. Consider alternative approaches like
     * single-pass cache check or result memoization if this becomes a performance bottleneck.
     * See docs/active/tech-debt.md for detailed analysis.
     */
    hasCachedData(userInput: string): boolean {
        const parsedInput = ValidationUtils.parseSteamUserInput(userInput)
        
        if (parsedInput.type === 'steamid') {
            // Direct steamID - check games cache directly
            const gamesKey = `games_${parsedInput.value}`
            return this.steamClient.hasCached(gamesKey)
        } else {
            // Custom URL - check if we have cached resolve data first
            const resolveKey = `resolve_${parsedInput.value.toLowerCase()}`
            const cachedResolve = this.steamClient.getCached<SteamResolveResponse>(resolveKey)
            
            if (!cachedResolve) {
                return false
            }
            
            // Check if we have cached games data for the resolved Steam ID
            const gamesKey = `games_${cachedResolve.steamid}`
            return this.steamClient.hasCached(gamesKey)
        }
    }

    /**
     * Get all cached users with their vanity URLs and display names
     */
    getCachedUsers(): Array<{ vanityUrl: string, displayName: string, gameCount: number, steamId: string }> {
        // Use the optimized implementation from SteamApiClient
        return this.steamClient.getCachedUsers()
    }

    /**
     * Load games from cache only (no Steam API calls)
     */
    async loadGamesFromCache(userInput: string, callbacks: ProgressCallbacks = {}, clearExisting = true): Promise<GameLibraryState> {
        const parsedInput = ValidationUtils.parseSteamUserInput(userInput)
        
        try {
            callbacks.onStatusUpdate?.('Loading from cache...', 'loading')
            callbacks.onProgress?.(0, 100, 'Reading cached data...')
            
            SteamIntegration.logger.info(`Loading cached games for Steam user: ${parsedInput.value} (type: ${parsedInput.type})`)
            
            // Clear existing games if requested
            if (clearExisting) {
                this.gameLibrary.clear()
            }
            
            // Get steamID (either directly or from cache)
            let steamId: string
            if (parsedInput.type === 'steamid') {
                steamId = parsedInput.value
            } else {
                const cachedSteamId = await this.getCachedSteamId(parsedInput.value)
                if (!cachedSteamId) {
                    throw new Error('No cached resolve data found for custom URL')
                }
                steamId = cachedSteamId
            }

            
            const cachedGames = this.steamClient.getCached<SteamUser>(`games_${steamId}`)
            if (!cachedGames) {
                throw new Error('No cached games data found')
            }
            
            // Update game library state with cached data
            this.gameLibrary.setUserData(cachedGames)
            
            callbacks.onProgress?.(10, 100, `Found ${cachedGames.game_count} games in cache. Loading...`)
            
            // Progressive loading via events - GameLibraryManager listens to GamesBatchReady  
            await this.steamClient.loadGamesProgressively(cachedGames, {
                maxGames: cachedGames.game_count,
                sortFn: sortByNumericField('rtime_last_played', 'playtime_forever'),
            })
            
            const gamesLoaded = this.gameLibrary.getState().userData?.games?.length ?? 0
            
            callbacks.onProgress?.(100, 100, 'Loading complete!')
            callbacks.onStatusUpdate?.(
                `Γ£à Loaded ${gamesLoaded} games from cache for ${cachedGames.vanity_url}!`, 
                'success'
            )
            
            // NOTE: Don't call storeSteamDataAndEmitEvent here - let the caller handle it
            // to avoid double-triggering shelf generation (maintains consistency with loadGamesForUser)
            
            return this.gameLibrary.getState()
            
        } catch (error) {
            SteamIntegration.logger.error('Failed to load games from cache:', error)
            
            // Generate cache-specific error message
            const errorMessage = error instanceof Error && error.message.includes('No cached')
                ? `Γ¥î No cached data found for "${userInput}". Please use "Load Games" to fetch fresh data from Steam first.`
                : `Γ¥î Failed to load from cache. Try "Load Games" to fetch fresh data from Steam.`
            
            callbacks.onStatusUpdate?.(errorMessage, 'error')
            throw error
        }
    }

    private async getCachedSteamId(vanityUrl: string): Promise<string | null> {
        const resolveKey = `resolve_${vanityUrl.toLowerCase()}`
        const cachedResolve = this.steamClient.getCached<SteamResolveResponse>(resolveKey)
        return cachedResolve?.steamid || null
    }
    


    updateMaxGames(maxGames: number): void {
        this.config.maxGames = maxGames
        SteamIntegration.logger.info(`Updated maxGames setting to: ${maxGames}`)
    }

    // This is only for testing?
    getSteamClient() {
        return this.steamClient
    }
    
    /**
     * Event handlers - migrated from SteamWorkflowManager
     * Eliminates unnecessary pass-through layer
     */
    
    private async handleGameStart(): Promise<void> {
        const cachedUsers = this.getCachedUsers()

        // Dev/test fallback: load demo games when no cached user exists, regardless of
        // autoLoadProfile (which defaults false and won't be set in a fresh test env)
        if (cachedUsers.length === 0 && AppSettings.get('developmentMode')) {
            SteamIntegration.logger.info('No cached user - loading anonymous store for dev/test')
            await this.loadDemoGames()
            return
        }

        if (!AppSettings.get('autoLoadProfile')) {
            SteamIntegration.logger.debug('Auto-load disabled')
            return
        }
        
        if (cachedUsers.length === 0) {
            SteamIntegration.logger.warn('ΓÜá∩╕Å Auto-load enabled but no Steam profiles cached yet - user must load a profile first')
            return
        }
        
        const user = cachedUsers[0]
        SteamIntegration.logger.info(`Auto-load: ${user.displayName} (${user.vanityUrl})`)
        
        this.eventManager.emit<SteamLoadFromCacheEvent>(SteamEventTypes.LoadFromCache, {
            userInput: user.vanityUrl
        })
    }

    /**
     * Load hardcoded demo games for dev/test environments.
     * Emits games directly into the batch pipeline ΓÇö no network calls.
     */
    private async loadDemoGames(): Promise<void> {
        try {
            const demoUser = ANONYMOUS_STORE_USER
            const games = demoUser.games as SteamGame[]
            const BATCH_SIZE = 18
            const totalBatches = Math.ceil(games.length / BATCH_SIZE)


            // Anonymous store: do not populate a Steam user identity
            // this.gameLibrary.setUserData(demoUser) - omitted so UI shows no profile
            // Emit games directly as batch events ΓÇö no Steam API network calls.
            // Strip artwork so game boxes render as text labels immediately, without
            // waiting for CDN fetches that will CORS-fail in test/anonymous contexts.
            for (let i = 0; i < totalBatches; i++) {
                const batchGames = games.slice(i * BATCH_SIZE, (i + 1) * BATCH_SIZE).map(g => ({
                    ...g
                }))
                EventManager.getInstance().emit<SteamGamesBatchEvent>(
                    SteamEventTypes.GamesBatchReady,
                    { games: batchGames, batchIndex: i, totalBatches }
                )
                if (i < totalBatches - 1) {
                    await new Promise(resolve => setTimeout(resolve, 0))
                }
            }

            this.storeSteamDataAndEmitEvent('demo-user')
            SteamIntegration.logger.info(`Demo store loaded: ${games.length} games in ${totalBatches} batches`)
        } catch (error) {
            SteamIntegration.logger.error('Failed to load demo games:', error)
        }
    }
    
    private async handleLoadGames(event: CustomEvent<SteamLoadGamesEvent>): Promise<void> {
        const { userInput } = event.detail
        
        try {
            await this.loadGamesForUser(userInput)
            this.storeSteamDataAndEmitEvent(userInput)
            SteamIntegration.logger.info('Load games completed')
        } catch (error) {
            SteamIntegration.logger.error('Load games failed:', error)
        }
    }
    
    private async handleLoadFromCache(event: CustomEvent<SteamLoadFromCacheEvent>): Promise<void> {
        const { userInput: vanityUrl } = event.detail
        
        try {
            if (!this.hasCachedData(vanityUrl)) {
                SteamIntegration.logger.warn('No cached data found')
                return
            }
            
            await this.loadGamesFromCache(vanityUrl)
            this.storeSteamDataAndEmitEvent(vanityUrl)
            SteamIntegration.logger.info('Loaded from cache')
        } catch (error) {
            SteamIntegration.logger.error('Load from cache failed:', error)
        }
    }

    private async handleRefreshCache(event: CustomEvent<SteamCacheRefreshEvent>): Promise<void> {
        try {
            const result = await this.refreshData()
            if (!result) {
                SteamIntegration.logger.warn('No data to refresh')
                return
            }
            
            const gameState = this.getGameLibraryState()
            if (gameState.userData?.vanity_url) {
                this.storeSteamDataAndEmitEvent(gameState.userData.vanity_url)
            }
            SteamIntegration.logger.info('Cache refreshed')
        } catch (error) {
            SteamIntegration.logger.error('Cache refresh failed:', error)
        }
    }

    private async handleClearCache(event: CustomEvent<SteamCacheClearEvent>): Promise<void> {
        try {
            await this.clearCache()
            SteamIntegration.logger.info('Cache cleared')
        } catch (error) {
            SteamIntegration.logger.error('Cache clear failed:', error)
        }
    }

    private async handleSettingsChange(event: CustomEvent<SettingChangedEvent>): Promise<void> {
        const { key, value } = event.detail
        
        if (key !== 'developmentMode') return
        
        try {
            const maxGames = value ? 20 : 100
            this.updateMaxGames(maxGames)
            SteamIntegration.logger.info(`Dev mode ${value ? 'enabled' : 'disabled'}: ${maxGames} games max`)
        } catch (error) {
            SteamIntegration.logger.error('Dev mode setting change failed:', error)
        }
    }
}

/**
 * Steam Integration Module
 * 
 * Exports Steam integration components for game library management
 */

export {
    SteamIntegration,
    type SteamIntegrationConfig,
    type ProgressCallbacks,
    type LoadGamesOptions
} from './SteamIntegration'

export {
    GameLibraryManager,
    type GameLibraryState
} from './GameLibraryManager'

/**
 * Simplified Steam API Client using composition layers
 */

import { HttpClient } from './http/HttpClient'
import { CacheManager } from './cache/SimpleCacheManager'
import { RateLimiter } from './rate-limit/RateLimiter'
import { BatchAppDetailsClient } from './batch/BatchAppDetailsClient'
import { Logger } from '../utils/Logger'
import { PerformanceMonitor, ASYNC_CONTEXT, MAIN_THREAD_CONTEXT } from '../utils/PerformanceMonitor'
import { AppDetailsCache } from './cache/AppDetailsCache'
import type { AppDetailsData } from './batch/BatchAppDetailsClient'
import type { SteamGameMetadata } from './types/SteamMetadata'
import { EventManager } from '../core/EventManager'
import { SteamEventTypes } from '../types/InteractionEvents'
import type { SteamGamesBatchEvent, SteamNetworkFetchProgressEvent } from '../types/InteractionEvents'

export interface SteamGame extends SteamGameMetadata {
    appid: number
    name: string
    playtime_forever: number
    playtime_2weeks?: number
    /** Unix timestamp of last play session. 0 means never played (but owned). */
    rtime_last_played?: number
    img_icon_url: string
    img_logo_url: string
    artwork: {
        icon: string
        logo: string
        header: string
        library: string
    }
}

export interface SteamUser {
    steamid: string
    vanity_url?: string
    game_count: number
    games: SteamGame[]
    retrieved_at: string
}

export interface SteamResolveResponse {
    vanity_url: string
    steamid: string
    resolved_at: string
}

export interface SteamApiError {
    error: string
    message: string
    timestamp: string
}

/**
 * Simplified Steam API Client using layered composition
 * 
 * All public methods include explicit caching logic for transparency and easier debugging.
 */
export class SteamApiClient {
    private static readonly logger = Logger.createLogFunctions(SteamApiClient.name)
    private http: HttpClient
    private cache: CacheManager
    private rateLimiter: RateLimiter
    private batchClient: BatchAppDetailsClient
    private appDetailsCache: AppDetailsCache

    // TODO: Tear this out of history, and resolve the value from terraform outputs
    constructor(apiBaseUrl = 'https://steam-api-dev.wehrly.com') {
        // Initialize all layers
        this.http = new HttpClient({ baseUrl: apiBaseUrl })
        this.cache = new CacheManager({ cachePrefix: 'steam_api_' })
        this.rateLimiter = new RateLimiter({ requestsPerSecond: 4 })
        this.batchClient = new BatchAppDetailsClient(apiBaseUrl)
        this.appDetailsCache = new AppDetailsCache()

        // Initialize app details cache
        this.appDetailsCache.init().catch(error => {
            console.warn('ΓÜá∩╕Å [SteamApiClient] Failed to initialize app details cache:', error)
        })
    }

    /**
     * Resolve Steam vanity URL to Steam ID with caching
     * 
     * @param vanityUrl - The custom URL part (e.g., "SpiteMonger")
     * @returns Promise<SteamResolveResponse> - Contains steamid and vanity_url
     */
    public async resolveVanityUrl(vanityUrl: string): Promise<SteamResolveResponse> {
        if (!vanityUrl || vanityUrl.trim().length === 0) {
            throw new Error('Vanity URL cannot be empty')
        }

        const cleanVanityUrl = vanityUrl.trim().toLowerCase()
        const cacheKey = `resolve_${cleanVanityUrl}`

        // Check cache first
        const cached = this.cache.get<SteamResolveResponse>(cacheKey)
        if (cached) {
            SteamApiClient.logger.debug(`Using cached vanity URL resolution for: ${cleanVanityUrl}`)
            return cached
        }

        // Make API request
        const endpoint = `/resolve/${encodeURIComponent(cleanVanityUrl)}`
        SteamApiClient.logger.debug(`Resolving vanity URL: "${vanityUrl}" -> "${cleanVanityUrl}"`)

        const rawResponse = await this.http.makeRequest<unknown>(endpoint)
        const response = this.normalizeResolveResponse(rawResponse, cleanVanityUrl)
        SteamApiClient.logger.info(`Vanity URL resolved: ${response.vanity_url || cleanVanityUrl}`)

        // Cache the result
        this.cache.set(cacheKey, response)

        return response
    }

    private normalizeResolveResponse(response: unknown, requestedVanityUrl: string): SteamResolveResponse {
        const isObject = (value: unknown): value is Record<string, unknown> =>
            typeof value === 'object' && value !== null

        if (!isObject(response)) {
            throw new Error('Invalid resolve vanity URL response shape')
        }

        if (response.success === false) {
            const message = typeof response.message === 'string' ? response.message : 'Failed to resolve vanity URL'
            throw new Error(message)
        }

        const payload = response.success === true && isObject(response.data) ? response.data : response
        const steamid = typeof payload.steamid === 'string' ? payload.steamid : undefined
        if (!steamid) {
            throw new Error('Invalid resolve vanity URL response shape')
        }

        return {
            steamid,
            vanity_url: typeof payload.vanity_url === 'string' ? payload.vanity_url : requestedVanityUrl,
            resolved_at: typeof payload.resolved_at === 'string' ? payload.resolved_at : new Date().toISOString()
        }
    }

    /**
     * Get user's Steam games with caching
     * 
     * @param steamId - The 17-digit Steam ID
     * @returns Promise<SteamUser> - Contains games list and user info
     */
    public async getUserGames(steamId: string): Promise<SteamUser> {
        if (!steamId || steamId.trim().length === 0) {
            throw new Error('Steam ID cannot be empty')
        }

        const cacheKey = `games_${steamId}`

        // Check cache first
        const cached = this.cache.get<SteamUser>(cacheKey)
        if (cached) {
            SteamApiClient.logger.debug(`Using cached games data for Steam ID: ${steamId}`)
            return cached
        }

        // Make API request
        const endpoint = `/games/${encodeURIComponent(steamId)}`
        SteamApiClient.logger.debug(`Fetching games for Steam ID: ${steamId}`)

        try {
            const response = await this.http.makeRequest<SteamUser>(endpoint)
            SteamApiClient.logger.info(`Fetched ${response.game_count} games for ${response.vanity_url || steamId}`)

            if (response.game_count === 0) {
                SteamApiClient.logger.warn('User has 0 games - this might indicate privacy settings or an empty library')
            }

            // Cache the result
            this.cache.set(cacheKey, response)

            return response
        } catch (error) {
            SteamApiClient.logger.error('Failed to fetch user games:', error)
            throw error
        }
    }

    /**
     * Get enhanced game details with artwork URLs, caching, and rate limiting
     * 
     * @param game - Basic game info from Steam API
     * @returns Promise<SteamGame> - Enhanced game with artwork URLs
     */
    public async getGameDetails(game: SteamGame): Promise<SteamGame> {
        const cacheKey = `game_${game.appid}`

        // Check cache first
        const cached = this.cache.get<SteamGame>(cacheKey)
        if (cached) {
            return cached
        }

        // Apply rate limiting for this operation
        const enhancedGame = await this.rateLimiter.limited(async () => {
            // Enhance game with artwork URLs - handle missing image URLs gracefully
            const enhanced: SteamGame = {
                ...game,
                artwork: {
                    icon: game.img_icon_url 
                        ? `https://steamcdn-a.akamaihd.net/steamcommunity/public/images/apps/${game.appid}/${game.img_icon_url}.jpg`
                        : '',
                    logo: game.img_logo_url 
                        ? `https://steamcdn-a.akamaihd.net/steamcommunity/public/images/apps/${game.appid}/${game.img_logo_url}.jpg`
                        : '',
                    header: `https://cdn.akamai.steamstatic.com/steam/apps/${game.appid}/header.jpg`,
                    library: `https://cdn.akamai.steamstatic.com/steam/apps/${game.appid}/library_600x900.jpg`
                }
            }

            return enhanced
        })()

        // Cache the result
        this.cache.set(cacheKey, enhancedGame)

        return enhancedGame
    }

    /**
     * Check if cache has complete metadata for a game
     */
    private isMetadataComplete(cached: AppDetailsData | undefined): boolean {
        if (!cached) return false
        const hasCategories = cached.categories && Array.isArray(cached.categories) && cached.categories.length > 0
        const hasGenres = cached.genres && Array.isArray(cached.genres) && cached.genres.length > 0
        return hasCategories || hasGenres
    }

    /**
     * Normalize batch response data (lift nested fields to top level)
     */
    private normalizeBatchData(data: AppDetailsData): AppDetailsData {
        const fullData = data?.full_data as Record<string, unknown> | undefined
        return {
            ...data,
            categories: data.categories || (fullData?.categories as AppDetailsData['categories']),
            genres: data.genres || (fullData?.genres as AppDetailsData['genres']),
            developers: data.developers || (fullData?.developers as string[]),
            publishers: data.publishers || (fullData?.publishers as string[]),
            release_date: data.release_date || (fullData?.release_date as AppDetailsData['release_date']),
            metacritic: data.metacritic || (fullData?.metacritic as AppDetailsData['metacritic']),
        }
    }

    /**
     * Build enhanced SteamGame object from base game + app details
     */
    private buildEnhancedGame(game: SteamGame, appDetails: AppDetailsData | undefined): SteamGame {
        const headerUrl = appDetails?.artwork?.header 
            || appDetails?.artwork?.capsule_v5 
            || appDetails?.artwork?.capsule
            || `https://cdn.akamai.steamstatic.com/steam/apps/${game.appid}/header.jpg`

        return {
            ...game,
            artwork: {
                icon: game.img_icon_url 
                    ? `https://steamcdn-a.akamaihd.net/steamcommunity/public/images/apps/${game.appid}/${game.img_icon_url}.jpg`
                    : '',
                logo: game.img_logo_url 
                    ? `https://steamcdn-a.akamaihd.net/steamcommunity/public/images/apps/${game.appid}/${game.img_logo_url}.jpg`
                    : '',
                header: headerUrl,
                library: `https://cdn.akamai.steamstatic.com/steam/apps/${game.appid}/library_600x900.jpg`
            },
            categories: appDetails?.categories,
            genres: appDetails?.genres,
            developers: appDetails?.developers,
            publishers: appDetails?.publishers,
            release_date: appDetails?.release_date,
            metacritic: appDetails?.metacritic,
            short_description: appDetails?.short_description
        }
    }

    /**
     * Load games with single-pass cache check and fetch
     * 
     * Optimized for fast cached loads:
     * 1. Single IndexedDB read for all games
     * 2. Only fetch games missing complete metadata
     * 3. Build enhanced game objects directly
     * 
     * @param steamUser - Steam user data with games list
     * @param options - maxGames limits display, onProgress for UI updates, onBatchReady for progressive batches
     */
    public async loadGamesProgressively(
        steamUser: SteamUser,
        options: {
            maxGames?: number
            /** Optional comparator to override default playtime-descending sort. */
            sortFn?: (a: SteamGame, b: SteamGame) => number
        } = {}
    ): Promise<SteamGame[]> {
        const { maxGames = 10, sortFn } = options
        const BATCH_SIZE = 18 // One shelf's worth

        const sortedGames = this.sortAndLimitGames(steamUser.games, maxGames, sortFn)
        const appids = sortedGames.map(g => g.appid)

        const { cachedAppids, uncachedAppids, cachedAppDetails } = await this.partitionByCache(appids)

        // Calculate total batches using per-phase rounding to match actual emission
        // This prevents off-by-one errors when cached+uncached rounds differently than total
        const cachedBatchCount = Math.ceil(cachedAppids.length / BATCH_SIZE)
        const uncachedBatchCount = Math.ceil(uncachedAppids.length / BATCH_SIZE)
        const totalBatchCount = cachedBatchCount + uncachedBatchCount

        // PHASE 1: Emit cached games immediately (cache-first for fast startup)
        let results: SteamGame[] = []
        if (cachedAppids.length > 0) {
            const cachedGames = await this.emitCachedGameBatches(
                sortedGames, cachedAppids, cachedAppDetails,
                totalBatchCount, BATCH_SIZE
            )
            results = cachedGames
        }

        // PHASE 2: Fetch uncached games in background (emit when ready)
        if (uncachedAppids.length > 0) {
            await this.fetchUncachedGamesInBackground(
                sortedGames, uncachedAppids, cachedAppids.length, totalBatchCount, BATCH_SIZE
            )
        }

        SteamApiClient.logger.info(`Loaded ${results.length} cached games, ${uncachedAppids.length} fetching in background`)
        return results
    }

    private sortAndLimitGames(games: SteamGame[], maxGames: number, sortFn?: (a: SteamGame, b: SteamGame) => number): SteamGame[] {
        const comparator = sortFn ?? ((a: SteamGame, b: SteamGame) => (b.playtime_forever ?? 0) - (a.playtime_forever ?? 0))
        return [...games]
            .sort(comparator)
            .slice(0, maxGames)
    }

    private async partitionByCache(appids: number[]): Promise<{
        cachedAppids: number[]
        uncachedAppids: number[]
        cachedAppDetails: Map<number, AppDetailsData>
    }> {
        const cachedAppDetails = await this.appDetailsCache.getMany(appids)
        const cachedAppids = appids.filter(id => this.isMetadataComplete(cachedAppDetails.get(id)))
        const uncachedAppids = appids.filter(id => !this.isMetadataComplete(cachedAppDetails.get(id)))

        if (uncachedAppids.length === 0) {
            SteamApiClient.logger.debug(`All ${appids.length} games have complete metadata in cache`)
        } else {
            SteamApiClient.logger.info(`Loading ${appids.length} games: ${cachedAppids.length} cached, ${uncachedAppids.length} to fetch`)
        }

        return { cachedAppids, uncachedAppids, cachedAppDetails }
    }

    private async emitCachedGameBatches(
        sortedGames: SteamGame[],
        cachedAppids: number[],
        cachedAppDetails: Map<number, AppDetailsData>,
        totalBatchCount: number,
        BATCH_SIZE: number
    ): Promise<SteamGame[]> {
        const buildMonitor = PerformanceMonitor.start('build-cached-games', SteamApiClient.logger, MAIN_THREAD_CONTEXT)
        const cachedGames = sortedGames.filter(g => cachedAppids.includes(g.appid))
        const cachedEnhanced: SteamGame[] = []

        // Build all cached games with metadata
        for (const game of cachedGames) {
            const enhancedGame = this.buildEnhancedGame(game, cachedAppDetails.get(game.appid))
            this.cache.set(`game_${game.appid}`, enhancedGame)
            cachedEnhanced.push(enhancedGame)
        }

        buildMonitor.end({ count: cachedEnhanced.length })

        // Emit cached games in batches with yielding
        // Note: Subscribers (GpuStorePropsRenderer.processOneBatch, etc.) are already instrumented
        const cachedBatches = Math.ceil(cachedEnhanced.length / BATCH_SIZE)

        for (let i = 0; i < cachedBatches; i++) {
            const batchGames = cachedEnhanced.slice(i * BATCH_SIZE, (i + 1) * BATCH_SIZE)
            const isLastCachedBatch = i === cachedBatches - 1

            EventManager.getInstance().emit<SteamGamesBatchEvent>(SteamEventTypes.GamesBatchReady, {
                games: batchGames as ReadonlyArray<Readonly<SteamGame>>,
                batchIndex: i,
                totalBatches: totalBatchCount
            })

            // Yield to main thread between batches
            if (!isLastCachedBatch) {
                await new Promise(resolve => setTimeout(resolve, 0))
            }
        }
        SteamApiClient.logger.info(`Emitted ${cachedEnhanced.length} cached games in ${cachedBatches} batches`)

        EventManager.getInstance().emit<SteamNetworkFetchProgressEvent>(SteamEventTypes.NetworkFetchProgress, {
            fetched: cachedAppids.length,
            total: sortedGames.length
        })

        return cachedEnhanced
    }

    private async fetchUncachedGamesInBackground(
        sortedGames: SteamGame[],
        uncachedAppids: number[],
        cachedAppidsCount: number,
        totalBatchCount: number,
        BATCH_SIZE: number
    ): Promise<void> {
        // Fetch metadata in background and emit events when ready
        this.fetchMetadataBackground(uncachedAppids, sortedGames, cachedAppidsCount, totalBatchCount, BATCH_SIZE)
            .catch(error => {
                SteamApiClient.logger.error('Background metadata fetch failed:', error)
            })
    }

    private async fetchMetadataBackground(
        uncachedAppids: number[],
        sortedGames: SteamGame[],
        cachedAppidsCount: number,
        totalBatchCount: number,
        BATCH_SIZE: number
    ): Promise<void> {
        // Background fetch starting for ${uncachedAppids.length} games
        // Note: Actual network timing tracked in BatchAppDetailsClient.fetchBatch -> network-batch

        try {
            const batchResponses = await this.batchClient.fetchBatch(uncachedAppids, {
                batchSize: 100
            })

            // Normalize and cache fetched metadata
            const fetchedAppDetails = new Map<number, AppDetailsData>()
            for (const [appid, response] of batchResponses.entries()) {
                fetchedAppDetails.set(appid, this.normalizeBatchData(response.data))
            }

            const cacheMonitor = PerformanceMonitor.start('cache-metadata', SteamApiClient.logger, ASYNC_CONTEXT)
            if (fetchedAppDetails.size > 0) {
                await this.appDetailsCache.setMany(fetchedAppDetails)
                cacheMonitor.end({ count: fetchedAppDetails.size })
            }

            // Build enhanced games with fetched metadata
            const uncachedGames = sortedGames.filter(g => uncachedAppids.includes(g.appid))
            const uncachedEnhanced: SteamGame[] = []

            for (const game of uncachedGames) {
                const enhancedGame = this.buildEnhancedGame(game, fetchedAppDetails.get(game.appid))
                this.cache.set(`game_${game.appid}`, enhancedGame)
                uncachedEnhanced.push(enhancedGame)
            }

            // Emit uncached games in batches (now that they have metadata)
            const uncachedBatches = Math.ceil(uncachedEnhanced.length / BATCH_SIZE)
            const startBatchIndex = Math.ceil(cachedAppidsCount / BATCH_SIZE)

            for (let i = 0; i < uncachedBatches; i++) {
                const batchGames = uncachedEnhanced.slice(i * BATCH_SIZE, (i + 1) * BATCH_SIZE)

                EventManager.getInstance().emit<SteamGamesBatchEvent>(SteamEventTypes.GamesBatchReady, {
                    games: batchGames as ReadonlyArray<Readonly<SteamGame>>,
                    batchIndex: startBatchIndex + i,
                    totalBatches: totalBatchCount
                })

                // Yield to main thread between batches
                if (i < uncachedBatches - 1) {
                    await new Promise(resolve => setTimeout(resolve, 0))
                }
            }

            SteamApiClient.logger.info(`[ASYNC] Emitted ${uncachedEnhanced.length} uncached games with metadata in ${uncachedBatches} batches`)

        } catch (error) {
            SteamApiClient.logger.error('[ASYNC] Background metadata fetch failed:', error)
            throw error
        }
    }

    /**
     * App details methods (for categories, genres, etc.)
     */
    public async getAppDetails(appid: number): Promise<AppDetailsData | null> {
        return this.appDetailsCache.get(appid)
    }

    public async getAppDetailsMany(appids: number[]): Promise<Map<number, AppDetailsData>> {
        return this.appDetailsCache.getMany(appids)
    }

    public async getAppDetailsCacheStats() {
        return this.appDetailsCache.getStats()
    }

    public async clearCache(): Promise<void> {
        this.cache.clear()
        await this.appDetailsCache.clear()
    }

    public getCacheStats() {
        return this.cache.getStats()
    }

    public getCacheManager(): CacheManager {
        return this.cache
    }

    public hasCached(key: string): boolean {
        return this.cache.get(key) !== null
    }

    public getCached<T>(key: string): T | null {
        return this.cache.get<T>(key)
    }

    public getAllCacheKeys(): string[] {
        return this.cache.getAllKeys()
    }

    public getCachedUsers(): Array<{ vanityUrl: string, displayName: string, gameCount: number, steamId: string }> {
        const cachedUsers: Array<{ vanityUrl: string, displayName: string, gameCount: number, steamId: string }> = []
        const userMap = new Map<string, { vanityUrl?: string, resolveData?: SteamResolveResponse, gamesData?: SteamUser }>()

        // Single pass through all cache keys to collect user data
        const allKeys = this.cache.getAllKeys()

        for (const key of allKeys) {
            if (key.startsWith('resolve_')) {
                const vanityUrl = key.replace('resolve_', '')
                const resolveData = this.cache.get<SteamResolveResponse>(key)
                if (resolveData && resolveData.steamid) {
                    const existing = userMap.get(resolveData.steamid) || {}
                    existing.vanityUrl = vanityUrl
                    existing.resolveData = resolveData
                    userMap.set(resolveData.steamid, existing)
                }
            } else if (key.startsWith('games_')) {
                const steamId = key.replace('games_', '')
                const gamesData = this.cache.get<SteamUser>(key)
                if (gamesData) {
                    const existing = userMap.get(steamId) || {}
                    existing.gamesData = gamesData
                    userMap.set(steamId, existing)
                }
            }
        }

        // Build final user list from users who have both resolve and games data
        for (const [steamId, userData] of userMap.entries()) {
            if (userData.resolveData && userData.gamesData) {
                cachedUsers.push({
                    vanityUrl: userData.vanityUrl || userData.gamesData.vanity_url || steamId,
                    displayName: userData.gamesData.vanity_url || userData.vanityUrl || steamId,
                    gameCount: userData.gamesData.game_count || 0,
                    steamId: steamId
                })
            }
        }

        return cachedUsers.sort((a, b) => a.displayName.localeCompare(b.displayName))
    }
}

// Export a default instance for convenience
export const steamApi = new SteamApiClient()

/**
 * Batch client for fetching Steam app details from Lambda cache
 * 
 * Provides efficient batch fetching of game metadata (categories, genres, etc.)
 * from the Lambda-cached Steam Store API data.
 */

import type { SteamGameMetadata } from '../types/SteamMetadata'
import { EventManager } from '../../core/EventManager'
import { SteamEventTypes } from '../../types/InteractionEvents'

export interface AppDetailsData extends SteamGameMetadata {
    name: string;
    type: string;
    is_free: boolean;
    artwork: {
        header: string | null;
        capsule: string | null;
        capsule_v5: string | null;
        background: string | null;
        background_raw: string | null;
    };
    // Additional fields from Steam Store API
    full_data?: Record<string, unknown>;
    [key: string]: unknown;
}

export interface BatchAppDetailsOptions {
    /**
     * Batch size for requests (recommended 50-100 for optimal performance)
     * Lambda checks cache first (instant), then rate-limits uncached Steam API calls (10 at a time)
     * Larger batches = fewer round trips, better for cache-heavy scenarios
     * First-time hydration: use 50 (mostly uncached). Subsequent: use 100+ (mostly cached)
     */
    batchSize?: number;

    /**
     * Callback for batch progress
     */
    onProgress?: (fetched: number, total: number) => void;

    /**
     * Callback for individual game data received
     */
    onGameData?: (appid: number, data: AppDetailsData) => void;
}

export interface AppDetailsResponse {
    success: boolean;
    appid: number;
    data: AppDetailsData;
    retrieved_at: string;
}

export interface BatchAppDetailsResult {
    success: boolean;
    total_requested: number;
    total_successful: number;
    total_failed: number;
    cache_hits?: number;
    cache_misses?: number;
    results: AppDetailsResponse[];
    failed?: Array<{ appid: number; error: string }>;
    timestamp: string;
}

import { Logger } from '../../utils/Logger'
import { PerformanceMonitor, ASYNC_CONTEXT } from '../../utils/PerformanceMonitor'

export class BatchAppDetailsClient {
    private static readonly logger = Logger.createLogFunctions(BatchAppDetailsClient.name)
    private apiBaseUrl: string;
    private eventManager: EventManager;

    constructor(apiBaseUrl: string = 'https://steam-api-dev.wehrly.com', eventManager?: EventManager) {
        this.apiBaseUrl = apiBaseUrl;
        this.eventManager = eventManager || EventManager.getInstance();
    }

    /**
     * Fetch app details for multiple games in batches
     * 
     * @param appids - Array of Steam app IDs to fetch
     * @param options - Batch options (size, callbacks)
     * @returns Map of appid -> app details data
     */
    async fetchBatch(
        appids: number[],
        options: BatchAppDetailsOptions = {}
    ): Promise<Map<number, AppDetailsResponse>> {
        const {
            batchSize = 100, // Increased: Lambda handles cached games instantly
            onProgress,
            onGameData
        } = options;

        const results = new Map<number, AppDetailsResponse>();

        // Split into batches
        const batches: number[][] = [];
        for (let i = 0; i < appids.length; i += batchSize) {
            batches.push(appids.slice(i, i + batchSize));
        }

        // Note: Individual batches are tracked with 'network-batch' monitor per batch
        if (batches.length > 0) {
            BatchAppDetailsClient.logger.info(`[ASYNC] Fetching ${appids.length} uncached games from Steam API (${batches.length} network ${batches.length === 1 ? 'batch' : 'batches'})...`)
        }

        let totalFetched = 0;
        let consecutiveFailures = 0;
        let lastBatchDuration: number; // Track response time for adaptive delays
        const MAX_CONSECUTIVE_FAILURES = 3; // Circuit breaker threshold
        const FAST_RESPONSE_THRESHOLD = 2000; // If batch returns in <2s, it's mostly cached

        // Process batches sequentially to respect rate limits
        for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
            // Circuit breaker: stop if too many consecutive failures
            if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
                console.error(`≡ƒÜ¿ [BatchAppDetails] Circuit breaker triggered after ${consecutiveFailures} consecutive failures. Stopping batch processing.`);
                break;
            }

            const batch = batches[batchIndex];
            const batchMonitor = PerformanceMonitor.start('network-batch', BatchAppDetailsClient.logger, ASYNC_CONTEXT)

            BatchAppDetailsClient.logger.info(`[ASYNC] Starting network batch ${batchIndex + 1}/${batches.length}: Requesting ${batch.length} games from Steam API...`);

            // Emit event for UI visibility
            this.eventManager.emit(SteamEventTypes.NetworkFetchProgress, {
                fetched: totalFetched,
                total: appids.length,
                timestamp: Date.now()
            });

            try {
                const batchResult = await this.fetchSingleBatch(batch);
                lastBatchDuration = batchMonitor.getElapsed();

                // Process successful results
                for (const game of batchResult.results) {
                    results.set(game.appid, game);
                    onGameData?.(game.appid, game.data);
                }

                totalFetched += batchResult.total_successful;

                // Calculate total work: if fetching N games in parallel, total work Γëê N ├ù elapsed
                // (Each game's metadata fetch would take ~elapsed ms if done sequentially)
                const totalWork = batch.length * lastBatchDuration;

                batchMonitor.end({
                    batch: `${batchIndex + 1}/${batches.length}`,
                    successful: `${batchResult.total_successful}/${batch.length}`,
                    total: `${totalFetched}/${appids.length}`
                }, totalWork);
                onProgress?.(totalFetched, appids.length);

                // Emit progress event for UI
                this.eventManager.emit(SteamEventTypes.NetworkFetchProgress, {
                    fetched: totalFetched,
                    total: appids.length,
                    timestamp: Date.now()
                });

                // Log cache performance
                if (batchResult.cache_hits !== undefined && batchResult.cache_misses !== undefined) {
                    const cacheHitRate = batchResult.cache_hits / (batchResult.cache_hits + batchResult.cache_misses) * 100;
                    BatchAppDetailsClient.logger.debug(`Batch ${batchIndex + 1} cache: ${batchResult.cache_hits} hits, ${batchResult.cache_misses} misses (${cacheHitRate.toFixed(1)}% hit rate) in ${lastBatchDuration.toFixed(0)}ms`)
                }

                if (batchResult.failed && batchResult.failed.length > 0) {
                    BatchAppDetailsClient.logger.warn(`Batch ${batchIndex + 1} had ${batchResult.failed.length} failures: ${batchResult.failed.map(f => `${f.appid}: ${f.error}`).join(', ')}`)
                }

                consecutiveFailures = 0; // Reset on success

                // Adaptive delay: skip delay if responses are fast (cached), add delay if slow (uncached)
                if (batchIndex < batches.length - 1) {
                    if (lastBatchDuration < FAST_RESPONSE_THRESHOLD) {
                        // Fast response = mostly cached, minimal delay needed
                        await new Promise(resolve => setTimeout(resolve, 50));
                    } else {
                        // Slow response = uncached API calls, add backoff delay
                        const baseDelay = 200;
                        const backoffDelay = Math.min(baseDelay * Math.pow(1.5, consecutiveFailures), 2000);
                        await new Promise(resolve => setTimeout(resolve, backoffDelay));
                    }
                }

            } catch (error) {
                consecutiveFailures++;
                BatchAppDetailsClient.logger.error(`Batch ${batchIndex + 1} failed: ${String(error)}`)

                // Exponential backoff on failure (max 5 seconds)
                const backoffDelay = Math.min(1000 * Math.pow(2, consecutiveFailures - 1), 5000);
                BatchAppDetailsClient.logger.debug(`Waiting ${backoffDelay}ms before next batch due to failure...`)
                await new Promise(resolve => setTimeout(resolve, backoffDelay));
            }
        }

        if (results.size < appids.length) {
            BatchAppDetailsClient.logger.warn(`${appids.length - results.size} games failed to fetch`);
        }
        return results;
    }

    /**
     * Fetch a single batch via Lambda endpoint
     */
    private async fetchSingleBatch(appids: number[]): Promise<BatchAppDetailsResult> {
        const url = `${this.apiBaseUrl}/batch-appdetails?appids=${appids.join(',')}`;

        // Set 35s timeout (Lambda has 30s, API Gateway has 30s max)
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 35000);

        try {
            const response = await fetch(url, {
                method: 'GET',
                headers: {
                    'Accept': 'application/json'
                },
                signal: controller.signal
            });

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`)
            }

            return await response.json();
        } finally {
            clearTimeout(timeoutId);
        }
    }

    /**
     * Fetch details for a single app (fallback to individual endpoint)
     */
    async fetchSingle(appid: number): Promise<AppDetailsResponse | null> {
        try {
            const response = await fetch(`${this.apiBaseUrl}/appdetails/${appid}`, {
                method: 'GET',
                headers: {
                    'Accept': 'application/json'
                }
            });

            if (!response.ok) {
                BatchAppDetailsClient.logger.warn(`Single fetch failed for ${appid}: ${response.status}`)
                return null;
            }

            return await response.json();
        } catch (error) {
            BatchAppDetailsClient.logger.error(`Error fetching appid ${appid}: ${String(error)}`)
            return null;
        }
    }
}

/**
 * Client-side cache for Steam app details (categories, genres, artwork URLs, etc.)
 * 
 * Stores the metadata from batch-appdetails endpoint locally to avoid repeated
 * Lambda calls. Uses IndexedDB for persistence across sessions.
 */

import type { AppDetailsData } from '../batch/BatchAppDetailsClient'

interface CachedAppDetails {
    appid: number
    data: AppDetailsData
    cached_at: number
}

export class AppDetailsCache {
    private static readonly DB_NAME = 'steam-app-details-cache'
    private static readonly DB_VERSION = 1
    private static readonly STORE_NAME = 'appdetails'

    private db: IDBDatabase | null = null
    private initPromise: Promise<void> | null = null

    /**
     * Initialize IndexedDB connection
     */
    async init(): Promise<void> {
        if (this.db) return
        if (this.initPromise) return this.initPromise

        this.initPromise = new Promise((resolve, reject) => {
            const request = indexedDB.open(AppDetailsCache.DB_NAME, AppDetailsCache.DB_VERSION)

            request.onerror = () => {
                console.error('Γ¥î [AppDetailsCache] Failed to open IndexedDB:', request.error)
                this.initPromise = null
                reject(request.error)
            }

            request.onsuccess = () => {
                const db = request.result

                // Verify the object store exists before marking as ready
                if (!db.objectStoreNames.contains(AppDetailsCache.STORE_NAME)) {
                    console.error('Γ¥î [AppDetailsCache] Object store missing - database schema not upgraded')
                    db.close()
                    this.initPromise = null
                    reject(new Error('Database schema not initialized'))
                    return
                }

                this.db = db
                console.log('Γ£à [AppDetailsCache] IndexedDB initialized')
                resolve()
            }

            request.onupgradeneeded = (event) => {
                const db = (event.target as IDBOpenDBRequest).result

                if (!db.objectStoreNames.contains(AppDetailsCache.STORE_NAME)) {
                    const store = db.createObjectStore(AppDetailsCache.STORE_NAME, { keyPath: 'appid' })
                    store.createIndex('cached_at', 'cached_at', { unique: false })
                    console.log('≡ƒôª [AppDetailsCache] Created object store')
                }
            }
        })

        return this.initPromise
    }

    /**
     * Get cached app details for a single game
     */
    async get(appid: number): Promise<AppDetailsData | null> {
        await this.init()
        if (!this.db) return null

        return new Promise((resolve) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readonly')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)
            const request = store.get(appid)

            request.onsuccess = () => {
                const cached = request.result as CachedAppDetails | undefined
                resolve(cached ? cached.data : null)
            }

            request.onerror = () => {
                console.error(`Γ¥î [AppDetailsCache] Failed to get appid ${appid}:`, request.error)
                resolve(null)
            }
        })
    }

    /**
     * Get cached app details for multiple games
     */
    async getMany(appids: number[]): Promise<Map<number, AppDetailsData>> {
        await this.init()
        const results = new Map<number, AppDetailsData>()

        if (!this.db) return results

        return new Promise((resolve) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readonly')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)

            let completed = 0
            const total = appids.length

            for (const appid of appids) {
                const request = store.get(appid)

                request.onsuccess = () => {
                    const cached = request.result as CachedAppDetails | undefined

                    // Add cached data if it exists (no expiration)
                    if (cached) {
                        results.set(appid, cached.data)
                    }

                    completed++
                    if (completed === total) {
                        if (results.size > 0 && results.size < total) {
                            console.log(`≡ƒôï [AppDetailsCache] Cache: ${results.size}/${total} games`);
                        }
                        resolve(results)
                    }
                }

                request.onerror = () => {
                    completed++
                    if (completed === total) {
                        resolve(results)
                    }
                }
            }
        })
    }

    /**
     * Store app details for a single game
     */
    async set(appid: number, data: AppDetailsData): Promise<void> {
        await this.init()
        if (!this.db) return

        const cached: CachedAppDetails = {
            appid,
            data,
            cached_at: Date.now()
        }

        return new Promise((resolve, _reject) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readwrite')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)
            const request = store.put(cached)

            request.onsuccess = () => {
                resolve()
            }

            request.onerror = () => {
                console.error(`Γ¥î [AppDetailsCache] Failed to cache appid ${appid}:`, request.error)
                _reject(request.error)
            }
        })
    }

    /**
     * Store app details for multiple games
     */
    async setMany(dataMap: Map<number, AppDetailsData>): Promise<void> {
        await this.init()
        if (!this.db || dataMap.size === 0) return

        return new Promise((resolve) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readwrite')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)

            let completed = 0
            const total = dataMap.size
            const now = Date.now()

            for (const [appid, data] of dataMap.entries()) {
                const cached: CachedAppDetails = {
                    appid,
                    data,
                    cached_at: now
                }

                const request = store.put(cached)

                request.onsuccess = () => {
                    completed++
                    if (completed === total) {
                        resolve()
                    }
                }

                request.onerror = () => {
                    completed++
                    if (completed === total) {
                        resolve()
                    }
                }
            }
        })
    }

    /**
     * Clear all cached app details
     */
    async clear(): Promise<void> {
        await this.init()
        if (!this.db) return

        return new Promise((resolve, _reject) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readwrite')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)
            const request = store.clear()

            request.onsuccess = () => {
                console.log('≡ƒùæ∩╕Å [AppDetailsCache] Cleared all cached app details')
                resolve()
            }

            request.onerror = () => {
                console.error('Γ¥î [AppDetailsCache] Failed to clear cache:', request.error)
                _reject(request.error)
            }
        })
    }

    /**
     * Get cache statistics
     */
    async getStats(): Promise<{ count: number; oldestEntry: number | null; newestEntry: number | null }> {
        await this.init()
        if (!this.db) return { count: 0, oldestEntry: null, newestEntry: null }

        return new Promise((resolve) => {
            const transaction = this.db.transaction([AppDetailsCache.STORE_NAME], 'readonly')
            const store = transaction.objectStore(AppDetailsCache.STORE_NAME)
            const countRequest = store.count()

            countRequest.onsuccess = () => {
                const count = countRequest.result

                if (count === 0) {
                    resolve({ count: 0, oldestEntry: null, newestEntry: null })
                    return
                }

                const index = store.index('cached_at')
                const oldestRequest = index.openCursor(null, 'next')
                const newestRequest = index.openCursor(null, 'prev')

                let oldest: number | null = null
                let newest: number | null = null

                oldestRequest.onsuccess = () => {
                    if (oldestRequest.result) {
                        oldest = (oldestRequest.result.value as CachedAppDetails).cached_at
                    }

                    newestRequest.onsuccess = () => {
                        if (newestRequest.result) {
                            newest = (newestRequest.result.value as CachedAppDetails).cached_at
                        }
                        resolve({ count, oldestEntry: oldest, newestEntry: newest })
                    }
                }
            }

            countRequest.onerror = () => {
                resolve({ count: 0, oldestEntry: null, newestEntry: null })
            }
        })
    }
}

/**
 * Transparent caching layer that can instrument any method
 * Handles localStorage persistence and cache invalidation
 */

export interface CacheConfig {
    /** Cache duration in milliseconds (default: 1 hour) */
    cacheDuration: number;
    /** Enable localStorage caching (default: true) */
    enableCache: boolean;
    /** Cache key prefix for localStorage */
    cachePrefix: string;
}

export interface CacheEntry<T> {
    data: T;
    timestamp: number;
}

export interface CacheStats {
    totalEntries: number;
    resolveEntries: number;
    gamesEntries: number;
    oldestEntry: number | null;
    newestEntry: number | null;
    totalSize: number;
}

export class CacheManager {
    private cache: Map<string, CacheEntry<any>> = new Map();
    private readonly config: CacheConfig;

    constructor(config: Partial<CacheConfig> = {}) {
        this.config = {
            cacheDuration: 60 * 60 * 1000, // 1 hour default
            enableCache: true,
            cachePrefix: 'steam_api_cache_',
            ...config
        };
        
        if (this.config.enableCache && typeof localStorage !== 'undefined') {
            this.loadFromStorage();
        }
    }

    /**
     * Wrap a method with caching
     */
    cached<TArgs extends any[], TReturn>(
        keyGenerator: (...args: TArgs) => string,
        method: (...args: TArgs) => Promise<TReturn>
    ) {
        return async (...args: TArgs): Promise<TReturn> => {
            if (!this.config.enableCache) {
                return method(...args);
            }

            const key = keyGenerator(...args);
            const cached = this.get<TReturn>(key);
            
            if (cached !== null) {
                return cached;
            }

            const result = await method(...args);
            this.set(key, result);
            return result;
        };
    }

    /**
     * Set cache entry
     */
    set<T>(key: string, data: T): void {
        if (!this.config.enableCache) return;

        const entry: CacheEntry<T> = {
            data,
            timestamp: Date.now(),
        };

        this.cache.set(this.config.cachePrefix + key, entry);
        this.updateStorage();
    }

    /**
     * Get cache entry
     */
    get<T>(key: string): T | null {
        const entry = this.cache.get(this.config.cachePrefix + key);
        if (!entry) return null;

        // Check expiration
        const isExpired = (Date.now() - entry.timestamp) > this.config.cacheDuration;
        if (isExpired) {
            this.cache.delete(this.config.cachePrefix + key);
            return null;
        }

        return entry.data;
    }

    /**
     * Clear all cache
     */
    clear(): void {
        this.cache.clear();
        if (typeof localStorage !== 'undefined') {
            const keysToRemove: string[] = [];
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (key?.startsWith(this.config.cachePrefix)) {
                    keysToRemove.push(key);
                }
            }
            keysToRemove.forEach(key => localStorage.removeItem(key));
        }
    }

    /**
     * Get cache statistics
     */
    getStats(): CacheStats {
        const entries = Array.from(this.cache.entries());
        const resolveEntries = entries.filter(([key]) => key.includes('resolve_')).length;
        const gamesEntries = entries.filter(([key]) => key.includes('games_')).length;
        
        const timestamps = entries.map(([, entry]) => entry.timestamp);
        const oldestEntry = timestamps.length > 0 ? Math.min(...timestamps) : null;
        const newestEntry = timestamps.length > 0 ? Math.max(...timestamps) : null;
        
        // Approximate size calculation
        const totalSize = entries.reduce((size, [key, entry]) => {
            return size + key.length + JSON.stringify(entry).length;
        }, 0) * 2; // Multiply by 2 for rough UTF-16 encoding size
        
        return {
            totalEntries: entries.length,
            resolveEntries,
            gamesEntries,
            oldestEntry,
            newestEntry,
            totalSize
        };
    }

    private updateStorage(): void {
        if (!this.config.enableCache || typeof localStorage === 'undefined') return;
        
        const state = JSON.stringify(Array.from(this.cache.entries()));
        localStorage.setItem(this.config.cachePrefix + 'state', state);
    }

    private loadFromStorage(): void {
        if (typeof localStorage === 'undefined') return;
        
        const state = localStorage.getItem(this.config.cachePrefix + 'state');
        if (!state) return;

        try {
            const entries = JSON.parse(state) as [string, CacheEntry<any>][];
            for (const [key, entry] of entries) {
                this.cache.set(key, entry);
            }
        } catch (error) {
            // Clear corrupted cache
            localStorage.removeItem(this.config.cachePrefix + 'state');
        }
    }
}

/**
 * Generic caching layer that can wrap any method with caching functionality
 */

// Cross-platform timeout type that works in both Node.js and browser environments
type TimeoutHandle = ReturnType<typeof setTimeout>

export interface CacheConfig {
    /** Cache duration in milliseconds (default: 1 hour) */
    cacheDuration: number
    /** Enable localStorage caching (default: true) */
    enableCache: boolean
    /** Cache key prefix for localStorage */
    cachePrefix: string
    /** Maximum cache size in bytes (default: 100MB) */
    maxCacheSize: number
    /** Maximum number of cache entries (default: 1000) */
    maxEntries: number
}

export interface CacheEntry<T> {
    data: T
    timestamp: number
    lastAccessed: number
    size?: number // Estimated size in bytes
}

export interface CacheStats {
    totalEntries: number
    totalSize: number
    cacheHits: number
    cacheMisses: number
}

/**
 * Generic caching layer that can wrap any method with caching functionality
 */
export class CacheManager {
    private cache: Map<string, CacheEntry<any>> = new Map()
    private readonly config: CacheConfig
    private pendingWrites: boolean = false
    private writeTimeout: TimeoutHandle | null = null
    private readonly WRITE_DEBOUNCE_MS = 2000 // 2 seconds

    constructor(config: Partial<CacheConfig> = {}) {
        this.config = {
            cacheDuration: 60 * 60 * 1000, // 1 hour default
            enableCache: true,
            cachePrefix: 'cache_',
            maxCacheSize: 100 * 1024 * 1024, // 100MB default
            maxEntries: 1000, // 1000 entries default
            ...config
        }
        
        if (this.config.enableCache && typeof localStorage !== 'undefined') {
            this.loadFromStorage()
            
            // Save immediately on page unload to prevent data loss
            if (typeof window !== 'undefined') {
                window.addEventListener('beforeunload', () => {
                    this.saveImmediately()
                })
            }
        }
    }

    /**
     * Wrap any async function with caching
     */
    withCache<TArgs extends any[], TResult>(
        fn: (...args: TArgs) => Promise<TResult>,
        getCacheKey: (...args: TArgs) => string
    ): (...args: TArgs) => Promise<TResult> {
        return async (...args: TArgs): Promise<TResult> => {
            const cacheKey = getCacheKey(...args)
            
            // Try cache first
            const cached = this.get<TResult>(cacheKey)
            if (cached) {
                return cached
            }
            
            // Execute function and cache result
            const result = await fn(...args)
            this.set(cacheKey, result)
            return result
        }
    }

    /**
     * Get from cache
     */
    get<T>(key: string): T | null {
        if (!this.config.enableCache) {
            return null
        }
        
        const fullKey = this.config.cachePrefix + key
        const entry = this.cache.get(fullKey)
        if (!entry) {
            return null
        }
        
        // Check expiration
        const age = performance.now() - entry.timestamp
        if (age > this.config.cacheDuration) {
            this.cache.delete(fullKey)
            return null
        }
        
        // Update access time for LRU tracking
        entry.lastAccessed = performance.now()
        
        return entry.data
    }

    /**
     * Set cache entry
     */
    set<T>(key: string, data: T): void {
        if (!this.config.enableCache) {
            return
        }
        
        const now = performance.now()
        const entry: CacheEntry<T> = {
            data,
            timestamp: now,
            lastAccessed: now,
            size: this.estimateSize(data)
        }
        
        const fullKey = this.config.cachePrefix + key
        this.cache.set(fullKey, entry)
        
        // Defer cache resolution (size limits + storage) to avoid blocking
        this.deferCacheResolution()
    }

    /**
     * Clear all cache
     */
    clear(): void {
        this.cache.clear()
        this.saveImmediately() // Save immediately on clear
    }

    /**
     * Force immediate save to storage (for critical operations)
     */
    saveImmediately(): void {
        if (this.writeTimeout) {
            clearTimeout(this.writeTimeout)
            this.writeTimeout = null
        }
        this.pendingWrites = false
        
        // Perform immediate cache resolution (size management + storage)
        this.performCacheResolution()
    }

    /**
     * Get cache statistics including size information
     */
    getStats(): CacheStats {
        const totalSize = Array.from(this.cache.values())
            .reduce((sum, entry) => sum + (entry.size || 0), 0)
        
        return {
            totalEntries: this.cache.size,
            totalSize,
            cacheHits: 0, // Could track this if needed
            cacheMisses: 0 // Could track this if needed
        }
    }

    /**
     * Estimate size of data in bytes
     */
    private estimateSize<T>(data: T): number {
        try {
            // Simple estimation using JSON string length
            const jsonString = JSON.stringify(data)
            return jsonString.length * 2 // UTF-16 characters are 2 bytes each
        } catch (error) {
            // Fallback for non-serializable data
            return 1024 // 1KB default estimate
        }
    }

    /**
     * Enforce cache size limits using LRU eviction
     */
    private enforceSizeLimits(): void {
        // Check entry count limit
        if (this.cache.size > this.config.maxEntries) {
            const entriesToEvict = this.cache.size - this.config.maxEntries
            this.evictLRUEntries(entriesToEvict)
        }

        // Check size limit
        const currentSize = this.calculateTotalSize()
        if (currentSize > this.config.maxCacheSize) {
            // Evict entries until we're under the limit
            this.evictBySize(this.config.maxCacheSize * 0.8) // Target 80% of max to avoid frequent evictions
        }
    }

    /**
     * Calculate total cache size in bytes
     */
    private calculateTotalSize(): number {
        return Array.from(this.cache.values())
            .reduce((sum, entry) => sum + (entry.size || 0), 0)
    }

    /**
     * Evict least recently used entries
     */
    private evictLRUEntries(count: number): void {
        // Sort entries by lastAccessed time (oldest first)
        const sortedEntries = Array.from(this.cache.entries())
            .sort(([, a], [, b]) => a.lastAccessed - b.lastAccessed)

        // Remove the oldest entries
        for (let i = 0; i < Math.min(count, sortedEntries.length); i++) {
            const [key] = sortedEntries[i]
            this.cache.delete(key)
        }
    }

    /**
     * Evict entries by size until target size is reached
     */
    private evictBySize(targetSize: number): void {
        // Sort entries by lastAccessed time (oldest first)
        const sortedEntries = Array.from(this.cache.entries())
            .sort(([, a], [, b]) => a.lastAccessed - b.lastAccessed)

        let currentSize = this.calculateTotalSize()
        
        for (const [key, entry] of sortedEntries) {
            if (currentSize <= targetSize) {
                break
            }
            
            this.cache.delete(key)
            currentSize -= (entry.size || 0)
        }
    }

    /**
     * Defer cache resolution (size management + storage) to avoid blocking operations
     */
    private deferCacheResolution(): void {
        // Clear any existing timeout
        if (this.writeTimeout) {
            clearTimeout(this.writeTimeout)
            this.writeTimeout = null
        }

        this.pendingWrites = true

        this.writeTimeout = setTimeout(this.performCacheResolution.bind(this), this.WRITE_DEBOUNCE_MS)
    }

    /**
     * Named timeout handler for cache resolution (for better debugging)
     */
    private performCacheResolution(): void {
        // Enforce size limits first
        this.enforceSizeLimits()
        
        // Then save to storage
        this.saveToStorage()
        
        // Reset state
        this.pendingWrites = false
        this.writeTimeout = null
    }

    /**
     * Get all cache keys (without prefix)
     */
    getAllKeys(): string[] {
        return Array.from(this.cache.keys()).map(key => key.replace(this.config.cachePrefix, ''))
    }

    private loadFromStorage(): void {
        try {
            const stored = localStorage.getItem('cache_state')
            if (stored) {
                const entries = JSON.parse(stored)
                this.cache = new Map(entries)
            }
        } catch (error) {
            console.warn('Failed to load cache from storage:', error)
        }
    }

    private saveToStorage(): void {
        try {
            if (typeof localStorage !== 'undefined') {
                if (this.cache.size === 0) {    // no cache to store
                    localStorage.removeItem('cache_state')
                } else {
                    const entries = Array.from(this.cache.entries())
                    localStorage.setItem('cache_state', JSON.stringify(entries))
                }
            }
        } catch (error) {
            console.warn('Failed to save cache to storage:', error)
        }
    }
}

/**
 * Base HTTP client for API requests
 * Handles timeouts, CORS, and basic error handling
 */

export interface HttpClientOptions {
    baseUrl: string;
    timeout?: number;
    defaultHeaders?: Record<string, string>;
}

export class HttpClient {
    private readonly baseUrl: string;
    private readonly timeout: number;
    private readonly defaultHeaders: Record<string, string>;

    constructor(options: HttpClientOptions) {
        this.baseUrl = options.baseUrl;
        this.timeout = options.timeout || 10000;
        this.defaultHeaders = options.defaultHeaders || {
            'Accept': 'application/json'
        };
    }

    async makeRequest<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
        const url = `${this.baseUrl}${endpoint}`;

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        try {
            const response = await fetch(url, {
                method: 'GET',
                headers: {
                    ...this.defaultHeaders,
                    'Origin': window.location.origin,
                },
                signal: controller.signal,
                ...options
            });

            clearTimeout(timeoutId);

            if (!response.ok) {
                let errorMessage: string;
                try {
                    const errorData = await response.json();
                    errorMessage = errorData.message || `HTTP ${response.status}: ${response.statusText}`;
                } catch {
                    errorMessage = `HTTP ${response.status}: ${response.statusText}`;
                }
                throw new Error(errorMessage);
            }

            return await response.json() as T;

        } catch (error) {
            clearTimeout(timeoutId);

            if (error instanceof Error) {
                if (error.name === 'AbortError') {
                    throw new Error(`Request timeout after ${this.timeout}ms`, { cause: error });
                }
                throw error;
            }

            throw new Error('Unknown error occurred during API request', { cause: error });
        }
    }
}

