    private buildHTML(): string {
        const renderRows = (entries: CategoryEntry[]): string =>
            entries.map(e => `
                <tr class="cat-row cat-row--${e.status}">
                    <td class="cat-label">${e.label}</td>
                    <td class="cat-status">${e.status}</td>
                    <td class="cat-desc">${e.description}</td>
