            `).join('')

        return `
            <div class="cat-ref-header">
                <span>≡ƒÅ╖∩╕Å Category Reference</span>
                <button class="cat-ref-close" title="Close">Γ£ò</button>
            </div>
            <div class="cat-ref-body">

                <section class="cat-section">
                    <h3>Steam Genres <span class="cat-count">(${STEAM_GENRE_CATEGORIES.length})</span></h3>
                    <p class="cat-section-note">Matched case-insensitively from <code>genres[0].description</code>. Unrecognised ΓåÆ Other.</p>
                    <table class="cat-table">
                        <thead><tr><th>Label</th><th>Status</th><th>Notes</th></tr></thead>
                        <tbody>${renderRows(STEAM_GENRE_CATEGORIES)}</tbody>
                    </table>
                </section>

                <section class="cat-section">
                    <h3>Meta / Library-State Categories</h3>
                    <p class="cat-section-note">Based on library data (playtime, date added, etc.), not Steam genre tags.</p>
                    <table class="cat-table">
                        <thead><tr><th>Label</th><th>Status</th><th>Notes</th></tr></thead>
                        <tbody>${renderRows(META_CATEGORIES)}</tbody>
                    </table>
                </section>

                <section class="cat-section">
                    <h3>Sort Dimensions</h3>
                    <p class="cat-section-note">These are better as sort/filter controls than as shelves. Design TBD.</p>
                    <table class="cat-table">
                        <thead><tr><th>Label</th><th>Status</th><th>Notes</th></tr></thead>
                        <tbody>${renderRows(SORT_DIMENSIONS)}</tbody>
                    </table>
                </section>

            </div>
        `
    }

    private toggle(): void {
        this.isOpen = !this.isOpen
        this.container?.classList.toggle('hidden', !this.isOpen)
        if (this.toggleButton) {
            this.toggleButton.classList.toggle('active', this.isOpen)
        }
        if (this.isOpen) {
            // Wire close button each time we open (innerHTML is static so it survives)
            const closeBtn = this.container?.querySelector('.cat-ref-close')
            closeBtn?.addEventListener('click', () => this.toggle(), { once: true })
        }
    }

    public dispose(): void {
        if (this.keyboardHandler) {
            document.removeEventListener('keydown', this.keyboardHandler)
        }
        this.container?.remove()
        this.toggleButton?.remove()
    }
}

/**
 * Lighting Controls Panel - Real-time lighting control interface
 * 
 * Provides granular control over individual lights and light groups:
 * - Toggle individual lights on/off
 * - Group lights by type (RectAreaLight, SpotLight, etc.)
 * - Master controls for entire light types
 * - Real-time updates with scene integration
 * 
 * Uses LightRegistry for O(1) lookups instead of scene traversal.
 */

import * as THREE from 'three'
import { EventManager, EventSource } from '../core/EventManager'
import { LightingEventTypes, type LightCreatedEvent, type LightingSystemReadyEvent } from '../types/LightingEvents'
import { AppSettings } from '../core/AppSettings'
import { LightRegistry } from '../lighting/LightRegistry'
import { Logger } from '../utils/Logger'
import '../styles/lighting-controls-panel.css'

interface LightGroupInfo {
    type: string
    lights: THREE.Light[]
    enabled: boolean
    collapsed: boolean
}

export class LightingControlsPanel {
    public static logger = Logger.createLogFunctions(LightingControlsPanel.name)
    private container: HTMLElement
    private scene: THREE.Scene | null = null
    private lightGroups: Map<string, LightGroupInfo> = new Map()
    private eventManager: EventManager
    private lightCreatedHandler: (event: CustomEvent<LightCreatedEvent>) => void
    private lightingSystemReadyHandler: (event: CustomEvent<LightingSystemReadyEvent>) => void

    private appSettings: AppSettings
    private debugIndicatorEnabled: boolean
    private panelCollapsed: boolean = true
    private horizontallyCollapsed: boolean = true
    private checkboxUpdatePending: number | null = null

    // Use central registry for light and debug helper lookups
    private registry: LightRegistry

    constructor(eventManager: EventManager, appSettings: AppSettings) {
        this.eventManager = eventManager
        this.registry = LightRegistry.getInstance()
        this.lightCreatedHandler = this.onLightCreated.bind(this)
        this.lightingSystemReadyHandler = this.onLightingSystemReady.bind(this)
        this.appSettings = appSettings
        this.debugIndicatorEnabled = this.appSettings.getSetting('showLightingDebug') ?? false
        this.panelCollapsed = true
        this.horizontallyCollapsed = true
        this.container = this.createPanel()
        this.setupEventListeners()
        // No initial scan - we'll scan when we get the first light event or system ready event
    }

    private createPanel(): HTMLElement {
        const panel = document.createElement('div')
        panel.id = 'lighting-controls-panel'
        panel.className = 'lighting-controls-panel horizontally-collapsed'
        panel.innerHTML = `
            <div class="panel-header clickable-header" id="lighting-panel-header">
                <h3><span class="panel-icon">≡ƒÆí</span><span class="panel-title"> Lighting Controls</span></h3>
                <div class="header-controls">
                    <button class="refresh-button" id="refresh-lights">≡ƒöä</button>
                    <span class="toggle-indicator" id="toggle-indicator">Γû╢</span>
                </div>
            </div>
            <div class="panel-content collapsed" id="lighting-panel-content">
                <div class="master-controls">
                    <label class="control-item">
                        <input type="checkbox" id="all-lights-toggle">
                        <span class="control-label">All Lights</span>
                    </label>
                    <label class="control-item">
                        <input type="checkbox" id="debug-indicator-toggle" ${this.debugIndicatorEnabled ? 'checked' : ''}>
                        <span class="control-label">Show Debug Indicators</span>
                    </label>
                </div>
                <div class="light-groups" id="light-groups-container">
                    <!-- Light groups with nested individual lights will be populated here -->
                </div>
            </div>
        `

        // Hide the separate lighting controls button since we're integrating it into the panel
        const separateButton = document.getElementById('lighting-controls-button')
        if (separateButton) {
            separateButton.style.display = 'none'
        }

        // Styles are now loaded from external CSS file

        const slot = document.getElementById('ui-right-center-group') ?? document.getElementById('ui-slot-top-right')
        if (slot) {
            slot.appendChild(panel)
        } else {
            document.body.appendChild(panel)
        }
        this.attachEventHandlers()
        return panel
    }

    private attachEventHandlers(): void {
        // Header click to toggle panel
        const panelHeader = document.getElementById('lighting-panel-header')
        if (panelHeader) {
            panelHeader.addEventListener('click', (e) => {
                // Don't toggle if clicking on the refresh button
                if ((e.target as HTMLElement).classList.contains('refresh-button')) {
                    return
                }
                this.togglePanelContent()
            })
        }

        // Master toggle
        const allLightsToggle = document.getElementById('all-lights-toggle') as HTMLInputElement
        if (allLightsToggle) {
            allLightsToggle.addEventListener('change', () => {
                this.toggleAllLights(allLightsToggle.checked)
            })
        }

        // Debug indicator toggle
        const debugToggle = document.getElementById('debug-indicator-toggle') as HTMLInputElement
        if (debugToggle) {
            debugToggle.checked = this.debugIndicatorEnabled
            debugToggle.addEventListener('change', () => {
                this.debugIndicatorEnabled = debugToggle.checked
                this.appSettings.setSetting('showLightingDebug', this.debugIndicatorEnabled, EventSource.UI)
                this.toggleAllDebugHelpers(this.debugIndicatorEnabled)
            })
        }

        // Refresh button
        const refreshButton = document.getElementById('refresh-lights')
        if (refreshButton) {
            refreshButton.addEventListener('click', (e) => {
                e.stopPropagation() // Prevent header click from triggering
                this.scanLights()
                this.updateUI()
            })
        }
    }

    private setupEventListeners(): void {
        // Listen for light creation events
        this.eventManager.registerEventHandler(LightingEventTypes.Created, this.lightCreatedHandler)
        // Listen for lighting system ready events
        this.eventManager.registerEventHandler(LightingEventTypes.SystemReady, this.lightingSystemReadyHandler)
    }

    private onLightCreated(event: CustomEvent<LightCreatedEvent>): void {
        LightingControlsPanel.logger.debug(`≡ƒÆí Light created: ${event.detail.lightType} (${event.detail.lightName || 'unnamed'})`)

        // Get scene from the first light event
        if (!this.scene) {
            this.scene = event.detail.scene
            this.performInitialScan() // Now we can scan for existing lights
        }

        this.addLightToGroups(event.detail.light, event.detail.lightType)
        this.updateUI()
    }

    private onLightingSystemReady(event: CustomEvent<LightingSystemReadyEvent>): void {
        LightingControlsPanel.logger.debug(`≡ƒÆí Lighting system ready: ${event.detail.quality} quality`)

        // Get scene from the system ready event if we don't have it yet
        if (!this.scene) {
            this.scene = event.detail.scene
            this.performInitialScan() // Now we can scan for existing lights
        }

        // Always refresh UI when system is ready (covers initial load and quality changes)
        this.scanLights()
        this.updateUI()
    }

    private addLightToGroups(light: THREE.Light, lightType: string): void {
        if (!this.lightGroups.has(lightType)) {
            this.lightGroups.set(lightType, {
                type: lightType,
                lights: [],
                enabled: light.visible, // Initialize based on first light's actual visibility
                collapsed: true // Start collapsed
            })
        }

        const group = this.lightGroups.get(lightType)!
        group.lights.push(light)

        // Recalculate group enabled state: true if ANY light in group is visible
        const enabledCount = group.lights.filter(l => l.visible).length
        group.enabled = enabledCount > 0
    }

    private performInitialScan(): void {
        // Initial scan to catch any existing lights
        this.scanLights()
        this.updateUI()
        // Force immediate checkbox update on initial load (don't defer)
        this.doUpdateCheckboxStates()
    }



    private scanLights(): void {
        const newGroups = new Map<string, LightGroupInfo>()

        // Use registry for O(1) grouped lookup instead of scene traversal
        const groupedLights = this.registry.getLightsGroupedByType()

        for (const [lightType, lights] of groupedLights) {
            newGroups.set(lightType, {
                type: lightType,
                lights: [...lights], // Copy array
                enabled: true,
                collapsed: true // Start collapsed
            })
        }

        // Update enabled states based on current visibility
        newGroups.forEach((group) => {
            const enabledCount = group.lights.filter(light => light.visible).length
            group.enabled = enabledCount > 0
        })

        this.lightGroups = newGroups
    }

    private updateUI(): void {
        this.updateLightGroups()
        this.updateIndividualLights()
        this.updateMasterToggle()
    }

    private updateLightGroups(): void {
        const container = document.getElementById('light-groups-container')
        if (!container) return

        container.innerHTML = ''

        this.lightGroups.forEach((group, type) => {
            const groupElement = document.createElement('div')
            groupElement.className = 'light-group'

            // Create group header with separate click regions
            const groupHeader = document.createElement('div')
            groupHeader.className = 'group-header'

            // Checkbox area (label + checkbox)
            const checkboxArea = document.createElement('div')
            checkboxArea.className = 'group-checkbox-area'
            checkboxArea.innerHTML = `
                <input type="checkbox" class="group-toggle" data-type="${type}" ${group.enabled ? 'checked' : ''}>
                <span class="control-label">${type} (${group.lights.length})</span>
            `

            // Expander arrow
            const expander = document.createElement('span')
            expander.className = `group-expander${group.collapsed ? ' collapsed' : ''}`
            expander.textContent = 'Γû╝'
            expander.dataset.type = type

            groupHeader.appendChild(checkboxArea)
            groupHeader.appendChild(expander)
            groupElement.appendChild(groupHeader)

            // Create lights container
            const lightsContainer = document.createElement('div')
            lightsContainer.className = `group-lights-container${group.collapsed ? ' collapsed' : ''}`
            lightsContainer.dataset.type = type

            // Add individual lights to this group
            group.lights.forEach((light, index) => {
                const lightElement = document.createElement('div')
                lightElement.className = 'individual-light'

                const lightName = light.name || `${type}-${index}`
                lightElement.innerHTML = `
                    <label class="control-item light-control">
                        <input type="checkbox" class="light-toggle" data-light-id="${light.id}" ${light.visible ? 'checked' : ''}>
                        <span class="control-label">${lightName}</span>
                        <span class="light-info">${this.getLightInfo(light)}</span>
                    </label>
                `

                const lightCheckbox = lightElement.querySelector('.light-toggle') as HTMLInputElement
                lightCheckbox.addEventListener('change', () => {
                    this.toggleIndividualLight(light, lightCheckbox.checked)
                })

                lightsContainer.appendChild(lightElement)
            })

            groupElement.appendChild(lightsContainer)

            // Event listeners
            const checkbox = checkboxArea.querySelector('.group-toggle') as HTMLInputElement
            checkboxArea.addEventListener('click', (e) => {
                // Only toggle checkbox if clicking the area, not the checkbox itself
                if (e.target !== checkbox) {
                    checkbox.checked = !checkbox.checked
                    this.toggleLightGroup(type, checkbox.checked)
                }
            })

            checkbox.addEventListener('change', () => {
                this.toggleLightGroup(type, checkbox.checked)
            })

            expander.addEventListener('click', () => {
                this.toggleGroupExpansion(type)
            })

            container.appendChild(groupElement)
        })
    }

    private updateIndividualLights(): void {
        // Individual lights are now nested within their groups
        // This method is kept for backwards compatibility but does nothing
        // The lights are rendered in updateLightGroups()
    }

    private updateMasterToggle(): void {
        const masterToggle = document.getElementById('all-lights-toggle') as HTMLInputElement
        if (!masterToggle) return

        const allLights = Array.from(this.lightGroups.values()).flatMap(group => group.lights)
        const enabledLights = allLights.filter(light => light.visible)

        masterToggle.checked = enabledLights.length === allLights.length
        masterToggle.indeterminate = enabledLights.length > 0 && enabledLights.length < allLights.length
    }

    /**
     * Schedule deferred checkbox update to avoid redundant work during rapid toggles
     * Coalesces multiple update requests into a single execution
     */
    private updateCheckboxStates(): void {
        // Cancel pending update if exists
        if (this.checkboxUpdatePending !== null) {
            cancelAnimationFrame(this.checkboxUpdatePending)
        }

        // Schedule update for next animation frame (deferred execution)
        this.checkboxUpdatePending = requestAnimationFrame(this.doUpdateCheckboxStates.bind(this))
    }

    /**
     * Actually update checkbox states without rebuilding DOM (fast)
     * Called via deferred execution to avoid redundant work
     */
    private doUpdateCheckboxStates(): void {
        // Clear pending flag first
        this.checkboxUpdatePending = null

        // Update master toggle
        this.updateMasterToggle()

        // Update group checkboxes
        this.lightGroups.forEach((group, type) => {
            const checkbox = document.querySelector(`.group-toggle[data-type="${type}"]`) as HTMLInputElement
            if (checkbox) {
                const enabledCount = group.lights.filter(light => light.visible).length
                checkbox.checked = enabledCount > 0
                checkbox.indeterminate = enabledCount > 0 && enabledCount < group.lights.length
            }
        })

        // Update individual light checkboxes
        this.lightGroups.forEach((group) => {
            group.lights.forEach(light => {
                const checkbox = document.querySelector(`.light-toggle[data-light-id="${light.id}"]`) as HTMLInputElement
                if (checkbox) {
                    checkbox.checked = light.visible
                }
            })
        })
    }

    private getLightInfo(light: THREE.Light): string {
        const info: string[] = []

        if ('intensity' in light) {
            info.push(`I:${light.intensity.toFixed(1)}`)
        }

        if (light instanceof THREE.PointLight || light instanceof THREE.SpotLight) {
            info.push(`D:${light.distance}`)
        }

        if (light instanceof THREE.RectAreaLight) {
            info.push(`${light.width}├ù${light.height}`)
        }

        return info.length > 0 ? `(${info.join(', ')})` : ''
    }

    private toggleAllLights(enabled: boolean): void {
        this.lightGroups.forEach((group) => {
            group.lights.forEach(light => {
                light.visible = enabled
                // Also toggle the debug helper visibility
                this.toggleDebugHelper(light, enabled)
            })
            group.enabled = enabled
        })

        // Emit lighting toggle event
        this.eventManager.emit(LightingEventTypes.Toggle, {
            enabled,
            source: EventSource.UI
        })

        // Only update checkbox states, not full UI rebuild
        this.updateCheckboxStates()
    }

    private toggleLightGroup(type: string, enabled: boolean): void {
        const group = this.lightGroups.get(type)
        if (!group) return

        group.lights.forEach(light => {
            light.visible = enabled
            // Also toggle the debug helper visibility
            this.toggleDebugHelper(light, enabled)
        })
        group.enabled = enabled

        LightingControlsPanel.logger.info(`≡ƒÆí ${enabled ? 'Enabled' : 'Disabled'} ${type} lights (${group.lights.length} lights)`)
        // Only update checkbox states, not full UI rebuild
        this.updateCheckboxStates()
    }

    private toggleIndividualLight(light: THREE.Light, enabled: boolean): void {
        light.visible = enabled

        // Also toggle the debug helper visibility
        this.toggleDebugHelper(light, enabled)

        const lightName = light.name || `${light.constructor.name}-${light.id}`
        LightingControlsPanel.logger.info(`≡ƒÆí ${enabled ? 'Enabled' : 'Disabled'} light: ${lightName}`)

        // Only update checkbox states, not full UI rebuild
        this.updateCheckboxStates()
    }

    private toggleGroupExpansion(type: string): void {
        const group = this.lightGroups.get(type)
        if (!group) return

        group.collapsed = !group.collapsed

        // Update the UI elements
        const expander = document.querySelector(`.group-expander[data-type="${type}"]`)
        const lightsContainer = document.querySelector(`.group-lights-container[data-type="${type}"]`)

        if (expander) {
            if (group.collapsed) {
                expander.classList.add('collapsed')
            } else {
                expander.classList.remove('collapsed')
            }
        }

        if (lightsContainer) {
            if (group.collapsed) {
                lightsContainer.classList.add('collapsed')
            } else {
                lightsContainer.classList.remove('collapsed')
            }
        }
    }

    public show(): void {
        this.container.style.display = 'flex'

        // Only scan lights and update UI, don't force expand the panel
        // Let it stay in its current collapsed/expanded state
        this.scanLights()
        this.updateUI()
    }

    public hide(): void {
        this.container.style.display = 'none'

        // Show the separate button again when panel is hidden
        const separateButton = document.getElementById('lighting-controls-button')
        if (separateButton) {
            separateButton.style.display = 'block'
        }
    }

    public toggle(): void {
        if (this.container.style.display === 'none') {
            this.show()
        } else {
            this.hide()
        }
    }

    private togglePanelContent(): void {
        const content = document.getElementById('lighting-panel-content')
        const indicator = document.getElementById('toggle-indicator')
        const panel = this.container

        if (!content || !indicator) return

        const isCollapsed = content.classList.contains('collapsed')
        this.panelCollapsed = !isCollapsed // Will be the new state after toggle

        if (isCollapsed) {
            // Expand: remove collapsed classes
            content.classList.remove('collapsed')
            panel.classList.remove('horizontally-collapsed')
            indicator.textContent = 'Γû╝'
            this.horizontallyCollapsed = false
            this.scanLights()
            this.updateUI()
        } else {
            // Collapse: add collapsed classes
            content.classList.add('collapsed')
            panel.classList.add('horizontally-collapsed')
            indicator.textContent = 'Γû╢'
            this.horizontallyCollapsed = true
        }
    }

    private toggleDebugHelper(light: THREE.Light, enabled: boolean): void {
        // Use registry for O(1) lookup instead of scene traversal
        const debugHelper = this.registry.getAttachedGeometry(light)

        if (debugHelper) {
            debugHelper.visible = this.debugIndicatorEnabled && enabled
        }
    }

    private toggleAllDebugHelpers(enabled: boolean): void {
        // Use registry for O(1) lookup instead of scene traversal
        const helpers = this.registry.getAllAttachedGeometry()
        for (const helper of helpers) {
            helper.visible = enabled
        }
    }

    public dispose(): void {
        // Deregister event handlers
        this.eventManager.deregisterEventHandler(LightingEventTypes.Created, this.lightCreatedHandler)
        this.eventManager.deregisterEventHandler(LightingEventTypes.SystemReady, this.lightingSystemReadyHandler)

        // Show the separate button again when disposing
        const separateButton = document.getElementById('lighting-controls-button')
        if (separateButton) {
            separateButton.style.display = 'block'
        }

        if (this.container.parentNode) {
            this.container.parentNode.removeChild(this.container)
        }
    }
}

/**
 * TD: raf-loop-migration
 * Performance Statistics Display
 * 
 * A lightweight performance monitoring component that displays FPS, memory usage,
 * and render time statistics. This is inspired by the popular stats.js library
 * but implemented using browser APIs to avoid external dependencies.
 */

import * as THREE from 'three'

export interface PerformanceStats {
    fps: number
    frameTime: number
    memoryUsed?: number
    memoryTotal?: number
    drawCalls?: number
    triangles?: number
}

export interface PerformanceConfig {
    updateInterval?: number // milliseconds
    precision?: number // decimal places
    showMemory?: boolean
    showDrawCalls?: boolean
    position?: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'
}

interface MemoryInfo {
    usedJSHeapSize: number
    totalJSHeapSize: number
    jsHeapSizeLimit: number
}

interface PerformanceWithMemory extends Performance {
    memory?: MemoryInfo
}

// TODO: Rename file to match PerformanceMonitorUI
export class PerformanceMonitorUI {
    private container: HTMLElement | null = null
    private fpsDisplay: HTMLElement | null = null
    private frameTimeDisplay: HTMLElement | null = null
    private memoryDisplay: HTMLElement | null = null
    private drawCallsDisplay: HTMLElement | null = null

    private frameCount = 0
    private lastTime = window.performance.now()
    private lastFpsUpdate = window.performance.now()
    private frameTimeHistory: number[] = []
    private animationId: number | null = null
    private uiInitialized = false

    private config: Required<PerformanceConfig>

    constructor(config: PerformanceConfig = {}) {
        this.config = {
            updateInterval: config.updateInterval ?? 100,
            precision: config.precision ?? 1,
            showMemory: config.showMemory ?? true,
            showDrawCalls: config.showDrawCalls ?? false,
            position: config.position ?? 'top-left'
        }

        // Don't create UI elements yet - defer until first use
        // This avoids blocking startup with DOM manipulation
    }

    /**
     * Initialize UI elements (deferred from constructor to avoid blocking startup)
     */
    private ensureUIInitialized(): void {
        if (this.uiInitialized) return

        this.container = this.createContainer()
        this.fpsDisplay = this.createDisplay('FPS', '0')
        this.frameTimeDisplay = this.createDisplay('MS', '0')

        if (this.config.showMemory && this.isMemoryAPISupported()) {
            this.memoryDisplay = this.createDisplay('MB', '0')
        }

        if (this.config.showDrawCalls) {
            this.drawCallsDisplay = this.createDisplay('DC', '0')
        }

        this.setupStyles()
        const slot = document.getElementById('ui-slot-top-right')
        if (slot) {
            slot.prepend(this.container)
        } else {
            document.body.appendChild(this.container)
        }
        this.uiInitialized = true
    }

    private createContainer(): HTMLElement {
        const container = document.createElement('div')
        container.id = 'performance-monitor'
        container.style.position = 'relative'
        container.style.zIndex = '10000'
        container.style.fontFamily = 'Monaco, monospace'
        container.style.fontSize = '10px'
        container.style.lineHeight = '1.2'
        container.style.pointerEvents = 'none'
        container.style.userSelect = 'none'
        return container
    }

    private createDisplay(label: string, initialValue: string): HTMLElement {
        const display = document.createElement('div')
        display.style.padding = '2px 4px'
        display.style.margin = '1px 0'
        display.style.backgroundColor = 'rgba(0, 0, 0, 0.8)'
        display.style.color = '#00ff00'
        display.style.border = '1px solid #333'
        display.style.borderRadius = '2px'
        display.innerHTML = `<span style="color: #fff">${label}:</span> ${initialValue}`
        this.container.appendChild(display)
        return display
    }

    private setupStyles(): void {
        const { position } = this.config

        this.container.style.top = ''
        this.container.style.right = ''
        this.container.style.bottom = ''
        this.container.style.left = ''
        this.container.style.margin = '0'
        this.container.style.alignSelf = ''

        switch (position) {
            case 'top-left':
                this.container.style.alignSelf = 'flex-start'
                break
            case 'top-right':
                this.container.style.alignSelf = 'flex-end'
                break
            case 'bottom-left':
                this.container.style.alignSelf = 'flex-start'
                this.container.style.marginTop = 'auto'
                break
            case 'bottom-right':
                this.container.style.alignSelf = 'flex-end'
                this.container.style.marginTop = 'auto'
                break
        }
    }

    private isMemoryAPISupported(): boolean {
        const perf = window.performance as PerformanceWithMemory
        return 'memory' in perf && perf.memory !== undefined && 'usedJSHeapSize' in perf.memory
    }

    /**
     * Start monitoring performance (creates UI if needed)
     */
    public start(): void {
        if (this.animationId !== null) return

        this.ensureUIInitialized()

        this.lastTime = window.performance.now()
        this.lastFpsUpdate = window.performance.now()
        this.frameCount = 0
        this.frameTimeHistory = []

        const update = () => {
            this.update()
            this.animationId = window.requestAnimationFrame(update)
        }

        this.animationId = window.requestAnimationFrame(update)
    }

    /**
     * Stop monitoring performance
     */
    public stop(): void {
        if (this.animationId !== null) {
            window.cancelAnimationFrame(this.animationId)
            this.animationId = null
        }
    }

    /**
     * Update performance statistics
     */
    private update(): void {
        const now = window.performance.now()
        const deltaTime = now - this.lastTime
        this.lastTime = now

        // Track frame time
        this.frameTimeHistory.push(deltaTime)
        if (this.frameTimeHistory.length > 60) {
            this.frameTimeHistory.shift()
        }

        this.frameCount++

        // Update displays at specified interval
        if (now - this.lastFpsUpdate >= this.config.updateInterval) {
            this.updateDisplays(now)
            this.lastFpsUpdate = now
        }
    }

    private updateDisplays(now: number): void {
        if (!this.fpsDisplay || !this.frameTimeDisplay) return // UI not initialized yet

        const deltaTime = now - this.lastFpsUpdate

        // Calculate FPS
        const fps = (this.frameCount * 1000) / deltaTime
        this.updateDisplay(this.fpsDisplay, 'FPS', fps.toFixed(this.config.precision))

        // Calculate average frame time
        const avgFrameTime = this.frameTimeHistory.reduce((a, b) => a + b, 0) / this.frameTimeHistory.length
        this.updateDisplay(this.frameTimeDisplay, 'MS', avgFrameTime.toFixed(this.config.precision))

        // Update memory display if supported
        if (this.memoryDisplay && this.isMemoryAPISupported()) {
            const perf = window.performance as PerformanceWithMemory
            const memInfo = perf.memory
            if (memInfo) {
                const memoryUsed = memInfo.usedJSHeapSize / 1048576 // Convert to MB
                this.updateDisplay(this.memoryDisplay, 'MB', memoryUsed.toFixed(this.config.precision))
            }
        }

        // Reset frame count for next interval
        this.frameCount = 0
    }

    private updateDisplay(element: HTMLElement, label: string, value: string): void {
        element.innerHTML = `<span style="color: #fff">${label}:</span> ${value}`

        // Color coding for FPS
        if (label === 'FPS') {
            const fpsValue = parseFloat(value)
            if (fpsValue >= 55) {
                element.style.color = '#00ff00' // Green for good FPS
            } else if (fpsValue >= 30) {
                element.style.color = '#ffff00' // Yellow for moderate FPS
            } else {
                element.style.color = '#ff0000' // Red for poor FPS
            }
        }
    }

    /**
     * Update render statistics from Three.js renderer
     */
    public updateRenderStats(renderer: THREE.WebGLRenderer): void {
        if (!this.drawCallsDisplay) return

        const info = renderer.info
        if (info?.render) {
            const drawCalls = info.render.calls
            this.updateDisplay(this.drawCallsDisplay, 'DC', drawCalls.toString())
        }
    }

    /**
     * Get current performance statistics
     */
    public getStats(): PerformanceStats {
        const avgFrameTime = this.frameTimeHistory.length > 0 
            ? this.frameTimeHistory.reduce((a, b) => a + b, 0) / this.frameTimeHistory.length 
            : 0

        const stats: PerformanceStats = {
            fps: avgFrameTime > 0 ? 1000 / avgFrameTime : 0,
            frameTime: avgFrameTime
        }

        if (this.isMemoryAPISupported()) {
            const perf = window.performance as PerformanceWithMemory
            const memInfo = perf.memory
            if (memInfo) {
                stats.memoryUsed = memInfo.usedJSHeapSize / 1048576
                stats.memoryTotal = memInfo.totalJSHeapSize / 1048576
            }
        }

        return stats
    }

    /**
     * Hide the performance monitor
     */
    public hide(): void {
        if (!this.container) return
        this.container.style.display = 'none'
    }

    /**
     * Show the performance monitor (creates UI if needed)
     */
    public show(): void {
        this.ensureUIInitialized()
        if (!this.container) return
        this.container.style.display = 'block'
    }

    /**
     * Toggle visibility of the performance monitor (creates UI if needed)
     */
    public toggle(): void {
        this.ensureUIInitialized()
        if (!this.container) return

        const isVisible = this.container.style.display !== 'none'
        if (isVisible) {
            this.hide()
        } else {
            this.show()
        }
    }

    /**
     * Remove the performance monitor from the DOM and stop monitoring
     */
    public dispose(): void {
        this.stop()
        if (this.container?.parentNode) {
            this.container.parentNode.removeChild(this.container)
        }
    }
}

/**
 * ProgressDisplay - Manages loading progress UI
 */

export class ProgressDisplay {
  private loadingProgress: HTMLElement | null
  private progressFill: HTMLElement | null
  private progressText: HTMLElement | null
  private progressGame: HTMLElement | null
  
  constructor() {
    this.loadingProgress = document.getElementById('loading-progress')
    this.progressFill = document.getElementById('progress-fill')
    this.progressText = document.getElementById('progress-text')
    this.progressGame = document.getElementById('progress-game')
  }
  
  init(): void {
    // Initially hide progress
    this.show(false)
  }
  
  show(visible: boolean): void {
    if (!this.loadingProgress) return
    
    this.loadingProgress.style.display = visible ? 'block' : 'none'
    
    if (!visible) {
      // Reset progress when hiding
      this.update(0, 100, '')
    }
  }
  
  update(current: number, total: number, message: string, gameText: string = ''): void {
    if (!this.progressFill || !this.progressText || !this.progressGame) return
    
    const percentage = Math.max(0, Math.min(100, (current / total) * 100))
    
    this.progressFill.style.width = `${percentage}%`
    this.progressText.textContent = message
    this.progressGame.textContent = gameText
  }
}

/**
 * SteamUIPanel - Manages Steam-specific UI controls and interactions
 */

// Cross-platform timeout type that works in both Node.js and browser environments
type TimeoutHandle = ReturnType<typeof setTimeout>

import { getElementByIdSafe } from '../utils'
import { renderTemplate } from '../utils/TemplateEngine'
import { EventManager, EventSource } from '../core/EventManager'
import { SteamEventTypes } from '../types/InteractionEvents'
import { SteamIntegration } from '../steam-integration/SteamIntegration'
import steamCacheStatsTemplate from '../templates/steam-ui/cache-stats.html?raw'

export class SteamUIPanel {
  private eventManager: EventManager
  private steamUI: HTMLElement | null
  private steamUserInput: HTMLInputElement | null
  private loadGamesButton: HTMLButtonElement | null
  private loadFromCacheButton: HTMLButtonElement | null
  private refreshCacheButton: HTMLButtonElement | null
  private clearCacheButton: HTMLButtonElement | null
  private showCacheStatsButton: HTMLButtonElement | null
  private cacheInfoDiv: HTMLElement | null
  private steamStatus: HTMLElement | null
  private cacheCheckDebounceTimeout: TimeoutHandle | null = null

  constructor() {
    this.eventManager = EventManager.getInstance()

    // Get UI elements
    this.steamUI = document.getElementById('steam-ui')
    this.steamUserInput = getElementByIdSafe('steam-user-input') as HTMLInputElement
    this.loadGamesButton = getElementByIdSafe('load-steam-games') as HTMLButtonElement
    this.loadFromCacheButton = getElementByIdSafe('load-from-cache') as HTMLButtonElement
    this.refreshCacheButton = getElementByIdSafe('refresh-cache') as HTMLButtonElement
    this.clearCacheButton = getElementByIdSafe('clear-cache') as HTMLButtonElement
    this.showCacheStatsButton = getElementByIdSafe('show-cache-stats') as HTMLButtonElement
    this.cacheInfoDiv = document.getElementById('cache-info')
    this.steamStatus = document.getElementById('steam-status')
  }

  init(): void {
    this.setupEventListeners()
  }

  private setupEventListeners(): void {
    // Hide panel when profile loading starts (from UI or auto-load)
    this.eventManager.registerEventHandler(SteamEventTypes.LoadGames, () => this.hide())
    this.eventManager.registerEventHandler(SteamEventTypes.LoadFromCache, () => this.hide())

    // Load Games button
    if (this.loadGamesButton) {
      this.loadGamesButton.addEventListener('click', () => {
        const userInput = this.getUserInput()
        if (userInput) {
          this.eventManager.emit(SteamEventTypes.LoadGames, {
            userInput,
            source: EventSource.UI
          })
        }
      })
    }

    // Load from Cache button
    if (this.loadFromCacheButton) {
      this.loadFromCacheButton.addEventListener('click', () => {
        const userInput = this.getUserInput()
        if (userInput) {
          this.eventManager.emit(SteamEventTypes.LoadFromCache, {
            userInput,
            source: EventSource.UI
          })
        }
      })
    }

    // Cache management buttons
    if (this.refreshCacheButton) {
      this.refreshCacheButton.addEventListener('click', () => {
        this.eventManager.emit(SteamEventTypes.CacheRefresh, {
          source: EventSource.UI
        })
      })
    }

    if (this.clearCacheButton) {
      this.clearCacheButton.addEventListener('click', () => {
        this.eventManager.emit(SteamEventTypes.CacheClear, {
          source: EventSource.UI
        })
      })
    }

    if (this.showCacheStatsButton) {
      this.showCacheStatsButton.addEventListener('click', () => {
        this.eventManager.emit(SteamEventTypes.CacheStats, {
          source: EventSource.UI
        })
      })
    }

    // Enter key support for input field
    if (this.steamUserInput) {
      this.steamUserInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          const userInput = this.getUserInput()
          if (userInput) {
            this.eventManager.emit(SteamEventTypes.LoadGames, {
              userInput,
              source: EventSource.UI
            })
          }
        }
      })

      // Input change handler for cache availability with debouncing
      this.steamUserInput.addEventListener('input', () => {
        const userInput = this.steamUserInput?.value.trim() || ''

        // Clear any existing debounce timer
        if (this.cacheCheckDebounceTimeout !== null) {
          clearTimeout(this.cacheCheckDebounceTimeout)
        }

        if (!userInput) {
          // If no input, immediately hide the button (no debounce needed)
          this.updateLoadFromCacheButtonVisibility(false)
          return
        }

        // Debounce cache check for 250ms to avoid excessive calls while typing
        this.cacheCheckDebounceTimeout = setTimeout(() => {
          const steamIntegration = SteamIntegration.getInstance()

          if (steamIntegration) {
            const hasCache = steamIntegration.hasCachedData(userInput)
            this.updateLoadFromCacheButtonVisibility(hasCache)
          } else {
            // No SteamIntegration instance, hide the button
            this.updateLoadFromCacheButtonVisibility(false)
          }

          this.cacheCheckDebounceTimeout = null
        }, 250)
      })
    }


  }

  private getUserInput(): string | null {
    if (!this.steamUserInput) return null

    const input = this.steamUserInput.value.trim()
    if (!input) {
      this.showStatus('Please enter a Steam Profile URL, Custom URL, or Steam ID', 'error')
      return null
    }

    return input
  }

  show(): void {
    if (this.steamUI) {
      this.steamUI.classList.remove('hidden')
    }
  }

  hide(): void {
    if (this.steamUI) {
      this.steamUI.classList.add('hidden')
    }
  }

  showStatus(message: string, type: 'loading' | 'success' | 'error'): void {
    if (!this.steamStatus) return

    // Use innerHTML for error messages that may contain HTML formatting, textContent for others
    if (type === 'error' && message.includes('<br>')) {
      this.steamStatus.innerHTML = message
    } else {
      this.steamStatus.textContent = message
    }
    this.steamStatus.className = `status-${type}`

    // Manage loading state based on status type
    if (type === 'loading') {
      this.setLoadingState(true)
    } else if (type === 'error' || type === 'success') {
      this.setLoadingState(false)
      if (type === 'success') {
        // Auto-hide success messages after 5 seconds
        setTimeout(() => {
          if (this.steamStatus) {
            this.steamStatus.className = 'status-hidden'
          }
        }, 5000)
      }
    }
  }

  setLoadingState(isLoading: boolean): void {
    // Disable all interactive elements during loading
    if (this.loadGamesButton) {
      this.loadGamesButton.disabled = isLoading
    }
    if (this.loadFromCacheButton) {
      this.loadFromCacheButton.disabled = isLoading
    }
    if (this.steamUserInput) {
      this.steamUserInput.disabled = isLoading
    }

    // Set visual state for the entire UI panel
    if (this.steamUI) {
      if (isLoading) {
        this.steamUI.classList.add('loading')
      } else {
        this.steamUI.classList.remove('loading')
      }
    }
  }

  updateCacheStats(stats: { totalEntries: number; cacheHits: number; cacheMisses: number }): void {
    // Update cache info if it's currently visible
    if (this.cacheInfoDiv && this.cacheInfoDiv.style.display === 'block') {
      this.showCacheStatsInfo(stats)
    }

    // Update button text to show entry count
    if (this.showCacheStatsButton) {
      this.showCacheStatsButton.textContent = `Cache Info (${stats.totalEntries})`
    }
  }

  showCacheStatsInfo(stats: { totalEntries: number; cacheHits: number; cacheMisses: number }): void {
    if (!this.cacheInfoDiv) return

    this.cacheInfoDiv.innerHTML = renderTemplate(steamCacheStatsTemplate, stats)

    // Toggle visibility
    const isHidden = this.cacheInfoDiv.style.display === 'none'
    this.cacheInfoDiv.style.display = isHidden ? 'block' : 'none'

    if (this.showCacheStatsButton) {
      this.showCacheStatsButton.textContent = isHidden ? 'Hide Info' : 'Cache Info'
    }
  }

  updateLoadFromCacheButtonVisibility(hasCache: boolean): void {
    if (!this.loadFromCacheButton) return

    if (!hasCache) {
      this.loadFromCacheButton.classList.add('hidden')
      return
    }

    this.loadFromCacheButton.classList.remove('hidden')
  }

  dispose(): void {
    if (this.cacheCheckDebounceTimeout !== null) {
      clearTimeout(this.cacheCheckDebounceTimeout)
      this.cacheCheckDebounceTimeout = null
    }
  }
}

/**
 * Global Toast Notification Manager
 * 
 * Provides application-wide toast notifications that appear as temporary
 * overlays. Replaces alert() calls with better UX.
 */

export interface ToastOptions {
    duration?: number // milliseconds, default 4000
    position?: 'top-right' | 'top-center' | 'bottom-right' | 'bottom-center'
}

export type ToastType = 'success' | 'error' | 'info' | 'warning'

// TODO: queuing system to ensure toasts don't flood the screen
export class ToastManager {
    private static instance: ToastManager | null = null
    private container: HTMLElement | null = null
    private toastCounter = 0

    private constructor() {
        this.createContainer()
    }

    private static getInstance(): ToastManager {
        if (!ToastManager.instance) {
            ToastManager.instance = new ToastManager()
        }
        return ToastManager.instance
    }

    // Static convenience methods - no need to access instance
    static success(message: string, options: ToastOptions = {}): void {
        ToastManager.getInstance().show(message, 'success', options)
    }

    static error(message: string, options: ToastOptions = {}): void {
        ToastManager.getInstance().show(message, 'error', { duration: 6000, ...options })
    }

    static info(message: string, options: ToastOptions = {}): void {
        ToastManager.getInstance().show(message, 'info', options)
    }

    static warning(message: string, options: ToastOptions = {}): void {
        ToastManager.getInstance().show(message, 'warning', options)
    }

    private createContainer(): void {
        if (this.container) return

        // Only create container if we have a valid DOM environment
        if (typeof document === 'undefined' || !document.body) {
            console.warn('ToastManager: DOM not available, toast notifications disabled')
            return
        }

        this.container = document.createElement('div')
        this.container.id = 'toast-container'
        this.container.className = 'toast-container'
        document.body.appendChild(this.container)
    }

    private show(message: string, type: ToastType = 'info', options: ToastOptions = {}): void {
        if (!this.container) {
            this.createContainer()
        }

        // If container still doesn't exist (DOM not available), fall back to console
        if (!this.container) {
            console.log(`Toast (${type}): ${message}`)
            return
        }

        const toast = this.createToast(message, type, options)
        this.container.appendChild(toast)

        // Trigger enter animation
        setTimeout(() => {
            toast.classList.add('toast-enter')
        }, 10)

        // Auto-remove after duration
        const duration = options.duration ?? 4000
        setTimeout(() => {
            this.removeToast(toast)
        }, duration)
    }

    private createToast(message: string, type: ToastType, options: ToastOptions): HTMLElement {
        const toast = document.createElement('div')
        toast.className = `toast toast-${type}`
        toast.dataset.id = (++this.toastCounter).toString()

        // Toast content
        const content = document.createElement('div')
        content.className = 'toast-content'
        content.textContent = message

        // Close button
        const closeBtn = document.createElement('button')
        closeBtn.className = 'toast-close'
        closeBtn.innerHTML = '├ù'
        closeBtn.onclick = () => this.removeToast(toast)

        toast.appendChild(content)
        toast.appendChild(closeBtn)

        return toast
    }

    private removeToast(toast: HTMLElement): void {
        toast.classList.remove('toast-enter')
        toast.classList.add('toast-exit')

        setTimeout(() => {
            if (toast.parentNode) {
                toast.parentNode.removeChild(toast)
            }
            // Let CSS handle container visibility based on content
        }, 5000) // Match CSS transition duration
    }

    dispose(): void {
        if(this.container) this.container.innerHTML = '';

        if (this.container && this.container.parentNode) {
            this.container.parentNode.removeChild(this.container)
        }
        this.container = null
        ToastManager.instance = null
    }
}

/**
 * UIManager - Coordinates all UI components and their interactions
