            source: EventSource.UI
        })
    }
}

/**
 * Compass Rose - Visual direction indicator for debugging spatial orientation
 * Shows N/S/E/W directions in top-right corner of screen
 */

import * as THREE from 'three'
import { AppSettings, type SettingChangedEvent } from '../../core/AppSettings'
import { EventManager } from '../../core/EventManager'
import { AppSettingsEventTypes } from '../../types/InteractionEvents'
import { RenderLoopRegistry } from '../../scene/RenderLoopRegistry'

export class CompassRose {
    private container: HTMLDivElement
    private camera: THREE.Camera
    private isVisible: boolean = true
    private appSettings: AppSettings
    private eventManager: EventManager
    private renderLoopRegistry: RenderLoopRegistry

    constructor(camera: THREE.Camera) {
        this.camera = camera
        this.appSettings = AppSettings.getInstance()
        this.eventManager = EventManager.getInstance()
        this.renderLoopRegistry = RenderLoopRegistry.getInstance()

        this.container = this.createCompassElement()
        document.body.appendChild(this.container)

        // Register update method with render loop
        this.renderLoopRegistry.register(this.constructor.name, this.update.bind(this))

        // Set initial visibility from settings (default: off)
        this.setVisible(this.appSettings.getSetting('showCompassRose'))

        // Listen for setting changes
        this.eventManager.registerEventHandler<SettingChangedEvent>(
            AppSettingsEventTypes.Changed,
            (event) => {
                if (event.detail.key === 'showCompassRose') {
                    this.setVisible(event.detail.value as boolean)
                }
            }
        )
    }

    private createCompassElement(): HTMLDivElement {
        const compass = document.createElement('div')
        compass.id = 'compass-rose'
        compass.style.position = 'fixed'
        compass.style.top = '60px'
        compass.style.right = '20px'
        compass.style.width = '80px'
        compass.style.height = '80px'
        compass.style.backgroundColor = 'rgba(0, 0, 0, 0.5)'
        compass.style.border = '2px solid rgba(255, 255, 255, 0.3)'
        compass.style.borderRadius = '50%'
        compass.style.display = 'flex'
        compass.style.alignItems = 'center'
        compass.style.justifyContent = 'center'
        compass.style.fontFamily = 'monospace'
        compass.style.fontSize = '12px'
        compass.style.color = 'white'
        compass.style.zIndex = '1000'
        compass.style.pointerEvents = 'none'

        // Create cardinal direction labels
        const directions = [
            { label: 'N', angle: 0, color: '#ff4444' },      // North (red) - negative Z
            { label: 'E', angle: 90, color: '#44ff44' },     // East (green) - positive X
            { label: 'S', angle: 180, color: '#ffffff' },    // South (white) - positive Z
            { label: 'W', angle: 270, color: '#4444ff' }     // West (blue) - negative X
        ]

        directions.forEach(dir => {
            const label = document.createElement('div')
            label.textContent = dir.label
            label.style.position = 'absolute'
            label.style.color = dir.color
            label.style.fontWeight = 'bold'
            label.style.fontSize = '14px'
            label.className = `compass-${dir.label.toLowerCase()}`

            // Position labels around circle
            const radius = 28
            const rad = (dir.angle - 90) * Math.PI / 180 // -90 to start from top
            const x = radius * Math.cos(rad)
            const y = radius * Math.sin(rad)

            label.style.left = `calc(50% + ${x}px - 6px)`
            label.style.top = `calc(50% + ${y}px - 7px)`

            compass.appendChild(label)
        })

        // Center dot
        const center = document.createElement('div')
        center.style.position = 'absolute'
        center.style.width = '4px'
        center.style.height = '4px'
        center.style.backgroundColor = 'yellow'
        center.style.borderRadius = '50%'
        center.style.left = 'calc(50% - 2px)'
        center.style.top = 'calc(50% - 2px)'
        compass.appendChild(center)

        return compass
    }

    public update(_now: number, _deltaTime: number): void {
        if (!this.isVisible) return

        // Get camera rotation
        const cameraDirection = new THREE.Vector3()
        this.camera.getWorldDirection(cameraDirection)

        // Calculate angle (0 = looking north/-Z, increases clockwise)
        const angle = Math.atan2(cameraDirection.x, -cameraDirection.z) * 180 / Math.PI

        // Rotate compass to match camera orientation
        this.container.style.transform = `rotate(${-angle}deg)`
    }

    public setVisible(visible: boolean): void {
        this.isVisible = visible
        this.container.style.display = visible ? 'flex' : 'none'
    }

    public dispose(): void {
        // Unregister from render loop
        this.renderLoopRegistry.unregister(this.constructor.name)

        if (this.container.parentElement) {
            this.container.parentElement.removeChild(this.container)
        }
    }
}

∩╗┐/**
 * PauseMenuManager - Main orchestrator for the pause menu system
 * 
 * Handles menu state, panel switching, and integration with input system
 */

import * as THREE from 'three'
import { PauseMenuPanel } from './PauseMenuPanel'
import { renderTemplate } from '../../utils/TemplateEngine'
import pauseMenuStructureTemplate from '../../templates/pause-menu/main-structure.html?raw'
import '../../styles/pause-menu/pause-menu-manager.css'

// Panel imports for default registration
import { CacheManagementPanel } from './panels/CacheManagementPanel'
import { HelpPanel } from './panels/HelpPanel'
import { ApplicationPanel } from './panels/ApplicationPanel'
import { GameSettingsPanel } from './panels/GameSettingsPanel'
import { GraphicsSettingsPanel } from './panels/GraphicsSettingsPanel'
import { CameraSettingsPanel } from './panels/CameraSettingsPanel'
import type { PerformanceMonitorUI } from '../PerformanceMonitor'
import { EventManager, EventSource } from '../../core/EventManager'
import { SteamEventTypes } from '../../types/InteractionEvents'
import { LightingEventTypes } from '../../types/LightingEvents'
import type { SteamDataLoadedEvent } from '../../types/InteractionEvents'
import type { LightingToggleEvent, LightingDebugToggleEvent } from '../../types/LightingEvents'
import { AppSettings, type ApplicationSettings } from '../../core/AppSettings'
import { DebugPanel } from './panels/DebugPanel'

export interface PauseMenuState {
    isOpen: boolean
    activePanel: string | null
    inputPaused: boolean
    previousFocus: HTMLElement | null
}

export interface PauseMenuConfig {
    displayName?: string
    containerId?: string
    overlayClass?: string
    menuClass?: string
}

export interface PauseMenuCallbacks {
    onPauseInput?: () => void
    onResumeInput?: () => void
    onMenuOpen?: () => void
    onMenuClose?: () => void
}

export interface SystemDependencies {
    performanceMonitor: PerformanceMonitorUI
    renderer: THREE.WebGLRenderer
}


export class PauseMenuManager {
    private state: PauseMenuState = {
        isOpen: false,
        activePanel: null,
        inputPaused: false,
        previousFocus: null
    }

    private config: Required<PauseMenuConfig>
    private callbacks: PauseMenuCallbacks
    private systemDependencies: SystemDependencies | null = null
    private panels: Map<string, PauseMenuPanel> = new Map()
    private overlay: HTMLElement | null = null
    private menuContainer: HTMLElement | null = null
    private cacheManagementPanel: CacheManagementPanel | null = null
    private applicationPanel: ApplicationPanel | null = null
    private eventManager: EventManager
    private appSettings: AppSettings
    private readonly performanceMonitor: PerformanceMonitorUI

    constructor(
        config: PauseMenuConfig = {}, 
        callbacks: PauseMenuCallbacks = {}, 
        systemDependencies: SystemDependencies | undefined,
        eventManager: EventManager,
        appSettings: AppSettings,
        performanceMonitor: PerformanceMonitorUI
    ) {
        this.config = {
            displayName: 'Settings',
            containerId: 'pause-menu-overlay',
            overlayClass: 'pause-menu-overlay',
            menuClass: 'pause-menu',
            ...config
        }
        this.callbacks = callbacks
        this.systemDependencies = systemDependencies || null
        this.eventManager = eventManager
        this.appSettings = appSettings
        this.performanceMonitor = performanceMonitor    
    }

    init(): void {
        this.createMenuStructure()
        this.setupKeyboardHandling()
        this.setupEventListeners()
    }

    private setupEventListeners(): void {
        this.eventManager.registerEventHandler(
            SteamEventTypes.DataLoaded, 
            this.onSteamDataLoaded.bind(this)
        )
    }

    private onSteamDataLoaded(event: CustomEvent<SteamDataLoadedEvent>): void {
        // Refresh cache management panel if it exists and is visible
        if (this.cacheManagementPanel) {
            this.cacheManagementPanel.refreshTemplate()
        }
    }

    setSystemDependencies(dependencies: SystemDependencies): void {
        this.systemDependencies = dependencies
    }

    registerPanel(panel: PauseMenuPanel): void {
        this.panels.set(panel.id, panel)
        panel.init()
        this.createPanelTab(panel)
    }

    registerDefaultPanels(): void {
        // Register cache management panel - no longer needs callbacks
        const cachePanel = new CacheManagementPanel()
        this.cacheManagementPanel = cachePanel
        this.registerPanel(cachePanel)

        // Register help panel
        this.registerPanel(new HelpPanel())

        // Register application panel
        const applicationPanel = new ApplicationPanel({}, this.appSettings, this.eventManager)
        applicationPanel.initialize({
            onSettingsChanged: (settings) => this.handleSettingsChange(settings)
        })
        this.applicationPanel = applicationPanel
        this.registerPanel(applicationPanel)

        // Register game settings panel
        this.registerPanel(new GameSettingsPanel({}, this.appSettings))

        // Register graphics settings panel
        const graphicsPanel = new GraphicsSettingsPanel({}, this.appSettings)
        graphicsPanel.initialize({
            onSettingsChanged: (settings) => this.handleSettingsChange(settings)
        })
        this.registerPanel(graphicsPanel)

        // Register camera settings panel
        const cameraPanel = new CameraSettingsPanel({}, this.appSettings)
        this.registerPanel(cameraPanel)

        const debugPanel = new DebugPanel({}, this.performanceMonitor)
        this.registerPanel(debugPanel)
    }

    toggle(): void {
        if (this.state.isOpen) {
            this.close()
        } else {
            this.open()
        }
    }

    open(panelId?: string): void {
        if (this.state.isOpen) return

        this.state.isOpen = true
        this.state.previousFocus = document.activeElement as HTMLElement

        // Pause input
        this.pauseInput()

        // Show overlay
        if (this.overlay) {
            this.overlay.style.display = 'flex'
        }

        // Show specific panel or first available
        const targetPanel = panelId || this.getFirstPanelId()
        if (targetPanel) {
            this.showPanel(targetPanel)
        }

        // Callbacks
        this.callbacks.onMenuOpen?.()
    }

    close(): void {
        if (!this.state.isOpen) return

        this.state.isOpen = false

        // Hide all panels
        this.hideAllPanels()

        // Hide overlay
        if (this.overlay) {
            this.overlay.style.display = 'none'
        }

        // Resume input
        this.resumeInput()

        // Restore focus
        if (this.state.previousFocus) {
            this.state.previousFocus.focus()
            this.state.previousFocus = null
        }

        // Callbacks
        this.callbacks.onMenuClose?.()
    }

    showPanel(panelId: string): void {
        // Hide current panel
        if (this.state.activePanel) {
            const currentPanel = this.panels.get(this.state.activePanel)
            currentPanel?.hide()
        }

        // Show new panel
        const panel = this.panels.get(panelId)
        if (panel) {
            panel.show()
            this.state.activePanel = panelId
            this.updateActiveTab(panelId)
        }
    }

    getState(): PauseMenuState {
        return { ...this.state }
    }

    isOpen(): boolean {
        return this.state.isOpen
    }

    private pauseInput(): void {
        if (!this.state.inputPaused) {
            this.state.inputPaused = true
            this.callbacks.onPauseInput?.()
        }
    }

    private resumeInput(): void {
        if (this.state.inputPaused) {
            this.state.inputPaused = false
            this.callbacks.onResumeInput?.()
        }
    }

    private createMenuStructure(): void {
        // Check if pause menu structure already exists
        const existingOverlay = document.getElementById(this.config.containerId)
        if (existingOverlay) {
            console.log('├░┼╕ΓÇ¥ΓÇ₧ Found existing pause menu structure, reusing it')
            this.overlay = existingOverlay
            this.menuContainer = existingOverlay.querySelector(`.${this.config.menuClass}`)

            // Verify required elements exist, if not recreate them
            if (!this.menuContainer || !existingOverlay.querySelector('#pause-menu-tabs')) {
                console.log('ΓÜá∩╕Å Existing structure incomplete, recreating...')
                existingOverlay.remove()
                this.createNewMenuStructure()
            } else {
                // Setup event handlers for existing structure
                this.setupEventHandlers()
                this.setupTabsScrolling()
            }
            return
        }

        this.createNewMenuStructure()
    }

    private createNewMenuStructure(): void {
        // Create overlay
        this.overlay = document.createElement('div')
        this.overlay.id = this.config.containerId
        this.overlay.className = this.config.overlayClass
        this.overlay.style.display = 'none'

        // Create menu container
        this.menuContainer = document.createElement('div')
        this.menuContainer.className = this.config.menuClass
        this.menuContainer.innerHTML = renderTemplate(pauseMenuStructureTemplate, {
            displayName: this.config.displayName
        })

        this.overlay.appendChild(this.menuContainer)
        document.body.appendChild(this.overlay)

        this.setupEventHandlers()
        this.setupTabsScrolling()
    }

    private setupEventHandlers(): void {
        if (!this.overlay) return

        // Setup close button
        const closeBtn = this.overlay.querySelector('#pause-menu-close')
        if (closeBtn) {
            closeBtn.addEventListener('click', () => this.close())
        }

        // Setup overlay click to close
        this.overlay.addEventListener('click', (e) => {
            if (e.target === this.overlay) {
                this.close()
            }
        })
    }

    private setupTabsScrolling(): void {
        const tabsContainer = document.getElementById('pause-menu-tabs')
        if (!tabsContainer) return

        // Mousewheel horizontal scrolling
        tabsContainer.addEventListener('wheel', (e) => {
            if (e.deltaY !== 0) {
                e.preventDefault()
                tabsContainer.scrollLeft += e.deltaY
            }
        }, { passive: false })

        // Touch horizontal scrolling (already handled by native touch events on overflow-x)
        // No additional code needed - CSS overflow-x: auto handles touch scrolling natively
    }

    private createPanelTab(panel: PauseMenuPanel): void {
        const tabsContainer = document.getElementById('pause-menu-tabs')
        if (!tabsContainer) {
            console.warn(`ΓÜá∩╕Å Cannot create tab for panel '${panel.id}': tabs container not found`)
            return
        }

        // Check if tab already exists (prevent duplicates)
        const existingTab = document.getElementById(`tab-${panel.id}`)
        if (existingTab) {
            console.log(`≡ƒöä Tab for panel '${panel.id}' already exists, skipping creation`)
            return
        }

        const tab = document.createElement('button')
        tab.id = `tab-${panel.id}`
        tab.className = 'pause-menu-tab'
        tab.innerHTML = `${panel.icon} ${panel.title}`

        tab.addEventListener('click', () => this.showPanel(panel.id))

        tabsContainer.appendChild(tab)
    }

    private updateActiveTab(panelId: string): void {
        // Remove active class from all tabs
        document.querySelectorAll('.pause-menu-tab').forEach(tab => {
            tab.classList.remove('active')
        })

        // Add active class to current tab
        const activeTab = document.getElementById(`tab-${panelId}`)
        if (activeTab) {
            activeTab.classList.add('active')
        }
    }

    private hideAllPanels(): void {
        this.panels.forEach(panel => panel.hide())
        this.state.activePanel = null
    }

    private getFirstPanelId(): string | undefined {
        return this.panels.keys().next().value
    }

    private setupKeyboardHandling(): void {
        document.addEventListener('keydown', (event) => {
            // Only handle escape if not in an input field
            if (event.key === 'Escape' && !this.isInputFocused()) {
                event.preventDefault()
                this.toggle()
            }
        })
    }

    private isInputFocused(): boolean {
        const activeElement = document.activeElement
        if (!activeElement) return false

        return activeElement.tagName === 'INPUT' ||
               activeElement.tagName === 'TEXTAREA' ||
               (activeElement as HTMLElement).contentEditable === 'true'
    }

    dispose(): void {
        // Close menu if open
        if (this.state.isOpen) {
            this.close()
        }

        // It's more complicated, but we could have the eventManager install an "onDispose" hook
        // Remove event listeners
        this.eventManager.removeEventListener(
            SteamEventTypes.DataLoaded,
            this.onSteamDataLoaded.bind(this)
        )

        // Dispose all panels
        this.panels.forEach(panel => {
            try {
                panel.dispose()
            } catch (error) {
                console.warn(`Failed to dispose panel ${panel.id}:`, error)
            }
        })
        this.panels.clear()

        // Remove DOM elements
        if (this.overlay) {
            try {
                this.overlay.remove()
            } catch (error) {
                console.warn('Failed to remove overlay:', error)
            }
            this.overlay = null
        }

        // Reset container reference
        this.menuContainer = null

        // Remove styles
        const styles = document.getElementById('pause-menu-styles')
        if (styles) {
            try {
                styles.remove()
            } catch (error) {
                console.warn('Failed to remove styles:', error)
            }
        }
    }

    private handleSettingsChange(settings: Partial<ApplicationSettings>): void {
        console.log('ΓÜÖ∩╕Å Settings changed:', settings)

        // Handle quality settings
        if (settings.qualityLevel !== undefined) {
            this.updateGraphicsQuality(settings.qualityLevel)
        }

        // Handle graphics settings
        if (settings.lightingQuality !== undefined || settings.shadowQuality !== undefined) {
            console.log('≡ƒÄ¿ Graphics settings changed, applying lighting update...')
            // Emit lighting quality change event
            if (settings.lightingQuality !== undefined) {
                this.eventManager.emit(LightingEventTypes.QualityChanged, {
                    quality: settings.lightingQuality,
                    source: EventSource.UI
                })
            }
        }

        if (settings.ceilingHeight !== undefined) {
            console.log(`≡ƒôÅ Ceiling height changed to ${settings.ceilingHeight}m`)
            // Note: Environment changes require SceneCoordinator integration (handled in next step)
        }

        // Handle lighting toggles (these can be applied immediately)
        if (settings.enableLighting !== undefined) {
            console.log(`≡ƒÆí Lighting ${settings.enableLighting ? 'enabled' : 'disabled'}`)
            this.eventManager.emit(LightingEventTypes.Toggle, { 
                enabled: settings.enableLighting 
            } as LightingToggleEvent)
        }

        if (settings.showLightingDebug !== undefined) {
            console.log(`≡ƒöì Lighting debug ${settings.showLightingDebug ? 'enabled' : 'disabled'}`)
            this.eventManager.emit(LightingEventTypes.DebugToggle, { 
                enabled: settings.showLightingDebug 
            } as LightingDebugToggleEvent)
        }
    }

    // TODO: Quality enum
    private updateGraphicsQuality(quality: 'low' | 'medium' | 'high' | 'ultra'): void {
        if (!this.systemDependencies) {
            console.warn('ΓÜá∩╕Å System dependencies not provided - cannot update graphics quality')
            return
        }

        const renderer = this.systemDependencies.renderer

        switch (quality) {
            case 'low':
                renderer.shadowMap.enabled = false
                renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1))
                break
            case 'medium':
                renderer.shadowMap.enabled = true
                renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5))
                break
            case 'high':
                renderer.shadowMap.enabled = true
                renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
                break
            case 'ultra':
                renderer.shadowMap.enabled = true
                renderer.setPixelRatio(window.devicePixelRatio)
                break
        }
    }
}

/**
 * Base class for extensible pause menu panels
 * Provides common functionality and interface for all menu panels
 */

export interface PauseMenuPanelConfig {
    containerId?: string
    className?: string
}

/**
 * RELOAD INDICATOR SYSTEM
 * 
 * Uses two data attributes for pure CSS control:
 * - data-requires-reload: Static, declared in HTML on controls that need reload
 * - data-changed: Dynamic, set by JS when value differs from initial
 * 
 * CSS :has() selectors cascade the indicator up through sections and tabs.
 * 
 * TODO: The reload requirement could be removed by implementing hot-reload
 * of LOD configs and ceiling geometry. See GpuGameBoxRenderer.buildLodConfigsFromSettings()
 */

export abstract class PauseMenuPanel {
    protected container: HTMLElement | null = null
    protected config: PauseMenuPanelConfig
    protected isVisible: boolean = false

    /** Store initial values to detect changes */
    protected initialValues: Map<string, string> = new Map()

    constructor(config: PauseMenuPanelConfig = {}) {
        this.config = {
            containerId: 'pause-menu-content',
            className: 'pause-menu-panel',
            ...config
        }
    }

    // Abstract methods that each panel must implement
    abstract readonly id: string
    abstract readonly title: string
    abstract readonly icon: string

    abstract render(): string
    abstract attachEvents(): void
    abstract onShow(): void
    abstract onHide(): void

    /**
     * Mark a control as changed or unchanged.
     * Sets data-changed attribute which CSS uses with data-requires-reload
     * to show reload indicators via :has() selectors.
     */
    protected markControlChanged(controlId: string, changed: boolean): void {
        const control = document.getElementById(controlId)
        if (control) {
            if (changed) {
                control.setAttribute('data-changed', '')
            } else {
                control.removeAttribute('data-changed')
            }
        }
    }

    /**
     * Store initial value for a control to detect changes later.
     */
    protected storeInitialValue(controlId: string, value: string): void {
        this.initialValues.set(controlId, value)
    }

    /**
     * Check if control value has changed from initial and update data-changed attribute.
     * Call this when a setting changes.
     */
    protected updateChangedState(controlId: string, currentValue: string): void {
        const initial = this.initialValues.get(controlId)
        const changed = initial !== undefined && initial !== currentValue
        this.markControlChanged(controlId, changed)
    }

    /**
     * Clear all data-changed attributes (e.g., on panel show or after reload).
     */
    protected clearAllChangedStates(): void {
        const controls = document.querySelectorAll('[data-changed]')
        controls.forEach(control => control.removeAttribute('data-changed'))
    }

    /**
     * Initialize the panel within the specified container
     */
    init(): void {
        const containerId = this.config.containerId
        if (!containerId) {
            console.warn('PauseMenuPanel: No container ID specified')
            return
        }

        this.container = document.getElementById(containerId)
        if (!this.container) {
            console.warn(`PauseMenuPanel: Container ${containerId} not found`)
            return
        }

        this.renderPanel()
        this.attachEvents()
        this.attachChangeTracking()
    }

    /**
     * Attach generic change tracking to all inputs/selects in this panel.
     * When any control changes, automatically:
     * 1. Store initial value if not yet stored
     * 2. Compare to initial and set/remove data-changed attribute
     */
    private attachChangeTracking(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const handleChange = (e: Event) => {
            const target = e.target as HTMLInputElement | HTMLSelectElement
            if (!target?.id) return

            const controlId = target.id
            const currentValue = target.value

            this.updateChangedState(controlId, currentValue)
        }

        // Listen on panel for bubbled events (more efficient than per-element)
        panel.addEventListener('input', handleChange)
        panel.addEventListener('change', handleChange)
    }

    /**
     * Store initial values for all inputs/selects in the panel.
     * Called on show to establish baseline for change detection.
     */
    protected storeAllInitialValues(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const controls = panel.querySelectorAll('input, select')
        controls.forEach(control => {
            const el = control as HTMLInputElement | HTMLSelectElement
            if (el.id) {
                this.initialValues.set(el.id, el.value)
            }
        })
    }

    /**
     * Show this panel (hide others, show this one)
     */
    show(): void {
        if (!this.container) return

        this.isVisible = true
        const panelElement = document.getElementById(`panel-${this.id}`)
        if (panelElement) {
            panelElement.style.display = 'block'
            this.onShow()
        }
    }

    /**
     * Hide this panel
     */
    hide(): void {
        if (!this.container) return

        this.isVisible = false
        const panelElement = document.getElementById(`panel-${this.id}`)
        if (panelElement) {
            panelElement.style.display = 'none'
            this.onHide()
        }
    }

    /**
     * Check if panel is currently visible
     */
    getIsVisible(): boolean {
        return this.isVisible
    }

    /**
     * Render the panel HTML structure
     */
    private renderPanel(): void {
        if (!this.container) return

        const panelHtml = `
            <div id="panel-${this.id}" class="${this.config.className}" style="display: none;">
                <div class="panel-header">
                    <h3>${this.icon} ${this.title}</h3>
                </div>
                <div class="panel-content">
                    ${this.render()}
                </div>
            </div>
        `

        this.container.insertAdjacentHTML('beforeend', panelHtml)
    }

    /**
     * Get panel DOM element
     */
    protected getPanelElement(): HTMLElement | null {
        return document.getElementById(`panel-${this.id}`)
    }

    /**
     * Add event listener helper with automatic cleanup tracking
     */
    protected addEventListener<K extends keyof HTMLElementEventMap>(
        element: HTMLElement | null,
        type: K,
        listener: (this: HTMLElement, ev: HTMLElementEventMap[K]) => void,
        options?: boolean | AddEventListenerOptions
    ): void {
        if (element) {
            element.addEventListener(type, listener, options)
            // Store for cleanup if needed
        }
    }

    /**
     * Clean up resources and remove event listeners
     */
    dispose(): void {
        const panelElement = this.getPanelElement()
        if (panelElement) {
            panelElement.remove()
        }
        this.container = null
        this.isVisible = false
    }
}

/**
 * Application Panel for Pause Menu
 * 
 * Provides application-level controls and settings:
 * - Resume application control
 * - Performance and graphics settings
 * - User preferences and interface options
 * - Debug and development tools
 * 
 * Central hub for all non-Steam related application configuration.
 * 
 * This panel serves as a UI representation of the AppSettings service,
 * displaying current settings and allowing user interaction to modify them.
 */

import { PauseMenuPanel, type PauseMenuPanelConfig } from '../PauseMenuPanel'
import '../../../styles/pause-menu/application-panel.css'
import { renderTemplate } from '../../../utils/TemplateEngine'
import applicationPanelTemplate from '../../../templates/pause-menu/application-panel.html?raw'
import { ToastManager } from '../../ToastManager'
import { AppSettings, type ApplicationSettings } from '../../../core/AppSettings'
import { EventSource } from '../../../core/EventManager'
import { UIComponentUtils } from '../../../utils/UIComponentUtils'
import type { EventManager } from '../../../core/EventManager'

export class ApplicationPanel extends PauseMenuPanel {
    public readonly id = 'application'
    public readonly title = 'Application'
    public readonly icon = 'ΓÜÖ∩╕Å'
    
    private appSettings: AppSettings
    private onSettingsChanged?: (settings: Partial<ApplicationSettings>) => void

    constructor(config: PauseMenuPanelConfig = {}, appSettings: AppSettings, _eventManager: EventManager) {
        super(config)
        this.appSettings = appSettings
    }

    /**
     * Initialize with application control callbacks
     */
    public initialize(callbacks: {
        onSettingsChanged?: (settings: Partial<ApplicationSettings>) => void
    }): void {
        this.onSettingsChanged = callbacks.onSettingsChanged
    }

    public render(): string {
        const currentSettings = this.appSettings.getAllSettings()
        return renderTemplate(applicationPanelTemplate, {
            // Quality level selections
            qualityLow: currentSettings.qualityLevel === 'low',
            qualityMedium: currentSettings.qualityLevel === 'medium',
            qualityHigh: currentSettings.qualityLevel === 'high',
            qualityUltra: currentSettings.qualityLevel === 'ultra',
            
            // Checkbox states
            showFPS: currentSettings.showFPS,
            showPerformanceStats: currentSettings.showPerformanceStats,
            hideUIInVR: currentSettings.hideUIInVR,
            verboseLogging: currentSettings.verboseLogging,
            showDebugInfo: currentSettings.showDebugInfo,
            autoSave: currentSettings.autoSave
        })
    }

    public attachEvents(): void {
        UIComponentUtils.setupButtons(this.container, [
            { buttonId: 'app-resume-btn', onClick: this.resume.bind(this) },
            { buttonId: 'app-fullscreen-btn', onClick: this.toggleFullscreen.bind(this) },
            { buttonId: 'export-logs-btn', onClick: this.exportLogs.bind(this) },
            { buttonId: 'reset-settings-btn', onClick: this.resetSettings.bind(this) },
            { buttonId: 'export-settings-btn', onClick: this.exportSettings.bind(this) },
            { buttonId: 'import-settings-btn', onClick: this.importSettings.bind(this) }
        ])

        UIComponentUtils.setupSelect<ApplicationSettings['qualityLevel']>(this.container, {
            selectId: 'quality-select',
            onChange: (value) => this.updateSetting('qualityLevel', value)
        })

        UIComponentUtils.setupToggles(this.container, [
            {
                toggleId: 'show-fps-toggle',
                onChange: (checked) => this.updateSetting('showFPS', checked)
            },
            {
                toggleId: 'show-perf-toggle',
                onChange: (checked) => this.updateSetting('showPerformanceStats', checked)
            },
            {
                toggleId: 'hide-ui-vr-toggle',
                onChange: (checked) => this.updateSetting('hideUIInVR', checked)
            },
            {
                toggleId: 'verbose-logging-toggle',
                onChange: (checked) => this.updateSetting('verboseLogging', checked)
            },
            {
                toggleId: 'show-debug-toggle',
                onChange: (checked) => this.updateSetting('showDebugInfo', checked)
            },
            {
                toggleId: 'auto-save-toggle',
                onChange: (checked) => this.updateSetting('autoSave', checked)
            }
        ])
    }

    public onShow(): void {
        // Update settings display when panel is shown
        this.refreshSettingsDisplay()
    }
    public onHide(): void {

    }

    private resume(): void {
        // Close the pause menu - emit event that parent can listen to
        this.container?.dispatchEvent(new CustomEvent('pause-menu-close', { bubbles: true }))
    }

    private toggleFullscreen(): void {
        // TODO: Consider moving this fullscreen functionality to the main pause menu header
        // for better accessibility and more prominent placement
        try {
            if (!document.fullscreenElement) {
                // Enter fullscreen
                document.documentElement.requestFullscreen().catch((err) => {
                    console.warn('Failed to enter fullscreen:', err)
                })
            } else {
                // Exit fullscreen
                document.exitFullscreen().catch((err) => {
                    console.warn('Failed to exit fullscreen:', err)
                })
            }
        } catch (error) {
            console.warn('Fullscreen API not supported or failed:', error)
        }
    }

    private updateSetting<K extends keyof ApplicationSettings>(
        key: K,
        value: ApplicationSettings[K]
    ): void {
        this.appSettings.setSetting(key, value, EventSource.UI)
        
        // Notify of settings change
        this.onSettingsChanged?.({ [key]: value })
    }

    private exportLogs(): void {
        // TODO: Implement log export functionality
        const currentSettings = this.appSettings.getAllSettings()
        const logs = {
            timestamp: new Date().toISOString(),
            settings: currentSettings,
            userAgent: navigator.userAgent,
            url: window.location.href
        }
        
        const dataStr = JSON.stringify(logs, null, 2)
        const dataBlob = new Blob([dataStr], { type: 'application/json' })
        const url = URL.createObjectURL(dataBlob)
        
        const link = document.createElement('a')
        link.href = url
        link.download = `steam-brick-mortar-logs-${Date.now()}.json`
        link.click()
        
        URL.revokeObjectURL(url)
    }

    private resetSettings(): void {
        if (window.confirm('Are you sure you want to reset all settings to defaults?\n\nThis cannot be undone.')) {
            this.appSettings.resetToDefaults(EventSource.UI)
            this.refreshSettingsDisplay()
            
            // Notify of complete settings reset
            const currentSettings = this.appSettings.getAllSettings()
            this.onSettingsChanged?.(currentSettings)
        }
    }

    private exportSettings(): void {
        const dataStr = this.appSettings.exportSettings()
        const dataBlob = new Blob([dataStr], { type: 'application/json' })
        const url = URL.createObjectURL(dataBlob)
        
        const link = document.createElement('a')
        link.href = url
        link.download = `steam-brick-mortar-settings-${Date.now()}.json`
        link.click()
        
        URL.revokeObjectURL(url)
    }

    // TODO: replace 'alert's with toast messages
    private importSettings(): void {
        const input = document.createElement('input')
        input.type = 'file'
        input.accept = '.json'
        
        input.onchange = (e) => {
            const file = (e.target as HTMLInputElement).files?.[0]
            if (!file) return
            
            const reader = new FileReader()
            reader.onload = (event) => {
                try {
                    const importedSettings = JSON.parse(event.target?.result as string)
                    
                    // Use AppSettings validation and import
                    if (this.appSettings.importSettings(importedSettings, EventSource.UI)) {
                        this.refreshSettingsDisplay()
                        
                        // Notify of settings import
                        const currentSettings = this.appSettings.getAllSettings()
                        this.onSettingsChanged?.(currentSettings)
                        
                        ToastManager.success('Settings imported successfully!')
                    } else {
                        ToastManager.error('Invalid settings file format.')
                    }
                } catch (error) {
                    console.error('Failed to import settings:', error)
                    ToastManager.error('Failed to import settings. Please check the file format.')
                }
            }
            
            reader.readAsText(file)
        }
        
        input.click()
    }

    private refreshSettingsDisplay(): void {
        // Update all form elements to reflect current settings
        const currentSettings = this.appSettings.getAllSettings()
        
        const qualitySelect = this.container?.querySelector('#quality-select') as HTMLSelectElement
        if (qualitySelect) qualitySelect.value = currentSettings.qualityLevel
        
        // Update all checkboxes
        const checkboxes = [
            { id: '#show-fps-toggle', setting: 'showFPS' as const },
            { id: '#show-perf-toggle', setting: 'showPerformanceStats' as const },
            { id: '#hide-ui-vr-toggle', setting: 'hideUIInVR' as const },
            { id: '#verbose-logging-toggle', setting: 'verboseLogging' as const },
            { id: '#show-debug-toggle', setting: 'showDebugInfo' as const },
            { id: '#auto-save-toggle', setting: 'autoSave' as const }
        ]
        
        checkboxes.forEach(({ id, setting }) => {
            const checkbox = this.container?.querySelector(id) as HTMLInputElement
            if (checkbox) {
                checkbox.checked = currentSettings[setting]
            }
        })
    }

    public getSettings(): ApplicationSettings {
        return this.appSettings.getAllSettings()
    }

    public updateSettings(newSettings: Partial<ApplicationSettings>): void {
        this.appSettings.updateSettings(newSettings, EventSource.UI)
        this.refreshSettingsDisplay()
    }

    public dispose(): void {
        // No need to manually save - AppSettings handles persistence automatically
        super.dispose()
    }
}

/**
 * CacheManagementPanel - Centralized cache management within pause menu
 * 
 * Consolidates cache operations from the scattered UI into one place
 */

import { PauseMenuPanel, type PauseMenuPanelConfig } from '../PauseMenuPanel'
import { renderTemplate } from '../../../utils/TemplateEngine'
import cacheManagementPanelTemplate from '../templates/cache-management-panel.html?raw'
import { PixelDataCache } from '../../../scene/game-box/instancing/PixelDataCache'
import { steamApi } from '../../../steam/SteamApiClient'
import { EventManager, EventSource } from '../../../core/EventManager'
import { SteamEventTypes } from '../../../types/InteractionEvents'
import '../../../styles/pause-menu/cache-management-panel.css'
import { UIComponentUtils } from '../../../utils/UIComponentUtils'

export interface CacheStats {
    imageCount: number
    totalSize: number
    lastUpdate: Date | null
}

export interface CachedUser {
    vanityUrl: string
    displayName: string
    gameCount: number
    steamId: string
}

export class CacheManagementPanel extends PauseMenuPanel {
    readonly id = 'cache-management'
    readonly title = 'Cache'
    readonly icon = '≡ƒÆ╛'

    private cacheStats: CacheStats = {
        imageCount: 0,
        totalSize: 0,
        lastUpdate: null
    }

    private cachedUsers: CachedUser[] = []
    private updateInterval: number | null = null
    private imageUrls: string[] = []
    private currentImageIndex: number = 0
    private previewerInitialized: boolean = false
    private eventManager: EventManager

    constructor(config: PauseMenuPanelConfig = {}) {
        super(config)
        this.eventManager = EventManager.getInstance()
    }

    render(): string {
        const settings = this.getSettings()

        // Get cached users for dropdown - handle case where users haven't loaded yet
        const cachedUsersOptions = this.cachedUsers.length > 0
            ? this.cachedUsers.map(user => `<option value="${user.vanityUrl}">${user.displayName} (${user.gameCount} games)</option>`).join('')
            : '<option value="" disabled>Loading cached users...</option>'

        // Prepare template data with current state
        const templateData = {
            // Cache stats (will be updated via refreshStats)
            imageCount: this.cacheStats.imageCount || 'Loading...',
            totalSize: this.cacheStats.totalSize ? this.formatBytes(this.cacheStats.totalSize) : 'Loading...',
            lastUpdate: this.cacheStats.lastUpdate?.toLocaleString() || 'Never',
            cacheApiStatus: ('caches' in window) ? 'Available' : 'Not available',
            cacheApiUnavailable: !('caches' in window),
            storageQuota: 'Calculating...',
            hasImages: this.cacheStats.imageCount > 0,

            // Cached users dropdown
            cachedUsersOptions: cachedUsersOptions,

            // Button states
            refreshButtonDisabled: '',
            validateButtonDisabled: '',
            clearButtonDisabled: '',
            downloadButtonDisabled: 'disabled', // No download function yet

            // Settings values from localStorage
            autoDownloadChecked: settings.autoDownload !== false ? 'checked' : '',
            cacheLimitValue: settings.cacheLimit || 500,
            preloadChecked: settings.preload ? 'checked' : ''
        }

        return renderTemplate(cacheManagementPanelTemplate, templateData)
    }

    /**
     * Refresh the panel template with current data
     * Called when Steam data loads to update hasImages state
     */
    refreshTemplate(): void {

        const panel = this.getPanelElement()
        if (!panel) {
            return
        }

        const contentContainer = panel.querySelector('.panel-content')
        if (!contentContainer) {
            return
        }

        // Re-render the template with current data
        contentContainer.innerHTML = this.render()

        // Re-attach event listeners since we replaced the content
        this.attachEvents()

        // If this panel is visible, refresh the stats
        if (this.isVisible) {
            this.updateCacheStats()
        }
    }

    attachEvents(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        UIComponentUtils.setupButtons(panel, [
            { buttonId: 'refresh-cache-btn', onClick: this.refreshCache.bind(this) },
            { buttonId: 'validate-cache-btn', onClick: this.validateCache.bind(this) },
            { buttonId: 'clear-cache-btn', onClick: this.clearCache.bind(this) },
            { buttonId: 'download-missing-btn', onClick: this.downloadMissing.bind(this) },
            { buttonId: 'load-cached-user-btn', onClick: this.loadSelectedCachedUser.bind(this) },
            { buttonId: 'initialize-previewer-btn', onClick: this.initializePreviewer.bind(this) },
            { buttonId: 'prev-image-btn', onClick: this.previousImage.bind(this) },
            { buttonId: 'next-image-btn', onClick: this.nextImage.bind(this) }
        ])

        UIComponentUtils.setupSelect(panel, {
            selectId: 'cached-users-select',
            onChange: () => this.onCachedUserSelectionChange()
        })

        UIComponentUtils.setupToggles(panel, [
            {
                toggleId: 'auto-download-toggle',
                onChange: (checked) => this.setSetting('autoDownload', checked)
            },
            {
                toggleId: 'preload-toggle',
                onChange: (checked) => this.setSetting('preload', checked)
            }
        ])

        UIComponentUtils.setupInput<number>(panel, {
            inputId: 'cache-limit-input',
            parseValue: (v) => parseInt(v, 10),
            onChange: (value) => this.setSetting('cacheLimit', value)
        })

        UIComponentUtils.setupInput<number>(panel, {
            inputId: 'image-index-input',
            parseValue: (v) => parseInt(v, 10),
            onChange: (index) => {
                if (!isNaN(index)) {
                    this.goToImage(index)
                }
            }
        })

        document.addEventListener('keydown', (e) => {
            if (!this.previewerInitialized) return

            if (e.key === 'ArrowLeft') {
                e.preventDefault()
                this.previousImage()
            } else if (e.key === 'ArrowRight') {
                e.preventDefault()
                this.nextImage()
            }
        })
    }

    onShow(): void {
        this.startStatsUpdate()
        this.updateCacheStats()
        this.updateStorageQuotaDisplay() // Get initial storage quota
        this.loadCachedUsers()
    }

    onHide(): void {
        this.stopStatsUpdate()
    }

    /**
     * Refresh cached users data and update dropdown
     * Call this when cache contents may have changed
     */
    refreshCachedUsers(): void {
        if (this.isVisible) {
            this.loadCachedUsers()
        }
    }

    /**
     * Load cached users for dropdown
     */
    private async loadCachedUsers(): Promise<void> {
        try {
            this.cachedUsers = steamApi.getCachedUsers()
            this.refreshCachedUsersDropdown()
        } catch (error) {
            console.error('Failed to load cached users:', error)
            this.cachedUsers = []
            this.refreshCachedUsersDropdown()
        }
    }

    /**
     * Refresh the cached users dropdown with current data
     */
    private refreshCachedUsersDropdown(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const select = panel.querySelector('#cached-users-select') as HTMLSelectElement
        if (!select) return

        // Generate options HTML based on current cached users state
        let options: string
        if (this.cachedUsers.length > 0) {
            options = this.cachedUsers
                .map(user => `<option value="${user.vanityUrl}">${user.displayName} (${user.gameCount} games)</option>`)
                .join('')
        } else {
            // Show appropriate message for empty state
            options = '<option value="" disabled>No cached users found</option>'
        }

        // Update select options (preserve the default option)
        select.innerHTML = `<option value="">Select a cached user...</option>${options}`

        // Update the load button state
        const loadBtn = panel.querySelector('#load-cached-user-btn') as HTMLButtonElement
        if (loadBtn) {
            loadBtn.disabled = true // Disable until user makes a selection
        }
    }

    /**
     * Enable cache actions when Steam profile is loaded
     */
    enableCacheActions(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const buttons = panel.querySelectorAll('.cache-btn')
        buttons.forEach(btn => {
            btn.removeAttribute('disabled')
        })
    }

    /**
     * Disable cache actions when no Steam profile is loaded
     */
    disableCacheActions(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const buttons = panel.querySelectorAll('.cache-btn')
        buttons.forEach(btn => {
            btn.setAttribute('disabled', 'true')
        })
    }

    /**
     * Start periodic cache stats updates
     */
    private startStatsUpdate(): void {
        if (this.updateInterval) return

        this.updateInterval = window.setInterval(() => {
            this.updateCacheStats()
        }, 5000) // Update every 5 seconds
    }

    /**
     * Stop periodic cache stats updates
     */
    private stopStatsUpdate(): void {
        if (this.updateInterval) {
            window.clearInterval(this.updateInterval)
            this.updateInterval = null
        }
    }

    /**
     * Update cache statistics display
     */
    private async updateCacheStats(): Promise<void> {
        try {
            // Primary: use PixelDataCache (the active texture cache)
            const pixelCache = PixelDataCache.getInstance()
            const pixelStats = await pixelCache.getStorageEstimate()

            this.cacheStats = {
                imageCount: pixelStats.count,
                totalSize: pixelStats.estimatedMB * 1024 * 1024, // Convert MB to bytes
                lastUpdate: new Date() // PixelDataCache doesn't track timestamps
            }

            this.updateStatsUI()
        } catch (error) {
            console.error('Failed to update cache stats:', error)
            this.showError('Failed to load cache statistics')
        }
    }

    /**
     * Get cache information from browser storage
     */
    private async getCacheInfo(): Promise<CacheStats> {
        // Try to get cache information from various sources
        const stats: CacheStats = {
            imageCount: 0,
            totalSize: 0,
            lastUpdate: null
        }

        try {
            // Check for cache API support
            if ('caches' in window) {
                const cacheNames = await window.caches.keys()
                for (const cacheName of cacheNames) {
                    if (cacheName.includes('steam') || cacheName.includes('image')) {
                        const cache = await window.caches.open(cacheName)
                        const requests = await cache.keys()
                        stats.imageCount += requests.length
                    }
                }
            }

            // Check localStorage for cache metadata
            const cacheMetadata = localStorage.getItem('steam-image-cache-metadata')
            if (cacheMetadata) {
                const metadata = JSON.parse(cacheMetadata)
                stats.totalSize = metadata.totalSize ?? 0
                stats.lastUpdate = metadata.lastUpdate ? new Date(metadata.lastUpdate) : null
            }

            // Estimate size if not available
            if (stats.totalSize === 0 && stats.imageCount > 0) {
                stats.totalSize = stats.imageCount * 150000 // Estimate 150KB per image
            }

        } catch (error) {
            console.warn('Could not get detailed cache info:', error)
            // Fallback to basic localStorage check
            const keys = Object.keys(localStorage).filter(key => 
                key.includes('steam') || key.includes('cache') || key.includes('image')
            )
            stats.imageCount = keys.length
        }

        return stats
    }

    /**
     * Update the statistics UI elements
     */
    private updateStatsUI(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const imageCountEl = panel.querySelector('#cache-image-count')
        const totalSizeEl = panel.querySelector('#cache-total-size')
        const lastUpdateEl = panel.querySelector('#cache-last-update')

        if (imageCountEl) {
            imageCountEl.textContent = this.cacheStats.imageCount.toString()
        }

        if (totalSizeEl) {
            totalSizeEl.textContent = this.formatBytes(this.cacheStats.totalSize)
        }

        if (lastUpdateEl) {
            lastUpdateEl.textContent = this.cacheStats.lastUpdate 
                ? this.cacheStats.lastUpdate.toLocaleString()
                : 'Never'
        }
    }

    /**
     * Refresh cache by re-downloading recent items
     */
    private async refreshCache(): Promise<void> {
        const panel = this.getPanelElement()
        if (!panel) return

        const btn = panel.querySelector('#refresh-cache-btn')
        if (!btn) return

        btn.textContent = '├░┼╕ΓÇ¥ΓÇ₧ Refreshing...'
        btn.setAttribute('disabled', 'true')

        try {
            // Refresh stats from PixelDataCache
            await this.updateCacheStats()

            this.showSuccess('Cache refreshed successfully')
        } catch (error) {
            console.error('Cache refresh failed:', error)
            this.showError('Failed to refresh cache')
        } finally {
            btn.textContent = '├░┼╕ΓÇ¥ΓÇ₧ Refresh Cache'
            btn.removeAttribute('disabled')
        }
    }

    /**
     * Validate cache and remove corrupted/empty images
     * TODO: PixelDataCache doesn't have validation yet - for now just refresh stats
     */
    private async validateCache(): Promise<void> {
        const panel = this.getPanelElement()
        if (!panel) return

        const btn = panel.querySelector('#validate-cache-btn')
        if (!btn) return

        btn.textContent = '├░┼╕ΓÇ¥┬ì Validating...'
        btn.setAttribute('disabled', 'true')

        try {
            // PixelDataCache uses versioning for invalidation, no per-entry validation needed
            // Just refresh the stats to show current state
            await this.updateCacheStats()

            this.showSuccess('Cache validation complete. Pixel cache uses version-based invalidation.')
        } catch (error) {
            console.error('Cache validation failed:', error)
            this.showError('Failed to validate cache')
        } finally {
            btn.textContent = '├░┼╕ΓÇ¥┬ì Validate Cache'
            btn.removeAttribute('disabled')
        }
    }

    /**
     * Clear all cached data
     */
    private async clearCache(): Promise<void> {
        const confirmed = window.confirm('Are you sure you want to clear all cached data? This will require re-downloading images.')
        if (!confirmed) return

        const panel = this.getPanelElement()
        if (!panel) return

        const btn = panel.querySelector('#clear-cache-btn')
        if (!btn) return

        btn.textContent = '├░┼╕ΓÇöΓÇÿ├»┬╕┬Å Clearing...'
        btn.setAttribute('disabled', 'true')

        try {
            // Clear PixelDataCache (the active texture cache)
            const pixelCache = PixelDataCache.getInstance()
            await pixelCache.clear()

            // Also clear Steam API cache (metadata)
            steamApi.clearCache()

            this.showSuccess('Cache cleared successfully')
            this.updateCacheStats()
        } catch (error) {
            console.error('Cache clear failed:', error)
            this.showError('Failed to clear cache')
        } finally {
            btn.textContent = '├░┼╕ΓÇöΓÇÿ├»┬╕┬Å Clear Cache'
            btn.removeAttribute('disabled')
        }
    }

    /**
     * Handle cached user selection change
     */
    private onCachedUserSelectionChange(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const select = panel.querySelector('#cached-users-select') as HTMLSelectElement
        const loadBtn = panel.querySelector('#load-cached-user-btn') as HTMLButtonElement

        if (select && loadBtn) {
            loadBtn.disabled = !select.value
        }
    }

    /**
     * Load the selected cached user
     */
    private async loadSelectedCachedUser(): Promise<void> {
        const panel = this.getPanelElement()
        if (!panel) return

        const select = panel.querySelector('#cached-users-select') as HTMLSelectElement
        const loadBtn = panel.querySelector('#load-cached-user-btn') as HTMLButtonElement

        if (!select || !loadBtn || !select.value) return

        const selectedVanityUrl = select.value

        loadBtn.textContent = '├░┼╕ΓÇ£ΓÇ╣ Loading...'
        loadBtn.disabled = true

        try {
            // Emit event to load cached user - this is a complex workflow
            this.eventManager.emit(SteamEventTypes.LoadFromCache, {
                userInput: selectedVanityUrl,
                source: EventSource.UI
            })

            this.showSuccess(`Loading cached games for ${selectedVanityUrl}...`)
        } catch (error) {
            console.error('Failed to load cached user:', error)
            this.showError('Failed to load cached user games')
        } finally {
            loadBtn.textContent = '├░┼╕ΓÇ£ΓÇ╣ Load Selected User'
            loadBtn.disabled = !select.value
        }
    }

    /**
     * Download missing images
     */
    private async downloadMissing(): Promise<void> {
        const panel = this.getPanelElement()
        if (!panel) return

        const btn = panel.querySelector('#download-missing-btn')
        if (!btn) return

        btn.textContent = '├░┼╕ΓÇ£┬Ñ Downloading...'
        btn.setAttribute('disabled', 'true')

        try {
            // Simulate download operation
            await new Promise(resolve => setTimeout(resolve, 3000))

            this.showSuccess('Missing images downloaded')
            this.updateCacheStats()
        } catch (error) {
            console.error('Download failed:', error)
            this.showError('Failed to download missing images')
        } finally {
            btn.textContent = '├░┼╕ΓÇ£┬Ñ Download Missing'
            btn.removeAttribute('disabled')
        }
    }

    /**
     * Set a cache setting
     */
    private setSetting(key: string, value: boolean | number | string): void {
        const settings = this.getSettings()
        settings[key] = value
        localStorage.setItem('cache-settings', JSON.stringify(settings))
        this.showSuccess(`Setting updated: ${key}`)
    }

    /**
     * Get cache settings from localStorage
     */
    private getSettings(): Record<string, boolean | number | string> {
        try {
            const settings = localStorage.getItem('cache-settings')
            return settings ? JSON.parse(settings) : {}
        } catch {
            return {}
        }
    }

    /**
     * Format bytes to human readable string
     */
    private formatBytes(bytes: number): string {
        if (bytes === 0) return '0 B'
        const k = 1024
        const sizes = ['B', 'KB', 'MB', 'GB']
        const i = Math.floor(Math.log(bytes) / Math.log(k))
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    }

    /**
     * Update storage quota display
     */
    private updateStorageQuotaDisplay(): void {
        if ('storage' in navigator && 'estimate' in navigator.storage) {
            navigator.storage.estimate().then(estimate => {
                const used = estimate.usage ?? 0
                const quota = estimate.quota ?? 0
                const usedMB = Math.round(used / 1024 / 1024)
                const quotaMB = Math.round(quota / 1024 / 1024)

                const panel = this.getPanelElement()
                const quotaEl = panel?.querySelector('#storage-quota')
                if (quotaEl) {
                    quotaEl.textContent = `${usedMB} MB / ${quotaMB} MB`
                }
            })
        }
    }

    /**
     * Get storage quota information
     */
    private getStorageQuota(): string {
        this.updateStorageQuotaDisplay() // Trigger async update
        return 'Calculating...'
    }

    /**
     * Show success message
     */
    private showSuccess(message: string): void {
        this.showMessage(message, 'success')
    }

    /**
     * Show error message
     */
    private showError(message: string): void {
        this.showMessage(message, 'error')
    }

    /**
     * Show a temporary message
     */
    private showMessage(message: string, type: 'success' | 'error'): void {
        const messageDiv = document.createElement('div')
        messageDiv.className = `cache-message cache-message-${type}`
        messageDiv.textContent = message

        const panel = this.getPanelElement()
        const content = panel?.querySelector('.panel-content')
        if (content) {
            content.insertBefore(messageDiv, content.firstChild)

            setTimeout(() => {
                messageDiv.remove()
            }, 3000)
        }
    }

    /**
     * Initialize the image previewer
     * @deprecated Image previewer requires blob cache which was removed. 
     * PixelDataCache stores RGBA pixels, not blobs.
     */
    private async initializePreviewer(): Promise<void> {
        // Image previewer disabled - no longer have blob cache
        // PixelDataCache stores decoded RGBA pixels, not displayable blobs
        this.showError('Image previewer not available - cache stores pixel data, not images')
    }

    /**
     * Navigate to previous image
     */
    private previousImage(): void {
        if (!this.previewerInitialized || this.imageUrls.length === 0) return

        this.currentImageIndex = this.currentImageIndex > 0 
            ? this.currentImageIndex - 1 
            : this.imageUrls.length - 1
        this.loadCurrentImage()
        this.updateIndexInput()
    }

    /**
     * Navigate to next image
     */
    private nextImage(): void {
        if (!this.previewerInitialized || this.imageUrls.length === 0) return

        this.currentImageIndex = this.currentImageIndex < this.imageUrls.length - 1 
            ? this.currentImageIndex + 1 
            : 0
        this.loadCurrentImage()
        this.updateIndexInput()
    }

    /**
     * Jump to specific image index
     */
    private goToImage(index: number): void {
        if (!this.previewerInitialized || this.imageUrls.length === 0) return

        const boundedIndex = Math.max(0, Math.min(index - 1, this.imageUrls.length - 1)) // Convert 1-based to 0-based
        this.currentImageIndex = boundedIndex
        this.loadCurrentImage()
    }

    /**
     * Show previewer navigation controls
     */
    private showPreviewerNavigation(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const navigation = panel.querySelector('#previewer-navigation') as HTMLElement
        const container = panel.querySelector('#image-preview-container') as HTMLElement

        if (navigation) navigation.classList.remove('hidden')
        if (container) container.classList.remove('hidden')
    }

    /**
     * Load current image into preview
     */
    private async loadCurrentImage(): Promise<void> {
        if (this.imageUrls.length === 0) return

        const panel = this.getPanelElement()
        if (!panel) return

        const imageElement = panel.querySelector('#preview-image') as HTMLImageElement
        const nameElement = panel.querySelector('#image-name')

        if (!imageElement) return

        const currentUrl = this.imageUrls[this.currentImageIndex]

        // Image previewer disabled - blob cache removed
        // Just show the URL directly (will fetch from CDN)
        imageElement.src = currentUrl

        // Extract filename from URL for display
        const filename = currentUrl.split('/').pop() || 'Unknown'
        if (nameElement) {
            nameElement.textContent = filename
        }

        // Update image size info when loaded
        imageElement.onload = () => {
            const sizeElement = panel.querySelector('#image-size')
            if (sizeElement) {
                sizeElement.textContent = `${imageElement.naturalWidth} ├âΓÇö ${imageElement.naturalHeight}`
            }
        }
    }

    /**
     * Update the index input value
     */
    private updateIndexInput(): void {
        const panel = this.getPanelElement()
        if (!panel) return

        const indexInput = panel.querySelector('#image-index-input') as HTMLInputElement
        if (indexInput) {
            indexInput.value = (this.currentImageIndex + 1).toString() // Convert 0-based to 1-based
        }
    }

    dispose(): void {
        this.stopStatsUpdate()

        // Clean up any blob URLs to prevent memory leaks
        const panel = this.getPanelElement()
        if (panel) {
            const imageElement = panel.querySelector('#preview-image') as HTMLImageElement
            if (imageElement && imageElement.dataset.blobUrl) {
                URL.revokeObjectURL(imageElement.dataset.blobUrl)
                delete imageElement.dataset.blobUrl
            }
        }

        super.dispose()
    }
}

/**
 * CameraSettingsPanel - Camera and perspective settings
 * 
 * Dedicated panel for camera-related settings:
 * - Field of View (FOV) adjustment
 * - Near/Far clipping plane distances
 * - Camera preset selection (Normal, Wide, Cinematic, etc.)
 * - Multiple camera management and switching
 */

import { PauseMenuPanel, type PauseMenuPanelConfig } from '../PauseMenuPanel'
import { renderTemplate } from '../../../utils/TemplateEngine'
import cameraSettingsPanelTemplate from '../../../templates/pause-menu/camera-settings-panel.html?raw'
import '../../../styles/pause-menu/camera-settings-panel.css'
import { AppSettings } from '../../../core/AppSettings'
import { DataManager } from '../../../core/data'
import { UIComponentUtils } from '../../../utils/UIComponentUtils'
import type * as THREE from 'three'

export interface CameraPreset {
    name: string
    fov: number
    near: number
    far: number
    description: string
}

export const CAMERA_PRESETS: { [key: string]: CameraPreset } = {
    NORMAL: {
        name: 'Normal',
        fov: 75,
        near: 0.1,
        far: 1000,
        description: 'Standard perspective, natural look'
    },
    WIDE: {
        name: 'Wide',
        fov: 90,
        near: 0.1,
        far: 1000,
        description: 'Wider view, better for VR (default)'
    },
    ULTRA_WIDE: {
        name: 'Ultra Wide',
        fov: 110,
        near: 0.1,
        far: 1000,
        description: 'Maximum awareness, slight distortion'
    },
    CINEMATIC: {
        name: 'Cinematic',
        fov: 60,
        near: 0.1,
        far: 1000,
        description: 'Narrow FOV, focused view, less distortion'
    },
    TELEPHOTO: {
        name: 'Telephoto',
        fov: 45,
        near: 0.5,
        far: 1000,
        description: 'Very narrow, compressed perspective'
    }
}

export class CameraSettingsPanel extends PauseMenuPanel {
    readonly id = 'camera-settings'
    readonly title = 'Camera'
    readonly icon = '≡ƒô╖'

    private appSettings: AppSettings
    private dataManager: DataManager
    private currentCameraIndex: number = 0
    private cameras: THREE.PerspectiveCamera[] = []

    constructor(config: PauseMenuPanelConfig = {}, appSettings: AppSettings) {
        super(config)
        this.appSettings = appSettings
        this.dataManager = DataManager.getInstance()
        this.loadCameras()
    }

    private loadCameras(): void {
        // Load main scene camera
        const mainCamera = this.dataManager.get<THREE.PerspectiveCamera>('core.mainCamera')
        if (mainCamera) {
            this.cameras.push(mainCamera)
        }
    }

    private getCurrentCamera(): THREE.PerspectiveCamera | null {
        return this.cameras[this.currentCameraIndex] || null
    }

    render(): string {
        const camera = this.getCurrentCamera()
        const currentPreset = this.detectCurrentPreset(camera)
        
        return renderTemplate(cameraSettingsPanelTemplate, {
            // Camera selection
            cameraCount: this.cameras.length,
            currentCameraIndex: this.currentCameraIndex + 1,
            hasPrevCamera: this.currentCameraIndex > 0,
            hasNextCamera: this.currentCameraIndex < this.cameras.length - 1,
            
            // Current camera values
            fov: camera?.fov?.toFixed(0) || 90,
            near: camera?.near?.toFixed(2) || 0.1,
            far: camera?.far?.toFixed(0) || 1000,
            
            // Preset selections
            presetNormal: currentPreset === 'NORMAL',
            presetWide: currentPreset === 'WIDE',
            presetUltraWide: currentPreset === 'ULTRA_WIDE',
            presetCinematic: currentPreset === 'CINEMATIC',
            presetTelephoto: currentPreset === 'TELEPHOTO',
            presetCustom: currentPreset === 'CUSTOM'
        })
    }
    
    onShow(): void {
        // Reload cameras when panel is shown
        this.loadCameras()
    }
    
    onHide(): void {
        // Nothing to cleanup
    }

    private detectCurrentPreset(camera: THREE.PerspectiveCamera | null): string {
        if (!camera) return 'CUSTOM'
        
        for (const [key, preset] of Object.entries(CAMERA_PRESETS)) {
            if (Math.abs(camera.fov - preset.fov) < 1 &&
                Math.abs(camera.near - preset.near) < 0.01 &&
                Math.abs(camera.far - preset.far) < 1) {
                return key
            }
        }
        
        return 'CUSTOM'
    }

    attachEvents(): void {
        this.attachCameraNavigationEvents()
        this.attachPresetEvents()
        this.attachSliderEvents()
    }

    private attachCameraNavigationEvents(): void {
        UIComponentUtils.setupButtons(this.container, [
            {
                buttonId: 'camera-prev-btn',
                onClick: () => {
                    if (this.currentCameraIndex > 0) {
                        this.currentCameraIndex--
                        this.updateCameraDisplay()
                    }
                }
            },
            {
                buttonId: 'camera-next-btn',
                onClick: () => {
                    if (this.currentCameraIndex < this.cameras.length - 1) {
                        this.currentCameraIndex++
                        this.updateCameraDisplay()
                    }
                }
            }
        ])
    }

    private attachPresetEvents(): void {
        UIComponentUtils.setupDataButtons(
            this.container,
            '[data-camera-preset]',
            'cameraPreset',
            (presetKey: string) => {
                if (CAMERA_PRESETS[presetKey]) {
                    this.applyPreset(CAMERA_PRESETS[presetKey])
                }
            }
        )
    }

    private attachSliderEvents(): void {
        UIComponentUtils.setupSliders(this.container, [
            {
                sliderId: 'camera-fov',
                valueDisplayId: 'camera-fov-value',
                formatDisplay: (v) => v.toFixed(0) + '┬░',
                onChange: (value) => {
                    const camera = this.getCurrentCamera()
                    if (camera) {
                        camera.fov = value
                        camera.updateProjectionMatrix()
                    }
                }
            },
            {
                sliderId: 'camera-near',
                valueDisplayId: 'camera-near-value',
                formatDisplay: (v) => v.toFixed(2),
                onChange: (value) => {
                    const camera = this.getCurrentCamera()
                    if (camera) {
                        camera.near = value
                        camera.updateProjectionMatrix()
                    }
                }
            },
            {
                sliderId: 'camera-far',
                valueDisplayId: 'camera-far-value',
                formatDisplay: (v) => v.toFixed(0),
                onChange: (value) => {
                    const camera = this.getCurrentCamera()
                    if (camera) {
                        camera.far = value
                        camera.updateProjectionMatrix()
                    }
                }
            }
        ])
    }

    private applyPreset(preset: CameraPreset): void {
        const camera = this.getCurrentCamera()
        if (!camera) return
        
        camera.fov = preset.fov
        camera.near = preset.near
        camera.far = preset.far
        camera.updateProjectionMatrix()
        
        this.updateCameraDisplay()
    }
    
    private updateCameraDisplay(): void {
        const camera = this.getCurrentCamera()
        if (!camera) return
        
        // Update camera index display
        const indexDisplay = this.container?.querySelector('#camera-index-display')
        if (indexDisplay) {
            indexDisplay.textContent = `${this.currentCameraIndex + 1}`
        }
        
        // Update all slider values
        UIComponentUtils.updateSliderValue(
            this.container,
            'camera-fov',
            'camera-fov-value',
            camera.fov,
            (v) => v.toFixed(0) + '┬░'
        )
        
        UIComponentUtils.updateSliderValue(
            this.container,
            'camera-near',
            'camera-near-value',
            camera.near,
            (v) => v.toFixed(2)
        )
        
        UIComponentUtils.updateSliderValue(
            this.container,
            'camera-far',
            'camera-far-value',
            camera.far,
            (v) => v.toFixed(0)
        )
    }
}

/**
 * DebugPanel - Development and diagnostic tools
 * 
 * Provides debug information for development and troubleshooting:
 * - Three.js scene object counts
 * - Performance metrics and memory usage
 * - Cache statistics and diagnostics
 * - Console access toggle
 */

import { PauseMenuPanel, type PauseMenuPanelConfig } from '../PauseMenuPanel'
import { renderTemplate } from '../../../utils/TemplateEngine'
import debugPanelTemplate from '../templates/debug-panel.html?raw'
import '../../../styles/pause-menu/debug-panel.css'
import { DebugStatsProvider } from './DebugStatsProvider'
import type { PerformanceMonitorUI } from '../../PerformanceMonitor'

export interface DebugStats {
    // Three.js Scene Stats
    sceneObjects: {
        total: number
        meshes: number
        lights: number
        cameras: number
        textures: number
        materials: number
        geometries: number
    }

    // Performance Stats
    performance: {
        fps: number
        frameTime: number
        memoryUsed: number
        memoryTotal: number
        triangles: number
        drawCalls: number
    }

    // Cache Stats
    cache: {
        imageCount: number
        imageCacheSize: number
        gameDataCount: number
        gameDataSize: number
        quotaUsed: number
        quotaTotal: number
    }

    // System Info
    system: {
        userAgent: string
        webxrSupported: boolean
        webglVersion: string
        maxTextureSize: number
        vendor: string
        renderer: string
    }
}

export class DebugPanel extends PauseMenuPanel {
    readonly id = 'debug'
    readonly title = 'Debug'
    readonly icon = '≡ƒöº'

    private updateInterval: number | null = null
    private stats: DebugStats = this.getInitialStats()
    private currentStats: DebugStats | null = null
    private debugStatsProvider: DebugStatsProvider
    private consoleVisible = false

    constructor(config: PauseMenuPanelConfig = {}, performanceMonitor: PerformanceMonitorUI) {
        super(config)

        this.debugStatsProvider = new DebugStatsProvider(performanceMonitor);
    }

    render(): string {
        // Flatten the hierarchical stats data for the simple template engine
        const templateData = {
            // Console state
            consoleActiveClass: this.consoleVisible ? 'primary' : 'secondary',
            consoleButtonText: this.consoleVisible ? '≡ƒÖê Hide Console' : '≡ƒæü∩╕Å Show Console',
            consoleVisibilityClass: this.consoleVisible ? 'visible' : 'hidden',

            // Scene objects (flattened)
            sceneObjectsTotal: this.stats.sceneObjects.total,
            sceneObjectsMeshes: this.stats.sceneObjects.meshes,
            sceneObjectsLights: this.stats.sceneObjects.lights,
            sceneObjectsCameras: this.stats.sceneObjects.cameras,
            sceneObjectsTextures: this.stats.sceneObjects.textures,
            sceneObjectsMaterials: this.stats.sceneObjects.materials,
            sceneObjectsGeometries: this.stats.sceneObjects.geometries,

            // Performance (flattened and formatted)
            performanceFpsClass: this.getPerformanceClass('fps'),
            performanceFps: this.stats.performance.fps.toFixed(1),
            performanceFrameTime: this.stats.performance.frameTime.toFixed(2) + 'ms',
            performanceMemoryClass: this.getPerformanceClass('memory'),
            performanceMemoryUsed: this.formatBytes(this.stats.performance.memoryUsed),
            performanceMemoryTotal: this.formatBytes(this.stats.performance.memoryTotal),
            performanceTriangles: this.stats.performance.triangles.toLocaleString(),
            performanceDrawCallsClass: this.getPerformanceClass('drawCalls'),
            performanceDrawCalls: this.stats.performance.drawCalls,

            // Cache (flattened and formatted)
            cacheImageCount: this.stats.cache.imageCount,
            cacheImageSize: this.formatBytes(this.stats.cache.imageCacheSize),
            cacheGameDataCount: this.stats.cache.gameDataCount,
            cacheGameDataSize: this.formatBytes(this.stats.cache.gameDataSize),
            cacheQuotaClass: this.getPerformanceClass('quota'),
            cacheQuotaUsage: this.formatQuotaUsage(),

            // System (flattened and formatted)
            systemWebxrClass: this.stats.system.webxrSupported ? 'good' : 'warning',
            systemWebxrText: this.stats.system.webxrSupported ? 'Γ£à Available' : 'Γ¥î Not Available',
            systemWebglVersion: this.stats.system.webglVersion,
            systemMaxTextureSize: this.stats.system.maxTextureSize + 'px',
            systemVendor: this.stats.system.vendor,
            systemRenderer: this.stats.system.renderer
        }

        return renderTemplate(debugPanelTemplate, templateData)
    }

    attachEvents(): void {
        const refreshButton = document.getElementById('refresh-debug')
        if (refreshButton) {
            refreshButton.addEventListener('click', () => this.refreshStats())
        }

        const consoleButton = document.getElementById('toggle-console')
        if (consoleButton) {
            consoleButton.addEventListener('click', () => this.toggleConsole())
        }

        const exportButton = document.getElementById('export-debug')
        if (exportButton) {
            exportButton.addEventListener('click', () => this.exportDebugInfo())
        }

        const clearConsoleButton = document.getElementById('clear-console')
        if (clearConsoleButton) {
            clearConsoleButton.addEventListener('click', () => this.clearConsole())
        }
    }

    private async refreshStats(): Promise<void> {
        try {
            this.stats = await this.debugStatsProvider.getDebugStats()
            this.currentStats = this.stats
            this.refresh()
            console.log('≡ƒöº Debug stats refreshed')
        } catch (error) {
            console.error('Failed to refresh debug stats:', error)
        }
    }

    private toggleConsole(): void {
        this.consoleVisible = !this.consoleVisible
        this.refresh()

        if (this.consoleVisible) {
            this.setupConsoleCapture()
        } else {
            this.removeConsoleCapture()
        }
    }

    // TODO: I think this isn't doing us any good and should be deleted
    private setupConsoleCapture(): void {
        // Capture console output and display in debug console
        const originalLog = console.log
        const originalWarn = console.warn
        const originalError = console.error

        const addToConsole = (type: string, ...args: unknown[]) => {
            const consoleOutput = document.getElementById('console-output')
            if (consoleOutput) {
                const line = document.createElement('div')
                line.className = `console-line ${type}`
                line.textContent = `[${new Date().toLocaleTimeString()}] ${args.join(' ')}`
                consoleOutput.appendChild(line)
                consoleOutput.scrollTop = consoleOutput.scrollHeight
            }
        }

        console.log = (...args: unknown[]) => {
            originalLog.apply(console, args)
            addToConsole('info', ...args)
        }

        console.warn = (...args: unknown[]) => {
            originalWarn.apply(console, args)
            addToConsole('warning', ...args)
        }

        console.error = (...args: unknown[]) => {
            originalError.apply(console, args)
            addToConsole('error', ...args)
        }
    }

    private removeConsoleCapture(): void {
        // Note: In a real implementation, you'd need to store the original functions
        // and restore them here. For now, this is a placeholder.
    }

    private clearConsole(): void {
        const consoleOutput = document.getElementById('console-output')
        if (consoleOutput) {
            consoleOutput.innerHTML = '<div class="console-line info">Console cleared.</div>'
        }
    }

    private exportDebugInfo(): void {
        const debugInfo = {
            timestamp: new Date().toISOString(),
            stats: this.stats,
            userAgent: navigator.userAgent,
            url: window.location.href,
            localStorage: Object.keys(localStorage).length
        }

        const debugJson = JSON.stringify(debugInfo, null, 2)
        const blob = new Blob([debugJson], { type: 'application/json' })
        const url = URL.createObjectURL(blob)

        const a = document.createElement('a')
        a.href = url
        a.download = `debug-info-${Date.now()}.json`
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)
        URL.revokeObjectURL(url)

        console.log('≡ƒöº Debug information exported')
    }

    private getInitialStats(): DebugStats {
        return {
            sceneObjects: {
                total: 0,
                meshes: 0,
                lights: 0,
                cameras: 0,
                textures: 0,
                materials: 0,
                geometries: 0
            },
            performance: {
                fps: 0,
                frameTime: 0,
                memoryUsed: 0,
                memoryTotal: 0,
                triangles: 0,
                drawCalls: 0
            },
            cache: {
                imageCount: 0,
                imageCacheSize: 0,
                gameDataCount: 0,
                gameDataSize: 0,
                quotaUsed: 0,
                quotaTotal: 0
            },
            system: {
                userAgent: navigator.userAgent,
                webxrSupported: false,
                webglVersion: 'Unknown',
                maxTextureSize: 0,
                vendor: 'Unknown',
                renderer: 'Unknown'
            }
        }
    }

    private getPerformanceClass(metric: string): string {
        switch (metric) {
            case 'fps':
                if (this.stats.performance.fps < 30) return 'warning'
                if (this.stats.performance.fps < 45) return 'caution'
                return 'good'
            case 'memory': {
                const memoryPercent = this.stats.performance.memoryUsed / this.stats.performance.memoryTotal
                if (memoryPercent > 0.9) return 'warning'
                if (memoryPercent > 0.7) return 'caution'
                return 'good'
            }
            case 'drawCalls':
                if (this.stats.performance.drawCalls > 1000) return 'warning'
                if (this.stats.performance.drawCalls > 500) return 'caution'
                return 'good'
            case 'quota': {
                const quotaPercent = this.stats.cache.quotaUsed / this.stats.cache.quotaTotal
                if (quotaPercent > 0.9) return 'warning'
                if (quotaPercent > 0.7) return 'caution'
                return 'good'
            }
            default:
                return ''
        }
    }

    private formatBytes(bytes: number): string {
        if (bytes === 0) return '0 B'
        const k = 1024
        const sizes = ['B', 'KB', 'MB', 'GB']
        const i = Math.floor(Math.log(bytes) / Math.log(k))
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    }

    private formatQuotaUsage(): string {
        const used = this.formatBytes(this.stats.cache.quotaUsed)
        const total = this.formatBytes(this.stats.cache.quotaTotal)
        const percent = ((this.stats.cache.quotaUsed / this.stats.cache.quotaTotal) * 100).toFixed(1)
        return `${used} / ${total} (${percent}%)`
    }

    onShow(): void {
        // Start auto-refresh when panel is visible
        this.updateInterval = window.setInterval(() => {
            this.refreshStats()
        }, 2000)

        // Initial refresh
        this.refreshStats()
    }

    onHide(): void {
        // Stop auto-refresh when panel is hidden
        if (this.updateInterval !== null) {
            window.clearInterval(this.updateInterval)
            this.updateInterval = null
        }

        // Hide console if visible
        if (this.consoleVisible) {
            this.consoleVisible = false
            this.removeConsoleCapture()
        }
    }

    private refresh(): void {
        if (this.container && this.isVisible) {
            // Only refresh if panel is actually visible to avoid interfering with tab switching
            this.updateStatsDisplay()
        }
    }

    private updateStatsDisplay(): void {
        if (!this.container) return

        // Instead of replacing innerHTML, update individual stat elements
        // This prevents disrupting the DOM structure and tab switching
        if (this.currentStats) {
            this.updateSceneStats(this.currentStats.sceneObjects)
            this.updatePerformanceStats(this.currentStats.performance)
            this.updateCacheStats(this.currentStats.cache)
            this.updateSystemStats(this.currentStats.system)
        }
    }

    private updateSceneStats(stats: DebugStats['sceneObjects']): void {
        const updateStat = (id: string, value: number) => {
            const element = document.getElementById(id)
            if (element) element.textContent = value.toString()
        }

        updateStat('stat-total-objects', stats.total)
        updateStat('stat-meshes', stats.meshes)
        updateStat('stat-lights', stats.lights)
        updateStat('stat-cameras', stats.cameras)
        updateStat('stat-textures', stats.textures)
        updateStat('stat-materials', stats.materials)
        updateStat('stat-geometries', stats.geometries)
    }

    private updatePerformanceStats(stats: DebugStats['performance']): void {
        const updateStat = (id: string, value: number, suffix: string = '') => {
            const element = document.getElementById(id)
            if (element) element.textContent = value.toString() + suffix
        }

        updateStat('stat-fps', Math.round(stats.fps))
        updateStat('stat-frame-time', parseFloat(stats.frameTime.toFixed(2)), 'ms')
        updateStat('stat-memory-used', Math.round(stats.memoryUsed / 1024 / 1024), 'MB')
        updateStat('stat-memory-total', Math.round(stats.memoryTotal / 1024 / 1024), 'MB')
        updateStat('stat-triangles', stats.triangles)
        updateStat('stat-draw-calls', stats.drawCalls)
    }

    private updateCacheStats(stats: DebugStats['cache']): void {
        const updateStat = (id: string, value: number, suffix: string = '') => {
            const element = document.getElementById(id)
            if (element) element.textContent = value.toString() + suffix
        }

        const updateQuotaUsage = () => {
            const element = document.getElementById('stat-quota-used')
            if (element) {
                const used = this.formatBytes(stats.quotaUsed)
                const total = this.formatBytes(stats.quotaTotal)
                const percent = ((stats.quotaUsed / stats.quotaTotal) * 100).toFixed(1)
                element.textContent = `${used} / ${total} (${percent}%)`
            }
        }

        updateStat('stat-image-count', stats.imageCount)
        updateStat('stat-image-cache-size', Math.round(stats.imageCacheSize / 1024 / 1024), 'MB')
        updateStat('stat-game-data-count', stats.gameDataCount)
        updateStat('stat-game-data-size', Math.round(stats.gameDataSize / 1024), 'KB')
        updateQuotaUsage()
    }

    private updateSystemStats(stats: DebugStats['system']): void {
        const updateStat = (id: string, value: string | number) => {
            const element = document.getElementById(id)
            if (element) element.textContent = value.toString()
        }

        updateStat('stat-webxr-supported', stats.webxrSupported ? 'Yes' : 'No')
        updateStat('stat-webgl-version', stats.webglVersion)
        updateStat('stat-max-texture-size', stats.maxTextureSize + 'px')
        updateStat('stat-vendor', stats.vendor)
        updateStat('stat-renderer', stats.renderer)
    }

    private fullRefresh(): void {
        // Full refresh that rebuilds the entire panel - only use when necessary
        if (this.container && this.isVisible) {
            this.container.innerHTML = this.render()
            this.attachEvents()
        }
    }

    dispose(): void {
        if (this.updateInterval !== null) {
            window.clearInterval(this.updateInterval)
        }
        this.removeConsoleCapture()
    }
}

/**
 * Debug Statistics Provider
 *
 * Provides comprehensive debug statistics for the application.
 * No constructor dependencies ΓÇö reads scene and renderer from DataManager,
 * and performance stats from the PerformanceMonitorUI registered there.
 */

import * as THREE from 'three'
import { DataManager } from '../../../core/data/DataManager'
import { DataKey } from '../../../core/data/DataTypes'
import type { PerformanceMonitorUI } from '../..'

export interface DebugStats {
    sceneObjects: {
        total: number
        meshes: number
        lights: number
        cameras: number
        textures: number
        materials: number
        geometries: number
    }
    performance: {
        fps: number
        frameTime: number
        memoryUsed: number
        memoryTotal: number
        triangles: number
        drawCalls: number
    }
    cache: {
        imageCount: number
        imageCacheSize: number
        gameDataCount: number
        gameDataSize: number
        quotaUsed: number
        quotaTotal: number
    }
    system: {
        userAgent: string
        webxrSupported: boolean
        webglVersion: string
        maxTextureSize: number
        vendor: string
        renderer: string
    }
}

export class DebugStatsProvider {
    performanceMonitor: PerformanceMonitorUI

    constructor(performanceMonitor: PerformanceMonitorUI) {
        this.performanceMonitor = performanceMonitor
    }

    async getDebugStats(): Promise<DebugStats> {
        const dm = DataManager.getInstance()
        const scene = dm.get<THREE.Scene>(DataKey.MainScene)
        const renderer = dm.get<THREE.WebGLRenderer>(DataKey.Renderer)

        // Scene object counts
        const sceneObjects = scene ? this.countSceneObjects(scene) : { meshes: 0, lights: 0, cameras: 0 }
        const info = renderer?.info

        // TODO: maybe it makes sense to hoist this info somewhere statically accessible... (gotta think it through)
        const perfStats = this.performanceMonitor.getStats() ?? { fps: 0, frameTime: 0, drawCalls: 0, triangles: 0 }

        // Cache stats
        const { PixelDataCache } = await import('../../../scene/game-box/instancing/PixelDataCache')
        const pixelCacheStorage = await PixelDataCache.getInstance().getStorageEstimate()

        // WebGL info
        const gl = renderer?.getContext()
        const memoryInfo = this.getMemoryInfo()
        const storageInfo = await this.getStorageInfo()

        return {
            sceneObjects: {
                total: scene?.children.length ?? 0,
                meshes: sceneObjects.meshes,
                lights: sceneObjects.lights,
                cameras: sceneObjects.cameras,
                textures: info?.memory.textures ?? 0,
                materials: Object.keys(scene?.userData.materials ?? {}).length,
                geometries: info?.memory.geometries ?? 0
            },
            performance: {
                fps: perfStats.fps,
                frameTime: perfStats.frameTime,
                memoryUsed: memoryInfo.usedJSHeapSize,
                memoryTotal: memoryInfo.totalJSHeapSize,
                triangles: info?.render.triangles ?? 0,
                drawCalls: info?.render.calls ?? 0
            },
            cache: {
                imageCount: pixelCacheStorage.count,
                imageCacheSize: Math.round(pixelCacheStorage.estimatedMB * 1024 * 1024),
                gameDataCount: 0,
                gameDataSize: 0,
                quotaUsed: storageInfo.quotaUsed,
                quotaTotal: storageInfo.quotaTotal
            },
            system: {
                userAgent: navigator.userAgent,
                webxrSupported: 'xr' in navigator,
                webglVersion: renderer?.capabilities.isWebGL2 ? 'WebGL 2.0' : 'WebGL 1.0',
                maxTextureSize: renderer?.capabilities.maxTextureSize ?? 0,
                vendor: renderer?.debug.checkShaderErrors
                    ? 'Debug Mode'
                    : (gl?.getParameter(gl.VENDOR) ?? 'Unknown'),
                renderer: gl?.getParameter(gl.RENDERER) ?? 'Unknown'
            }
        }
    }

    // TODO: Scene manager debug wrapper?
    private countSceneObjects(scene: THREE.Scene): { meshes: number; lights: number; cameras: number } {
        let meshes = 0, lights = 0, cameras = 0
        scene.traverse((obj) => {
            if (obj instanceof THREE.Mesh) meshes++
            if (obj instanceof THREE.Light) lights++
            if (obj instanceof THREE.Camera) cameras++
        })
        return { meshes, lights, cameras }
    }

    private getMemoryInfo(): { usedJSHeapSize: number; totalJSHeapSize: number } {
        const perf = window.performance as unknown as {
            memory?: { usedJSHeapSize: number; totalJSHeapSize: number }
        }
        return perf.memory ?? { usedJSHeapSize: 0, totalJSHeapSize: 0 }
    }

    private async getStorageInfo(): Promise<{ quotaUsed: number; quotaTotal: number }> {
        try {
            if ('storage' in navigator && 'estimate' in navigator.storage) {
                const estimate = await navigator.storage.estimate()
                return { quotaUsed: estimate.usage ?? 0, quotaTotal: estimate.quota ?? 0 }
            }
        } catch { /* Storage API not available */ }
        return { quotaUsed: 0, quotaTotal: 0 }
    }
}

/**
 * GameSettingsPanel - Steam-specific settings and configuration
 * 
 * Dedicated panel for Steam-related settings separate from general app settings:
 * - Steam profile management
 * - Game library preferences
 * - Steam API behavior settings
 * - Cache preferences specific to Steam data
 */

import { PauseMenuPanel, type PauseMenuPanelConfig } from '../PauseMenuPanel'
import { renderTemplate } from '../../../utils/TemplateEngine'
import gameSettingsPanelTemplate from '../../../templates/pause-menu/game-settings-panel.html?raw'
