import { EventManager } from '../../core/EventManager'
import { AppEventTypes, type PhaseCompletedEvent, type GameLoadingProgressEvent, type GameLoadingStartedEvent, type GameLoadingPhaseChangedEvent } from '../../types/InteractionEvents'
import { StartupPhase } from '../../utils/StartupEventTracker'
import './StartupProgressUI.css'

/**
 * StartupProgressUI
 *
 * Displays a startup progress bar driven exclusively by AppEventTypes events emitted
 * through the EventManager. It no longer holds a reference to StartupEventTracker and
 * is not directly called by it.
 */
export class StartupProgressUI {
    private container: HTMLDivElement
    private progressBar: HTMLDivElement
    private phaseText: HTMLDivElement
    private detailText: HTMLDivElement
    private isVisible: boolean = true

    // Game loading sub-progress tracking
    private gameLoadingPhase: 'cache' | 'fetch' | 'batch' | null = null
    private gameLoadingProgress: { current: number; total: number } = { current: 0, total: 0 }
    private gameLoadingStartWeight: number = 0

    /**
     * Phase weights determine how much each phase contributes to the 0-100 progress bar.
     * Ordered to match the new 5-phase architecture.
     */
    private readonly phaseWeights = new Map<StartupPhase, number>([
        [StartupPhase.CoreInit,        10],
        [StartupPhase.EngineStart,     15],
        [StartupPhase.WorldBuild,      40],
        [StartupPhase.ControlsReady,    5],
        [StartupPhase.Interactive,     10],
        [StartupPhase.PrewarmEncore,    5],
        [StartupPhase.PostSetupEncore, 15],
    ])

    private currentProgress: number = 0

    constructor() {
        this.container = this.createContainer()
        this.phaseText = this.createPhaseText()
        this.detailText = this.createDetailText()
        this.progressBar = this.createProgressBarWithLayout()

        document.body.appendChild(this.container)

        this.registerEventListeners()
    }

    // -------------------------------------------------------------------------
    // Event-driven wiring
    // -------------------------------------------------------------------------

    private registerEventListeners(): void {
        const eventManager = EventManager.getInstance()

        eventManager.registerEventHandler(AppEventTypes.PhaseStarted, (e: CustomEvent<PhaseCompletedEvent>) => {
            this.onPhaseStarted(e.detail.phase as StartupPhase)
        })

        eventManager.registerEventHandler(AppEventTypes.PhaseCompleted, (e: CustomEvent<PhaseCompletedEvent>) => {
            this.onPhaseCompleted(e.detail.phase as StartupPhase)
        })

        eventManager.registerEventHandler(AppEventTypes.Milestone, (e: CustomEvent) => {
            this.updateMilestone((e.detail as { description: string }).description)
        })

        eventManager.registerEventHandler(AppEventTypes.DetailUpdate, (e: CustomEvent) => {
            this.updateDetail((e.detail as { detail: string }).detail)
        })

        eventManager.registerEventHandler(AppEventTypes.GameLoadingStarted, (e: CustomEvent<GameLoadingStartedEvent>) => {
            this.startGameLoading(e.detail.totalGames, e.detail.phase as StartupPhase)
        })

        eventManager.registerEventHandler(AppEventTypes.GameLoadingPhaseChanged, (e: CustomEvent<GameLoadingPhaseChangedEvent>) => {
            this.gameLoadingPhase = e.detail.loadingPhase
            this.updateDetail(e.detail.detail)
        })

        eventManager.registerEventHandler(AppEventTypes.GameLoadingProgress, (e: CustomEvent<GameLoadingProgressEvent>) => {
            this.updateGameLoadingProgress(e.detail.current, e.detail.total)
        })

        eventManager.registerEventHandler(AppEventTypes.StartupComplete, () => {
            this.complete()
        })
    }

    // -------------------------------------------------------------------------
    // UI update helpers
    // -------------------------------------------------------------------------

    private onPhaseStarted(phase: StartupPhase): void {
        if (!this.isVisible) return

        let cumulativeProgress = 0
        for (const [p, weight] of this.phaseWeights.entries()) {
            if (p === phase) break
            cumulativeProgress += weight
        }

        this.currentProgress = cumulativeProgress
        this.updateProgressBar(this.currentProgress)
        this.phaseText.textContent = this.formatPhaseName(phase)
    }

    private onPhaseCompleted(phase: StartupPhase): void {
        if (!this.isVisible) return

        const weight = this.phaseWeights.get(phase) || 0
        this.currentProgress += weight
        this.updateProgressBar(this.currentProgress)
    }

    private updateMilestone(description: string): void {
        if (!this.isVisible) return
        this.phaseText.textContent = description
        this.hideDetail()
    }

    private updateDetail(detail: string): void {
        if (!this.isVisible) return
        this.detailText.textContent = detail
        this.detailText.style.display = 'block'
    }

    private hideDetail(): void {
        if (!this.isVisible) return
        this.detailText.style.display = 'none'
    }

    private startGameLoading(totalGames: number, phase: StartupPhase = StartupPhase.PostSetupEncore): void {
        if (!this.isVisible) return

        let cumulativeProgress = 0
        for (const [p, weight] of this.phaseWeights.entries()) {
            if (p === phase) break
            cumulativeProgress += weight
        }
        this.gameLoadingStartWeight = cumulativeProgress
        this.gameLoadingProgress = { current: 0, total: totalGames }
    }

    private updateGameLoadingProgress(current: number, total?: number): void {
        if (!this.isVisible) return

        this.gameLoadingProgress.current = current
        if (total !== undefined) {
            this.gameLoadingProgress.total = total
        }

        const phaseWeight = this.phaseWeights.get(StartupPhase.PostSetupEncore) || 15
        const progressRatio = this.gameLoadingProgress.total > 0
            ? this.gameLoadingProgress.current / this.gameLoadingProgress.total
            : 0
        const subProgress = this.gameLoadingStartWeight + (phaseWeight * progressRatio)

        this.updateProgressBar(subProgress)
    }

    private complete(): void {
        if (!this.isVisible) return

        this.updateProgressBar(100)
        this.phaseText.textContent = 'Application loaded'
        this.hideDetail()

        setTimeout(() => {
            this.fadeOut()
        }, 800)
    }

    private updateProgressBar(progress: number): void {
        const clampedProgress = Math.min(100, Math.max(0, progress))
        this.progressBar.style.width = `${clampedProgress}%`
    }

    private formatPhaseName(phase: StartupPhase): string {
        // PascalCase ΓåÆ spaced words
        return phase.replace(/([A-Z])/g, ' $1').trim()
    }

    private fadeOut(): void {
        this.container.style.opacity = '0'
        setTimeout(() => { this.remove() }, 500)
    }

    public remove(): void {
        if (this.container.parentElement) {
            this.container.parentElement.removeChild(this.container)
        }
        this.isVisible = false

        // Signal for Playwright visual tools.
        if (import.meta.env.DEV) {
            (window as any).__playwrightSceneReady = true
        }
    }

    public showError(message: string): void {
        if (!this.isVisible) return
        this.container.classList.add('startup-error')
        this.phaseText.textContent = 'Startup failed'
        this.detailText.textContent = message
        this.detailText.style.display = 'block'
    }

    // -------------------------------------------------------------------------
    // DOM construction
    // -------------------------------------------------------------------------

    private createContainer(): HTMLDivElement {
        const container = document.createElement('div')
        container.id = 'startup-progress-container'
        return container
    }

    private createPhaseText(): HTMLDivElement {
        const text = document.createElement('div')
        text.className = 'startup-phase-text'
        text.textContent = 'Loading...'
        return text
    }

    private createDetailText(): HTMLDivElement {
        const text = document.createElement('div')
        text.className = 'startup-detail-text'
        return text
    }

    private createProgressBarWithLayout(): HTMLDivElement {
        const textColumn = document.createElement('div')
        textColumn.className = 'startup-text-column'
        textColumn.appendChild(this.phaseText)
        textColumn.appendChild(this.detailText)

        const barContainer = document.createElement('div')
        barContainer.className = 'startup-bar-container'

        const bar = document.createElement('div')
        bar.className = 'startup-progress-bar'
        barContainer.appendChild(bar)

        this.container.appendChild(textColumn)
        this.container.appendChild(barContainer)

        return bar
    }
}

/**
 * DOM manipulation and event handling utilities
 */

export class DOMUtils {
    /**
     * Safely get an element by ID with type casting
     */
    static getElementById<T extends HTMLElement = HTMLElement>(id: string): T | null {
        return document.getElementById(id) as T | null
    }

    /**
     * Safely get an input element by ID
     */
    static getInputElement(id: string): HTMLInputElement | null {
        return this.getElementById<HTMLInputElement>(id)
    }

    /**
     * Safely get a button element by ID
     */
    static getButtonElement(id: string): HTMLButtonElement | null {
        return this.getElementById<HTMLButtonElement>(id)
    }

    /**
     * Set element display style
     */
    static setDisplay(element: HTMLElement | null, display: string): void {
        if (element) {
            element.style.display = display
        }
    }

    /**
     * Show element (set display to block)
     */
    static show(element: HTMLElement | null): void {
        this.setDisplay(element, 'block')
    }

    /**
     * Hide element (set display to none)
     */
    static hide(element: HTMLElement | null): void {
        this.setDisplay(element, 'none')
    }

    /**
     * Toggle element visibility
     */
    static toggle(element: HTMLElement | null): boolean {
        if (!element) return false
        
        const isHidden = element.style.display === 'none'
        element.style.display = isHidden ? 'block' : 'none'
        return !isHidden // Returns true if now visible
    }

    /**
     * Set element text content safely
     */
    static setText(element: HTMLElement | null, text: string): void {
        if (element) {
            element.textContent = text
        }
    }

    /**
     * Set element inner HTML safely
     */
    static setHTML(element: HTMLElement | null, html: string): void {
        if (element) {
            element.innerHTML = html
        }
    }

    /**
     * Add event listener with error handling
     */
    static addEventListener<K extends keyof HTMLElementEventMap>(
        element: HTMLElement | null,
        type: K,
        listener: (this: HTMLElement, ev: HTMLElementEventMap[K]) => void,
        options?: boolean | AddEventListenerOptions
    ): void {
        if (element) {
            element.addEventListener(type, listener, options)
        }
    }

    /**
     * Set button disabled state
     */
    static setButtonDisabled(button: HTMLButtonElement | null, disabled: boolean): void {
        if (button) {
            button.disabled = disabled
        }
    }

    /**
     * Set input placeholder text
     */
    static setPlaceholder(input: HTMLInputElement | null, placeholder: string): void {
        if (input) {
            input.placeholder = placeholder
        }
    }

    /**
     * Get input value safely
     */
    static getInputValue(input: HTMLInputElement | null): string {
        return input?.value?.trim() || ''
    }
}

/**
 * Safely get an element by ID (functional approach)
 */
export function getElementByIdSafe<T extends HTMLElement = HTMLElement>(id: string): T | null {
    return document.getElementById(id) as T | null
}

/**
 * Emoji Texture Atlas Generator
 * 
 * Creates a texture atlas from emoji characters for efficient GPU rendering.
 * Emojis are rendered to a canvas and packed into a single texture, with
 * UV coordinates tracked for each emoji.
 */

import * as THREE from 'three'

export interface EmojiAtlasEntry {
    emoji: string
    uvOffset: [number, number]  // UV coordinates in atlas (0-1 range)
    atlasIndex: number           // Index in the atlas for quick lookup
}

export interface EmojiAtlasConfig {
    emojis: string[]
    emojiSize?: number      // Size of each emoji in pixels (default: 128)
    padding?: number        // Padding between emojis (default: 4)
    atlasSize?: number      // Total atlas size (default: 512)
}

export class EmojiTextureAtlas {
    private canvas: HTMLCanvasElement
    private context: CanvasRenderingContext2D
    private texture: THREE.CanvasTexture
    private emojiMap: Map<string, EmojiAtlasEntry>
    private atlasSize: number
    private emojiSize: number
    private padding: number
    private emojisPerRow: number

    constructor(config: EmojiAtlasConfig) {
        const {
            emojis,
            emojiSize = 128,
            padding = 4,
            atlasSize = 512
        } = config

        this.atlasSize = atlasSize
        this.emojiSize = emojiSize
        this.padding = padding
        this.emojisPerRow = Math.floor(atlasSize / (emojiSize + padding))
        this.emojiMap = new Map()

        // Create canvas for rendering
        this.canvas = document.createElement('canvas')
        this.canvas.width = atlasSize
        this.canvas.height = atlasSize

        const ctx = this.canvas.getContext('2d')
        if (!ctx) {
            throw new Error('Failed to get 2D context for emoji atlas')
        }
        this.context = ctx

        // Generate the atlas
        this.generateAtlas(emojis)

        // Create Three.js texture
        this.texture = new THREE.CanvasTexture(this.canvas)
        this.texture.needsUpdate = true
        this.texture.minFilter = THREE.LinearFilter
        this.texture.magFilter = THREE.LinearFilter

        console.debug(`≡ƒÄ¿ Created emoji atlas with ${emojis.length} emojis (${this.emojisPerRow}x${Math.ceil(emojis.length / this.emojisPerRow)})`)
        console.debug(`≡ƒÄ¿ Atlas size: ${atlasSize}x${atlasSize}, Emoji size: ${this.emojiSize}px, Padding: ${this.padding}px`)
    }

    private generateAtlas(emojis: string[]): void {
        // Clear canvas with transparent background
        this.context.clearRect(0, 0, this.atlasSize, this.atlasSize)

        // Set up text rendering
        this.context.font = `${this.emojiSize * 0.8}px Arial`
        this.context.textAlign = 'center'
        this.context.textBaseline = 'middle'

        // Render each emoji
        emojis.forEach((emoji, index) => {
            const row = Math.floor(index / this.emojisPerRow)
            const col = index % this.emojisPerRow

            const x = col * (this.emojiSize + this.padding) + this.emojiSize / 2
            const y = row * (this.emojiSize + this.padding) + this.emojiSize / 2

            // Render emoji
            this.context.fillText(emoji, x, y)

            // Calculate UV coordinates (normalized 0-1)
            const uvX = col / this.emojisPerRow
            const uvY = row / Math.ceil(emojis.length / this.emojisPerRow)

            // Store entry
            this.emojiMap.set(emoji, {
                emoji,
                uvOffset: [uvX, uvY],
                atlasIndex: index
            })
        })
    }

    public getTexture(): THREE.CanvasTexture {
        return this.texture
    }

    public getEmojiEntry(emoji: string): EmojiAtlasEntry | undefined {
        return this.emojiMap.get(emoji)
    }

    public getEmojiUVOffset(emoji: string): [number, number] | undefined {
        return this.emojiMap.get(emoji)?.uvOffset
    }

    public hasEmoji(emoji: string): boolean {
        return this.emojiMap.has(emoji)
    }

    public getAtlasInfo() {
        const totalRows = Math.ceil(this.emojiMap.size / this.emojisPerRow)
        return {
            atlasSize: this.atlasSize,
            emojiSize: this.emojiSize,
            emojisPerRow: this.emojisPerRow,
            totalEmojis: this.emojiMap.size,
            uvScale: 1 / this.emojisPerRow, // UV scale per emoji (X axis)
            uvScaleY: 1 / totalRows          // UV scale per emoji (Y axis)
        }
    }

    public dispose(): void {
        this.texture.dispose()
        this.emojiMap.clear()
    }
}

