/**
 * FrameBudgetScheduler - Frame-budget-aware task scheduler
 * 
 * Defers non-critical work (like texture array copies) to frames where we have
 * headroom, preventing frame drops during heavy operations.
 * 
 * Key features:
 * - Ultra-lightweight frame time tracking (O(1) rolling average)
 * - Budget-aware task scheduling
 * - Time-based anti-starvation (no frame counting overhead)
 * - Self-tuning based on target FPS
 * 
 * Usage:
 *   scheduler.schedule(() => arrayData.set(pixels, offset), { estimatedMs: 0.5 })
 */

import { Logger } from './Logger'

export interface TaskOptions {
    /** Estimated execution time in ms (helps budget planning) */
    estimatedMs?: number
    /** Task priority - higher priority tasks execute first */
    priority?: 'low' | 'normal' | 'high'
    /**
     * Maximum time to defer before forcing execution (default: ~400ms).
     * Set to 0 to never force (task runs only when budget allows).
     * Use 0 for cosmetic updates (texture upserts, material upgrades) where
     * skipping beats hitching.
     */
    maxDeferMs?: number
}

interface QueuedTask {
    fn: () => void
    estimatedMs: number
    priority: number  // 0=low, 1=normal, 2=high
    maxDeferMs: number
    queuedAt: number
}

export interface SchedulerStats {
    currentFps: number
    targetFps: number
    rollingAvgFrameTime: number
    pendingTasks: number
    tasksExecutedLastFrame: number
    totalTasksDeferred: number
    totalTasksForced: number
    budgetThreshold: number
}

export interface FrameBudgetSchedulerConfig {
    /** Target frames per second (default: 60) */
    targetFps?: number
    /** Fraction of remaining frame budget to use (default: 0.8) */
    budgetThreshold?: number
    /** Maximum tasks to process per frame (default: 1) */
    maxTasksPerFrame?: number
    /** Default max defer time in ms (default: 400). 0 = never force. */
    defaultMaxDeferMs?: number
    /** Number of frames to track for rolling average (default: 60) */
    ringBufferSize?: number
    /**
     * After a heavy frame (one that exceeded the frame time budget),
     * skip this many frames before processing tasks again. Provides breathing
     * room so the renderer can catch up. Default: 2.
     * Note: force-executed tasks (anti-starvation) do NOT trigger cooldown on their own.
     */
    heavyFrameCooldownFrames?: number
    /**
     * If a frame gap exceeds this many ms, treat it as a deliberate pause
     * (tab hidden, rAF suspended) rather than genuine overload.
     * Pending task timestamps are shifted forward so they don't appear overdue.
     * Default: 500ms.
     */
    pauseGapThresholdMs?: number
}

const PRIORITY_MAP = { low: 0, normal: 1, high: 2 } as const

export class FrameBudgetScheduler {
    private static instance: FrameBudgetScheduler | null = null
    // Use createLogFunctions consistently. Tests should mock `createLogFunctions`
    // instead of the removed `withContext` helper.
    public static logger = Logger.createLogFunctions(FrameBudgetScheduler.name)

    // Configuration
    private targetFps: number
    private targetFrameTime: number
    private budgetThreshold: number
    private maxTasksPerFrame: number
    private defaultMaxDeferMs: number

    // Frame time tracking (ultra-lightweight)
    private frameTimeRing: Float32Array
    private ringIndex = 0
    private rollingSum = 0
    private frameCount = 0  // Track how many samples we have (for startup)
    private lastFrameTime = 0
    private frameStartTime = 0

    // Task queue
    private pendingTasks: QueuedTask[] = []
    private needsSort = false  // Only sort when we add different priorities

    // Stats
    private tasksExecutedLastFrame = 0
    private totalTasksDeferred = 0
    private totalTasksForced = 0

    // Pause/resume detection
    private readonly pauseGapThresholdMs: number

    // Cooldown state: skip N frames after a heavy (over-budget) frame
    private heavyFrameCooldownFrames: number
    private cooldownFramesRemaining = 0

    private constructor(config: FrameBudgetSchedulerConfig = {}) {
        this.targetFps = config.targetFps ?? 60
        this.targetFrameTime = 1000 / this.targetFps
        this.budgetThreshold = config.budgetThreshold ?? 0.8
        this.maxTasksPerFrame = config.maxTasksPerFrame ?? 1  // take longer, ride smoother
        this.defaultMaxDeferMs = config.defaultMaxDeferMs ?? 400
        this.heavyFrameCooldownFrames = config.heavyFrameCooldownFrames ?? 120
        this.pauseGapThresholdMs = config.pauseGapThresholdMs ?? 500

        const ringSize = config.ringBufferSize ?? 60
        this.frameTimeRing = new Float32Array(ringSize)

        FrameBudgetScheduler.logger.lifecycle(`Initialized: target ${this.targetFps}fps, budget threshold ${this.budgetThreshold * 100}%`)
    }

    public static getInstance(config?: FrameBudgetSchedulerConfig): FrameBudgetScheduler {
        if (!FrameBudgetScheduler.instance) {
            FrameBudgetScheduler.instance = new FrameBudgetScheduler(config)
        }
        return FrameBudgetScheduler.instance
    }

    /**
     * Call at the START of each frame (before rendering)
     * This updates frame time tracking and processes pending tasks
     */
    public onFrameStart(now: number): void {
        // Calculate delta from last frame
        if (this.lastFrameTime > 0) {
            const delta = now - this.lastFrameTime
            this.updateFrameTime(delta)

            // If the gap looks like a deliberate rAF pause (tab hidden, window minimized),
            // shift all pending task timestamps forward by the gap so they don't appear
            // overdue when the app resumes. This prevents a burst of forced executions
            // on re-focus that would all fire as if they'd been "waiting" for the full
            // hidden duration.
            if (delta > this.pauseGapThresholdMs && this.pendingTasks.length > 0) {
                for (const task of this.pendingTasks) {
                    task.queuedAt += delta
                }
            }
        }

        this.lastFrameTime = now
        this.frameStartTime = now
        this.tasksExecutedLastFrame = 0

        // Respect cooldown ΓÇö let the renderer breathe after a heavy frame
        if (this.cooldownFramesRemaining > 0) {
            this.cooldownFramesRemaining--
            return
        }

        // Process pending tasks at frame start (when we have full budget)
        this.processPendingTasks(now)
    }

    /**
     * Optional: call at the END of each frame to process more tasks if budget remains
     */
    public onFrameEnd(): void {
        // Could process more tasks here if we have leftover budget
        // For now, we only process at frame start for simplicity
    }

    private updateFrameTime(delta: number): void {
        // Subtract old value from sum, add new value
        this.rollingSum -= this.frameTimeRing[this.ringIndex]
        this.rollingSum += delta
        this.frameTimeRing[this.ringIndex] = delta

        // Advance ring index
        this.ringIndex = (this.ringIndex + 1) % this.frameTimeRing.length

        // Track sample count for accurate average during startup
        if (this.frameCount < this.frameTimeRing.length) {
            this.frameCount++
        }
    }

    public getRollingAvgFrameTime(): number {
        if (this.frameCount === 0) return this.targetFrameTime
        return this.rollingSum / this.frameCount
    }

    public getCurrentFps(): number {
        const avgFrameTime = this.getRollingAvgFrameTime()
        return avgFrameTime > 0 ? 1000 / avgFrameTime : this.targetFps
    }

    public hasBudget(estimatedMs: number = 1): boolean {
        const elapsed = performance.now() - this.frameStartTime
        const remaining = this.targetFrameTime - elapsed
        const usableBudget = remaining * this.budgetThreshold

        return usableBudget >= estimatedMs
    }

    public getRemainingBudget(): number {
        const elapsed = performance.now() - this.frameStartTime
        return Math.max(0, (this.targetFrameTime - elapsed) * this.budgetThreshold)
    }

    public schedule(task: () => void, options: TaskOptions = {}): void {
        const priority = PRIORITY_MAP[options.priority ?? 'normal']

        const queuedTask: QueuedTask = {
            fn: task,
            estimatedMs: options.estimatedMs ?? 1,
            priority,
            maxDeferMs: options.maxDeferMs ?? this.defaultMaxDeferMs,
            queuedAt: performance.now()
        }

        this.pendingTasks.push(queuedTask)

        // Mark that we need to sort if this isn't normal priority
        if (priority !== 1) {
            this.needsSort = true
        }

        this.totalTasksDeferred++
    }

    public scheduleAsync<T>(task: () => T, options: TaskOptions = {}): Promise<T> {
        return new Promise((resolve, reject) => {
            this.schedule(() => {
                try {
                    resolve(task())
                } catch (e) {
                    reject(e)
                }
            }, options)
        })
    }

    private processPendingTasks(now: number): void {
        if (this.pendingTasks.length === 0) return

        // Sort by priority if needed (descending - high priority first)
        if (this.needsSort) {
            this.pendingTasks.sort((a, b) => b.priority - a.priority)
            this.needsSort = false
        }

        let tasksExecuted = 0
        let budgetExceeded = false

        while (this.pendingTasks.length > 0 && tasksExecuted < this.maxTasksPerFrame) {
            const task = this.pendingTasks[0]

            // maxDeferMs === 0 means "never force ΓÇö cosmetic update, skip if busy"
            if (task.maxDeferMs === 0) {
                if (!this.hasBudget(task.estimatedMs)) {
                    budgetExceeded = true
                    break
                }
            } else {
                // Anti-starvation: force if task has been waiting too long.
                // Note: pause-resume gaps are already compensated in onFrameStart by
                // advancing queuedAt, so this check reflects genuine scheduler delay.
                const waitTime = now - task.queuedAt
                const forceExecution = waitTime > task.maxDeferMs

                if (forceExecution) {
                    FrameBudgetScheduler.logger.warn(`Task forced after ${waitTime.toFixed(0)}ms wait (limit: ${task.maxDeferMs}ms) - system may be overloaded`)
                    this.totalTasksForced++
                } else if (!this.hasBudget(task.estimatedMs)) {
                    budgetExceeded = true
                    break
                }
            }

            // Execute task
            this.pendingTasks.shift()
            try {
                task.fn()
            } catch (e) {
                FrameBudgetScheduler.logger.error('Task execution failed:', e)
            }
            tasksExecuted++
        }

        this.tasksExecutedLastFrame = tasksExecuted

        // Impose cooldown when the frame genuinely ran out of budget ΓÇö that's the
        // signal that the system is under load and needs breathing room.
        // Forced executions (anti-starvation) are already a late response to starvation
        // and don't warrant adding more delay on top.
        if (budgetExceeded && this.heavyFrameCooldownFrames > 0) {
            this.cooldownFramesRemaining = this.heavyFrameCooldownFrames
        }
    }

    public tryExecuteOrSchedule(task: () => void, options: TaskOptions = {}): boolean {
        if (this.hasBudget(options.estimatedMs ?? 1)) {
            task()
            return true
        }
        this.schedule(task, options)
        return false
    }

    public getStats(): SchedulerStats {
        return {
            currentFps: this.getCurrentFps(),
            targetFps: this.targetFps,
            rollingAvgFrameTime: this.getRollingAvgFrameTime(),
            pendingTasks: this.pendingTasks.length,
            tasksExecutedLastFrame: this.tasksExecutedLastFrame,
            totalTasksDeferred: this.totalTasksDeferred,
            totalTasksForced: this.totalTasksForced,
            budgetThreshold: this.budgetThreshold
        }
    }

    public setTargetFps(fps: number): void {
        this.targetFps = fps
        this.targetFrameTime = 1000 / fps
        FrameBudgetScheduler.logger.lifecycle(`Target FPS changed to ${fps}`)
    }

    public setBudgetThreshold(threshold: number): void {
        this.budgetThreshold = Math.max(0.1, Math.min(1.0, threshold))
        FrameBudgetScheduler.logger.lifecycle(`Budget threshold changed to ${(this.budgetThreshold * 100).toFixed(0)}%`)
    }

    public setMaxTasksPerFrame(max: number): void {
        this.maxTasksPerFrame = Math.max(1, Math.min(20, max))
        FrameBudgetScheduler.logger.lifecycle(`Max tasks per frame changed to ${this.maxTasksPerFrame}`)
    }

    public clearPendingTasks(): void {
        const count = this.pendingTasks.length
        this.pendingTasks = []
        if (count > 0) {
            FrameBudgetScheduler.logger.warn(`Cleared ${count} pending tasks`)
        }
    }

    public diagnose(): void {
        const stats = this.getStats()
        console.group('≡ƒôè FrameBudgetScheduler Stats')
        console.log(`FPS: ${stats.currentFps.toFixed(1)} / ${stats.targetFps} target`)
        console.log(`Avg frame time: ${stats.rollingAvgFrameTime.toFixed(2)}ms`)
        console.log(`Budget threshold: ${(stats.budgetThreshold * 100).toFixed(0)}%`)
        console.log(`Remaining budget: ${this.getRemainingBudget().toFixed(2)}ms`)
        console.log(`Pending tasks: ${stats.pendingTasks}`)
        console.log(`Tasks last frame: ${stats.tasksExecutedLastFrame}`)
        console.log(`Total deferred: ${stats.totalTasksDeferred}`)
        console.log(`Total forced: ${stats.totalTasksForced}`)
        console.groupEnd()
    }

    public resetStats(): void {
        this.totalTasksDeferred = 0
        this.totalTasksForced = 0
        this.tasksExecutedLastFrame = 0
    }

    public dispose(): void {
        this.clearPendingTasks()
        FrameBudgetScheduler.instance = null
        FrameBudgetScheduler.logger.lifecycle('Disposed')
    }
}

/**
 * Structured logger with configurable log levels
 * 
 * Features:
 * - Per-context log levels (set DEBUG for specific classes only)
 * - Log categories: lifecycle (startup flow) vs runtime (frame updates, LOD changes)
 * - Global and per-context level configuration
 * 
 * Usage:
 *   const { info, debug } = Logger.createLogFunctions('MyClass')
 *   info('Starting up')           // Always shown at INFO level
 *   log.lifecycle('Init phase 1')     // Startup/teardown flow (DEBUG by default)
 *   log.runtime('LOD changed')        // Frame-by-frame events (suppressed by default)
 * 
 * Configuration:
 *   Logger.setContextLevel('LodDistanceManager', LogLevel.WARN)  // Quiet specific class
 *   Logger.setRuntimeLogging(true)                                // Enable runtime logs
 */

export enum LogLevel {
  ERROR = 0,
  WARN = 1,
  INFO = 2,
  DEBUG = 3,
  TRACE = 4  // For very verbose output
}

/** Log categories for filtering */
export enum LogCategory {
  /** Normal log messages */
  GENERAL = 'general',
  /** Startup, initialization, teardown flow */
  LIFECYCLE = 'lifecycle',
  /** Per-frame, high-frequency runtime events */
  RUNTIME = 'runtime'
}

export class Logger {
  private static instance: Logger
  private globalLevel: LogLevel = LogLevel.INFO
  private context: string = ''

  // Per-context level overrides (classes must opt-in to DEBUG)
  private static contextLevels: Map<string, LogLevel> = new Map()

  // Category toggles (runtime is off by default to reduce noise)
  private static categoryEnabled: Map<LogCategory, boolean> = new Map([
    [LogCategory.GENERAL, true],
    [LogCategory.LIFECYCLE, true],
    [LogCategory.RUNTIME, false]  // Off by default - too noisy
  ])

  private constructor() {
    // Global default is INFO - classes must opt-in for DEBUG via setContextLevel
    // Can be overridden via URL param for full debugging
    if (typeof window !== 'undefined' && window.location?.search?.includes('debug=true')) {
      this.globalLevel = LogLevel.DEBUG
    } else if (typeof globalThis !== 'undefined' && (globalThis as { vi?: unknown }).vi) {
      this.globalLevel = LogLevel.WARN // Only warnings and errors during tests
    } else {
      this.globalLevel = LogLevel.INFO // Default to INFO - opt-in for DEBUG
    }
  }

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger()
      Logger.initializeDefaultContextLevels()
    }
    return Logger.instance
  }

  /**
   * Initialize default context log levels
   * Classes with noisy output are set to INFO by default to reduce console spam
   */
  private static initializeDefaultContextLevels(): void {
    // Classes that produce a lot of noise which is only helpful when actively debugging them
    Logger.setContextLevel('GpuGameBoxRenderer', LogLevel.INFO)
    Logger.setContextLevel('SteamApiClient', LogLevel.INFO)
    Logger.setContextLevel('BatchAppDetailsClient', LogLevel.INFO)
    Logger.setContextLevel('GameArtworkInspector', LogLevel.INFO)
  }

  /**
   * Set log level for a specific context (class name)
   * Useful for silencing noisy classes or enabling debug for specific ones
   */
  static setContextLevel(context: string, level: LogLevel): void {
    Logger.contextLevels.set(context, level)
  }

  /**
   * Clear context-specific level override
   */
  static clearContextLevel(context: string): void {
    Logger.contextLevels.delete(context)
  }

  /**
   * Get all context-specific level overrides (for debugging)
   */
  static getContextLevels(): Map<string, LogLevel> {
    return new Map(Logger.contextLevels)
  }

  /**
   * Clear all context-specific level overrides
   */
  static clearAllContextLevels(): void {
    Logger.contextLevels.clear()
  }

  /**
   * Reset Logger to default state (for testing)
   * Clears all context levels and resets categories to defaults
   */
  static reset(): void {
    Logger.contextLevels.clear()
    Logger.categoryEnabled.set(LogCategory.GENERAL, true)
    Logger.categoryEnabled.set(LogCategory.LIFECYCLE, true)
    Logger.categoryEnabled.set(LogCategory.RUNTIME, false)
    // Reset global level to INFO
    if (Logger.instance) {
      Logger.instance.globalLevel = LogLevel.INFO
    }
  }

  getLevel(): LogLevel {
    return this.globalLevel
  }

  static setCategoryEnabled(category: LogCategory, enabled: boolean): void {
    Logger.categoryEnabled.set(category, enabled)
  }

  static isCategoryEnabled(category: LogCategory): boolean {
    return Logger.categoryEnabled.get(category) ?? true
  }

  static setRuntimeLogging(enabled: boolean): void {
    Logger.setCategoryEnabled(LogCategory.RUNTIME, enabled)
  }

  /**
   * Set the global log level (applies to contexts without overrides)
   */
  setLevel(level: LogLevel): void {
    this.globalLevel = level
  }

  /**
   * Get effective log level for this context
   */
  private getEffectiveLevel(): LogLevel {
    if (this.context && Logger.contextLevels.has(this.context)) {
      return Logger.contextLevels.get(this.context)!
    }
    return this.globalLevel
  }

  private formatMessage(level: string, message: string): string {
    const timestamp = new Date().toISOString().slice(11, 23) // HH:mm:ss.sss
    const prefix = this.context ? `[${this.context}]` : ''
    return `${timestamp} ${level} ${prefix} ${message}`
  }

  private shouldLog(level: LogLevel, category: LogCategory = LogCategory.GENERAL): boolean {
    // Check category first
    if (!Logger.categoryEnabled.get(category)) {
      return false
    }
    // Then check level
    return level <= this.getEffectiveLevel()
  }

  error(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.ERROR)) {
      console.error(this.formatMessage('ERROR', message), ...args)
    }
  }

  warn(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.WARN)) {
      console.warn(this.formatMessage('WARN', message), ...args)
    }
  }

  info(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.INFO)) {
      console.log(this.formatMessage('INFO', message), ...args)
    }
  }

  debug(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.DEBUG)) {
      console.debug(this.formatMessage('DEBUG', message), ...args)
    }
  }

  /**
   * Lifecycle logs - startup, initialization, teardown flow
   * Shown by default, but can be disabled
   */
  lifecycle(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.DEBUG, LogCategory.LIFECYCLE)) {
      console.debug(this.formatMessage('LIFE', message), ...args)
    }
  }

  /**
   * Runtime logs - per-frame events, LOD changes, high-frequency updates
   * Disabled by default to reduce noise. Enable with Logger.setRuntimeLogging(true)
   */
  runtime(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.DEBUG, LogCategory.RUNTIME)) {
      console.debug(this.formatMessage('RT', message), ...args)
    }
  }

  /**
   * Trace logs - very verbose, for deep debugging
   */
  trace(message: string, ...args: unknown[]): void {
    if (this.shouldLog(LogLevel.TRACE)) {
      console.debug(this.formatMessage('TRACE', message), ...args)
    }
  }

  /**
   * Create bound log functions that show the CALLER's file location in browser console.
   * 
  * When you use Logger.createLogFunctions(), the returned functions are bound so the browser
  * console shows the class/caller file instead of Logger.ts. This gives more useful
  * stack attribution and makes debugging easier in dev tools.
   * 
   * Usage:
   *   const { info, debug, warn, error } = Logger.createLogFunctions('InstancedShelfRenderer')
   *   info('Initialized')  // Console shows InstancedShelfRenderer.ts, not Logger.ts
   * 
   * Note: Level filtering is evaluated at call time, so setContextLevel still works.
   */
  /**
   * Optimized timestamp formatter - reuses Date object and uses performance.now() for sub-second precision
   * Avoids repeated Date() constructor calls which are expensive
   */
  private static formatTimestamp(): string {
    const now = new Date()
    const h = now.getHours().toString().padStart(2, '0')
    const m = now.getMinutes().toString().padStart(2, '0')
    const s = now.getSeconds().toString().padStart(2, '0')
    const ms = now.getMilliseconds().toString().padStart(3, '0')
    return `${h}:${m}:${s}.${ms}`
  }

  static createLogFunctions(context: string): {
    error: (...args: unknown[]) => void
    warn: (...args: unknown[]) => void
    info: (...args: unknown[]) => void
    debug: (...args: unknown[]) => void
    lifecycle: (...args: unknown[]) => void
    runtime: (...args: unknown[]) => void
    trace: (...args: unknown[]) => void
  } {
    const instance = Logger.getInstance()
    const formatPrefix = () => `${Logger.formatTimestamp()} [${context}]`

    const getEffectiveLevel = (): LogLevel => {
      if (Logger.contextLevels.has(context)) {
        return Logger.contextLevels.get(context)!
      }
      return instance.globalLevel
    }

    const shouldLog = (level: LogLevel, category: LogCategory = LogCategory.GENERAL): boolean => {
      if (!Logger.categoryEnabled.get(category)) {
        return false
      }
      return level <= getEffectiveLevel()
    }

    // Return wrapper functions that preserve call stack by using console.X.bind()
    // The key is to avoid arrow functions - use function expressions that delegate immediately
    return {
      error: function(...args: unknown[]) {
        shouldLog(LogLevel.ERROR) && console.error(formatPrefix(), 'ERROR', ...args)
      },
      warn: function(...args: unknown[]) {
        shouldLog(LogLevel.WARN) && console.warn(formatPrefix(), 'WARN', ...args)
      },
      info: function(...args: unknown[]) {
        shouldLog(LogLevel.INFO) && console.log(formatPrefix(), 'INFO', ...args)
      },
      debug: function(...args: unknown[]) {
        shouldLog(LogLevel.DEBUG) && console.debug(formatPrefix(), 'DEBUG', ...args)
      },
      lifecycle: function(...args: unknown[]) {
        shouldLog(LogLevel.DEBUG, LogCategory.LIFECYCLE) && console.debug(formatPrefix(), 'LIFE', ...args)
      },
      runtime: function(...args: unknown[]) {
        shouldLog(LogLevel.DEBUG, LogCategory.RUNTIME) && console.debug(formatPrefix(), 'RT', ...args)
      },
      trace: function(...args: unknown[]) {
        shouldLog(LogLevel.TRACE) && console.debug(formatPrefix(), 'TRACE', ...args)
      }
    }
  }
}

// Export a default instance for convenience
export const logger = Logger.getInstance()

/**
 * Console helper functions for per-class log level control
 * Usage from browser console:
 *   setLogLevel('HighTextureCache', 'WARN')  // Quiet specific class
 *   setLogLevel('LodArtworkOrchestrator', 'DEBUG')  // Enable debug for specific class
 *   resetLogLevel('HighTextureCache')  // Reset to global level
 *   listLogLevels()  // Show all context-specific overrides
 *   setGlobalLogLevel('INFO')  // Set default level for all
 *   enableRuntimeLogs()  // Enable high-frequency logs
 *   disableRuntimeLogs()  // Disable high-frequency logs
 */
function setLogLevel(context: string, level: keyof typeof LogLevel): void {
  Logger.setContextLevel(context, LogLevel[level])
  console.log(`≡ƒô¥ Log level for "${context}" set to ${level}`)
}

function resetLogLevel(context: string): void {
  Logger.clearContextLevel(context)
  console.log(`≡ƒô¥ Log level for "${context}" reset to global`)
}

function listLogLevels(): void {
  const levels = Logger.getContextLevels()
  if (levels.size === 0) {
    console.log('≡ƒô¥ No context-specific log levels set')
    return
  }
  console.log('≡ƒô¥ Context-specific log levels:')
  for (const [context, level] of levels) {
    const levelName = Object.entries(LogLevel).find(([, v]) => v === level)?.[0] ?? 'UNKNOWN'
    console.log(`   ${context}: ${levelName}`)
  }
}

function setGlobalLogLevel(level: keyof typeof LogLevel): void {
  Logger.getInstance().setLevel(LogLevel[level])
  console.log(`≡ƒô¥ Global log level set to ${level}`)
}

function enableRuntimeLogs(): void {
  Logger.setRuntimeLogging(true)
  console.log('≡ƒô¥ Runtime logs enabled (high-frequency events)')
}

function disableRuntimeLogs(): void {
  Logger.setRuntimeLogging(false)
  console.log('≡ƒô¥ Runtime logs disabled')
}

// Expose Logger and helpers globally for console configuration
if (typeof window !== 'undefined') {
  (window as unknown as { Logger: typeof Logger }).Logger = Logger
  ;(window as unknown as { LogLevel: typeof LogLevel }).LogLevel = LogLevel
  ;(window as unknown as { LogCategory: typeof LogCategory }).LogCategory = LogCategory

  // Expose helper functions
  ;(window as unknown as { setLogLevel: typeof setLogLevel }).setLogLevel = setLogLevel
  ;(window as unknown as { resetLogLevel: typeof resetLogLevel }).resetLogLevel = resetLogLevel
  ;(window as unknown as { listLogLevels: typeof listLogLevels }).listLogLevels = listLogLevels
  ;(window as unknown as { setGlobalLogLevel: typeof setGlobalLogLevel }).setGlobalLogLevel = setGlobalLogLevel
  ;(window as unknown as { enableRuntimeLogs: typeof enableRuntimeLogs }).enableRuntimeLogs = enableRuntimeLogs
  ;(window as unknown as { disableRuntimeLogs: typeof disableRuntimeLogs }).disableRuntimeLogs = disableRuntimeLogs
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { ManagedWorker, type WorkerMessage } from './ManagedWorker'

// Fake Worker that wires itself up so tests can trigger responses/crashes
class FakeWorker implements EventTarget {
    onmessage: ((e: MessageEvent) => void) | null = null
    onerror: ((e: ErrorEvent) => void) | null = null
    onmessageerror: null = null
    postMessage = vi.fn()
    terminate = vi.fn()
    addEventListener = vi.fn()
    removeEventListener = vi.fn()
    dispatchEvent = vi.fn(() => true)

    respond(data: object) { this.onmessage?.({ data } as MessageEvent) }
    crash(errorDetail?: Error) {
        this.onerror?.({ message: undefined, error: errorDetail ?? new Error('crash') } as ErrorEvent)
    }
}

interface TestIn extends WorkerMessage { type: 'PING' }
interface TestOut extends WorkerMessage { type: 'PONG'; value: number }

let fakeWorker: FakeWorker

class TestManagedWorker extends ManagedWorker<TestIn, TestOut> {
    public receivedMessages: TestOut[] = []

    constructor() {
        // Pass the fake worker instance through a factory that returns it
        super(() => fakeWorker as unknown as Worker, 'TestWorker')
    }

    protected override handleMessage(data: TestOut): void {
        this.receivedMessages.push(data)
    }

    public ping(messageId: string): Promise<TestOut> {
        return this.send<TestOut>({ type: 'PING', messageId })
    }
}

describe('ManagedWorker', () => {
    beforeEach(() => { fakeWorker = new FakeWorker() })

    it('sends a message to the worker', () => {
        const w = new TestManagedWorker()
        w.ping('id-1')
        expect(fakeWorker.postMessage).toHaveBeenCalledWith({ type: 'PING', messageId: 'id-1' })
    })

    it('resolves promise when worker responds with matching messageId', async () => {
        const w = new TestManagedWorker()
        const p = w.ping('id-2')
        fakeWorker.respond({ type: 'PONG', messageId: 'id-2', value: 42 })
        expect((await p).value).toBe(42)
    })

    it('rejects all pending promises on worker crash', async () => {
        const w = new TestManagedWorker()
        const p = w.ping('id-3')
        fakeWorker.crash(new Error('boom'))
        await expect(p).rejects.toThrow('boom')
    })

    it('crash rejection includes the worker name', async () => {
        const w = new TestManagedWorker()
        const p = w.ping('id-4')
        fakeWorker.crash(new Error('internal'))
        await expect(p).rejects.toThrow('TestWorker')
    })

    it('calls handleMessage for every received response', async () => {
        const w = new TestManagedWorker()
        const p = w.ping('id-5')
        fakeWorker.respond({ type: 'PONG', messageId: 'id-5', value: 1 })
        await p
        expect(w.receivedMessages).toHaveLength(1)
    })

    it('terminates the worker and rejects pending on dispose', async () => {
        const w = new TestManagedWorker()
        const p = w.ping('id-6')
        w.dispose()
        await expect(p).rejects.toThrow('disposed')
        expect(fakeWorker.terminate).toHaveBeenCalled()
        expect(w.pendingCount).toBe(0)
    })

    it('rejects immediately when already disposed', async () => {
        const w = new TestManagedWorker()
        w.dispose()
        await expect(w.ping('id-7')).rejects.toThrow('disposed')
    })
})

/**
 * ManagedWorker<TIn, TOut>
 *
 * Base class for Web Worker manager objects.
 *
 * Owns the Worker lifecycle, pending-message map, and error handling so
 * individual manager classes don't each re-implement the same boilerplate.
 *
 * TIn:  union of message types sent TO the worker (must have messageId: string)
 * TOut: union of message types received FROM the worker (must have messageId: string)
 *
 * Subclass responsibilities:
 *   - Call super(workerFactory, workerName) in constructor
 *   - Optionally override protected handleMessage(data: TOut): void
 *   - Optionally override protected onWorkerCrash(err: Error): void
 *   - Call this.send<TResponse>(message) to send and await a response
 */

import { Logger } from './Logger'

export interface WorkerMessage {
    messageId: string
}

type PendingEntry<TOut> = {
    resolve: (data: TOut) => void
    reject: (err: Error) => void
}

/** Accept either a Vite "?worker" constructable or a plain factory function (useful in tests). */
type WorkerFactory = (() => Worker) | (new () => Worker)


/** Extract meaningful message from a browser ErrorEvent (runtime crashes set message=undefined). */
function extractWorkerError(e: ErrorEvent): string {
    if (e.error instanceof Error) return e.error.message || e.error.toString()
    if (e.message) return e.message
    if (e.filename) return `Worker error in ${e.filename}:${e.lineno}`
    return 'Unknown worker error (likely a runtime crash inside the worker)'
}

export abstract class ManagedWorker<TIn extends WorkerMessage, TOut extends WorkerMessage> {
    private readonly worker: Worker
    private readonly name: string
    private readonly pending = new Map<string, PendingEntry<TOut>>()
    private disposed = false
    private msgCounter = 0

    constructor(workerFactory: WorkerFactory, workerName: string) {
        this.name = workerName

        // Support both constructable (Vite ?worker imports) and plain factory functions (tests)
        let worker: Worker
        try {
            worker = new (workerFactory as new () => Worker)()
        } catch {
            worker = (workerFactory as () => Worker)()
        }
        this.worker = worker

        this.worker.onmessage = (e: MessageEvent<TOut>) => {
            this.dispatchMessage(e.data)
        }

        const logger = Logger.createLogFunctions(workerName)
        this.worker.onerror = (e: ErrorEvent) => {
            const msg = extractWorkerError(e)
            logger.error(`Worker crashed: ${msg}`, { filename: e.filename, error: e.error })
            const err = new Error(`${workerName} crashed: ${msg}`)
            for (const [, entry] of this.pending) entry.reject(err)
            this.pending.clear()
            this.onWorkerCrash(err)
        }
    }

    /** Generate a unique message ID. */
    protected nextId(): string {
        return `${this.name}_${Date.now()}_${this.msgCounter++}`
    }

    /**
     * Send a message to the worker and await the response with matching messageId.
     * Caller must set message.messageId (use this.nextId()).
     */
    protected send<TResponse extends TOut>(message: TIn): Promise<TResponse> {
        if (this.disposed) {
            return Promise.reject(new Error(`${this.name}: already disposed`))
        }
        return new Promise<TResponse>((resolve, reject) => {
            this.pending.set(message.messageId, {
                resolve: (data) => resolve(data as TResponse),
                reject,
            })
            this.worker.postMessage(message)
        })
    }

    /** Post fire-and-forget (no response expected). */
    protected post(message: TIn): void {
        if (!this.disposed) this.worker.postMessage(message)
    }

    private dispatchMessage(data: TOut): void {
        const entry = this.pending.get(data.messageId)
        if (entry) {
            this.pending.delete(data.messageId)
            entry.resolve(data)
        }
        this.handleMessage(data)
    }

    /** Called for every inbound message. Override to observe or handle push-style messages. */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected handleMessage(_data: TOut): void { /* no-op */ }

    /** Called after all pending promises are rejected on a worker crash. Override for cleanup. */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    protected onWorkerCrash(_err: Error): void { /* no-op */ }

    public dispose(): void {
        if (this.disposed) return
        this.disposed = true
        const err = new Error(`${this.name}: disposed`)
        for (const [, entry] of this.pending) entry.reject(err)
        this.pending.clear()
        this.worker.terminate()
    }

    public get isDisposed(): boolean { return this.disposed }
    public get pendingCount(): number { return this.pending.size }
}

/**
 * Material Utilities - PBR Material Creation and Management
 * 
 * Provides standardized PBR materials for the Blockbuster environment
 * Upgrade from MeshPhongMaterial to MeshStandardMaterial for better visuals
 */

import * as THREE from 'three'
import { BlockbusterColors } from './Colors'

export interface PBRMaterialOptions {
    color?: number | THREE.Color
    roughness?: number
    metalness?: number
    emissive?: number | THREE.Color
    emissiveIntensity?: number
}

export class MaterialUtils {
    /**
     * Create a standard PBR material with Blockbuster-appropriate settings
     */
    static createPBRMaterial(options: PBRMaterialOptions = {}): THREE.MeshStandardMaterial {
        return new THREE.MeshStandardMaterial({
            color: options.color ?? 0x808080,
            roughness: options.roughness ?? 0.8,
            metalness: options.metalness ?? 0.1,
            emissive: options.emissive ?? 0x000000,
            emissiveIntensity: options.emissiveIntensity ?? 0,
        })
    }

    /**
     * Create game box materials with varied colors (PBR version)
     */
    static createGameBoxMaterials(): THREE.MeshStandardMaterial[] {
        const colors = [
            0x4a90e2, // Blue
            0xe74c3c, // Red
            0x2ecc71, // Green  
            0xf39c12, // Orange
            0x9b59b6, // Purple
            0x1abc9c, // Teal
        ]

        return colors.map(color => 
            MaterialUtils.createPBRMaterial({
                color,
                roughness: 0.7,
                metalness: 0.1,
            })
        )
    }

    /**
     * Create game box material with color from game name (PBR version)
     */
    static createGameBoxMaterialFromName(gameNameHue: number): THREE.MeshStandardMaterial {
        const color = new THREE.Color().setHSL(gameNameHue, 0.7, 0.5)
        return MaterialUtils.createPBRMaterial({
            color,
            roughness: 0.7,
            metalness: 0.1,
        })
    }

    /**
     * Create floor material with carpet-like properties
     */
    static createFloorMaterial(): THREE.MeshStandardMaterial {
        return MaterialUtils.createPBRMaterial({
            color: BlockbusterColors.floor,
            roughness: 0.9, // Very rough for carpet texture
            metalness: 0.0, // No metallic properties for carpet
        })
    }

    /**
     * Create wall material with slight texture
     */
    static createWallMaterial(): THREE.MeshStandardMaterial {
        return MaterialUtils.createPBRMaterial({
            color: BlockbusterColors.walls,
            roughness: 0.8, // Slightly rough for painted walls
            metalness: 0.0, // No metallic properties for painted walls
        })
    }

    /**
     * Create ceiling material
     */
    static createCeilingMaterial(): THREE.MeshStandardMaterial {
        return MaterialUtils.createPBRMaterial({
            color: BlockbusterColors.ceiling,
            roughness: 0.9, // Very rough for popcorn texture
            metalness: 0.0, // No metallic properties
        })
    }

    /**
     * Create shelf wood material
     */
    static createShelfWoodMaterial(): THREE.MeshStandardMaterial {
        return MaterialUtils.createPBRMaterial({
            color: BlockbusterColors.shelfWood,
            roughness: 0.6, // Moderate roughness for wood
            metalness: 0.0, // No metallic properties for wood
        })
    }

    /**
     * Create signage material
     */
    static createSignageMaterial(backgroundColor: number, _textColor: number): THREE.MeshStandardMaterial {
        return MaterialUtils.createPBRMaterial({
            color: backgroundColor,
            roughness: 0.3, // Smoother for signage
            metalness: 0.0,
            emissive: backgroundColor,
            emissiveIntensity: 0.1, // Slight glow for signage
        })
    }
}

/**
 * MeshPrewarmer
 *
 * Singleton that collects InstancedMesh objects from any renderer that opts in,
 * then calls renderer.compileAsync() once after a debounce window, ensuring all
 * registrations from a single init burst are batched into one compile call.
 *
 * Only active when KHR_parallel_shader_compile is available ΓÇö without it,
 * compileAsync() blocks the main thread anyway and Three.js logs a warning,
 * so we skip it entirely and let shaders compile on first render.
 *
 * Usage (static API ΓÇö no getInstance() needed):
 *   MeshPrewarmer.register(myInstancedMesh)
 *
 * The prewarm scene is a lightweight container (holds references only, no copies).
 * After compileAsync resolves the meshes are removed and the instance is released
 * for GC (one-shot lifecycle).
 */

import * as THREE from 'three'
import { DataManager } from '../core/data/DataManager'
import { DataKey } from '../core/data/DataTypes'
import { SystemCapabilitiesDetector } from './SystemCapabilities'
import { Logger } from './Logger'

const DEBOUNCE_MS = 500

export class MeshPrewarmer {
    // ES2022 private static field ΓÇö truly private, not just TS-private.
    // Nulled in cleanup() to release for GC after the one-shot prewarm completes.
    static #instance: MeshPrewarmer | null = null
    private static readonly logger = Logger.createLogFunctions(MeshPrewarmer.name)

    // Single declaration of lazy-init logic. All static methods go through this getter.
    static get #current(): MeshPrewarmer {
        return MeshPrewarmer.#instance ??= new MeshPrewarmer()
    }

    private readonly prewarmScene = new THREE.Scene()
    private debounceHandle: ReturnType<typeof setTimeout> | null = null
    private completed = false

    private constructor() {}

    /**
     * Register a mesh for shader prewarm. Safe to call multiple times ΓÇö each
     * call resets the debounce window so that a burst of registrations is
     * batched into a single compileAsync() call.
     *
     * No-op if prewarm has already completed or KHR is unavailable.
     */
    public static register(mesh: THREE.InstancedMesh): void {
        MeshPrewarmer.#current.registerImpl(mesh)
    }

    private registerImpl(mesh: THREE.InstancedMesh): void {
        if (this.completed) {
            MeshPrewarmer.logger.warn(
                `register("${mesh.name}") called after prewarm completed ΓÇö mesh will compile on first render. ` +
                `If this is unexpected, ensure register() is called before the prewarm debounce fires.`
            )
            return
        }

        const capabilities = SystemCapabilitiesDetector.detect()
        if (!capabilities.hasParallelShaderCompile) return

        this.prewarmScene.add(mesh)
        MeshPrewarmer.logger.debug(`Registered mesh "${mesh.name}" for prewarm (${this.prewarmScene.children.length} total)`)

        // Reset debounce ΓÇö wait for the burst to settle before compiling
        if (this.debounceHandle !== null) {
            clearTimeout(this.debounceHandle)
        }
        this.debounceHandle = setTimeout(() => this.runPrewarm(), DEBOUNCE_MS)
    }

    private async runPrewarm(): Promise<void> {
        this.debounceHandle = null

        const renderer = DataManager.getInstance().get<THREE.WebGLRenderer>(DataKey.Renderer)
        const camera   = DataManager.getInstance().get<THREE.Camera>(DataKey.MainCamera)

        if (!renderer || !camera) {
            MeshPrewarmer.logger.warn('Renderer/camera not available ΓÇö skipping prewarm')
            this.cleanup()
            return
        }

        const meshCount = this.prewarmScene.children.length
        MeshPrewarmer.logger.debug(`≡ƒöÑ Compiling ${meshCount} mesh(es) via compileAsync...`)
        const startTime = performance.now()

        try {
            await renderer.compileAsync(this.prewarmScene, camera)
            MeshPrewarmer.logger.debug(
                `Γ£à Shader prewarm complete ΓÇö ${meshCount} mesh(es) in ${(performance.now() - startTime).toFixed(0)}ms`
            )
        } catch (error) {
            MeshPrewarmer.logger.warn('compileAsync failed (non-fatal):', error)
        }

        this.cleanup()
    }

    private cleanup(): void {
        for (const child of [...this.prewarmScene.children]) {
            this.prewarmScene.remove(child)
        }
        this.completed = true
        MeshPrewarmer.#instance = null  // release for GC ΓÇö one-shot lifecycle
    }
}

/**
 * Advanced noise generation utilities for procedural textures
 * Implements Perlin and Simplex noise for more realistic patterns
 */

export class NoiseGenerator {
  private static permutation: number[] = [
    151, 160, 137, 91, 90, 15, 131, 13, 201, 95, 96, 53, 194, 233, 7, 225,
    140, 36, 103, 30, 69, 142, 8, 99, 37, 240, 21, 10, 23, 190, 6, 148,
    247, 120, 234, 75, 0, 26, 197, 62, 94, 252, 219, 203, 117, 35, 11, 32,
    57, 177, 33, 88, 237, 149, 56, 87, 174, 20, 125, 136, 171, 168, 68, 175,
    74, 165, 71, 134, 139, 48, 27, 166, 77, 146, 158, 231, 83, 111, 229, 122,
    60, 211, 133, 230, 220, 105, 92, 41, 55, 46, 245, 40, 244, 102, 143, 54,
    65, 25, 63, 161, 1, 216, 80, 73, 209, 76, 132, 187, 208, 89, 18, 169,
    200, 196, 135, 130, 116, 188, 159, 86, 164, 100, 109, 198, 173, 186, 3, 64,
    52, 217, 226, 250, 124, 123, 5, 202, 38, 147, 118, 126, 255, 82, 85, 212,
    207, 206, 59, 227, 47, 16, 58, 17, 182, 189, 28, 42, 223, 183, 170, 213,
    119, 248, 152, 2, 44, 154, 163, 70, 221, 153, 101, 155, 167, 43, 172, 9,
    129, 22, 39, 253, 19, 98, 108, 110, 79, 113, 224, 232, 178, 185, 112, 104,
    218, 246, 97, 228, 251, 34, 242, 193, 238, 210, 144, 12, 191, 179, 162, 241,
    81, 51, 145, 235, 249, 14, 239, 107, 49, 192, 214, 31, 181, 199, 106, 157,
    184, 84, 204, 176, 115, 121, 50, 45, 127, 4, 150, 254, 138, 236, 205, 93,
    222, 114, 67, 29, 24, 72, 243, 141, 128, 195, 78, 66, 215, 61, 156, 180
  ];

  private static p: number[] = new Array(512);

  static {
    // Initialize permutation table
    for (let i = 0; i < 512; i++) {
      NoiseGenerator.p[i] = NoiseGenerator.permutation[i % 256];
    }
  }

  /**
   * Simple 2D noise function that actually works
   */
  public static perlin(x: number, y: number, _z: number = 0): number {
    // Use a simple but effective noise implementation
    const value = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
    return (value - Math.floor(value)) * 2 - 1; // Return value between -1 and 1
  }

  /**
   * Octave noise - combines multiple octaves of Perlin noise
   */
  public static octaveNoise(x: number, y: number, octaves: number = 4, persistence: number = 0.5, scale: number = 1): number {
    let value = 0;
    let amplitude = 1;
    let frequency = scale;
    let maxValue = 0;

    for (let i = 0; i < octaves; i++) {
      value += this.perlin(x * frequency, y * frequency) * amplitude;
      maxValue += amplitude;
      amplitude *= persistence;
      frequency *= 2;
    }

    return value / maxValue;
  }

  /**
   * Wood grain noise - specialized for wood textures
   * Creates longitudinal grain running along the X-axis (length of the board)
   */
  public static woodGrain(x: number, y: number, ringFrequency: number = 0.1, grainStrength: number = 0.3): number {
    // Create grain lines running horizontally (along X-axis)
    // This simulates wood cut along the length of the grain
    const grainLines = Math.sin(y * ringFrequency) * 0.5 + 0.5;
    
    // Add subtle variation along the grain direction (X-axis)
    const grainVariation = this.octaveNoise(x * 0.01, y * 0.05, 2, 0.3, 1) * 0.2;
    
    // Add fine grain detail perpendicular to the main grain
    const fineGrain = this.octaveNoise(x * 0.08, y * 0.02, 3, 0.4, 1) * grainStrength;
    
    // Combine grain lines with variations for realistic wood appearance
    return Math.max(0, Math.min(1, grainLines + grainVariation + fineGrain));
  }

  /**
   * Carpet fiber noise - creates realistic carpet texture
   */
  public static carpetFiber(x: number, y: number, fiberDensity: number = 0.3): number {
    // Create fiber pattern with multiple octaves
    const fiber1 = this.octaveNoise(x * 0.1, y * 0.1, 2, 0.5, 1);
    const fiber2 = this.octaveNoise(x * 0.05, y * 0.2, 3, 0.3, 1);
    const fiber3 = this.octaveNoise(x * 0.2, y * 0.1, 2, 0.7, 1);
    
    return (fiber1 + fiber2 + fiber3) * fiberDensity;
  }

  /**
   * Popcorn ceiling noise - creates bumpy ceiling texture
   */
  public static popcornCeiling(x: number, y: number, bumpSize: number = 0.4, density: number = 0.6): number {
    // Create random bumps at different scales
    const bump1 = this.octaveNoise(x * 0.05, y * 0.05, 2, 0.8, 1);
    const bump2 = this.octaveNoise(x * 0.1, y * 0.1, 3, 0.6, 1);
    const bump3 = this.octaveNoise(x * 0.2, y * 0.2, 2, 0.4, 1);
    
    const combined = (bump1 + bump2 + bump3) * bumpSize;
    
    // Apply density threshold to create more realistic sparse bumps
    return combined > (1 - density) ? combined : 0;
  }

  private static fade(t: number): number {
    return t * t * t * (t * (t * 6 - 15) + 10);
  }

  private static lerp(t: number, a: number, b: number): number {
    return a + t * (b - a);
  }

  private static grad(hash: number, x: number, y: number, z: number): number {
    const h = hash & 15;
    const u = h < 8 ? x : y;
    const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  }
}

/**
 * Unified Performance Monitor
 * 
 * Single system for performance tracking that provides:
 * - Console logging with threshold warnings
 * - Main thread blocking detection
 * - Frame budget violation tracking
 * - Report generation for offline analysis
 * 
 * Replaces PerformanceTimer and MainThreadBlockingTracker with one consistent API.
 * 
 * Usage:
 * ```typescript
 * const monitor = PerformanceMonitor.start('batch-process', logger)
 * // ... do work ...
 * monitor.end({ batchIndex: 1 })
 * ```
 */

import { AppSettings, Setting } from '../core/AppSettings'

const TARGET_FRAME_TIME = 16.67 // 60 FPS budget in milliseconds
const DEFAULT_CONSOLE_THRESHOLD = 100 // Warn in console if operation > 100ms
const DEFAULT_BLOCKING_THRESHOLD = 33 // Flag as blocking if > 2 frames

export interface LogFunctions {
    error: (...args: unknown[]) => void
    warn: (...args: unknown[]) => void
    info: (...args: unknown[]) => void
    debug: (...args: unknown[]) => void
}

export interface MonitorOptions {
    /** Console warning threshold in milliseconds (default: 100) */
    consoleThreshold?: number
    /** Blocking detection threshold in milliseconds (default: 33) */
    blockingThreshold?: number
    /** Thread context for log messages */
    context?: 'MAIN THREAD' | 'ASYNC'
    /** Initial metadata */
    metadata?: Record<string, unknown>
    /** Log level for non-warnings (default: 'debug') */
    level?: 'debug' | 'info'
}

/** Pre-configured context for async operations (network, cache, etc.) */
export const ASYNC_CONTEXT: MonitorOptions = {
    context: 'ASYNC',
    level: 'info'
}

/** Pre-configured context for main thread operations */
export const MAIN_THREAD_CONTEXT: MonitorOptions = {
    context: 'MAIN THREAD'
}

export interface BlockingOperation {
    name: string
    startTime: number
    endTime: number
    duration: number // Wall-clock time (actual elapsed time)
    totalWork?: number // Sum of all parallel work (e.g., 20 parallel fetches ├ù 500ms each = 10000ms)
    metadata?: Record<string, unknown>
    severity: 'normal' | 'warning' | 'critical'
    context?: 'MAIN THREAD' | 'ASYNC'
}

export interface FrameViolation {
    frameNumber: number
    duration: number
    overbudget: number
    timestamp: number
    operations: string[]
}

export interface AggregatedOperation {
    name: string
    count: number
    totalDuration: number // Sum of wall-clock times
    totalWork?: number // Sum of all parallel work across all operations
    averageDuration: number
    minDuration: number
    maxDuration: number
    severity: 'normal' | 'warning' | 'critical'
}

export interface PerformanceReport {
    metadata: {
        userAgent: string
        timestamp: string
        duration: number
        url: string
    }
    mainThreadBlocking: {
        operations: BlockingOperation[]
        aggregatedOperations: AggregatedOperation[]
        totalDuration: number
    }
    asyncOperations: {
        operations: BlockingOperation[]
        aggregatedOperations: AggregatedOperation[]
        totalDuration: number
    }
    frameViolations: FrameViolation[]
    summary: {
        totalOperations: number
        mainThreadOperations: number
        asyncOperations: number
        warningOperations: number
        criticalOperations: number
        totalFrameViolations: number
        longestBlock: BlockingOperation | null
        longestAsync: BlockingOperation | null
    }
}

class PerformanceMonitorInstance {
    private operation: string
    private logger: LogFunctions
    private startTime: number
    private options: Required<MonitorOptions>

    constructor(operation: string, logger: LogFunctions, options: MonitorOptions = {}) {
        this.operation = operation
        this.logger = logger
        this.startTime = performance.now()
        this.options = {
            consoleThreshold: options.consoleThreshold ?? DEFAULT_CONSOLE_THRESHOLD,
            blockingThreshold: options.blockingThreshold ?? DEFAULT_BLOCKING_THRESHOLD,
            context: options.context ?? undefined as any,
            metadata: options.metadata ?? {},
            level: options.level ?? 'debug'
        }

        // Start blocking detection if enabled
        if (PerformanceMonitor.isBlockingDetectionEnabled()) {
            PerformanceMonitor.startOperation(operation, this.options.metadata)
        }

        // Create performance mark for browser DevTools
        performance.mark(`${operation}-start`)
    }

    getElapsed(): number {
        return performance.now() - this.startTime
    }

    end(metadata?: Record<string, unknown>, totalWork?: number): void {
        const elapsed = this.getElapsed()
        const allMetadata = { ...this.options.metadata, ...metadata }

        // Create performance measure for browser DevTools
        performance.mark(`${this.operation}-end`)
        performance.measure(this.operation, `${this.operation}-start`, `${this.operation}-end`)

        // Console logging (always happens)
        this.logResult(elapsed, allMetadata, totalWork)

        // Blocking detection (only if enabled)
        if (PerformanceMonitor.isBlockingDetectionEnabled()) {
            PerformanceMonitor.endOperation(this.operation, elapsed, allMetadata, this.options.blockingThreshold, this.options.context, totalWork)
        }
    }

    private logResult(elapsed: number, metadata: Record<string, unknown>, totalWork?: number): void {
        const contextPrefix = this.options.context ? `[${this.options.context}] ` : ''
        const workStr = totalWork ? ` [${totalWork.toFixed(0)}ms total work]` : ''
        const metadataStr = this.formatMetadata(metadata)
        const baseMsg = `${contextPrefix}${this.operation}: ${elapsed.toFixed(1)}ms${workStr}${metadataStr}`

        if (elapsed > this.options.consoleThreshold) {
            this.logger.warn(`${baseMsg} ΓÜá∩╕Å`)
        } else {
            this.logger[this.options.level](baseMsg)
        }
    }

    private formatMetadata(metadata: Record<string, unknown>): string {
        if (Object.keys(metadata).length === 0) return ''

        const parts = Object.entries(metadata).map(([key, value]) => {
            if (typeof value === 'number') {
                return `${key}: ${value}`
            }
            return `${key}: ${value}`
        })

        return ` (${parts.join(', ')})`
    }
}

export class PerformanceMonitor {
    private static operations: BlockingOperation[] = []
    private static activeOperations = new Map<string, { startTime: number; metadata?: Record<string, unknown> }>()
    private static activeOperationNames = new Set<string>()

    // Frame tracking
    private static frameViolations: FrameViolation[] = []
    private static frameStart = 0
    private static frameNumber = 0
    private static isFrameTracking = false
    private static rafId: number | null = null
    private static isPageVisible = true

    // Tracking state
    private static isTracking = false
    private static trackingStartTime = 0

    static {
        // Setup page visibility tracking
        if (typeof document !== 'undefined') {
            document.addEventListener('visibilitychange', () => {
                PerformanceMonitor.isPageVisible = !document.hidden
                if (!PerformanceMonitor.isPageVisible) {
                    PerformanceMonitor.frameStart = 0
                }
            })
            PerformanceMonitor.isPageVisible = !document.hidden
        }
    }

    static isBlockingDetectionEnabled(): boolean {
        return AppSettings.get(Setting.EnableBlockingTracker)
    }

    static start(operation: string, logger: LogFunctions, options?: MonitorOptions): PerformanceMonitorInstance {
        // Start tracking if this is the first monitored operation and blocking detection is enabled
        if (!PerformanceMonitor.isTracking && PerformanceMonitor.isBlockingDetectionEnabled()) {
            PerformanceMonitor.startTracking()
        }

        return new PerformanceMonitorInstance(operation, logger, options)
    }

    private static startTracking(): void {
        if (this.isTracking) return

        this.isTracking = true
        this.trackingStartTime = performance.now()
        this.operations = []
        this.frameViolations = []
        this.activeOperations.clear()
        this.activeOperationNames.clear()
        this.frameNumber = 0

        this.startFrameTracking()
    }

    static stopTracking(): PerformanceReport {
        this.isTracking = false
        this.stopFrameTracking()
        return this.generateReport()
    }

    /** @internal - Internal utility, do not call directly */
    static startOperation(name: string, metadata?: Record<string, unknown>): void {
        const id = `${name}-${performance.now()}`
        this.activeOperations.set(id, {
            startTime: performance.now(),
            metadata
        })
        this.activeOperationNames.add(name)
    }

    /** @internal - Internal utility, do not call directly */
    static endOperation(
        name: string,
        duration: number,
        metadata: Record<string, unknown>,
        blockingThreshold: number,
        context?: 'MAIN THREAD' | 'ASYNC',
        totalWork?: number
    ): void {
        // Find most recent operation with this name
        const id = Array.from(this.activeOperations.keys())
            .reverse()
            .find(k => k.startsWith(name))

        if (!id) return

        const active = this.activeOperations.get(id)!

        // Determine severity based on blocking threshold
        let severity: BlockingOperation['severity'] = 'normal'
        if (duration > blockingThreshold * 2) {
            severity = 'critical'
        } else if (duration > blockingThreshold) {
            severity = 'warning'
        }

        const operation: BlockingOperation = {
            name,
            startTime: active.startTime,
            endTime: active.startTime + duration,
            duration,
            totalWork,
            metadata,
            severity,
            context
        }

        this.operations.push(operation)
        this.activeOperations.delete(id)
        this.activeOperationNames.delete(name)
    }

    private static startFrameTracking(): void {
        if (this.isFrameTracking) return

        this.isFrameTracking = true
        this.scheduleNextFrame()
    }

    private static stopFrameTracking(): void {
        this.isFrameTracking = false
        if (this.rafId !== null) {
            cancelAnimationFrame(this.rafId)
            this.rafId = null
        }
    }

    private static scheduleNextFrame(): void {
        if (!this.isFrameTracking) return

        this.rafId = requestAnimationFrame((timestamp) => {
            if (!this.isPageVisible) {
                this.frameStart = 0
                this.scheduleNextFrame()
                return
            }

            if (this.frameStart > 0) {
                const frameDuration = timestamp - this.frameStart
                const overbudget = frameDuration - TARGET_FRAME_TIME

                if (overbudget >= 1.0) {
                    const activeOps = Array.from(this.activeOperationNames)

                    this.frameViolations.push({
                        frameNumber: this.frameNumber,
                        duration: frameDuration,
                        overbudget: overbudget,
                        timestamp,
                        operations: activeOps
                    })
                }
            }

            this.frameStart = timestamp
            this.frameNumber++
            this.scheduleNextFrame()
        })
    }

    private static generateReport(): PerformanceReport {
        const endTime = performance.now()

        // Separate operations by context
        const mainThreadOps = this.operations.filter(op => op.context !== 'ASYNC')
        const asyncOps = this.operations.filter(op => op.context === 'ASYNC')

        const warningOps = this.operations.filter(op => op.severity === 'warning')
        const criticalOps = this.operations.filter(op => op.severity === 'critical')

        const longestBlock = mainThreadOps.length > 0
            ? mainThreadOps.reduce((max, op) => op.duration > max.duration ? op : max)
            : null
        const longestAsync = asyncOps.length > 0
            ? asyncOps.reduce((max, op) => op.duration > max.duration ? op : max)
            : null

        // Generate aggregated stats for both contexts
        const generateAggregations = (operations: BlockingOperation[]) => {
            const operationGroups = new Map<string, BlockingOperation[]>()
            for (const op of operations) {
                if (!operationGroups.has(op.name)) {
                    operationGroups.set(op.name, [])
                }
                operationGroups.get(op.name)!.push(op)
            }

            const aggregatedOperations: AggregatedOperation[] = []
            for (const [name, ops] of operationGroups.entries()) {
                // Only aggregate if there are multiple instances OR if any instance is < 16ms
                const shouldAggregate = ops.length > 1 || ops.some(op => op.duration < 16)

                if (shouldAggregate) {
                    const durations = ops.map(op => op.duration)
                    const totalDuration = durations.reduce((sum, d) => sum + d, 0)
                    const totalWork = ops.reduce((sum, op) => sum + (op.totalWork || op.duration), 0)
                    const maxSeverity = ops.some(op => op.severity === 'critical') ? 'critical' :
                                       ops.some(op => op.severity === 'warning') ? 'warning' : 'normal'

                    const agg: AggregatedOperation = {
                        name,
                        count: ops.length,
                        totalDuration,
                        averageDuration: totalDuration / ops.length,
                        minDuration: Math.min(...durations),
                        maxDuration: Math.max(...durations),
                        severity: maxSeverity
                    }

                    // Only include totalWork if at least one operation has it
                    if (ops.some(op => op.totalWork !== undefined)) {
                        agg.totalWork = totalWork
                    }

                    aggregatedOperations.push(agg)
                }
            }

            // Sort by total duration
            aggregatedOperations.sort((a, b) => b.totalDuration - a.totalDuration)

            // Filter detailed operations: only significant (>=16ms) AND not repeated
            const detailedOperations = operations.filter(op => {
                const group = operationGroups.get(op.name)!
                const isRepeated = group.length > 1
                return op.duration >= 16 && !isRepeated
            })

            const totalDuration = operations.reduce((sum, op) => sum + op.duration, 0)

            return { aggregatedOperations, detailedOperations, totalDuration }
        }

        const mainThreadStats = generateAggregations(mainThreadOps)
        const asyncStats = generateAggregations(asyncOps)

        return {
            metadata: {
                userAgent: navigator.userAgent,
                timestamp: new Date().toISOString(),
                duration: endTime - this.trackingStartTime,
                url: window.location.href
            },
            mainThreadBlocking: {
                operations: mainThreadStats.detailedOperations,
                aggregatedOperations: mainThreadStats.aggregatedOperations,
                totalDuration: mainThreadStats.totalDuration
            },
            asyncOperations: {
                operations: asyncStats.detailedOperations,
                aggregatedOperations: asyncStats.aggregatedOperations,
                totalDuration: asyncStats.totalDuration
            },
            frameViolations: this.frameViolations,
            summary: {
                totalOperations: this.operations.length,
                mainThreadOperations: mainThreadOps.length,
                asyncOperations: asyncOps.length,
                warningOperations: warningOps.length,
                criticalOperations: criticalOps.length,
                totalFrameViolations: this.frameViolations.length,
                longestBlock,
                longestAsync
            }
        }
    }

    static getReport(): PerformanceReport {
        return this.generateReport()
    }

    static downloadReport(filename = 'performance-report.json'): void {
        const report = this.getReport()
        const json = JSON.stringify(report, null, 2)
        const blob = new Blob([json], { type: 'application/json' })
        const url = URL.createObjectURL(blob)

        const a = document.createElement('a')
        a.href = url
        a.download = filename
        a.click()

        URL.revokeObjectURL(url)
    }

    static getStats() {
        return {
            isTracking: this.isTracking,
            totalOperations: this.operations.length,
            warningOperations: this.operations.filter(op => op.severity === 'warning').length,
            criticalOperations: this.operations.filter(op => op.severity === 'critical').length,
            frameViolations: this.frameViolations.length,
            activeOperations: this.activeOperations.size
        }
    }

    static reset(): void {
        this.operations = []
        this.frameViolations = []
        this.activeOperations.clear()
        this.activeOperationNames.clear()
        this.frameNumber = 0
    }
}

// Expose to window for console access
if (typeof window !== 'undefined') {
    (window as any).UnifiedPerformanceMonitor = PerformanceMonitor
}

/**
 * Procedural Texture Generator
 * Creates textures programmatically for better performance and no file dependencies
 */

import * as THREE from 'three'
import { 
  WoodTextureGenerator, 
  CarpetTextureGenerator, 
  CeilingTextureGenerator,
  type WoodTextureOptions,
  type EnhancedWoodTextureOptions,
  type WoodNormalMapOptions,
  type CarpetTextureOptions,
  type EnhancedCarpetTextureOptions,
  type CeilingTextureOptions,
  type EnhancedCeilingTextureOptions
} from './textures'

export class ProceduralTextures {
    private static instance: ProceduralTextures
    private woodGenerator: WoodTextureGenerator
    private carpetGenerator: CarpetTextureGenerator
    private ceilingGenerator: CeilingTextureGenerator

    private constructor() {
        this.woodGenerator = new WoodTextureGenerator()
        this.carpetGenerator = new CarpetTextureGenerator()
        this.ceilingGenerator = new CeilingTextureGenerator()
    }

    public static getInstance(): ProceduralTextures {
        if (!ProceduralTextures.instance) {
            ProceduralTextures.instance = new ProceduralTextures()
        }
        return ProceduralTextures.instance
    }

    /**
     * Create a wood grain texture procedurally
     */
    public createWoodTexture(options: WoodTextureOptions = {}): THREE.Texture {
        return this.woodGenerator.createTexture(options)
    }

    /**
     * Create a carpet texture procedurally
     */
    public createCarpetTexture(options: CarpetTextureOptions = {}): THREE.Texture {
        return this.carpetGenerator.createTexture(options)
    }

    /**
     * Create a popcorn ceiling texture procedurally
     */
    public createCeilingTexture(options: CeilingTextureOptions = {}): THREE.Texture {
        return this.ceilingGenerator.createTexture(options)
    }

    /**
     * Create a normal map for wood grain
     */
    public createWoodNormalMap(options: WoodNormalMapOptions = {}): THREE.Texture {
        return this.woodGenerator.createNormalMap(options)
    }

    /**
     * Create an enhanced wood grain texture with realistic patterns
     */
    public createEnhancedWoodTexture(options: EnhancedWoodTextureOptions = {}): THREE.Texture {
        return this.woodGenerator.createEnhancedTexture(options)
    }

    /**
     * Create an enhanced carpet texture with realistic fiber patterns
     */
    public createEnhancedCarpetTexture(options: EnhancedCarpetTextureOptions = {}): THREE.Texture {
        return this.carpetGenerator.createEnhancedTexture(options)
    }

    /**
     * Create an enhanced popcorn ceiling texture with realistic bumps
     */
    public createEnhancedCeilingTexture(options: EnhancedCeilingTextureOptions = {}): THREE.Texture {
        return this.ceilingGenerator.createEnhancedTexture(options)
    }

    /**
     * Clear texture cache to free memory
     */
    public clearCache(): void {
        this.woodGenerator.clearCache()
        this.carpetGenerator.clearCache()
        this.ceilingGenerator.clearCache()
    }

    /**
     * Get cache statistics
     */
    public getCacheStats(): { count: number; keys: string[] } {
        const woodStats = this.woodGenerator.getCacheStats()
        const carpetStats = this.carpetGenerator.getCacheStats()
        const ceilingStats = this.ceilingGenerator.getCacheStats()
        
        return {
            count: woodStats.count + carpetStats.count + ceilingStats.count,
            keys: [...woodStats.keys, ...carpetStats.keys, ...ceilingStats.keys]
        }
    }
}

/**
 * Shared Material Manager - Material Resource Pooling
 *
 * TD: singleton-pattern-refactor
 * TD: carpet-worker-offload
 *
 * Provides centralized management of shared material instances to reduce
 * material duplication and enable effective batching.
 *
 * Performance:
 * - Initialization: Near-instant (empty pool)
 * - Simple materials (glass, fallback, shelf interior): sync, instant
 * - Procedural materials (wood, carpet, ceiling): generated off-thread via
 *   ProceduralTextureWorker. Call prewarm() at startup so by the time
 *   getMaterial() is called they are already cached.
 */

import * as THREE from 'three'
import { MaterialUtils } from './MaterialUtils'
import { Logger } from './Logger'
import { ProceduralTextureWorker } from './textures/ProceduralTextureWorker'
import { EventManager } from '../core/EventManager'
import { StorePropsEventTypes } from '../scene/props/PropsEvents'
import { FrameBudgetScheduler } from './FrameBudgetScheduler'

import { ProceduralCarpetPatternGenerator, type CarpetStyleConfig } from './textures/ProceduralCarpetPatternGenerator'

export enum MaterialType {
    FallbackGameBox = 'fallbackGameBox',
    MdfVeneer       = 'mdfVeneer',
    ShelfInterior   = 'shelfInterior',
    BrandAccent     = 'brandAccent',
    Carpet          = 'carpet',
    Ceiling         = 'ceiling',
    WallWood        = 'wallWood',
    BasicWood       = 'basicWood',
    Glass           = 'glass'
}

export interface MaterialPool {
    materials: Map<MaterialType, THREE.MeshStandardMaterial>
}

export interface MaterialStats {
    totalMaterials: number
    memoryEstimate: number  // bytes
    poolHitRate:    number  // 0-1
}

export class SharedMaterialManager {
    private static readonly logger = Logger.createLogFunctions(SharedMaterialManager.name)
    private static instance: SharedMaterialManager

    private materialPool:    MaterialPool | null = null
    private prewarmPromise:  Promise<void> | null = null
    private poolRequests = 0
    private poolHits     = 0
    private disposed     = false

    private proceduralCarpetPatternGenerator: ProceduralCarpetPatternGenerator
    private currentCarpetStyle: CarpetStyleConfig = {
        patternType: 'classic',
        variant: 'diamond',
        colors: ['#8B0000', '#800020', '#722F37'],
        scale: 1.0,
        density: 0.4
    }

    private constructor() {
        this.proceduralCarpetPatternGenerator = new ProceduralCarpetPatternGenerator()
        // Lightweight ΓÇö no sync texture generation here.

        // Observe SetupRequest to trigger prewarm. Use plain registerEventHandler
        // so this fires even when GpuStorePropsEventHandler holds the normal handler slot.
        EventManager.getInstance().registerEventHandler(
            StorePropsEventTypes.SetupRequest,
            this.generateTexturesAsync.bind(this)
        )
    }

    public static getInstance(): SharedMaterialManager {
        if (!SharedMaterialManager.instance) {
            SharedMaterialManager.instance = new SharedMaterialManager()
        }
        return SharedMaterialManager.instance
    }

    // ΓöÇΓöÇΓöÇ Lifecycle ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    public initialize(): void {
        if (this.disposed) throw new Error('SharedMaterialManager has been disposed')
        if (this.materialPool) {
            SharedMaterialManager.logger.warn('ΓÜá∩╕Å SharedMaterialManager already initialized')
            return
        }
        const t0 = performance.now()
        this.materialPool = { materials: new Map() }
        SharedMaterialManager.logger.debug(
            `Γ£à SharedMaterialManager initialized in ${(performance.now() - t0).toFixed(2)}ms`
        )
    }

    /**
     * Pre-warm all procedurally-generated materials off the main thread.
     * Call once at startup. Subsequent calls return the same Promise (idempotent).
     */
    public async generateTexturesAsync(): Promise<void> {
        if (this.disposed) return
        if (this.prewarmPromise) return this.prewarmPromise

        this.prewarmPromise = (async () => {
            if (!this.materialPool) this.initialize()
            const worker = ProceduralTextureWorker.getInstance()
            const t0 = performance.now()
            SharedMaterialManager.logger.debug('≡ƒÜÇ Starting off-thread material prewarm...')

            await Promise.all([
                this.prewarmMDFVeneer(worker),
                this.prewarmCarpet(worker),
                this.prewarmCeiling(worker),
                this.prewarmWallWood(worker),
                // BasicWood: currently unused ΓÇö no getMaterial(BasicWood) callers exist.
                // Re-add this.prewarmBasicWood(worker) if a use is introduced.
            ])

            SharedMaterialManager.logger.debug(
                `Γ£¿ Material prewarm complete in ${(performance.now() - t0).toFixed(2)}ms`
            )
        })().catch(err => {
            SharedMaterialManager.logger.warn('Material prewarm failed, continuing with fallback materials:', err)
        })

        return this.prewarmPromise
    }


    // --- Public API ----------------------------------------------------------

    public getMaterial(type: MaterialType): THREE.MeshStandardMaterial {
        if (!this.materialPool) this.initialize()

        if (!this.materialPool!.materials.has(type)) {
            // Fallback sync path: only reached if prewarm() wasn't awaited first.
            // Procedural types will still block here ΓÇö prewarm() prevents this.
            const mat = this.createMaterialSync(type)
            this.materialPool!.materials.set(type, mat)
        }

        this.poolRequests++
        this.poolHits++
        return this.materialPool!.materials.get(type)!
    }

    public isInitialized(): boolean {
        return this.materialPool !== null && !this.disposed
    }

    public getStats(): MaterialStats {
        if (!this.materialPool) return { totalMaterials: 0, memoryEstimate: 0, poolHitRate: 0 }
        const totalMaterials = this.materialPool.materials.size
        return {
            totalMaterials,
            memoryEstimate: totalMaterials * 1024,
            poolHitRate: this.poolRequests > 0 ? this.poolHits / this.poolRequests : 0
        }
    }

    public dispose(): void {
        if (this.materialPool) {
            this.materialPool.materials.forEach(m => m.dispose())
            this.materialPool.materials.clear()
            this.materialPool = null
        }
        ProceduralTextureWorker.getInstance()?.dispose?.()
        this.disposed = true
        SharedMaterialManager.instance = null as any
        console.log('≡ƒùæ∩╕Å SharedMaterialManager disposed')
    }

    // ΓöÇΓöÇΓöÇ Async prewarm helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    private async prewarmMDFVeneer(worker: ProceduralTextureWorker): Promise<void> {
        const [diffuseBitmap, normalBitmap] = await Promise.all([
            worker.generate('wood_enhanced', {
                width: 1024, height: 1024,
                grainStrength: 0.3, ringFrequency: 0.01,
                color1: '#E6D3B7', color2: '#D4C4A0', color3: '#C8B896',
            }),
            worker.generate('wood_normal', { width: 1024, height: 1024, strength: 0.06 }),
        ])
        const diffuse = this.bitmapToTexture(diffuseBitmap, 6, 4)
        const normal  = this.bitmapToTexture(normalBitmap,  6, 4)

        FrameBudgetScheduler.getInstance().schedule(
            () => this.upsertMaterial(MaterialType.MdfVeneer,
                new THREE.MeshStandardMaterial({ map: diffuse, normalMap: normal, roughness: 0.4, metalness: 0.0 })),
            { priority: 'normal', estimatedMs: 2, maxDeferMs: 0 }
        )
    }

    private async prewarmCarpet(_worker: ProceduralTextureWorker): Promise<void> {
        // TD: carpet-worker-offload
        // Currently runs synchronously on the main thread. Should be moved to
        // ProceduralTextureWorker (add a 'carpet_enhanced' type) like the other
        // procedural textures. See tech-debt.md for tracking.
        const config = {
            width: 512,
            height: 512,
            style: this.currentCarpetStyle,
            roughness: 0.9,
            metalness: 0.0,
            repeat: { x: 4, y: 4 }
        }

        const material = this.proceduralCarpetPatternGenerator.createCarpetMaterial(config)

        FrameBudgetScheduler.getInstance().schedule(
            () => this.upsertMaterial(MaterialType.Carpet, material),
            { priority: 'normal', estimatedMs: 5, maxDeferMs: 0 }
        )
    }

    private async prewarmCeiling(worker: ProceduralTextureWorker): Promise<void> {
        const [diffuseBitmap, normalBitmap] = await Promise.all([
            worker.generate('ceiling_popcorn', {
                width: 512, height: 512,
                color: '#E8E6D0', bumpDensity: 14, bumpHeight: 1.4, detailScale: 5,
            }),
            worker.generate('ceiling_popcorn_normal', {
                width: 512, height: 512,
                bumpDensity: 14, detailScale: 5, strength: 20,
            }),
        ])
        const diffuse = this.bitmapToTexture(diffuseBitmap, 6, 6)
        const normal  = this.bitmapToTexture(normalBitmap, 6, 6)

        FrameBudgetScheduler.getInstance().schedule(
            () => this.upsertMaterial(MaterialType.Ceiling,
                new THREE.MeshStandardMaterial({
                    map: diffuse, normalMap: normal,
                    roughness: 0.95, metalness: 0.0,
                })),
            { priority: 'normal', estimatedMs: 2, maxDeferMs: 0 }
        )
    }

    private async prewarmWallWood(worker: ProceduralTextureWorker): Promise<void> {
        const [d, n] = await Promise.all([
            worker.generate('wood_planks', {
                width: 1024, height: 1024,
                numPlanks: 4,
                grainFrequency: 1.2,
                grainStrength: 0.12,
                baseColors: ['#7B3F10', '#8B4A14', '#9B5520', '#A8622A', '#8C4A18', '#955218'],
                edgeColor: '#5C2F0A',
            }),
            worker.generate('wood_normal', { width: 1024, height: 1024, strength: 0.3 }),
        ])
        // Texture Y = plank bands. Rotated 90deg so planks run vertically on wall.
        // repeat(1, 12): 1 tile per ceiling height, 12 tiles across wall width (~0.55m per plank width).
        const diffuse = this.bitmapToTexture(d, 1, 12)
        const normal  = this.bitmapToTexture(n, 1, 12)
        diffuse.rotation = Math.PI / 2
        normal.rotation  = Math.PI / 2
        diffuse.center.set(0.5, 0.5)
        normal.center.set(0.5, 0.5)

        FrameBudgetScheduler.getInstance().schedule(
            () => this.upsertMaterial(MaterialType.WallWood,
                new THREE.MeshStandardMaterial({
                    map: diffuse,
                    normalMap: normal,
                    roughness: 0.8, metalness: 0.1,
                })),
            { priority: 'normal', estimatedMs: 2, maxDeferMs: 0 }
        )
    }

    private async prewarmBasicWood(worker: ProceduralTextureWorker): Promise<void> {
        const [d, n] = await Promise.all([
            worker.generate('wood_enhanced', {
                width: 1024, height: 1024, grainStrength: 0.3, ringFrequency: 0.08,
                color1: '#8B4513', color2: '#A0522D', color3: '#654321',
            }),
            worker.generate('wood_normal', { width: 1024, height: 1024, strength: 0.18 }),
        ])
        const diffuse = this.bitmapToTexture(d, 3, 1)
        const normal  = this.bitmapToTexture(n, 3, 1)

        FrameBudgetScheduler.getInstance().schedule(
            () => this.upsertMaterial(MaterialType.BasicWood,
                new THREE.MeshStandardMaterial({
                    map: diffuse,
                    normalMap: normal,
                    roughness: 0.8, metalness: 0.1,
                })),
            { priority: 'normal', estimatedMs: 2, maxDeferMs: 0 }
        )
    }

    /** Wrap an ImageBitmap in a repeating THREE.Texture. */
    private bitmapToTexture(bitmap: ImageBitmap, repeatX: number, repeatY: number): THREE.Texture {
        const texture = new THREE.Texture(bitmap)
        texture.wrapS = texture.wrapT = THREE.RepeatWrapping
        texture.repeat.set(repeatX, repeatY)
        texture.needsUpdate = true
        return texture
    }

    /**
     * Insert or upgrade a pooled material.
     *
     * Critical behavior: if a fallback material is already in use by live meshes,
     * mutate that same material instance instead of replacing the object reference.
     * This allows textured prewarm results to "pop in" without rebuilding meshes.
     */
    private upsertMaterial(type: MaterialType, material: THREE.MeshStandardMaterial): void {
        const existing = this.materialPool!.materials.get(type)

        if (!existing) {
            this.materialPool!.materials.set(type, material)
            SharedMaterialManager.logger.debug(`Γ£à Inserted material ${type} (first use)`)
            return
        }

        // Dispose old GPU textures on the existing material before swapping properties.
        if (existing.map) existing.map.dispose()
        if (existing.normalMap) existing.normalMap.dispose()

        // Transfer core PBR properties to preserve object identity for all meshes
        // currently referencing this material instance.
        existing.color.copy(material.color)
        existing.emissive.copy(material.emissive)
        existing.emissiveIntensity = material.emissiveIntensity
        existing.roughness = material.roughness
        existing.metalness = material.metalness
        existing.transparent = material.transparent
        existing.opacity = material.opacity
        existing.side = material.side
        existing.map = material.map
        existing.normalMap = material.normalMap
        existing.name = material.name
        existing.needsUpdate = true

        // Avoid double-disposing transferred textures.
        material.map = null
        material.normalMap = null

        SharedMaterialManager.logger.debug(`≡ƒÄ¿ Upserted material ${type} ΓÇö needsUpdate set, GPU upload on next render`)
        material.dispose()
    }

    // ΓöÇΓöÇΓöÇ Sync fallback (instant, no canvas work) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    /**
     * Synchronous material creation ΓÇö called by getMaterial() when the cache
     * is cold (prewarm() not yet awaited). Procedural types will block here.
     */
    private createMaterialSync(type: MaterialType): THREE.MeshStandardMaterial {
        switch (type) {
            case MaterialType.FallbackGameBox:
                return new THREE.MeshStandardMaterial({
                    color: 0xff00ff, roughness: 0.8, metalness: 0.2,
                    name: 'fallback-gamebox-material',
                })
            case MaterialType.ShelfInterior:
                return MaterialUtils.createPBRMaterial({ color: 0xf8f8f8, roughness: 0.2, metalness: 0.0 })
            case MaterialType.BrandAccent:
                return MaterialUtils.createPBRMaterial({ color: 0x0066cc, roughness: 0.3, metalness: 0.1 })
            case MaterialType.Glass:
                return new THREE.MeshStandardMaterial({
                    color: 0xCCF5FF, emissive: 0xFFE4B5, emissiveIntensity: 0.375,
                    roughness: 0.1, metalness: 0.0, transparent: true, opacity: 0.35,
                    side: THREE.DoubleSide,
                })
            // Procedural types ΓÇö generate synchronously as fallback (slow, avoidable via prewarm)
            case MaterialType.MdfVeneer:
            case MaterialType.Carpet:
            case MaterialType.Ceiling:
            case MaterialType.WallWood:
            case MaterialType.BasicWood:
                SharedMaterialManager.logger.debug(
                    `getMaterial(${type}) called before prewarm() ΓÇö returning flat-color fallback (prewarm not yet complete)`
                )
                return this.createProceduralFallback(type)
            default:
                throw new Error(`Unknown material type: ${type}`)
        }
    }

    /**
     * Sync fallback for procedural materials when prewarm() wasn't awaited.
     * Creates a flat-colour approximation ΓÇö visually imperfect but non-blocking fast.
     */
    private createProceduralFallback(type: MaterialType): THREE.MeshStandardMaterial {
        const FALLBACK_COLORS: Record<string, number> = {
            [MaterialType.MdfVeneer]: 0xE6D3B7,
            [MaterialType.Carpet]:    0x8B0000,
            [MaterialType.Ceiling]:   0xF5F5DC,
            [MaterialType.WallWood]:  0x8B4513,
            [MaterialType.BasicWood]: 0x8B4513,
        }
        return new THREE.MeshStandardMaterial({
            color:     FALLBACK_COLORS[type] ?? 0x888888,
            roughness: 0.8,
            metalness: 0.0,
            name:      `${type}-sync-fallback`,
        })
    }
}

/**
 * Startup Event Tracker
 *
 * Tracks and logs all events during application startup to help understand:
 * - The order of initialization events
 * - Timing between events (comparative)
 * - Total time for each phase
 * - Dependencies and bottlenecks
 *
 * Emits AppEventTypes.PhaseCompleted via EventManager so that UI (StartupProgressUI)
 * can react without being directly coupled to this tracker.
 *
 * Also runs a requestAnimationFrame hitch detector from the first blocking phase
 * (CoreInit) through StartupComplete. If the gap between two rAF ticks exceeds
 * 100ms the tracker logs "Main Thread Hitch Detected: Xms" ΓÇö intentionally
 * formatted so that our Playwright console-capture tests can find it.
 * The detector stays alive through async encores (PrewarmEncore, PostSetupEncore)
 * because those run off-thread work that can still hitch the main thread, and stops
 * only when StartupComplete fires.
 */

import { EventManager } from '../core/EventManager'
import {
    AppEventTypes,
    type PhaseCompletedEvent,
    type MilestoneEvent,
    type DetailUpdateEvent,
    type GameLoadingStartedEvent,
    type GameLoadingPhaseChangedEvent,
    type GameLoadingProgressEvent,
    StorePropsEventTypes,
    SteamEventTypes,
    GameEventTypes,
    type StorePropsProgressEvent,
    type SteamGamesBatchEvent,
    type SteamNetworkFetchProgressEvent
} from '../types/InteractionEvents'

// Use window.performance for browser environment - globally accessible
const getPerformanceNow = (): number => {
    if (typeof window !== 'undefined' && window.performance) {
        return window.performance.now()
    }
    return Date.now()
}

// ---------------------------------------------------------------------------
// Phase enum ΓÇö aligned to the 5-phase startup architecture doc
// ---------------------------------------------------------------------------

export enum StartupPhase {
    // Blocking startup phases (rAF hitch detector runs during these)
    CoreInit       = 'CoreInit',
    EngineStart    = 'EngineStart',
    WorldBuild     = 'WorldBuild',
    ControlsReady  = 'ControlsReady',
    Interactive    = 'Interactive',

    // Post-interactive async encores
    PrewarmEncore    = 'PrewarmEncore',
    PostSetupEncore  = 'PostSetupEncore',
}

// Phases considered "blocking" for the purpose of hitch detection.
const BLOCKING_PHASES = new Set<StartupPhase>([
    StartupPhase.CoreInit,
    StartupPhase.EngineStart,
    StartupPhase.WorldBuild,
    StartupPhase.ControlsReady,
    StartupPhase.Interactive,
])

// ---------------------------------------------------------------------------
// Threshold warnings
// ---------------------------------------------------------------------------

/** If a phase exceeds `warn` ms log console.warn; if it exceeds `error` ms log console.error. */
const PHASE_THRESHOLDS_MS: Partial<Record<StartupPhase, { warn: number; error: number }>> = {
    [StartupPhase.CoreInit]:      { warn: 50,   error: 200 },
    [StartupPhase.EngineStart]:   { warn: 500,  error: 1000 },
    [StartupPhase.WorldBuild]:    { warn: 2000, error: 5000 },
    [StartupPhase.ControlsReady]: { warn: 100,  error: 500 },
    [StartupPhase.Interactive]:   { warn: 200,  error: 1000 },
}

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

interface StartupEvent {
    phase: StartupPhase
    timestamp: number
    description: string
    metadata?: Record<string, unknown>
}

interface PhaseMetrics {
    startTime: number
    endTime?: number
    duration?: number
    events: StartupEvent[]
}

// ---------------------------------------------------------------------------
// StartupEventTracker
// ---------------------------------------------------------------------------

export class StartupEventTracker {
    private static instance: StartupEventTracker

    private events: StartupEvent[] = []
    private phases = new Map<StartupPhase, PhaseMetrics>()
    private startTime: number

    private _enabled: boolean = true
    public get enabled(): boolean { return this._enabled }
    public set enabled(value: boolean) { this._enabled = !!value }

    // Game loading progress tracking (for PostSetupEncore)
    private totalGames = 0
    private loadedGames = 0
    private cachedBatchesComplete = false
    private fetchingInProgress = false

    private readonly CACHED_BATCH_THRESHOLD = 0.9
    private readonly COMPLETION_DELAY_MS = 300

    // rAF hitch detector state
    private hitchDetectorActive = false
    private lastRafTime = 0
    private rafHandle: number | null = null
    private readonly HITCH_THRESHOLD_MS = 100

    // Track how many blocking phases are currently open
    private activeBlockingPhaseCount = 0

    private constructor() {
        const windowWithStartTime = window as Window & { __APP_START_TIME?: number }
        if (typeof window !== 'undefined' && windowWithStartTime.__APP_START_TIME !== undefined) {
            this.startTime = windowWithStartTime.__APP_START_TIME
        } else {
            this.startTime = getPerformanceNow()
        }
    }

    public static getInstance(): StartupEventTracker {
        if (!StartupEventTracker.instance) {
            StartupEventTracker.instance = new StartupEventTracker()
        }
        return StartupEventTracker.instance
    }

    // ---------------------------------------------------------------------------
    // Listener wiring (called once EventManager is available)
    // ---------------------------------------------------------------------------

    public setupProgressListeners(): void {
        const eventManager = EventManager.getInstance()

        eventManager.registerEventHandler(StorePropsEventTypes.Progress, this.handleStorePropsProgress.bind(this))
        eventManager.registerEventHandler(SteamEventTypes.GamesBatchReady, this.handleGamesBatchReady.bind(this))
        eventManager.registerEventHandler(SteamEventTypes.NetworkFetchProgress, this.handleNetworkFetchProgress.bind(this))
        eventManager.registerEventHandler(GameEventTypes.AllBatchesComplete, this.handleAllBatchesComplete.bind(this))
    }

    private handleStorePropsProgress(event: CustomEvent<StorePropsProgressEvent>): void {
        if (event.detail.detail) {
            EventManager.getInstance().emit<DetailUpdateEvent>(AppEventTypes.DetailUpdate, { detail: event.detail.detail })
        }
    }

    private handleGamesBatchReady(event: CustomEvent<SteamGamesBatchEvent>): void {
        const { games, batchIndex, totalBatches } = event.detail
        this.loadedGames += games.length

        if (batchIndex === 0) {
            this.totalGames = totalBatches * games.length
            EventManager.getInstance().emit<GameLoadingStartedEvent>(AppEventTypes.GameLoadingStarted, {
                totalGames: this.totalGames,
                phase: StartupPhase.PostSetupEncore
            })
        }

        const estimatedCachedBatches = Math.floor(totalBatches * this.CACHED_BATCH_THRESHOLD)
        if (batchIndex >= estimatedCachedBatches && !this.cachedBatchesComplete) {
            this.cachedBatchesComplete = true
            this.fetchingInProgress = true
            EventManager.getInstance().emit<GameLoadingPhaseChangedEvent>(AppEventTypes.GameLoadingPhaseChanged, {
                loadingPhase: 'fetch',
                detail: 'Fetching new game metadata from Steam...'
            })
        }

        if (!this.cachedBatchesComplete) {
            EventManager.getInstance().emit<GameLoadingPhaseChangedEvent>(AppEventTypes.GameLoadingPhaseChanged, {
                loadingPhase: 'cache',
                detail: `Loading cached games (${this.loadedGames}/${this.totalGames})...`
            })
        } else if (this.fetchingInProgress) {
            EventManager.getInstance().emit<GameLoadingPhaseChangedEvent>(AppEventTypes.GameLoadingPhaseChanged, {
                loadingPhase: 'fetch',
                detail: `Fetching ${totalBatches - batchIndex} remaining games from Steam...`
            })
            this.fetchingInProgress = batchIndex < totalBatches - 1
        }

        EventManager.getInstance().emit<GameLoadingProgressEvent>(AppEventTypes.GameLoadingProgress, {
            current: this.loadedGames,
            total: this.totalGames
        })
    }

    private handleNetworkFetchProgress(event: CustomEvent<SteamNetworkFetchProgressEvent>): void {
        const { fetched, total } = event.detail
        EventManager.getInstance().emit<GameLoadingPhaseChangedEvent>(AppEventTypes.GameLoadingPhaseChanged, {
            loadingPhase: 'fetch',
            detail: `Waiting for Steam API (${fetched}/${total} games)...`
        })
    }

    private handleAllBatchesComplete(): void {
        EventManager.getInstance().emit<GameLoadingProgressEvent>(AppEventTypes.GameLoadingProgress, {
            current: this.totalGames,
            total: this.totalGames
        })
        setTimeout(() => {
            EventManager.getInstance().emit(AppEventTypes.StartupComplete, {})
        // Stop hitch detector at true startup completion ΓÇö encores may have been hitching
        this.stopHitchDetector()
        }, this.COMPLETION_DELAY_MS)
    }

    // ---------------------------------------------------------------------------
    // Phase lifecycle
    // ---------------------------------------------------------------------------

    public phaseStart(phase: StartupPhase, description?: string): void {
        if (!this.enabled) return

        const timestamp = getPerformanceNow()
        this.phases.set(phase, { startTime: timestamp, events: [] })

        const desc = description || `Starting ${phase}`
        this.logEvent(phase, desc)

        // Start hitch detector when first blocking phase begins
        if (BLOCKING_PHASES.has(phase)) {
            this.activeBlockingPhaseCount++
            if (!this.hitchDetectorActive) {
                this.startHitchDetector()
            }
        }

        // Notify UI via EventManager
        EventManager.getInstance().emit<PhaseCompletedEvent>(AppEventTypes.PhaseStarted, {
            phase,
            timestamp,
            duration: 0
        })
    }

    public phaseEnd(phase: StartupPhase, description?: string): void {
        if (!this.enabled) return

        const timestamp = getPerformanceNow()
        const phaseMetrics = this.phases.get(phase)

        if (phaseMetrics) {
            phaseMetrics.endTime = timestamp
            phaseMetrics.duration = timestamp - phaseMetrics.startTime

            const desc = description || `Completed ${phase}`
            this.logEvent(phase, desc, { duration: phaseMetrics.duration })

            // Threshold warnings
            const thresholds = PHASE_THRESHOLDS_MS[phase]
            if (thresholds) {
                if (phaseMetrics.duration >= thresholds.error) {
                    console.error(`[StartupTracker] Phase ${phase} took ${phaseMetrics.duration.toFixed(0)}ms (threshold: ${thresholds.error}ms error)`)
                } else if (phaseMetrics.duration >= thresholds.warn) {
                    console.warn(`[StartupTracker] Phase ${phase} took ${phaseMetrics.duration.toFixed(0)}ms (threshold: ${thresholds.warn}ms warn)`)
                }
            }

            // Notify UI via EventManager
            EventManager.getInstance().emit<PhaseCompletedEvent>(AppEventTypes.PhaseCompleted, {
                phase,
                timestamp,
                duration: phaseMetrics.duration
            })
        }

        // Stop hitch detector when all *blocking* phases are done as a fallback.
        // The primary stop is driven by StartupComplete (see handleAllBatchesComplete).
        // This fallback catches edge cases where StartupComplete never fires (e.g. no games loaded).
        if (BLOCKING_PHASES.has(phase)) {
            this.activeBlockingPhaseCount = Math.max(0, this.activeBlockingPhaseCount - 1)
            if (this.activeBlockingPhaseCount === 0) {
                this.stopHitchDetector()
            }
        }
    }

    // ---------------------------------------------------------------------------
    // rAF hitch detector
    // ---------------------------------------------------------------------------

    private startHitchDetector(): void {
        if (typeof requestAnimationFrame === 'undefined') return
        this.hitchDetectorActive = true
        this.lastRafTime = getPerformanceNow()
        this.scheduleRafTick()
    }

    private scheduleRafTick(): void {
        if (!this.hitchDetectorActive) return
        this.rafHandle = requestAnimationFrame(() => {
            if (!this.hitchDetectorActive) return
            const now = getPerformanceNow()
            const gap = now - this.lastRafTime
            if (gap > this.HITCH_THRESHOLD_MS) {
                console.warn(`Main Thread Hitch Detected: ${gap.toFixed(0)}ms`)
            }
            this.lastRafTime = now
            this.scheduleRafTick()
        })
    }

    private stopHitchDetector(): void {
        this.hitchDetectorActive = false
        if (this.rafHandle !== null && typeof cancelAnimationFrame !== 'undefined') {
            cancelAnimationFrame(this.rafHandle)
            this.rafHandle = null
        }
    }

    // ---------------------------------------------------------------------------
    // Event helpers
    // ---------------------------------------------------------------------------

    public logEvent(phase: StartupPhase, description: string, metadata?: Record<string, unknown>): void {
        if (!this.enabled) return

        const timestamp = getPerformanceNow()
        const event: StartupEvent = { phase, timestamp, description, metadata }

        this.events.push(event)
        const phaseMetrics = this.phases.get(phase)
        if (phaseMetrics) {
            phaseMetrics.events.push(event)
        }
    }

    public logAsyncStart(phase: StartupPhase, operation: string): number {
        if (!this.enabled) return 0
        const timestamp = getPerformanceNow()
        this.logEvent(phase, `${operation} (started)`)
        return timestamp
    }

    public logAsyncEnd(phase: StartupPhase, operation: string, startTimestamp: number): void {
        if (!this.enabled) return
        const timestamp = getPerformanceNow()
        const duration = timestamp - startTimestamp
        this.logEvent(phase, `${operation} (completed)`, { duration })
    }

    public milestone(phase: StartupPhase, description: string, metadata?: Record<string, unknown>): void {
        if (!this.enabled) return
        this.logEvent(phase, `MILESTONE: ${description}`, metadata)
        EventManager.getInstance().emit<MilestoneEvent>(AppEventTypes.Milestone, { description })
    }

    // ---------------------------------------------------------------------------
    // Summary
    // ---------------------------------------------------------------------------

    public getSummary(): {
        totalTime: number
        phases: Array<{ phase: StartupPhase; duration: number; eventCount: number }>
        events: StartupEvent[]
    } {
        const totalTime = getPerformanceNow() - this.startTime
        const phaseSummary = Array.from(this.phases.entries()).map(([phase, metrics]) => ({
            phase,
            duration: metrics.duration || 0,
            eventCount: metrics.events.length
        }))
        return { totalTime, phases: phaseSummary, events: this.events }
    }

    public printSummary(): void {
        const summary = this.getSummary()
        console.log(`\n≡ƒôè Startup complete: ${summary.totalTime.toFixed(0)}ms`)
        console.table(
            summary.phases.map(p => ({
                phase: p.phase,
                'duration (ms)': p.duration.toFixed(0),
                events: p.eventCount
            }))
        )
    }
}

/**
 * Steam error message utilities for providing clear, contextual feedback to users
 */

export interface SteamErrorContext {
    userInput: string
    parsedInputType: 'steamid' | 'customurl'
    parsedInputValue: string
    errorType: 'vanity_not_found' | 'steamid_invalid' | 'api_error' | 'network_error' | 'unknown'
    originalError?: Error
}

export class SteamErrorMessages {
    /**
     * Generate a user-friendly error message with specific guidance based on the input and error context
     */
    static generateErrorMessage(context: SteamErrorContext): string {
        const { userInput, parsedInputType, parsedInputValue, errorType } = context

        // Base explanation of what was attempted
        const attemptedFormat = parsedInputType === 'steamid' 
            ? `SteamID "${parsedInputValue}"`
            : `custom URL "${parsedInputValue}"`

        switch (errorType) {
            case 'vanity_not_found':
                if (parsedInputType === 'customurl') {
                    return this.buildCustomUrlNotFoundMessage(userInput, parsedInputValue)
                } else {
                    return `Γ¥î SteamID "${parsedInputValue}" was not found. Please verify the 17-digit SteamID is correct.`
                }

            case 'steamid_invalid':
                return this.buildInvalidSteamIdMessage(userInput, parsedInputValue)

            case 'api_error':
                return `Γ¥î Steam API error occurred while looking up ${attemptedFormat}. Please try again in a moment.`

            case 'network_error':
                return `Γ¥î Network error while contacting Steam. Please check your connection and try again.`

            case 'unknown':
            default:
                return this.buildGenericErrorWithGuidance(userInput, parsedInputType)
        }
    }

    private static buildCustomUrlNotFoundMessage(originalInput: string, parsedValue: string): string {
        const baseMessage = `Γ¥î Custom URL "${parsedValue}" was not found.`
        
        // Common bullet points for all scenarios
        const commonOptions = this.getCommonInputOptions()
        
        // Provide specific guidance based on the input format
        if (originalInput === parsedValue) {
            // User entered just the custom URL part (e.g., "moodchanging")
            return `${baseMessage}<br><br>This might be a display name rather than a custom URL. Please try one of these instead:<br>${commonOptions}`
        } else {
            // User entered a URL that we parsed
            return `${baseMessage}<br><br>Please verify the custom URL is correct, or try:<br>${commonOptions}`
        }
    }

    private static buildInvalidSteamIdMessage(originalInput: string, parsedValue: string): string {
        const commonOptions = this.getCommonInputOptions()
        return `Γ¥î "${parsedValue}" is not a valid SteamID.<br><br>SteamIDs must be 17-digit numbers. Please try:<br>${commonOptions}`
    }

    private static buildGenericErrorWithGuidance(originalInput: string, inputType: 'steamid' | 'customurl'): string {
        const inputTypeDesc = inputType === 'steamid' ? 'SteamID' : 'custom URL'
        const commonOptions = this.getCommonInputOptions()
        
        return `Γ¥î Unable to load games using "${originalInput}" as a ${inputTypeDesc}.<br><br>Please try one of these formats:<br>${commonOptions}`
    }

    /**
     * Determine error type from the error message or error object
     */
    static categorizeError(error: Error): SteamErrorContext['errorType'] {
        const message = error.message.toLowerCase()
        
        if (message.includes('vanity url not found') || message.includes('not found')) {
            return 'vanity_not_found'
        }
        
        if (message.includes('invalid steamid') || message.includes('steamid')) {
            return 'steamid_invalid'
        }
        
        if (message.includes('network') || message.includes('connection')) {
            return 'network_error'
        }
        
        if (message.includes('api') || message.includes('server')) {
            return 'api_error'
        }
        
        return 'unknown'
    }

    /**
     * Get common input options as HTML formatted bullet points
     */
    private static getCommonInputOptions(): string {
        return `ΓÇó Your SteamID (17-digit number): e.g., 76561197960287930<br>
ΓÇó Your full profile URL: steamcommunity.com/profiles/[YourSteamID]<br>
ΓÇó Your custom URL (if you've set one): steamcommunity.com/id/[YourCustomURL]`
    }

    /**
     * Helper to extract meaningful guidance for display names vs custom URLs
     */
    static getDisplayNameGuidance(): string {
        return `≡ƒÆí Tip: Display names (what others see) are different from custom URLs.<br>
To find your SteamID or custom URL:<br>
1. Go to your Steam profile<br>
2. Right-click ΓåÆ "Copy Profile URL"<br>
3. Use that URL here, or extract the number/name from it`
    }
}

/**
 * System Capabilities Detection
 * 
 * Simple utilities for detecting system capabilities that handlers can use
 * to decide whether to register as replacement handlers.
 * 
 * Used by handlers for self-registration logic, NOT by the event system.
 */

import { Logger } from '../utils/Logger'

export interface SystemCapabilities {
    hasWebGL2: boolean
    hasInstancedArrays: boolean
    hasHardwareRenderer: boolean
    supportsLargeTextures: boolean
    hasGoodGPU: boolean // Deprecated: use hasHardwareRenderer && supportsLargeTextures
    maxTextureSize: number
    renderer: string
    /** True when KHR_parallel_shader_compile is available ΓÇö compileAsync() is non-blocking */
    hasParallelShaderCompile: boolean
    // TODO: Add more capabilities as needed:
    // TODO: - hasVertexArrayObjects: boolean
    // TODO: - hasFloatTextures: boolean  
    // TODO: - maxDrawBuffers: number
    // TODO: - hasVR: boolean
}

export class SystemCapabilitiesDetector {
    private static readonly logger = Logger.createLogFunctions(SystemCapabilitiesDetector.name)
    private static cachedCapabilities: SystemCapabilities | null = null
    private static readonly LARGE_TEXTURE_THRESHOLD = 4096

    /**
     * Detect system capabilities (cached after first call)
     */
    public static detect(): SystemCapabilities {
        if (SystemCapabilitiesDetector.cachedCapabilities) {
            return SystemCapabilitiesDetector.cachedCapabilities
        }

        const capabilities = SystemCapabilitiesDetector.detectCapabilities()
        SystemCapabilitiesDetector.cachedCapabilities = capabilities

        SystemCapabilitiesDetector.logger.debug('System capabilities detected:', capabilities)
        return capabilities
    }

    /**
     * Force re-detection of capabilities (for testing or dynamic changes)
     */
    public static redetect(): SystemCapabilities {
        SystemCapabilitiesDetector.cachedCapabilities = null
        return SystemCapabilitiesDetector.detect()
    }

    private static detectCapabilities(): SystemCapabilities {
        // Create a test canvas to check WebGL capabilities
        const canvas = document.createElement('canvas')
        const gl = canvas.getContext('webgl2')
        const gl1 = canvas.getContext('webgl')

        const hasWebGL2 = !!gl
        const hasInstancedArrays = hasWebGL2 || !!(gl1 && typeof gl1.getExtension === 'function' && gl1.getExtension('ANGLE_instanced_arrays'))

        let maxTextureSize = 0
        let renderer = 'unknown'
        let hasHardwareRenderer = false
        let supportsLargeTextures = false
        let hasGoodGPU = false
        let hasParallelShaderCompile = false

        const context = gl || gl1
        if (context) {
            const canQueryParameters = typeof context.getParameter === 'function'
            const canGetExtensions = typeof context.getExtension === 'function'
            if (!canQueryParameters || !canGetExtensions) {
                SystemCapabilitiesDetector.logger.warn('WebGL context missing expected query APIs; using conservative capability defaults')
            }

            maxTextureSize = SystemCapabilitiesDetector.readMaxTextureSize(context, canQueryParameters)
            renderer = SystemCapabilitiesDetector.readRenderer(context, canQueryParameters, canGetExtensions)

            // KHR_parallel_shader_compile ΓÇö when present, compileAsync() offloads shader linking
            // to the driver background thread and resolves without blocking the main thread.
            hasParallelShaderCompile = canGetExtensions && !!context.getExtension('KHR_parallel_shader_compile')

            // TODO: Validate this heuristic with real-world telemetry once the app reaches a broader user base.
            // For now, keep current behavior to avoid changing handler selection semantics.
            hasHardwareRenderer = !renderer.toLowerCase().includes('software')
            supportsLargeTextures = maxTextureSize >= SystemCapabilitiesDetector.LARGE_TEXTURE_THRESHOLD

            SystemCapabilitiesDetector.logUnknownRendererMetrics(renderer, {
                hasWebGL2,
                hasInstancedArrays,
                maxTextureSize
            })

            // Legacy compatibility: "good GPU" means both hardware renderer and large textures
            hasGoodGPU = hasHardwareRenderer && supportsLargeTextures
        }

        // Clean up test canvas
        canvas.remove()

        return {
            hasWebGL2,
            hasInstancedArrays,
            hasHardwareRenderer,
            supportsLargeTextures,
            hasGoodGPU,
            maxTextureSize,
            renderer,
            hasParallelShaderCompile
        }
    }

    private static readMaxTextureSize(
        context: WebGLRenderingContext | WebGL2RenderingContext,
        canQueryParameters: boolean
    ): number {
        if (!canQueryParameters || context.MAX_TEXTURE_SIZE === undefined) {
            return 0
        }

        return context.getParameter(context.MAX_TEXTURE_SIZE)
    }

    private static readRenderer(
        context: WebGLRenderingContext | WebGL2RenderingContext,
        canQueryParameters: boolean,
        canGetExtensions: boolean
    ): string {
        if (!canGetExtensions || !canQueryParameters) {
            return 'unknown'
        }

        const debugInfo = context.getExtension('WEBGL_debug_renderer_info')
        if (!debugInfo) {
            return 'unknown'
        }

        return context.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL) ?? 'unknown'
    }

    private static logUnknownRendererMetrics(
        renderer: string,
        details: { hasWebGL2: boolean; hasInstancedArrays: boolean; maxTextureSize: number }
    ): void {
        if (renderer !== 'unknown') {
            return
        }

        SystemCapabilitiesDetector.logger.debug('Renderer reported as unknown; tracking values for future heuristic tuning', details)
    }

    /**
     * Check if system meets specific capability requirements
     */
    public static meetsRequirements(requirements: Partial<SystemCapabilities>): boolean {
        const capabilities = SystemCapabilitiesDetector.detect()

        for (const [key, requiredValue] of Object.entries(requirements)) {
            const actualValue = capabilities[key as keyof SystemCapabilities]

            if (typeof requiredValue === 'boolean' && actualValue !== requiredValue) {
                return false
            }

            if (typeof requiredValue === 'number' && (actualValue as number) < requiredValue) {
                return false
            }
        }

        return true
    }
}

// Convenience functions for common capability checks
export const hasWebGL2 = (): boolean => SystemCapabilitiesDetector.detect().hasWebGL2
export const hasInstancedArrays = (): boolean => SystemCapabilitiesDetector.detect().hasInstancedArrays
export const hasHardwareRenderer = (): boolean => SystemCapabilitiesDetector.detect().hasHardwareRenderer
export const supportsLargeTextures = (): boolean => SystemCapabilitiesDetector.detect().supportsLargeTextures
export const hasGoodGPU = (): boolean => SystemCapabilitiesDetector.detect().hasGoodGPU
export const hasParallelShaderCompile = (): boolean => SystemCapabilitiesDetector.detect().hasParallelShaderCompile

// Export the detection function for convenience
export const detectSystemCapabilities = SystemCapabilitiesDetector.detect

/**
 * Simple template utility for HTML templates with dynamic value interpolation
 */

export interface TemplateValues {
    [key: string]: string | number | boolean | undefined
}

/**
 * Replace template placeholders with actual values
 * Supports:
 * - {{value}} - simple interpolation
 * - {{#if condition}}content{{/if}} - conditional blocks
 * - {{#if condition}}content{{else}}alternative{{/if}} - conditional with else
 * - {{#selected value}}selected{{/selected}} - selected attribute helper
 * - {{#checked value}}checked{{/checked}} - checked attribute helper
 */
export function interpolateTemplate(template: string, values: TemplateValues): string {
    let result = template

    // Handle conditional blocks with else FIRST: {{#if condition}}content{{else}}alternative{{/if}}
    result = result.replace(/\{\{#if\s+(\w+)\s*\}\}([\s\S]*?)\{\{else\}\}([\s\S]*?)\{\{\/if\}\}/g, (match, key, ifContent, elseContent) => {
        const value = values[key]
        return value ? (ifContent || '') : (elseContent || '')
    })

    // Handle conditional blocks without else: {{#if condition}}content{{/if}}
    result = result.replace(/\{\{#if\s+(\w+)\s*\}\}([\s\S]*?)\{\{\/if\}\}/g, (match, key, content) => {
        const value = values[key]
        return value ? (content || '') : ''
    })

    // Handle selected attribute helper {{#selected value}}selected{{/selected}}
    result = result.replace(/\{\{#selected\s+(\w+)\}\}([\s\S]*?)\{\{\/selected\}\}/g, (match, key, content) => {
        const value = values[key]
        return value ? content : ''
    })

    // Handle checked attribute helper {{#checked value}}checked{{/checked}}
    result = result.replace(/\{\{#checked\s+(\w+)\}\}([\s\S]*?)\{\{\/checked\}\}/g, (match, key, content) => {
        const value = values[key]
        return value ? content : ''
    })

    // Handle simple interpolation LAST: {{value}}
    result = result.replace(/\{\{(\w+)\}\}/g, (match, key) => {
        const value = values[key]
        return value !== undefined ? String(value) : ''
    })

    return result
}

/**
 * Load and interpolate a template
 */
export function renderTemplate(template: string, values: TemplateValues): string {
    return interpolateTemplate(template, values)
}

/**
 * Declarative UI component configuration utilities
 * 
 * Reduces 30-60 lines of repetitive DOM event handling per panel to ~10-20 lines
 * of type-safe configuration objects.
 * 
 * Pattern: Use .bind(this) for direct method references, arrow functions for logic blocks.
 * 
 * @example Basic slider with live value display
 * UIComponentUtils.setupSlider(container, {
 *   sliderId: 'fov',
 *   valueDisplayId: 'fov-value',
 *   formatDisplay: (v) => v + '┬░',
 *   onChange: (v) => { camera.fov = v; camera.updateProjectionMatrix() }
 * })
 * 
 * @example Button with bound method (preferred for simple calls)
 * UIComponentUtils.setupButton(container, {
 *   buttonId: 'reset-btn',
 *   onClick: this.resetToDefaults.bind(this)
 * })
 * 
 * @example Preset buttons using data attributes
 * UIComponentUtils.setupDataButtons(container, '[data-preset]', 'preset',
 *   (key: string) => this.applyPreset(PRESETS[key])
 * )
 */

export interface SliderConfig {
    sliderId: string
    valueDisplayId: string
    onInput?: (value: number) => void
    onChange?: (value: number) => void
    formatDisplay?: (value: number) => string
}

export interface ToggleConfig {
    toggleId: string
    onChange: (checked: boolean) => void
}

export interface ButtonConfig {
    buttonId: string
    onClick: () => void
}

export interface SelectConfig<T = string> {
    selectId: string
    onChange: (value: T) => void
    parseValue?: (rawValue: string) => T
}

export interface InputConfig<T = string> {
    inputId: string
    onChange: (value: T) => void
    parseValue?: (rawValue: string) => T
}

export class UIComponentUtils {
    static setupSlider(
        container: HTMLElement | null,
        config: SliderConfig
    ): void {
        if (!container) return

        const slider = container.querySelector(`#${config.sliderId}`) as HTMLInputElement
        const valueDisplay = container.querySelector(`#${config.valueDisplayId}`) as HTMLSpanElement

        if (!slider) return

        const updateDisplay = (value: number) => {
            if (valueDisplay) {
                valueDisplay.textContent = config.formatDisplay 
                    ? config.formatDisplay(value)
                    : value.toString()
            }
        }

        if (config.onInput) {
            slider.addEventListener('input', (e) => {
                const value = parseFloat((e.target as HTMLInputElement).value)
                updateDisplay(value)
                if (config.onInput) {
                    config.onInput(value)
                }
            })
        } else {
            slider.addEventListener('input', (e) => {
                const value = parseFloat((e.target as HTMLInputElement).value)
                updateDisplay(value)
            })
        }

        if (config.onChange) {
            slider.addEventListener('change', (e) => {
                const value = parseFloat((e.target as HTMLInputElement).value)
                if (config.onChange) {
                    config.onChange(value)
                }
            })
        }
    }

    static setupSliders(
        container: HTMLElement | null,
        configs: SliderConfig[]
    ): void {
        configs.forEach(config => this.setupSlider(container, config))
    }

    static setupToggle(
        container: HTMLElement | null,
        config: ToggleConfig
    ): void {
        if (!container) return

        const toggle = container.querySelector(`#${config.toggleId}`) as HTMLInputElement
        if (!toggle) return

        toggle.addEventListener('change', (e) => {
            config.onChange((e.target as HTMLInputElement).checked)
        })
    }

    static setupToggles(
        container: HTMLElement | null,
        configs: ToggleConfig[]
    ): void {
        configs.forEach(config => this.setupToggle(container, config))
    }

    static setupButton(
        container: HTMLElement | null,
        config: ButtonConfig
    ): void {
        if (!container) return

        const button = container.querySelector(`#${config.buttonId}`) as HTMLButtonElement
        if (!button) return

        button.addEventListener('click', config.onClick)
    }

    static setupButtons(
        container: HTMLElement | null,
        configs: ButtonConfig[]
    ): void {
        configs.forEach(config => this.setupButton(container, config))
    }

    /** Configure buttons using data attributes (useful for presets/dynamic groups) */
    static setupDataButtons<T = string>(
        container: HTMLElement | null,
        selector: string,
        dataAttribute: string,
        onClick: (value: T, button: HTMLElement) => void
    ): void {
        if (!container) return

        const buttons = container.querySelectorAll(selector)
        buttons.forEach(button => {
            const value = (button as HTMLElement).dataset[dataAttribute] as T
            if (value !== undefined) {
                button.addEventListener('click', () => {
                    onClick(value, button as HTMLElement)
                })
            }
        })
    }

    static setupSelect<T = string>(
        container: HTMLElement | null,
        config: SelectConfig<T>
    ): void {
        if (!container) return

        const select = container.querySelector(`#${config.selectId}`) as HTMLSelectElement
        if (!select) return

        select.addEventListener('change', (e) => {
            const rawValue = (e.target as HTMLSelectElement).value
            const value = config.parseValue ? config.parseValue(rawValue) : rawValue as T
            config.onChange(value)
        })
    }

    static setupSelects<T = string>(
        container: HTMLElement | null,
        configs: SelectConfig<T>[]
    ): void {
        configs.forEach(config => this.setupSelect(container, config))
    }

    static setupInput<T = string>(
        container: HTMLElement | null,
        config: InputConfig<T>
    ): void {
        if (!container) return

        const input = container.querySelector(`#${config.inputId}`) as HTMLInputElement
        if (!input) return

        input.addEventListener('change', (e) => {
            const rawValue = (e.target as HTMLInputElement).value
            const value = config.parseValue ? config.parseValue(rawValue) : rawValue as T
            config.onChange(value)
        })
    }

    static setupInputs<T = string>(
        container: HTMLElement | null,
        configs: InputConfig<T>[]
    ): void {
        configs.forEach(config => this.setupInput(container, config))
    }

    static updateSliderValue(
        container: HTMLElement | null,
        sliderId: string,
        valueDisplayId: string,
        value: number,
        formatDisplay?: (value: number) => string
    ): void {
        if (!container) return

        const slider = container.querySelector(`#${sliderId}`) as HTMLInputElement
        const valueDisplay = container.querySelector(`#${valueDisplayId}`) as HTMLSpanElement

        if (slider) {
            slider.value = value.toString()
        }

        if (valueDisplay) {
            valueDisplay.textContent = formatDisplay 
                ? formatDisplay(value)
                : value.toString()
        }
    }
}

/**
 * Input validation and parsing utilities
 */

export class ValidationUtils {
    /**
     * Parse Steam user input to determine the appropriate lookup method
     * 
     * Steam User Identification Mapping:
     * - steamID: Unique numeric identifier (e.g., 76561198054514251)
     * - Custom URL: User-chosen string for steamcommunity.com/id/<custom_url>
     * - Profile URL: Direct link using steamID steamcommunity.com/profiles/<steamid>
     * 
     * Supported input formats:
     * - Direct steamID: "76561198054514251"
     * - Direct custom URL: "SpiteMonger"
     * - Full custom URL: "https://steamcommunity.com/id/SpiteMonger"
     * - Partial custom URL: "steamcommunity.com/id/SpiteMonger"
     * - Profile URL: "https://steamcommunity.com/profiles/76561198054514251"
     * - Profile path: "/profiles/76561198054514251"
     */
    static parseSteamUserInput(input: string): { type: 'steamid' | 'customurl', value: string } {
        if (!input || typeof input !== 'string') {
            return { type: 'customurl', value: '' }
        }

        const trimmedInput = input.trim()
        if (!trimmedInput) {
            return { type: 'customurl', value: '' }
        }

        // Check for steamID in profile URL format
        const profileMatch = trimmedInput.match(/(?:steamcommunity\.com\/profiles\/|\/profiles\/)([0-9]{17})\/?/i)
        if (profileMatch) {
            return { type: 'steamid', value: profileMatch[1] }
        }

        // Check for direct steamID (17-digit number)
        if (/^[0-9]{17}$/.test(trimmedInput)) {
            return { type: 'steamid', value: trimmedInput }
        }

        // Check for custom URL in various formats
        const customUrlMatch = trimmedInput.match(/(?:steamcommunity\.com\/id\/|\/id\/)?([^/\s]+)\/?$/i)
        const customUrl = customUrlMatch ? customUrlMatch[1] : trimmedInput
        
        return { type: 'customurl', value: customUrl }
    }

    /**
     * @deprecated Use parseSteamUserInput instead. This method will be removed in a future version.
     */
    static extractVanityFromInput(input: string): string {
        const result = ValidationUtils.parseSteamUserInput(input)
        return result.value
    }

    /**
     * Validate that a string is not empty after trimming
     */
    static isNonEmptyString(value: string): boolean {
        return typeof value === 'string' && value.trim().length > 0
    }

    /**
     * Sanitize user input for display purposes
     */
    static sanitizeForDisplay(input: string): string {
        return input
            .replace(/[<>]/g, '') // Remove potential HTML tags
            .trim()
    }

    /**
     * Generate a consistent hue value (0-1) from a string for color generation
     */
    static stringToHue(str: string): number {
        if (!str || typeof str !== 'string') {
            return 0
        }

        let hash = 0
        for (let i = 0; i < str.length; i++) {
            hash = str.charCodeAt(i) + ((hash << 5) - hash)
        }
        return Math.abs(hash % 360) / 360
    }
}

import * as THREE from 'three'
import type { MaterialOptions, TextureLoadOptions } from './MaterialBase'

/**
 * Base class for material generators
 */
export abstract class BaseMaterialGenerator {
  protected materialCache: Map<string, THREE.Material> = new Map()

  /**
   * Get a cached material or create a new one
   */
  protected getCachedMaterial<T extends THREE.Material>(
    cacheKey: string, 
    createFn: () => T | Promise<T>
  ): T | Promise<T> {
    if (this.materialCache.has(cacheKey)) {
      return this.materialCache.get(cacheKey) as T
    }

    const result = createFn()
    
    if (result instanceof Promise) {
      return result.then(material => {
        this.materialCache.set(cacheKey, material)
        return material
      })
    } else {
      this.materialCache.set(cacheKey, result)
      return result
    }
  }

  /**
   * Apply common texture options
   */
  protected applyTextureOptions(texture: THREE.Texture, options: TextureLoadOptions): void {
    if (options.repeat) {
      texture.repeat.set(options.repeat.x, options.repeat.y)
    }
    
    if (options.anisotropy !== undefined) {
      texture.anisotropy = options.anisotropy
    }
    
    // Common VR optimizations
    texture.wrapS = THREE.RepeatWrapping
    texture.wrapT = THREE.RepeatWrapping
  }

  /**
   * Clear material cache to free memory
   */
  public clearCache(): void {
    this.materialCache.forEach(material => material.dispose())
    this.materialCache.clear()
  }

  /**
   * Get cache statistics
   */
  public getCacheStats(): { count: number; keys: string[] } {
    return {
      count: this.materialCache.size,
      keys: Array.from(this.materialCache.keys())
    }
  }

  /**
   * Abstract method to be implemented by subclasses
   */
  abstract createMaterial(options?: MaterialOptions): THREE.Material | Promise<THREE.Material>
}

import * as THREE from 'three'
import type { MaterialOptions } from './MaterialBase'
import { BaseMaterialGenerator } from './BaseMaterialGenerator'
import { TextureLoader } from './TextureLoader'
import { CarpetTextureGenerator } from '../textures/CarpetTextureGenerator'

export interface CarpetMaterialOptions extends MaterialOptions {
  diffuseUrl?: string
  normalUrl?: string
  color?: THREE.Color | string
  roughness?: number
  metalness?: number
}

export interface ProceduralCarpetMaterialOptions extends MaterialOptions {
  color?: string
  roughness?: number
  metalness?: number
}

export interface EnhancedProceduralCarpetMaterialOptions extends MaterialOptions {
  color?: string
  fiberDensity?: number
  roughness?: number
  metalness?: number
}

/**
 * Carpet material generator
 */
export class CarpetMaterialGenerator extends BaseMaterialGenerator {
  private textureLoader: TextureLoader
  private carpetTextureGenerator: CarpetTextureGenerator

  constructor() {
    super()
    this.textureLoader = TextureLoader.getInstance()
    this.carpetTextureGenerator = new CarpetTextureGenerator()
  }

  /**
   * Create a carpet material from texture files
   */
  public async createMaterial(options: CarpetMaterialOptions = {}): Promise<THREE.MeshStandardMaterial> {
    const {
      diffuseUrl,
      normalUrl,
      repeat = { x: 4, y: 4 },
      color = new THREE.Color(0x8B0000)
    } = options

    const colorStr = color instanceof THREE.Color ? `#${color.getHexString()}` : color
    const cacheKey = `carpet_${diffuseUrl || 'none'}_${normalUrl || 'none'}_${repeat.x}_${repeat.y}_${colorStr}`
    
    return this.getCachedMaterial(cacheKey, async () => {
      const material = new THREE.MeshStandardMaterial({
        color: color instanceof THREE.Color ? color : new THREE.Color(color),
