export const P: number[] = new Array(512)
for (let i = 0; i < 512; i++) P[i] = PERM_BASE[i & 255]

export function fade(t: number): number { return t * t * t * (t * (t * 6 - 15) + 10) }

export function lerp(t: number, a: number, b: number): number { return a + t * (b - a) }

export function grad(hash: number, x: number, y: number, z: number): number {
    const h = hash & 15
    const u = h < 8 ? x : y
    const v = h < 4 ? y : h === 12 || h === 14 ? x : z
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v)
}

export function noise2D(x: number, y: number): number {
    const X = Math.floor(x) & 255
    const Y = Math.floor(y) & 255
    const xf = x - Math.floor(x)
    const yf = y - Math.floor(y)
    const u = fade(xf)
    const v = fade(yf)
    const a = P[X] + Y
    const aa = P[a]; const ab = P[a + 1]
    const b = P[X + 1] + Y
    const ba = P[b]; const bb = P[b + 1]
    return lerp(v,
        lerp(u, grad(P[aa], xf, yf, 0), grad(P[ba], xf - 1, yf, 0)),
        lerp(u, grad(P[ab], xf, yf - 1, 0), grad(P[bb], xf - 1, yf - 1, 0))
    )
}

export function octaveNoise(x: number, y: number, octaves: number, persistence: number, scale: number): number {
    let total = 0, amplitude = 1, frequency = scale, maxValue = 0
    for (let i = 0; i < octaves; i++) {
        total += noise2D(x * frequency, y * frequency) * amplitude
        maxValue += amplitude
        amplitude *= persistence
        frequency *= 2
    }
    return total / maxValue
}

export function hexToRgb(hex: string): { r: number; g: number; b: number } {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
    return result
        ? { r: parseInt(result[1], 16), g: parseInt(result[2], 16), b: parseInt(result[3], 16) }
        : { r: 128, g: 128, b: 128 }
}

import { noise2D, octaveNoise, hexToRgb } from '../noise-utils'

function carpetFiber(x: number, y: number, fiberDensity: number): number {
    const fiber1 = noise2D(x * fiberDensity * 0.5, y * fiberDensity * 2) * 0.5
    const fiber2 = noise2D(x * fiberDensity * 2, y * fiberDensity * 0.5) * 0.3
    const fiber3 = noise2D(x * fiberDensity * 4, y * fiberDensity * 4) * 0.2
    return fiber1 + fiber2 + fiber3
}

export interface CarpetEnhancedOptions {
    color?: string
    fiberDensity?: number
    roughness?: number
}

export function paintCarpetEnhanced(data: Uint8ClampedArray, width: number, height: number, opts: CarpetEnhancedOptions = {}): void {
    const color = opts.color ?? '#8B0000'
    const fiberDensity = opts.fiberDensity ?? 0.4
    const roughness = opts.roughness ?? 0.8
    const rgb = hexToRgb(color)
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const fv = carpetFiber(x, y, fiberDensity)
            const cv = octaveNoise(x * 0.01, y * 0.01, 2, 0.6, 1) * 0.2
            const intensity = 1 + (fv + cv) * roughness
            data[i] = Math.max(0, Math.min(255, rgb.r * intensity))
            data[i + 1] = Math.max(0, Math.min(255, rgb.g * intensity))
            data[i + 2] = Math.max(0, Math.min(255, rgb.b * intensity))
            data[i + 3] = 255
        }
    }
}

import { octaveNoise, hexToRgb } from '../noise-utils'

export interface CeilingEnhancedOptions {
