export function paintCeilingEnhanced(data: Uint8ClampedArray, width: number, height: number, opts: CeilingEnhancedOptions = {}): void {
    const color = opts.color ?? '#F5F5DC'
    const bumpSize = opts.bumpSize ?? 0.5
    const density = opts.density ?? 0.7
    const rgb = hexToRgb(color)
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const bump = octaveNoise(x * density * 0.02, y * density * 0.02, 4, 0.5, 1)
            const detail = octaveNoise(x * density * 0.08, y * density * 0.08, 2, 0.3, 1) * 0.3
            const totalBump = (bump + detail) * bumpSize * 80
            data[i] = Math.max(0, Math.min(255, rgb.r + totalBump))
            data[i + 1] = Math.max(0, Math.min(255, rgb.g + totalBump))
            data[i + 2] = Math.max(0, Math.min(255, rgb.b + totalBump))
            data[i + 3] = 255
        }
    }
}

import { describe, it, expect } from 'vitest'
import { paintCeilingPopcorn, paintCeilingPopcornNormal } from './ceiling-popcorn'

describe('ceiling-popcorn', () => {
    const width = 128
    const height = 128

    describe('paintCeilingPopcorn', () => {
        it('fills all pixels with non-zero alpha', () => {
            const data = new Uint8ClampedArray(width * height * 4)
            paintCeilingPopcorn(data, width, height)

            for (let i = 0; i < data.length; i += 4) {
                expect(data[i + 3]).toBe(255)
            }
        })

        it('has meaningful brightness variation', () => {
            const data = new Uint8ClampedArray(width * height * 4)
            paintCeilingPopcorn(data, width, height)

            let minVal = 255
            let maxVal = 0

            for (let i = 0; i < data.length; i += 4) {
                const avg = (data[i] + data[i+1] + data[i+2]) / 3
                minVal = Math.min(minVal, avg)
                maxVal = Math.max(maxVal, avg)
            }

            expect(maxVal - minVal).toBeGreaterThan(10)
        })

        it('tiles seamlessly', () => {
            const data = new Uint8ClampedArray(width * height * 4)
            paintCeilingPopcorn(data, width, height)

            for (let y = 0; y < height; y++) {
                const iLeft = (y * width + 0) * 4
                const iRight = (y * width + (width - 1)) * 4

                // Diff should be small for seamless tiling (allowing some slope/noise jitter but close)
                // Using 35 to be safe across various channels with layered noise
                expect(Math.abs(data[iLeft] - data[iRight])).toBeLessThan(35)
                expect(Math.abs(data[iLeft + 1] - data[iRight + 1])).toBeLessThan(35)
                expect(Math.abs(data[iLeft + 2] - data[iRight + 2])).toBeLessThan(35)
            }
        })
    })

    describe('paintCeilingPopcornNormal', () => {
        it('has centered R/G channels and full B channel', () => {
            const data = new Uint8ClampedArray(width * height * 4)
            paintCeilingPopcornNormal(data, width, height)

            let sumR = 0
            let sumG = 0
            const pixelCount = width * height

            for (let i = 0; i < data.length; i += 4) {
                sumR += data[i]
                sumG += data[i + 1]
                expect(data[i + 2]).toBe(255)
            }

            const avgR = sumR / pixelCount
            const avgG = sumG / pixelCount

            // Should be roughly 128
            expect(avgR).toBeGreaterThan(120)
            expect(avgR).toBeLessThan(136)
            expect(avgG).toBeGreaterThan(120)
            expect(avgG).toBeLessThan(136)
        })
    })
})

import { octaveNoise, hexToRgb } from '../noise-utils'

export interface CeilingPopcornOptions {
    color?: string
    bumpDensity?: number
    bumpHeight?: number
    detailScale?: number
}

export interface CeilingPopcornNormalOptions {
    bumpDensity?: number
    detailScale?: number
    strength?: number
}

/**
 * Popcorn ceiling diffuse texture.
 * Tight, tile-safe bumps using fractional noise coordinates so the tile
 * wraps seamlessly. Higher bumpDensity = more, smaller bumps.
 */
export function paintCeilingPopcorn(data: Uint8ClampedArray, width: number, height: number, opts: CeilingPopcornOptions = {}): void {
    const color = opts.color ?? '#E8E6D0'
    const bumpDensity = opts.bumpDensity ?? 14
    const bumpHeight = opts.bumpHeight ?? 1.4
    const detailScale = opts.detailScale ?? 5
    const rgb = hexToRgb(color)
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const nx = (x / width) * bumpDensity
            const ny = (y / height) * bumpDensity
            const bump1 = octaveNoise(nx, ny, 3, 0.5, 1) * 0.6 + 0.4
            const bump2 = octaveNoise(nx * detailScale, ny * detailScale, 2, 0.4, 1) * 0.4
            const bump3 = octaveNoise(nx * detailScale * 3, ny * detailScale * 3, 1, 0.3, 1) * 0.15
            const h = Math.max(0, Math.min(1, (bump1 + bump2 + bump3) * bumpHeight))
            const warm = bump1 * 8
            data[i]     = Math.max(0, Math.min(255, rgb.r + h * 25 + warm))
            data[i + 1] = Math.max(0, Math.min(255, rgb.g + h * 22 + warm * 0.8))
            data[i + 2] = Math.max(0, Math.min(255, rgb.b + h * 15))
            data[i + 3] = 255
        }
    }
}

/**
 * Normal map for popcorn ceiling ΓÇö same seamless coordinates as the diffuse.
 */
export function paintCeilingPopcornNormal(data: Uint8ClampedArray, width: number, height: number, opts: CeilingPopcornNormalOptions = {}): void {
    const bumpDensity = opts.bumpDensity ?? 14
    const detailScale = opts.detailScale ?? 5
    const strength = opts.strength ?? 20
    const heightAt = (px: number, py: number): number => {
        const nx = (px / width)  * bumpDensity
        const ny = (py / height) * bumpDensity
        return octaveNoise(nx, ny, 3, 0.5, 1) * 0.6
             + octaveNoise(nx * detailScale, ny * detailScale, 2, 0.4, 1) * 0.4
    }
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const dX = (heightAt(x + 1, y) - heightAt(x - 1, y)) * strength
            const dY = (heightAt(x, y + 1) - heightAt(x, y - 1)) * strength
            data[i]     = Math.floor((dX * 0.5 + 0.5) * 255)
            data[i + 1] = Math.floor((dY * 0.5 + 0.5) * 255)
            data[i + 2] = 255
            data[i + 3] = 255
        }
    }
}

import { octaveNoise, hexToRgb } from '../noise-utils'

function woodGrainLinear(x: number, y: number, ringFrequency: number, grainStrength: number): number {
    // Lumber-like longitudinal grain: dominant variation across Y, subtle drift across X.
    // This avoids tree-ring cross-section appearance (radial circles).
    const baseLines = Math.sin(y * ringFrequency) * 0.5 + 0.5
    const alongGrainVariation = octaveNoise(x * 0.01, y * 0.05, 2, 0.3, 1) * 0.2
    const fineCrossGrain = octaveNoise(x * 0.08, y * 0.02, 3, 0.4, 1) * grainStrength
    return Math.max(0, Math.min(1, baseLines + alongGrainVariation + fineCrossGrain))
}

export interface WoodEnhancedOptions {
    grainStrength?: number
    ringFrequency?: number
    color1?: string
    color2?: string
    color3?: string
}

export function paintWoodEnhanced(data: Uint8ClampedArray, width: number, height: number, opts: WoodEnhancedOptions = {}): void {
    const grainStrength = opts.grainStrength ?? 0.4
    const ringFrequency = opts.ringFrequency ?? 0.08
    const color1 = opts.color1 ?? '#8B4513'
    const color2 = opts.color2 ?? '#A0522D'
    const color3 = opts.color3 ?? '#654321'
    const rgb1 = hexToRgb(color1)
    const rgb2 = hexToRgb(color2)
    const rgb3 = hexToRgb(color3)
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const gv = woodGrainLinear(x, y, ringFrequency, grainStrength)
            const c1 = octaveNoise(x * 0.03, y * 0.03, 3, 0.5, 1) * 0.12
            const c2 = octaveNoise(x * 0.08, y * 0.08, 4, 0.4, 1) * 0.08
            const c3 = octaveNoise(x * 0.15, y * 0.15, 2, 0.3, 1) * 0.05
            const v = Math.max(0, Math.min(1, gv + c1 + c2 + c3))
            let r: number, g: number, b: number
            if (v < 0.5) {
                const f = v * 2
                r = rgb1.r + (rgb2.r - rgb1.r) * f
                g = rgb1.g + (rgb2.g - rgb1.g) * f
                b = rgb1.b + (rgb2.b - rgb1.b) * f
            } else {
                const f = (v - 0.5) * 2
                r = rgb2.r + (rgb3.r - rgb2.r) * f
                g = rgb2.g + (rgb3.g - rgb2.g) * f
                b = rgb2.b + (rgb3.b - rgb2.b) * f
            }
            data[i] = r; data[i + 1] = g; data[i + 2] = b; data[i + 3] = 255
        }
    }
}

export interface WoodNormalOptions {
    strength?: number
}

export function paintWoodNormal(data: Uint8ClampedArray, width: number, height: number, opts: WoodNormalOptions = {}): void {
    const strength = opts.strength ?? 0.5
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4
            const grainX = Math.sin(x * 0.02) * strength
            const nx = Math.cos(grainX) * 127 + 128
            const ny = Math.sin(grainX) * 127 + 128
            data[i] = Math.floor(nx)
            data[i + 1] = Math.floor(ny)
            data[i + 2] = 255
            data[i + 3] = 255
        }
    }
}

import { noise2D, octaveNoise, hexToRgb } from '../noise-utils'

export interface WoodPlanksOptions {
    numPlanks?: number
    grainFrequency?: number
    grainStrength?: number
    baseColors?: string[]
    edgeColor?: string
}

/**
 * Wood paneling with distinct plank zones.
 * Each plank is a horizontal band in texture space. Since this texture is applied
 * with rotation=PI/2 in Three.js (to make planks run vertically on walls), the
 * Y axis in texture space maps to horizontal on the wall.
 *
 * numPlanks:      how many plank zones per tile
 * grainFrequency: fine grain line frequency within each plank
 * grainStrength:  amplitude of grain variation (keep low for subtlety)
 * baseColors:     array of hex colors cycling across planks (each slightly different)
 * edgeColor:      gap/shadow color between planks
 */
export function paintWoodPlanks(data: Uint8ClampedArray, width: number, height: number, opts: WoodPlanksOptions = {}): void {
    const numPlanks = opts.numPlanks ?? 4
    const grainFrequency = opts.grainFrequency ?? 1.2
    const grainStrength = opts.grainStrength ?? 0.12
    const baseColors = opts.baseColors ?? [
        '#7B3F10', '#8B4A14', '#9B5520', '#A8622A', '#8C4A18', '#955218'
    ]
    const edgeColor = opts.edgeColor ?? '#5C2F0A'
    const plankHeight = height / numPlanks
    const edgeRgb = hexToRgb(edgeColor)

    for (let y = 0; y < height; y++) {
        const plankIndex = Math.floor(y / plankHeight)
        const plankLocalY = (y % plankHeight) / plankHeight  // 0..1 within plank

        // Per-plank variation seeded by index
        const plankVariation = noise2D(plankIndex * 7.3, 0.5) * 0.15

        // Plank edge darkening ΓÇö narrow shadow at top and bottom of each plank
        const edgeT = Math.min(plankLocalY, 1 - plankLocalY)
        const edgeFactor = Math.min(1, edgeT / 0.06)  // 6% of plank height for edge

        const colorIdx = plankIndex % baseColors.length
        const rgb1 = hexToRgb(baseColors[colorIdx])
        const rgb2 = hexToRgb(baseColors[(colorIdx + 1) % baseColors.length])

        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4

            // Fine grain running along Y (within plank)
            const grainVal = (Math.sin(y * grainFrequency) * 0.5 + 0.5)
            const grainNoise = octaveNoise(x * 0.02, y * 0.04, 3, 0.5, 1) * grainStrength
            // Larger-scale variation across plank width (makes boards look different side-to-side)
            const widthVar = octaveNoise(x * 0.006, plankIndex * 3.7, 2, 0.6, 1) * 0.2

            const v = Math.max(0, Math.min(1, grainVal * 0.3 + grainNoise + widthVar + plankVariation + 0.35))

            // Blend between this plank's colors based on large-scale variation
            const blendT = Math.max(0, Math.min(1, plankVariation * 2 + 0.5))
            let r = rgb1.r + (rgb2.r - rgb1.r) * blendT
            let g = rgb1.g + (rgb2.g - rgb1.g) * blendT
            let b = rgb1.b + (rgb2.b - rgb1.b) * blendT

            // Apply grain darkening/lightening
            r = Math.max(0, Math.min(255, r * (0.8 + v * 0.4)))
            g = Math.max(0, Math.min(255, g * (0.8 + v * 0.4)))
            b = Math.max(0, Math.min(255, b * (0.8 + v * 0.4)))

            // Edge shadow (plank gap)
            r = r * edgeFactor + edgeRgb.r * (1 - edgeFactor)
            g = g * edgeFactor + edgeRgb.g * (1 - edgeFactor)
            b = b * edgeFactor + edgeRgb.b * (1 - edgeFactor)

            data[i] = Math.round(r); data[i + 1] = Math.round(g)
            data[i + 2] = Math.round(b); data[i + 3] = 255
        }
    }
}

