        y: number
    }
}

export interface MovementOptions {
    speed: number
    mouseSensitivity: number
}

export interface InputCallbacks {
    onMouseMove?: (deltaX: number, deltaY: number) => void
    onKeyPress?: (key: string) => void
    onKeyRelease?: (key: string) => void
}

/**
 * Manages input for desktop and VR modes
 */
export class InputManager {
    private static readonly logger = Logger.createLogFunctions(InputManager.name)

    private inputState: InputState = {
        keys: { w: false, a: false, s: false, d: false, q: false, e: false, space: false, c: false },
        mouse: { down: false, x: 0, y: 0 }
    }

    // Progressive movement tracking
    private keyPressTime: { [key: string]: number } = {}
    // TODO: make momentum transferable to adjacent directions (W <-> A/D <-> S)
    private readonly ACCELERATION_TIME = 2500 // 2.5 seconds to reach max speed
    private readonly MAX_SPEED_MULTIPLIER = 1.4

    private options: MovementOptions = {
        speed: 0.1,
        mouseSensitivity: 0.005
    }

    private callbacks: InputCallbacks = {}
    private isListeningToEvents = false

    constructor(options: Partial<MovementOptions> = {}, callbacks: InputCallbacks = {}) {
        this.options = { ...this.options, ...options }
        this.callbacks = callbacks
    }

    /**
     * Start listening to input events
     */
    startListening(): void {
        if (this.isListeningToEvents) {
            InputManager.logger.warn('InputManager already listening to events')
            return
        }


        this.setupMouseControls()
        this.setupKeyboardControls()
        this.isListeningToEvents = true

        InputManager.logger.debug('Input controls activated')
    }

    /**
     * Stop listening to input events
     */
    stopListening(): void {
        if (!this.isListeningToEvents) {
            return
        }

        this.removeEventListeners()
        this.isListeningToEvents = false

        InputManager.logger.debug('Input controls deactivated')
    }

    /**
     * Setup mouse controls for camera movement
     */
    private setupMouseControls(): void {
        document.addEventListener('mousedown', this.handleMouseDown)
        document.addEventListener('mouseup', this.handleMouseUp)
        document.addEventListener('mousemove', this.handleMouseMove)
    }

    /**
     * Setup keyboard controls for movement
     */
    private setupKeyboardControls(): void {
        document.addEventListener('keydown', this.handleKeyDown)
        document.addEventListener('keyup', this.handleKeyUp)
    }

    /**
     * Remove all event listeners
     */
    private removeEventListeners(): void {
        document.removeEventListener('mousedown', this.handleMouseDown)
        document.removeEventListener('mouseup', this.handleMouseUp)
        document.removeEventListener('mousemove', this.handleMouseMove)
        document.removeEventListener('keydown', this.handleKeyDown)
        document.removeEventListener('keyup', this.handleKeyUp)
    }

    private handleMouseDown = (event: MouseEvent): void => {
        this.inputState.mouse.down = true
        this.inputState.mouse.x = event.clientX
        this.inputState.mouse.y = event.clientY
    }

    private handleMouseUp = (): void => {
        this.inputState.mouse.down = false
    }

    private handleMouseMove = (event: MouseEvent): void => {
        if (!this.inputState.mouse.down) return

        const deltaX = event.clientX - this.inputState.mouse.x
        const deltaY = event.clientY - this.inputState.mouse.y

        this.inputState.mouse.x = event.clientX
        this.inputState.mouse.y = event.clientY

        this.callbacks.onMouseMove?.(deltaX, deltaY)
    }

    private handleKeyDown = (event: KeyboardEvent): void => {
        switch (event.code) {
            case 'KeyW': 
                if (!this.inputState.keys.w) {
                    this.inputState.keys.w = true
                    this.keyPressTime['w'] = Date.now()
                    this.callbacks.onKeyPress?.('w')
                }
                break
            case 'KeyA': 
                if (!this.inputState.keys.a) {
                    this.inputState.keys.a = true
                    this.keyPressTime['a'] = Date.now()
                    this.callbacks.onKeyPress?.('a')
                }
                break
            case 'KeyS': 
                if (!this.inputState.keys.s) {
                    this.inputState.keys.s = true
                    this.keyPressTime['s'] = Date.now()
                    this.callbacks.onKeyPress?.('s')
                }
                break
            case 'KeyD': 
                if (!this.inputState.keys.d) {
                    this.inputState.keys.d = true
                    this.keyPressTime['d'] = Date.now()
                    this.callbacks.onKeyPress?.('d')
                }
                break
            case 'KeyQ': 
                if (!this.inputState.keys.q) {
                    this.inputState.keys.q = true
                    this.callbacks.onKeyPress?.('q')
                }
                break
            case 'KeyE': 
                if (!this.inputState.keys.e) {
                    this.inputState.keys.e = true
                    this.callbacks.onKeyPress?.('e')
                }
                break
            case 'Space': 
                if (!this.inputState.keys.space) {
                    this.inputState.keys.space = true
                    this.keyPressTime['space'] = Date.now()
                    this.callbacks.onKeyPress?.('space')
                }
                break
            case 'KeyC': 
                if (!this.inputState.keys.c) {
                    this.inputState.keys.c = true
                    this.keyPressTime['c'] = Date.now()
                    this.callbacks.onKeyPress?.('c')
                }
                break
        }
    }

    private handleKeyUp = (event: KeyboardEvent): void => {
        switch (event.code) {
            case 'KeyW': 
                this.inputState.keys.w = false
                delete this.keyPressTime['w']
                this.callbacks.onKeyRelease?.('w')
                break
            case 'KeyA': 
                this.inputState.keys.a = false
                delete this.keyPressTime['a']
                this.callbacks.onKeyRelease?.('a')
                break
            case 'KeyS': 
                this.inputState.keys.s = false
                delete this.keyPressTime['s']
                this.callbacks.onKeyRelease?.('s')
                break
            case 'KeyD': 
                this.inputState.keys.d = false
                delete this.keyPressTime['d']
                this.callbacks.onKeyRelease?.('d')
                break
            case 'KeyQ': 
                this.inputState.keys.q = false
                this.callbacks.onKeyRelease?.('q')
                break
            case 'KeyE': 
                this.inputState.keys.e = false
                this.callbacks.onKeyRelease?.('e')
                break
            case 'Space': 
                this.inputState.keys.space = false
                delete this.keyPressTime['space']
                this.callbacks.onKeyRelease?.('space')
                break
            case 'KeyC': 
                this.inputState.keys.c = false
                delete this.keyPressTime['c']
                this.callbacks.onKeyRelease?.('c')
                break
        }
    }

    /**
     * Calculate progressive speed based on how long key has been held
     */
    private getProgressiveSpeed(key: string): number {
        const pressTime = this.keyPressTime[key]
        if (!pressTime) return 0

        const heldTime = Date.now() - pressTime
        const progress = Math.min(heldTime / this.ACCELERATION_TIME, 1) // 0 to 1 over 1.5s

        // Start at minimal speed, ramp up to 1.2x base speed
        const minSpeed = this.options.speed * 0.1 // Smallest increment
        const maxSpeed = this.options.speed * this.MAX_SPEED_MULTIPLIER

        return minSpeed + (maxSpeed - minSpeed) * progress
    }

    /**
     * Apply WASD + Space/C movement to a camera with progressive acceleration
     */
    updateCameraMovement(camera: THREE.Camera): void {
        if (this.inputState.keys.w) camera.translateZ(-this.getProgressiveSpeed('w'))
        if (this.inputState.keys.s) camera.translateZ(this.getProgressiveSpeed('s'))
        if (this.inputState.keys.a) camera.translateX(-this.getProgressiveSpeed('a'))
        if (this.inputState.keys.d) camera.translateX(this.getProgressiveSpeed('d'))
        if (this.inputState.keys.space) camera.translateY(this.getProgressiveSpeed('space')) // Move up
        if (this.inputState.keys.c) camera.translateY(-this.getProgressiveSpeed('c')) // Move down
    }

    /**
     * Apply mouse movement to camera rotation (Y-axis only)
     */
    updateCameraRotation(camera: THREE.Camera, deltaX: number, deltaY: number): void {
        // Mouse left/right only affects Y-axis rotation (yaw)
        camera.rotation.y -= deltaX * this.options.mouseSensitivity
        // Note: deltaY is ignored - pitch controls removed from mouse
    }

    /**
     * Apply Q/E key roll rotation to a camera - DISABLED for better UX
     */
    updateCameraRoll(camera: THREE.Camera): void {
        // Rotation controls disabled - they were difficult to work with
        // if (this.inputState.keys.q) camera.rotation.z += this.options.speed * 2 // Roll left
        // if (this.inputState.keys.e) camera.rotation.z -= this.options.speed * 2 // Roll right
    }

    /**
     * Get current input state
     */
    getInputState(): InputState {
        return { ...this.inputState }
    }

    /**
     * Update movement options
     */
    setMovementOptions(options: Partial<MovementOptions>): void {
        this.options = { ...this.options, ...options }
    }

    /**
     * Update callbacks
     */
    setCallbacks(callbacks: InputCallbacks): void {
        this.callbacks = { ...this.callbacks, ...callbacks }
    }

    /**
     * Check if any movement keys are pressed
     */
    isMoving(): boolean {
        const { keys } = this.inputState
        return keys.w || keys.a || keys.s || keys.d || keys.q || keys.e
    }

    /**
     * Clean up resources
     */
    dispose(): void {
        this.stopListening()
        this.callbacks = {}
    }
}

/**
 * WebXR Coordinator - Complete WebXR Session and Input Coordination
 * 
 * This coordinator manages all WebXR functionality in one place:
 * - WebXR session lifecycle (start/end/error handling)
 * - Input management integration for VR controllers
 * - WebXR capability detection and support handling
 * - Renderer integration for WebXR functionality
 * 
 * The App should only need to call setupWebXR() and handleWebXRToggle()
 * to get full WebXR functionality without managing individual components.
 */

import * as THREE from 'three'
import { WebXRManager, type WebXRCapabilities } from './WebXRManager'
import { InputManager } from './InputManager'
import { EventManager } from '../core/EventManager'
import { WebXREventTypes } from '../types/InteractionEvents'
import type { WebXRErrorEvent, WebXRSupportChangeEvent } from '../types/InteractionEvents'
import { RenderLoopRegistry } from '../scene/RenderLoopRegistry'

export interface WebXRCoordinatorConfig {
    camera: THREE.Camera
    input?: {
        speed?: number
        mouseSensitivity?: number
    }
}

/**
 * Coordinates all WebXR functionality including session management and input
 */
export class WebXRCoordinator {
    private webxrManager: WebXRManager
    private inputManager: InputManager
    private eventManager: EventManager
    private renderLoopRegistry: RenderLoopRegistry
    private camera: THREE.Camera
    private pendingMouseDeltas: { deltaX: number, deltaY: number } | null = null

    constructor(config: WebXRCoordinatorConfig) {
        this.camera = config.camera
        this.eventManager = EventManager.getInstance()
        this.renderLoopRegistry = RenderLoopRegistry.getInstance()

        this.webxrManager = new WebXRManager({
            onSessionStart: () => this.handleSessionStart(),
            onSessionEnd: () => this.handleSessionEnd(),
            onError: (error: Error) => this.handleError(error),
            onSupportChange: (capabilities: WebXRCapabilities) => this.handleSupportChange(capabilities)
        })

        // Initialize input manager with mouse move callback
        this.inputManager = new InputManager(
            { 
                speed: config.input?.speed ?? 0.1, 
                mouseSensitivity: config.input?.mouseSensitivity ?? 0.005 
            },
            {
                onMouseMove: (deltaX: number, deltaY: number) => {
                    // We need the camera for mouse rotation, but we don't have it here
                    // Store the deltas and apply them in updateCameraMovement
                    this.pendingMouseDeltas = { deltaX, deltaY }
                }
            }
        )
    }

    /**
     * Complete WebXR setup - call this once during app initialization
     */
    async setupWebXR(renderer: THREE.WebGLRenderer): Promise<void> {
        // Set the renderer for WebXR
        this.webxrManager.setRenderer(renderer)

        // Check WebXR capabilities
        await this.webxrManager.checkCapabilities()

        // Start input listening
        this.inputManager.startListening()

        // Register update method with render loop
        this.renderLoopRegistry.register(this.constructor.name, this.updateCamera.bind(this))
    }

    /**
     * Update camera movement - called every frame by render loop registry
     */
    private updateCamera(_now: number, _deltaTime: number): void {
        this.updateCameraMovement(this.camera)
    }

    /**
     * Handle WebXR toggle request from UI
     */
    async handleWebXRToggle(): Promise<void> {
        try {
            await this.webxrManager.startVRSession()
        } catch (error) {
            // Error handling is done in the WebXRManager callbacks
            console.debug('WebXR toggle failed:', error)
        }
    }

    /**
     * Update camera movement and rotation using input manager
     * Call this from the render loop
     */
    updateCameraMovement(camera: THREE.Camera): void {
        // Handle keyboard movement
        // we should ABSOLUTELY NOT update the camera in VR this way (from keybinds rather than headset data)
        this.inputManager.updateCameraMovement(camera)

        // Handle Q/E roll rotation
        this.inputManager.updateCameraRoll(camera)

        // Handle pending mouse rotation (Y-axis only now)
        if (this.pendingMouseDeltas) {
            this.inputManager.updateCameraRotation(camera, this.pendingMouseDeltas.deltaX, this.pendingMouseDeltas.deltaY)
            this.pendingMouseDeltas = null // Clear after processing
        }
    }

    /**
     * Pause input handling (e.g., when pause menu is open)
     */
    pauseInput(): void {
        this.inputManager.stopListening()
    }

    /**
     * Resume input handling
     */
    resumeInput(): void {
        this.inputManager.startListening()
    }

    /**
     * Get the WebXR manager for advanced operations
     */
    getWebXRManager(): WebXRManager {
        return this.webxrManager
    }

    /**
     * Dispose of resources
     */
    dispose(): void {
        this.renderLoopRegistry.unregister(this.constructor.name)
        this.inputManager.dispose()
        this.webxrManager.dispose()
    }

    // Private event handlers

    private handleSessionStart(): void {
        console.log('Γ£à WebXR session started!')
        this.eventManager.emit(WebXREventTypes.SessionStart, {})
    }

    private handleSessionEnd(): void {
        console.log('≡ƒÜ¬ WebXR session ended')
        this.eventManager.emit(WebXREventTypes.SessionEnd, {})
    }

    private handleError(error: Error): void {
        console.error('Γ¥î WebXR error:', error)
        this.eventManager.emit<WebXRErrorEvent>(WebXREventTypes.Error, { error })
    }

    private handleSupportChange(capabilities: WebXRCapabilities): void {
        this.eventManager.emit<WebXRSupportChangeEvent>(WebXREventTypes.SupportChange, { capabilities })
    }
}

/**
 * WebXR Event Handler
 * 
 * Handles all WebXR-related interaction workflows that were previously 
 * managed in SteamBrickAndMortarApp. This includes:
 * - WebXR session lifecycle management
 * - WebXR error handling
 * - WebXR capability updates
 * - Input pause/resume coordination
 * - Menu interaction coordination
 * 
 * Listens to interaction events and coordinates between WebXRCoordinator
 * and UICoordinator.
 */

import { EventManager } from '../core/EventManager'
import { WebXRCoordinator } from './WebXRCoordinator'
import { WebXRUICoordinator } from '../ui/coordinators'
import { Logger } from '../utils/Logger'
import { ToastManager } from '../ui/ToastManager'
import { WebXREventTypes, InputEventTypes, UIEventTypes } from '../types/InteractionEvents'
import type { WebXRCapabilities } from './WebXRManager'
import type {
    WebXRToggleEvent,
    WebXRSessionStartEvent,
    WebXRSessionEndEvent,
    WebXRErrorEvent,
    WebXRSupportChangeEvent,
    InputPauseEvent,
    InputResumeEvent,
    MenuOpenEvent,
    MenuCloseEvent
} from '../types/InteractionEvents'

export class WebXREventHandler {
    private static readonly logger = Logger.createLogFunctions(WebXREventHandler.name)
    private eventManager: EventManager
    private webxrCoordinator: WebXRCoordinator
    private webxrUICoordinator: WebXRUICoordinator
    private boundHandlers: Record<string, EventListener>

    constructor(
        webxrCoordinator: WebXRCoordinator,
        webxrUICoordinator: WebXRUICoordinator,
        eventManager?: EventManager
    ) {
        this.webxrCoordinator = webxrCoordinator
        this.webxrUICoordinator = webxrUICoordinator
        this.eventManager = eventManager || EventManager.getInstance()

        this.boundHandlers = {
            onWebXRToggle: this.onWebXRToggle.bind(this),
            onWebXRSessionStart: this.onWebXRSessionStart.bind(this),
            onWebXRSessionEnd: this.onWebXRSessionEnd.bind(this),
            onWebXRError: this.onWebXRError.bind(this),
            onWebXRSupportChange: this.onWebXRSupportChange.bind(this),
            onInputPause: this.onInputPause.bind(this),
            onInputResume: this.onInputResume.bind(this),
            onMenuOpen: this.onMenuOpen.bind(this),
            onMenuClose: this.onMenuClose.bind(this)
        }

        this.setupEventListeners()
        WebXREventHandler.logger.debug('WebXREventHandler initialized')
    }

    private setupEventListeners(): void {
        this.eventManager.registerEventHandler(WebXREventTypes.Toggle, this.boundHandlers.onWebXRToggle)
        this.eventManager.registerEventHandler(WebXREventTypes.SessionStart, this.boundHandlers.onWebXRSessionStart)
        this.eventManager.registerEventHandler(WebXREventTypes.SessionEnd, this.boundHandlers.onWebXRSessionEnd)
        this.eventManager.registerEventHandler(WebXREventTypes.Error, this.boundHandlers.onWebXRError)
        this.eventManager.registerEventHandler(WebXREventTypes.SupportChange, this.boundHandlers.onWebXRSupportChange)
        this.eventManager.registerEventHandler(InputEventTypes.Pause, this.boundHandlers.onInputPause)
        this.eventManager.registerEventHandler(InputEventTypes.Resume, this.boundHandlers.onInputResume)
        this.eventManager.registerEventHandler(UIEventTypes.MenuOpen, this.boundHandlers.onMenuOpen)
        this.eventManager.registerEventHandler(UIEventTypes.MenuClose, this.boundHandlers.onMenuClose)
    }

    private onWebXRToggle = (event: CustomEvent<WebXRToggleEvent>) => {
        this.handleWebXRToggle(event.detail)
    }

    private onWebXRSessionStart = (event: CustomEvent<WebXRSessionStartEvent>) => {
        this.handleWebXRSessionStart(event.detail)
    }

    private onWebXRSessionEnd = (event: CustomEvent<WebXRSessionEndEvent>) => {
        this.handleWebXRSessionEnd(event.detail)
    }

    private onWebXRError = (event: CustomEvent<WebXRErrorEvent>) => {
        this.handleWebXRError(event.detail)
    }

    private onWebXRSupportChange = (event: CustomEvent<WebXRSupportChangeEvent>) => {
        this.handleWebXRSupportChange(event.detail)
    }

    private onInputPause = (event: CustomEvent<InputPauseEvent>) => {
        this.handleInputPause(event.detail)
    }

    private onInputResume = (event: CustomEvent<InputResumeEvent>) => {
        this.handleInputResume(event.detail)
    }

    private onMenuOpen = (event: CustomEvent<MenuOpenEvent>) => {
        this.handleMenuOpen(event.detail)
    }

    private onMenuClose = (event: CustomEvent<MenuCloseEvent>) => {
        this.handleMenuClose(event.detail)
    }

    private async handleWebXRToggle(_event: WebXRToggleEvent): Promise<void> {
        WebXREventHandler.logger.debug('Handling WebXR toggle request')
        await this.webxrCoordinator.handleWebXRToggle()
    }

    private handleWebXRSessionStart(_event: WebXRSessionStartEvent): void {
        WebXREventHandler.logger.debug('WebXR session started')
        this.webxrUICoordinator.updateWebXRSessionState(true)
    }

    private handleWebXRSessionEnd(_event: WebXRSessionEndEvent): void {
        WebXREventHandler.logger.debug('WebXR session ended')
        this.webxrUICoordinator.updateWebXRSessionState(false)
    }

    private handleWebXRError(event: WebXRErrorEvent): void {
        WebXREventHandler.logger.error('WebXR error occurred:', event.error)
        ToastManager.error('Failed to enter VR mode')
    }

    private handleWebXRSupportChange(event: WebXRSupportChangeEvent): void {
        WebXREventHandler.logger.debug('WebXR capabilities changed:', event.capabilities)
        this.webxrUICoordinator.updateWebXRSupport(event.capabilities)
    }

    private handleInputPause(event: InputPauseEvent): void {
        WebXREventHandler.logger.debug(`Input paused: ${event.reason || 'unspecified'}`)
        this.webxrCoordinator.pauseInput()
    }

    private handleInputResume(event: InputResumeEvent): void {
        WebXREventHandler.logger.debug(`Input resumed: ${event.reason || 'unspecified'}`)
        this.webxrCoordinator.resumeInput()
    }

    private handleMenuOpen(event: MenuOpenEvent): void {
        WebXREventHandler.logger.debug(`Menu opened: ${event.menuType}`)
        // Pause input when any menu opens
        this.webxrCoordinator.pauseInput()
    }

    private handleMenuClose(event: MenuCloseEvent): void {
        WebXREventHandler.logger.debug(`Menu closed: ${event.menuType}`)
        // Resume input when menu closes
        this.webxrCoordinator.resumeInput()
    }

    dispose(): void {
        this.eventManager.deregisterEventHandler(WebXREventTypes.Toggle, this.boundHandlers.onWebXRToggle)
        this.eventManager.deregisterEventHandler(WebXREventTypes.SessionStart, this.boundHandlers.onWebXRSessionStart)
        this.eventManager.deregisterEventHandler(WebXREventTypes.SessionEnd, this.boundHandlers.onWebXRSessionEnd)
        this.eventManager.deregisterEventHandler(WebXREventTypes.Error, this.boundHandlers.onWebXRError)
        this.eventManager.deregisterEventHandler(WebXREventTypes.SupportChange, this.boundHandlers.onWebXRSupportChange)
        this.eventManager.deregisterEventHandler(InputEventTypes.Pause, this.boundHandlers.onInputPause)
        this.eventManager.deregisterEventHandler(InputEventTypes.Resume, this.boundHandlers.onInputResume)
        this.eventManager.deregisterEventHandler(UIEventTypes.MenuOpen, this.boundHandlers.onMenuOpen)
        this.eventManager.deregisterEventHandler(UIEventTypes.MenuClose, this.boundHandlers.onMenuClose)

        WebXREventHandler.logger.debug('WebXREventHandler disposed')
    }
}

/**
 * WebXR Manager
 * 
 * Manages WebXR session and capability detection:
 * - Detect WebXR support
 * - Handle VR session lifecycle
 * - Manage XR button states
 * - Session event handling
 */

import * as THREE from 'three'
import { Logger } from '../utils/Logger'
// Use global WebXR types from webxr.d.ts

export interface WebXRCapabilities {
    isSupported: boolean
    supportsImmersiveVR: boolean
    hasNavigatorXR: boolean
}

export interface WebXRSessionCallbacks {
    onSessionStart?: () => void
    onSessionEnd?: () => void
    onError?: (error: Error) => void
    onSupportChange?: (capabilities: WebXRCapabilities) => void
}

/**
 * Manages WebXR session lifecycle and capabilities
 */
export class WebXRManager {
    private static readonly logger = Logger.createLogFunctions(WebXRManager.name)
    private renderer: THREE.WebGLRenderer | null = null
    private currentSession: XRSession | null = null
    private capabilities: WebXRCapabilities = {
        isSupported: false,
        supportsImmersiveVR: false,
        hasNavigatorXR: false
    }
    private callbacks: WebXRSessionCallbacks = {}

    constructor(callbacks: WebXRSessionCallbacks = {}) {
        this.callbacks = callbacks
    }

    /**
     * Initialize WebXR manager with a Three.js renderer
     */
    setRenderer(renderer: THREE.WebGLRenderer): void {
        this.renderer = renderer

        // Enable XR on the renderer
        this.renderer.xr.enabled = true
    }

    /**
     * Check WebXR support and capabilities
     */
    async checkCapabilities(): Promise<WebXRCapabilities> {
        // Check if navigator.xr exists
        this.capabilities.hasNavigatorXR = !!navigator.xr

        if (!this.capabilities.hasNavigatorXR) {
            WebXRManager.logger.warn('WebXR not supported - falling back to desktop mode')
            this.capabilities.isSupported = false
            this.capabilities.supportsImmersiveVR = false
            this.callbacks.onSupportChange?.(this.capabilities)
            return this.capabilities
        }

        try {
            // Check if immersive VR sessions are supported
            this.capabilities.supportsImmersiveVR = await navigator.xr.isSessionSupported('immersive-vr')
            this.capabilities.isSupported = this.capabilities.supportsImmersiveVR

            if (this.capabilities.supportsImmersiveVR) {
                WebXRManager.logger.info('WebXR VR sessions supported')
            } else {
                WebXRManager.logger.warn('WebXR VR sessions not supported - desktop mode only')
            }
        } catch (error) {
            WebXRManager.logger.warn('WebXR session support check failed:', error)
            this.capabilities.isSupported = false
            this.capabilities.supportsImmersiveVR = false
        }

        this.callbacks.onSupportChange?.(this.capabilities)
        return this.capabilities
    }

    /**
     * Get current capabilities without re-checking
     */
    getCapabilities(): WebXRCapabilities {
        return { ...this.capabilities }
    }

    /**
     * Start an immersive VR session
     */
    async startVRSession(): Promise<void> {
        if (!this.renderer) {
            throw new Error('Renderer not set. Call setRenderer() first.')
        }

        if (!navigator.xr) {
            throw new Error('WebXR not available')
        }

        if (!this.capabilities.supportsImmersiveVR) {
            throw new Error('Immersive VR sessions not supported')
        }

        if (this.currentSession) {
            console.warn('ΓÜá∩╕Å WebXR session already active')
            return
        }

        try {
            console.log('≡ƒÑ╜ Attempting to start WebXR session...')

            const session = await navigator.xr.requestSession('immersive-vr')
            this.currentSession = session

            // Set the session on the renderer
            await this.renderer.xr.setSession(session)

            // Set up session event listeners
            session.addEventListener('end', () => {
                console.log('≡ƒÜ¬ WebXR session ended')
                this.currentSession = null
                this.callbacks.onSessionEnd?.()
            })

            console.log('Γ£à WebXR session started!')
            this.callbacks.onSessionStart?.()

        } catch (error) {
            console.error('Γ¥î Failed to start WebXR session:', error)
            this.callbacks.onError?.(error as Error)
            throw error
        }
    }

    /**
     * End the current VR session
     */
    async endVRSession(): Promise<void> {
        if (!this.currentSession) {
            console.warn('ΓÜá∩╕Å No active WebXR session to end')
            return
        }

        try {
            await this.currentSession.end()
            // Session end event will be handled by the event listener
        } catch (error) {
            console.error('Γ¥î Failed to end WebXR session:', error)
            this.callbacks.onError?.(error as Error)
            throw error
        }
    }

    /**
     * Check if a VR session is currently active
     */
    isSessionActive(): boolean {
        return this.currentSession !== null
    }

    /**
     * Get the current XR session (if any)
     */
    getCurrentSession(): XRSession | null {
        return this.currentSession
    }

    /**
     * Update callbacks
     */
    setCallbacks(callbacks: WebXRSessionCallbacks): void {
        this.callbacks = { ...this.callbacks, ...callbacks }
    }

    /**
     * Clean up resources
     */
    dispose(): void {
        if (this.currentSession) {
            this.currentSession.end().catch(console.error)
        }
        this.currentSession = null
        this.callbacks = {}
    }
}

